// Perspective constants for the worm's-eye view
const VP_X = 600;
const VP_Y = -1300;
const Y_REF = 600;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);

  // Custom brushes for hyperrealistic coloured-pencil grain, graphite, and gold ink
  brush.add("fine_cpencil", {
    type: "default",
    weight: 0.45,
    scatter: 0.28,
    sharpness: 0.72,
    grain: 14,
    opacity: 155,
    spacing: 0.14,
    pressure: [0.65, 1.0, 0.65],
    noise: 0.55
  });

  brush.add("gold_ink", {
    type: "default",
    weight: 0.34,
    scatter: 0.03,
    sharpness: 0.96,
    grain: 3,
    opacity: 235,
    spacing: 0.08,
    pressure: [0.85, 1.0, 0.85],
    noise: 0.12
  });

  brush.add("gold_glint", {
    type: "default",
    weight: 0.24,
    scatter: 0.02,
    sharpness: 0.98,
    grain: 2,
    opacity: 250,
    spacing: 0.07,
    pressure: [0.4, 1.15, 0.4],
    noise: 0.08
  });

  brush.add("cedar_grain", {
    type: "default",
    weight: 0.38,
    scatter: 0.22,
    sharpness: 0.8,
    grain: 16,
    opacity: 140,
    spacing: 0.12,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.65
  });

  brush.add("sky_pencil", {
    type: "default",
    weight: 0.9,
    scatter: 0.65,
    sharpness: 0.45,
    grain: 18,
    opacity: 65,
    spacing: 0.22,
    pressure: [0.3, 0.95, 0.3],
    noise: 0.5
  });
}

// Perspective helper: scale factor at canvas height y
function perspK(y) {
  return (y - VP_Y) / (Y_REF - VP_Y);
}

// Perspective helper: X coordinate at canvas height y for reference offset dx0
function perspX(dx0, y) {
  return VP_X + dx0 * perspK(y);
}

// Helper for fast opaque polygon wash
function washPoly(pts, col, opacity = 255) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  let p = new brush.Polygon(pts);
  p.wash(col, opacity);
  brush.noWash();
}

// Helper for linearly interpolating hex colors
function mixHex(c1, c2, t) {
  let col1 = color(c1);
  let col2 = color(c2);
  return lerpColor(col1, col2, constrain(t, 0, 1));
}

// Point on the worm's-eye elliptical ring at base y0, radius r, and normalized across-width parameter u in [-1, 1]
function ringPt(dx0, y0, r, u, archFactor = 0.22) {
  let xc = perspX(dx0, y0);
  // Slope perpendicular to the pencil's converging axis
  let axisSlope = (dx0 * 1.0) / (Y_REF - VP_Y);
  let x = xc + u * r;
  // Worm's-eye view: front of cylinder (u=0) bows upward (smaller y) relative to edges (u = +-1)
  let arch = -archFactor * r * (1 - u * u);
  let tilt = -axisSlope * (u * r) * 0.85;
  return [x, y0 + arch + tilt];
}

// Point on the hexagonal-to-conical triple-scalloped collar for u in [-1, 1]
function scallopPt(dx0, yCollar, r, u) {
  let xc = perspX(dx0, yCollar);
  let axisSlope = (dx0 * 1.0) / (Y_REF - VP_Y);
  let x = xc + u * r;
  let tilt = -axisSlope * (u * r) * 0.85;

  // Three hexagonal facets span:
  // Left facet: [-1.0, -0.46], Center facet: [-0.46, 0.46], Right facet: [0.46, 1.0]
  let b = 0.46;
  let yOff = 0;

  if (u < -b) {
    // Left facet parabolic scallop
    let t = (u + 1.0) / (1.0 - b); // 0 at outer left, 1 at left ridge
    let parabola = 4 * t * (1 - t);
    let baseLine = lerp(0.24 * r, 0.05 * r, t);
    yOff = baseLine - 0.14 * r * parabola;
  } else if (u <= b) {
    // Center facet parabolic scallop (highest in worm's-eye view)
    let t = (u + b) / (2 * b); // 0 at left ridge, 1 at right ridge
    let parabola = 4 * t * (1 - t);
    let baseLine = 0.05 * r;
    yOff = baseLine - 0.22 * r * parabola;
  } else {
    // Right facet parabolic scallop
    let t = (u - b) / (1.0 - b); // 0 at right ridge, 1 at outer right
    let parabola = 4 * t * (1 - t);
    let baseLine = lerp(0.05 * r, 0.24 * r, t);
    yOff = baseLine - 0.14 * r * parabola;
  }

  return [x, yCollar + yOff + tilt];
}

