function drawJadeSky() {
  // Layered cool jade gradient bands from zenith to horizon
  const bands = 28;
  for (let i = 0; i < bands; i++) {
    let t = i / (bands - 1);
    let y1 = i * (1200 / bands) - 4;
    let y2 = (i + 1) * (1200 / bands) + 4;
    let col;
    if (t < 0.45) {
      col = mixHex("#b7d9cf", "#d4ece4", t / 0.45);
    } else {
      col = mixHex("#d4ece4", "#eef8f4", (t - 0.45) / 0.55);
    }
    washPoly([[0, y1], [1200, y1], [1200, y2], [0, y2]], col, 255);
  }

  // Soft watercolor atmospheric luminosity behind the central spire
  brush.noStroke();
  brush.fill("#f4fcf9", 75);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.25, 0.15);
  brush.circle(600, 360, 420, 0.02);
  brush.circle(600, 260, 260, 0.02);
  brush.noFill();

  // Coloured-pencil sky grain in cool celadon, ice-jade, and pale silver-mint
  for (let i = 0; i < 240; i++) {
    let y = random(0, 980);
    let t = y / 980;
    let xSpan = random(140, 420);
    let xc = random(0, 1200);
    let x1 = constrain(xc - xSpan * 0.5, 0, 1200);
    let x2 = constrain(xc + xSpan * 0.5, 0, 1200);
    let cSky = t < 0.5
      ? mixHex("#9ec7bc", "#c6e3da", random(0, 1))
      : mixHex("#cfe8e0", "#f4fbf8", random(0, 1));
    brush.set("sky_pencil", cSky, random(0.7, 1.35));
    brush.line(x1, y, x2, y + random(-3, 3));
  }

  // Streamlined Art Deco geometric sunburst & stepped setback halo in the sky
  let sunCx = 600;
  let sunCy = 460;
  for (let a = -82; a <= 82; a += 4) {
    let rad = 1100;
    let ang = -90 + a;
    let x1 = sunCx + cos(ang) * 70;
    let y1 = sunCy + sin(ang) * 70;
    let x2 = sunCx + cos(ang) * rad;
    let y2 = sunCy + sin(ang) * rad;
    if (a % 12 === 0) {
      brush.set("gold_ink", "#d9c27e", 0.45);
      brush.line(x1, y1, x2, y2);
    } else {
      brush.set("2H", "#eef8f4", 0.65);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Symmetrical stepped Art Deco sky frame lines behind the spire
  const decoSteps = [
    { dx: 64,  yTop: 42,  yBot: 260 },
    { dx: 138, yTop: 145, yBot: 400 },
    { dx: 212, yTop: 265, yBot: 540 },
    { dx: 286, yTop: 390, yBot: 680 },
    { dx: 360, yTop: 520, yBot: 820 },
    { dx: 434, yTop: 655, yBot: 960 }
  ];
  for (let s of decoSteps) {
    for (let side of [-1, 1]) {
      let xTop = perspX(side * s.dx, s.yTop);
      let xBot = perspX(side * s.dx, s.yBot);
      let xIn  = perspX(side * (s.dx - 54), s.yTop);
      brush.set("gold_ink", "#d5bc72", 0.52);
      brush.line(xTop, s.yTop, xBot, s.yBot);
      brush.line(xIn, s.yTop, xTop, s.yTop);
    }
  }
}

function drawPencilOcclusion(p) {
  let yTip = p.yTip;
  let rTip = p.r0 * perspK(yTip);
  let yCollar = yTip + rTip * 2.75;
  let yBot = 1210;

  let tipX = perspX(p.dx0, yTip - 4);
  let rCol = (p.r0 + 5.5) * perspK(yCollar);
  let rBot = (p.r0 + 6.5) * perspK(yBot);

  let xcCol = perspX(p.dx0, yCollar);
  let xcBot = perspX(p.dx0, yBot);

  let pts = [
    [tipX, yTip - 4],
    [xcCol + rCol, yCollar],
    [xcBot + rBot, yBot],
    [xcBot - rBot, yBot],
    [xcCol - rCol, yCollar]
  ];
  washPoly(pts, "#091815", 85);
}

function getLacquerPalette(kind) {
  if (kind === "black") {
    return {
      leftBase: "#32414a",
      leftHi: "#637985",
      leftEdge: "#8ba2ae",
      midBase: "#1b242a",
      midSpec: "#526773",
      midDark: "#12181d",
      rightBase: "#0c1115",
      rightRim: "#1f3236",
      bevelL: "#a7c0cc",
      bevelR: "#2c3c44"
    };
  } else if (kind === "cream") {
    return {
      leftBase: "#f2f6f2",
      leftHi: "#ffffff",
      leftEdge: "#e0ebe5",
      midBase: "#dde7e1",
      midSpec: "#f9fcf9",
      midDark: "#cad8d0",
      rightBase: "#9eb4ac",
      rightRim: "#b8ccc4",
      bevelL: "#ffffff",
      bevelR: "#7f968e"
    };
  } else {
    // Racing green ("green")
    return {
      leftBase: "#1d5747",
      leftHi: "#438773",
      leftEdge: "#6eb09b",
      midBase: "#103c30",
      midSpec: "#31705e",
      midDark: "#0b2c23",
      rightBase: "#072019",
      rightRim: "#174539",
      bevelL: "#8cd1bb",
      bevelR: "#0d3328"
    };
  }
}

function drawHyperPencil(p, tierIdx) {
  let dx0 = p.dx0;
  let r0 = p.r0;
  let yTip = p.yTip;
  let rAtTip = r0 * perspK(yTip);

  // Cone & collar vertical proportions
  let coneHeight = rAtTip * 2.78;
  let yCollar = yTip + coneHeight;
  let yGraphite = yTip + coneHeight * 0.34;
  let yBot = 1210;

  let rGraph = r0 * perspK(yGraphite) * 0.34;
  let rCollar = r0 * perspK(yCollar);
  let rBot = r0 * perspK(yBot);

  // Ferrule band position
  let yFerrule1 = yCollar + p.ferruleOff;
  let rFer1 = r0 * perspK(yFerrule1);
  let ferruleH = rFer1 * 1.38;
  let yFerrule2 = yFerrule1 + ferruleH;

  // =========================================================================
  // 1. HEXAGONAL LACQUERED SHAFT (3 visible facets: Left, Center, Right)
  // =========================================================================
  let pal = getLacquerPalette(p.kind);
  let uEdges = [-1.0, -0.46, 0.46, 1.0];

  // Build top scalloped boundary points and bottom boundary points for each of the 3 facets
  for (let f = 0; f < 3; f++) {
    let uA = uEdges[f];
    let uB = uEdges[f + 1];

    // Sample top scalloped curve along [uA, uB]
    let topPts = [];
    let steps = 8;
    for (let s = 0; s <= steps; s++) {
      let u = lerp(uA, uB, s / steps);
      topPts.push(scallopPt(dx0, yCollar, rCollar, u));
    }

    let botRight = [perspX(dx0, yBot) + uB * rBot, yBot];
    let botLeft  = [perspX(dx0, yBot) + uA * rBot, yBot];

    let facetPoly = [...topPts, botRight, botLeft];
    let baseCol = f === 0 ? pal.leftBase : (f === 1 ? pal.midBase : pal.rightBase);
    washPoly(facetPoly, baseCol, 255);

    // Coloured-pencil longitudinal lacquer texture along the converging facet
    let grainLines = f === 1 ? 15 : 10;
    for (let g = 0; g <= grainLines; g++) {
      let gt = g / grainLines;
      let u = lerp(uA, uB, gt);
      let pTop = scallopPt(dx0, yCollar, rCollar, u);
      let pBot = [perspX(dx0, yBot) + u * rBot, yBot];

      let strokeCol;
      let weight = 0.85;
      if (f === 0) {
        // Left lit facet: bright sheen near inner ridge, sky reflection near outer edge
        strokeCol = gt < 0.3
          ? mixHex(pal.leftEdge, pal.leftBase, gt / 0.3)
          : mixHex(pal.leftBase, pal.leftHi, (gt - 0.3) / 0.7);
      } else if (f === 1) {
        // Center facet: crisp specular sheen strip around gt in [0.15, 0.38]
        if (gt > 0.14 && gt < 0.38) {
          let st = 1 - abs(gt - 0.26) / 0.12;
          strokeCol = mixHex(pal.midBase, pal.midSpec, st);
          weight = 1.05;
        } else {
          strokeCol = mixHex(pal.midBase, pal.midDark, gt);
        }
      } else {
        // Right shadow facet: deep core shadow with subtle reflected rim near outer right edge
        strokeCol = gt > 0.68
          ? mixHex(pal.rightBase, pal.rightRim, (gt - 0.68) / 0.32)
          : pal.rightBase;
      }

      brush.set("fine_cpencil", strokeCol, weight);
      brush.line(pTop[0], pTop[1] + 2, pBot[0], pBot[1]);
    }
  }

  // Crisp specular bevel highlights along the hexagonal facet ridges
  let pRidgeLTop = scallopPt(dx0, yCollar, rCollar, -0.46);
  let pRidgeLBot = [perspX(dx0, yBot) - 0.46 * rBot, yBot];
  brush.set("rotring", pal.bevelL, 0.75);
  brush.line(pRidgeLTop[0], pRidgeLTop[1], pRidgeLBot[0], pRidgeLBot[1]);

  let pRidgeRTop = scallopPt(dx0, yCollar, rCollar, 0.46);
  let pRidgeRBot = [perspX(dx0, yBot) + 0.46 * rBot, yBot];
  brush.set("rotring", pal.bevelR, 0.65);
  brush.line(pRidgeRTop[0], pRidgeRTop[1], pRidgeRBot[0], pRidgeRBot[1]);

  // Subtle Art Deco gold foil cartouche lines on the center facet above the ferrule
  if (yFerrule1 - yCollar > 36) {
    let yCart1 = yCollar + (yFerrule1 - yCollar) * 0.28;
    let yCart2 = yCollar + (yFerrule1 - yCollar) * 0.78;
    for (let uC of [-0.18, 0.0, 0.18]) {
      let pt1 = ringPt(dx0, yCart1, r0 * perspK(yCart1), uC, 0.16);
      let pt2 = ringPt(dx0, yCart2, r0 * perspK(yCart2), uC, 0.16);
      brush.set("gold_ink", "#d7b456", uC === 0 ? 0.62 : 0.42);
      brush.line(pt1[0], pt1[1], pt2[0], pt2[1]);
    }
  }

  // =========================================================================
  // 2. RIBBED BRASS FERRULE BAND ("each ferrule a band of brass")
  // =========================================================================
  if (yFerrule1 < 1190) {
    drawBrassFerrule(dx0, r0, yFerrule1, min(yFerrule2, 1205));
  }

  // =========================================================================
  // 3. SHAVED CEDAR WOOD CONE (Coloured-pencil radial fibers + growth arches)
  // =========================================================================
  let coneSlices = 22;
  for (let i = 0; i < coneSlices; i++) {
    let t0 = i / coneSlices;
    let t1 = (i + 1) / coneSlices;
    let u0 = lerp(-1, 1, t0);
    let u1 = lerp(-1, 1, t1);
    let tm = (t0 + t1) * 0.5;

    let g0 = ringPt(dx0, yGraphite, rGraph, u0, 0.22);
    let g1 = ringPt(dx0, yGraphite, rGraph, u1, 0.22);
    let c0 = scallopPt(dx0, yCollar, rCollar, u0);
    let c1 = scallopPt(dx0, yCollar, rCollar, u1);

    // Cylindrical lighting across the shaved cedar cone (cool-lit blonde cedar to slate-umber shadow)
    let cedarCol;
    if (tm < 0.16) {
      cedarCol = mixHex("#b7b0a8", "#eddcc8", tm / 0.16);
    } else if (tm < 0.36) {
      cedarCol = mixHex("#eddcc8", "#f8efe2", (tm - 0.16) / 0.20);
    } else if (tm < 0.64) {
      cedarCol = mixHex("#f8efe2", "#cfb095", (tm - 0.36) / 0.28);
    } else if (tm < 0.86) {
      cedarCol = mixHex("#cfb095", "#7a6456", (tm - 0.64) / 0.22);
    } else {
      cedarCol = mixHex("#7a6456", "#968579", (tm - 0.86) / 0.14);
    }

    washPoly([g0, g1, c1, c0], cedarCol, 255);

    // Coloured-pencil radial wood fiber strokes
    let um = (u0 + u1) * 0.5;
    let gm = ringPt(dx0, yGraphite, rGraph, um, 0.22);
    let cm = scallopPt(dx0, yCollar, rCollar, um);
    let fiberCol = tm < 0.45
      ? mixHex(cedarCol, "#fffaf2", 0.35)
      : mixHex(cedarCol, "#523f34", 0.35);
    brush.set("cedar_grain", fiberCol, 0.78);
    brush.line(gm[0], gm[1], cm[0], cm[1]);
  }

  // Concentric wood growth-ring arches across the shaved cedar cone
  const ringLevels = [0.22, 0.42, 0.62, 0.80];
  for (let rl of ringLevels) {
    let yR = lerp(yGraphite, yCollar, rl);
    let rR = lerp(rGraph, rCollar, rl);
    let grainCol = rl % 0.4 < 0.25 ? "#a98268" : "#8d6850";
    brush.set("cedar_grain", grainCol, 0.58);
    let prev = null;
    for (let s = 0; s <= 14; s++) {
      let u = lerp(-0.92, 0.92, s / 14);
      // Slight natural wave in the wood ring
      let wave = sin(u * 180 + rl * 90) * 0.03 * rR;
      let pt = ringPt(dx0, yR + wave, rR, u, 0.26);
      if (prev) {
        brush.line(prev[0], prev[1], pt[0], pt[1]);
      }
      prev = pt;
    }
  }

  // Crisp triple-scalloped collar rim: dark step shadow + white primer undercoat line
  let prevScallop = null;
  for (let s = 0; s <= 24; s++) {
    let u = lerp(-1, 1, s / 24);
    let pt = scallopPt(dx0, yCollar, rCollar, u);
    if (prevScallop) {
      // Dark step micro-shadow just above lacquer
      brush.set("rotring", "#1b2421", 0.58);
      brush.line(prevScallop[0], prevScallop[1] - 0.8, pt[0], pt[1] - 0.8);
      // Bright cream-white primer edge along the cut lacquer
      brush.set("rotring", "#f5f7f2", 0.75);
      brush.line(prevScallop[0], prevScallop[1] + 1.1, pt[0], pt[1] + 1.1);
    }
    prevScallop = pt;
  }

  // =========================================================================
  // 4. CRISP GRAPHITE CORE CATCHING THE LIGHT
  // =========================================================================
  let tipPt = [perspX(dx0, yTip), yTip];
  let graphSlices = 14;
  for (let i = 0; i < graphSlices; i++) {
    let t0 = i / graphSlices;
    let t1 = (i + 1) / graphSlices;
    let u0 = lerp(-1, 1, t0);
    let u1 = lerp(-1, 1, t1);
    let tm = (t0 + t1) * 0.5;

    let g0 = ringPt(dx0, yGraphite, rGraph, u0, 0.22);
    let g1 = ringPt(dx0, yGraphite, rGraph, u1, 0.22);

    let gCol;
    if (tm < 0.20) {
      gCol = mixHex("#2c3840", "#687c88", tm / 0.20);
    } else if (tm < 0.36) {
      // Brilliant specular highlight strip on the graphite cone
      gCol = mixHex("#687c88", "#eef7fa", (tm - 0.20) / 0.16);
    } else if (tm < 0.52) {
      gCol = mixHex("#eef7fa", "#34414a", (tm - 0.36) / 0.16);
    } else if (tm < 0.85) {
      gCol = mixHex("#34414a", "#10161a", (tm - 0.52) / 0.33);
    } else {
      gCol = mixHex("#10161a", "#2b3940", (tm - 0.85) / 0.15);
    }

    washPoly([tipPt, g1, g0], gCol, 255);

    // Fine graphite sheen strokes
    let gm = ringPt(dx0, yGraphite, rGraph, (u0 + u1) * 0.5, 0.22);
    brush.set("2B", gCol, 0.45);
    brush.line(tipPt[0], tipPt[1], gm[0], gm[1]);
  }

  // Razor-sharp white-silver specular reflection line on the graphite core
  let gSpecBase = ringPt(dx0, yGraphite, rGraph, -0.38, 0.22);
  brush.set("rotring", "#ffffff", 0.85);
  brush.line(tipPt[0], tipPt[1] + 1, gSpecBase[0], gSpecBase[1]);

  // Crisp silhouette outline on the cone and graphite tip
  let gLeft  = ringPt(dx0, yGraphite, rGraph, -1.0, 0.22);
  let gRight = ringPt(dx0, yGraphite, rGraph,  1.0, 0.22);
  let cLeft  = scallopPt(dx0, yCollar, rCollar, -1.0);
  let cRight = scallopPt(dx0, yCollar, rCollar,  1.0);

  brush.set("2H", "#465459", 0.55);
  brush.line(tipPt[0], tipPt[1], gLeft[0], gLeft[1]);
  brush.line(gLeft[0], gLeft[1], cLeft[0], cLeft[1]);

  brush.set("2B", "#161d21", 0.62);
  brush.line(tipPt[0], tipPt[1], gRight[0], gRight[1]);
  brush.line(gRight[0], gRight[1], cRight[0], cRight[1]);

  // =========================================================================
  // 5. FINE GOLD INK LINES TRACING THE VERTICALS
  // =========================================================================
  const goldVerts = [
    { u: -1.00, col: "#d5b152", w: 0.72 },
    { u: -0.46, col: "#f7e299", w: 0.92 },
    { u:  0.46, col: "#c9a141", w: 0.78 },
    { u:  1.00, col: "#9e7a28", w: 0.65 }
  ];
  for (let gv of goldVerts) {
    let pTop = scallopPt(dx0, yCollar, rCollar, gv.u);
    let pBot = [perspX(dx0, yBot) + gv.u * rBot, yBot];
    brush.set("gold_ink", gv.col, gv.w);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }
}

function drawBrassFerrule(dx0, r0, y1, y2) {
  let r1 = (r0 + 0.9) * perspK(y1);
  let r2 = (r0 + 0.9) * perspK(y2);
  let slices = 24;

  // Metallic reflection gradient across cylinder [-1, 1]
  for (let i = 0; i < slices; i++) {
    let t0 = i / slices;
    let t1 = (i + 1) / slices;
    let u0 = lerp(-1, 1, t0);
    let u1 = lerp(-1, 1, t1);
    let tm = (t0 + t1) * 0.5;

    let pTop0 = ringPt(dx0, y1, r1, u0, 0.20);
    let pTop1 = ringPt(dx0, y1, r1, u1, 0.20);
    let pBot1 = ringPt(dx0, y2, r2, u1, 0.20);
    let pBot0 = ringPt(dx0, y2, r2, u0, 0.20);

    let bCol;
    if (tm < 0.14) {
      bCol = mixHex("#453719", "#9e833d", tm / 0.14);
    } else if (tm < 0.28) {
      bCol = mixHex("#9e833d", "#f5e39e", (tm - 0.14) / 0.14);
    } else if (tm < 0.36) {
      // Bright white-gold specular bar
      bCol = mixHex("#f5e39e", "#fffef2", (tm - 0.28) / 0.08);
    } else if (tm < 0.48) {
      bCol = mixHex("#fffef2", "#c8a750", (tm - 0.36) / 0.12);
    } else if (tm < 0.72) {
      bCol = mixHex("#c8a750", "#59461e", (tm - 0.48) / 0.24);
    } else if (tm < 0.88) {
      // Secondary warm brass reflection on the right
      bCol = mixHex("#59461e", "#b89644", (tm - 0.72) / 0.16);
    } else {
      bCol = mixHex("#b89644", "#33270f", (tm - 0.88) / 0.12);
    }

    washPoly([pTop0, pTop1, pBot1, pBot0], bCol, 255);

    // Fine vertical metallic sheen stroke
    let um = (u0 + u1) * 0.5;
    let pm1 = ringPt(dx0, y1, r1, um, 0.20);
    let pm2 = ringPt(dx0, y2, r2, um, 0.20);
    brush.set("fine_cpencil", bCol, 0.65);
    brush.line(pm1[0], pm1[1], pm2[0], pm2[1]);
  }

  // Knurled/ribbed horizontal rings at top & bottom of the brass ferrule
  const ringFracs = [0.0, 0.11, 0.22, 0.78, 0.89, 1.0];
  for (let rf of ringFracs) {
    let yR = lerp(y1, y2, rf);
    let rR = lerp(r1, r2, rf);
    let prev = null;
    for (let s = 0; s <= 18; s++) {
      let u = lerp(-1, 1, s / 18);
      let pt = ringPt(dx0, yR, rR, u, 0.20);
      if (prev) {
        // Dark bronze crimp groove
        brush.set("rotring", "#2b200b", 0.62);
        brush.line(prev[0], prev[1] - 0.7, pt[0], pt[1] - 0.7);
        // Bright gold-ink rim highlight
        let hiCol = abs(u + 0.32) < 0.25 ? "#fffdf0" : "#e8ca74";
        brush.set("gold_ink", hiCol, 0.72);
        brush.line(prev[0], prev[1] + 0.8, pt[0], pt[1] + 0.8);
      }
      prev = pt;
    }
  }

  // Fine vertical knurling ticks inside the top and bottom crimped collars
  for (let band of [[0.02, 0.20], [0.80, 0.98]]) {
    let yA = lerp(y1, y2, band[0]);
    let yB = lerp(y1, y2, band[1]);
    let rA = lerp(r1, r2, band[0]);
    let rB = lerp(r1, r2, band[1]);
    for (let k = -9; k <= 9; k++) {
      let u = k / 10.0;
      let pA = ringPt(dx0, yA, rA, u, 0.20);
      let pB = ringPt(dx0, yB, rB, u, 0.20);
      brush.set("rotring", "#3d2e12", 0.42);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }
}

function drawFinalGoldAccents(tiers) {
  // Soaring fine gold ink lines extending upward from the spire tips into the sky
  for (let tIdx = 1; tIdx < tiers.length; tIdx++) {
    for (let p of tiers[tIdx]) {
      let tipX = perspX(p.dx0, p.yTip);
      let tipY = p.yTip;

      // Subtle gold-ink spire needle extending slightly above the tip along the perspective ray
      let skyY = tipY - (p.dx0 === 0 && tIdx === 1 ? 42 : 22);
      let skyX = perspX(p.dx0, skyY);
      brush.set("gold_glint", "#e6c972", 0.65);
      brush.line(tipX, tipY, skyX, skyY);

      // Crisp micro star-glint on the freshly sharpened graphite point
      brush.set("gold_glint", "#ffffff", 0.75);
      brush.line(tipX - 4.5, tipY, tipX + 4.5, tipY);
      brush.line(tipX, tipY - 4.5, tipX, tipY + 4.5);
    }
  }

  // Extra radiant crown glint on the supreme central apex tip at (600, 62)
  let apexX = 600;
  let apexY = 62;
  brush.set("gold_glint", "#fffef5", 0.95);
  brush.line(apexX - 14, apexY, apexX + 14, apexY);
  brush.line(apexX, apexY - 18, apexX, apexY + 14);
  brush.line(apexX - 7, apexY - 7, apexX + 7, apexY + 7);
  brush.line(apexX - 7, apexY + 7, apexX + 7, apexY - 7);
}

