// ============================================================================
// CLOTH GEOMETRY & ADIRE ELEKO STARCH-RESIST PATTERNS
// ============================================================================

function clothLeftEdge(y) {
  let t = constrain(y / 1120, 0, 1);
  if (y < 360) {
    let s = y / 360;
    return lerp(195, 415, pow(s, 1.15)) + sin(y * 0.7) * 8;
  } else if (y < 660) {
    let s = (y - 360) / 300;
    return 415 + sin(s * 180) * 28 + sin(y * 1.4) * 7;
  } else {
    let s = (y - 660) / 460;
    return lerp(420, 355, pow(s, 0.85)) + sin(y * 0.55) * 14;
  }
}

function clothRightEdge(y) {
  if (y < 360) {
    let s = y / 360;
    return lerp(575, 650, pow(s, 0.9)) + cos(y * 0.65) * 10;
  } else if (y < 660) {
    let s = (y - 360) / 300;
    return lerp(650, 735, s) - sin(s * 180) * 22 + cos(y * 1.3) * 8;
  } else {
    let s = (y - 660) / 460;
    return lerp(735, 865, pow(s, 0.8)) + cos(y * 0.5) * 16;
  }
}

// Evaluates authentic Yoruba Adire Eleko starch-resist motifs in cloth (U, V) space
// Returns > 0 where starch resist protects the untouched paper from dye
function evaluateAdireResist(U, V) {
  // Warp U and V slightly with organic hand-painted cassava-paste irregularity
  let wobU = U + (noise(U * 8, V * 8) - 0.5) * 0.012;
  let wobV = V + (noise(U * 8 + 31, V * 8 + 17) - 0.5) * 0.012;

  // Grid cell coordinates (4 columns across cloth width, 9 rows along cloth length)
  let colF = wobU * 4.0;
  let rowF = wobV * 9.0;
  let col = floor(colF);
  let row = floor(rowF);
  let u = fract(colF);
  let v = fract(rowF);

  // 1. Structural double-line Adire panel dividers (reserved white paper strips)
  if (u < 0.055 || u > 0.945 || (u > 0.085 && u < 0.115)) return 1.0;
  if (v < 0.055 || v > 0.945 || (v > 0.085 && v < 0.115)) return 1.0;

  // Normalize interior panel coordinates to [0, 1]
  let pu = constrain((u - 0.12) / 0.82, 0, 1);
  let pv = constrain((v - 0.12) / 0.82, 0, 1);

  let motifType = abs(col * 3 + row * 5) % 4;

  if (motifType === 0) {
    // EKA: Comb-drawn wavy parallel cassava tracks + seed dots
    let wave = pu + sin(pv * 360 * 2.0) * 0.075;
    let stripe = fract(wave * 5.0);
    if (stripe < 0.28) return 0.95;
    // Dots between comb tracks
    let dotV = fract(pv * 6.0);
    if (stripe > 0.52 && stripe < 0.76 && abs(dotV - 0.5) < 0.18) return 0.9;
  } else if (motifType === 1) {
    // OLOKUN SPIRAL & RADIATING PETALS
    let dx = pu - 0.5;
    let dy = pv - 0.5;
    let r = sqrt(dx * dx + dy * dy);
    let ang = (atan2(dy, dx) + 360) % 360;
    if (r < 0.34) {
      let spiral = fract(r * 7.5 - ang / 360.0);
      if (spiral < 0.34) return 1.0;
    } else if (r < 0.48) {
      let petal = fract(ang / 30.0);
      if (petal < 0.36) return 0.9;
    }
  } else if (motifType === 2) {
    // IGI: Herringbone cassava leaf / feather ribs
    let spine = abs(pu - 0.5);
    if (spine < 0.045) return 1.0;
    let rib = fract((pv * 6.0) + (pu > 0.5 ? (pu - 0.5) : (0.5 - pu)) * 4.5);
    if (rib < 0.30 && spine < 0.44) return 0.95;
  } else {
    // IBADANDUN: Crisscross lattice with central starch dots
    let d1 = fract((pu + pv) * 3.5);
    let d2 = fract((pu - pv + 2.0) * 3.5);
    if (d1 < 0.20 || d2 < 0.20) return 0.95;
    let cx = abs(d1 - 0.60);
    let cy = abs(d2 - 0.60);
    if (cx * cx + cy * cy < 0.032) return 0.95;
  }

  return 0.0;
}

// Helper for drawing a filled/washed/stroked polygon via brush.beginShape
function drawPoly(pts, curv = 0.25, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// ============================================================================
// LAYER 1 & 2: CLAY VAT RIM & DEEP INDIGO VAT BATH (AROUND CLOTH SILHOUETTE)
// ============================================================================

function renderVatAndCourtyard() {
  let vatCx = 600;
  let vatCy = 785;
  let rInner = 490;
  let rOuter = 655;

  // 1. Earthy Courtyard corners outside the clay vat rim (top-left & top-right)
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.45);

  // Top-left courtyard corner
  brush.fill(PAL.clayMid, 130);
  drawPoly([
    [0, 0], [205, 0], [235, 160], [180, 310], [0, 420]
  ], 0.15);

  // Top-right courtyard corner
  brush.fill(PAL.clayMid, 135);
  drawPoly([
    [580, 0], [1200, 0], [1200, 460], [1020, 310], [800, 175], [595, 120]
  ], 0.15);

  brush.fill(PAL.clayDark, 115);
  drawPoly([
    [720, 0], [1200, 0], [1200, 310], [980, 210], [740, 95]
  ], 0.2);

  // 2. Curved Dark Clay Vat Rim — Split Left and Right of the Cloth so Cloth Paper stays Untouched
  // Left Rim Arc
  for (let pass = 0; pass < 3; pass++) {
    let col = pass === 0 ? PAL.clayLight : (pass === 1 ? PAL.clayMid : PAL.clayDark);
    let op = pass === 0 ? 110 : (pass === 1 ? 150 : 140);
    brush.fill(col, op);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.7, 0.5);

    let ptsL = [];
    let rOut = rOuter - pass * 22;
    let rIn = rInner + pass * 18;
    for (let a = 155; a <= 242; a += 5) {
      let x = vatCx + cos(a) * rOut;
      let y = vatCy + sin(a) * rOut;
      x = min(x, clothLeftEdge(y) - 8);
      ptsL.push([x, y]);
    }
    for (let a = 242; a >= 155; a -= 5) {
      let x = vatCx + cos(a) * rIn;
      let y = vatCy + sin(a) * rIn;
      x = min(x, clothLeftEdge(y) - 8);
      ptsL.push([x, y]);
    }
    drawPoly(ptsL, 0.25);

    // Right Rim Arc
    let ptsR = [];
    for (let a = 292; a <= 385; a += 5) {
      let x = vatCx + cos(a) * rOut;
      let y = vatCy + sin(a) * rOut;
      x = max(x, clothRightEdge(y) + 8);
      ptsR.push([x, y]);
    }
    for (let a = 385; a >= 292; a -= 5) {
      let x = vatCx + cos(a) * rIn;
      let y = vatCy + sin(a) * rIn;
      x = max(x, clothRightEdge(y) + 8);
      ptsR.push([x, y]);
    }
    drawPoly(ptsR, 0.25);
  }

  // Soft pastel terracotta & ochre rim highlight along the worn top lip of the vat
  brush.fill(PAL.pastelOchre, 75);
  brush.fillBleed(0.18, "out");
  let lipR = [];
  for (let a = 300; a <= 358; a += 6) {
    let rMid = (rInner + rOuter) * 0.5 - 12;
    lipR.push([max(vatCx + cos(a) * (rMid + 26), clothRightEdge(vatCy + sin(a) * rMid) + 12), vatCy + sin(a) * (rMid + 26)]);
  }
  for (let a = 358; a >= 300; a -= 6) {
    let rMid = (rInner + rOuter) * 0.5 - 12;
    lipR.push([max(vatCx + cos(a) * (rMid - 22), clothRightEdge(vatCy + sin(a) * rMid) + 12), vatCy + sin(a) * (rMid - 22)]);
  }
  drawPoly(lipR, 0.3);

  // Inner vertical shadow wall of the clay vat before the liquid meniscus
  brush.fill(PAL.clayDeep, 175);
  brush.fillBleed(0.15, "in");
  let wallL = [];
  for (let a = 165; a <= 240; a += 6) {
    let y1 = vatCy + sin(a) * (rInner + 15);
    wallL.push([min(vatCx + cos(a) * (rInner + 15), clothLeftEdge(y1) - 6), y1]);
  }
  for (let a = 240; a >= 165; a -= 6) {
    let y2 = vatCy + sin(a) * (rInner - 42);
    wallL.push([min(vatCx + cos(a) * (rInner - 42), clothLeftEdge(y2) - 6), y2]);
  }
  drawPoly(wallL, 0.2);

  let wallR = [];
  for (let a = 295; a <= 375; a += 6) {
    let y1 = vatCy + sin(a) * (rInner + 15);
    wallR.push([max(vatCx + cos(a) * (rInner + 15), clothRightEdge(y1) + 6), y1]);
  }
  for (let a = 375; a >= 295; a -= 6) {
    let y2 = vatCy + sin(a) * (rInner - 42);
    wallR.push([max(vatCx + cos(a) * (rInner - 42), clothRightEdge(y2) + 6), y2]);
  }
  drawPoly(wallR, 0.2);

  // 3. Deep Indigo Dye Bath inside the Vat (Left, Right, and Bottom Pool)
  // Built in layered watercolor passes from Prussian blue to near-black indigo
  let bathPasses = [
    { col: PAL.prussian, op: 165, bleed: 0.25, inset: 0 },
    { col: PAL.indigo, op: 185, bleed: 0.18, inset: 14 },
    { col: PAL.indigoBlack, op: 195, bleed: 0.12, inset: 28 }
  ];

  for (let bp of bathPasses) {
    brush.fill(bp.col, bp.op);
    brush.fillBleed(bp.bleed, "in");
    brush.fillTexture(0.55, 0.35);

    // Left Vat Pool
    let poolL = [];
    for (let y = 420; y <= 1140; y += 35) {
      let dy = y - vatCy;
      let dx = sqrt(max(0, sq(rInner - 25 - bp.inset) - dy * dy));
      let xVat = max(0, vatCx - dx);
      poolL.push([min(xVat, clothLeftEdge(y) - 10), y]);
    }
    for (let y = 1140; y >= 420; y -= 35) {
      poolL.push([clothLeftEdge(y) - 6 - bp.inset * 0.4, y]);
    }
    drawPoly(poolL, 0.2);

    // Right Vat Pool
    let poolR = [];
    for (let y = 420; y <= 1140; y += 35) {
      poolR.push([clothRightEdge(y) + 6 + bp.inset * 0.4, y]);
    }
    for (let y = 1140; y >= 420; y -= 35) {
      let dy = y - vatCy;
      let dx = sqrt(max(0, sq(rInner - 25 - bp.inset) - dy * dy));
      let xVat = min(1200, vatCx + dx);
      poolR.push([max(xVat, clothRightEdge(y) + 10), y]);
    }
    drawPoly(poolR, 0.2);

    // Bottom Submergence Pool (below y = 1045)
    let poolB = [
      [180, 1055 + bp.inset * 0.5],
      [600, 1085 + bp.inset * 0.5],
      [1020, 1055 + bp.inset * 0.5],
      [1120, 1200],
      [80, 1200]
    ];
    drawPoly(poolB, 0.2);
  }

  // 4. Iridescent Bronze Oxidation Sheen swirling on the Indigo Bath Surface
  let bronzeSwirls = [
    // Left surface oxidation veils
    { cx: 235, cy: 760, rx: 125, ry: 42, col: PAL.bronze, op: 85 },
    { cx: 255, cy: 755, rx: 80, ry: 22, col: PAL.bronzeLight, op: 95 },
    { cx: 290, cy: 920, rx: 115, ry: 36, col: PAL.bronze, op: 80 },
    { cx: 280, cy: 920, rx: 65, ry: 16, col: PAL.pastelOchre, op: 85 },
    { cx: 210, cy: 610, rx: 85, ry: 28, col: PAL.pastelLavender, op: 65 },
    // Right surface oxidation veils
    { cx: 955, cy: 730, rx: 130, ry: 44, col: PAL.bronze, op: 90 },
    { cx: 945, cy: 726, rx: 78, ry: 20, col: PAL.bronzeLight, op: 100 },
    { cx: 920, cy: 890, rx: 120, ry: 38, col: PAL.bronze, op: 85 },
    { cx: 930, cy: 888, rx: 70, ry: 18, col: PAL.pastelOchre, op: 90 },
    { cx: 960, cy: 590, rx: 90, ry: 30, col: PAL.pastelPeriwinkle, op: 70 },
    // Bottom submergence bronze & pastel sky ripples
    { cx: 600, cy: 1125, rx: 240, ry: 35, col: PAL.bronze, op: 90 },
    { cx: 600, cy: 1122, rx: 160, ry: 18, col: PAL.bronzeLight, op: 105 },
    { cx: 440, cy: 1065, rx: 95, ry: 24, col: PAL.pastelSky, op: 75 },
    { cx: 775, cy: 1060, rx: 105, ry: 25, col: PAL.pastelSky, op: 75 }
  ];

  for (let s of bronzeSwirls) {
    brush.fill(s.col, s.op);
    brush.fillBleed(0.3, "out");
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      let rMod = 1 + (noise(s.cx * 0.02 + cos(a), s.cy * 0.02 + sin(a)) - 0.5) * 0.35;
      pts.push([
        s.cx + cos(a) * s.rx * rMod,
        s.cy + sin(a) * s.ry * rMod + sin(a * 2) * 6
      ]);
    }
    drawPoly(pts, 0.35);
  }
  brush.noFill();

  // 5. Tactile Clay Vat Striations, Pitted Grain & Aged Indigo Splashes
  for (let i = 0; i < 65; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let aBase = side < 0 ? random(158, 232) : random(300, 375);
    let r = random(rInner - 10, rOuter - 10);
    let x1 = vatCx + cos(aBase) * r;
    let y1 = vatCy + sin(aBase) * r;
    let x2 = vatCx + cos(aBase + random(4, 12)) * (r + random(-8, 8));
    let y2 = vatCy + sin(aBase + random(4, 12)) * (r + random(-8, 8));

    if (side < 0 && (x1 > clothLeftEdge(y1) - 14 || x2 > clothLeftEdge(y2) - 14)) continue;
    if (side > 0 && (x1 < clothRightEdge(y1) + 14 || x2 < clothRightEdge(y2) + 14)) continue;

    let col = random([PAL.clayDeep, PAL.clayLight, PAL.pastelOchre, PAL.indigo]);
    brush.set(i % 3 === 0 ? "charcoal" : "2B", col, random(0.35, 0.85));
    brush.line(x1, y1, x2, y2);
  }

  // Vat foam clusters ("flower of the indigo vat") floating near the inner clay wall
  let foamCenters = [
    [220, 560], [185, 680], [215, 830], [295, 1010],
    [980, 570], [1015, 700], [985, 845], [895, 1005]
  ];
  for (let fc of foamCenters) {
    for (let b = 0; b < 14; b++) {
      let bx = fc[0] + randomGaussian(0, 22);
      let by = fc[1] + randomGaussian(0, 14);
      let br = random(2.5, 8.5);
      brush.noStroke();
      brush.wash(b % 3 === 0 ? PAL.paper : PAL.pastelSky, random(160, 235));
      brush.circle(bx, by, br, 0.2);
      brush. noWash();
      brush.set("rigger", PAL.prussian, 0.45);
      brush.arc(bx, by, br, 0, 355);
    }
  }
}

// ============================================================================
// LAYER 3: THE WRUNG ADIRE CLOTH (LAYERED WATERCOLOR + UNTOUCHED PAPER RESIST)
// ============================================================================

function renderFoldStrip(foldCfg) {
  let { ptsLeft, ptsRight, uMin, uMax, vMin, vMax, shadowBias, twistDir } = foldCfg;
  let nV = 28;
  let nU = 14;

  // Helper to bilinearly interpolate (x, y) on the fold surface
  function surfXY(su, sv) {
    let idxF = sv * (ptsLeft.length - 1);
    let i0 = floor(idxF);
    let i1 = min(ptsLeft.length - 1, i0 + 1);
    let f = idxF - i0;
    let lx = lerp(ptsLeft[i0][0], ptsLeft[i1][0], f);
    let ly = lerp(ptsLeft[i0][1], ptsLeft[i1][1], f);
    let rx = lerp(ptsRight[i0][0], ptsRight[i1][0], f);
    let ry = lerp(ptsRight[i0][1], ptsRight[i1][1], f);

    // Slight cylindrical arch across the fold
    let arch = sin(su * 180) * 8 * twistDir;
    return [lerp(lx, rx, su) + arch * 0.3, lerp(ly, ry, su) - arch];
  }

  // Step through UV grid and group contiguous non-resisted (dyed) cells along U
  // Leaving starch-resist cells completely unpainted so the untouched #F5EFE4 paper remains crisp!
  brush.noStroke();

  for (let iv = 0; iv < nV; iv++) {
    let sv0 = iv / nV;
    let sv1 = (iv + 1) / nV;
    let svMid = (sv0 + sv1) * 0.5;
    let V = lerp(vMin, vMax, svMid);

    let iu = 0;
    while (iu < nU) {
      let suTest = (iu + 0.5) / nU;
      let UTest = lerp(uMin, uMax, suTest);
      let resist = evaluateAdireResist(UTest, V);

      if (resist > 0.5) {
        // UNTOUCHED PAPER (Starch-Resist)!
        // Only if deep in fold trough or hand cast-shadow, lay a whisper-soft pastel glaze
        let edgeShade = 1.0 - sin(suTest * 180);
        let pinchShade = (V > 0.30 && V < 0.62) ? 0.35 : 0.0;
        let totalShade = edgeShade * 0.55 + pinchShade + shadowBias;

        if (totalShade > 0.52) {
          let su0 = iu / nU;
          let su1 = (iu + 1) / nU;
          let p00 = surfXY(su0, sv0);
          let p10 = surfXY(su1, sv0);
          let p11 = surfXY(su1, sv1);
          let p01 = surfXY(su0, sv1);
          brush.fill(totalShade > 0.78 ? PAL.pastelPeriwinkle : PAL.pastelSky, 52);
          brush.fillBleed(0.06, "in");
          brush.fillTexture(0.3, 0.2);
          drawPoly([p00, p10, p11, p01], 0.1);
          brush.noFill();
        }
        iu++;
      } else {
        // Contiguous run of indigo-dyed fabric
        let iuStart = iu;
        while (iu < nU) {
          let suNext = (iu + 0.5) / nU;
          let UNext = lerp(uMin, uMax, suNext);
          if (evaluateAdireResist(UNext, V) > 0.5 || (iu - iuStart) >= 4) break;
          iu++;
        }
        let iuEnd = iu;
        let su0 = iuStart / nU;
        let su1 = iuEnd / nU;
        let suMid = (su0 + su1) * 0.5;

        let p00 = surfXY(su0, sv0);
        let p10 = surfXY(su1, sv0);
        let p11 = surfXY(su1, sv1);
        let p01 = surfXY(su0, sv1);

        // Compute 3D cylindrical fold lighting + wringing compression darkness
        let cylLight = sin(suMid * 180); // 1 at fold crest, 0 at fold crevices
        let wringDepth = (V > 0.32 && V < 0.62) ? 0.32 : (V >= 0.62 ? 0.22 : 0.0);
        let darkness = (1.0 - cylLight) * 0.65 + wringDepth + shadowBias;

        // Pass 1: Watercolor Prussian / Pastel-Blue Sheen
        let baseCol = PAL.prussian;
        let baseOp = 155;
        if (darkness < 0.28) {
          baseCol = PAL.prussianLight;
          baseOp = 130;
        } else if (darkness > 0.72) {
          baseCol = PAL.indigo;
          baseOp = 185;
        } else if (darkness > 0.50) {
          baseCol = PAL.prussianDeep;
          baseOp = 170;
        }

        brush.fill(baseCol, baseOp);
        brush.fillBleed(0.11, "out");
        brush.fillTexture(0.55, 0.45);
        drawPoly([p00, p10, p11, p01], 0.15);

        // Pass 2: Deep Indigo-Black in troughs & wrung compression creases
        if (darkness > 0.58) {
          brush.fill(darkness > 0.82 ? PAL.indigoBlack : PAL.indigo, 165);
          brush.fillBleed(0.08, "in");
          drawPoly([p00, p10, p11, p01], 0.12);
        }

        // Subtle bronze oxidation glint on wet crests of the twisted cloth
        if (cylLight > 0.82 && V > 0.28 && V < 0.82 && (iv + iuStart) % 5 === 0) {
          brush.fill(PAL.bronze, 68);
          brush.fillBleed(0.15, "out");
          drawPoly([p00, p10, p11, p01], 0.15);
        }
        brush.noFill();
      }
    }
  }

  // Fine starch-resist crackle veins, wet cloth fiber hatching & indigo bleed borders
  for (let iv = 0; iv <= nV; iv++) {
    let sv = iv / nV;
    let V = lerp(vMin, vMax, sv);
    for (let iu = 0; iu < nU; iu++) {
      let su0 = iu / nU;
      let su1 = (iu + 1) / nU;
      let U0 = lerp(uMin, uMax, su0);
      let U1 = lerp(uMin, uMax, su1);
      let r0 = evaluateAdireResist(U0, V);
      let r1 = evaluateAdireResist(U1, V);

      let p0 = surfXY(su0, sv);
      let p1 = surfXY(su1, sv);

      // Crisp indigo boundary where starch resist meets saturated dye
      if ((r0 > 0.5) !== (r1 > 0.5)) {
        brush.set("rigger", PAL.prussianDeep, 0.55);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      } else if (r0 > 0.5 && r1 > 0.5 && random() < 0.28) {
        // Hairline indigo crackle inside the wrung cassava starch paste!
        brush.set("starchCrack", PAL.prussian, random(0.28, 0.52));
        brush.line(
          p0[0] + random(-3, 3),
          p0[1] + random(-3, 3),
          p1[0] + random(-3, 3),
          p1[1] + random(-3, 3)
        );
      } else if (r0 <= 0.5 && (iu === 0 || iu === nU - 1)) {
        // Deep indigo crease along fold valley
        brush.set("2B", PAL.indigoBlack, 0.75);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      }
    }
  }

  // Longitudinal tension striations along the fold
  for (let s = 0.08; s <= 0.92; s += 0.14) {
    let isEdge = s < 0.2 || s > 0.8;
    for (let iv = 0; iv < nV; iv += 2) {
      let sv0 = iv / nV;
      let sv1 = min(1, (iv + 2) / nV);
      let U = lerp(uMin, uMax, s);
      let V = lerp(vMin, vMax, (sv0 + sv1) * 0.5);
      if (evaluateAdireResist(U, V) > 0.5 && !isEdge) continue;

      let pA = surfXY(s, sv0);
      let pB = surfXY(s, sv1);
      brush.set(
        isEdge ? "2B" : "cpencil",
        isEdge ? PAL.indigoBlack : PAL.prussianDeep,
        isEdge ? 0.7 : 0.42
      );
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }
}

