// ============================================================================
// LAYER 4: ANATOMICAL DYER'S HANDS (DEEP BROWN SKIN, INDIGO CREASES, STAINED NAILS)
// ============================================================================

// Renders a sculpted 3D anatomical limb/finger segment with:
// - Opaque skin base wash
// - Layered sienna/umber watercolor shading
// - Soft pastel peach/lavender wet skin sheen
// - Indigo-stained skin flexion creases
function renderSkinSegment(pts, lightStripPts, coreShadowPts, creaseLines, stainZonePts) {
  // 1. Opaque skin foundation so underlying cloth/vat never bleeds through
  brush.noStroke();
  brush.wash(PAL.skinDeep, 248);
  drawPoly(pts, 0.28);
  brush.noWash();

  // 2. Warm sienna/umber watercolor midtone body
  brush.fill(PAL.skinMid, 165);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.42);
  drawPoly(pts, 0.28);

  // 3. Deep espresso & indigo shadow along lower/receding edge
  if (coreShadowPts && coreShadowPts.length >= 3) {
    brush.fill(PAL.skinShadow, 185);
    brush.fillBleed(0.14, "in");
    drawPoly(coreShadowPts, 0.25);

    brush.fill(PAL.indigoBlack, 105);
    brush.fillBleed(0.12, "in");
    drawPoly(coreShadowPts, 0.25);
  }

  // 4. Indigo dye staining in skin creases & finger edges contacting wet cloth
  if (stainZonePts && stainZonePts.length >= 3) {
    brush.fill(PAL.prussianDeep, 145);
    brush.fillBleed(0.18, "out");
    drawPoly(stainZonePts, 0.25);
  }

  // 5. Earthy lit plane + Soft Pastel Peach/Rose/Sky wet specular skin sheen
  if (lightStripPts && lightStripPts.length >= 3) {
    brush.fill(PAL.skinLight, 145);
    brush.fillBleed(0.14, "out");
    drawPoly(lightStripPts, 0.3);

    // Narrow wet highlight core inside the lit strip
    let cx = 0, cy = 0;
    for (let p of lightStripPts) { cx += p[0]; cy += p[1]; }
    cx /= lightStripPts.length;
    cy /= lightStripPts.length;
    let wetCore = lightStripPts.map(p => [lerp(cx, p[0], 0.58), lerp(cy, p[1], 0.58)]);

    brush.fill(PAL.pastelPeach, 115);
    brush.fillBleed(0.10, "out");
    drawPoly(wetCore, 0.32);

    let specCore = lightStripPts.map(p => [lerp(cx, p[0], 0.32), lerp(cy, p[1], 0.32)]);
    brush.fill(PAL.pastelSky, 95);
    brush.fillBleed(0.06, "out");
    drawPoly(specCore, 0.32);
  }
  brush.noFill();

  // 6. Contour definition
  brush.set("2B", PAL.skinAbyss, 0.72);
  drawPoly(pts, 0.28, true);

  // 7. Indigo-stained skin creases & knuckle wrinkles
  if (creaseLines) {
    for (let cl of creaseLines) {
      brush.set("rigger", PAL.indigoBlack, 0.58);
      brush.spline(cl, 0.35);
      // Parallel warm umber/Prussian micro-ridge next to the crease
      let offsetCl = cl.map(p => [p[0] + 1.8, p[1] + 1.5]);
      brush.set("starchCrack", PAL.prussian, 0.42);
      brush.spline(offsetCl, 0.35);
    }
  }
}

// Renders a stained blue-black fingernail with cuticle shadow, dusty pastel lunula, and wet highlight
function renderStainedNail(cx, cy, rx, ry, angleDeg) {
  push();
  translate(cx, cy);
  rotate(angleDeg);

  // Nail bed & plate polygon
  let nailPts = [];
  for (let a = 0; a < 360; a += 30) {
    let radX = rx * (a > 90 && a < 270 ? 0.92 : 1.05);
    let radY = ry * (1.0 - 0.08 * abs(sin(a)));
    nailPts.push([cos(a) * radX, sin(a) * radY]);
  }

  // 1. Opaque deep indigo-black nail base
  brush.noStroke();
  brush.wash(PAL.indigo, 250);
  drawPoly(nailPts, 0.3);
  brush.noWash();

  // 2. Prussian blue & near-black pooled dye at cuticle and tip
  brush.fill(PAL.indigoBlack, 200);
  brush.fillBleed(0.08, "in");
  drawPoly(nailPts, 0.3);

  // 3. Soft pastel rose-lavender lunula (half-moon at proximal nail base) showing through indigo stain
  let lunulaPts = [
    [-rx * 0.72, -ry * 0.38],
    [-rx * 0.25, -ry * 0.52],
    [-rx * 0.15, 0],
    [-rx * 0.25, ry * 0.52],
    [-rx * 0.72, ry * 0.38]
  ];
  brush.fill(PAL.pastelLavender, 135);
  brush.fillBleed(0.08, "out");
  drawPoly(lunulaPts, 0.3);

  // 4. Crisp wet specular reflection along the convex nail ridge
  let glintPts = [
    [-rx * 0.45, -ry * 0.42],
    [rx * 0.55, -ry * 0.36],
    [rx * 0.48, -ry * 0.12],
    [-rx * 0.48, -ry * 0.18]
  ];
  brush.wash(PAL.paper, 230);
  drawPoly(glintPts, 0.25);
  brush.noWash();
  brush.noFill();

  // 5. Cuticle fold & lateral nail groove stained black-blue
  brush.set("rigger", PAL.abyss, 0.65);
  drawPoly(nailPts, 0.3, true);
  brush.set("rigger", PAL.prussianLight, 0.38);
  brush.line(-rx * 0.35, -ry * 0.28, rx * 0.45, -ry * 0.24);

  pop();
}

function renderDyersHands() {
  // Cast shadows of the hands onto the twisted cloth before drawing the hands
  brush.noStroke();
  brush.fill(PAL.indigoBlack, 145);
  brush.fillBleed(0.22, "out");
  // Left hand cast shadow on upper-central twist
  drawPoly([
    [320, 360], [545, 345], [535, 495], [355, 490]
  ], 0.25);
  // Right hand cast shadow on central & lower twist
  drawPoly([
    [535, 450], [775, 425], [765, 695], [555, 680]
  ], 0.25);
  brush.noFill();

  // ==========================================================================
  // LEFT HAND (Upper-Left: Wrist entering from left, fingers curling over top of cloth,
  // thumb pressing firmly across the front of the upper twist)
  // ==========================================================================

