// ============================================================================
// LAYER 5: INDIGO STREAMING BETWEEN FINGERS, BEADS, DRIPS & BRONZE SHEEN
// ============================================================================

function renderDyeStream(xStart, yStart, xEnd, yEnd, startW, endW, sway) {
  let steps = 22;
  let leftPts = [];
  let rightPts = [];
  let centerPts = [];
  let bronzePts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(xStart, xEnd, t) + sin(t * 180 * 1.5) * sway + (noise(xStart * 0.1, t * 4) - 0.5) * 8;
    let y = lerp(yStart, yEnd, pow(t, 1.05));
    // Rayleigh instability pinch modulation
    let pinch = 1.0 - 0.28 * sin(t * 360 * 2.5) * t;
    let w = lerp(startW, endW, pow(t, 0.7)) * pinch;

    leftPts.push([x - w, y]);
    rightPts.push([x + w, y]);
    centerPts.push([x - w * 0.25, y]);
    bronzePts.push([x + w * 0.35, y]);
  }

  let polyPts = leftPts.concat(rightPts.slice().reverse());

  // 1. Prussian blue translucent watercolor bleed halo
  brush.noStroke();
  brush.fill(PAL.prussianLight, 130);
  brush.fillBleed(0.20, "out");
  brush.fillTexture(0.45, 0.35);
  drawPoly(polyPts, 0.3);

  // 2. Deep saturated Prussian-to-Indigo liquid core
  brush.fill(PAL.indigo, 210);
  brush.fillBleed(0.06, "in");
  drawPoly(polyPts, 0.3);
  brush.noFill();

  // 3. Near-black indigo spine
  brush.set("2B", PAL.indigoBlack, 0.85);
  brush.spline(centerPts, 0.4);

  // 4. Bronze oxidation sheen thread along the right edge of the falling stream
  brush.set("cpencil", PAL.bronzeLight, 0.65);
  brush.spline(bronzePts, 0.4);

  // 5. Crisp untouched-paper / pastel-sky specular highlight along the liquid ridge
  for (let i = 1; i < centerPts.length - 2; i += 3) {
    brush.set("rigger", i % 2 === 0 ? PAL.paper : PAL.pastelSky, 0.52);
    brush.line(
      centerPts[i][0], centerPts[i][1],
      centerPts[i + 1][0], centerPts[i + 1][1]
    );
  }
}

function renderDyeBead(x, y, r, isTeardrop = true) {
  // Tiny dark cast shadow beneath bead
  brush.noStroke();
  brush.fill(PAL.indigoBlack, 185);
  brush.fillBleed(0.08, "out");
  brush.circle(x + 1.2, y + 2.2, r * 0.95, 0.15);

  // Saturated Prussian/Indigo droplet body
  if (isTeardrop) {
    let pts = [
      [x, y - r * 1.65],
      [x + r * 0.95, y - r * 0.2],
      [x + r * 0.85, y + r * 0.75],
      [x, y + r * 1.05],
      [x - r * 0.85, y + r * 0.75],
      [x - r * 0.95, y - r * 0.2]
    ];
    brush.wash(PAL.prussianDeep, 240);
    drawPoly(pts, 0.35);
    brush.noWash();
    brush.fill(PAL.indigoBlack, 195);
    brush.fillBleed(0.05, "in");
    drawPoly(pts, 0.35);
  } else {
    brush.wash(PAL.prussianDeep, 240);
    brush.circle(x, y, r, 0.15);
    brush.noWash();
    brush.fill(PAL.indigoBlack, 190);
    brush.fillBleed(0.05, "in");
    brush.circle(x, y, r * 0.85, 0.15);
  }
  brush.noFill();

  // Lower crescent internal refraction (bronze oxidation / pastel sky)
  brush.set("rigger", random() < 0.5 ? PAL.bronzeLight : PAL.pastelSky, 0.45);
  brush.arc(x, y, r * 0.68, 25, 155);

  // Pinpoint untouched-paper specular highlight on upper-left of bead
  brush.noStroke();
  brush.wash(PAL.paper, 250);
  brush.circle(x - r * 0.32, y - r * 0.32, max(1.4, r * 0.34), 0.1);
  brush.noWash();
}

function renderImpactRipple(cx, cy, maxRx, maxRy) {
  for (let ring = 0; ring < 3; ring++) {
    let t = (ring + 1) / 3;
    let rx = maxRx * t;
    let ry = maxRy * t;
    let pts = [];
    for (let a = 0; a < 360; a += 20) {
      pts.push([cx + cos(a) * rx, cy + sin(a) * ry]);
    }
    brush.set("rigger", ring === 0 ? PAL.paper : (ring === 1 ? PAL.pastelSky : PAL.bronzeLight), 0.55 - ring * 0.12);
    drawPoly(pts, 0.4, true);
  }
  // Tiny splash crown beads
  renderDyeBead(cx - maxRx * 0.35, cy - 14, 3.8, true);
  renderDyeBead(cx + maxRx * 0.28, cy - 18, 3.2, true);
}

