function draw() {
  translate(-width / 2, -height / 2);

  // Pure warm cotton-rag watercolor paper ground — kept untouched where starch resist reserves whites
  background(PAL.paper);

  // Subtle paper deckle warmth only at the outermost canvas border
  brush.noStroke();
  brush.fill(PAL.paperWarm, 55);
  brush.fillBleed(0.3, "in");
  brush.fillTexture(0.6, 0.25);
  drawPoly([[0, 0], [1200, 0], [1200, 90], [0, 90]], 0.1);
  drawPoly([[0, 1110], [1200, 1110], [1200, 1200], [0, 1200]], 0.1);
  brush.noFill();

  // 1. Render Dark Clay Vat Rim, Deep Indigo Bath & Bronze Oxidation Swirls (around cloth bounds)
  renderVatAndCourtyard();

  // 2. Render Twisted Adire Cloth with Reserved Untouched-Paper Starch-Resist Patterns
  renderAdireCloth();

  // 3. Render the Dyer's Hands (Deep Brown Skin, Indigo Creases, Blue-Black Stained Fingernails)
  renderDyersHands();

  // 4. Render Pressurized Indigo Streams, Falling Dye Beads, Oxidation Glints & Splash Ripples
  renderStreamsAndBeads();

  noLoop();
}

