function initLayers() {
  const names = [
    "PAPER_KNOCKOUT",
    "BUTTER_BOUNCE",
    "MINT",
    "MINT_OVER",
    "GREY",
    "GREY_OVER",
    "VERMILION",
    "VERMILION_OVER",
    "CYAN",
    "CYAN_OVER",
    "OVERPRINT_DARK",
    "HIGHLIGHT"
  ];
  layers = {};
  for (let n of names) {
    layers[n] = { polys: [], hatches: [], lines: [] };
  }
}

function addPoly(layerName, pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  let cleaned = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (!p || isNaN(p[0]) || isNaN(p[1])) continue;
    if (cleaned.length === 0) {
      cleaned.push([p[0], p[1]]);
    } else {
      let prev = cleaned[cleaned.length - 1];
      if ( Math.hypot(p[0] - prev[0], p[1] - prev[1]) > 0.6 ) {
        cleaned.push([p[0], p[1]]);
      }
    }
  }
  if (cleaned.length >= 3) {
    let first = cleaned[0];
    let last = cleaned[cleaned.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) < 0.6) {
      cleaned.pop();
    }
  }
  if (cleaned.length >= 3) {
    layers[layerName].polys.push({ pts: cleaned, curvature });
  }
}

function addHatchedPoly(layerName, pts, dist, angle, curvature = 0) {
  if (!pts || pts.length < 3) return;
  addPoly(layerName, pts, curvature);
  let last = layers[layerName].polys[layers[layerName].polys.length - 1];
  if (last) {
    layers[layerName].hatches.push({
      pts: last.pts,
      dist,
      angle,
      curvature
    });
  }
}

function addLine(layerName, x1, y1, x2, y2, weight = 0.6) {
  if (Math.hypot(x2 - x1, y2 - y1) < 0.8) return;
  layers[layerName].lines.push({ x1, y1, x2, y2, weight });
}

//Emit automatic misregistration sliver & overprint quads along shared edge A->B
function emitEdgeMisregistration(A, B, layerA, layerB) {
  if (!layerA || !layerB || layerA === layerB) return;
  let offA = OFFSET[layerA] || [0, 0];
  let offB = OFFSET[layerB] || [0, 0];
  let dx = offA[0] - offB[0];
  let dy = offA[1] - offB[1];
  let d = Math.hypot(dx, dy);
  if (d < 1.2) return;

  let ex = B[0] - A[0];
  let ey = B[1] - A[1];
  let len = Math.hypot(ex, ey);
  if (len < 3) return;

  // Normal pointing left of A->B
  let nx = -ey / len;
  let ny = ex / len;
  let cross = dx * nx + dy * ny;

  let quad = [
    [A[0] + offA[0], A[1] + offA[1]],
    [B[0] + offA[0], B[1] + offB[1] * 0 + offA[1]],
    [B[0] + offB[0], B[1] + offB[1]],
    [A[0] + offB[0], A[1] + offB[1]]
  ];

  // Determine whether plates pull apart (exposing paper sliver) or overlap (forming dark overprint)
  if (cross < -1.1) {
    addPoly("PAPER_KNOCKOUT", quad, 0);
  } else if (cross > 1.1) {
    let overLayer = pickOverprintLayer(layerA, layerB);
    if (overLayer) addPoly(overLayer, quad, 0);
  }
}

function pickOverprintLayer(a, b) {
  let set = new Set([a, b]);
  if (set.has("OVERPRINT_DARK")) return "OVERPRINT_DARK";
  if (set.has("CYAN") && set.has("VERMILION")) return "OVERPRINT_DARK";
  if (set.has("CYAN") && set.has("GREY")) return "OVERPRINT_DARK";
  if (set.has("VERMILION") && set.has("GREY")) return "VERMILION_OVER";
  if (set.has("VERMILION") && set.has("MINT")) return "VERMILION_OVER";
  if (set.has("CYAN") && set.has("MINT")) return "CYAN_OVER";
  if (set.has("GREY") && set.has("MINT")) return "GREY_OVER";
  return null;
}

// ============================================================================
// TUBE COORDINATE SYSTEM & 3D DEFORMATION MODEL
// ============================================================================
// Nozzle tip at (748, 365), tube axis pointing down-left at 136.5 degrees
const NOZZLE_ORIGIN = { x: 748, y: 365 };
const AXIS_ANGLE = 136.5;

function tubeSpine(u) {
  let rad = AXIS_ANGLE * Math.PI / 180;
  let ux = Math.cos(rad);
  let uy = Math.sin(rad);
  let vx = -uy;
  let vy = ux;

  // Wrung lower-half lateral S-bend & rolled-tail kink
  let shiftV = 0;
  let compressU = u;
  if (u > 340 && u <= 600) {
    let t = (u - 340) / 260;
    shiftV = -16 * Math.sin(t * Math.PI);
  } else if (u > 600) {
    let t = (u - 600) / 145;
    // Foreshortening across the rolled fold + angular twist of the crimped tail
    compressU = 600 + (u - 600) * 0.82;
    shiftV = 18 * t;
  }

  return {
    x: NOZZLE_ORIGIN.x + compressU * ux + shiftV * vx,
    y: NOZZLE_ORIGIN.y + compressU * uy + shiftV * vy,
    ux, uy, vx, vy
  };
}

// Half-width of the tube as it flares from cylindrical shoulder to flattened crimp
function tubeHalfWidth(u) {
  if (u < 52) return 28;
  if (u < 148) {
    let t = (u - 52) / (148 - 52);
    // Slight conical curve
    return 28 + 100 * Math.pow(t, 0.92);
  }
  if (u < 360) {
    let t = (u - 148) / (360 - 148);
    // Swollen body tapering into squeezed waist
    return 128 + 14 * Math.sin(t * Math.PI * 0.85);
  }
  if (u < 600) {
    let t = (u - 360) / (600 - 360);
    // Flattening cylinder flares out toward pi/2 * R, modulated by wrung buckles
    let buckle = -7 * Math.sin(t * Math.PI * 2.5);
    return 138 + 30 * Math.pow(t, 0.85) + buckle;
  }
  // Flattened & rolled crimp tail
  let t = (u - 600) / 145;
  return 166 + 8 * t;
}

// Convert tube (u, s) where s in [-1, 1] and 3D height z into canvas [x, y]
function tubePoint(u, s, z = 0) {
  let sp = tubeSpine(u);
  let w = tubeHalfWidth(u);
  // Perspective curve across cylinder cross-section (stronger near shoulder, flatter near crimp)
  let cylArch = 0;
  if (u >= 52 && u < 580) {
    let cylFactor = u < 148 ? 1.0 : Math.max(0, 1.0 - (u - 148) / 420);
    cylArch = -22 * cylFactor * (1 - s * s);
  }
  // 3D height z projects slightly up-left (key light / camera tilt direction)
  let uProj = cylArch - z * 0.42;
  let vProj = s * w - z * 0.28;

  return [
    sp.x + uProj * sp.ux + vProj * sp.vx,
    sp.y + uProj * sp.uy + vProj * sp.vy
  ];
}

// ============================================================================
// BUILD ALL GEOMETRIC SEPARATIONS
// ============================================================================
function buildArtwork() {
  initLayers();

  buildTubeKnockoutHull();
  buildThreadedNozzle();
  buildConicalShoulder();
  buildUpperSqueezedBody();
  buildWrungFoilCreaseMesh();
  buildRolledTailAndCrimp();
  buildExtrudedPasteRibbon();
}

// 1. Base Paper Knockout Hull (ensures crisp paper slivers wherever screens separate)
function buildTubeKnockoutHull() {
  let leftEdge = [];
  let rightEdge = [];

  for (let u = 2; u <= 742; u += 12) {
    let zMod = 0;
    if (u > 350 && u < 620) {
      zMod = 6 * Math.sin((u - 350) * 0.07);
    }
    leftEdge.push(tubePoint(u, -1.01, zMod));
    rightEdge.push(tubePoint(u, 1.01, -zMod));
  }
  let hull = leftEdge.concat(rightEdge.reverse());
  addPoly("PAPER_KNOCKOUT", hull, 0);
}

// 2. Open Threaded Nozzle (u = 0 to 52)
function buildThreadedNozzle() {
  // Base cylindrical shadow/midtone planes of nozzle
  let sBands = [
    { s0: -1.00, s1: -0.68, layer: "MINT" },
    { s0: -0.68, s1: -0.22, layer: "HIGHLIGHT" },
    { s0: -0.22, s1:  0.18, layer: "GREY" },
    { s0:  0.18, s1:  0.62, layer: "CYAN" },
    { s0:  0.62, s1:  0.88, layer: "OVERPRINT_DARK" },
    { s0:  0.88, s1:  1.00, layer: "BUTTER_BOUNCE" }
  ];

  for (let b of sBands) {
    let p0 = tubePoint(4, b.s0, 4);
    let p1 = tubePoint(4, b.s1, 4);
    let p2 = tubePoint(52, b.s1, 4);
    let p3 = tubePoint(52, b.s0, 4);
    addPoly(b.layer, [p0, p1, p2, p3], 0);
  }

  // 5 Helical Screw Threads wrapping across u = 10..46
  for (let t = 0; t < 5; t++) {
    let uBase = 10 + t * 8.2;
    let steps = 10;
    let crestPtsTop = [];
    let crestPtsBot = [];
    let troughPtsBot = [];

    for (let i = 0; i <= steps; i++) {
      let s = -1.04 + (2.08 * i) / steps;
      let slantU = uBase + s * 3.2; // Helical thread slant
      let threadBulge = (1 - Math.pow(s, 4)) * 5.5 + (Math.abs(s) > 0.88 ? 4.5 : 0);
      crestPtsTop.push(tubePoint(slantU - 1.8, s, threadBulge));
      crestPtsBot.push(tubePoint(slantU + 1.4, s, threadBulge));
      troughPtsBot.push(tubePoint(slantU + 4.2, s, 1.0));
    }

    // Split thread into Highlight (left/upper), Mint/Grey (center), Cyan/Dark (right)
    let sliceThread = (i0, i1, crestLayer, troughLayer) => {
      let cPoly = [];
      let tPoly = [];
      for (let i = i0; i <= i1; i++) cPoly.push(crestPtsTop[i]);
      for (let i = i1; i >= i0; i--) cPoly.push(crestPtsBot[i]);
      addPoly(crestLayer, cPoly, 0);

      for (let i = i0; i <= i1; i++) tPoly.push(crestPtsBot[i]);
      for (let i = i1; i >= i0; i--) tPoly.push(troughPtsBot[i]);
      addPoly(troughLayer, tPoly, 0);
      emitEdgeMisregistration(crestPtsBot[i0], crestPtsBot[i1], crestLayer, troughLayer);
    };

    sliceThread(0, 4, "HIGHLIGHT", "CYAN");
    sliceThread(4, 6, "MINT", "CYAN");
    sliceThread(6, 8, "GREY", "OVERPRINT_DARK");
    sliceThread(8, 10, "CYAN", "OVERPRINT_DARK");
  }

  // Open Nozzle Lip & Dark Mouth Cavity at u = 0..6
  let lipOuter = [];
  let lipInner = [];
  for (let i = 0; i <= 16; i++) {
    let ang = (i / 16) * Math.PI * 2;
    let s = Math.cos(ang);
    let uOff = 3 + Math.sin(ang) * 5.5;
    lipOuter.push(tubePoint(uOff, s * 1.02, 5));
    lipInner.push(tubePoint(uOff, s * 0.76, 4));
  }
  addPoly("HIGHLIGHT", lipOuter, 0.2);
  addPoly("OVERPRINT_DARK", lipInner, 0.2);
}

// 3. Conical Spun-Aluminum Shoulder (u = 52 to 148)
function buildConicalShoulder() {
  // Radial metallic reflection wedges on the conical shoulder
  let sectors = [
    { s0: -1.00, s1: -0.84, lTop: "GREY",           lMid: "MINT",           lBot: "GREY",           hatch: false },
    { s0: -0.84, s1: -0.46, lTop: "HIGHLIGHT",      lMid: "HIGHLIGHT",      lBot: "HIGHLIGHT",      hatch: false },
    { s0: -0.46, s1: -0.22, lTop: "MINT",           lMid: "HIGHLIGHT",      lBot: "MINT",           hatch: true,  ang: 105 },
    { s0: -0.22, s1: -0.02, lTop: "GREY",           lMid: "GREY",           lBot: "MINT",           hatch: true,  ang: 45 },
    { s0: -0.02, s1:  0.10, lTop: "HIGHLIGHT",      lMid: "VERMILION",      lBot: "HIGHLIGHT",      hatch: false },
    { s0:  0.10, s1:  0.24, lTop: "GREY",           lMid: "CYAN",           lBot: "GREY",           hatch: false },
    { s0:  0.24, s1:  0.54, lTop: "CYAN",           lMid: "CYAN",           lBot: "CYAN",           hatch: true,  ang: 15 },
    { s0:  0.54, s1:  0.78, lTop: "OVERPRINT_DARK", lMid: "OVERPRINT_DARK", lBot: "CYAN",           hatch: false },
    { s0:  0.78, s1:  0.91, lTop: "GREY",           lMid: "MINT",           lBot: "MINT",           hatch: false },
    { s0:  0.91, s1:  1.00, lTop: "BUTTER_BOUNCE",  lMid: "BUTTER_BOUNCE",  lBot: "HIGHLIGHT",      hatch: false }
  ];

  let uRings = [52, 82, 116, 148];

  for (let sec of sectors) {
    for (let r = 0; r < 3; r++) {
      let u0 = uRings[r];
      let u1 = uRings[r + 1];
      let layer = r === 0 ? sec.lTop : (r === 1 ? sec.lMid : sec.lBot);

      // Subtle锯齿 (lathe-ring step) along sector boundaries for spun-metal realism
      let jitter0 = (r === 1) ? 0.025 : 0;
      let s0a = Math.max(-1, sec.s0 + jitter0);
      let s1a = Math.min(1, sec.s1 + jitter0);

      let poly = [
        tubePoint(u0, s0a, 6),
        tubePoint(u0, (s0a + s1a) * 0.5, 7),
        tubePoint(u0, s1a, 6),
        tubePoint(u1, s1a, 7),
        tubePoint(u1, (s0a + s1a) * 0.5, 8),
        tubePoint(u1, s0a, 7)
      ];

      if (sec.hatch && r === 1) {
        addHatchedPoly(layer, poly, 5.5, sec.ang, 0);
      } else {
        addPoly(layer, poly, 0);
      }

      emitEdgeMisregistration(poly[2], poly[3], layer, "CYAN");
    }
  }

  // Concentric lathe-turned specular glints across the shoulder cone
  for (let uLathe of [68, 96, 126, 145]) {
    let pA = tubePoint(uLathe - 1.5, -0.82, 8);
    let pB = tubePoint(uLathe - 1.5, 0.12, 8);
    let pC = tubePoint(uLathe + 1.8, 0.12, 8);
    let pD = tubePoint(uLathe + 1.8, -0.82, 8);
    addPoly("HIGHLIGHT", [pA, pB, pC, pD], 0);
  }

  // Rolled Shoulder Seam Collar at u = 146..154
  let seamSegs = [
    { s0: -1.02, s1: -0.35, top: "HIGHLIGHT", bot: "CYAN" },
    { s0: -0.35, s1:  0.22, top: "MINT",      bot: "OVERPRINT_DARK" },
    { s0:  0.22, s1:  0.78, top: "GREY",      bot: "OVERPRINT_DARK" },
    { s0:  0.78, s1:  1.02, top: "HIGHLIGHT", bot: "CYAN" }
  ];
  for (let sg of seamSegs) {
    let steps = 5;
    let topStrip = [];
    let midStrip = [];
    let botStrip = [];
    for (let i = 0; i <= steps; i++) {
      let s = sg.s0 + ((sg.s1 - sg.s0) * i) / steps;
      topStrip.push(tubePoint(145, s, 9));
      midStrip.push(tubePoint(149.5, s, 10));
      botStrip.push(tubePoint(153.5, s, 5));
    }
    addPoly(sg.top, topStrip.concat([...midStrip].reverse()), 0);
    addPoly(sg.bot, midStrip.concat([...botStrip].reverse()), 0);
    emitEdgeMisregistration(midStrip[0], midStrip[steps], sg.top, sg.bot);
  }
}

// 4. Upper Squeezed Foil Body, Concave Thumb-Dent & Warped Branding (u = 153 to 360)
function buildUpperSqueezedBody() {
  // Define height field z(u, s) for the upper body with a realistic thumb-squeeze depression
  let upperZ = (u, s) => {
    // Base cylindrical bulge
    let base = 18 * Math.sqrt(Math.max(0, 1 - s * s));
    // Concave thumb-dent centered at (u = 278, s = -0.08)
    let du = (u - 278) / 62;
    let ds = (s + 0.08) / 0.48;
    let r2 = du * du + ds * ds;
    let dent = r2 < 1.3 ? -26 * Math.pow(Math.max(0, 1 - r2 / 1.3), 1.6) : 0;
    // Sharp ridge rim around the thumb-dent
    let rim = (r2 > 0.7 && r2 < 1.35) ? 9 * Math.sin(((r2 - 0.7) / 0.65) * Math.PI) : 0;
    return base + dent + rim;
  };

  // A. The Graphic Brand Collar (u = 154 to 238)
  // Includes: Foil gap (154..164), Wide Warm Vermilion Band (164..216), Paper gap (216..224), Process Cyan Stripe (224..236)
  let collarRows = [
    { u0: 153, u1: 164, type: "FOIL" },
    { u0: 164, u1: 215, type: "VERMILION_BAND" },
    { u0: 215, u1: 224, type: "PAPER_STRIPE" },
    { u0: 224, u1: 237, type: "CYAN_STRIPE" }
  ];

  let sCols = [-1.00, -0.82, -0.44, -0.16, 0.08, 0.34, 0.68, 0.88, 1.00];

  for (let row of collarRows) {
    for (let c = 0; c < sCols.length - 1; c++) {
      let s0 = sCols[c];
      let s1 = sCols[c + 1];
      let sMid = 0.5 * (s0 + s1);

      // Kink the collar downward across the incipient thumb-dent ridge around s in [-0.2, 0.3]
      let kink0 = (s0 > -0.3 && s0 < 0.4) ? 8 * (1 - Math.abs(s0 - 0.05) / 0.35) : 0;
      let kink1 = (s1 > -0.3 && s1 < 0.4) ? 8 * (1 - Math.abs(s1 - 0.05) / 0.35) : 0;

      let p0 = tubePoint(row.u0 + kink0, s0, upperZ(row.u0, s0));
      let p1 = tubePoint(row.u0 + kink1, s1, upperZ(row.u0, s1));
      let p2 = tubePoint(row.u1 + kink1, s1, upperZ(row.u1, s1));
      let p3 = tubePoint(row.u1 + kink0, s0, upperZ(row.u1, s0));
      let poly = [p0, p1, p2, p3];

      let layer = "MINT";
      let doHatch = false;
      let hAngle = 45;

      if (row.type === "FOIL") {
        if (sMid < -0.80) layer = "GREY";
        else if (sMid < -0.40) layer = "HIGHLIGHT";
        else if (sMid < -0.10) layer = "MINT";
        else if (sMid < 0.15) layer = "GREY";
        else if (sMid < 0.65) layer = "CYAN";
        else if (sMid < 0.86) layer = "OVERPRINT_DARK";
        else layer = "BUTTER_BOUNCE";
      } else if (row.type === "VERMILION_BAND") {
        if (sMid > -0.78 && sMid < -0.46) {
          // Intense specular foil reflection bleaching the vermilion ink
          layer = "HIGHLIGHT";
        } else if (sMid >= 0.40 && sMid < 0.85) {
          layer = "VERMILION_OVER";
          doHatch = true;
          hAngle = 75;
        } else {
          layer = "VERMILION";
        }
      } else if (row.type === "PAPER_STRIPE") {
        if (sMid < -0.10) layer = "HIGHLIGHT";
        else if (sMid < 0.35) layer = "MINT";
        else if (sMid < 0.85) layer = "GREY";
        else layer = "BUTTER_BOUNCE";
      } else if (row.type === "CYAN_STRIPE") {
        if (sMid > -0.75 && sMid < -0.45) layer = "MINT";
        else if (sMid >= 0.38 && sMid < 0.86) layer = "OVERPRINT_DARK";
        else layer = "CYAN";
      }

      if (doHatch) {
        addHatchedPoly(layer, poly, 5.0, hAngle, 0);
      } else {
        addPoly(layer, poly, 0);
      }
      emitEdgeMisregistration(p1, p2, layer, "CYAN");
      emitEdgeMisregistration(p3, p2, layer, "VERMILION");
    }
  }

  // Diagonal specular slash cutting across the Vermilion collar
  addPoly("HIGHLIGHT", [
    tubePoint(164, -0.76, 16),
    tubePoint(164, -0.50, 17),
    tubePoint(215, -0.36, 17),
    tubePoint(215, -0.64, 16)
  ], 0);

  // B. Faceted Thumb-Dent Zone (u = 237 to 360)
  let uGrid = [237, 266, 298, 330, 360];
  let sGrid = [-1.00, -0.82, -0.52, -0.22, 0.06, 0.36, 0.68, 0.88, 1.00];

  for (let r = 0; r < uGrid.length - 1; r++) {
    for (let c = 0; c < sGrid.length - 1; c++) {
      let u0 = uGrid[r], u1 = uGrid[r + 1];
      let s0 = sGrid[c], s1 = sGrid[c + 1];

      // Warp grid nodes slightly to follow the concave thumb-dent rim
      let warp = (u, s) => {
        let du = u - 282;
        let ds = s + 0.06;
        let d = Math.hypot(du / 55, ds / 0.45);
        let uShift = (d < 1.2) ? 7 * Math.sin(d * Math.PI) * Math.sign(du || 1) : 0;
        let sShift = (d < 1.2) ? 0.04 * Math.sin(d * Math.PI) * Math.sign(ds || 1) : 0;
        return [u + uShift, Math.max(-1, Math.min(1, s + sShift))];
      };

      let [ua, sa] = warp(u0, s0);
      let [ub, sb] = warp(u0, s1);
      let [uc, sc] = warp(u1, s1);
      let [ud, sd] = warp(u1, s0);

      let za = upperZ(ua, sa);
      let zb = upperZ(ub, sb);
      let zc = upperZ(uc, sc);
      let zd = upperZ(ud, sd);

      let pa = tubePoint(ua, sa, za);
      let pb = tubePoint(ub, sb, zb);
      let pc = tubePoint(uc, sc, zc);
      let pd = tubePoint(ud, sd, zd);

      // Triangulate each quad into 2 metallic facets and slice each into internal reflection bands
      let diagFlip = ((r + c) % 2 === 0);
      if (diagFlip) {
        renderMetallicFacet(pa, pb, pc, [ua, sa, za], [ub, sb, zb], [uc, sc, zc]);
        renderMetallicFacet(pa, pc, pd, [ua, sa, za], [uc, sc, zc], [ud, sd, zd]);
      } else {
        renderMetallicFacet(pa, pb, pd, [ua, sa, za], [ub, sb, zb], [ud, sd, zd]);
        renderMetallicFacet(pb, pc, pd, [ub, sb, zb], [uc, sc, zc], [ud, sd, zd]);
      }
    }
  }

  // C. Buckled Graphic Typography & Pharmacy Cross printed on Upper Body (u = 250..348)
  buildBuckledTypography(upperZ);
}

// Render a single 3D metallic foil triangle as multi-banded graphic screenprint separations
function renderMetallicFacet(pA, pB, pC, vA, vB, vC) {
  // Compute 3D surface normal from (u, s*140, z)
  let ax = vB[0] - vA[0], ay = (vB[1] - vA[1]) * 145, az = vB[2] - vA[2];
  let bx = vC[0] - vA[0], by = (vC[1] - vA[1]) * 145, bz = vC[2] - vA[2];
  let nx = ay * bz - az * by;
  let ny = az * bx - ax * bz;
  let nz = ax * by - ay * bx;
  let nLen = Math.hypot(nx, ny, nz) || 1;
  nx /= nLen; ny /= nLen; nz /= nLen;
  if (nz < 0) { nx = -nx; ny = -ny; nz = -nz; }

  // Key light from upper-left (-0.45, -0.62, 0.64)
  let lightDot = nx * (-0.45) + ny * (-0.62) + nz * 0.64;
  let sAvg = (vA[1] + vB[1] + vC[1]) / 3;
  let uAvg = (vA[0] + vB[0] + vC[0]) / 3;

  // Determine primary, secondary (reflection band), and ridge bevel separations
  let primary = "MINT";
  let band = "HIGHLIGHT";
  let ridge = "HIGHLIGHT";
  let doHatch = false;
  let hatchAngle = 45;

  if (sAvg > 0.84) {
    primary = "BUTTER_BOUNCE";
    band = "MINT";
    ridge = "HIGHLIGHT";
  } else if (lightDot > 0.72) {
    primary = "HIGHLIGHT";
    band = "MINT";
    ridge = "HIGHLIGHT";
  } else if (lightDot > 0.48) {
    primary = "MINT";
    band = "HIGHLIGHT";
    ridge = "HIGHLIGHT";
    doHatch = (uAvg > 360 && ((Math.floor(uAvg) + Math.floor(sAvg * 10)) % 3 === 0));
    hatchAngle = 105;
  } else if (lightDot > 0.22) {
    primary = "GREY";
    band = (sAvg < 0) ? "MINT" : "CYAN";
    ridge = "HIGHLIGHT";
    doHatch = true;
    hatchAngle = 45;
  } else if (lightDot > -0.06) {
    primary = "CYAN";
    band = "GREY";
    ridge = "MINT";
    doHatch = (sAvg < 0.4);
    hatchAngle = 15;
  } else {
    primary = "OVERPRINT_DARK";
    band = "CYAN";
    ridge = "GREY";
  }

  // Warm Vermilion bounce reflection in steep facets near the collar or central creases
  if (uAvg < 440 && Math.abs(nx) > 0.38 && sAvg > -0.35 && sAvg < 0.35) {
    band = "VERMILION";
  }

  // Subdivide triangle into:
  // 1) Outer base triangle (primary separation)
  // 2) Sliced interior reflection band (band separation)
  // 3) Crisp crease-ridge bevel along edge AB (ridge separation)
  if (doHatch) {
    addHatchedPoly(primary, [pA, pB, pC], 5.5, hatchAngle, 0);
  } else {
    addPoly(primary, [pA, pB, pC], 0);
  }

  // Interior metallic reflection band cutting across the facet
  let lerpPt = (P, Q, t) => [P[0] + (Q[0] - P[0]) * t, P[1] + (Q[1] - P[1]) * t];
  let b1 = lerpPt(pA, pC, 0.28);
  let b2 = lerpPt(pB, pC, 0.28);
  let b3 = lerpPt(pB, pC, 0.64);
  let b4 = lerpPt(pA, pC, 0.64);
  addPoly(band, [b1, b2, b3, b4], 0);

  // Sharp ridge highlight bevel along the upper edge
  if (vA[2] + vB[2] > 8 || lightDot > 0.35) {
    let r1 = lerpPt(pA, pC, 0.14);
    let r2 = lerpPt(pB, pC, 0.14);
    addPoly(ridge, [pA, pB, r2, r1], 0);
  }

  emitEdgeMisregistration(pA, pB, primary, band);
}

// Warped Pharmacy Cross & Bold Sans-Serif Letterforms ("M I N T") on the squeezed upper body
function buildBuckledTypography(zFn) {
  let mapRect = (u0, u1, s0, s1, layer) => {
    let pts = [
      tubePoint(u0, s0, zFn(u0, s0) + 1.5),
      tubePoint(u0, 0.5 * (s0 + s1), zFn(u0, 0.5 * (s0 + s1)) + 1.5),
      tubePoint(u0, s1, zFn(u0, s1) + 1.5),
      tubePoint(u1, s1, zFn(u1, s1) + 1.5),
      tubePoint(u1, 0.5 * (s0 + s1), zFn(u1, 0.5 * (s0 + s1)) + 1.5),
      tubePoint(u1, s0, zFn(u1, s0) + 1.5)
    ];
    addPoly(layer, pts, 0);
  };

  // Apothecary Cross emblem on upper-left of label (u = 252..286, s = -0.68..-0.36)
  mapRect(252, 286, -0.57, -0.47, "VERMILION");
  mapRect(263, 275, -0.68, -0.36, "VERMILION");
  // Specular foil highlight slicing across the corner of the cross
  mapRect(252, 268, -0.59, -0.52, "HIGHLIGHT");

  // Bold geometric block letters "M  I  N  T" buckled across the thumb-dent (u = 252..294)
  // Letter 'M' (s = -0.26 .. -0.02)
  mapRect(252, 292, -0.26, -0.20, "CYAN");
  mapRect(252, 292, -0.08, -0.02, "CYAN");
  addPoly("CYAN", [
    tubePoint(252, -0.22, zFn(252, -0.22) + 2),
    tubePoint(252, -0.17, zFn(252, -0.17) + 2),
    tubePoint(276, -0.13, zFn(276, -0.13) + 2),
