  ], 0);
  addPoly("CYAN", [
    tubePoint(252, -0.11, zFn(252, -0.11) + 2),
    tubePoint(252, -0.06, zFn(252, -0.06) + 2),
    tubePoint(276, -0.13, zFn(276, -0.13) + 2),
    tubePoint(276, -0.16, zFn(276, -0.16) + 2)
  ], 0);

  // Letter 'I' (s = 0.04 .. 0.11)
  mapRect(252, 292, 0.04, 0.11, "CYAN");

  // Letter 'N' (s = 0.17 .. 0.39)
  mapRect(252, 292, 0.17, 0.23, "CYAN");
  mapRect(252, 292, 0.33, 0.39, "OVERPRINT_DARK");
  addPoly("CYAN", [
    tubePoint(252, 0.21, zFn(252, 0.21) + 2),
    tubePoint(252, 0.26, zFn(252, 0.26) + 2),
    tubePoint(292, 0.35, zFn(292, 0.35) + 2),
    tubePoint(292, 0.30, zFn(292, 0.30) + 2)
  ], 0);

  // Letter 'T' (s = 0.45 .. 0.67)
  mapRect(252, 261, 0.45, 0.67, "OVERPRINT_DARK");
