  // Secondary graphic specification bars below typography (u = 308..342)
  mapRect(308, 315, -0.66, 0.32, "VERMILION");
  mapRect(322, 327, -0.66, 0.14, "CYAN");
  mapRect(334, 339, -0.52, 0.48, "GREY");
  // Foil ridge highlight cutting across the specification bars
  mapRect(306, 341, -0.46, -0.34, "HIGHLIGHT");
}

// 5. Wrung, Flattened & Deeply Creased Foil Mid-Lower Body (u = 358 to 605)
function buildWrungFoilCreaseMesh() {
  // Hand-crafted 9x8 crease vertex lattice with deep Yoshimura diamond folds & diagonal wringing ridges
  const uRows = [358, 390, 424, 458, 492, 526, 558, 584, 606];
  const sBase = [-1.00, -0.76, -0.44, -0.12, 0.18, 0.48, 0.78, 1.00];

  // Explicit 3D height z (positive = sharp ridge crest, negative = deep pinched valley trough)
  const zTable = [
    [ -6,  18,  26, -12,  14,  22,  -8, -14], // r=0 (u=358)
    [-14,  28,  -8,  24, -18,  26,  12, -18], // r=1 (u=390) - Diagonal ridge 1 starts
    [ 16, -16,  32,  -6,  28, -16,  22,  -8], // r=2 (u=424) - Deep diamond buckle
    [-18,  24, -22,  34, -12,  28, -14,  14], // r=3 (u=458) - Major central wringing ridge
    [ 14, -12,  28, -24,  32,  -8,  24, -16], // r=4 (u=492) - Counter-torsion valley
    [-12,  30, -16,  26, -20,  30, -12,  12], // r=5 (u=526) - Lower diamond crest
    [ 18, -18,  24, -14,  26, -16,  20, -14], // r=6 (u=558) - Pre-roll pinch trough
    [-16,  12, -22, -18, -24, -14, -18, -20], // r=7 (u=584) - Deep shadow cliff under Roll 1
    [ 22,  34,  30,  36,  28,  32,  26,  18]  // r=8 (u=606) - Crest of Roll 1 knuckle
  ];

  // Build deformed 3D node grid
  let nodes = [];
  for (let r = 0; r < uRows.length; r++) {
    let rowNodes = [];
    for (let c = 0; c < sBase.length; c++) {
      let u = uRows[r];
      let s = sBase[c];
      let z = zTable[r][c];

      // Lateral accordion gusset teeth at the outer edges (c === 0 and c === 7)
      if (c === 0) {
        s = -1.00 + ((r % 2 === 0) ? -0.05 : 0.04);
      } else if (c === sBase.length - 1) {
        s = 1.00 + ((r % 2 === 0) ? 0.05 : -0.04);
      } else {
        // Interior crease vertices pinch toward high ridges
        s += 0.04 * Math.sin(r * 1.7 + c * 2.1);
        u += 6.5 * Math.cos(r * 2.3 - c * 1.5);
      }

      let pt = tubePoint(u, s, z);
      rowNodes.push({ pt, vec: [u, s, z] });
    }
    nodes.push(rowNodes);
  }

  // Render all triangulated foil facets in the wrung mesh
  for (let r = 0; r < uRows.length - 1; r++) {
    for (let c = 0; c < sBase.length - 1; c++) {
      let nA = nodes[r][c];
      let nB = nodes[r][c + 1];
      let nC = nodes[r + 1][c + 1];
      let nD = nodes[r + 1][c];

      // Choose diagonal that aligns with the physical diagonal wringing ridges
      let useAC = ((r + c) % 2 === 0);
      if (useAC) {
        renderMetallicFacet(nA.pt, nB.pt, nC.pt, nA.vec, nB.vec, nC.vec);
        renderMetallicFacet(nA.pt, nC.pt, nD.pt, nA.vec, nC.vec, nD.vec);
        // Emphasize sharp diagonal ridge or valley along AC
        drawCreaseSeam(nA, nC);
      } else {
        renderMetallicFacet(nA.pt, nB.pt, nD.pt, nA.vec, nB.vec, nD.vec);
        renderMetallicFacet(nB.pt, nC.pt, nD.pt, nB.vec, nC.vec, nD.vec);
        drawCreaseSeam(nB, nD);
      }
      // Horizontal/transverse buckle seams
      if (r >= 2 && r <= 7) {
        drawCreaseSeam(nA, nB);
      }
    }

    // Side-gusset thickness strips along left (c=0) and right (c=last) silhouettes
    let leftTop = nodes[r][0];
    let leftBot = nodes[r + 1][0];
    let gLeftA = tubePoint(leftTop.vec[0] + 4, leftTop.vec[1] - 0.07, leftTop.vec[2] - 10);
    let gLeftB = tubePoint(leftBot.vec[0] + 4, leftBot.vec[1] - 0.07, leftBot.vec[2] - 10);
    addPoly((r % 2 === 0) ? "HIGHLIGHT" : "CYAN", [leftTop.pt, leftBot.pt, gLeftB, gLeftA], 0);

    let rightTop = nodes[r][sBase.length - 1];
    let rightBot = nodes[r + 1][sBase.length - 1];
    let gRightA = tubePoint(rightTop.vec[0] + 4, rightTop.vec[1] + 0.07, rightTop.vec[2] - 10);
    let gRightB = tubePoint(rightBot.vec[0] + 4, rightBot.vec[1] + 0.07, rightBot.vec[2] - 10);
    addPoly((r % 2 === 0) ? "OVERPRINT_DARK" : "BUTTER_BOUNCE", [rightTop.pt, rightBot.pt, gRightB, gRightA], 0);
  }

  // Printed red & cyan label stripes buckling down the right flank of the wrung zone
  for (let r = 0; r < uRows.length - 2; r++) {
    let n1 = nodes[r][5];
    let n2 = nodes[r + 1][5];
    let pA = n1.pt;
    let pB = [n1.pt[0] + 12, n1.pt[1] + 8];
    let pC = [n2.pt[0] + 12, n2.pt[1] + 8];
    let pD = n2.pt;
    addPoly((r % 2 === 0) ? "VERMILION" : "VERMILION_OVER", [pA, pB, pC, pD], 0);
  }
}

// Crisp knife-edge highlight bevels and deep valley shadow wedges along major foil creases
function drawCreaseSeam(n1, n2) {
  let zAvg = 0.5 * (n1.vec[2] + n2.vec[2]);
  let dx = n2.pt[0] - n1.pt[0];
  let dy = n2.pt[1] - n1.pt[1];
  let len = Math.hypot(dx, dy);
  if (len < 6) return;
  let nx = -dy / len;
  let ny = dx / len;

  if (zAvg > 12) {
    // Convex ridge: razor-sharp Paper Highlight crest flanked by a thin Cyan contrast shadow
    let w = 4.8;
    let hPoly = [
      n1.pt,
      n2.pt,
      [n2.pt[0] + nx * w, n2.pt[1] + ny * w],
      [n1.pt[0] + nx * w, n1.pt[1] + ny * w]
    ];
    let sPoly = [
      n1.pt,
      n2.pt,
      [n2.pt[0] - nx * (w * 0.85), n2.pt[1] - ny * (w * 0.85)],
      [n1.pt[0] - nx * (w * 0.85), n1.pt[1] - ny * (w * 0.85)]
    ];
    addPoly("HIGHLIGHT", hPoly, 0);
    addPoly("CYAN", sPoly, 0);
  } else if (zAvg < -8) {
    // Concave pinch trough: sharp Overprint Dark core inside a Process Cyan valley
    let w = 5.2;
    let dPoly = [
      [n1.pt[0] - nx * w, n1.pt[1] - ny * w],
      [n2.pt[0] - nx * w * 0.6, n2.pt[1] - ny * w * 0.6],
      [n2.pt[0] + nx * w * 0.6, n2.pt[1] + ny * w * 0.6],
      [n1.pt[0] + nx * w, n1.pt[1] + ny * w]
    ];
    addPoly("OVERPRINT_DARK", dPoly, 0);
  }
}

// 6. Rolled Bottom Folds, Factory Eye-Mark & Serrated Crimp Seal (u = 600 to 742)
function buildRolledTailAndCrimp() {
  let sSteps = [-1.02, -0.78, -0.50, -0.22, 0.06, 0.34, 0.62, 0.84, 1.02];

  // A. First Rolled Knuckle (u = 600..646)
  for (let i = 0; i < sSteps.length - 1; i++) {
    let s0 = sSteps[i];
    let s1 = sSteps[i + 1];
    let z0 = 28 + 8 * Math.sin(i * 1.9);
    let z1 = 28 + 8 * Math.sin((i + 1) * 1.9);

    // Upper highlight knuckle of the roll
    let k0 = tubePoint(600, s0, z0);
    let k1 = tubePoint(600, s1, z1);
    let k2 = tubePoint(622, s1, z1 + 6);
    let k3 = tubePoint(622, s0, z0 + 6);
    let kLayer = (i % 2 === 0) ? "HIGHLIGHT" : (i < 5 ? "MINT" : "GREY");
    addPoly(kLayer, [k0, k1, k2, k3], 0);

    // Under-turn of the roll casting a deep shadow onto the tail flap
    let u0 = tubePoint(622, s0, z0 + 6);
    let u1 = tubePoint(622, s1, z1 + 6);
    let u2 = tubePoint(646, s1, -8);
    let u3 = tubePoint(646, s0, -8);
    let uLayer = (i % 3 === 0) ? "OVERPRINT_DARK" : "CYAN";
    addPoly(uLayer, [u0, u1, u2, u3], 0);
    emitEdgeMisregistration(k3, k2, kLayer, uLayer);
  }

  // B. Flattened Tail Apron (u = 646..696) + Factory Registration Eye-Mark
  for (let i = 0; i < sSteps.length - 1; i++) {
    let s0 = sSteps[i];
    let s1 = sSteps[i + 1];
    let zApron = (i % 2 === 0) ? 6 : -4;

    let a0 = tubePoint(646, s0, -4);
    let a1 = tubePoint(646, s1, -4);
    let a2 = tubePoint(696, s1, zApron);
    let a3 = tubePoint(696, s0, zApron);

    let aLayer = "MINT";
    if (i === 1 || i === 4) aLayer = "HIGHLIGHT";
    else if (i === 3 || i === 5) aLayer = "GREY";
    else if (i >= 6) aLayer = "CYAN";

    if (aLayer === "GREY") {
      addHatchedPoly(aLayer, [a0, a1, a2, a3], 5.0, 45, 0);
    } else {
      addPoly(aLayer, [a0, a1, a2, a3], 0);
    }
  }

  // Iconic Factory Eye-Mark (solid Vermilion + Cyan registration block at center of tail, u = 654..692)
  addPoly("VERMILION", [
    tubePoint(654, -0.16, 6),
    tubePoint(654,  0.14, 6),
    tubePoint(692,  0.14, 6),
    tubePoint(692, -0.16, 6)
  ], 0);
  addPoly("CYAN", [
    tubePoint(654, 0.14, 6),
    tubePoint(654, 0.24, 6),
    tubePoint(692, 0.24, 6),
    tubePoint(692, 0.14, 6)
  ], 0);
  // Foil crease glint cutting across the factory eye-mark
  addPoly("HIGHLIGHT", [
    tubePoint(654, -0.05, 8),
    tubePoint(654,  0.02, 8),
    tubePoint(692,  0.06, 8),
    tubePoint(692, -0.01, 8)
  ], 0);

  // C. Serrated Crimped End Seal (u = 696..742) with 30 metallic waffle ribs
  const numRibs = 30;
  for (let i = 0; i < numRibs; i++) {
    let s0 = -1.02 + (2.04 * i) / numRibs;
    let s1 = -1.02 + (2.04 * (i + 1)) / numRibs;
    let ribZ = (i % 2 === 0) ? 7 : 1;

    let r0 = tubePoint(696, s0, ribZ);
    let r1 = tubePoint(696, s1, ribZ);
    let r2 = tubePoint(740, s1, ribZ);
    let r3 = tubePoint(740, s0, ribZ);

    let ribLayer;
    if (i % 4 === 0) ribLayer = "HIGHLIGHT";
    else if (i % 4 === 1) ribLayer = "MINT";
    else if (i % 4 === 2) ribLayer = "GREY";
    else ribLayer = (i > 18) ? "OVERPRINT_DARK" : "CYAN";

    addPoly(ribLayer, [r0, r1, r2, r3], 0);
  }

  // Crisp shadow bevel along top of crimp (u = 694..699) and bottom cut edge (u = 739..744)
  addPoly("CYAN", [
    tubePoint(694, -1.02, 4),
    tubePoint(694,  1.02, 4),
    tubePoint(699,  1.02, 4),
    tubePoint(699, -1.02, 4)
  ], 0);
  addPoly("OVERPRINT_DARK", [
    tubePoint(739, -1.02, 2),
    tubePoint(739,  1.02, 2),
    tubePoint(744,  1.02, 2),
    tubePoint(744, -1.02, 2)
  ], 0);
}

// 7. Extruded Curling Ribbon of Striped Toothpaste
function buildExtrudedPasteRibbon() {
  // Smooth S-curve control spine emerging from the nozzle mouth at (746, 368)
  const ctrl = [
    [744, 370], // Inside nozzle mouth
    [762, 346], // Exiting mouth
    [822, 286], // Rising arch
    [918, 262], // Upper crest
    [996, 326], // Right outer loop
    [972, 438], // Sweeping back left
    [882, 518], // Inner waist of S-curve
    [882, 622], // Lower curve turning right
    [968, 682], // Lower belly
    [1048, 642],// Flicked-up tapered tip
    [1066, 616] // Pointed tangent guide
  ];

  // Catmull-Rom spline evaluation along N = 72 steps
  const N = 72;
  let spine = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let seg = t * (ctrl.length - 3);
    let idx = Math.min(ctrl.length - 4, Math.floor(seg));
    let lt = seg - idx;

    let p0 = ctrl[idx];
    let p1 = ctrl[idx + 1];
    let p2 = ctrl[idx + 2];
    let p3 = ctrl[idx + 3];

    let lt2 = lt * lt;
    let lt3 = lt2 * lt;

    let x = 0.5 * (
      (2 * p1[0]) +
      (-p0[0] + p2[0]) * lt +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * lt2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * lt3
    );
    let y = 0.5 * (
      (2 * p1[1]) +
      (-p0[1] + p2[1]) * lt +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * lt2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * lt3
    );

    // Radius profile: matches nozzle mouth (23px), swells to plump 31px in bends, tapers to curly tip (1.5px)
    let rad;
    if (t < 0.08) {
      rad = 22 + 9 * (t / 0.08);
    } else if (t < 0.78) {
      rad = 30.5 + 3.2 * Math.sin((t - 0.08) * Math.PI * 3.2);
    } else {
      let tt = (t - 0.78) / 0.22;
      rad = 29 * Math.pow(1 - tt, 1.45) + 1.5;
    }

    spine.push({ x, y, r: rad, t });
  }

  // Compute smooth normals along the paste spine
  for (let i = 0; i <= N; i++) {
    let prev = spine[Math.max(0, i - 1)];
    let next = spine[Math.min(N, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let len = Math.hypot(dx, dy) || 1;
    spine[i].nx = -dy / len;
    spine[i].ny = dx / len;
  }

  // Helper to get point on ribbon at spine index i and cross-section s in [-1, 1]
  let pastePt = (i, s) => {
    let sp = spine[i];
    // Subtle 3D helical twist of the stripes as the ribbon curls in space
    return [sp.x + sp.nx * sp.r * s, sp.y + sp.ny * sp.r * s];
  };

  // A. Full Paper Knockout Silhouette for the Paste Ribbon
  let leftSil = [];
  let rightSil = [];
  for (let i = 0; i <= N; i++) {
    leftSil.push(pastePt(i, -1.03));
    rightSil.push(pastePt(i, 1.03));
  }
  addPoly("PAPER_KNOCKOUT", leftSil.concat(rightSil.reverse()), 0);

  // B. Helical Striped Toothpaste Separations across chunks of the ribbon
  // A classic 3-stripe paste (Signal/Aquafresh style):
  // - Glossy Paper White upper highlight ridge
  // - Bold Warm Vermilion stripe (with internal wet white glint & dark overprint shadow edge)
  // - Creamy Paper White / Mint central body
  // - Process Mint & Process Cyan lower aqua stripe
  // - Dusky Mid-Grey / Overprint Dark core shadow + Butter-Yellow bottom bounce rim
  let chunkSize = 4;
  for (let i0 = 0; i0 < N; i0 += chunkSize) {
    let i1 = Math.min(N, i0 + chunkSize);
    let tMid = spine[Math.floor(0.5 * (i0 + i1))].t;

    // Helical twist shifts the stripes smoothly across the cross-section s
    let twist = (i) => 0.16 * Math.sin((i / N) * Math.PI * 3.1 - 0.3);

    let buildBand = (sStartFn, sEndFn, layer, doHatch = false, hAng = 45) => {
      let topPts = [];
      let botPts = [];
      for (let i = i0; i <= i1; i++) {
        topPts.push(pastePt(i, Math.max(-1, Math.min(1, sStartFn(i)))));
        botPts.push(pastePt(i, Math.max(-1, Math.min(1, sEndFn(i)))));
      }
      let poly = topPts.concat(botPts.reverse());
      if (doHatch) {
        addHatchedPoly(layer, poly, 5.0, hAng, 0);
      } else {
        addPoly(layer, poly, 0);
      }
      emitEdgeMisregistration(topPts[0], topPts[topPts.length - 1], layer, "PAPER_KNOCKOUT");
    };

    // 1. Upper contour rim (Mint or Highlight depending on curve orientation)
    let upperRimLayer = (tMid > 0.34 && tMid < 0.62) ? "MINT" : "HIGHLIGHT";
    buildBand(i => -1.00, i => -0.78 + twist(i) * 0.3, upperRimLayer);

    // 2. Warm Vermilion Stripe
    buildBand(i => -0.78 + twist(i) * 0.3, i => -0.26 + twist(i), "VERMILION");

    // Wet specular Paper White glint running inside the Vermilion stripe on upward-facing arches
    if (tMid < 0.34 || (tMid > 0.60 && tMid < 0.90)) {
      buildBand(i => -0.60 + twist(i) * 0.6, i => -0.46 + twist(i) * 0.6, "HIGHLIGHT");
    }
    // Overprint dark crimson edge along the bottom of the Vermilion stripe in shaded bends
    if (tMid > 0.24 && tMid < 0.72) {
      buildBand(i => -0.34 + twist(i), i => -0.24 + twist(i), "VERMILION_OVER");
    }

    // 3. Central White Paste Body (Paper Highlight on lit bends, Mint/Grey in shaded bends)
    let centerLayer = (tMid > 0.36 && tMid < 0.58) ? "MINT" : "HIGHLIGHT";
    buildBand(i => -0.24 + twist(i), i => 0.18 + twist(i), centerLayer);

    // 4. Cool Mint Stripe (upper half of the aqua stripe)
    buildBand(i => 0.18 + twist(i), i => 0.50 + twist(i), "MINT", (tMid > 0.3 && tMid < 0.6), 105);

    // 5. Process Cyan Stripe (shadow half of the aqua stripe)
    buildBand(i => 0.50 + twist(i), i => 0.78 + twist(i) * 0.5, "CYAN", (tMid < 0.3), 15);

    // 6. Underside Core Shadow (Mid-Grey & Twilight Overprint Dark)
    let shadowLayer = (tMid > 0.18 && tMid < 0.48) || (tMid > 0.68 && tMid < 0.92)
      ? "OVERPRINT_DARK"
      : "GREY";
    buildBand(i => 0.78 + twist(i) * 0.5, i => 0.91, shadowLayer, (shadowLayer === "GREY"), 45);

    // 7. Bottom Reflected Bounce Rim (Butter-Yellow & Paper Sliver)
    let rimLayer = (tMid > 0.45 && tMid < 0.75) ? "HIGHLIGHT" : "BUTTER_BOUNCE";
    buildBand(i => 0.91, i => 1.00, rimLayer);
  }

  // C. Transverse Compression Creases at the 3 tight inner bends of the paste ribbon
  const pinchIndices = [19, 22, 39, 42, 55, 58];
  for (let idx of pinchIndices) {
    let sp = spine[idx];
    let sign = (idx >= 38 && idx <= 44) ? -1 : 1; // Inner side of the bend
    let pEdge = pastePt(idx, sign * 0.96);
    let pMid = pastePt(idx + 1, sign * 0.15);
    let pSide = pastePt(idx - 1, sign * 0.72);
    addPoly("CYAN", [pEdge, pMid, pSide], 0);
    let pH1 = pastePt(idx + 1, sign * 0.92);
    let pH2 = pastePt(idx + 2, sign * 0.25);
    let pH3 = pastePt(idx, sign * 0.60);
    addPoly("HIGHLIGHT", [pH1, pH2, pH3], 0);
  }
}

// ============================================================================
// RENDER ALL PULLED SCREENPRINT SEPARATIONS IN COLOR BATCHES
// ============================================================================
function renderScreenSeparation(layerName, hexColor, washAlpha, edgeWeight = 0.42) {
  let bucket = layers[layerName];
  if (!bucket) return;
  let off = OFFSET[layerName] || [0, 0];

  brush.noField();
  brush.noFill();
  brush.noMass();

  // 1. Pull flat matte screenprint ink wash + crisp stenciled edge
  brush.wash(hexColor, washAlpha);
  brush.set("screen_edge", hexColor, edgeWeight);

  for (let item of bucket.polys) {
    let pts = item.pts;
    brush.beginShape(item.curvature || 0);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0] + off[0], pts[i][1] + off[1]);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 2. Pull graphic screenprint line-screen hatches for midtone transitions
  if (bucket.hatches.length > 0) {
    let hatchCol = (layerName === "MINT") ? PALETTE.CYAN
                 : (layerName === "GREY") ? PALETTE.OVERPRINT_DARK
                 : (layerName === "CYAN") ? PALETTE.OVERPRINT_DARK
                 : PALETTE.VERMILION_OVER;
    brush.hatchStyle("halftone_line", hatchCol, 0.36);
    brush.set("screen_edge", hexColor, 0.3);

    for (let h of bucket.hatches) {
      brush.hatch(h.dist, h.angle, { rand: 0.015 });
      brush.beginShape(h.curvature || 0);
      for (let i = 0; i < h.pts.length; i++) {
        brush.vertex(h.pts[i][0] + off[0], h.pts[i][1] + off[1]);
      }
      brush.endShape(true);
      brush.noHatch();
    }
  }

  // 3. Pull any fine registration/detail lines in this separation
  if (bucket.lines.length > 0) {
    for (let ln of bucket.lines) {
      brush.set("screen_edge", hexColor, ln.weight);
      brush.line(
        ln.x1 + off[0], ln.y1 + off[1],
        ln.x2 + off[0], ln.y2 + off[1]
      );
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 0. Archival Cream Paper Ground
  background(PALETTE.PAPER);

  // 1. Solid Matte Butter-Yellow Field
  brush.noFill();
  brush.noHatch();
  brush.wash(PALETTE.BUTTER, 252);
  brush.set("screen_edge", PALETTE.BUTTER, 0.5);
  brush.rect(0, 0, width, height, "corner");
  brush.noWash();

  // Subtle matte squeegee grain across the butter-yellow field
  brush.set("squeegee_tooth", PALETTE.BUTTER_DEEP, 1.0);
  for (let y = 40; y < height - 40; y += 28) {
    brush.line(30, y, width - 30, y + random(-4, 4));
  }

  // Build all separations for the crumpled toothpaste tube & striped paste ribbon
  buildArtwork();

  // 2. Pull Each Screenprint Separation in Sequence (Grouped by Color for Performance & Authenticity)
  // Screen 1: Raw Paper Knockout Silhouette (creates the misregistered paper slivers against the yellow field)
  renderScreenSeparation("PAPER_KNOCKOUT", PALETTE.PAPER, 255, 0.55);

  // Screen 2: Reflected Butter-Yellow Bounce Facets
  renderScreenSeparation("BUTTER_BOUNCE", PALETTE.BUTTER, 250, 0.45);

  // Screen 3: Process Mint Separation & Mint-over-Yellow Overprint
  renderScreenSeparation("MINT", PALETTE.MINT, 246, 0.45);
  renderScreenSeparation("MINT_OVER", PALETTE.MINT_OVER_YELLOW, 246, 0.40);

  // Screen 4: Mid-Grey Separation & Grey-over-Mint Overprint
  renderScreenSeparation("GREY", PALETTE.GREY, 246, 0.45);
  renderScreenSeparation("GREY_OVER", PALETTE.GREY_OVER_MINT, 246, 0.40);

  // Screen 5: Warm Vermilion Separation & Vermilion Overprint
  renderScreenSeparation("VERMILION", PALETTE.VERMILION, 248, 0.48);
  renderScreenSeparation("VERMILION_OVER", PALETTE.VERMILION_OVER, 248, 0.42);

  // Screen 6: Process Cyan Separation & Cyan Overprint
  renderScreenSeparation("CYAN", PALETTE.CYAN, 248, 0.48);
  renderScreenSeparation("CYAN_OVER", PALETTE.CYAN_OVER_MINT, 248, 0.42);

  // Screen 7: Dusky Twilight Deep Overprint (Cyan x Vermilion x Grey)
  renderScreenSeparation("OVERPRINT_DARK", PALETTE.OVERPRINT_DARK, 252, 0.48);

  // Screen 8: Final Crisp Paper Highlight Screen (Foil Crease Ridges, Threads & Wet Paste Sheen)
  renderScreenSeparation("HIGHLIGHT", PALETTE.PAPER_BRIGHT, 255, 0.45);

  // Subtle matte paper tooth pass over the printed inks to unify the serigraph surface
  brush.set("squeegee_tooth", PALETTE.PAPER, 0.75);
  for (let i = 0; i < 24; i++) {
    let y = map(i, 0, 23, 180, 1020);
    brush.line(110, y, 1080, y);
  }

  noLoop();
}

