function buildSpecimenLayout() {
  const cx = 600;
  const cy = 600;
  buttons = [];

  function addBtn(x, y, r, type, rot, isClear, nacrePhase) {
    // Micro-jitter (< 0.25px) for human hand-mounted realism under a microscope
    let jx = random(-0.18, 0.18);
    let jy = random(-0.18, 0.18);
    let jRot = random(-1.2, 1.2);
    buttons.push({
      x: x + jx,
      y: y + jy,
      r: r,
      type: type, // "fluted4", "pearl4", "fisheye2", "clear4", "clear2", "seed2"
      rot: rot + jRot,
      isClear: isClear,
      nacrePhase: nacrePhase !== undefined ? nacrePhase : random(-25, 25)
    });
  }

  // --- RING 0: Grand Central Mother-of-Pearl Master Button ---
  addBtn(cx, cy, 36.0, "fluted4", 0, false, 0);

  // --- RING 1: Tight Collar of 18 Clear & Pearl Seed Buttons (r = 51) ---
  for (let i = 0; i < 18; i++) {
    let a = i * 20;
    let bx = cx + 51 * cos(a);
    let by = cy + 51 * sin(a);
    addBtn(bx, by, 7.6, "seed2", a + 90, i % 2 === 1, (i * 30) % 60 - 30);
