  // --- RING 2: 16 Radial Fisheye Lenticular Pearl Buttons (r = 82) ---
  for (let i = 0; i < 16; i++) {
    let a = i * 22.5;
    let bx = cx + 82 * cos(a);
    let by = cy + 82 * sin(a);
    addBtn(bx, by, 14.0, "fisheye2", a, false, sin(a * 2) * 20);

    // Ring 2b: 16 interstitial clear crystal buttons tucked in the valleys (r = 102)
    let aMid = a + 11.25;
    let mx = cx + 102 * cos(aMid);
    let my = cy + 102 * sin(aMid);
    addBtn(mx, my, 6.8, "clear2", aMid + 90, true, 0);
  }

  // --- RING 3: 16 Large Bevelled Shirt Buttons (r = 140) ---
  // Index 15 (angle = 337.5° / -22.5°, upper-right) is TIPPED ON ITS EDGE!
  const tippedIdx = 15;
  for (let i = 0; i < 16; i++) {
