    } else {
      addBtn(bx, by, 22.0, bType, a, i % 4 === 2, cos(a) * 25);
    }

    // Ring 3b: Inner & outer diamond valley beads framing Ring 3
    let aVal = a + 11.25;
    // Inner valley bead (r = 121)
    addBtn(
      cx + 121 * cos(aVal),
      cy + 121 * sin(aVal),
      5.5,
      "seed2",
      aVal,
      true,
      0
    );
    // Outer valley bead (r = 159) — slightly nudged next to the tipped button!
    let nudgeR = (i === tippedIdx || i === (tippedIdx + 15) % 16) ? 2.2 : 0;
    let nudgeA = i === tippedIdx ? 0.9 : (i === (tippedIdx + 15) % 16 ? -0.9 : 0);
    addBtn(
      cx + (159 + nudgeR) * cos(aVal + nudgeA),
