// ============================================================================
// BACKGROUND, DARKFIELD CONDENSER & SLIDE MOUNT
// ============================================================================
function drawDarkfieldGround(cx, cy) {
  brush.noStroke();

  // Deep optical condenser rings using fast brush.wash()
  brush.wash("#060b16", 180);
  brush.circle(cx, cy, 575, 0.01);

  brush.wash("#081020", 110);
  brush.circle(cx, cy, 520, 0.01);

  brush.wash("#050912", 150);
  brush.circle(cx, cy, 420, 0.01);

  brush.wash("#091324", 85);
  brush.circle(cx, cy, 300, 0.01);

  brush.wash("#050811", 160);
  brush.circle(cx, cy, 200, 0.01);

  brush.wash("#0a1528", 70);
  brush.circle(cx, cy, 95, 0.01);

  brush.noWash();

  // Whisper-faint radial darkfield condenser striae in the deep background
  for (let i = 0; i < 72; i++) {
    let a = i * 5 + random(-1.5, 1.5);
    let r1 = random(45, 180);
    let r2 = random(380, 535);
    brush.set("2H", "#101c30", 0.22);
    brush.line(cx + r1 * cos(a), cy + r1 * sin(a), cx + r2 * cos(a), cy + r2 * sin(a));
  }
}

function drawSlideMount(cx, cy) {
  // Subtle Newton's interference arcs near the coverslip edge
  brush.set("nacre_veil", "#9e7ad6", 0.85);
  brush.arc(cx, cy, 536, -110, -15);
  brush.arc(cx, cy, 536, 85, 165);

  brush.set("nacre_veil", "#6bc7b4", 0.85);
  brush.arc(cx, cy, 539, -65, 35);
  brush.arc(cx, cy, 539, 130, 215);

  // Outer spun asphaltum & silver turntable rings (r = 542 to 578)
  const mountRings = [
    { r: 541, col: "#4c627a", w: 0.65 },
    { r: 543, col: "#8aa2bc", w: 0.55 },
    { r: 554, col: "#2e3f52", w: 0.5 },
    { r: 558, col: "#536a82", w: 0.45 },
    { r: 572, col: "#384b61", w: 0.6 },
    { r: 575, col: "#6b829c", w: 0.4 }
  ];

  for (let mr of mountRings) {
    brush.set("razor_pen", mr.col, mr.w);
    brush.circle(cx, cy, mr.r, 0.008);
  }

  // Calibrated ocular micrometer ticks between r = 558 and r = 572
  for (let deg = 0; deg < 360; deg += 2) {
    let isMajor = deg % 10 === 0;
    let isMid = deg % 5 === 0;
    let rIn = 558.5;
    let rOut = isMajor ? 571.5 : (isMid ? 567.5 : 564.0);
    let col = isMajor ? "#9ab2ca" : "#43576e";
    let w = isMajor ? 0.48 : 0.28;
    brush.set("razor_pen", col, w);
    brush.line(
      cx + rIn * cos(deg),
      cy + rIn * sin(deg),
      cx + rOut * cos(deg),
      cy + rOut * sin(deg)
    );
  }

  // Razor-sharp darkfield specular arcs along the bevelled glass coverslip edge (r = 542)
  brush.set("razor_pen", "#d6e6f7", 0.85);
  brush.arc(cx, cy, 542, -135, 15);
  brush.arc(cx, cy, 542, 75, 175);

  brush.set("specular_needle", "#ffffff", 0.95);
  brush.arc(cx, cy, 542, -95, -20);
  brush.arc(cx, cy, 542, 105, 155);

  brush.set("specular_needle", "#d8e8f8", 0.65);
  brush.arc(cx, cy, 573, -85, -25);
  brush.arc(cx, cy, 573, 110, 150);
}

function drawBalsamMotes(cx, cy) {
  // Tiny trapped micro-vesicles and silver refractive specks in the darkfield medium
  for (let i = 0; i < 85; i++) {
    let a = random(360);
    let r = sqrt(random(0.02, 0.96)) * 532;
    let mx = cx + r * cos(a);
    let my = cy + r * sin(a);
    let mr = random(0.6, 1.9);

    if (mr > 1.25) {
      brush.set("razor_pen", "#6d849e", 0.28);
      brush.circle(mx, my, mr, 0.02);
      brush.set("specular_needle", "#eef6ff", 0.35);
      brush.arc(mx, my, mr, -110, 20);
    } else {
      brush.set("razor_pen", "#8aa2bc", 0.3);
      brush.line(mx - 0.5, my - 0.5, mx + 0.5, my + 0.5);
    }
  }
}

// ============================================================================
// FLAT BUTTON RENDERER (Darkfield Rim, Bevelled Lip, Iridescence & Holes)
// ============================================================================
function drawFlatButton(b, cx, cy) {
  const x = b.x;
  const y = b.y;
  const r = b.r;
  const rot = b.rot;
  const type = b.type;
  const isClear = b.isClear;

  // Key darkfield light from -55° (top-left) blended subtly with radial condenser angle
  let radAngle = atan2(y - cy, x - cx);
  let lightDir = -55 + sin(radAngle + 55) * 12;
  let oppDir = lightDir + 180;

  let rWell = r * (type === "fisheye2" ? 0.75 : (type === "seed2" ? 0.66 : 0.68));

  // --------------------------------------------------------------------------
  // 1. FAINT GHOSTS OF IRIDESCENCE (Lilac & Celadon inside the concave dome)
  // --------------------------------------------------------------------------
  if (!isClear && r >= 6.0) {
    let phase = rot + b.nacrePhase;
    let veilWeight = constrain(map(r, 6, 36, 0.26, 1.15), 0.24, 1.25);

    // Lilac ghost crescent
    brush.set("nacre_veil", "#c59bf2", veilWeight);
    brush.arc(x, y, rWell * 0.64, phase - 95, phase + 25);

    // Celadon ghost crescent on opposing side of dome
    brush.set("nacre_veil", "#74dec7", veilWeight);
    brush.arc(x, y, rWell * 0.60, phase + 75, phase + 195);

    if (r >= 11.0) {
      // Secondary deeper dome shimmer
      brush.set("nacre_veil", "#a67be0", veilWeight * 0.85);
      brush.arc(x, y, rWell * 0.38, phase - 75, phase + 40);

      brush.set("nacre_veil", "#5ac4ae", veilWeight * 0.85);
      brush.arc(x, y, rWell * 0.36, phase + 95, phase + 210);

      // Silky aragonite diffraction filaments inside the well
      let numFil = r >= 18 ? 5 : 3;
      let filW = map(r, 11, 36, 0.34, 0.62);
      for (let f = 0; f < numFil; f++) {
        let fr = map(f, 0, numFil - 1, rWell * 0.28, rWell * 0.78);
        brush.set("nacre_filament", f % 2 === 0 ? "#dec2ff" : "#aaf5e3", filW);
        brush.arc(x, y, fr, lightDir - 80 + f * 8, lightDir - 10 + f * 8);
        brush.set("nacre_filament", f % 2 === 0 ? "#8ce8d3" : "#cdb0f5", filW * 0.9);
        brush.arc(x, y, fr, oppDir - 65 - f * 6, oppDir + 15 - f * 6);
      }
    }
  } else if (isClear && r >= 7.5) {
    // Subtle refractive dispersion on clear glass/lucite buttons
    let dispW = map(r, 7.5, 22, 0.28, 0.5);
    brush.set("nacre_filament", "#8adcd0", dispW);
    brush.arc(x, y, rWell * 0.86, oppDir - 45, oppDir + 25);
    brush.set("nacre_filament", "#b89cf0", dispW);
    brush.arc(x, y, rWell * 0.84, lightDir - 35, lightDir + 35);
  }

  // --------------------------------------------------------------------------
  // 2. BEVELLED LIP & SPECIAL SURFACE CARVING
  // --------------------------------------------------------------------------
  let baseW = map(r, 5, 36, 0.30, 0.68);
  let litW = map(r, 5, 36, 0.42, 0.92);
  let specW = map(r, 5, 36, 0.48, 1.08);

  // Full 360° inner well boundary
  brush.set("razor_pen", isClear ? "#3e536b" : "#4b617a", baseW * 0.9);
  brush.circle(x, y, rWell, 0.012);

  // Sloping inner bevel wall facing the light (brightest around oppDir)
  brush.set("razor_pen", "#b2c7de", litW * 0.88);
  brush.arc(x, y, rWell, oppDir - 70, oppDir + 70);

  if (r >= 9.0) {
    // Razor catchlight on the concave inner bevel lip
    brush.set("specular_needle", "#edf6ff", specW * 0.72);
    brush.arc(x, y, rWell * 1.03, oppDir - 45, oppDir + 45);

    // Near-side bevel ridge
    brush.set("razor_pen", "#7d94ad", baseW * 0.85);
    brush.arc(x, y, rWell * 1.07, lightDir - 60, lightDir + 55);
  }

  // Type-specific bevel details
  if (type === "fluted4" && r >= 11.5) {
    // Engine-turned radial pearl flutes between rWell and outer rim
    let numFlutes = r >= 28 ? 40 : (r >= 18 ? 28 : 20);
    let rIn = rWell * 1.06;
    let rOut = r * 0.91;
    for (let k = 0; k < numFlutes; k++) {
      let fa = rot + k * (360 / numFlutes);
      let diffL = abs(((fa - lightDir + 540) % 360) - 180);
      let diffO = abs(((fa - oppDir + 540) % 360) - 180);
      let isBright = diffL < 48 || diffO < 42;
      brush.set(
        "razor_pen",
        isBright ? "#cce0f5" : "#4d647d",
        isBright ? baseW * 0.72 : baseW * 0.48
      );
      brush.line(
        x + rIn * cos(fa),
        y + rIn * sin(fa),
        x + rOut * cos(fa),
        y + rOut * sin(fa)
      );
    }
  } else if (type === "fisheye2" && r >= 8.5) {
    // Lenticular "cat's-eye" groove carved across the face along rot
    drawFisheyeGroove(x, y, r, rot, lightDir, baseW, specW);
  }

  // --------------------------------------------------------------------------
  // 3. OUTER RIM (Darkfield Lit Rim & Specular Edge)
  // --------------------------------------------------------------------------
  // Full 360° outer boundary
  brush.set("razor_pen", isClear ? "#506780" : "#5e7691", baseW);
  brush.circle(x, y, r, 0.01);

  if (r >= 10.0) {
    // Secondary outer bevel step ring at 0.94 * r
    brush.set("razor_pen", "#7a92ab", baseW * 0.78);
    brush.arc(x, y, r * 0.94, lightDir - 95, lightDir + 95);
    brush.arc(x, y, r * 0.94, oppDir - 65, oppDir + 65);
  }

  // Primary lit rim arc (top-left darkfield cone)
  brush.set("razor_pen", "#deecf9", litW);
  brush.arc(x, y, r, lightDir - 82, lightDir + 82);

  // Blinding pure white specular needle glint on outer rim
  brush.set("specular_needle", "#ffffff", specW);
  brush.arc(x, y, r, lightDir - 46, lightDir + 46);

  // Opposite refractive exit rim (bottom-right)
  brush.set("razor_pen", "#aec5dc", litW * 0.82);
  brush.arc(x, y, r, oppDir - 62, oppDir + 62);

  brush.set("specular_needle", "#e4f0fc", specW * 0.72);
  brush.arc(x, y, r, oppDir - 34, oppDir + 34);

  // --------------------------------------------------------------------------
  // 4. THREAD HOLES & RECESSED THREAD GROOVES
  // --------------------------------------------------------------------------
  let numHoles = (type === "fisheye2" || type === "clear2" || type === "seed2") ? 2 : 4;
  let holeDist = r * (numHoles === 2 ? 0.255 : 0.275);
  let holeR = max(1.05, r * (numHoles === 2 ? 0.125 : 0.116));

  // Subtle recessed thread-groove channels between holes on larger 4-hole buttons
  if (numHoles === 4 && r >= 11.5) {
    for (let pair of [-1, 1]) {
      let pAngle = rot + (pair === 1 ? 90 : 270);
      let px = x + holeDist * 0.7 * cos(pAngle);
      let py = y + holeDist * 0.7 * sin(pAngle);
      let dx = holeDist * 0.55 * cos(rot);
      let dy = holeDist * 0.55 * sin(rot);
      brush.set("razor_pen", "#455b73", baseW * 0.55);
      brush.line(px - dx, py - dy, px + dx, py + dy);
    }
  }

  for (let h = 0; h < numHoles; h++) {
    let ha = rot + (numHoles === 2 ? h * 180 : 45 + h * 90);
    let hx = x + holeDist * cos(ha);
    let hy = y + holeDist * sin(ha);

    // Punch dark inky ground through the iridescence inside each hole
    if (r >= 9.0) {
      brush.set("dark_mask", "#04070e", map(holeR, 1, 4.5, 0.22, 0.78));
      brush.circle(hx, hy, holeR * 0.65, 0.0);
    }

    // Full 360° silver lip of the thread hole
    brush.set("razor_pen", "#93abc4", baseW * 0.85);
    brush.circle(hx, hy, holeR, 0.015);

    // Deep tunnel bottom exit arc inside large holes
    if (r >= 15.0) {
      let offX = hx + holeR * 0.26 * cos(oppDir);
      let offY = hy + holeR * 0.26 * sin(oppDir);
      brush.set("razor_pen", "#6d859e", baseW * 0.68);
      brush.arc(offX, offY, holeR * 0.88, oppDir - 65, oppDir + 65);
    }

    // Bright white specular crescent on the inner wall of the hole facing the light
    brush.set("specular_needle", "#ffffff", specW * 0.82);
    brush.arc(hx, hy, holeR, oppDir - 75, oppDir + 75);

    // Secondary subtle glint on the near lip of the hole
    if (r >= 10.0) {
      brush.set("razor_pen", "#cde0f2", baseW * 0.65);
      brush.arc(hx, hy, holeR, lightDir - 45, lightDir + 45);
    }
  }
}

function drawFisheyeGroove(x, y, r, rot, lightDir, baseW, specW) {
  let len = r * 0.72;
  let wid = r * 0.30;
  let c = cos(rot);
  let s = sin(rot);

  // Two symmetric lenticular arcs forming the cat's-eye groove
  for (let side of [-1, 1]) {
    let pts = [];
    for (let i = 0; i <= 10; i++) {
      let t = i / 10;
      let u = lerp(-len, len, t);
      let v = side * wid * sin(t * 180);
      let gx = x + u * c - v * s;
      let gy = y + u * s + v * c;
      let p = sin(t * 180) * 0.9 + 0.2;
      pts.push([gx, gy, p]);
    }
    let normalAng = rot + side * 90;
    let facesLight = abs(((normalAng - (lightDir + 180) + 540) % 360) - 180) < 90;
    brush.set(
      facesLight ? "specular_needle" : "razor_pen",
      facesLight ? "#e8f4ff" : "#6c849e",
      facesLight ? specW * 0.68 : baseW * 0.75
    );
    brush.spline(pts, 0.5);
  }
}

// ============================================================================
// THE ONE BUTTON TIPPED ON ITS EDGE (Hyperreal 3D Foreshortened Projection)
// ============================================================================
function drawTippedButton(data, cx, cy) {
  const seatX = data.seatX;
  const seatY = data.seatY;
  const r = data.r; // 22.5

  // --------------------------------------------------------------------------
  // 1. GHOSTLY EMPTY MOUNTING SEAT ON THE SLIDE GLASS
  // --------------------------------------------------------------------------
  brush.set("razor_pen", "#25364a", 0.38);
  brush.arc(seatX, seatY, r, -165, -15);
  brush.arc(seatX, seatY, r, 15, 165);

  brush.set("razor_pen", "#1d2c3d", 0.32);
  brush.arc(seatX, seatY, r * 0.68, -140, 140);

  // Tiny balsam residue micro-rings where the button lifted off its seat
  const bubbles = [
    { dx: -9, dy: -6, br: 1.4 },
    { dx: -13, dy: 2, br: 0.9 },
    { dx: -5, dy: -12, br: 1.1 },
    { dx: 8, dy: -9, br: 1.2 }
  ];
  for (let b of bubbles) {
    brush.set("razor_pen", "#5c748e", 0.3);
    brush.circle(seatX + b.dx, seatY + b.dy, b.br, 0.02);
    brush.set("specular_needle", "#dceaf8", 0.35);
    brush.arc(seatX + b.dx, seatY + b.dy, b.br, -100, 30);
  }

  // --------------------------------------------------------------------------
  // 2. 3D PROJECTION PARAMETERS OF THE TIPPED BUTTON
  // --------------------------------------------------------------------------
  // Tilted up at ~65° around a major axis angled at 34°
  const bx = seatX + 3.2;
  const by = seatY - 2.4;
  const rotDeg = 34;          // Major axis orientation
  const aspect = 0.42;        // cos(65°) foreshortening
  const thick = 8.4;          // Cylindrical rim thickness in px
  const frontY = -thick * 0.46;
  const backY = thick * 0.54;
  const wellDepth = 2.3;      // 3D concavity offset of the sunken dish

  const cRot = cos(rotDeg);
  const sRot = sin(rotDeg);

  function toGlobal(lx, ly) {
    return [bx + lx * cRot - ly * sRot, by + lx * sRot + ly * cRot];
  }

  // --------------------------------------------------------------------------
  // 3. OPTICAL CAUSTIC & CONTACT SHADOW ON THE GLASS SLIDE
  // --------------------------------------------------------------------------
  let [contactX, contactY] = toGlobal(0, backY + r * aspect * 0.92);
  brush.set("nacre_veil", "#a47ee0", 0.75);
  drawEllipticalSpline(contactX, contactY, r * 0.62, r * 0.22, rotDeg, 10, 170, 14);
  brush.set("nacre_veil", "#6cd4be", 0.70);
  drawEllipticalSpline(contactX, contactY, r * 0.52, r * 0.18, rotDeg, 20, 160, 14);

  // --------------------------------------------------------------------------
  // 4. SOLID DARKFIELD OCCLUSION OF THE 3D BUTTON BODY
  // --------------------------------------------------------------------------
  for (let s = 0; s <= 12; s++) {
    let f = s / 12;
    let [ox, oy] = toGlobal(0, lerp(frontY, backY, f));
    for (let radScale of [0.25, 0.52, 0.78, 0.92]) {
      brush.set("dark_mask", "#050811", 0.95);
      drawEllipticalSpline(ox, oy, r * radScale, r * aspect * radScale, rotDeg, 0, 360, 18);
    }
  }

  // --------------------------------------------------------------------------
  // 5. CYLINDRICAL SIDE WALL (Turned Edge of the Pearl Button)
  // --------------------------------------------------------------------------
  let [backCx, backCy] = toGlobal(0, backY);

  // Iridescent nacre glow inside the laminated shell edge
  let [midEdgeCx, midEdgeCy] = toGlobal(0, (frontY + backY) * 0.5);
  brush.set("nacre_veil", "#c59bf2", 0.85);
  drawEllipticalSpline(midEdgeCx, midEdgeCy, r * 0.96, r * aspect * 0.96, rotDeg, 5, 110, 14);
  brush.set("nacre_veil", "#74dec7", 0.85);
  drawEllipticalSpline(midEdgeCx, midEdgeCy, r * 0.96, r * aspect * 0.96, rotDeg, 75, 175, 14);

  // Axial thickness contour lines along the curved barrel edge
  const numEdgeRibs = 32;
  for (let i = 0; i <= numEdgeRibs; i++) {
    let a = map(i, 0, numEdgeRibs, -8, 188);
    let lx = r * cos(a);
    let lyFront = frontY + r * aspect * sin(a);
    let lyBack = backY + r * aspect * sin(a);
    let [x1, y1] = toGlobal(lx, lyFront);
    let [x2, y2] = toGlobal(lx, lyBack);

    // Highlight zones along the curved cylinder barrel
    let isGlint = (a > 12 && a < 52) || (a > 128 && a < 168);
    brush.set(
      isGlint ? "specular_needle" : "razor_pen",
      isGlint ? "#e8f3ff" : "#5e7691",
      isGlint ? 0.58 : 0.38
    );
    brush.line(x1, y1, x2, y2);
  }

  // Lathe-turned circumferential grooves along the button's cylindrical edge
  for (let gFrac of [0.28, 0.55, 0.78]) {
    let [gx, gy] = toGlobal(0, lerp(frontY, backY, gFrac));
    brush.set("razor_pen", gFrac === 0.55 ? "#9ab2cb" : "#516880", 0.48);
    drawEllipticalSpline(gx, gy, r, r * aspect, rotDeg, -5, 185, 20);

    brush.set("specular_needle", "#eef6ff", 0.55);
    drawEllipticalSpline(gx, gy, r, r * aspect, rotDeg, 15, 58, 10, (t) => sin(t * 180));
    drawEllipticalSpline(gx, gy, r, r * aspect, rotDeg, 125, 168, 10, (t) => sin(t * 180));
  }

  // Back rim ellipse arc (bottom edge of the cylinder)
  brush.set("razor_pen", "#869eb8", 0.65);
  drawEllipticalSpline(backCx, backCy, r, r * aspect, rotDeg, -8, 188, 22);

  brush.set("specular_needle", "#ffffff", 0.82);
  drawEllipticalSpline(backCx, backCy, r, r * aspect, rotDeg, 20, 160, 16, (t) => sin(t * 180));

  // Crisp silhouette tangent edges at a = 0° and a = 180°
  for (let side of [-1, 1]) {
    let [tx1, ty1] = toGlobal(side * r, frontY);
    let [tx2, ty2] = toGlobal(side * r, backY);
    brush.set("specular_needle", "#ffffff", 0.88);
    brush.line(tx1, ty1, tx2, ty2);
  }

  // --------------------------------------------------------------------------
  // 6. FORESHORTENED FRONT FACE & CONCAVE IRIDESCENT DOME
  // --------------------------------------------------------------------------
  let [frontCx, frontCy] = toGlobal(0, frontY);
  let [wellCx, wellCy] = toGlobal(0, frontY + wellDepth);
  let rWell = r * 0.68;

  // Heightened Bragg iridescence inside the tilted concave dome (lilac & celadon)
  for (let band = 0; band < 4; band++) {
    let s = map(band, 0, 3, 0.32, 0.86);
    brush.set("nacre_veil", band % 2 === 0 ? "#d6b0ff" : "#b589eb", 1.15);
    drawEllipticalSpline(wellCx, wellCy, rWell * s, rWell * aspect * s, rotDeg, 155, 345, 16);

    brush.set("nacre_veil", band % 2 === 0 ? "#86f2dc" : "#62ccb6", 1.15);
    drawEllipticalSpline(wellCx, wellCy, rWell * s, rWell * aspect * s, rotDeg, -25, 165, 16);
  }

  // Fine nacre interference striations across the tilted dome
  for (let f = 0; f < 7; f++) {
    let s = map(f, 0, 6, 0.25, 0.90);
    brush.set("nacre_filament", f % 2 === 0 ? "#ebd6ff" : "#b8faea", 0.68);
    drawEllipticalSpline(
      wellCx,
      wellCy,
      rWell * s,
      rWell * aspect * s,
      rotDeg,
      175 + f * 6,
      320 - f * 4,
      14,
      (t) => sin(t * 180)
    );
    brush.set("nacre_filament", f % 2 === 0 ? "#9cf5e2" : "#d8baf8", 0.65);
    drawEllipticalSpline(
      wellCx,
      wellCy,
      rWell * s,
      rWell * aspect * s,
      rotDeg,
      5 + f * 5,
      145 - f * 5,
      14,
      (t) => sin(t * 180)
    );
  }

  // Foreshortened radial pearl flutes on the sloped bevel between outer rim and sunken well
  const numFlutes = 36;
  for (let k = 0; k < numFlutes; k++) {
    let a = k * (360 / numFlutes);
    let [xOut, yOut] = toGlobal(r * 0.93 * cos(a), frontY + r * 0.93 * aspect * sin(a));
    let [xIn, yIn] = toGlobal(rWell * 1.03 * cos(a), frontY + wellDepth + rWell * 1.03 * aspect * sin(a));

    // Lower bevel slope (sin(a) > 0) faces directly into the upper-left key light!
    let isLitSlope = (a > 15 && a < 165) || (a > 210 && a < 330);
    brush.set(
      "razor_pen",
      a > 20 && a < 160 ? "#e2effc" : (isLitSlope ? "#9eb6cf" : "#516880"),
      a > 20 && a < 160 ? 0.52 : 0.36
    );
    brush.line(xIn, yIn, xOut, yOut);
  }

  // Recessed inner well ellipse (bevelled lip boundary)
  brush.set("razor_pen", "#6d859e", 0.58);
  drawEllipticalSpline(wellCx, wellCy, rWell, rWell * aspect, rotDeg, 0, 360, 24);

  // Blazing highlight on the lower inner bevel wall facing the light
  brush.set("razor_pen", "#dcebf9", 0.82);
  drawEllipticalSpline(wellCx, wellCy, rWell, rWell * aspect, rotDeg, 10, 170, 18);

  brush.set("specular_needle", "#ffffff", 0.98);
  drawEllipticalSpline(wellCx, wellCy, rWell, rWell * aspect, rotDeg, 30, 150, 14, (t) => sin(t * 180));

  // Upper inner bevel rim highlight
  brush.set("razor_pen", "#a8bfd6", 0.52);
  drawEllipticalSpline(wellCx, wellCy, rWell, rWell * aspect, rotDeg, 195, 345, 16);

  // --------------------------------------------------------------------------
  // 7. FOUR FORESHORTENED ELLIPTICAL THREAD HOLES (With 3D Tunnel Depth)
  // --------------------------------------------------------------------------
  const holeDist = r * 0.275;
  const holeR = r * 0.118;
  for (let h = 0; h < 4; h++) {
    let ha = 28 + h * 90;
    let hlx = holeDist * cos(ha);
    let hly = frontY + wellDepth + holeDist * aspect * sin(ha);
    let [hx, hy] = toGlobal(hlx, hly);

    // Punch dark void inside the elliptical hole
    brush.set("dark_mask", "#04070e", 0.45);
    drawEllipticalSpline(hx, hy, holeR * 0.68, holeR * aspect * 0.68, rotDeg, 0, 360, 12);

    // Back tunnel aperture of the drilled hole (shifted along cylinder axis)
    let [hBackX, hBackY] = toGlobal(hlx, hly + 2.6);
    brush.set("razor_pen", "#758da6", 0.42);
    drawEllipticalSpline(hBackX, hBackY, holeR * 0.92, holeR * aspect * 0.92, rotDeg, 195, 345, 10);

    // Inner tunnel wall axial glints
    for (let ta of [215, 250, 290, 325]) {
      let [wx1, wy1] = toGlobal(hlx + holeR * cos(ta), hly + holeR * aspect * sin(ta));
      let [wx2, wy2] = toGlobal(hlx + holeR * cos(ta), hly + 2.4 + holeR * aspect * sin(ta));
      brush.set("razor_pen", "#b8cde2", 0.36);
      brush.line(wx1, wy1, wx2, wy2);
    }

    // Front elliptical hole rim
    brush.set("razor_pen", "#9cb4cc", 0.52);
    drawEllipticalSpline(hx, hy, holeR, holeR * aspect, rotDeg, 0, 360, 16);

    // Razor-sharp white catchlight on the lit rim of the hole
    brush.set("specular_needle", "#ffffff", 0.85);
    drawEllipticalSpline(hx, hy, holeR, holeR * aspect, rotDeg, 15, 165, 12, (t) => sin(t * 180));

    brush.set("specular_needle", "#e6f2ff", 0.62);
    drawEllipticalSpline(hx, hy, holeR, holeR * aspect, rotDeg, 200, 340, 12, (t) => sin(t * 180));
  }

  // --------------------------------------------------------------------------
  // 8. FRONT FACE OUTER RIM ELLIPSE (Blazing Darkfield Edge)
  // --------------------------------------------------------------------------
  // Full 360° front rim ellipse
  brush.set("razor_pen", "#7d95ae", 0.68);
  drawEllipticalSpline(frontCx, frontCy, r, r * aspect, rotDeg, 0, 360, 28);

  // Inner step of the outer rim bevel (0.94 * r)
  brush.set("razor_pen", "#9ab2cb", 0.52);
  drawEllipticalSpline(frontCx, frontCy, r * 0.94, r * 0.94 * aspect, rotDeg, 0, 360, 24);

  // Primary blazing white edge along the raised upper-left lip (facing the light)
  brush.set("razor_pen", "#e6f2ff", 0.95);
  drawEllipticalSpline(frontCx, frontCy, r, r * aspect, rotDeg, 165, 365, 20);

  brush.set("specular_needle", "#ffffff", 1.18);
  drawEllipticalSpline(frontCx, frontCy, r, r * aspect, rotDeg, 185, 345, 18, (t) => sin(t * 180) * 1.1 + 0.2);

  // Secondary bright specular arc along the front-lower lip
  brush.set("razor_pen", "#d4e6f8", 0.82);
  drawEllipticalSpline(frontCx, frontCy, r, r * aspect, rotDeg, 10, 170, 18);

  brush.set("specular_needle", "#ffffff", 0.96);
  drawEllipticalSpline(frontCx, frontCy, r, r * aspect, rotDeg, 35, 145, 14, (t) => sin(t * 180));
}

function drawEllipticalSpline(cx, cy, rx, ry, rotDeg, a1, a2, numPts, pressureFn) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i <= numPts; i++) {
    let t = i / numPts;
    let a = lerp(a1, a2, t);
    let lx = rx * cos(a);
    let ly = ry * sin(a);
    let gx = cx + lx * c - ly * s;
    let gy = cy + lx * s + ly * c;
    let p = pressureFn ? pressureFn(t) : 1.0;
    pts.push([gx, gy, p]);
  }
  brush.spline(pts, 0.5);
}

// ============================================================================
// OVER-GLASS COVERSLIP REFLECTIONS
// ============================================================================
function drawCoverslipReflections(cx, cy) {
  // Subtle diagonal optical sheen across the top glass surface
  for (let i = -3; i <= 3; i++) {
    let offset = i * 6.5;
    brush.set("nacre_veil", "#dcebff", 0.55);
    brush.arc(cx, cy, 485 + offset, -128, -58);
    brush.arc(cx, cy, 310 + offset, -122, -62);
  }

  // Tiny crisp surface dust specks on the top coverslip glass (with double reflection)
  const glassSpecks = [
    { x: 385, y: 310 },
    { x: 790, y: 275 },
    { x: 845, y: 740 },
    { x: 315, y: 780 },
    { x: 520, y: 215 }
  ];
  for (let sp of glassSpecks) {
    brush.set("specular_needle", "#ffffff", 0.42);
    brush.line(sp.x - 0.8, sp.y - 0.3, sp.x + 0.8, sp.y + 0.3);
    brush.set("razor_pen", "#526880", 0.28);
    brush.line(sp.x + 1.8, sp.y + 2.2, sp.x + 3.0, sp.y + 2.6);
  }
}

// Hyperrealism in p5.brush: Boxer Taping His Hands in a Dim Gym
// Palette: Gunmetal silver-green, pallid colourless skin, crushed charcoal blacks,
// stained & frayed white hand wraps, metallic silver pencil highlights.

const PALETTE = {
  voidBlack: "#040706",
  crushBlack: "#080d0c",
  deepShadow: "#0e1614",
  gunmetalDark: "#16221f",
  gunmetalMid: "#23332f",
  gunmetalSlate: "#334641",
  gunmetalLight: "#485e58",

  skinShadow: "#141d1b",
  skinCore: "#212e2b",
  skinMidDark: "#384843",
  skinMid: "#50625c",
  skinLight: "#6d807a",
