function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.voidBlack);

  // 1. Grimy gym atmosphere, overhead light cone, and blurred ring ropes
  drawGymBackground();

  // 2. Deep crushed-black torso & lap shadow anchoring the arms
  drawTorsoShadowMass();

  // 3. Left-side Arm (Boxer's right forearm & clenched fist being wrapped)
  drawLeftForearmAndFist();

  // 4. Layered, stained, frayed hand wraps on the left fist and wrist
  drawLeftHandWraps();

  // 5. High-tension strip of white tape pulled taut between the two hands
  drawTautTapeBridge();

  // 6. Right-side Arm & Gripping Hand pulling the tape, plus hanging frayed tail
  drawRightArmAndGrippingHand();

  // 7. Specular sweat droplets, rivulets, and metallic silver pencil highlights
  drawSweatAndSilverHighlights();

  // 8. Harsh pushed-film grain, charcoal edge crush, and gritty atmospheric dust
  drawPushedFilmGrain();

  noLoop();
}

// ============================================================================
// GEOMETRY & SHADING HELPERS
// ============================================================================

function lerpPt(a, b, t) {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t)];
}

function evalCatmullRom(pts, t) {
  let n = pts.length - 1;
  let f = constrain(t, 0, 1) * n;
  let i = Math.min(Math.floor(f), n - 1);
  let lt = f - i;
  let p0 = pts[Math.max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[Math.min(n, i + 1)];
  let p3 = pts[Math.min(n, i + 2)];
  let t2 = lt * lt;
  let t3 = t2 * lt;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * lt +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * lt +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
  );
  return [x, y];
}

function washPoly(pts, col, opacity, curvature = 0.15) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function fillPoly(pts, col, opacity, bleed = 0.12, tex = 0.45, curvature = 0.18) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.35);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function massPoly(pts, brushName, col, opts, curvature = 0.15) {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.mass(brushName, col, opts);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noMass();
}

// Volumetric ribbon renderer: builds wash bands + cross-contour + longitudinal hatching
// between a top spine curve (u=0) and bottom spine curve (u=1)
function renderVolumetricRibbon(topPts, botPts, cfg) {
  let vSamples = cfg.vSamples || 16;
  let uBands = cfg.uBands || [];
  let bulgeAmp = cfg.bulgeAmp || 0;

  // Helper to sample surface at (u, v) with 3D cylindrical bulge
  function surfacePt(u, v) {
    let pTop = evalCatmullRom(topPts, v);
    let pBot = evalCatmullRom(botPts, v);
    let bx = lerp(pTop[0], pBot[0], u);
    let by = lerp(pTop[1], pBot[1], u);
    let dx = pBot[0] - pTop[0];
    let dy = pBot[1] - pTop[1];
    let len = Math.hypot(dx, dy) || 1;
    // Normal pointing along the cylinder axis / outward arch
    let nx = -dy / len;
    let ny = dx / len;
    let arch = Math.sin(u * Math.PI) * bulgeAmp;
    return [bx + nx * arch, by + ny * arch];
  }

  // 1. Sub-band washes and watercolor fills
  for (let b of uBands) {
    let poly = [];
    for (let i = 0; i <= vSamples; i++) {
      poly.push(surfacePt(b.u0, i / vSamples));
    }
    for (let i = vSamples; i >= 0; i--) {
      poly.push(surfacePt(b.u1, i / vSamples));
    }
    if (b.mode === "wash") {
      washPoly(poly, b.col, b.op, 0.12);
    } else {
      fillPoly(poly, b.col, b.op, b.bleed || 0.1, b.tex || 0.45, 0.15);
    }
  }

  // 2. Cross-contour strokes wrapping around the form (along u)
  if (cfg.crossCount && cfg.crossStyleFn) {
    for (let i = 0; i < cfg.crossCount; i++) {
      let v = constrain((i + random(-0.35, 0.35)) / cfg.crossCount, 0.02, 0.98);
      let uStart = cfg.crossU0 !== undefined ? cfg.crossU0 : 0.02;
      let uEnd = cfg.crossU1 !== undefined ? cfg.crossU1 : 0.98;
      let subU0 = constrain(uStart + random(-0.04, 0.08), 0, 0.9);
      let subU1 = constrain(uEnd + random(-0.08, 0.04), subU0 + 0.1, 1);
      let uMid = (subU0 + subU1) * 0.5;
      let st = cfg.crossStyleFn(uMid, v);
      if (!st) continue;
      brush.set(st.brush, st.col, st.weight);
      let sPts = [];
      let steps = 5;
      for (let s = 0; s <= steps; s++) {
        let u = lerp(subU0, subU1, s / steps);
        let vJitter = constrain(v + (noise(i * 0.3, s * 0.4) - 0.5) * 0.03, 0, 1);
        let p = surfacePt(u, vJitter);
        let pr = s === 0 || s === steps ? 0.3 : 1.1;
        sPts.push([p[0], p[1], pr]);
      }
      brush.spline(sPts, 0.45);
    }
  }

  // 3. Longitudinal strokes following the muscle/fabric grain (along v)
  if (cfg.longCount && cfg.longStyleFn) {
    for (let i = 0; i < cfg.longCount; i++) {
      let u = constrain(random(0.01, 0.99), 0.01, 0.99);
      let v0 = constrain(random(0, 0.65), 0, 0.85);
      let v1 = constrain(v0 + random(0.18, 0.55), v0 + 0.1, 1.0);
      let vMid = (v0 + v1) * 0.5;
      let st = cfg.longStyleFn(u, vMid);
      if (!st) continue;
      brush.set(st.brush, st.col, st.weight);
      let sPts = [];
      let steps = 5;
      for (let s = 0; s <= steps; s++) {
        let v = lerp(v0, v1, s / steps);
        let uJitter = constrain(u + (noise(i * 0.25, s * 0.5) - 0.5) * 0.035, 0, 1);
        let p = surfacePt(uJitter, v);
        let pr = s === 0 || s === steps ? 0.35 : 1.05;
        sPts.push([p[0], p[1], pr]);
      }
      brush.spline(sPts, 0.35);
    }
  }

  return surfacePt;
}

// ============================================================================
// 1. GYM BACKGROUND & BLURRED RING ROPES
// ============================================================================

function drawGymBackground() {
  // Deep murky gunmetal-green atmospheric cone from overhead gym fixture
  fillPoly(
    [[140, 0], [880, 0], [1120, 740], [80, 780]],
    PALETTE.gunmetalDark, 150, 0.45, 0.65, 0.2
  );
  fillPoly(
    [[260, 0], [740, 0], [920, 620], [180, 640]],
    PALETTE.gunmetalMid, 120, 0.48, 0.6, 0.25
  );
  fillPoly(
    [[340, 0], [640, 0], [760, 460], [280, 480]],
    PALETTE.gunmetalSlate, 85, 0.5, 0.55, 0.25
  );

  // Crushed dark corners in upper gym ceiling / walls
  washPoly([[0, 0], [260, 0], [150, 580], [0, 650]], PALETTE.crushBlack, 210);
  washPoly([[820, 0], [1200, 0], [1200, 720], [960, 580]], PALETTE.crushBlack, 210);

  // Blurred Ring Corner Pad & Turnbuckles on the left (x: 50..215, y: 20..560)
  washPoly([[45, 10], [195, 10], [225, 520], [70, 540]], PALETTE.deepShadow, 220);
  fillPoly([[75, 20], [185, 20], [210, 500], [95, 510]], PALETTE.voidBlack, 190, 0.35, 0.5);
  // Subtle silver-green rim glare on the right edge of the corner pad
  fillPoly([[172, 30], [198, 30], [222, 470], [195, 475]], PALETTE.gunmetalLight, 75, 0.35, 0.4);

  // Three sagging, out-of-focus boxing ring ropes cutting across the background
  const ropes = [
    {
      yLeft: 118, yMid: 152, yRight: 96, thick: 34,
      topCol: PALETTE.skinLight, midCol: PALETTE.gunmetalMid, botCol: PALETTE.voidBlack
    },
    {
      yLeft: 268, yMid: 304, yRight: 242, thick: 38,
      topCol: PALETTE.skinMid, midCol: PALETTE.gunmetalDark, botCol: PALETTE.voidBlack
    },
    {
      yLeft: 422, yMid: 456, yRight: 392, thick: 36,
      topCol: PALETTE.gunmetalLight, midCol: PALETTE.deepShadow, botCol: PALETTE.voidBlack
    }
  ];

  for (let idx = 0; idx < ropes.length; idx++) {
    let r = ropes[idx];
    let topSpine = [
      [180, r.yLeft],
      [460, r.yMid - 4],
      [790, r.yMid - 8],
      [1200, r.yRight]
    ];
    let botSpine = [
      [180, r.yLeft + r.thick],
      [460, r.yMid + r.thick - 4],
      [790, r.yMid + r.thick - 8],
      [1200, r.yRight + r.thick]
    ];

    // Turnbuckle hardware blur where rope meets corner pad
    washPoly([
      [145, r.yLeft - 8], [218, r.yLeft - 4],
      [222, r.yLeft + r.thick + 10], [148, r.yLeft + r.thick + 8]
    ], PALETTE.voidBlack, 210);
    fillPoly([
      [165, r.yLeft - 4], [212, r.yLeft - 2],
      [212, r.yLeft + 10], [165, r.yLeft + 8]
    ], PALETTE.skinMid, 95, 0.3, 0.4);

    // Out-of-focus rope washes
    renderVolumetricRibbon(topSpine, botSpine, {
      vSamples: 14,
      bulgeAmp: 4,
      uBands: [
        { u0: -0.15, u1: 0.35, col: r.topCol, op: 85, bleed: 0.42, tex: 0.5 },
        { u0: 0.15, u1: 0.65, col: r.midCol, op: 130, bleed: 0.38, tex: 0.5 },
        { u0: 0.45, u1: 1.15, col: r.botCol, op: 185, bleed: 0.38, tex: 0.5 }
      ],
      longCount: 45,
      longStyleFn: (u, v) => {
        if (u < 0.28) {
          return {
            brush: "charcoal",
            col: v > 0.15 && v < 0.65 ? PALETTE.skinPallid : PALETTE.skinMid,
            weight: random(1.4, 2.8)
          };
        } else if (u < 0.65) {
          return { brush: "charcoal", col: PALETTE.gunmetalMid, weight: random(1.8, 3.2) };
        }
        return { brush: "charcoal", col: PALETTE.voidBlack, weight: random(2.0, 3.5) };
      }
    });

    // Blurred tape markers wrapped around the ring ropes
    for (let tx of [330 + idx * 45, 720 - idx * 30, 980 + idx * 20]) {
      let tv = (tx - 180) / 1020;
      let pT = evalCatmullRom(topSpine, tv);
      let pB = evalCatmullRom(botSpine, tv);
      fillPoly([
        [pT[0] - 14, pT[1] - 2], [pT[0] + 14, pT[1] - 2],
        [pB[0] + 14, pB[1] + 2], [pB[0] - 14, pB[1] + 2]
      ], PALETTE.wrapMid, 65, 0.35, 0.4);
    }
  }

  // Murky vertical gym wall grime & distant pillar streaks
  brush.field("columns");
  brush.wiggle(2);
  for (let i = 0; i < 140; i++) {
    let x = random(0, 1200);
    let y = random(0, 620);
    let dFromLight = Math.hypot(x - 490, y - 160);
    let col = dFromLight < 320
      ? (random() < 0.45 ? PALETTE.gunmetalSlate : PALETTE.gunmetalMid)
      : (random() < 0.6 ? PALETTE.voidBlack : PALETTE.deepShadow);
    brush.set("charcoal", col, random(1.2, 3.4));
    brush.flowLine(x, y, random(60, 210), random(86, 94));
  }
  brush.noField();
}

