function drawTorsoShadowMass() {
  // Crushed black mass of the boxer's chest and lap behind the arms
  washPoly([
    [0, 520], [1200, 480], [1200, 1200], [0, 1200]
  ], PALETTE.voidBlack, 235, 0.05);

  massPoly([
    [80, 560], [640, 490], [1140, 540], [1200, 1200], [0, 1200]
  ], "charcoal", PALETTE.voidBlack, {
    precision: 0.3,
    strength: 0.85,
    gradient: 0.2,
    outline: false
  });

  // Faint sweaty chest / ribcage sheen deep in the background gap (x: 560..820, y: 420..580)
  fillPoly([
    [590, 450], [780, 440], [830, 580], [540, 610]
  ], PALETTE.gunmetalDark, 90, 0.35, 0.5);

  // Subtle waistband / boxing trunks fold hint deep in the lower shadow (y: 860..980)
  for (let i = 0; i < 45; i++) {
    let x = random(320, 880);
    let y = random(720, 1150);
    brush.set("charcoal", random() < 0.7 ? PALETTE.voidBlack : PALETTE.deepShadow, random(1.8, 3.6));
    brush.line(x, y, x + random(-60, 60), y + random(30, 110));
  }
}

