function drawLeftForearmAndFist() {
  // --- A. LEFT FOREARM (from bottom-left (-60, 740)..(80, 1080) up to wrist (310, 535)..(405, 695)) ---
  const faTop = [
    [-70, 745],
    [45, 672],
    [165, 602],
    [275, 550],
    [355, 522]
  ];
  const faBot = [
    [40, 1090],
    [160, 965],
    [265, 845],
    [355, 738],
    [425, 668]
  ];

  // Solid opaque foundation so background doesn't bleed through arm
  let faOutline = [...faTop, ...[...faBot].reverse()];
  washPoly(faOutline, PALETTE.skinCore, 250, 0.15);

  // Volumetric planes of the muscular forearm (brachioradialis, extensor ridge, ulna shadow)
  let faSurf = renderVolumetricRibbon(faTop, faBot, {
    vSamples: 18,
    bulgeAmp: -18,
    uBands: [
      { u0: 0.0, u1: 0.14, mode: "wash", col: PALETTE.skinPallid, op: 210 },
      { u0: 0.08, u1: 0.28, mode: "fill", col: PALETTE.skinLight, op: 175, bleed: 0.12, tex: 0.45 },
      { u0: 0.22, u1: 0.46, mode: "fill", col: PALETTE.skinMid, op: 180, bleed: 0.15, tex: 0.5 },
      { u0: 0.40, u1: 0.68, mode: "fill", col: PALETTE.skinMidDark, op: 195, bleed: 0.15, tex: 0.55 },
      { u0: 0.60, u1: 0.88, mode: "wash", col: PALETTE.skinShadow, op: 230 },
      { u0: 0.82, u1: 1.0, mode: "wash", col: PALETTE.voidBlack, op: 245 }
    ],
    crossCount: 165,
    crossStyleFn: (u, v) => {
      if (u < 0.16) return { brush: "2H", col: PALETTE.skinHighlight, weight: random(0.45, 0.85) };
      if (u < 0.35) return { brush: "HB", col: PALETTE.skinPallid, weight: random(0.55, 1.0) };
      if (u < 0.58) return { brush: "2B", col: PALETTE.skinMid, weight: random(0.65, 1.25) };
      if (u < 0.78) return { brush: "2B", col: PALETTE.skinCore, weight: random(0.8, 1.5) };
      return { brush: "charcoal", col: PALETTE.voidBlack, weight: random(1.1, 2.2) };
    },
    longCount: 140,
    longStyleFn: (u, v) => {
      if (u < 0.12) return { brush: "cpencil", col: PALETTE.silverMid, weight: random(0.4, 0.75) };
      if (u < 0.32) return { brush: "HB", col: PALETTE.skinLight, weight: random(0.5, 0.9) };
      if (u < 0.55) return { brush: "2B", col: PALETTE.skinMidDark, weight: random(0.6, 1.15) };
      return { brush: "charcoal", col: PALETTE.voidBlack, weight: random(1.0, 2.1) };
    }
  });

  // Extensor muscle furrow shadow running along u ≈ 0.36
  for (let i = 0; i < 45; i++) {
    let v0 = random(0.05, 0.75);
    let v1 = v0 + random(0.08, 0.22);
    let p0 = faSurf(0.36 + random(-0.03, 0.03), v0);
    let p1 = faSurf(0.38 + random(-0.03, 0.03), v1);
    brush.set("2B", PALETTE.skinCore, random(0.7, 1.3));
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // Skin constricting bulge just before the tight wrist wrap (v ≈ 0.78..0.86)
  for (let i = 0; i < 38; i++) {
    let u = random(0.03, 0.75);
    let p0 = faSurf(u, 0.76);
    let p1 = faSurf(u, 0.83);
    brush.set("2H", u < 0.35 ? PALETTE.skinHighlight : PALETTE.skinMid, random(0.4, 0.8));
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // --- B. SUBCUTANEOUS VEINS ON LEFT FOREARM ---
  const leftVeins = [
    // Main cephalic branch snaking along upper-mid forearm into wrist wrap
    [[-30, 775], [35, 725], [105, 682], [175, 632], [242, 598], [302, 568]],
    // Median branch forking off and diving under the lower wrist wrap
    [[105, 682], [162, 690], [225, 668], [288, 638], [335, 612]],
    // Dorsal tributary near upper ridge
    [[55, 678], [118, 642], [175, 632]],
    // Lower tributary
    [[162, 690], [205, 728], [268, 705], [322, 665]]
  ];

  for (let vPath of leftVeins) {
    drawAnatomicalVein(vPath, 4.5);
  }

  // --- C. UNWRAPPED SWOLLEN KNUCKLES & CURLED FINGERS OF LEFT FIST ---
  // The wrap covers the wrist, palm, thumb base, and dorsal MCP pad, while the swollen
  // proximal/middle phalanges and PIP joints of Index, Middle, Ring, and Pinky clench tightly on the right side of the fist.
  const fistBasePoly = [
    [480, 365], [565, 345], [625, 368], [672, 412],
    [682, 475], [658, 535], [595, 575], [475, 565]
  ];
  washPoly(fistBasePoly, PALETTE.skinCore, 250, 0.15);

  // Individual clenched fingers (from top/back Middle & Index down to Ring & Pinky, plus Thumb tucked in front)
  const clenchedFingers = [
    // Middle finger proximal-to-PIP ridge (highest crest of the fist)
    {
      top: [[525, 355], [575, 348], [622, 368], [652, 405]],
      bot: [[515, 392], [565, 388], [608, 408], [632, 438]],
      bruise: true
    },
    // Index finger (front-upper plane of the fist, pressed by the thumb)
    {
      top: [[495, 378], [552, 378], [604, 402], [635, 442]],
      bot: [[485, 432], [542, 436], [588, 458], [612, 488]],
      bruise: true
    },
    // Ring finger (stepping down behind middle finger)
    {
      top: [[585, 366], [628, 382], [662, 415], [675, 455]],
      bot: [[575, 405], [615, 422], [645, 452], [652, 482]],
      bruise: true
    },
    // Pinky finger (lowest outer edge of fist)
    {
      top: [[618, 412], [652, 435], [676, 468], [674, 505]],
      bot: [[598, 455], [632, 478], [652, 508], [642, 532]],
      bruise: false
    },
    // Tucked thumb tip & IP joint locking across the front of the fist
    {
      top: [[488, 512], [538, 492], [585, 484], [618, 495]],
      bot: [[495, 562], [548, 548], [592, 535], [615, 526]],
      bruise: false
    }
  ];

  for (let f of clenchedFingers) {
    renderVolumetricRibbon(f.top, f.bot, {
      vSamples: 12,
      bulgeAmp: -8,
      uBands: [
        { u0: 0.0, u1: 0.25, mode: "wash", col: PALETTE.skinPallid, op: 215 },
        { u0: 0.18, u1: 0.52, mode: "fill", col: f.bruise ? PALETTE.rawKnuckle : PALETTE.skinMid, op: 175, bleed: 0.12, tex: 0.5 },
        { u0: 0.45, u1: 0.78, mode: "fill", col: f.bruise ? PALETTE.bruiseMid : PALETTE.skinMidDark, op: 190, bleed: 0.12, tex: 0.5 },
        { u0: 0.70, u1: 1.0, mode: "wash", col: PALETTE.voidBlack, op: 235 }
      ],
      crossCount: 42,
      crossStyleFn: (u, v) => {
        if (u < 0.25) return { brush: "2H", col: PALETTE.skinHighlight, weight: random(0.35, 0.7) };
        if (u < 0.6) return { brush: "HB", col: f.bruise ? PALETTE.rawKnuckle : PALETTE.skinMid, weight: random(0.45, 0.85) };
        return { brush: "2B", col: PALETTE.voidBlack, weight: random(0.6, 1.2) };
      },
      longCount: 28,
      longStyleFn: (u, v) => {
        if (u < 0.22) return { brush: "cpencil", col: PALETTE.silverMid, weight: random(0.35, 0.65) };
        return { brush: "2B", col: PALETTE.skinCore, weight: random(0.5, 0.95) };
      }
    });

    // Deep inter-finger crease line at bottom of each finger
    brush.set("rotring", PALETTE.voidBlack, 1.1);
    let creasePts = f.bot.map(p => [p[0], p[1], 0.9]);
    brush.spline(creasePts, 0.35);

    // Concentric joint wrinkles at the PIP knuckle (v ≈ 0.68)
    let pJointTop = evalCatmullRom(f.top, 0.68);
    let pJointBot = evalCatmullRom(f.bot, 0.68);
    for (let w = -3; w <= 3; w++) {
      let wx = lerp(pJointTop[0], pJointBot[0], 0.45) + w * 2.5;
      let wy = lerp(pJointTop[1], pJointBot[1], 0.45) + w * 1.2;
      brush.set("2H", w % 2 === 0 ? PALETTE.skinCore : PALETTE.skinHighlight, 0.45);
      brush.arc(wx, wy, 9, -65, 65);
    }
  }

  // Deep shadow hollow in the clenched palm pocket (x: 545..635, y: 465..535)
  fillPoly([
    [545, 455], [612, 465], [635, 515], [565, 525]
  ], PALETTE.voidBlack, 225, 0.15, 0.5);
}

// Helper to draw raised subcutaneous veins with shadow trough, fleshy body, and silver crest
function drawAnatomicalVein(pts, baseWidth = 4.0) {
  let samples = 28;
  // 1. Dark shadow underside of vein
  for (let pass = 0; pass < 2; pass++) {
    let shadowSpline = [];
    for (let i = 0; i <= samples; i++) {
      let t = i / samples;
      let p = evalCatmullRom(pts, t);
      let w = Math.sin(t * Math.PI) * 1.1 + 0.3;
      shadowSpline.push([p[0] + 1.5 + pass * 0.8, p[1] + baseWidth * 0.55 + pass * 0.9, w]);
    }
    brush.set("2B", PALETTE.skinShadow, 0.85);
    brush.spline(shadowSpline, 0.4);
  }

  // 2. Fleshy midtone body of the vein
  let bodySpline = [];
  for (let i = 0; i <= samples; i++) {
    let t = i / samples;
    let p = evalCatmullRom(pts, t);
    let w = Math.sin(t * Math.PI) * 1.3 + 0.4;
    bodySpline.push([p[0], p[1], w]);
  }
  brush.set("HB", PALETTE.skinLight, 1.15);
  brush.spline(bodySpline, 0.4);

  // 3. Cross-skin micro-hatches bridging over the vein
  for (let i = 2; i < samples - 1; i++) {
    let t = i / samples;
    let p = evalCatmullRom(pts, t);
    let pNext = evalCatmullRom(pts, Math.min(1, t + 0.04));
    let ang = atan2(pNext[1] - p[1], pNext[0] - p[0]) + 90;
    let r = baseWidth * 1.15;
    brush.set("2H", i % 2 === 0 ? PALETTE.skinPallid : PALETTE.skinMidDark, 0.45);
    brush.line(
      p[0] - cos(ang) * r, p[1] - sin(ang) * r,
      p[0] + cos(ang) * r, p[1] + sin(ang) * r
    );
  }

  // 4. Metallic silver-pencil ridge along the top-lit crest of the vein
  let silverSpline = [];
  for (let i = 0; i <= samples; i++) {
    let t = i / samples;
    let p = evalCatmullRom(pts, t);
    let w = Math.sin(t * Math.PI) * 1.2 + 0.2;
    silverSpline.push([p[0] - 1.0, p[1] - baseWidth * 0.38, w]);
  }
  brush.set("silver_needle", PALETTE.silverBright, 0.95);
  brush.spline(silverSpline, 0.4);
}

