// Detailed hyperreal renderer for a single strip of cotton gauze / athletic tape
function drawGauzeBand(b) {
  // 1. Cast shadow underneath the band edges onto the underlying layer
  let shadowPoly = [];
  for (let i = 0; i <= 10; i++) {
    let p = evalCatmullRom(b.top, i / 10);
    shadowPoly.push([p[0] + 3, p[1] + 5]);
  }
  for (let i = 10; i >= 0; i--) {
    let p = evalCatmullRom(b.bot, i / 10);
    shadowPoly.push([p[0] + 4, p[1] + 6]);
  }
  fillPoly(shadowPoly, PALETTE.voidBlack, 150, 0.12, 0.4, 0.15);

  // 2. Opaque base wash + volumetric shading across the gauze strip
  let surf = renderVolumetricRibbon(b.top, b.bot, {
    vSamples: 16,
    bulgeAmp: b.bulge || -10,
    uBands: [
      { u0: 0.0, u1: 0.18, mode: "wash", col: PALETTE.wrapPeak, op: 245 },
      { u0: 0.12, u1: 0.36, mode: "wash", col: PALETTE.wrapBright, op: 235 },
      { u0: 0.28, u1: 0.54, mode: "fill", col: PALETTE.wrapDirtyWhite, op: 205, bleed: 0.08, tex: 0.45 },
      { u0: 0.46, u1: 0.72, mode: "fill", col: PALETTE.wrapLightGrey, op: 200, bleed: 0.1, tex: 0.5 },
      { u0: 0.65, u1: 0.86, mode: "fill", col: PALETTE.wrapMidDark, op: 215, bleed: 0.1, tex: 0.5 },
      { u0: 0.80, u1: 1.0, mode: "wash", col: PALETTE.wrapDeepShadow, op: 240 }
    ],
    // Herringbone cotton weave (cross threads)
    crossCount: 58,
    crossStyleFn: (u, v) => {
      if (u < 0.22) return { brush: "2H", col: PALETTE.wrapPure, weight: random(0.3, 0.6) };
      if (u < 0.52) return { brush: "2H", col: PALETTE.wrapMid, weight: random(0.35, 0.65) };
      if (u < 0.78) return { brush: "HB", col: PALETTE.wrapMidDark, weight: random(0.45, 0.8) };
      return { brush: "2B", col: PALETTE.voidBlack, weight: random(0.6, 1.1) };
    },
    // Tension wrinkles & warp threads along the tape length
    longCount: 46,
    longStyleFn: (u, v) => {
      if (u < 0.16) return { brush: "silver_needle", col: PALETTE.wrapPure, weight: random(0.5, 0.95) };
      if (u < 0.42) return { brush: "2H", col: PALETTE.wrapPeak, weight: random(0.4, 0.75) };
      if (u < 0.70) return { brush: "HB", col: PALETTE.wrapMid, weight: random(0.45, 0.85) };
      return { brush: "2B", col: PALETTE.wrapDeepShadow, weight: random(0.6, 1.1) };
    }
  });

  // 3. Sweat, grime, and dried blood stains bled into the cotton fibers
  if (b.stains) {
    for (let st of b.stains) {
      let center = surf(st.u, st.v);
      let stPoly = [];
      let ptsCount = 9;
      for (let k = 0; k < ptsCount; k++) {
        let ang = (k / ptsCount) * 360;
        let rad = st.r * random(0.6, 1.25);
        stPoly.push([center[0] + cos(ang) * rad, center[1] + sin(ang) * rad * 0.75]);
      }
      fillPoly(stPoly, st.col, 115, 0.28, 0.65, 0.3);
      // Gritty stain border hatch
      for (let h = 0; h < 14; h++) {
        let ang = random(360);
        let r1 = random(0, st.r * 0.8);
        brush.set("2B", st.col, random(0.35, 0.75));
        brush.line(
          center[0] + cos(ang) * r1,
          center[1] + sin(ang) * r1,
          center[0] + cos(ang) * (r1 + random(6, 14)),
          center[1] + sin(ang) * (r1 + random(6, 14))
        );
      }
    }
  }

  // 4. Crisp compression creases & edge seam definition
  for (let c = 0; c < 5; c++) {
    let uCrease = random(0.12, 0.82);
    let v0 = random(0.05, 0.35);
    let v1 = constrain(v0 + random(0.35, 0.6), 0.2, 0.95);
    let darkPts = [];
    let lightPts = [];
    for (let s = 0; s <= 5; s++) {
      let v = lerp(v0, v1, s / 5);
      let p = surf(uCrease, v);
      darkPts.push([p[0], p[1], s === 0 || s === 5 ? 0.2 : 0.9]);
      lightPts.push([p[0] - 1.2, p[1] - 1.8, s === 0 || s === 5 ? 0.2 : 1.0]);
    }
    brush.set("2B", uCrease < 0.5 ? PALETTE.wrapMidDark : PALETTE.wrapDeepShadow, 0.55);
    brush.spline(darkPts, 0.4);
    if (uCrease < 0.65) {
      brush.set("silver_needle", PALETTE.wrapPure, 0.75);
      brush.spline(lightPts, 0.4);
    }
  }

  // 5. Razor-sharp top/bottom edge outlines & frayed cotton fibers
  let edgeSamples = 18;
  for (let i = 0; i < edgeSamples; i++) {
    let v = i / edgeSamples;
    let pT = surf(0.0, v);
    let pB = surf(1.0, v);

    // Frayed whiskers along the selvedge edges of the gauze
    if (b.frayLeft && random() < 0.75) {
      brush.set("fray_thread", v < 0.65 ? PALETTE.wrapPure : PALETTE.wrapLightGrey, random(0.6, 1.1));
      let fLen = random(5, 16);
      let fAng = random(-155, -25);
      brush.line(pT[0], pT[1], pT[0] + cos(fAng) * fLen, pT[1] + sin(fAng) * fLen);
    }
    if (b.frayRight && random() < 0.7) {
      brush.set("fray_thread", v < 0.5 ? PALETTE.wrapBright : PALETTE.wrapMid, random(0.5, 1.0));
      let fLen = random(5, 15);
      let fAng = random(20, 150);
      brush.line(pB[0], pB[1], pB[0] + cos(fAng) * fLen, pB[1] + sin(fAng) * fLen);
    }
  }

  // Dark overlap shadow along the bottom/right edge of the gauze strip
  let botEdgePts = [];
  let topHighlightPts = [];
  for (let i = 0; i <= 10; i++) {
    let pB = surf(0.98, i / 10);
    let pT = surf(0.03, i / 10);
    botEdgePts.push([pB[0], pB[1], 0.85]);
    topHighlightPts.push([pT[0], pT[1], 1.0]);
  }
  brush.set("rotring", PALETTE.voidBlack, 0.75);
  brush.spline(botEdgePts, 0.35);
  brush.set("silver_needle", PALETTE.wrapPure, 1.05);
  brush.spline(topHighlightPts, 0.35);
}

// ============================================================================
// 5. HIGH-TENSION TAUT TAPE BRIDGE (BETWEEN LEFT WRIST & RIGHT HAND)
// ============================================================================

function drawTautTapeBridge() {
  // Stretches under fierce tension from the underside/front of the left wrist (392, 608)..(412, 666)
  // across the dark gap to the pinching right thumb & index finger at (762, 578)..(776, 614).
  const bridgeTop = [
    [392, 606],
    [515, 596],
    [645, 586],
    [766, 578]
  ];
  const bridgeBot = [
    [412, 666],
    [532, 646],
    [658, 628],
    [776, 612]
  ];

  // Deep dramatic contrast shadow immediately behind and below the taut white tape
  fillPoly([
    [388, 595], [775, 568], [785, 638], [405, 690]
  ], PALETTE.voidBlack, 220, 0.18, 0.5);

  // Volumetric body of the taut strip (narrows toward the right-hand pinch point!)
  let bridgeSurf = renderVolumetricRibbon(bridgeTop, bridgeBot, {
    vSamples: 20,
    bulgeAmp: -3,
    uBands: [
      { u0: 0.0, u1: 0.22, mode: "wash", col: PALETTE.wrapPure, op: 250 },
      { u0: 0.16, u1: 0.44, mode: "wash", col: PALETTE.wrapPeak, op: 240 },
      { u0: 0.38, u1: 0.68, mode: "fill", col: PALETTE.wrapDirtyWhite, op: 215, bleed: 0.06, tex: 0.45 },
      { u0: 0.60, u1: 0.85, mode: "fill", col: PALETTE.wrapMid, op: 215, bleed: 0.08, tex: 0.5 },
      { u0: 0.78, u1: 1.0, mode: "wash", col: PALETTE.wrapShadow, op: 240 }
    ],
    crossCount: 65,
    crossStyleFn: (u, v) => {
      if (u < 0.3) return { brush: "2H", col: PALETTE.wrapPure, weight: 0.38 };
      if (u < 0.7) return { brush: "2H", col: PALETTE.wrapLightGrey, weight: 0.42 };
      return { brush: "HB", col: PALETTE.wrapShadow, weight: 0.55 };
    },
    longCount: 55,
    longStyleFn: (u, v) => {
      if (u < 0.25) return { brush: "silver_needle", col: PALETTE.silverPure, weight: 0.85 };
      if (u < 0.6) return { brush: "2H", col: PALETTE.wrapPeak, weight: 0.5 };
      return { brush: "2B", col: PALETTE.wrapMidDark, weight: 0.65 };
    }
  });

  // Radiating high-tension stress pleats fanning out from the right hand's pinch at v=1.0
  const pleatU = [0.18, 0.34, 0.52, 0.68, 0.82];
  for (let pu of pleatU) {
    let shadowPleat = [];
    let highlightPleat = [];
    for (let s = 0; s <= 12; s++) {
      let v = s / 12;
      // Pleats converge tightly as v -> 1.0
      let uCurrent = lerp(pu, 0.48 + (pu - 0.5) * 0.35, Math.pow(v, 1.4));
      let p = bridgeSurf(uCurrent, v);
      let wave = Math.sin(v * 180) * 1.8;
      shadowPleat.push([p[0], p[1] + wave, 0.4 + v * 0.9]);
      highlightPleat.push([p[0], p[1] + wave - 1.8, 0.4 + v * 1.0]);
    }
    brush.set("2B", PALETTE.wrapMidDark, 0.65);
    brush.spline(shadowPleat, 0.35);
    brush.set("silver_needle", PALETTE.wrapPure, 0.95);
    brush.spline(highlightPleat, 0.35);
  }

  // Sweat & grime smudges on the taut strip
  fillPoly([
    bridgeSurf(0.25, 0.28), bridgeSurf(0.22, 0.46),
    bridgeSurf(0.68, 0.44), bridgeSurf(0.62, 0.25)
  ], PALETTE.stainSweat, 95, 0.22, 0.6);

  // Razor-sharp glowing top edge & frayed cotton threads peeling off the taut bridge
  let topBridgeEdge = [];
  for (let i = 0; i <= 16; i++) {
    let v = i / 16;
    let pT = bridgeSurf(0.02, v);
    topBridgeEdge.push([pT[0], pT[1], 1.1]);

    // Frayed loose threads curling upward and downward off the stretched edge
    if (random() < 0.85) {
      brush.set("fray_thread", PALETTE.wrapPure, random(0.65, 1.15));
      let curlPts = [
        [pT[0], pT[1], 1.0],
        [pT[0] + random(-12, 14), pT[1] - random(5, 16), 0.7],
        [pT[0] + random(-24, 24), pT[1] - random(8, 26), 0.2]
      ];
      brush.spline(curlPts, 0.5);
    }
    let pB = bridgeSurf(0.98, v);
    if (random() < 0.75) {
      brush.set("fray_thread", PALETTE.wrapLightGrey, random(0.55, 1.0));
      let curlPts = [
        [pB[0], pB[1], 1.0],
        [pB[0] + random(-10, 15), pB[1] + random(6, 18), 0.6],
        [pB[0] + random(-18, 22), pB[1] + random(14, 34), 0.15]
      ];
      brush.spline(curlPts, 0.5);
    }
  }
  brush.set("silver_needle", PALETTE.silverPure, 1.25);
  brush.spline(topBridgeEdge, 0.25);
}

