function drawSweatAndSilverHighlights() {
  // 1. Metallic silver pencil cross-hatching along the highest specular ridges of the forearms,
  //    knuckles, veins, tendons, and taut tape folds
  const specularZones = [
    // Left forearm upper brachioradialis ridge
    { x0: -10, y0: 715, x1: 270, y1: 558, spread: 24, count: 65, ang: -30 },
    // Unwrapped swollen knuckles on left fist
    { x0: 515, y0: 360, x1: 645, y1: 420, spread: 28, count: 55, ang: 22 },
    // Taut tape top ridge & pinch pleats
    { x0: 405, y0: 604, x1: 760, y1: 582, spread: 14, count: 75, ang: -4 },
    // Right hand dorsal tendons & index/middle knuckle arch
    { x0: 760, y0: 485, x1: 905, y1: 545, spread: 26, count: 60, ang: 25 },
    // Right forearm upper extensor ridge
    { x0: 935, y0: 585, x1: 1150, y1: 805, spread: 22, count: 55, ang: 44 }
  ];

  for (let z of specularZones) {
    for (let i = 0; i < z.count; i++) {
      let t = random(0, 1);
      let bx = lerp(z.x0, z.x1, t) + random(-z.spread, z.spread) * 0.4;
      let by = lerp(z.y0, z.y1, t) + random(-z.spread, z.spread);
      let len = random(8, 26);
      let a = z.ang + random(-14, 14);
      brush.set(
        random() < 0.6 ? "silver_needle" : "cpencil",
        random() < 0.45 ? PALETTE.silverPure : PALETTE.silverBright,
        random(0.45, 0.95)
      );
      brush.line(bx, by, bx + cos(a) * len, by + sin(a) * len);
    }
  }

  // 2. Individual hyperrealistic beads of sweat and trickling rivulets on the skin
  const sweatClusters = [
    // Left forearm sweat beads
    { cx: 95, cy: 675, rx: 85, ry: 45, count: 36 },
    { cx: 225, cy: 615, rx: 70, ry: 42, count: 32 },
    // Left fist swollen knuckles
    { cx: 585, cy: 405, rx: 55, ry: 38, count: 28 },
    // Right hand & wrist
    { cx: 835, cy: 525, rx: 55, ry: 40, count: 26 },
    { cx: 1035, cy: 735, rx: 75, ry: 48, count: 30 }
  ];

  for (let cl of sweatClusters) {
    for (let i = 0; i < cl.count; i++) {
      let sx = cl.cx + random(-cl.rx, cl.rx);
      let sy = cl.cy + random(-cl.ry, cl.ry);
      let rad = random(1.6, 4.2);

      // Tiny dark shadow underneath the sweat bead
      brush.set("rotring", PALETTE.voidBlack, 0.55);
      brush.arc(sx, sy + 0.8, rad, 15, 165);

      // Refracted dark interior top crescent
      brush.set("2B", PALETTE.skinShadow, 0.45);
      brush.arc(sx, sy, rad * 0.8, 195, 345);

      // Pinpoint metallic silver specular glint on upper-left of bead
      brush.set("silver_needle", PALETTE.silverPure, 1.15);
      brush.line(sx - rad * 0.4, sy - rad * 0.35, sx + rad * 0.25, sy - rad * 0.25);

      // Occasional trickling sweat rivulet running down the contour of the muscle
      if (random() < 0.22) {
        let rivPts = [];
        let rx = sx;
        let ry = sy + rad;
        for (let s = 0; s < 5; s++) {
          rivPts.push([rx, ry, s === 4 ? 1.3 : 0.65]);
          rx += random(-3, 5);
          ry += random(6, 14);
        }
        brush.set("2B", PALETTE.skinShadow, 0.45);
        brush.spline(rivPts.map(p => [p[0] + 1.2, p[1], p[2]]), 0.45);
        brush.set("silver_needle", PALETTE.silverBright, 0.85);
        brush.spline(rivPts, 0.45);
      }
    }
  }
}

