function drawPushedFilmGrain() {
  // 1. Harsh charcoal vignette crushing the outer perimeter and bottom edge into pitch black
  const vignetteZones = [
    // Top-left corner crush
    { x0: 0, y0: 0, x1: 280, y1: 320, count: 45 },
    // Top-right corner crush
    { x0: 920, y0: 0, x1: 1200, y1: 360, count: 45 },
    // Bottom-left under left forearm
    { x0: 0, y0: 960, x1: 420, y1: 1200, count: 55 },
    // Bottom-center deep lap void
    { x0: 360, y0: 820, x1: 840, y1: 1200, count: 65 }
  ];

  for (let vz of vignetteZones) {
    for (let i = 0; i < vz.count; i++) {
      let x = random(vz.x0, vz.x1);
      let y = random(vz.y0, vz.y1);
      let len = random(45, 130);
      let ang = random(-35, 35);
      brush.set("charcoal", PALETTE.voidBlack, random(1.8, 3.8));
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }
  }

  // 2. High-ISO pushed-film silver halide grain & gritty gym chalk/dust across the canvas
  for (let i = 0; i < 240; i++) {
    let gx = random(20, 1180);
    let gy = random(20, 1180);
    let isDarkGrain = random() < 0.62;
    let col = isDarkGrain
      ? (random() < 0.5 ? PALETTE.voidBlack : PALETTE.gunmetalDark)
      : (random() < 0.7 ? PALETTE.skinLight : PALETTE.silverDim);
    brush.set("pushed_grain", col, random(0.8, 1.9));
    brush.line(gx, gy, gx + random(-28, 28), gy + random(-28, 28));
  }

  // 3. Raw, scratchy dry-charcoal and graphite hatch incidents around the silhouette edges
  //    of the fists and forearms ("gritty edges and nothing pretty")
  const grittyEdges = [
    // Upper contour of left forearm
    [[-30, 725], [140, 615], [320, 530]],
    // Knuckle silhouette of left fist
    [[475, 372], [565, 348], [648, 392], [678, 468]],
    // Underside of taut tape bridge
    [[410, 668], [585, 638], [768, 614]],
    // Back of right gripping hand
    [[745, 512], [805, 462], [895, 502], [985, 635]]
  ];

  for (let edge of grittyEdges) {
    for (let i = 0; i < 36; i++) {
      let t = random(0, 1);
      let p = evalCatmullRom(edge, t);
      let jitterX = p[0] + random(-8, 8);
      let jitterY = p[1] + random(-8, 8);
      let ang = random(360);
      let len = random(6, 22);
      brush.set(
        random() < 0.5 ? "charcoal" : "2B",
        random() < 0.65 ? PALETTE.voidBlack : PALETTE.gunmetalSlate,
        random(0.5, 1.35)
      );
      brush.line(jitterX, jitterY, jitterX + cos(ang) * len, jitterY + sin(ang) * len);
    }
  }
}

