  { type: "upright", angle: -12, colors: ["crimsonCool", "cream"], fullness: 0.96, wind: "concentric", tail: "snipped", nest: 0.25, label: "V-02", pin: false },
  { type: "spindle", angle: -44, colors: ["cream", "slateIndigo", "mustard"], fullness: 0.80, wind: "diamond", tail: "loose", nest: 0.45, label: "V-03", pin: false },
  { type: "bobbin", angle: 0, colors: ["black"], fullness: 0.91, wind: "cross", tail: "loose", nest: 0.5, label: "V-04", pin: true },
  { type: "bobbin", angle: 86, colors: ["cochineal", "ochre", "cream"], fullness: 0.87, wind: "parallel", tail: "snipped", nest: 0.2, label: "V-05", pin: false }
];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(40921);
  noiseSeed(88317);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.bgDeep);

  // 1. Render outer dark archival border
  drawOuterMat();

  // 2. Render all 25 compartment floors and their recessed wood grain
  drawAllCompartmentFloors();

  // 3. Render the 25 spools, winding cards, snipped tails, and unwound nests
  for (let r = 0; r < GRID_COUNT; r++) {
    for (let c = 0; c < GRID_COUNT; c++) {
      let idx = r * GRID_COUNT + c;
      let cx = INNER_START + c * (CELL_SIZE + DIVIDER);
      let cy = INNER_START + r * (CELL_SIZE + DIVIDER);
      drawCompartmentContents(r, c, cx, cy, CELL_SIZE, CELLS[idx]);
    }
  }

  // 4. Render the wooden grid dividers, lap joints, and outer cabinet frame
  drawWoodenGridAndFrame();

  // 5. Render a few delicate stray thread filaments crossing over the wooden dividers
  drawCrossDividerThreads();

  noLoop();
}

// ============================================================================
// 1. OUTER MAT & COMPARTMENT FLOORS
// ============================================================================

function drawOuterMat() {
  brush.noFill();
  brush.noWash();
  brush.set("charcoal", "#0b0e12", 1.2);
  for (let i = 0; i < 4; i++) {
    let off = 4 + i * 5;
    brush.rect(off, off, 1200 - off * 2, 1200 - off * 2);
  }
}

function drawAllCompartmentFloors() {
  // Batch base washes for the 25 cells
  brush.noStroke();
  for (let r = 0; r < GRID_COUNT; r++) {
    for (let c = 0; c < GRID_COUNT; c++) {
      let cx = INNER_START + c * (CELL_SIZE + DIVIDER);
      let cy = INNER_START + r * (CELL_SIZE + DIVIDER);
      let col = PALETTE.floorBase[(r * 3 + c * 2) % PALETTE.floorBase.length];
      brush.wash(col, 235);
      brush.rect(cx, cy, CELL_SIZE, CELL_SIZE);
    }
  }
  brush.noWash();

  // Continuous horizontal plank grain running behind the compartments
  for (let r = 0; r < GRID_COUNT; r++) {
    let plankSeed = r * 137;
    let cy = INNER_START + r * (CELL_SIZE + DIVIDER);

    for (let c = 0; c < GRID_COUNT; c++) {
      let cx = INNER_START + c * (CELL_SIZE + DIVIDER);

      // Base hatch pass for wood texture
      brush.noStroke();
      brush.hatchStyle("cpencil", PALETTE.floorGrainMid[(r + c) % PALETTE.floorGrainMid.length], 0.55);
      brush.hatch(5.5, 0.5 * (r % 2 === 0 ? 1 : -1), { rand: 0.04 });
      brush.rect(cx + 2, cy + 2, CELL_SIZE - 4, CELL_SIZE - 4);
      brush.noHatch();

      // Directional colored-pencil wood grain fibers
      let numGrain = 34;
      for (let i = 0; i < numGrain; i++) {
        let t = i / (numGrain - 1);
        let y = cy + 4 + t * (CELL_SIZE - 8);
        let nVal = noise((cx + 50) * 0.005, y * 0.03 + plankSeed);

        let gCol;
        let w = 0.45;
        if (nVal < 0.36) {
          gCol = random(PALETTE.floorGrainDark);
          w = 0.6;
        } else if (nVal < 0.72) {
          gCol = random(PALETTE.floorGrainMid);
          w = 0.45;
        } else {
          gCol = random(PALETTE.floorGrainLight);
          w = 0.35;
        }

        brush.set("cpencil", gCol, w);
        let waveAmp = sin(t * 180) * 4.5;
        let pts = [
          [cx + 2, y + noise(cx * 0.01, y * 0.05) * 2 - 1],
          [cx + CELL_SIZE * 0.35, y + waveAmp * 0.6 + (noise(cx + 40, y * 0.04) - 0.5) * 3],
          [cx + CELL_SIZE * 0.7, y + waveAmp * 0.9 + (noise(cx + 90, y * 0.04) - 0.5) * 3],
          [cx + CELL_SIZE - 2, y + (noise(cx + 140, y * 0.04) - 0.5) * 2]
        ];
        brush.spline(pts, 0.4);
      }

      // Recessed ambient occlusion hatching along all 4 inner walls of the cell
      drawCellCornerShading(cx, cy, CELL_SIZE);
    }
  }
}

function drawCellCornerShading(cx, cy, s) {
  brush.set("2B", "#0e1217", 0.55);
  // Top & Left inner shadow
  for (let i = 0; i < 9; i++) {
    let d = 1.5 + i * 2.1;
    if (i < 6) {
      brush.line(cx + 2, cy + d, cx + s - 2, cy + d);
      brush.line(cx + d, cy + 2, cx + d, cy + s - 2);
    }
    // Bottom & Right softer AO
    if (i < 5) {
      brush.line(cx + 2, cy + s - d * 0.8, cx + s - 2, cy + s - d * 0.8);
      brush.line(cx + s - d * 0.8, cy + 2, cx + s - d * 0.8, cy + s - 2);
    }
  }
}

// ============================================================================
// 2. COMPARTMENT CONTENTS (LABELS, NESTS, SPOOLS, PINS)
// ============================================================================

function drawCompartmentContents(r, c, cx, cy, s, spec) {
  let centerX = cx + s / 2;
  let centerY = cy + s / 2;

  // Tiny archival paper inventory tag glued in one corner of the cell floor
  drawArchivalCornerTag(cx, cy, s, r, c, spec.label);

  // Half-unwound thread nest on the floor beneath the spool
  if (spec.nest > 0.05) {
    let primaryThread = PALETTE.threads[spec.colors[0]];
    let secondaryThread = spec.colors.length > 1 ? PALETTE.threads[spec.colors[1]] : primaryThread;
    drawUnwoundNest(cx, cy, s, spec.nest, primaryThread, secondaryThread, spec.angle);
  }

  // Dispatch spool / card type
  if (spec.type === "bobbin") {
    drawTurnedBobbin(centerX, centerY, s, spec, false);
  } else if (spec.type === "spindle") {
    drawTurnedBobbin(centerX, centerY, s, spec, true);
  } else if (spec.type === "upright") {
    drawUprightSpool(centerX, centerY, s, spec);
  } else if (spec.type === "card") {
    drawTocapuWindingCard(centerX, centerY, s, spec);
  }

  // Optional tiny dressmaker's brass/steel pin stuck into the thread
  if (spec.pin) {
    drawArchivePin(centerX, centerY, spec.angle);
  }
}

function drawArchivalCornerTag(cx, cy, s, r, c, labelText) {
  // Position alternates neatly by cell parity
  let tx = (r + c) % 2 === 0 ? cx + 10 : cx + s - 38;
  let ty = r % 2 === 0 ? cy + s - 22 : cy + 10;
  let tw = 28;
  let th = 13;

  brush.noStroke();
  brush.wash("#cfc9b8", 210);
  brush.rect(tx, ty, tw, th);
  brush.noWash();

  // Paper border & aged edge
  brush.set("2H", "#6e6859", 0.35);
  brush.rect(tx, ty, tw, th);

  // Reddish or black archival tick marks simulating tiny catalog typography
  let inkCol = (r + c) % 3 === 0 ? "#6e1727" : "#1c222b";
  brush.set("rotring", inkCol, 0.35);
  brush.line(tx + 3, ty + 3, tx + tw - 3, ty + 3);
  brush.line(tx + 3, ty + th - 3, tx + tw - 3, ty + th - 3);

  // Simulated Roman/numeric glyph strokes
  for (let i = 0; i < 4; i++) {
    let gx = tx + 5 + i * 4.8;
    brush.line(gx, ty + 5, gx + (i % 2 === 0 ? 0 : 2), ty + th - 5);
  }
}

// ============================================================================
// 3. UNWOUND THREAD NESTS & SNIPPED TAILS
// ============================================================================

function drawUnwoundNest(cx, cy, s, density, threadA, threadB, baseAngle) {
  let numLoops = floor(map(density, 0.05, 0.9, 6, 34));
  let pad = 16;

  // Bias the nest toward one or two corners of the cell
  let biasX = cx + s * (cos(baseAngle + 45) > 0 ? 0.62 : 0.38);
  let biasY = cy + s * (sin(baseAngle + 45) > 0 ? 0.62 : 0.38);

  for (let i = 0; i < numLoops; i++) {
    let th = i % 4 === 0 ? threadB : threadA;
    let pts = [];
    let numPts = 5;

    let startX = constrain(biasX + random(-s * 0.36, s * 0.36), cx + pad, cx + s - pad);
    let startY = constrain(biasY + random(-s * 0.36, s * 0.36), cy + pad, cy + s - pad);
    let curX = startX;
    let curY = startY;
    let ang = random(360);

    for (let p = 0; p < numPts; p++) {
      pts.push([curX, curY]);
      ang += random(-110, 110);
      let step = random(18, 42);
      curX = constrain(curX + cos(ang) * step, cx + pad * 0.7, cx + s - pad * 0.7);
      curY = constrain(curY + sin(ang) * step, cy + pad * 0.7, cy + s - pad * 0.7);
    }

    // 1. Cast shadow on compartment floor
    let shadowPts = pts.map(pt => [pt[0] + 1.8, pt[1] + 2.2]);
    brush.set("2B", "#0f1318", 0.55);
    brush.spline(shadowPts, 0.65);

    // 2. Main colored-pencil filament
    let mainCol = i % 3 === 0 ? th.dark : (i % 2 === 0 ? th.mid : th.bright);
    brush.set("cpencil", mainCol, 0.55);
    brush.spline(pts, 0.65);

    // 3. Crisp silk/alpaca highlight on upper loops
    if (i > numLoops * 0.45) {
      let hiPts = pts.slice(1, 4).map(pt => [pt[0] - 0.3, pt[1] - 0.3]);
      brush.set("2H", i % 2 === 0 ? th.light : th.sheen, 0.35);
      brush.spline(hiPts, 0.65);
    }
  }
}

function drawSnippedTail(x1, y1, x2, y2, mx, my, threadObj) {
  let pts = [
    [x1, y1],
    [mx, my],
    [x2, y2]
  ];
  let shadowPts = pts.map(p => [p[0] + 1.6, p[1] + 2.0]);

  brush.set("2B", "#0d1015", 0.6);
  brush.spline(shadowPts, 0.55);

  brush.set("cpencil", threadObj.mid, 0.7);
  brush.spline(pts, 0.55);

  brush.set("2H", threadObj.sheen, 0.38);
  brush.spline(pts, 0.55);
}

// ============================================================================
// 4. TURNED WOODEN BOBBINS & CONICAL ANDEAN SPINDLE-BOBBINS
// ============================================================================

function drawTurnedBobbin(cx, cy, cellSpan, spec, isSpindle) {
  push();
  translate(cx, cy);
  rotate(spec.angle);

  let isDiag = abs(abs(spec.angle) - 45) < 15;
  let totalLen = isSpindle ? (isDiag ? 168 : 152) : (isDiag ? 148 : 136);
  let flangeR = isSpindle ? 28 : 38;
  let flangeThick = isSpindle ? 14 : 16;
  let coreLen = totalLen - flangeThick * 2;
  let threadR = map(spec.fullness, 0.4, 1.0, flangeR * 0.46, flangeR * 0.93);

  // 1. Cast shadow beneath bobbin on the floor
  brush.noStroke();
  brush.wash("#0e1217", 175);
  brush.rect(-totalLen * 0.48 + 4, -flangeR * 0.85 + 5, totalLen * 0.96, flangeR * 1.7);
  brush.noWash();

  brush.set("2B", "#0b0e13", 0.7);
  for (let sy = -flangeR + 3; sy <= flangeR + 5; sy += 3.2) {
    let sxSpan = (abs(sy) > threadR + 2) ? totalLen * 0.5 : totalLen * 0.47;
    brush.line(-sxSpan + 3, sy, sxSpan + 5, sy);
  }

  // 2. If spindle, draw protruding turned wooden spindle tips at both ends
  if (isSpindle) {
    drawSpindleTips(totalLen, flangeR);
  }

  // 3. Draw wooden flanges at left and right ends
  drawBobbinFlange(-totalLen / 2, flangeThick, flangeR, true, isSpindle);
  drawBobbinFlange(totalLen / 2 - flangeThick, flangeThick, flangeR, false, isSpindle);

  // 4. If low fullness, show glimpses of the turned wood barrel under the thread
  if (spec.fullness < 0.6) {
    drawExposedWoodBarrel(-coreLen / 2, coreLen, flangeR * 0.36);
  }

  // 5. Render the wound thread barrel (single or multi-band Tocapu stripes)
  let numBands = spec.colors.length;
  let bandLen = coreLen / numBands;

  for (let b = 0; b < numBands; b++) {
    let bx = -coreLen / 2 + b * bandLen;
    let th = PALETTE.threads[spec.colors[b]];
    drawWoundThreadBand(bx, bandLen, threadR, th, spec.wind, b, numBands);
  }

  // 6. Snipped thread tail emerging from flange notch or barrel
  let tailThread = PALETTE.threads[spec.colors[0]];
  if (spec.tail === "snipped") {
    // Notch on right flange
    brush.set("rotring", "#1a1410", 0.55);
    brush.line(totalLen / 2 - flangeThick * 0.8, -flangeR * 0.55, totalLen / 2 - 2, -flangeR * 0.58);
    drawSnippedTail(
      totalLen / 2 - flangeThick * 0.5, -flangeR * 0.55,
      totalLen / 2 + 16, -flangeR * 0.15,
      totalLen / 2 + 9, -flangeR * 0.45,
      tailThread
    );
  } else {
    drawSnippedTail(
      0, threadR * 0.85,
      -coreLen * 0.35, flangeR + 22,
      -coreLen * 0.15, flangeR + 14,
      tailThread
    );
  }

  pop();
}

function drawSpindleTips(totalLen, flangeR) {
  let tipLen = 17;
  let tipR = 8.5;
  for (let side of [-1, 1]) {
    let xStart = side === -1 ? -totalLen / 2 - tipLen : totalLen / 2;
    brush.noStroke();
    brush.wash(PALETTE.spoolWood.base, 230);
    brush.rect(xStart, -tipR, tipLen, tipR * 2);
    brush.noWash();

    for (let y = -tipR; y <= tipR; y += 1.6) {
      let n = y / tipR;
      let col = getCylinderWoodColor(n);
      brush.set("cpencil", col, 0.48);
      let inset = abs(n) * 3.5;
      let x0 = side === -1 ? xStart + inset : xStart;
      let x1 = side === -1 ? xStart + tipLen : xStart + tipLen - inset;
      brush.line(x0, y, x1, y);
    }
    // Turned decorative dark ring on spindle tip
    let rx = side === -1 ? xStart + tipLen * 0.45 : xStart + tipLen * 0.55;
    brush.set("rotring", PALETTE.spoolWood.dark, 0.45);
    brush.line(rx, -tipR + 1, rx, tipR - 1);
  }
}

function drawBobbinFlange(x, w, r, isLeft, isSpindle) {
  // Base wash
  brush.noStroke();
  brush.wash(PALETTE.spoolWood.base, 235);
  brush.rect(x, -r, w, r * 2);
  brush.noWash();

  // Cylindrical shading & fine wood grain across the turned flange
  let step = 1.4;
  for (let y = -r; y <= r; y += step) {
    let normY = y / r; // -1 to 1
    let col = getCylinderWoodColor(normY);

    // Tapered bevel on outer edge
    let bevel = pow(abs(normY), 3) * (isSpindle ? 4.5 : 2.5);
    let x0 = isLeft ? x + bevel : x + bevel * 0.4;
    let x1 = isLeft ? x + w - bevel * 0.4 : x + w - bevel;

    brush.set("cpencil", col, 0.5);
    brush.line(x0, y, x1, y);

    // Specular wood sheen band near normY = -0.35
    if (normY > -0.48 && normY < -0.18) {
      brush.set("2H", PALETTE.spoolWood.highlight, 0.4);
      brush.line(x0 + 1, y, x1 - 1, y);
    }
  }

  // Turned lathe grooves running vertically down the flange
  brush.set("2B", PALETTE.spoolWood.dark, 0.45);
  let gx = isLeft ? x + w * 0.35 : x + w * 0.65;
  brush.line(gx, -r + 2, gx, r - 2);

  // Crisp inner edge shadow where flange meets the thread
  let innerX = isLeft ? x + w : x;
  brush.set("rotring", "#17120e", 0.5);
  brush.line(innerX, -r + 1, innerX, r - 1);
}

function drawExposedWoodBarrel(x, len, r) {
  brush.noStroke();
  brush.wash(PALETTE.spoolWood.mid, 230);
  brush.rect(x, -r, len, r * 2);
  brush.noWash();

  for (let y = -r; y <= r; y += 1.8) {
    let col = getCylinderWoodColor(y / r);
    brush.set("cpencil", col, 0.45);
    brush.line(x, y, x + len, y);
  }
}

function getCylinderWoodColor(normY) {
  // Light comes from flat overhead, slightly biased toward -0.3
  let d = abs(normY + 0.28);
  if (d < 0.22) return PALETTE.spoolWood.light;
  if (d < 0.48) return PALETTE.spoolWood.warm;
  if (d < 0.78) return PALETTE.spoolWood.base;
  if (d < 1.02) return PALETTE.spoolWood.mid;
  return PALETTE.spoolWood.dark;
}

function drawWoundThreadBand(bx, bLen, r, th, windMode, bandIdx, totalBands) {
  // 1. Base wash for deep pigment body
  brush.noStroke();
  brush.wash(th.wash, 240);
  brush.rect(bx, -r, bLen, r * 2);
  brush.noWash();

  // 2. Longitudinal cylindrical shading bed (dense colored-pencil base)
  for (let y = -r; y <= r; y += 2.0) {
    let normY = y / r;
    let d = abs(normY + 0.25);
    let shadeCol = d < 0.28 ? th.bright : (d < 0.65 ? th.mid : (d < 0.95 ? th.dark : th.deep));
    brush.set("cpencil", shadeCol, 0.58);
    brush.line(bx + 0.5, y, bx + bLen - 0.5, y);
  }

  // 3. Individual wrapped filament strokes across the cylinder
  let numStrands = floor(bLen * 1.35);
  for (let i = 0; i <= numStrands; i++) {
    let t = i / numStrands;
    let sx = bx + 1.5 + t * (bLen - 3);

    // Slight profile bulge in the middle of each thread band
    let bulge = sin(t * 180) * 1.8;
    let curR = r + bulge;

    // Angle of the thread wrap
    let tilt = 0;
    if (windMode === "cross") {
      tilt = (i % 2 === 0 ? 1 : -1) * 7.5;
    } else if (windMode === "diamond") {
      tilt = sin(t * 360 * 1.5) * 11;
    } else {
      tilt = random(-2.2, 2.2);
    }

    let xTop = constrain(sx - tilt, bx + 0.5, bx + bLen - 0.5);
    let xBot = constrain(sx + tilt, bx + 0.5, bx + bLen - 0.5);
    let xMid = (xTop + xBot) * 0.5 + 1.8; // Cylindrical curvature bow

    // Main filament stroke (dark to mid)
    let strokeCol = i % 3 === 0 ? th.dark : (i % 2 === 0 ? th.mid : th.bright);
    brush.set("cpencil", strokeCol, 0.45);
    brush.spline([[xTop, -curR], [xMid, 0], [xBot, curR]], 0.45);

    // Deep shadow at bottom curve of the cylinder
    brush.set("2B", th.deep, 0.42);
    brush.line(lerp(xMid, xBot, 0.45), curR * 0.45, xBot, curR);

    // Top-crown anisotropic thread sheen
    if (i % 2 === 0) {
      let sy1 = -curR * 0.62;
      let sy2 = -curR * 0.05;
      let sx1 = lerp(xTop, xMid, 0.38);
      let sx2 = lerp(xTop, xMid, 0.95);
      brush.set("2H", i % 4 === 0 ? th.sheen : th.light, 0.4);
      brush.line(sx1, sy1, sx2, sy2);
    }
  }

  // 4. Extra diamond/criss-cross over-threads for precision-wound spools
  if (windMode === "cross" || windMode === "diamond") {
    let numCross = floor(bLen * 0.38);
    for (let k = 0; k < numCross; k++) {
      let cx0 = bx + random(2, bLen - 14);
      let cx1 = cx0 + random(8, 14);
      let dir = k % 2 === 0 ? 1 : -1;
      brush.set("cpencil", k % 3 === 0 ? th.light : th.mid, 0.38);
      brush.line(cx0, -r * 0.85 * dir, cx1, r * 0.85 * dir);
    }
  }

  // 5. Divider line between adjacent multi-color bands
  if (bandIdx > 0 && totalBands > 1) {
    brush.set("2B", "#12151a", 0.5);
    brush.line(bx, -r, bx, r);
  }
}

// ============================================================================
// 5. UPRIGHT SPOOLS (OVERHEAD CIRCULAR VIEW WITH ANDEAN LABEL)
// ============================================================================

function drawUprightSpool(cx, cy, cellSpan, spec) {
  push();
  translate(cx, cy);
  rotate(spec.angle);

  let outerR = 68;
  let threadPeekR = 73;
  let labelR = 40;
  let holeR = 11;
  let mainThread = PALETTE.threads[spec.colors[0]];
  let accentThread = PALETTE.threads[spec.colors[1 % spec.colors.length]];

  // 1. Soft circular contact shadow on compartment floor
  brush.noStroke();
  brush.wash("#0d1117", 190);
  brush.circle(4, 5, outerR + 6);
  brush.noWash();

  // 2. Thread filaments peeking out from underneath the top wooden flange
  for (let a = 0; a < 360; a += 3) {
    let rad = threadPeekR + sin(a * 7) * 1.8;
    let x0 = cos(a) * (outerR - 3);
    let y0 = sin(a) * (outerR - 3);
    let x1 = cos(a + 6) * rad;
    let y1 = sin(a + 6) * rad;
    let cCol = a % 6 === 0 ? mainThread.light : (a % 4 === 0 ? mainThread.mid : mainThread.dark);
    brush.set("cpencil", cCol, 0.5);
    brush.line(x0, y0, x1, y1);
  }

  // 3. Wooden top flange base wash
  brush.noStroke();
  brush.wash(PALETTE.spoolWood.base, 240);
  brush.circle(0, 0, outerR);
  brush.noWash();

  // 4. Wood grain hatching across the circular wooden top
  brush.noStroke();
  brush.hatchStyle("cpencil", PALETTE.spoolWood.mid, 0.5);
  brush.hatch(3.2, 12, { rand: 0.04 });
  brush.circle(0, 0, outerR - 1);
  brush.noHatch();

  brush.hatchStyle("2H", PALETTE.spoolWood.light, 0.38);
  brush.hatch(5.0, 14, { rand: 0.03 });
  brush.circle(-3, -3, outerR - 6);
  brush.noHatch();

  // 5. Concentric lathe turning rings on the wood flange
  let rings = [outerR - 1, outerR - 5, outerR - 11, labelR + 3];
  for (let i = 0; i < rings.length; i++) {
    let rr = rings[i];
    brush.set("cpencil", i % 2 === 0 ? PALETTE.spoolWood.dark : PALETTE.spoolWood.endGrain, 0.48);
    brush.arc(0, 0, rr, 0, 360);
  }
  // Chamfer highlight arc on upper-left rim
  brush.set("2H", PALETTE.spoolWood.highlight, 0.55);
  brush.arc(0, 0, outerR - 2.5, 195, 330);

  // 6. Vintage cream paper spool label with Tocapu geometric border
  brush.noStroke();
  brush.wash(PALETTE.threads.cream.bright, 245);
  brush.circle(0, 0, labelR);
  brush.noWash();

  // Paper texture hatch
  brush.hatchStyle("2H", PALETTE.threads.cream.light, 0.35);
  brush.hatch(3.5, -30, { rand: 0.02 });
  brush.circle(0, 0, labelR - 1);
  brush.noHatch();

  // Printed Andean geometric rings & radial ticks on the label
  brush.set("rotring", mainThread.dark, 0.5);
  brush.arc(0, 0, labelR - 2, 0, 360);
  brush.arc(0, 0, labelR - 9, 0, 360);

  brush.set("cpencil", accentThread.mid, 0.55);
  brush.arc(0, 0, labelR - 5.5, 0, 360);

  // Stepped geometric Tocapu blocks around the label ring
  for (let a = 0; a < 360; a += 15) {
    let rIn = labelR - 9;
    let rOut = labelR - 2.5;
    let col = (a / 15) % 2 === 0 ? mainThread.mid : accentThread.dark;
    brush.set("rotring", col, 0.5);
    brush.line(cos(a) * rIn, sin(a) * rIn, cos(a) * rOut, sin(a) * rOut);
  }

  // Tiny calligraphic numerals/marks around the inner ring
  brush.set("rotring", "#1a1e24", 0.35);
  for (let a = 20; a < 340; a += 45) {
    let rm = (labelR - 10 + holeR + 4) * 0.5;
    brush.line(cos(a) * (rm - 2), sin(a) * (rm - 2), cos(a + 6) * (rm + 2), sin(a + 6) * (rm + 2));
    brush.line(cos(a + 4) * (rm - 2), sin(a + 4) * (rm - 2), cos(a - 2) * (rm + 2), sin(a - 2) * (rm + 2));
  }

  // 7. Central dark bore hole of the spool
  brush.noStroke();
  brush.wash("#0e1116", 250);
  brush.circle(0, 0, holeR);
  brush.noWash();

  brush.set("2B", "#07090c", 0.65);
  for (let h = -holeR + 2; h <= holeR - 2; h += 2.2) {
    let hw = sqrt(max(0, holeR * holeR - h * h));
    brush.line(-hw, h, hw, h);
  }
  brush.set("rotring", PALETTE.spoolWood.dark, 0.5);
  brush.arc(0, 0, holeR, 0, 360);

  // 8. Snipped tail emerging from under the upright spool
  drawSnippedTail(
    outerR * 0.7, outerR * 0.65,
    outerR + 18, outerR * 0.15,
    outerR + 12, outerR * 0.55,
    mainThread
  );

  pop();
}

// ============================================================================
// 6. TOCAPU GEOMETRIC WINDING CARDS
// ============================================================================

function drawTocapuWindingCard(cx, cy, cellSpan, spec) {
  push();
  translate(cx, cy);
  rotate(spec.angle);

  let cardS = 64; // Half-size of the winding card
  let notch = 16;

  // 1. Shadow of the winding card
  brush.noStroke();
  brush.wash("#0d1117", 185);
  brush.rect(-cardS + 4, -cardS + 5, cardS * 2, cardS * 2);
  brush.noWash();

  // 2. Exposed cream/ochre archival pressboard corners (4 notched tabs)
  let cornerCoords = [
    [-cardS, -cardS],
    [cardS - notch * 1.6, -cardS],
    [-cardS, cardS - notch * 1.6],
    [cardS - notch * 1.6, cardS - notch * 1.6]
  ];
  for (let cc of cornerCoords) {
    brush.noStroke();
    brush.wash("#bfb8a6", 240);
    brush.rect(cc[0], cc[1], notch * 1.6, notch * 1.6);
    brush.noWash();

    brush.set("cpencil", "#8c8470", 0.45);
    for (let ly = cc[1] + 2; ly < cc[1] + notch * 1.6; ly += 2.5) {
      brush.line(cc[0] + 1, ly, cc[0] + notch * 1.6 - 1, ly);
    }
    brush.set("rotring", "#4a4438", 0.4);
    brush.rect(cc[0], cc[1], notch * 1.6, notch * 1.6);
  }

  // 3. Crisscrossed Tocapu geometric thread wraps across the card
  // Outer band (vertical wrap)
  let c0 = PALETTE.threads[spec.colors[0]];
  let c1 = PALETTE.threads[spec.colors[1 % spec.colors.length]];
  let c2 = PALETTE.threads[spec.colors[2 % spec.colors.length]];

  let wSpan = cardS - notch * 0.7;

  // Vertical outer wrap
  drawCardFilamentBlock(-wSpan, -cardS + 4, wSpan * 2, (cardS - 4) * 2, c0, true);

  // Horizontal middle wrap (creates woven Tocapu cross)
  drawCardFilamentBlock(-cardS + 4, -wSpan * 0.78, (cardS - 4) * 2, wSpan * 1.56, c1, false);

  // Inner concentric square diamond wrap
  let innerS = wSpan * 0.55;
  drawCardFilamentBlock(-innerS, -innerS, innerS * 2, innerS * 2, c2, true);

  // Diagonal X-binding threads anchoring the card corners (classic Andean motif)
  for (let d = -5; d <= 5; d++) {
    let off = d * 1.8;
    let thCol = abs(d) < 2 ? c0.sheen : (abs(d) < 4 ? c0.light : c0.mid);
    brush.set("cpencil", thCol, 0.5);
    brush.line(-wSpan + off, -wSpan - off, wSpan + off, wSpan - off);
    brush.line(-wSpan + off, wSpan + off, wSpan + off, -wSpan + off);
  }

  // Snipped tail tucked into corner slit
  if (spec.tail !== "tucked") {
    drawSnippedTail(wSpan * 0.6, cardS - 4, wSpan + 16, cardS + 14, wSpan + 10, cardS + 4, c1);
  }

  pop();
}

function drawCardFilamentBlock(x, y, w, h, th, isVertical) {
  brush.noStroke();
  brush.wash(th.wash, 235);
  brush.rect(x, y, w, h);
  brush.noWash();

  if (isVertical) {
    for (let lx = x + 1; lx <= x + w - 1; lx += 1.6) {
      let t = (lx - x) / w;
      let col = (floor(lx) % 3 === 0) ? th.dark : (floor(lx) % 2 === 0 ? th.mid : th.bright);
      brush.set("cpencil", col, 0.48);
      let bow = (t - 0.5) * 3.5;
      brush.spline([[lx, y], [lx + bow, y + h * 0.5], [lx, y + h]], 0.35);

      // Center sheen band
      brush.set("2H", th.light, 0.38);
      brush.line(lx + bow * 0.6, y + h * 0.28, lx + bow * 0.6, y + h * 0.58);
    }
    // Edge shadow
    brush.set("2B", th.deep, 0.5);
    brush.line(x, y, x + w, y);
    brush.line(x, y + h, x + w, y + h);
  } else {
    for (let ly = y + 1; ly <= y + h - 1; ly += 1.6) {
      let t = (ly - y) / h;
      let col = (floor(ly) % 3 === 0) ? th.dark : (floor(ly) % 2 === 0 ? th.mid : th.bright);
      brush.set("cpencil", col, 0.48);
      let bow = (t - 0.5) * 3.5;
      brush.spline([[x, ly], [x + w * 0.5, ly + bow], [x + w, ly]], 0.35);

      brush.set("2H", th.light, 0.38);
      brush.line(x + w * 0.28, ly + bow * 0.6, x + w * 0.58, ly + bow * 0.6);
    }
    brush.set("2B", th.deep, 0.5);
    brush.line(x, y, x, y + h);
    brush.line(x + w, y, x + w, y + h);
  }
}

