// ============================================================================
// 8. WOODEN GRID DIVIDERS, LAP JOINTS & OUTER DRAWER FRAME
// ============================================================================

function drawWoodenGridAndFrame() {
  // 1. Interior Vertical Dividers (4 strips)
  for (let c = 1; c < GRID_COUNT; c++) {
    let dx = INNER_START + c * CELL_SIZE + (c - 1) * DIVIDER;
    drawWoodStrip(dx, INNER_START, DIVIDER, INNER_SPAN, true);
  }

  // 2. Interior Horizontal Dividers (4 strips)
  for (let r = 1; r < GRID_COUNT; r++) {
    let dy = INNER_START + r * CELL_SIZE + (r - 1) * DIVIDER;
    drawWoodStrip(INNER_START, dy, INNER_SPAN, DIVIDER, false);
  }

  // 3. Half-Lap Joint Intersections (4x4 = 16 interior cross joints)
  for (let r = 1; r < GRID_COUNT; r++) {
    for (let c = 1; c < GRID_COUNT; c++) {
      let jx = INNER_START + c * CELL_SIZE + (c - 1) * DIVIDER;
      let jy = INNER_START + r * CELL_SIZE + (r - 1) * DIVIDER;
      drawLapJoint(jx, jy, DIVIDER);
    }
  }

  // 4. Outer Wooden Drawer Frame (Top, Bottom, Left, Right rails)
  let outerSpan = 1200 - MARGIN * 2;
  // Top & Bottom rails (horizontal grain)
  drawWoodStrip(MARGIN, MARGIN, outerSpan, FRAME_THICK, false, true);
  drawWoodStrip(MARGIN, 1200 - MARGIN - FRAME_THICK, outerSpan, FRAME_THICK, false, true);

  // Left & Right stiles (vertical grain between rails)
  drawWoodStrip(MARGIN, INNER_START, FRAME_THICK, INNER_SPAN, true, true);
  drawWoodStrip(1200 - MARGIN - FRAME_THICK, INNER_START, FRAME_THICK, INNER_SPAN, true, true);

  // 5. Corner Box / Dovetail Joinery on the 4 outer corners
  drawCornerDovetails(MARGIN, MARGIN, FRAME_THICK);
  drawCornerDovetails(1200 - MARGIN - FRAME_THICK, MARGIN, FRAME_THICK);
  drawCornerDovetails(MARGIN, 1200 - MARGIN - FRAME_THICK, FRAME_THICK);
  drawCornerDovetails(1200 - MARGIN - FRAME_THICK, 1200 - MARGIN - FRAME_THICK, FRAME_THICK);

  // 6. Mortise tenon slots where the 4+4 inner dividers meet the outer frame
  for (let i = 1; i < GRID_COUNT; i++) {
    let pos = INNER_START + i * CELL_SIZE + (i - 1) * DIVIDER;
    // Top & bottom T-joints
    drawTJoint(pos, INNER_START - 4, DIVIDER, 4);
    drawTJoint(pos, INNER_START + INNER_SPAN, DIVIDER, 4);
    // Left & right T-joints
    drawTJoint(INNER_START - 4, pos, 4, DIVIDER);
    drawTJoint(INNER_START + INNER_SPAN, pos, 4, DIVIDER);
  }

  // 7. Small oxidized brass museum plaque centered on the bottom drawer rail
  drawBrassMuseumPlaque(600, 1200 - MARGIN - FRAME_THICK / 2);
}

function drawWoodStrip(x, y, w, h, isVertical, isFrame = false) {
  // Base wash
  brush.noStroke();
  let baseCol = isFrame ? PALETTE.woodFrame : (isVertical ? PALETTE.woodBaseV : PALETTE.woodBaseH);
  brush.wash(baseCol, 245);
  brush.rect(x, y, w, h);
  brush.noWash();

  // Directional colored-pencil wood grain
  if (isVertical) {
    let step = 1.8;
    for (let lx = x + 1.5; lx <= x + w - 1.5; lx += step) {
      let n = noise(lx * 0.15, y * 0.01);
      let col = n < 0.35 ? random(PALETTE.woodGrainDark) : (n < 0.72 ? random(PALETTE.woodGrainMid) : random(PALETTE.woodGrainLight));
      brush.set("cpencil", col, 0.48);

      // Break into 3 segments for subtle organic grain drift
      let m1 = y + h * 0.33;
      let m2 = y + h * 0.66;
      let drift1 = (noise(lx * 0.2, m1 * 0.01) - 0.5) * 2.2;
      let drift2 = (noise(lx * 0.2, m2 * 0.01) - 0.5) * 2.2;
      brush.spline([[lx, y], [lx + drift1, m1], [lx + drift2, m2], [lx, y + h]], 0.3);
    }

    // Chamfer highlights & darks along long vertical edges
    brush.set("2H", PALETTE.woodChamferLight, 0.5);
    brush.line(x + 1.2, y, x + 1.2, y + h);
    brush.set("2B", PALETTE.woodChamferDark, 0.6);
    brush.line(x + w - 1.0, y, x + w - 1.0, y + h);
    brush.set("rotring", "#14161a", 0.4);
    brush.line(x, y, x, y + h);
    brush.line(x + w, y, x + w, y + h);
  } else {
    let step = 1.8;
    for (let ly = y + 1.5; ly <= y + h - 1.5; ly += step) {
      let n = noise(x * 0.01, ly * 0.15);
      let col = n < 0.35 ? random(PALETTE.woodGrainDark) : (n < 0.72 ? random(PALETTE.woodGrainMid) : random(PALETTE.woodGrainLight));
      brush.set("cpencil", col, 0.48);

      let m1 = x + w * 0.33;
      let m2 = x + w * 0.66;
      let drift1 = (noise(m1 * 0.01, ly * 0.2) - 0.5) * 2.2;
      let drift2 = (noise(m2 * 0.01, ly * 0.2) - 0.5) * 2.2;
      brush.spline([[x, ly], [m1, ly + drift1], [m2, ly + drift2], [x + w, ly]], 0.3);
    }

    // Chamfer highlights & darks along long horizontal edges
    brush.set("2H", PALETTE.woodChamferLight, 0.5);
    brush.line(x, y + 1.2, x + w, y + 1.2);
    brush.set("2B", PALETTE.woodChamferDark, 0.6);
    brush.line(x, y + h - 1.0, x + w, y + h - 1.0);
    brush.set("rotring", "#14161a", 0.4);
    brush.line(x, y, x + w, y);
    brush.line(x, y + h, x + w, y + h);
  }
}

function drawLapJoint(jx, jy, s) {
  // Subtle recessed end-grain/lap-slot square at each divider intersection
  brush.set("rotring", "#1b1917", 0.5);
  brush.rect(jx, jy, s, s);

  brush.set("2H", PALETTE.woodChamferLight, 0.42);
  brush.line(jx + 1.5, jy + 1.5, jx + s - 1.5, jy + 1.5);
  brush.line(jx + 1.5, jy + 1.5, jx + 1.5, jy + s - 1.5);

  // Tiny aged brass pin/brad in the center of the lap joint
  brush.set("rotring", "#24201c", 0.45);
  brush.circle(jx + s / 2, jy + s / 2, 1.5);
}

function drawTJoint(x, y, w, h) {
  brush.noStroke();
  brush.wash("#2b2825", 230);
  brush.rect(x, y, w, h);
  brush.noWash();
  brush.set("rotring", "#141311", 0.45);
  brush.rect(x, y, w, h);
}

function drawCornerDovetails(cx, cy, s) {
  // Render 3 interlocking box-joint fingers at each drawer corner
  let fingers = 3;
  let fw = s / fingers;
  for (let i = 0; i < fingers; i++) {
    let fy = cy + i * fw;
    let isEndGrain = i % 2 === 0;
    brush.noStroke();
    brush.wash(isEndGrain ? "#2e2a26" : "#4a453f", 240);
    brush.rect(cx, fy, s, fw);
    brush.noWash();

    // End grain cross-hatching
    for (let gy = fy + 1.5; gy < fy + fw - 1; gy += 1.8) {
      brush.set("cpencil", isEndGrain ? "#1f1c19" : "#69635b", 0.45);
      brush.line(cx + 1, gy, cx + s - 1, gy);
    }
    brush.set("rotring", "#141210", 0.45);
    brush.rect(cx, fy, s, fw);
  }
}

function drawBrassMuseumPlaque(cx, cy) {
  let pw = 116;
  let ph = 18;
  let px = cx - pw / 2;
  let py = cy - ph / 2;

  brush.noStroke();
  brush.wash("#594d34", 240);
  brush.rect(px, py, pw, ph);
  brush.noWash();

  // Brushed brass horizontal pencil lines
  for (let y = py + 1.5; y < py + ph - 1; y += 1.6) {
    let col = y < cy ? "#8c7a53" : "#453b26";
    brush.set("cpencil", col, 0.45);
    brush.line(px + 2, y, px + pw - 2, y);
  }

  // Bevel & two tiny brass rivets
  brush.set("rotring", "#1c1810", 0.5);
  brush.rect(px, py, pw, ph);
  brush.set("2H", "#baa679", 0.45);
  brush.line(px + 1, py + 1, px + pw - 1, py + 1);

  brush.set("rotring", "#241e12", 0.5);
  brush.circle(px + 7, cy, 2.2);
  brush.circle(px + pw - 7, cy, 2.2);

  // Engraved archival inscription marks ("TOCAPU — CUSCO")
  brush.set("rotring", "#1f1a10", 0.4);
  for (let gx = px + 20; gx < px + pw - 20; gx += 5.5) {
    if (abs(gx - cx) < 5) {
      brush.line(gx - 1, cy, gx + 3, cy);
    } else {
      brush.line(gx, cy - 3.5, gx, cy + 3.5);
      brush.line(gx, cy - 3.5, gx + 2.5, cy - 3.5);
    }
  }
}

// ============================================================================
// 9. STRAY THREAD INCIDENTS CROSSING OVER DIVIDERS
// ============================================================================

function drawCrossDividerThreads() {
  // Thread 1: Cochineal filament escaping from Row 1 Col 1 over the divider into Row 1 Col 0
  let xDiv1 = INNER_START + 1 * CELL_SIZE;
  let yCell1 = INNER_START + 1 * (CELL_SIZE + DIVIDER) + CELL_SIZE * 0.65;
  drawSnippedTail(
    xDiv1 + DIVIDER + 26, yCell1 - 14,
    xDiv1 - 28, yCell1 + 18,
    xDiv1 + DIVIDER * 0.5, yCell1 - 2,
    PALETTE.threads.cochineal
  );

  // Thread 2: Ochre filament escaping from Row 2 Col 1 down over the horizontal divider into Row 3 Col 1
  let xCell2 = INNER_START + 1 * (CELL_SIZE + DIVIDER) + CELL_SIZE * 0.58;
  let yDiv2 = INNER_START + 3 * CELL_SIZE + 2 * DIVIDER;
  drawSnippedTail(
    xCell2 - 12, yDiv2 - 22,
    xCell2 + 24, yDiv2 + DIVIDER + 24,
    xCell2 + 4, yDiv2 + DIVIDER * 0.5,
    PALETTE.threads.ochre
  );

  // Thread 3: Cream filament resting across the divider between Row 3 Col 2 and Row 3 Col 3
  let xDiv3 = INNER_START + 3 * CELL_SIZE + 2 * DIVIDER;
  let yCell3 = INNER_START + 3 * (CELL_SIZE + DIVIDER) + CELL_SIZE * 0.32;
  drawSnippedTail(
    xDiv3 - 24, yCell3 + 10,
    xDiv3 + DIVIDER + 22, yCell3 - 12,
    xDiv3 + DIVIDER * 0.5, yCell3 - 4,
    PALETTE.threads.cream
  );
}

// Hyperrealist CMYK Ben-Day & Stippled Pen Macro Hot Dog
// Built entirely from graduated Ben-Day dots and stippled pen marks in Process C, M, Y, K

const GRID_W = 600;
const GRID_H = 600;

let C_buf, M_buf, Y_buf, K_buf, D_buf;
let H_buf, MAT_buf;
let perm = new Uint8Array(512);
let blisters = [];
let blisterBins = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Register custom stippled Ben-Day ink brushes after scaleBrushes(3) for exact pixel sizing
  brush.add("benday_core", {
    type: "custom",
    weight: 3.0,
    scatter: 0.025,
    opacity: 215,
    spacing: 0.28,
    pressure: [0.96, 1.04, 0.96],
    tip: (_m) => {
      _m.noStroke();
      _m.circle(0, 0, 2.35);
      // Stippled pen micro-tooth around the dot perimeter so up close it reads as stippled ink
      _m.circle(0.92, 0.22, 0.78);
      _m.circle(-0.82, 0.52, 0.72);
      _m.circle(0.18, -0.95, 0.74);
      _m.circle(-0.48, -0.78, 0.68);
      _m.circle(0.68, -0.62, 0.64);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.18
  });

  brush.add("stipple_dot", {
    type: "custom",
    weight: 1.75,
    scatter: 0.05,
    opacity: 225,
    spacing: 0.32,
    pressure: [1.0, 1.0],
    tip: (_m) => {
      _m.noStroke();
      _m.circle(0, 0, 1.55);
      _m.circle(0.52, -0.32, 0.68);
      _m.circle(-0.44, 0.38, 0.58);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.22
  });

  initNoiseTable(8472);
  initBlisters();
  buildSceneBuffers();
}

function initNoiseTable(seed) {
  let p = new Uint8Array(256);
  for (let i = 0; i < 256; i++) p[i] = i;
  let s = seed >>> 0;
  for (let i = 255; i > 0; i--) {
    s = (Math.imul(1664525, s) + 1013904223) >>> 0;
    let j = s % (i + 1);
    let tmp = p[i];
    p[i] = p[j];
    p[j] = tmp;
  }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
}

function fastNoise(x, y) {
  let xi = Math.floor(x);
  let yi = Math.floor(y);
  let xf = x - xi;
  let yf = y - yi;
  xi &= 255;
  yi &= 255;
  let u = xf * xf * (3.0 - 2.0 * xf);
  let v = yf * yf * (3.0 - 2.0 * yf);
  let aa = perm[perm[xi] + yi];
  let ab = perm[perm[xi] + yi + 1];
  let ba = perm[perm[xi + 1] + yi];
  let bb = perm[perm[xi + 1] + yi + 1];
  let x1 = aa + u * (ba - aa);
  let x2 = ab + u * (bb - ab);
  return (x1 + v * (x2 - x1)) * (1.0 / 255.0);
}

function fbm(x, y) {
  let v = 0.0;
  v += 0.52 * fastNoise(x, y);
  v += 0.28 * fastNoise(x * 2.07 + 17.3, y * 2.07 - 11.9);
  v += 0.13 * fastNoise(x * 4.23 - 31.1, y * 4.23 + 23.7);
  v += 0.07 * fastNoise(x * 8.51 + 7.4, y * 8.51 + 41.2);
  return v;
}

// Cellular sponge function for the sesame-free bread crumb pores
function crumbPoreField(x, y) {
  let gx = Math.floor(x);
  let gy = Math.floor(y);
  let fx = x - gx;
  let fy = y - gy;
  let minD1 = 9.0;
  let minD2 = 9.0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      let cx = (gx + dx) & 255;
      let cy = (gy + dy) & 255;
      let h1 = perm[(perm[cx] + cy) & 255] * (1.0 / 255.0);
      let h2 = perm[(perm[cy] + cx * 3) & 255] * (1.0 / 255.0);
      let px = dx + 0.15 + 0.7 * h1 - fx;
      let py = dy + 0.15 + 0.7 * h2 - fy;
      let d2 = px * px + py * py;
      if (d2 < minD1) {
        minD2 = minD1;
        minD1 = d2;
      } else if (d2 < minD2) {
        minD2 = d2;
      }
    }
  }
  let d1 = Math.sqrt(minD1);
  let d2 = Math.sqrt(minD2);
  return { d1, edge: d2 - d1 };
}

function initBlisters() {
  const NUM_BINS = 20;
  blisterBins = Array.from({ length: NUM_BINS }, () => []);
  blisters = [];

  // Generate 78 realistic heat blisters across the grilled sausage skin
  let s = 918273;
  const rand = () => {
    s = (Math.imul(1664525, s) + 1013904223) >>> 0;
    return (s & 0xfffffff) / 0xfffffff;
  };

  for (let i = 0; i < 78; i++) {
    let u = -780 + rand() * 1560;
    let vc = -165 + rand() * 320;
    let r = 7 + Math.pow(rand(), 1.5) * 25;
    let aspect = 0.72 + rand() * 0.55;
    let ang = (rand() - 0.5) * 0.7;
    let burst = r > 15 && rand() < 0.58 ? 1.0 : 0.0;
    let charTint = 0.25 + rand() * 0.75;
    let b = {
      u,
      vc,
      rx: r,
      ry: r * aspect,
      cosA: Math.cos(ang),
      sinA: Math.sin(ang),
      h: 4.5 + r * 0.36,
      burst,
      charTint
    };
    blisters.push(b);

    let minBin = Math.max(0, Math.floor((u - r * 1.6 + 850) / 85));
    let maxBin = Math.min(NUM_BINS - 1, Math.floor((u + r * 1.6 + 850) / 85));
    for (let bin = minBin; bin <= maxBin; bin++) {
      blisterBins[bin].push(b);
    }
  }
}

// Analytical mustard zigzag centerline and radius at coordinate u
function getMustardZigzag(u) {
  let phase = (u + 48.0) / 138.0;
  let s = Math.sin(phase * Math.PI);
  // Squeeze-bottle pause at the turns flattens the wave peaks slightly
  let wave = s + 0.19 * Math.sin(3.0 * phase * Math.PI);
  let wobble = 14.0 * (fastNoise(u * 0.009 + 4.2, 2.7) - 0.5);
  let vCenter = wave * (144.0 + 16.0 * Math.sin(u * 0.0035)) + wobble;
  // Mustard ribbon swells where the bottle reverses direction at the turns
  let turnSwelling = Math.pow(Math.abs(s), 1.6);
  let radius = 28.5 + 15.5 * turnSwelling + 4.5 * (fastNoise(u * 0.018, 9.1) - 0.5);
  return { vCenter, radius, turnSwelling };
}

// Smooth minimum for coalescing liquid mustard between zigzag and hanging drip
function smin(a, b, k) {
  let h = Math.max(k - Math.abs(a - b), 0.0) / k;
  return Math.min(a, b) - h * h * k * 0.25;
}

// Evaluate 3D height and liquid distance of the glossy mustard (zigzag + hanging drip + satellite bead)
function evaluateMustard(x, y, u, vc) {
  // 1. Distance to the main zigzag ribbon in (u, vc) space
  let minZigNorm = 999.0;
  let bestZigR = 32.0;
  let bestZigRidge = 0.0;

  for (let k = -3; k <= 3; k++) {
    let us = u + k * 15.0;
    let mz = getMustardZigzag(us);
    let du = u - us;
    let dv = vc - mz.vCenter;
    let dist = Math.sqrt(du * du + dv * dv);
    let normD = dist / mz.radius;
    if (normD < minZigNorm) {
      minZigNorm = normD;
      bestZigR = mz.radius;
      bestZigRidge = dv / mz.radius;
    }
  }

  let zigSignedDist = (minZigNorm - 1.0) * bestZigR;

  // 2. Main hanging drip ("a drip about to fall") pulling down from the lower zigzag lobe around (672, 682)
  let dripSignedDist = 999.0;
  let dripR = 30.0;
  let isBulb = 0.0;

  if (x > 550 && x < 810 && y > 625 && y < 1095) {
    // Sample along vertical drip axis y
    for (let ky = -2; ky <= 2; ky++) {
      let ys = Math.max(672.0, Math.min(1018.0, y + ky * 11.0));
      let t = (ys - 672.0) / (1018.0 - 672.0);
      // Slight graceful curve as gravity pulls the drop straight down
      let xCenter = 669.0 + 11.0 * Math.sin(t * Math.PI * 0.75) + 3.5 * t;
      let r = 10.0;
      if (ys < 765.0) {
        // Viscous root cone pooling off the lower sausage & crumb
        let s = (ys - 672.0) / 93.0;
        r = 10.2 + 37.5 * Math.pow(1.0 - s, 1.75);
      } else if (ys < 855.0) {
        // Taut capillary waist
        let s = (ys - 765.0) / 90.0;
        let waist = (s - 0.52) / 0.52;
        r = 7.8 + 2.6 * waist * waist + (s > 0.52 ? 8.5 * Math.pow((s - 0.52) / 0.48, 2.0) : 0.0);
      } else {
        // Swollen teardrop bulb about to fall
        let s = (ys - 855.0) / (1018.0 - 855.0);
        if (s < 0.62) {
          let uBulb = s / 0.62;
          r = 16.3 + 27.5 * Math.sin(uBulb * Math.PI * 0.5);
        } else {
          let uTip = (s - 0.62) / 0.38;
          r = 43.8 * Math.sqrt(Math.max(0.0, 1.0 - uTip * uTip));
        }
      }
      let dx = x - xCenter;
      let dy = y - ys;
      let d = Math.sqrt(dx * dx + dy * dy) - r;
      if (d < dripSignedDist) {
        dripSignedDist = d;
        dripR = Math.max(6.0, r);
        isBulb = ys > 845.0 ? 1.0 : 0.35;
      }
    }

    // Stretching micro-filament (y = 1014..1040) and detaching satellite bead at (681, 1053)
    if (y > 1005.0 && y < 1080.0) {
      let threadY = Math.max(1015.0, Math.min(1042.0, y));
      let dThread = Math.hypot(x - 681.5, y - threadY) - 2.9;
      let dBead = Math.hypot(x - 681.5, (y - 1053.0) * 0.92) - 12.2;
      let dMicro = smin(dThread, dBead, 5.5);
      if (dMicro < dripSignedDist) {
        dripSignedDist = dMicro;
        dripR = y > 1038.0 ? 12.2 : 4.0;
        isBulb = 1.0;
      }
    }
  }

  // 3. Secondary smaller gravity sag at the lower-left turn (u ~ -228, vc ~ +148)
  let sagSignedDist = 999.0;
  if (x > 360 && x < 530 && y > 730 && y < 920) {
    let ys = Math.max(765.0, Math.min(872.0, y));
    let s = (ys - 765.0) / 107.0;
    let xSag = 452.0 + 6.0 * Math.sin(s * Math.PI);
    let rSag = 34.0 * Math.sin((1.0 - s * 0.65) * Math.PI * 0.5) * Math.sqrt(Math.max(0.0, 1.0 - s * s));
    sagSignedDist = Math.hypot(x - xSag, y - ys) - rSag;
  }

  let combinedDist = smin(zigSignedDist, dripSignedDist, 18.0);
  combinedDist = smin(combinedDist, sagSignedDist, 14.0);

  let effR = dripSignedDist < zigSignedDist ? dripR : bestZigR;
  if (combinedDist < 0.0) {
    let q = Math.max(0.0, Math.min(1.0, 1.0 + combinedDist / effR));
    // Plump, glossy liquid cross-section with subtle nozzle ridges
    let profile = Math.pow(q * (2.0 - q), 0.58);
    let ridge = (1.0 - isBulb * 0.7) * 2.2 * Math.cos(bestZigRidge * Math.PI * 2.5) * q;
    let h = effR * 0.92 * profile + ridge;
    return { inside: true, h, distOutside: 0.0, q, isBulb };
  } else {
    return { inside: false, h: 0.0, distOutside: combinedDist, q: 0.0, isBulb };
  }
}

function buildSceneBuffers() {
  C_buf = new Float32Array(GRID_W * GRID_H);
  M_buf = new Float32Array(GRID_W * GRID_H);
  Y_buf = new Float32Array(GRID_W * GRID_H);
  K_buf = new Float32Array(GRID_W * GRID_H);
  D_buf = new Float32Array(GRID_W * GRID_H);

  H_buf = new Float32Array(GRID_W * GRID_H);
  MAT_buf = new Uint8Array(GRID_W * GRID_H);

  let auxChar = new Float32Array(GRID_W * GRID_H);
  let auxPore = new Float32Array(GRID_W * GRID_H);
  let auxShadow = new Float32Array(GRID_W * GRID_H);
  let auxU = new Float32Array(GRID_W * GRID_H);
  let auxVC = new Float32Array(GRID_W * GRID_H);

  // Hot dog axis orientation (-27.5 degrees diagonal macro crop)
  const theta = -27.5 * (Math.PI / 180.0);
  const cosT = Math.cos(theta);
  const sinT = Math.sin(theta);
  const cx = 590.0;
  const cy = 542.0;

  // PASS 1: Evaluate 3D Heightfield & Material Regions
  for (let iy = 0; iy < GRID_H; iy++) {
    let y = (iy + 0.5) * 2.0;
    for (let ix = 0; ix < GRID_W; ix++) {
      let x = (ix + 0.5) * 2.0;
      let idx = iy * GRID_W + ix;

      let dx = x - cx;
      let dy = y - cy;
      let u = dx * cosT + dy * sinT;
      let v = -dx * sinT + dy * cosT;

      // Slight organic bow of the frankfurter
      let curve = -0.00013 * u * u + 15.0 * Math.sin(u * 0.0036 + 0.35);
      let vc = v - curve;
      auxU[idx] = u;
      auxVC[idx] = vc;

      // 1. Sausage geometry
      let sausageR = 206.0 + 7.5 * Math.sin(u * 0.0052) + 8.0 * (fbm(u * 0.006, 1.7) - 0.5);
      let zSausage = -100.0;
      let charVal = 0.0;
      let blisterRimVal = 0.0;

      if (Math.abs(vc) < sausageR) {
        let ts = vc / sausageR;
        zSausage = sausageR * Math.sqrt(Math.max(0.0, 1.0 - ts * ts));

        // Fine longitudinal casing tension wrinkles & cellular skin grain
        let skinGrain =
          1.4 * Math.sin(vc * 0.28 + 4.0 * fastNoise(u * 0.02, vc * 0.02)) +
          2.2 * (fbm(u * 0.045, vc * 0.045) - 0.5);
        zSausage += skinGrain;

        // Diagonal grill char marks across the exposed crown of the sausage
        let gCoord = u * 0.69 + vc * 0.72 + 18.0 * (fbm(u * 0.011, vc * 0.011) - 0.5);
        let gPeriod = 228.0;
        let gMod = ((gCoord % gPeriod) + gPeriod) % gPeriod;
        let gDist = Math.abs(gMod - gPeriod * 0.5);
        let crownMask = Math.max(0.0, 1.0 - Math.pow(ts / 0.84, 4.0));
        let barHalfW = (27.0 + 11.0 * (fbm(u * 0.025, vc * 0.025) - 0.5)) * crownMask;

        if (gDist < barHalfW * 1.35 && crownMask > 0.05) {
          let qg = gDist / Math.max(0.001, barHalfW);
          if (qg < 1.0) {
            charVal = Math.pow(1.0 - qg * qg, 0.75) * (0.75 + 0.35 * fbm(u * 0.05, vc * 0.05));
            zSausage -= 6.5 * charVal;
          } else {
            // Puckered blistered ridge right along the edge of the grill sear
            let rim = Math.sin(((qg - 1.0) / 0.35) * Math.PI);
            zSausage += 2.6 * rim;
            charVal = 0.22 * rim;
          }
        }

        // Blistered skin domes & burst craters
        let bin = Math.max(0, Math.min(19, Math.floor((u + 850.0) / 85.0)));
        let bList = blisterBins[bin];
        for (let bIdx = 0; bIdx < bList.length; bIdx++) {
          let b = bList[bIdx];
          let du = u - b.u;
          let dv = vc - b.vc;
          let ru = (du * b.cosA + dv * b.sinA) / b.rx;
          let rv = (-du * b.sinA + dv * b.cosA) / b.ry;
          let d2 = ru * ru + rv * rv;
          if (d2 < 1.55) {
            let d = Math.sqrt(d2);
            if (d < 0.92) {
              let dome = Math.cos((d / 0.92) * Math.PI * 0.5);
              if (b.burst > 0.5 && d < 0.48) {
                // Burst blister crater with charred inner floor
                let crater = Math.cos((d / 0.48) * Math.PI * 0.5);
                zSausage += b.h * dome - b.h * 0.85 * crater;
                charVal = Math.max(charVal, (0.55 + 0.4 * b.charTint) * crater);
              } else {
                zSausage += b.h * dome;
                charVal = Math.max(charVal, 0.32 * b.charTint * dome);
              }
            } else if (d < 1.24) {
              // Taut wrinkle ring around the blister base
              let ring = Math.sin(((d - 0.92) / 0.32) * Math.PI);
              zSausage += 2.4 * ring;
              blisterRimVal = Math.max(blisterRimVal, ring);
              charVal = Math.max(charVal, 0.38 * ring * b.charTint);
            }
          }
        }
      }

      // 2. Split Bun Geometry (Upper & Lower Lobes with Sesame-Free Crumb and Smooth Crust)
      let zBun = -100.0;
      let bunType = 0; // 1 = smooth crust, 2 = sesame-free crumb
      let poreDepth = 0.0;

      // Upper Bun Lobe (vc < -110)
      let upperInner = -120.0 + 14.0 * (fbm(u * 0.008, 3.1) - 0.5);
      // Dip the upper bun outer edge slightly in the top-left corner so a cool background corner peeks through
      let upperOuter = -545.0 + 28.0 * (fbm(u * 0.005, 5.4) - 0.5) + (u < -220 ? (u + 220) * 0.22 : 0.0);
      if (vc < upperInner && vc > upperOuter) {
        let tb = (vc - upperInner) / (upperOuter - upperInner); // 0 at inner split, 1 at outer edge
        // Pillowy profile of the upper bun roll
        zBun = 198.0 * Math.pow(Math.sin(tb * Math.PI), 0.62) + 32.0 * (1.0 - tb);

        // Crumb-to-crust boundary around vc ~ -280
        let crustLine = -278.0 + 19.0 * (fbm(u * 0.013, 7.8) - 0.5);
        if (vc > crustLine) {
          bunType = 2; // Sesame-free exposed crumb
          let c1 = crumbPoreField(u * 0.055, vc * 0.055);
          let c2 = crumbPoreField(u * 0.13 + 19.4, vc * 0.13 - 8.2);
          let pocket1 = Math.max(0.0, 1.0 - c1.d1 * 1.45);
          let pocket2 = Math.max(0.0, 1.0 - c2.d1 * 1.55);
          poreDepth = Math.min(1.0, pocket1 * 0.85 + pocket2 * 0.55);
          zBun -= poreDepth * 8.5 + 2.5 * fastNoise(u * 0.25, vc * 0.25);
        } else {
          bunType = 1; // Smooth golden-brown crust (sesame-free)
          let crustSmooth = Math.min(1.0, (crustLine - vc) / 22.0);
          // Subtle soft bake wrinkles near the ends
          let bakeWrinkle = 1.8 * Math.sin(u * 0.035 + 3.0 * fastNoise(u * 0.015, vc * 0.015)) * (1.0 - crustSmooth * 0.6);
          zBun += 4.5 * crustSmooth + bakeWrinkle;
          poreDepth = (1.0 - crustSmooth) * 0.35;
        }
      }

      // Lower Bun Lobe (vc > +105)
      let lowerInner = 115.0 + 14.0 * (fbm(u * 0.008, 9.2) - 0.5);
      // Curve the lower bun outer boundary inward on the right so the hanging mustard drip suspends over the cool shadow
      let dripCutout = u > -40.0 ? Math.min(135.0, (u + 40.0) * 0.32) : 0.0;
      let lowerOuter = 505.0 - dripCutout + 24.0 * (fbm(u * 0.006, 11.3) - 0.5);

      if (vc > lowerInner && vc < lowerOuter) {
        let tb = (vc - lowerInner) / (lowerOuter - lowerInner);
        zBun = 178.0 * Math.pow(Math.sin(tb * Math.PI), 0.64) + 26.0 * (1.0 - tb);

        let crustLine = 272.0 - dripCutout * 0.25 + 18.0 * (fbm(u * 0.014, 14.1) - 0.5);
        if (vc < crustLine) {
          bunType = 2; // Sesame-free exposed crumb on lower lip
          let c1 = crumbPoreField(u * 0.058 + 7.1, vc * 0.058 + 3.3);
          let c2 = crumbPoreField(u * 0.14 - 12.7, vc * 0.14 + 21.5);
          let pocket1 = Math.max(0.0, 1.0 - c1.d1 * 1.45);
          let pocket2 = Math.max(0.0, 1.0 - c2.d1 * 1.55);
          poreDepth = Math.min(1.0, pocket1 * 0.85 + pocket2 * 0.55);
          zBun -= poreDepth * 8.5 + 2.5 * fastNoise(u * 0.25, vc * 0.25);
        } else {
          bunType = 1; // Lower smooth crust
          let crustSmooth = Math.min(1.0, (vc - crustLine) / 22.0);
          let sideFold = 2.4 * Math.sin(u * 0.042 + 4.0 * fastNoise(u * 0.018, vc * 0.018));
          zBun += 4.0 * crustSmooth + sideFold;
          poreDepth = (1.0 - crustSmooth) * 0.35;
        }
      }

      // Determine base surface (Sausage vs Bun vs Cool Background)
      let baseZ = -40.0;
      let mat = 0; // 0 = background, 1 = bun crust, 2 = bun crumb, 3 = sausage, 4 = mustard
      let shadowAO = 0.0;

      if (zSausage > zBun && zSausage > 0.0) {
        baseZ = zSausage;
        mat = 3;
        // Crevice ambient occlusion where sausage meets the split bun lips
        if (zBun > 0.0 && zSausage - zBun < 28.0) {
          shadowAO = Math.pow(1.0 - (zSausage - zBun) / 28.0, 1.6) * 0.78;
        }
      } else if (zBun > 0.0) {
        baseZ = zBun;
        mat = bunType;
        if (zSausage > 0.0 && zBun - zSausage < 28.0) {
          shadowAO = Math.pow(1.0 - (zBun - zSausage) / 28.0, 1.6) * 0.82;
        }
        // Cast shadow from the plump sausage onto the lower inner crumb
        if (vc > 140.0 && vc < 245.0) {
          let creaseDist = Math.abs(vc - 182.0);
          if (creaseDist < 42.0) {
            shadowAO = Math.max(shadowAO, (1.0 - creaseDist / 42.0) * 0.55);
          }
        }
      } else {
        // Background plate/table shadow beneath the lower bun and behind the hanging drip
        baseZ = 0.0;
        mat = 0;
        let distFromBun = vc > 0 ? vc - lowerOuter : upperOuter - vc;
        if (distFromBun > 0.0 && distFromBun < 130.0) {
          shadowAO = Math.pow(1.0 - distFromBun / 130.0, 1.5) * 0.88;
        }
      }

      // 3. Glossy Mustard Zigzag & Hanging Drip over the scene
      let mInfo = evaluateMustard(x, y, u, vc);
      if (mInfo.inside) {
        // Mustard sits on top of sausage/bun, or hangs in space for the drip bulb
        let underlyingZ = Math.max(45.0, baseZ);
        if (mInfo.isBulb > 0.5 && mat === 0) {
          underlyingZ = 95.0; // Suspended 3D teardrop bulb in the foreground
        }
        H_buf[idx] = underlyingZ + mInfo.h;
        MAT_buf[idx] = 4;
        auxChar[idx] = mInfo.q;
        auxPore[idx] = mInfo.isBulb;
        auxShadow[idx] = (1.0 - mInfo.q) * 0.35;
      } else {
        // Cast shadow from the mustard ribbon and hanging drip onto sausage, bun, and background
        let mShadowDist = evaluateMustard(x - 14.0, y - 18.0, u - 4.0, vc - 18.0).distOutside;
        if (mShadowDist < 22.0) {
          let mCast = Math.pow(1.0 - mShadowDist / 22.0, 1.5) * 0.68;
          shadowAO = Math.max(shadowAO, mCast);
        }
        if (mInfo.distOutside < 9.0) {
          // Wet meniscus contact ring right around the mustard edge
          let meniscus = Math.pow(1.0 - mInfo.distOutside / 9.0, 1.7) * 0.52;
          shadowAO = Math.max(shadowAO, meniscus);
        }
        H_buf[idx] = baseZ;
        MAT_buf[idx] = mat;
        auxChar[idx] = charVal;
        auxPore[idx] = mat === 3 ? blisterRimVal : poreDepth;
        auxShadow[idx] = shadowAO;
      }
    }
  }

  // PASS 2: Compute 3D Surface Normals, Cool-Palette Lighting, Greasy Speculars & CMYK Separation
  // Key light from top-left-front (cool studio / diner light)
  const L1x = -0.46, L1y = -0.58, L1z = 0.67;
  // Secondary grazing rim/strip light for wet grease reflections
  const L2x = 0.48, L2y = -0.36, L2z = 0.80;
  // Half-vectors with viewer V = (0, 0, 1)
  const H1len = Math.hypot(L1x, L1y, L1z + 1.0);
  const H1x = L1x / H1len, H1y = L1y / H1len, H1z = (L1z + 1.0) / H1len;
  const H2len = Math.hypot(L2x, L2y, L2z + 1.0);
  const H2x = L2x / H2len, H2y = L2y / H2len, H2z = (L2z + 1.0) / H2len;

  for (let iy = 0; iy < GRID_H; iy++) {
    let y = (iy + 0.5) * 2.0;
    let iyPrev = Math.max(0, iy - 1);
    let iyNext = Math.min(GRID_H - 1, iy + 1);

    for (let ix = 0; ix < GRID_W; ix++) {
      let x = (ix + 0.5) * 2.0;
      let ixPrev = Math.max(0, ix - 1);
      let ixNext = Math.min(GRID_W - 1, ix + 1);
      let idx = iy * GRID_W + ix;

      let mat = MAT_buf[idx];
      let u = auxU[idx];
      let vc = auxVC[idx];
      let shadowAO = auxShadow[idx];

      // Central difference height gradient (clamped across material silhouettes for smooth interior normals)
      let hC = H_buf[idx];
      let hL = MAT_buf[iy * GRID_W + ixPrev] === mat ? H_buf[iy * GRID_W + ixPrev] : hC;
      let hR = MAT_buf[iy * GRID_W + ixNext] === mat ? H_buf[iy * GRID_W + ixNext] : hC;
      let hU = MAT_buf[iyPrev * GRID_W + ix] === mat ? H_buf[iyPrev * GRID_W + ix] : hC;
      let hD = MAT_buf[iyNext * GRID_W + ix] === mat ? H_buf[iyNext * GRID_W + ix] : hC;

      let dzdx = (hR - hL) * 0.32;
      let dzdy = (hD - hU) * 0.32;
      let nLen = Math.hypot(dzdx, dzdy, 1.0);
      let nx = -dzdx / nLen;
      let ny = -dzdy / nLen;
      let nz = 1.0 / nLen;

      let diff1 = Math.max(0.0, nx * L1x + ny * L1y + nz * L1z);
      let diff2 = Math.max(0.0, nx * L2x + ny * L2y + nz * L2z);
      let ndotv = Math.max(0.0, nz);
      let fresnel = Math.pow(1.0 - ndotv, 2.4);

      let specDot1 = Math.max(0.0, nx * H1x + ny * H1y + nz * H1z);
      let specDot2 = Math.max(0.0, nx * H2x + ny * H2y + nz * H2z);

      let C = 0.0, M = 0.0, Y = 0.0, K = 0.0, detail = 0.0;

      if (mat === 3) {
        // --- GRILLED HOT DOG SKIN (Blistered, Greasy, Charred) ---
        let charVal = auxChar[idx];
        let blisterRim = auxPore[idx];

        // High-gloss wet grease film on the taut casing (reduced inside matte carbon char core)
        let glossMask = Math.max(0.12, 1.0 - charVal * 0.75) * (1.0 - shadowAO * 0.7);
        let microGlint = fastNoise(x * 0.14, y * 0.14);
        let specSharp = Math.pow(specDot1, 36.0) * 1.35 + Math.pow(specDot2, 48.0) * 0.85;
        let specBroad = Math.pow(specDot1, 9.0) * 0.42;
        let blisterHighlight = blisterRim * Math.pow(specDot1, 14.0) * 0.95;
        let greaseSpec = Math.min(1.0, (specSharp * (0.65 + 0.7 * microGlint) + specBroad + blisterHighlight) * glossMask);

        let shade = Math.max(0.0, Math.min(1.0, 1.0 - (diff1 * 0.78 + diff2 * 0.25) + shadowAO * 0.68));
        let coolUnder = Math.max(0.0, vc / 205.0);

        // Base cured frankfurter CMYK with cool shadow & grazing reflection tint
        C = 0.10 + 0.56 * shade + 0.28 * fresnel + 0.18 * coolUnder;
        M = 0.68 + 0.24 * (1.0 - shade * 0.4) - 0.14 * fresnel + 0.10 * blisterRim;
        Y = 0.52 + 0.24 * (1.0 - coolUnder * 0.6) - 0.22 * fresnel;
        K = 0.03 + 0.52 * Math.pow(shade, 1.5) + 0.35 * shadowAO;

        // Dense overlapping 4-color process in the grill char marks
        if (charVal > 0.01) {
          let cPow = Math.min(1.0, charVal * 1.15);
          // Caramelized mahogany border around the char mark
          let searHalo = Math.sin(Math.min(1.0, charVal) * Math.PI);
          M = Math.min(0.96, M + 0.22 * searHalo + 0.18 * cPow);
          Y = Math.min(0.92, Y + 0.26 * searHalo + 0.12 * cPow);
          C = Math.min(0.94, C * (1.0 - cPow) + 0.86 * cPow);
          K = Math.min(0.98, K * (1.0 - cPow) + 0.94 * Math.pow(cPow, 0.8));
        }

        // Wet grease specular glints cut cleanly through to cool ice-blue/white paper
        if (greaseSpec > 0.15) {
          let wipe = Math.min(1.0, (greaseSpec - 0.15) / 0.65);
          Y *= 1.0 - wipe * 0.96;
          M *= 1.0 - wipe * 0.92;
          K *= 1.0 - wipe * 0.98;
          // Leave a delicate cool cyan trace on the edge of the wet reflection, pure paper white at core
          C = C * (1.0 - wipe * 0.78) + 0.14 * Math.sin(wipe * Math.PI);
        }

        detail = Math.min(1.0, charVal * 0.85 + blisterRim * 0.9 + greaseSpec * 0.6 + shadowAO * 0.5);

      } else if (mat === 1) {
        // --- SPLIT BUN EXTERIOR CRUST (Golden-Cool Baked Roll, Sparse Highlights) ---
        let borderTransition = auxPore[idx];
        let shade = Math.max(0.0, Math.min(1.0, 1.0 - (diff1 * 0.86 + diff2 * 0.22) + shadowAO * 0.75));

        // Upper bun dome gets a broad, luminous highlight zone where Ben-Day dots are ultra-sparse
        let upperHighlightZone = vc < -260.0 ? Math.max(0.0, 1.0 - Math.hypot((u + 110.0) * 0.0022, (vc + 365.0) * 0.0068)) : 0.0;
        let highlightLift = Math.min(1.0, Math.pow(diff1, 1.6) * 0.75 + upperHighlightZone * 0.55) * (1.0 - shadowAO);

        // Baked crust base with cool cyan shadows on the lower/shaded curves
        Y = Math.max(0.02, 0.68 * (1.0 - highlightLift * 0.88) + 0.14 * borderTransition);
        M = Math.max(0.0, 0.38 * (1.0 - highlightLift * 0.92) + 0.12 * shade + 0.10 * borderTransition);
        C = Math.max(0.0, (0.06 + 0.64 * Math.pow(shade, 1.25) + 0.22 * fresnel) * (1.0 - highlightLift * 0.94));
        K = Math.max(0.0, (0.48 * Math.pow(shade, 1.8) + 0.38 * shadowAO) * (1.0 - highlightLift * 0.98));

        detail = borderTransition * 0.6 + shadowAO * 0.5;

      } else if (mat === 2) {
        // --- SESAME-FREE CRUMB (Porous, Airy, Spongy Interior Bread) ---
        let pore = auxPore[idx];
        let shade = Math.max(0.0, Math.min(1.0, 1.0 - (diff1 * 0.75 + diff2 * 0.25) + shadowAO * 0.8));

        // Cell walls are pale creamy-cool white; inside each tiny pore is a cool-warm micro-shadow
        let pShadow = Math.pow(pore, 1.15);
        Y = 0.12 + 0.34 * pShadow + 0.22 * shade + 0.15 * shadowAO;
        M = 0.03 + 0.22 * pShadow + 0.18 * shade + 0.16 * shadowAO;
        C = 0.05 + 0.38 * pShadow + 0.42 * shade + 0.24 * shadowAO;
        K = 0.24 * Math.pow(pShadow, 1.5) + 0.46 * Math.pow(shade, 1.7) + 0.35 * shadowAO;

        // Bright bread cell rims catch light
        if (pore < 0.25 && shadowAO < 0.25) {
          let cellRim = (1.0 - pore / 0.25) * diff1;
          Y *= 1.0 - cellRim * 0.65;
          M *= 1.0 - cellRim * 0.75;
          C *= 1.0 - cellRim * 0.70;
          K = 0.0;
        }

        detail = Math.min(1.0, Math.abs(pore - 0.38) * 1.8 + 0.45);

      } else if (mat === 4) {
        // --- GLOSSY MUSTARD ZIGZAG & HANGING DRIP ABOUT TO FALL ---
        let q = auxChar[idx];
        let isBulb = auxPore[idx];

        // Razor-sharp wet liquid specular window reflections
        let specWindow1 = Math.pow(specDot1, 28.0) * 1.65;
        let specWindow2 = Math.pow(specDot2, 42.0) * 1.15;
        // Extra curved highlight along the hanging teardrop bulb
        let bulbGlint = isBulb > 0.5 && nx < -0.18 && ny < 0.25 ? Math.pow(Math.max(0.0, -nx * 0.75 - ny * 0.35 + nz * 0.55), 14.0) * 1.4 : 0.0;
        let totalSpec = Math.min(1.0, specWindow1 + specWindow2 + bulbGlint);

        // Internal subsurface caustic glow on the lower-right belly of the mustard & drip
        let causticGlow = Math.max(0.0, nx * 0.55 + ny * 0.55 + nz * 0.35) * q;
        let shade = Math.max(0.0, 1.0 - (diff1 * 0.75 + diff2 * 0.3));

        // Brash, electric process yellow body with warm turmeric-magenta core and cool cyan reflected rim
        Y = 0.94 + 0.05 * causticGlow;
        M = 0.14 + 0.32 * shade + 0.16 * causticGlow - 0.08 * q;
        C = 0.03 + 0.42 * Math.pow(shade, 1.4) + 0.28 * fresnel * (1.0 - causticGlow * 0.6);
        K = 0.26 * Math.pow(shade, 2.0) + 0.12 * (1.0 - q);

        // Cut pure paper-white specular highlights into the glossy mustard & drip
        if (totalSpec > 0.22) {
          let wipe = Math.min(1.0, (totalSpec - 0.22) / 0.48);
          Y *= 1.0 - wipe * 0.98;
          M *= 1.0 - wipe * 0.98;
          C *= 1.0 - wipe * 0.92;
          K = 0.0;
        }

        detail = Math.min(1.0, (1.0 - q) * 0.9 + totalSpec * 0.95 + isBulb * 0.5);

      } else {
        // --- COOL BACKGROUND CORNERS & DEEP CAST SHADOW BEHIND THE HANGING DRIP ---
        // Cool cyan-indigo diner shadow that makes the yellow hanging drip pop dramatically
        let dripHalo = Math.max(0.0, 1.0 - Math.hypot(x - 680.0, y - 965.0) / 240.0);
        let darkCorner = Math.max(shadowAO, dripHalo * 0.82);

        C = 0.52 + 0.36 * darkCorner;
        M = 0.24 + 0.34 * darkCorner;
        Y = 0.04 + 0.14 * darkCorner;
        K = 0.16 + 0.68 * Math.pow(darkCorner, 1.25);
        detail = darkCorner * 0.5;
      }

      C_buf[idx] = Math.max(0.0, Math.min(1.0, C));
      M_buf[idx] = Math.max(0.0, Math.min(1.0, M));
      Y_buf[idx] = Math.max(0.0, Math.min(1.0, Y));
      K_buf[idx] = Math.max(0.0, Math.min(1.0, K));
      D_buf[idx] = Math.max(0.0, Math.min(1.0, detail));
    }
  }
}

function sampleBuffer(buf, x, y) {
  let gx = Math.max(0.0, Math.min(GRID_W - 1.001, x * 0.5 - 0.5));
  let gy = Math.max(0.0, Math.min(GRID_H - 1.001, y * 0.5 - 0.5));
  let ix = Math.floor(gx);
  let iy = Math.floor(gy);
  let fx = gx - ix;
  let fy = gy - iy;
  let idx = iy * GRID_W + ix;
  let v00 = buf[idx];
  let v10 = buf[idx + 1];
  let v01 = buf[idx + GRID_W];
  let v11 = buf[idx + GRID_W + 1];
  return (v00 + fx * (v10 - v00)) * (1.0 - fy) + (v01 + fx * (v11 - v01)) * fy;
}

// Render a single CMYK process channel as graduated Ben-Day dots + stippled pen dots
function renderCMYKChannel(buf, hexColor, screenAngleDeg, pitch, seedOffset) {
  let rad = screenAngleDeg * (Math.PI / 180.0);
  let cosA = Math.cos(rad);
  let sinA = Math.sin(rad);
  const cx = 600.0;
  const cy = 600.0;
  const halfDiag = 870.0;

  let s = seedOffset >>> 0;
  const nextRand = () => {
    s = (Math.imul(1664525, s) + 1013904223) >>> 0;
    return (s & 0xfffffff) / 0xfffffff;
  };

  let fineStipples = [];

  // 1. Graduated Ben-Day Dot Pass
  brush.set("benday_core", hexColor, 1.0);

  for (let gy = -halfDiag; gy <= halfDiag; gy += pitch) {
    let rowIdx = Math.round(gy / pitch);
    // Hexagonal Ben-Day offset on alternating rows for classic comic/print rosette packing
    let rowShift = (rowIdx & 1) * (pitch * 0.5);

    for (let gx = -halfDiag; gx <= halfDiag; gx += pitch) {
      let rx = gx + rowShift;
      let ry = gy;

      let x = cx + rx * cosA - ry * sinA;
      let y = cy + rx * sinA + ry * cosA;

      if (x < -14.0 || x > 1214.0 || y < -14.0 || y > 1214.0) continue;

      let val = sampleBuffer(buf, x, y);
      let det = sampleBuffer(D_buf, x, y);

      if (val < 0.028) continue;

      // In sparse highlight zones (like the bun's highlights), probabilistically thin out dots
      // and transition to tiny stippled pen pinpricks
      if (val < 0.19) {
        let keepProb = Math.pow(val / 0.19, 1.25);
        if (nextRand() > keepProb) continue;
        let jx = x + (nextRand() - 0.5) * 3.8;
        let jy = y + (nextRand() - 0.5) * 3.8;
        if (jx >= -10 && jx <= 1210 && jy >= -10 && jy <= 1210) {
          fineStipples.push(jx, jy, 0.55 + val * 2.8);
        }
        continue;
      }

      // Subtle organic hand-registration jitter so up close it feels like stippled ink
      let jitterAmp = (1.0 - val * 0.65) * 1.15;
      let dxJ = (nextRand() - 0.5) * jitterAmp;
      let dyJ = (nextRand() - 0.5) * jitterAmp;
      let px = x + dxJ;
      let py = y + dyJ;

      // Graduated Ben-Day diameter: scales from small dots in midtones to dense overlapping dots in char marks
      let normV = (val - 0.15) / 0.85;
      let targetDiam = pitch * (0.24 + 1.14 * Math.pow(normV, 0.78));
      let w = targetDiam / 7.2;

      let ang = nextRand() * Math.PI * 2.0;
      let halfL = Math.max(0.48, 0.44 * w);
      let lx = Math.cos(ang) * halfL;
      let ly = Math.sin(ang) * halfL;

      brush.strokeWeight(w);
      brush.line(px - lx, py - ly, px + lx, py + ly);

      // Add satellite stippled pen dots around high-detail edges (blisters, crumb pores, char marks, drip)
      if (det > 0.32 || val > 0.72) {
        let numSat = val > 0.78 ? 2 : 1;
        for (let k = 0; k < numSat; k++) {
          if (nextRand() < 0.62) {
            let sAng = nextRand() * Math.PI * 2.0;
            let sDist = targetDiam * (0.42 + nextRand() * 0.36);
            let sx = px + Math.cos(sAng) * sDist;
            let sy = py + Math.sin(sAng) * sDist;
            if (sx >= -10 && sx <= 1210 && sy >= -10 && sy <= 1210) {
              let sv = sampleBuffer(buf, sx, sy);
              if (sv > 0.14) {
                fineStipples.push(sx, sy, 0.65 + sv * 1.15);
              }
            }
          }
        }
      }
    }
  }

  // 2. Pure Stippled Pen Pass ("rotring" / "stipple_dot") for micro-detail resolution & sparse highlights
  // Also sample stochastic stipples along high-detail features (blister rims, crumb pores, drip meniscus)
  for (let i = 0; i < 2400; i++) {
    let sx = nextRand() * 1200.0;
    let sy = nextRand() * 1200.0;
    let det = sampleBuffer(D_buf, sx, sy);
    if (det < 0.25 && nextRand() > 0.25) continue;
    let sv = sampleBuffer(buf, sx, sy);
    if (sv > 0.08 && nextRand() < sv * (0.45 + 0.55 * det)) {
      fineStipples.push(sx, sy, 0.55 + sv * 1.25);
    }
  }

  if (fineStipples.length > 0) {
    brush.set("stipple_dot", hexColor, 1.0);
    for (let i = 0; i < fineStipples.length; i += 3) {
      let sx = fineStipples[i];
      let sy = fineStipples[i + 1];
      let sw = fineStipples[i + 2];
      let ang = nextRand() * Math.PI * 2.0;
      let halfL = Math.max(0.42, 0.35 * sw);
      let lx = Math.cos(ang) * halfL;
      let ly = Math.sin(ang) * halfL;
      brush.strokeWeight(sw);
      brush.line(sx - lx, sy - ly, sx + lx, sy + ly);
    }
  }

  // 3. Crisp Technical Pen ("rotring") pinprick stipples for ultra-fine up-close pen texture
  brush.set("rotring", hexColor, 1.0);
  for (let i = 0; i < 1600; i++) {
    let sx = nextRand() * 1200.0;
    let sy = nextRand() * 1200.0;
    let sv = sampleBuffer(buf, sx, sy);
    let det = sampleBuffer(D_buf, sx, sy);
    if (sv > 0.05 && nextRand() < (sv * 0.45 + det * 0.45)) {
      let ang = nextRand() * Math.PI * 2.0;
      let len = 0.65 + sv * 0.85;
      brush.strokeWeight(0.55 + sv * 0.65);
      brush.line(sx, sy, sx + Math.cos(ang) * len, sy + Math.sin(ang) * len);
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // Cool arctic-white printmaking paper ground
  background("#EFF5FA");
  brush.noFill();
  brush.noHatch();
  brush.noField();

  // Base halftone screen pitch (in pixels on 1200x1200 canvas)
  const PITCH = 10.6;

  // 1. Process Yellow (0 deg screen angle) - Electric mustard, warm bun crust & sear glow
  renderCMYKChannel(Y_buf, "#FFE600", 0.0, PITCH, 104729);

  // 2. Process Magenta (75 deg screen angle) - Juicy frankfurter meat, toasted crust & warm shadows
  renderCMYKChannel(M_buf, "#E6007E", 75.0, PITCH, 209381);

  // 3. Process Cyan (15 deg screen angle) - Cool palette shadows, grazing grease sheen & background
  renderCMYKChannel(C_buf, "#009FE3", 15.0, PITCH, 318493);

  // 4. Luminous Mustard Caustic Stipple Pass (keeps the glossy mustard & drip dazzlingly bright)
  brush.set("stipple_dot", "#FFEA00", 1.0);
  let ms = 774123;
  const mRand = () => {
    ms = (Math.imul(1664525, ms) + 1013904223) >>> 0;
    return (ms & 0xfffffff) / 0xfffffff;
  };
  for (let i = 0; i < 1800; i++) {
    let mx = mRand() * 1200.0;
    let my = mRand() * 1200.0;
    let gx = Math.floor(mx * 0.5);
    let gy = Math.floor(my * 0.5);
    let idx = gy * GRID_W + gx;
    if (MAT_buf[idx] === 4) {
      let yv = Y_buf[idx];
      let cv = C_buf[idx];
      if (yv > 0.65 && cv < 0.35 && mRand() < yv) {
        let w = 0.75 + yv * 0.65;
        let ang = mRand() * Math.PI * 2.0;
        brush.strokeWeight(w);
        brush.line(mx - Math.cos(ang) * 0.5, my - Math.sin(ang) * 0.5, mx + Math.cos(ang) * 0.5, my + Math.sin(ang) * 0.5);
      }
    }
  }

  // 5. Process Black (45 deg screen angle) - Dense overlapping char marks, deep creases & drip contrast
  renderCMYKChannel(K_buf, "#101622", 45.0, PITCH, 429587);

  noLoop();
}

