// ============================================================================
// GEOMETRY & SPOTLIGHT CLIPPING UTILITIES
// ============================================================================

function spotDist(x, y) {
  let dx = x - SPOT.x;
  let dy = y - SPOT.y;
  let c = cos(SPOT.angle);
  let s = sin(SPOT.angle);
  let rx = (dx * c - dy * s) / SPOT.rx;
  let ry = (dx * s + dy * c) / SPOT.ry;
  return sqrt(rx * rx + ry * ry);
}

function spotPoint(thetaDeg, rScale = 1.0, shiftX = 0, shiftY = 0) {
  let lx = cos(thetaDeg) * SPOT.rx * rScale;
  let ly = sin(thetaDeg) * SPOT.ry * rScale;
  let c = cos(SPOT.angle);
  let s = sin(SPOT.angle);
  return [
    SPOT.x + shiftX + lx * c + ly * s,
    SPOT.y + shiftY - lx * s + ly * c
  ];
}

function spotEllipsePoly(rScale = 1.0, steps = 72, shiftX = 0, shiftY = 0, jitter = 0) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let r = rScale + (jitter > 0 ? random(-jitter, jitter) : 0);
    pts.push(spotPoint(a, r, shiftX, shiftY));
  }
  return pts;
}

function cleanPts(pts) {
  if (!pts || pts.length === 0) return [];
  let out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - out[out.length - 1][0];
    let dy = pts[i][1] - out[out.length - 1][1];
    if (dx * dx + dy * dy > 0.3) out.push(pts[i]);
  }
  return out;
}

function safeSpline(pts, curv = 0.5) {
  let c = cleanPts(pts);
  if (c.length >= 2) brush.spline(c, curv);
}

function safeShape(pts, curv = 0.12, closed = true) {
  let c = cleanPts(pts);
  if (c.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < c.length; i++) {
    if (c[i].length >= 3) brush.vertex(c[i][0], c[i][1], c[i][2]);
    else brush.vertex(c[i][0], c[i][1]);
  }
  brush.endShape(closed);
}

function intersectSpotEdge(pA, pB, maxD = 1.0) {
  let dA = spotDist(pA[0], pA[1]);
  let aInside = dA <= maxD;
  let lo = 0, hi = 1;
  for (let iter = 0; iter < 8; iter++) {
    let mid = 0.5 * (lo + hi);
    let xm = lerp(pA[0], pB[0], mid);
    let ym = lerp(pA[1], pB[1], mid);
    if ((spotDist(xm, ym) <= maxD) === aInside) lo = mid;
    else hi = mid;
  }
  let t = 0.5 * (lo + hi);
  let res = [lerp(pA[0], pB[0], t), lerp(pA[1], pB[1], t)];
  if (pA.length >= 3 && pB.length >= 3) res.push(lerp(pA[2], pB[2], t));
  return res;
}

function clipPolylineToSpot(pts, maxD = 1.0) {
  if (!pts || pts.length < 2) return [];
  let fine = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i], p1 = pts[i + 1];
    let d = dist(p0[0], p0[1], p1[0], p1[1]);
    let steps = max(1, ceil(d / 5));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let p = [lerp(p0[0], p1[0], t), lerp(p0[1], p1[1], t)];
      if (p0.length >= 3 && p1.length >= 3) p.push(lerp(p0[2], p1[2], t));
      fine.push(p);
    }
  }
  fine.push(pts[pts.length - 1]);

  let segments = [];
  let current = [];
  for (let i = 0; i < fine.length; i++) {
    let p = fine[i];
    let inside = spotDist(p[0], p[1]) <= maxD;
    if (inside) {
      if (current.length === 0 && i > 0) {
        current.push(intersectSpotEdge(fine[i - 1], p, maxD));
      }
      current.push(p);
    } else {
      if (current.length > 0) {
        current.push(intersectSpotEdge(fine[i - 1], p, maxD));
        if (current.length >= 2) segments.push(current);
        current = [];
      }
    }
  }
  if (current.length >= 2) segments.push(current);
  return segments;
}

function drawClippedSpline(pts, curv = 0.5, maxD = 1.0) {
  let segs = clipPolylineToSpot(pts, maxD);
  for (let s of segs) {
    safeSpline(s, curv);
  }
}

function drawClippedLine(x1, y1, x2, y2, maxD = 1.0) {
  let segs = clipPolylineToSpot([[x1, y1], [x2, y2]], maxD);
  for (let s of segs) {
    let a = s[0], b = s[s.length - 1];
    if (dist(a[0], a[1], b[0], b[1]) > 0.4) {
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }
}

// ============================================================================
// 1. DENSE CHARCOAL DARKNESS BASE
// ============================================================================

function drawCharcoalDarknessBase() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noStroke();

  // Four quadrant charcoal masses enveloping the spotlight oval
  let ringAngles = [
    [0, 95],
    [90, 185],
    [180, 275],
    [270, 365]
  ];
  let darkCols = ["#120e0c", "#0e0b09", "#15110e", "#0c0a08"];

  for (let q = 0; q < 4; q++) {
    let a0 = ringAngles[q][0];
    let a1 = ringAngles[q][1];
    let pts = [];
    for (let a = a0; a <= a1; a += 8) {
      pts.push(spotPoint(a, 1.02));
    }
    for (let a = a1; a >= a0; a -= 12) {
      pts.push(spotPoint(a, 2.35));
    }
    brush.mass("charcoal", darkCols[q], {
      precision: 0.35,
      strength: 0.92,
      gradient: 0.15,
      outline: false
    });
    safeShape(pts, 0.05, true);
  }
  brush.noMass();

  // Tactile sweeping charcoal strokes across the outer void
  let sootPalette = ["#080706", "#110d0b", "#181310", "#211914", "#0c0908"];
  for (let i = 0; i < 380; i++) {
    let ang = random(360);
    let r = random(1.03, 2.25);
    let pCenter = spotPoint(ang, r);
    if (pCenter[0] < -80 || pCenter[0] > 1280 || pCenter[1] < -80 || pCenter[1] > 1280) continue;

    let tangent = ang + 90 + random(-22, 22);
    let halfLen = random(45, 150);
    let x1 = pCenter[0] - cos(tangent) * halfLen;
    let y1 = pCenter[1] - sin(tangent) * halfLen * 0.65;
    let x2 = pCenter[0] + cos(tangent) * halfLen;
    let y2 = pCenter[1] + sin(tangent) * halfLen * 0.65;

    if (spotDist(x1, y1) < 1.01 || spotDist(x2, y2) < 1.01) continue;

    let col = random(sootPalette);
    let bName = i % 3 === 0 ? "velvet_soot" : "heavy_charcoal";
    brush.set(bName, col, random(0.8, 1.6));
    brush.line(x1, y1, x2, y2);
  }

  // Cross-grain raw umber/bistre charcoal hatch in the upper darkness for depth
  for (let i = 0; i < 160; i++) {
    let x = random(20, 1180);
    let y = random(20, 460);
    if (spotDist(x, y) < 1.05) continue;
    let len = random(50, 140);
    let a = random(-35, 35);
    let x2 = x + cos(a) * len;
    let y2 = y + sin(a) * len;
    if (spotDist(x2, y2) < 1.05) continue;
    brush.set("charcoal", random(["#1a1410", "#120e0b", "#241b15", "#090706"]), random(0.7, 1.3));
    brush.line(x, y, x2, y2);
  }
}

