// ============================================================================
// 3. FORENSIC RINK HISTORY (OLD BLADE SCRATCHES CLIPPED AT SPOTLIGHT EDGE)
// ============================================================================

function drawRinkHistoryScratches() {
  // Sweeping arcs of previous glides, crossovers, and three-turns across the ice
  for (let i = 0; i < 95; i++) {
    let x0 = random(100, 1100);
    let y0 = random(420, 990);
    let len = random(140, 520);
    let baseAng = random(-38, 38) + (random() < 0.35 ? 155 : 0);
    let curveRate = random(-0.18, 0.18);

    let pts = [];
    let shadowPts = [];
    let steps = 14;
    let cx = x0, cy = y0;
    let ang = baseAng;
    for (let s = 0; s <= steps; s++) {
      pts.push([cx, cy, random(0.4, 1.1)]);
      shadowPts.push([cx + 1.2, cy + 1.6, random(0.4, 1.0)]);
      let stepLen = len / steps;
      cx += cos(ang) * stepLen;
      cy += sin(ang) * stepLen * 0.62;
      ang += curveRate * 8;
    }

    // Cool steel-blue groove shadow
    let grooveCol = random(["#4d6f87", "#6789a1", "#39566b", "#7c9ab0", "#8c755e"]);
    brush.set("2H", grooveCol, random(0.45, 0.95));
    drawClippedSpline(shadowPts, 0.5, 0.996);

    // Forensic white/ivory specular catch-light on the scratch lip
    let hiCol = random(["#ffffff", "#fffaf0", "#eef6fa", "#f5e6cf"]);
    brush.set("fine_needle", hiCol, random(0.55, 1.15));
    drawClippedSpline(pts, 0.5, 0.997);
  }

  // Extra-sharp boundary-crossing scratches around the perimeter to emphasize abrupt cutoff
  for (let i = 0; i < 55; i++) {
    let edgeAng = random(360);
    let pEdge = spotPoint(edgeAng, 1.0);
    let inAng = edgeAng + 180 + random(-55, 55);
    let inLen = random(65, 220);
    let outLen = random(20, 50);

    let pIn = [
      pEdge[0] + cos(inAng) * inLen,
      pEdge[1] + sin(inAng) * inLen * 0.65
    ];
    let pMid = [
      lerp(pIn[0], pEdge[0], 0.5) + random(-15, 15),
      lerp(pIn[1], pEdge[1], 0.5) + random(-10, 10)
    ];
    let pOut = [
      pEdge[0] - cos(inAng) * outLen,
      pEdge[1] - sin(inAng) * outLen * 0.65
    ];

    // Groove + crisp white edge strictly clipped to 0.998
    brush.set("HB", "#3b5970", random(0.6, 1.0));
    drawClippedSpline([[pIn[0], pIn[1] + 1.5], [pMid[0], pMid[1] + 1.5], [pOut[0], pOut[1] + 1.5]], 0.4, 0.998);

    brush.set("fine_needle", "#ffffff", random(0.8, 1.35));
    drawClippedSpline([pIn, pMid, pOut], 0.4, 0.998);
  }

  // Small chipped toe-pick divots scattered on the ice surface
  for (let i = 0; i < 42; i++) {
    let a = random(360);
    let r = sqrt(random(0.08, 0.94));
    let p = spotPoint(a, r);
    // Avoid placing right on top of the boot upper
    if (p[0] > 440 && p[0] < 850 && p[1] > 420 && p[1] < 640) continue;

    let w = random(5, 14);
    let h = random(2, 5);
    brush.set("2H", "#39576e", 0.7);
    brush.line(p[0] - w * 0.5, p[1], p[0] + w * 0.5, p[1] - h * 0.4);
    brush.set("fine_needle", "#ffffff", 0.95);
    brush.line(p[0] - w * 0.5, p[1] + 1.2, p[0] + w * 0.5, p[1] - h * 0.4 + 1.2);
  }
}

// ============================================================================
// 4. CARVED CRESCENT GOUGE & BOOT CAST SHADOW
// ============================================================================

function getCrescentSpine(t) {
  // t = 0: right spotlight edge entry (~1078, 632)
  // t = 1: front toe-pick contact (~440, 686)
  let x = lerp(1082, 440, t);
  let baseLineY = lerp(636, 686, t);
  let curveBow = -sin(t * 180) * 44 + sin(t * 360) * 8;
  return [x, baseLineY + curveBow];
}

function drawCarvedCrescentAndBootShadow() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // A. Dramatic cast shadow of the boot & ankle thrown toward the lower-left across the ice
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.55, 0.3);

  brush.fill("#1d3140", 135);
  safeShape([
    [445, 684],
    [795, 618],
    [650, 695],
    [485, 785],
    [255, 815],
    [185, 765],
    [225, 695],
    [355, 675]
  ], 0.25, true);

  brush.fill("#2b231d", 115);
  safeShape([
    [438, 682],
    [740, 626],
    [590, 688],
    [390, 742],
    [265, 735],
    [340, 682]
  ], 0.22, true);
  brush.noFill();

  // Cross-hatched core of the cast shadow right beneath the blade & sole
  for (let i = 0; i < 85; i++) {
    let t = random(0, 1);
    let x1 = lerp(240, 760, t) + random(-15, 15);
    let y1 = lerp(745, 622, t) + random(-8, 22);
    let len = random(35, 110);
    let ang = 166 + random(-10, 10);
    let x2 = x1 + cos(ang) * len;
    let y2 = y1 + sin(ang) * len * 0.55;
    if (spotDist(x1, y1) > 0.99 || spotDist(x2, y2) > 0.99) continue;
    brush.set("2B", random(["#1a2a36", "#263c4d", "#241d18", "#355166"]), random(0.6, 1.15));
    brush.line(x1, y1, x2, y2);
  }

  // B. The Carved Crescent Trench (sweeping from right spotlight edge into the braking blade)
  let upperRim = [];
  let lowerRim = [];
  let midTrench = [];
  let steps = 48;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let c = getCrescentSpine(t);
    // Trench widens as the blade rotates broadside into the stop
    let halfW = lerp(9, 34, pow(sin(t * 155), 0.85)) + (t > 0.5 ? 14 * (t - 0.5) : 0);
    let pUp = [c[0] + 4, c[1] - halfW * 0.72];
    let pLo = [c[0] - 6, c[1] + halfW * 1.05];
    if (spotDist(c[0], c[1]) <= 0.998) {
      upperRim.push(pUp);
      lowerRim.push(pLo);
      midTrench.push(c);
    }
  }

  let crescentPoly = upperRim.concat(lowerRim.slice().reverse());
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fill("#28475c", 165);
  safeShape(crescentPoly, 0.1, true);

  brush.fill("#48718c", 120);
  safeShape(crescentPoly, 0.1, true);
  brush.noFill();

  // Forensic blade-chatter ribs perpendicular to the crescent curve
  for (let i = 0; i <= 115; i++) {
    let t = i / 115;
    let c = getCrescentSpine(t);
    if (spotDist(c[0], c[1]) > 0.997) continue;

    let halfW = lerp(9, 34, pow(sin(t * 155), 0.85)) + (t > 0.5 ? 14 * (t - 0.5) : 0);
    let p1 = [c[0] + random(-2, 4), c[1] - halfW * 0.7];
    let pMid = [c[0] - 5 + random(-2, 2), c[1] + halfW * 0.15];
    let p2 = [c[0] - 7 + random(-3, 2), c[1] + halfW * 1.05];

    // Deep steel-blue chatter trough
    brush.set("2H", i % 2 === 0 ? "#1b3344" : "#31546b", random(0.65, 1.1));
    drawClippedSpline([p1, pMid, p2], 0.35, 0.997);

    // Razor-sharp white shaved-ice ridge beside each trough
    brush.set("fine_needle", i % 3 === 0 ? "#ffffff" : "#e8f2f7", random(0.7, 1.25));
    drawClippedSpline([
      [p1[0] - 1.4, p1[1] + 0.5],
      [pMid[0] - 1.4, pMid[1] + 0.5],
      [p2[0] - 1.4, p2[1] + 0.5]
    ], 0.35, 0.997);
  }

  // Deep shadow groove directly along the blade's biting edge and crescent inner wall
  brush.set("rotring", "#10202b", 1.35);
  drawClippedSpline(upperRim, 0.4, 0.998);

  brush.set("2B", "#1c3547", 1.1);
  drawClippedSpline(midTrench, 0.4, 0.998);

  // Crushed white snow lip piled up along the leading (lower) edge of the crescent
  for (let i = 0; i < lowerRim.length - 1; i++) {
    let p = lowerRim[i];
    brush.set("scuff_grain", "#ffffff", random(0.9, 1.7));
    drawClippedLine(p[0] - 4, p[1] - 2, p[0] + 6, p[1] + 3, 0.997);
    if (i % 2 === 0) {
      brush.set("fine_needle", "#fffaf0", 1.1);
      drawClippedLine(p[0] - 2, p[1], p[0] + 5, p[1] + 1.5, 0.997);
    }
  }
}

