    brush.set("fine_needle", col, random(0.65, 1.15));
    brush.line(x, yTop, x - 3, yBot);
  }

  // 4. Blinding specular hollow-grind highlight along the bottom biting edge & top bevel
  brush.set("fine_needle", "#ffffff", 1.45);
  safeSpline([[442, 686], [518, 680], [665, 650], [812, 617], [868, 602]], 0.25);

  brush.set("fine_needle", "#fff6e0", 1.15);
  safeSpline([[454, 673], [520, 668], [665, 638], [812, 605], [870, 591]], 0.25);

  // 5. Forensic Toe Picks (4 sharp serrated teeth at the left tip of the blade)
  const pickTeeth = [
    [[454, 654], [439, 661], [447, 666]],
    [[447, 666], [432, 673], [443, 676]],
    [[443, 676], [435, 682], [446, 683]],
    [[446, 683], [440, 688], [454, 685]]
  ];
  for (let pt of pickTeeth) {
    brush.set("rotring", "#0d1821", 1.1);
    safeSpline(pt, 0.05);
    brush.set("fine_needle", "#ffffff", 1.25);
    brush.line(pt[0][0], pt[0][1] - 0.8, pt[1][0], pt[1][1] - 0.8);
  }

  // 6. Sole plate & heel plate mounting screws
  const screwLocs = [
    [472, 640], [512, 635], [568, 628], [615, 622],
    [728, 583], [772, 574], [818, 564]
  ];
  for (let sc of screwLocs) {
    brush.set("rotring", "#1a0f08", 0.9);
    brush.circle(sc[0], sc[1], 2.2, 0.1);
    brush.set("fine_needle", "#ffffff", 1.0);
    brush.line(sc[0] - 1.5, sc[1] - 1, sc[0] + 1.5, sc[1] - 1);
  }
}

// ============================================================================
// 7. WARM STACKED-LEATHER HEEL & OUTSOLE (WARM PALETTE ANCHOR)
// ============================================================================

function drawStackedLeatherHeelAndSole() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // A. Stacked leather heel block
  const heelBlock = [
    [706, 536], // Top front of heel
    [846, 504], // Top rear of heel
    [838, 558], // Bottom rear on heel plate
    [712, 585], // Bottom front on heel plate
    [709, 560]  // Concave heel breast waist
  ];

  brush.wash("#592e14", 250);
  safeShape(heelBlock, 0.06, true);
  brush.noWash();

  // 8 horizontal compressed leather lifts in warm mahogany, burnt sienna, and amber ochre
  const liftColors = [
    "#3d1d0a", "#78411c", "#4f2810", "#9c592b",
    "#5c3014", "#b56e39", "#693818", "#8c5025"
  ];
  for (let i = 0; i < 8; i++) {
    let t = (i + 0.5) / 8;
    let xL = lerp(706, 712, t);
    let yL = lerp(536, 585, t);
    let xR = lerp(846, 838, t);
    let yR = lerp(504, 558, t);

    // Warm sunlit right/center side of the heel stack
    brush.set("cpencil", liftColors[i], 1.6);
    brush.line(xL, yL, xR, yR);

    // Golden-amber catch-light along each leather lamination seam
    brush.set("fine_needle", i % 2 === 0 ? "#e6ab6e" : "#c78648", 0.9);
    brush.line(xL + 14, yL - 2.5, xR - 4, yR + 0.8);

    // Dark shadow on the left (heel breast) side of the stack
    brush.set("2B", "#261206", 1.2);
    brush.line(xL, yL, xL + 22, lerp(yL, yR, 0.16));
  }

  // Vertical leather grain & tiny brass heel nails along the bottom lift
  for (let i = 0; i < 24; i++) {
    let t = i / 23;
    let xTop = lerp(710, 844, t);
    let yTop = lerp(537, 505, t);
    let xBot = lerp(713, 837, t);
    let yBot = lerp(584, 557, t);
    brush.set("2H", t < 0.25 ? "#210f05" : "#4a250f", 0.65);
    brush.line(xTop, yTop, xBot, yBot);

    if (i % 2 === 1 && t > 0.12) {
      brush.set("fine_needle", "#ffdfb3", 1.05);
      brush.line(xBot, yBot - 3.5, xBot, yBot - 1.2);
    }
  }

  // B. Curved warm leather outsole (from toe cap under the ball up into the high arch waist)
  const outsolePoly = [
    [443, 634], // Toe tip top of welt
    [515, 631],
    [578, 622],
    [645, 588], // Arch rise
    [706, 536], // Meets heel breast top
    [708, 548], // Meets heel breast bottom
    [648, 600],
    [580, 632],
    [515, 640],
    [446, 643]  // Toe tip bottom on sole plate
  ];

  brush.noStroke();
  brush.wash("#6e3c1b", 250);
  safeShape(outsolePoly, 0.12, true);
  brush.noWash();

  // Warm sienna & golden-ochre modeling along the outsole edge
  brush.set("cpencil", "#b8753c", 1.45);
  safeSpline([[444, 638], [515, 635], [578, 626], [646, 593], [707, 542]], 0.25);

  brush.set("rotring", "#2b1407", 1.15);
  safeSpline([[446, 643], [515, 640], [580, 632], [648, 600], [708, 548]], 0.25);

  // Forensic welt lockstitching along the top lip of the leather sole
  for (let i = 0; i < 34; i++) {
    let t = i / 33;
    let x, y;
    if (t < 0.55) {
      let u = t / 0.55;
      x = lerp(445, 578, u);
      y = lerp(634, 622, u) + sin(u * 180) * 2;
    } else {
      let u = (t - 0.55) / 0.45;
      x = lerp(578, 705, u);
      y = lerp(622, 537, u) + sin(u * 180) * 6;
    }
    brush.set("fine_needle", "#f5e3c6", 0.9);
    brush.line(x, y - 0.5, x + 3.2, y - 1.2);
  }
}

// ============================================================================
// 8. SCUFFED WHITE LEATHER BOOT, STITCHING, HOOKS & CRISSCROSSED LACES
// ============================================================================

function drawSkaterBootAndLaces() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Clip the lit boot upper polygon right along the spotlight oval boundary (y ~ 426..445)
  const litBootPoly = [
    [443, 634], // Toe welt
    [436, 606], // Toe front curve
    [446, 582], // Toe dome
    [476, 565], // Toe crown
    [522, 558], // Vamp top
    [552, 553], // Throat base
    [586, 518], // Lower instep
    [618, 482], // Below flex notch
    [627, 480], // Flex notch apex
    [619, 470], // Above flex notch
    [634, 427], // Front cuff at spotlight cutoff!
    [730, 427], // Mid cuff at spotlight cutoff!
    [833, 444], // Backstay at spotlight cutoff!
    [852, 475], // Heel counter curve
    [846, 504], // Top of stacked heel rear
    [706, 536], // Top of stacked heel front
    [645, 588], // High arch waist
    [578, 622], // Ball of foot
    [515, 631]
  ];

  // Padded leather tongue protruding slightly along the throat/instep
  const litTonguePoly = [
    [546, 554],
    [538, 545],
    [572, 508],
    [605, 466],
    [620, 426], // Tongue cut off at spotlight edge!
    [644, 426],
    [625, 475],
    [590, 520]
  ];

  // 1. Opaque warm ivory/alabaster base wash for tongue & boot
  brush.wash("#dfd3c0", 245);
  safeShape(litTonguePoly, 0.1, true);

  brush.wash("#f5efe4", 252);
  safeShape(litBootPoly, 0.08, true);
  brush.noWash();

  // 2. Watercolor & dry-media 3D form shading on the leather boot
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.45, 0.2);

  // Cool steel-blue reflected shadow along the lower belly of the vamp, arch, and heel cup
  // (reflected upward from the blue-white ice!)
  brush.fill("#68869e", 82);
  safeShape([
    [444, 633],
    [515, 630],
    [578, 621],
    [645, 587],
    [706, 536],
    [845, 504],
    [840, 485],
    [715, 510],
    [635, 558],
    [555, 598],
    [455, 612]
  ], 0.18, true);

  // Warm parchment/taupe shadow in the ankle hollow (below the malleolus bump) & flex crease
  brush.fill("#b8a58e", 78);
  safeShape([
    [620, 478],
    [695, 472],
    [755, 495],
    [695, 528],
    [625, 515]
  ], 0.25, true);

  // Warm alabaster highlight on the crown of the toe box & ankle bone (malleolus)
  brush.fill("#fffdf9", 130);
  safeShape([
    [448, 594],
    [478, 567],
    [535, 560],
    [565, 578],
    [495, 605]
  ], 0.25, true);

  brush.fill("#fffdf9", 115);
  safeShape([
    [695, 442],
    [758, 440],
    [775, 472],
    [712, 482]
  ], 0.3, true);
  brush.noFill();

  // 3. Fine contoured leather shading & ankle flex compression creases
  for (let i = 0; i < 140; i++) {
    let t = random(0, 1);
    let x = lerp(448, 835, t);
    let yBase = t < 0.45 ? lerp(628, 608, t / 0.45) : lerp(608, 502, (t - 0.45) / 0.55);
    let y = yBase - random(2, 42);
    if (spotDist(x, y) > 0.996) continue;

    let ang = t < 0.45 ? -10 + random(-12, 12) : -28 + random(-15, 15);
    let len = random(18, 48);
    let col = y > yBase - 16
      ? random(["#54738c", "#6f8ea6", "#8aa4b8", "#7d7061"])
      : random(["#d6c8b4", "#e6dac8", "#c4b39b", "#fffcf5"]);

    brush.set("leather_shader", col, random(0.65, 1.25));
    drawClippedLine(x, y, x + cos(ang) * len, y + sin(ang) * len, 0.996);
  }

  // Deep compression creases radiating from the ankle flex notch (caused by the hard stop!)
  const flexCreases = [
    [[625, 480], [668, 486], [712, 502]],
    [[621, 473], [662, 474], [702, 482]],
    [[616, 488], [655, 502], [692, 520]],
    [[588, 518], [630, 532], [665, 550]]
  ];
  for (let fc of flexCreases) {
    // Dark warm-slate crease trough
    brush.set("2B", "#6e6256", 0.95);
    drawClippedSpline(fc, 0.4, 0.997);
    brush.set("fine_needle", "#4a4138", 0.75);
    drawClippedSpline(fc, 0.4, 0.997);

    // Bright ivory leather fold ridge just above each trough
    let hiFc = fc.map(p => [p[0], p[1] - 2.4]);
    brush.set("fine_needle", "#fffef9", 1.15);
    drawClippedSpline(hiFc, 0.4, 0.997);
  }

  // 4. FORENSIC SCUFFS & BLADE-NICKS ON THE WHITE LEATHER (Toe Box, Vamp & Arch)
  const scuffClusters = [
    { x: 468, y: 604, w: 38, h: 18, ang: -18, n: 26 }, // Toe cap abrasion
    { x: 522, y: 596, w: 46, h: 22, ang: -12, n: 32 }, // Ball-of-foot blade graze
    { x: 492, y: 578, w: 32, h: 14, ang: 8,   n: 18 }, // Upper toe scuff
    { x: 615, y: 562, w: 42, h: 18, ang: -26, n: 24 }, // Arch side scuff
    { x: 765, y: 488, w: 36, h: 16, ang: -14, n: 18 }  // Heel counter scuff
  ];

  for (let sc of scuffClusters) {
    for (let i = 0; i < sc.n; i++) {
      let sx = sc.x + random(-sc.w * 0.5, sc.w * 0.5);
      let sy = sc.y + random(-sc.h * 0.5, sc.h * 0.5);
      let len = random(6, 22);
      let a = sc.ang + random(-18, 18);
      let col = random(["#63584c", "#827465", "#473f36", "#9c8d7c", "#526370"]);
      brush.set(i % 3 === 0 ? " fine_needle".trim() : "scuff_grain", col, random(0.55, 1.1));
      drawClippedLine(sx, sy, sx + cos(a) * len, sy + sin(a) * len, 0.997);

      // Tiny peeled-leather highlight under the sharpest blade nicks
      if (i % 4 === 0) {
        brush.set("fine_needle", "#ffffff", 0.85);
        drawClippedLine(sx, sy + 1.3, sx + cos(a) * len * 0.8, sy + sin(a) * len * 0.8 + 1.3, 0.997);
      }
    }
  }

  // 5. Boot Seams & Forensic Double-Row Lockstitching (Cut off abruptly at spotlight edge!)
  // Eyelet facing border curve
  const facingSeam1 = [[522, 558], [556, 562], [598, 524], [632, 484], [629, 468], [648, 412]];
  const facingSeam2 = facingSeam1.map(p => [p[0] + 4.5, p[1] + 1.5]);

  // Backstay heel counter seam
  const backSeam1 = [[822, 510], [832, 474], [814, 420]];
  const backSeam2 = backSeam1.map(p => [p[0] - 5, p[1] + 1]);

  brush.set("2H", "#8c7f70", 0.75);
  drawClippedSpline(facingSeam1, 0.3, 0.998);
  drawClippedSpline(backSeam1, 0.3, 0.998);

  // Individual micro-stitches along all four seam rows
  const stitchCurves = [facingSeam1, facingSeam2, backSeam1, backSeam2];
  for (let curve of stitchCurves) {
    let segs = clipPolylineToSpot(curve, 0.998);
    for (let seg of segs) {
      for (let i = 0; i < seg.length - 1; i++) {
        let p0 = seg[i], p1 = seg[i + 1];
        let xm = lerp(p0[0], p1[0], 0.65);
        let ym = lerp(p0[1], p1[1], 0.65);
        // Dark needle hole + raised white thread dash
        brush.set("fine_needle", "#4f453b", 0.75);
        brush.line(p0[0], p0[1], xm, ym);
        brush.set("fine_needle", "#ffffff", 0.95);
        brush.line(p0[0] - 0.8, p0[1] - 0.5, xm - 0.8, ym - 0.5);
      }
    }
  }

  // Crisp silhouette edge of the boot & flex notch
  brush.set("rotring", "#332b24", 0.95);
  drawClippedSpline([
    [443, 634], [436, 606], [446, 582], [476, 565], [522, 558],
    [552, 553], [586, 518], [618, 482], [627, 480], [619, 470], [636, 418]
  ], 0.15, 0.998);

  brush.set("fine_needle", "#ffffff", 1.25);
  drawClippedSpline([
    [438, 604], [448, 582], [478, 566], [522, 559], [552, 554]
  ], 0.25, 0.998);

  // 6. FORENSIC EYELETS, CHROME LACE HOOKS & 3D CRISSCROSSED WHITE LACES
  // Define the stations along the throat & ankle cuff (lower 5 = eyelets, upper 3 = chrome hooks)
  const laceNodes = [
    { xR: 556, yR: 550, xL: 542, yL: 544, type: "eyelet" },
    { xR: 572, yR: 534, xL: 557, yL: 527, type: "eyelet" },
    { xR: 588, yR: 517, xL: 572, yL: 509, type: "eyelet" },
    { xR: 603, yR: 500, xL: 586, yL: 492, type: "eyelet" },
    { xR: 617, yR: 483, xL: 600, yL: 474, type: "eyelet" },
    { xR: 626, yR: 463, xL: 608, yL: 454, type: "hook" },
    { xR: 632, yR: 444, xL: 614, yL: 435, type: "hook" },
    { xR: 638, yR: 424, xL: 620, yL: 415, type: "hook" } // Right on the spotlight cutoff edge!
  ];

  // Draw metal eyelets & projecting chrome hooks
  for (let nd of laceNodes) {
    if (spotDist(nd.xR, nd.yR) <= 0.999) {
      if (nd.type === "eyelet") {
        // Dark grommet hole + bright silver rim
        brush.set("rotring", "#1f1915", 1.1);
        brush.circle(nd.xR, nd.yR, 2.8, 0.1);
        brush.set("fine_needle", "#ffffff", 1.15);
        brush.arc(nd.xR, nd.yR, 3.2, -140, 40);
      } else {
        // Projecting 3D chrome lace hook with dark cast shadow & warm/white specular glint
        brush.set("rotring", "#241d17", 1.25);
        brush.line(nd.xR - 2, nd.yR + 2, nd.xR + 5, nd.yR + 3);
        brush.set("2B", "#4d6678", 1.3);
        brush.circle(nd.xR + 1, nd.yR, 3.8, 0.15);
        brush.set("fine_needle", "#fff6e0", 1.3);
        brush.line(nd.xR - 2, nd.yR - 1.5, nd.xR + 4, nd.yR - 0.5);
        brush.set("fine_needle", "#ffffff", 1.4);
        brush.circle(nd.xR + 1, nd.yR - 1, 1.8, 0.05);
      }
    }
  }

  // Draw the crisscrossed woven cotton laces with cast shadows, 3D thickness, and weave ticks
  for (let i = 0; i < laceNodes.length - 1; i++) {
    let cur = laceNodes[i];
    let nxt = laceNodes[i + 1];

    // Strap A: from cur.L across to nxt.R (underneath strap)
    drawForensicLaceStrap(
      [cur.xL, cur.yL],
      [lerp(cur.xL, nxt.xR, 0.5) - 2, lerp(cur.yL, nxt.yR, 0.5) - 1],
      [nxt.xR, nxt.yR]
    );

    // Strap B: from cur.R across to nxt.L (overlapping top strap)
    drawForensicLaceStrap(
      [cur.xR, cur.yR],
      [lerp(cur.xR, nxt.xL, 0.5) + 1, lerp(cur.yR, nxt.yL, 0.5) - 1.5],
      [nxt.xL, nxt.yL]
    );
  }

  // Dramatic tied bow loops & dangling lace ends at the top ankle — sliced by the spotlight edge!
  const bowLoop1 = [[626, 428], [596, 434], [575, 448], [588, 456], [616, 440], [628, 429]];
  const bowLoop2 = [[630, 426], [658, 412], [682, 418], [672, 432], [646, 434], [632, 428]];
  const laceTail1 = [[624, 430], [602, 458], [588, 492], [582, 518]];
  const laceTail2 = [[628, 430], [640, 464], [644, 498]];

  drawForensicLaceStrap(bowLoop1[0], bowLoop1[2], bowLoop1[4]);
  drawForensicLaceStrap(bowLoop2[0], bowLoop2[2], bowLoop2[4]);
  drawForensicLaceStrap(laceTail1[0], laceTail1[1], laceTail1[3]);
  drawForensicLaceStrap(laceTail2[0], laceTail2[1], laceTail2[2]);

  // Plastic/metal aglet tips at the ends of the two hanging lace tails
  const aglets = [
    [[588, 492], [582, 518]],
    [[640, 464], [644, 498]]
  ];
  for (let ag of aglets) {
    let pA = [lerp(ag[0][0], ag[1][0], 0.65), lerp(ag[0][1], ag[1][1], 0.65)];
    let pB = ag[1];
    brush.set("rotring", "#2b231c", 1.15);
    drawClippedLine(pA[0] + 1.2, pA[1] + 1.2, pB[0] + 1.2, pB[1] + 1.2, 0.998);
    brush.set("cpencil", "#e6c79c", 1.35);
    drawClippedLine(pA[0], pA[1], pB[0], pB[1], 0.998);
    brush.set("fine_needle", "#ffffff", 1.1);
    drawClippedLine(pA[0] - 0.8, pA[1], pB[0] - 0.8, pB[1], 0.998);
  }
}

function drawForensicLaceStrap(p0, pMid, p1) {
  let pts = [p0, pMid, p1];

  // 1. Dark cast shadow of the lace strap onto the leather tongue/boot beneath
  let shadowPts = pts.map(p => [p[0] + 1.8, p[1] + 2.6]);
  brush.set("2B", "#2e261f", 1.2);
  drawClippedSpline(shadowPts, 0.4, 0.998);

  // 2. Warm taupe/putty underside bevel of the woven cotton lace
  let underPts = pts.map(p => [p[0] + 0.6, p[1] + 1.2]);
  brush.set("HB", "#9e8f7e", 1.35);
  drawClippedSpline(underPts, 0.4, 0.998);

  // 3. Thick bright warm-white body of the flat lace
  brush.set("cpencil", "#faf6ee", 1.85);
  drawClippedSpline(pts, 0.4, 0.998);

  // 4. Razor-sharp pure white top catch-light (clipped dead at spotlight boundary!)
  let topPts = pts.map(p => [p[0] - 0.6, p[1] - 0.9]);
  brush.set("fine_needle", "#ffffff", 1.35);
  drawClippedSpline(topPts, 0.4, 0.998);
}

// ============================================================================
// 9. EXPLOSIVE FAN OF SHAVED ICE & FROZEN AIRBORNE CRYSTALS
// ============================================================================

function drawShavedIceFanAndCrystals() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // A. Translucent steel-blue & warm-ivory base washes for the erupting snow plume
  // Erupting from the blade edge (440, 686)..(720, 636) toward the left/lower-left
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.6, 0.25);

  // Cool steel-blue shadowed underside of the airborne ice cloud
  brush.fill("#587e99", 85);
  safeShape([
    [442, 684],
    [665, 648],
    [520, 712],
    [340, 768],
    [175, 765],
    [142, 685],
    [245, 630],
    [385, 655]
  ], 0.3, true);

  // Luminous warm-white & alabaster sunlit top crest of the shaved ice fan
  brush.fill("#fffdf9", 150);
  safeShape([
    [440, 682],
    [595, 658],
    [435, 692],
    [265, 715],
    [145, 665],
    [158, 575],
    [295, 585],
    [415, 648]
  ], 0.3, true);
  brush.noFill();

  // B. Dry-media snow masses (dense pulverized ice sheets right where the blade planes the ice)
  const snowClumps = [
    [[442, 684], [545, 666], [485, 702], [365, 712], [345, 678]],
    [[375, 682], [448, 672], [385, 642], [255, 622], [235, 668]],
    [[295, 665], [375, 698], [265, 738], [162, 708], [178, 652]],
    [[525, 668], [645, 648], [585, 682], [475, 692]]
  ];

  for (let i = 0; i < snowClumps.length; i++) {
    brush.mass("cpencil", i % 2 === 0 ? "#ffffff" : "#f7f0e4", {
      precision: 0.45,
      strength: 0.85,
      gradient: 0.25,
      outline: false
    });
    safeShape(snowClumps[i], 0.25, true);
  }
  brush.noMass();

  // C. Parabolic trajectories of shaved ice ribbons & powder streams
  // All clipped strictly at the spotlight oval boundary (d <= 0.998)!
  for (let i = 0; i < 230; i++) {
    // Launch point along the biting edge of the blade (heavy concentration near toe/ball)
    let u = pow(random(0, 1), 1.35);
    let x0 = lerp(438, 765, u);
    let y0 = lerp(685, 625, u) + random(-4, 6);

    // Fan angles: erupting forward-left (155° to 222°), with a few high plumes (135° to 155°)
    let launchAng = random(146, 218) + u * 12;
    let speed = random(90, 390) * (1.15 - u * 0.45);
    let gravity = random(18, 68);

    let pts = [];
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let px = x0 + cos(launchAng) * speed * t;
      let py = y0 + sin(launchAng) * speed * t * 0.68 + gravity * t * t;
      let pWeight = lerp(1.3, 0.25, t);
      pts.push([px, py, pWeight]);
    }

    // Choose between shadow steel-blue under-streams, warm-ivory mid-streams, and pure white crests
    let col, bName, wMult;
    if (i < 55) {
      col = random(["#5c829c", "#7ba0b8", "#436680", "#cbb9a3"]);
      bName = "ice_shave";
      wMult = random(0.7, 1.35);
    } else if (i < 165) {
      col = random(["#ffffff", "#fffdf9", "#f7efe2", "#e8f3fa"]);
      bName = "ice_shave";
      wMult = random(0.6, 1.4);
    } else {
      col = "#ffffff";
      bName = "fine_needle";
      wMult = random(0.75, 1.35);
    }

    brush.set(bName, col, wMult);
    drawClippedSpline(pts, 0.45, 0.998);
  }

  // D. Fine mist & stippled ice powder inside the fan (using spray brush)
  for (let i = 0; i < 65; i++) {
    let u = random(0, 1);
    let x1 = lerp(445, 650, u);
    let y1 = lerp(682, 646, u);
    let ang = random(152, 212);
    let len = random(80, 340);
    let x2 = x1 + cos(ang) * len;
    let y2 = y1 + sin(ang) * len * 0.65;
    let col = i % 4 === 0 ? "#9ec0d6" : i % 3 === 0 ? "#fff5e0" : "#ffffff";
    brush.set("spray", col, random(0.7, 1.35));
    drawClippedLine(x1, y1, x2, y2, 0.992);
  }

  // E. Over 1,100 individual frozen airborne ice crystal specks & diamond glints
  // Concentrated in the fan and suspended across the spotlight beam, cut off at d = 0.997
  for (let i = 0; i < 1150; i++) {
    let cx, cy;
    if (i < 820) {
      // Fan distribution radiating from the blade toward the left spotlight boundary
      let u = pow(random(0, 1), 0.85);
      let xOrigin = lerp(438, 750, random(0, 1));
      let yOrigin = lerp(685, 626, (xOrigin - 438) / 312);
      let ang = random(138, 226);
      let distFromBlade = u * random(35, 420);
      cx = xOrigin + cos(ang) * distFromBlade;
      cy = yOrigin + sin(ang) * distFromBlade * 0.68 + random(-25, 35) * u;
    } else {
      // Wider theatrical halo of suspended ice dust catching the follow-spot beam
      let a = random(360);
      let r = sqrt(random(0.05, 0.995));
      let p = spotPoint(a, r);
      cx = p[0];
      cy = p[1];
      // Keep the boot leather face clean so only a few crystals glint in front of it
      if (cx > 460 && cx < 830 && cy > 435 && cy < 610 && random() < 0.78) continue;
    }

    let d = spotDist(cx, cy);
    if (d > 0.997) continue; // Abrupt guillotine at spotlight boundary!

    let crystalCol = random([
      "#ffffff", "#ffffff", "#fffdf7", "#fff3db", "#d8effc", "#b5d8ed"
    ]);

    if (i % 7 === 0) {
      // Sharp crystalline diamond glint
      brush.set("crystal_glint", crystalCol, random(0.55, 1.35));
      brush.line(cx, cy, cx + random(1.5, 4.5), cy + random(-2.5, 2.5));
    } else if (i % 19 === 0) {
      // 4-point specular star crystal catching the follow-spot lens
      let arm = random(2.2, 5.2);
      brush.set("fine_needle", "#ffffff", random(0.85, 1.3));
      brush.line(cx - arm, cy, cx + arm, cy);
      brush.line(cx, cy - arm, cx, cy + arm);
    } else {
      // Crisp micro-fleck of shaved ice
      let dx = random(-3.2, 3.2);
      let dy = random(-2.0, 2.0);
      brush.set("fine_needle", crystalCol, random(0.6, 1.35));
      brush.line(cx, cy, cx + dx, cy + dy);
    }
  }
}

// ============================================================================
// 10. SPOTLIGHT LENS RIM & FINAL DENSE CHARCOAL GUILLOTINE COLLAR
// ============================================================================

function drawSpotlightEdgeRimAndFinalCharcoal() {
  // 1. Forensic spotlight cut-line across the boot cuff, laces, and tongue (around y ~ 426..444)
  // Where the hard edge of the follow-spot slices across the 3D leather and laces,
  // a theatrical halogen spotlight creates a razor-thin warm golden-ivory rim!
  let bootCutPts = [];
  for (let a = -112; a <= -52; a += 1.5) {
    let p = spotPoint(a, 0.998);
    if (p[0] >= 572 && p[0] <= 838) {
      bootCutPts.push(p);
    }
  }
  if (bootCutPts.length >= 2) {
    brush.set("cpencil", "#e8b474", 1.35);
    safeSpline(bootCutPts, 0.3);
    brush.set("fine_needle", "#fff8e8", 1.25);
    safeSpline(bootCutPts.map(p => [p[0], p[1] + 1.2]), 0.3);
  }

  // 2. Subtle warm amber/ochre + cool steel optical fringe around the entire 360° spotlight oval
  for (let pass = 0; pass < 36; pass++) {
    let a0 = pass * 10 + random(-3, 3);
    let a1 = a0 + random(12, 22);
    let r = random(0.992, 1.002);
    let arcPts = [];
    for (let a = a0; a <= a1; a += 3) {
      arcPts.push(spotPoint(a, r));
    }
    let rimCol = pass % 3 === 0 ? "#b87f44" : pass % 2 === 0 ? "#416078" : "#805c38";
    brush.set("2H", rimCol, random(0.65, 1.15));
    safeSpline(arcPts, 0.4);
  }

  // 3. Final dense charcoal guillotine collar immediately outside d = 1.003
  // Ensures every mark outside the follow-spot oval is swallowed by velvety total darkness
  const guillotinePalette = ["#090706", "#0f0c0a", "#14100d", "#070605"];
  for (let ring = 0; ring < 4; ring++) {
    let rScale = 1.008 + ring * 0.018;
    for (let seg = 0; seg < 36; seg++) {
      let aStart = seg * 10 + random(-2, 2);
      let aEnd = aStart + 13;
      let pts = [];
      for (let a = aStart; a <= aEnd; a += 3) {
        pts.push(spotPoint(a, rScale + random(-0.003, 0.003)));
      }
      let bName = ring === 0 ? "charcoal" : "heavy_charcoal";
      let col = guillotinePalette[(ring + seg) % guillotinePalette.length];
      brush.set(bName, col, ring === 0 ? 0.95 : 1.35);
      safeSpline(pts, 0.35);
    }
  }

  // Crisp charcoal edge-trimming strokes right along d = 1.003
  for (let i = 0; i < 180; i++) {
    let a = (i / 180) * 360 + random(-1, 1);
    let p1 = spotPoint(a - 2.2, 1.004);
    let p2 = spotPoint(a + 2.2, 1.006);
    brush.set("2B", "#0a0807", random(0.9, 1.35));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// Hyperrealism in p5.brush:
// Worn white cotton skipping rope in kolam-like loops around a 5x5 grid of smooth river pebbles
// on freshly swept terracotta/burnt-sienna earth, lit by low raking morning sun.

const SEED = 4219;
const LIGHT_ANGLE = 23; // Degrees: raking morning light from upper-left to lower-right
let LX, LY;             // Light direction unit vector

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  LX = cos(LIGHT_ANGLE);
  LY = sin(LIGHT_ANGLE);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Base burnt-sienna / terracotta ground
  background("#b05636");
  brush.noField();

  // 2. Atmospheric ground washes & dusty edges
  renderTerracottaGround();

  // 3. Parallel arcing broom striations in the red dust
  renderBroomStriations();

  // 4. Build the 5x5 grid of river pebbles
  const pebbles = createPebbleGrid();

  // 5. Build the kolam-like dropped skipping rope path & handles
  const ropeData = buildKolamRopeAndHandles(pebbles);

  // 6. Render pebble cast shadows & rope ground cast shadows first
  renderPebbleShadows(pebbles);
  renderRopeGroundShadow(ropeData.points);
  renderHandleShadows(ropeData.handles);

  // 7. Render the 25 smooth river pebbles in 3D relief
  renderPebbles(pebbles);

  // 8. Render the rope lower pass (z < 3.5), crossing occlusion, and upper pass (z >= 3.5)
  renderRopePass(ropeData.points, 0, 3.5);
  renderRopeCrossingOcclusion(ropeData.points, ropeData.crossings);
  renderRopePass(ropeData.points, 3.5, 99);

  // 9. Render the turned wooden handles, stopper knots, and frayed cotton tips
  for (let h of ropeData.handles) {
    renderWoodenHandle(h);
    renderFrayedTip(h);
  }

  // 10. Final raking sunlight dust, chalk powder motes & dusty vignette
  renderFinalDustAndVignette();

  noLoop();
}

// ============================================================================
// 1. TERRACOTTA / BURNT-SIENNA GROUND
// ============================================================================
function renderTerracottaGround() {
  brush.noStroke();

  // Warm sunlit core across the upper-left and center
  brush.fill("#cf7952", 65);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.65, 0.25);
  brush.circle(460, 460, 480, 0.25);
  brush.circle(620, 580, 420, 0.25);

  // Deeper burnt-sienna & raw-umber tonal pools toward outer edges
  const edgePools = [
    [120, 140, 340, "#7d351d", 55],
    [1080, 150, 380, "#6b2b16", 65],
    [140, 1060, 380, "#6e2d18", 65],
    [1080, 1080, 420, "#542110", 75],
    [600, 1140, 360, "#662814", 55],
    [1140, 600, 350, "#5e2512", 60],
    [60, 600, 310, "#75301a", 50],
    [600, 60, 310, "#75301a", 50]
  ];
  for (let [x, y, r, col, op] of edgePools) {
    brush.fill(col, op);
    brush.fillBleed(0.5, "out");
    brush.fillTexture(0.7, 0.3);
    brush.circle(x, y, r, 0.3);
  }
  brush.noFill();

  // Dry earth tooth using wide spray and charcoal dust passes
  for (let i = 0; i < 160; i++) {
    let x = random(30, 1170);
    let y = random(30, 1170);
    let dFromCenter = dist(x, y, 560, 560);
    let col = dFromCenter < 430
      ? (random() < 0.55 ? "#d98862" : "#964125")
      : (random() < 0.65 ? "#632714" : "#8a391f");
    brush.set("spray", col, random(1.2, 2.6));
    brush.line(x, y, x + random(-90, 90), y + random(-90, 90));
  }
}

// ============================================================================
// 2. PARALLEL ARCING BROOM STRIATIONS IN THE SWEPT DUST
// ============================================================================
function renderBroomStriations() {
  // Primary coconut-broom sweep pivot located off bottom-left
  const pivX = -460;
  const pivY = 1480;

  // Secondary subtle overlapping sweep near top-left corner
  const piv2X = -380;
  const piv2Y = -280;

  // Draw secondary sweep faintly in upper-left / lower-right
  for (let r = 520; r < 1950; r += 8.5) {
    let angSpan = 55;
    let aStart = 12 + random(-3, 3);
    let aEnd = aStart + angSpan;
    for (let a = aStart; a < aEnd; a += random(7, 13)) {
      let a2 = min(aEnd, a + random(4.5, 9.5));
      let x1 = piv2X + cos(a) * r;
      let y1 = piv2Y + sin(a) * r;
      let x2 = piv2X + cos(a2) * r;
      let y2 = piv2Y + sin(a2) * r;
      if (x1 < -20 || x1 > 1220 || y1 < -20 || y1 > 1220) continue;
      if (x2 < -20 || x2 > 1220 || y2 < -20 || y2 > 1220) continue;

      brush.set("cpencil", "#82361d", random(0.28, 0.5));
      brush.line(x1, y1, x2, y2);
    }
  }

  // Primary sweeping parallel arcs across the courtyard
  for (let r = 820; r < 2480; r += 5.2) {
    let nVal = noise(r * 0.015);
    let rJit = r + (nVal - 0.5) * 3.5;

    // Sweep angle range that covers the 1200x1200 canvas
    let aMin = -68;
    let aMax = -12;
    let a = aMin + random(0, 3);

    while (a < aMax) {
      let segAngle = random(3.5, 8.5);
      let aNext = min(aMax, a + segAngle);
      let aMid = (a + aNext) * 0.5;

      let x1 = pivX + cos(a) * rJit;
      let y1 = pivY + sin(a) * rJit;
      let xm = pivX + cos(aMid) * rJit;
      let ym = pivY + sin(aMid) * rJit;
      let x2 = pivX + cos(aNext) * rJit;
      let y2 = pivY + sin(aNext) * rJit;

      a = aNext + random(0.4, 2.2);

      // Cull segments outside canvas
      if ((x1 < -15 && x2 < -15) || (x1 > 1215 && x2 > 1215) ||
          (y1 < -15 && y2 < -15) || (y1 > 1215 && y2 > 1215)) {
        continue;
      }

      // Distance from warm sunlit center modulates striation contrast
      let dCenter = dist(xm, ym, 560, 540);
      let darkCol = dCenter < 460
        ? (random() < 0.6 ? "#6e2c17" : "#85381f")
        : (random() < 0.65 ? "#4a1c0d" : "#612512");
      let litCol = dCenter < 480
        ? (random() < 0.55 ? "#e39c76" : "#cf825b")
        : (random() < 0.6 ? "#b86843" : "#9e5130");

      // Furrow shadow line
      let wFurrow = random(0.32, 0.68);
      brush.set("cpencil", darkCol, wFurrow);
      brush.spline([[x1, y1, 0.5], [xm, ym, 0.9], [x2, y2, 0.4]], 0.35);

      // Sunlit dust ridge immediately adjacent (shifted toward upper-left light)
      if (random() < 0.82) {
        let off = random(1.4, 2.4);
        brush.set("2H", litCol, random(0.28, 0.58));
        brush.spline([
          [x1 - LX * off, y1 - LY * off, 0.4],
          [xm - LX * off, ym - LY * off, 0.85],
          [x2 - LX * off, y2 - LY * off, 0.4]
        ], 0.35);
      }
    }
  }

  // Tiny scattered red-earth grit & sand granules caught by the broom
  for (let i = 0; i < 320; i++) {
    let gx = random(35, 1165);
    let gy = random(35, 1165);
    let gr = random(0.8, 2.4);
    // Tiny shadow of grit
    brush.set("2B", "#2e1208", gr * 0.55);
    brush.line(gx + LX * 1.6, gy + LY * 1.6, gx + LX * 3.4, gy + LY * 3.4);
    // Grit body
    brush.set("cpencil", random() < 0.6 ? "#e8aa87" : "#702c16", gr * 0.65);
    brush.line(gx, gy, gx + 0.8, gy + 0.4);
  }
}

// ============================================================================
// 3. EVEN 5x5 GRID OF SMOOTH RIVER PEBBLES
// ============================================================================
function createPebbleGrid() {
  const pebbles = [];
  const spacing = 146;
  const startX = 600 - 2 * spacing;
  const startY = 600 - 2 * spacing;

  // Subtle mineral palettes within the monochrome-umber-chalk-sienna family
  const stoneTypes = [
    { base: "#4f3c33", dark: "#261913", mid: "#6e564a", light: "#ab9284", spec: "#dfd0c5", vein: "#cbb8ab" },
    { base: "#614b40", dark: "#2e1f18", mid: "#806659", light: "#bda496", spec: "#ede0d5", vein: "#d9c7ba" },
    { base: "#42322b", dark: "#1f140f", mid: "#5c473e", light: "#967e72", spec: "#cfc0b6", vein: "#b59f92" },
    { base: "#73594b", dark: "#36241b", mid: "#917464", light: "#ccb4a4", spec: "#f5ebe2", vein: "#e8d8cb" },
    { base: "#593d31", dark: "#2b1911", mid: "#785546", light: "#b58e7c", spec: "#e6cfc3", vein: "#cfaea0" }
  ];

  for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 5; col++) {
      let cx = startX + col * spacing + random(-4.2, 4.2);
      let cy = startY + row * spacing + random(-4.2, 4.2);
      let rx = random(18.5, 23.0);
      let ry = rx * random(0.78, 0.94);
      let rot = random(-40, 40);
      let st = stoneTypes[(row * 5 + col + floor(random(2))) % stoneTypes.length];

      pebbles.push({
        col, row,
        x: cx, y: cy,
        rx, ry, rot,
        palette: st,
        hasVein: random() < 0.55,
        veinAngle: random(-60, 60),
        asym: random(-0.08, 0.08)
      });
    }
  }
  return pebbles;
}

function getPebbleContour(p, scaleRx = 1, scaleRy = 1, offsetX = 0, offsetY = 0, steps = 20) {
  let pts = [];
  let cRot = cos(p.rot);
  let sRot = sin(p.rot);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let radMod = 1 + p.asym * cos(a) + 0.03 * sin(3 * a);
    let lx = cos(a) * p.rx * scaleRx * radMod;
    let ly = sin(a) * p.ry * scaleRy * radMod;
    let wx = p.x + offsetX + lx * cRot - ly * sRot;
    let wy = p.y + offsetY + lx * sRot + ly * cRot;
    pts.push([wx, wy]);
  }
  return pts;
}

function renderPebbleShadows(pebbles) {
  for (let p of pebbles) {
    // Soft outer umber shadow cast by low raking morning sun
    let shLen = (p.rx + p.ry) * 0.95;

    brush.noStroke();
    brush.fill("#261008", 95);
    brush.fillBleed(0.2, "out");
    brush.fillTexture(0.55, 0.3);
    let shPts = getPebbleContour(p, 1.02, 0.92, LX * shLen * 0.68, LY * shLen * 0.68, 18);
    brush.beginShape(0.35);
    for (let pt of shPts) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
    brush.noFill();

    // Dry charcoal & pencil hatched shadow gradient
    for (let pass = 0; pass < 26; pass++) {
      let t = pass / 25;
      let distShift = lerp(2, shLen * 1.18, t);
      let spread = sin(t * 180) * 0.92 + 0.15;
      let sx = p.x + LX * distShift;
      let sy = p.y + LY * distShift;
      let perpX = -LY * p.ry * spread;
      let perpY = LX * p.rx * spread;

      let col = t < 0.45 ? "#170904" : (t < 0.78 ? "#2e140a" : "#4f2212");
      let w = lerp(0.85, 0.35, t);
      brush.set(t < 0.5 ? "charcoal" : "cpencil", col, w);
      brush.line(
        sx - perpX + random(-1.5, 1.5),
        sy - perpY + random(-1.5, 1.5),
        sx + perpX + random(-1.5, 1.5),
        sy + perpY + random(-1.5, 1.5)
      );
    }

    // Subtle displaced dust rim around base of pebble
    brush.set("cpencil", "#d98f68", 0.45);
    let rimPts = getPebbleContour(p, 1.12, 1.12, -LX * 1.5, -LY * 1.5, 16);
    for (let i = 0; i < 8; i++) {
      let p1 = rimPts[i];
      let p2 = rimPts[(i + 1) % 16];
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

function renderPebbles(pebbles) {
  for (let p of pebbles) {
    const pal = p.palette;
    const basePts = getPebbleContour(p, 1.0, 1.0, 0, 0, 20);

    // 1. Solid wash base so ground striations are completely occluded
    brush.noStroke();
    brush.wash(pal.base, 245);
    brush.beginShape(0.35);
    for (let pt of basePts) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
    brush.noWash();

    // 2. Concentric 3D dome shading shifting toward upper-left light source
    const layers = 14;
    for (let l = 0; l < layers; l++) {
      let t = l / (layers - 1); // 0 = outer rim, 1 = sunlit crown
      let sc = lerp(0.96, 0.16, t);
      let shiftX = -LX * p.rx * 0.38 * t;
      let shiftY = -LY * p.ry * 0.38 * t;
      let ring = getPebbleContour(p, sc, sc, shiftX, shiftY, 18);

      let col;
      if (t < 0.25) col = pal.dark;
      else if (t < 0.52) col = pal.base;
      else if (t < 0.78) col = pal.mid;
      else if (t < 0.92) col = pal.light;
      else col = pal.spec;

      brush.set("cpencil", col, lerp(0.65, 0.45, t));
      for (let i = 0; i < ring.length; i++) {
        let p1 = ring[i];
        let p2 = ring[(i + 1) % ring.length];
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // 3. Crescent core shadow on the lower-right side of the pebble dome
    for (let a = -55; a <= 105; a += 8) {
      let rad = a;
      let rIn = 0.58;
      let rOut = 0.92;
      for (let rStep = rIn; rStep <= rOut; rStep += 0.11) {
        let x1 = p.x + cos(rad) * p.rx * rStep;
        let y1 = p.y + sin(rad) * p.ry * rStep;
        let x2 = p.x + cos(rad + 14) * p.rx * rStep;
        let y2 = p.y + sin(rad + 14) * p.ry * rStep;
        // Warm terracotta bounce light right at the outer shadow edge
        let isBounce = rStep > 0.82;
        brush.set("cpencil", isBounce ? "#9e4d30" : pal.dark, isBounce ? 0.42 : 0.52);
        brush.line(x1, y1, x2, y2);
      }
    }

    // 4. Water-worn quartz vein (if present) curving across the stone dome
    if (p.hasVein) {
      let va = p.veinAngle;
      let vx1 = p.x - cos(va) * p.rx * 0.78;
      let vy1 = p.y - sin(va) * p.ry * 0.78;
      let vxm = p.x - LX * 3.5 + cos(va + 90) * 3.2;
      let vym = p.y - LY * 3.5 + sin(va + 90) * 3.2;
      let vx2 = p.x + cos(va) * p.rx * 0.78;
      let vy2 = p.y + sin(va) * p.ry * 0.78;
      brush.set("2H", pal.vein, 0.42);
      brush.spline([[vx1, vy1, 0.3], [vxm, vym, 0.9], [vx2, vy2, 0.3]], 0.4);
    }

    // 5. Chalk pastel highlight on the upper-left sunlit crown
    let hx = p.x - LX * p.rx * 0.36;
    let hy = p.y - LY * p.ry * 0.36;
    for (let k = 0; k < 10; k++) {
      let ang = LIGHT_ANGLE + 180 + random(-55, 55);
      let d1 = random(1, 5.5);
      let d2 = d1 + random(2.5, 5.5);
      brush.set(k < 5 ? "cpencil" : "2H", k < 4 ? pal.spec : "#faf3ec", random(0.35, 0.6));
      brush.line(
        hx + cos(ang) * d1, hy + sin(ang) * d1,
        hx + cos(ang) * d2, hy + sin(ang) * d2
      );
    }

    // 6. Crisp dark contact crevice around the base of the pebble
    brush.set("2B", "#170904", 0.55);
    for (let i = 0; i < basePts.length; i++) {
      let p1 = basePts[i];
      let p2 = basePts[(i + 1) % basePts.length];
      let midX = (p1[0] + p2[0]) * 0.5 - p.x;
      let midY = (p1[1] + p2[1]) * 0.5 - p.y;
      let dotL = (midX * LX + midY * LY) / p.rx;
      if (dotL > -0.35) {
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }
}

// ============================================================================
// 4. KOLAM-LIKE SKIPPING ROPE PATH & WOODEN HANDLES
// ============================================================================
function buildKolamRopeAndHandles(pebbles) {
  const S = 146;
  const gx = (u) => 600 + (u - 2) * S;
  const gy = (v) => 600 + (v - 2) * S;
  const R = 0.41; // Orbit radius in grid units (~60px around each pebble)

  // Continuous figure-eight Sikku-Kolam waypoints (u, v) weaving around the 5x5 pebbles,
  // with organic child-dropped slack near the two handle ends.
  const rawGridUV = [
    // Exit Handle 1 collar in lower-left
    [-0.22, 4.18],
    [-0.12, 4.35],
    // Pebble (0,4) CCW bottom -> right
    [0.02, 4 + R],
    [0 + R, 4.00],
    // Pebble (0,3) CW bottom -> left -> top
    [0.00, 3 + R],
    [0 - R, 3.00],
    [0.00, 3 - R],
    // Pebble (1,2) CCW left -> bottom -> right -> top
    [1 - R, 2.00],
    [1.00, 2 + R],
    [1 + R, 2.00],
    [1.00, 2 - R],
    // Pebble (0,2) CW top -> left -> bottom -> right
    [0.00, 2 - R],
    [0 - R, 2.00],
    [0.00, 2 + R],
    [0 + R, 2.00],
    // Pebble (0,1) CCW bottom -> right -> top -> left
    [0 + R, 1.00],
    [0.00, 1 - R],
    [0 - R, 1.00],
    [0.00, 1 + R],
    // Sweep up to Pebble (0,0) CW left -> top -> right
    [0 - R, 0.00],
    [0.00, 0 - R],
    [0 + R, 0.00],
    // Pebble (1,0) CCW bottom -> right -> top -> left
    [1.00, 0 + R],
    [1 + R, 0.00],
    [1.00, 0 - R],
    [1 - R, 0.00],
    // Pebble (1,1) CW left -> bottom -> right -> top
    [1 - R, 1.00],
    [1.00, 1 + R],
    [1 + R, 1.00],
    [1.00, 1 - R],
    // Pebble (2,0) CW left -> top -> right -> bottom
    [2 - R, 0.00],
    [2.00, 0 - R],
    [2 + R, 0.00],
    [2.00, 0 + R],
    // Pebble (2,1) CCW top -> left -> bottom -> right
    [2 - R, 1.00],
    [2.00, 1 + R],
    [2 + R, 1.00],
    [2.00, 1 - R],
    // Pebble (3,0) CW left -> top -> right
    [3 - R, 0.00],
    [3.00, 0 - R],
    [3 + R, 0.00],
    // Pebble (4,0) CCW bottom -> right -> top -> left
    [4.00, 0 + R],
    [4 + R, 0.00],
    [4.00, 0 - R],
    [4 - R, 0.00],
    // Pebble (3,1) CW right -> bottom -> left -> top
    [3 + R, 1.00],
    [3.00, 1 + R],
    [3 - R, 1.00],
    [3.00, 1 - R],
    // Pebble (4,1) CCW left -> bottom -> right -> top
    [4 - R, 1.00],
    [4.00, 1 + R],
    [4 + R, 1.00],
    // Pebble (4,2) CW top -> right -> bottom -> left
    [4.00, 2 - R],
    [4 + R, 2.00],
    [4.00, 2 + R],
    [4 - R, 2.00],
    // Pebble (3,2) CCW right -> top -> left -> bottom
    [3.00, 2 - R],
    [3 - R, 2.00],
    [3.00, 2 + R],
    [3 + R, 2.00],
    // Central Pebble (2,2) CW top -> right -> bottom -> left
    [2.00, 2 - R],
    [2 + R, 2.00],
    [2.00, 2 + R],
    [2 - R, 2.00],
    // Pebble (1,3) CCW top -> left -> bottom -> right
    [1.00, 3 - R],
    [1 - R, 3.00],
    [1.00, 3 + R],
    [1 + R, 3.00],
    // Pebble (1,4) CW top -> right -> bottom -> left
    [1.00, 4 - R],
    [1 + R, 4.00],
    [1.00, 4 + R],
    [1 - R, 4.00],
    // Back up around (2,3) CCW left -> bottom -> right -> top
    [2 - R, 3.00],
    [2.00, 3 + R],
    [2 + R, 3.00],
    [2.00, 3 - R],
    // Pebble (2,4) CW top -> right -> bottom -> left
    [2.00, 4 - R],
    [2 + R, 4.00],
    [2.00, 4 + R],
    [2 - R, 4.00],
    // Sweep across to Pebble (3,3) CCW left -> bottom -> right -> top
    [3 - R, 3.00],
    [3.00, 3 + R],
    [3 + R, 3.00],
    // Pebble (4,3) CW top -> right -> bottom -> left
    [4.00, 3 - R],
    [4 + R, 3.00],
    [4.00, 3 + R],
    [4 - R, 3.00],
    // Pebble (3,4) CCW top -> left -> bottom -> right
    [3.00, 4 - R],
    [3 - R, 4.00],
    [3.00, 4 + R],
    [3 + R, 4.00],
    // Pebble (4,4) CW top -> right -> bottom -> relaxed trail to Handle 2
    [4.00, 4 - R],
    [4 + R + 0.05, 3.98],
    [4.12, 4 + R + 0.06],
    [4.46, 4.32],
    [4.62, 3.92]
  ];

  // Convert to canvas coordinates with slight organic hand-dropped perturbation
  const ctrlPts = rawGridUV.map((uv, idx) => {
    let isEnd = idx < 2 || idx >= rawGridUV.length - 2;
    let jit = isEnd ? 0 : 5.5;
    return {
      x: gx(uv[0]) + (noise(idx * 0.37, 1) - 0.5) * jit * 2,
      y: gy(uv[1]) + (noise(idx * 0.37, 2) - 0.5) * jit * 2
    };
  });

  // Dense Catmull-Rom sampling
  let dense = [];
  const subSteps = 18;
  for (let i = 0; i < ctrlPts.length - 1; i++) {
    let p0 = ctrlPts[max(0, i - 1)];
    let p1 = ctrlPts[i];
    let p2 = ctrlPts[i + 1];
    let p3 = ctrlPts[min(ctrlPts.length - 1, i + 2)];
    for (let s = 0; s < subSteps; s++) {
      let t = s / subSteps;
      let pt = catmullRomPoint(p0, p1, p2, p3, t);
      dense.push(pt);
    }
  }
  dense.push({ x: ctrlPts[ctrlPts.length - 1].x, y: ctrlPts[ctrlPts.length - 1].y });

  // Relaxation + guaranteed pebble clearance pass
  for (let iter = 0; iter < 8; iter++) {
    for (let i = 2; i < dense.length - 2; i++) {
      for (let p of pebbles) {
        let dx = dense[i].x - p.x;
        let dy = dense[i].y - p.y;
        let d = sqrt(dx * dx + dy * dy);
        let minClear = max(p.rx, p.ry) + 23;
        if (d < minClear && d > 0.01) {
          let push = (minClear - d) * 0.65;
          dense[i].x += (dx / d) * push;
          dense[i].y += (dy / d) * push;
        }
      }
    }
    // Gentle Laplacian smoothing so curve stays silky smooth
    let copy = dense.map(p => ({ x: p.x, y: p.y }));
    for (let i = 2; i < dense.length - 2; i++) {
      dense[i].x = 0.22 * copy[i - 1].x + 0.56 * copy[i].x + 0.22 * copy[i + 1].x;
      dense[i].y = 0.22 * copy[i - 1].y + 0.56 * copy[i].y + 0.22 * copy[i + 1].y;
    }
  }

  // Resample at uniform arc length step = 2.5px
  const stepDist = 2.5;
  let uniformPts = [{ x: dense[0].x, y: dense[0].y, s: 0, z: 0 }];
  let accumS = 0;
  for (let i = 1; i < dense.length; i++) {
    let prev = uniformPts[uniformPts.length - 1];
    let d = dist(prev.x, prev.y, dense[i].x, dense[i].y);
    while (d >= stepDist) {
      let ang = atan2(dense[i].y - prev.y, dense[i].x - prev.x);
      let nx = prev.x + cos(ang) * stepDist;
      let ny = prev.y + sin(ang) * stepDist;
      accumS += stepDist;
      let nextPt = { x: nx, y: ny, s: accumS, z: 0 };
      uniformPts.push(nextPt);
      prev = nextPt;
      d = dist(prev.x, prev.y, dense[i].x, dense[i].y);
    }
  }

  // Compute tangent & normal at every point
  const N = uniformPts.length;
  for (let i = 0; i < N; i++) {
    let pPrev = uniformPts[max(0, i - 2)];
    let pNext = uniformPts[min(N - 1, i + 2)];
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let len = sqrt(dx * dx + dy * dy) || 1;
    uniformPts[i].tx = dx / len;
    uniformPts[i].ty = dy / len;
    uniformPts[i].nx = -uniformPts[i].ty;
    uniformPts[i].ny = uniformPts[i].tx;
  }

  // Detect self-crossings and elevate the upper branch smoothly
  let crossings = [];
  for (let i = 20; i < N - 20; i += 3) {
    for (let j = i + 45; j < N - 20; j += 3) {
      let d = dist(uniformPts[i].x, uniformPts[i].y, uniformPts[j].x, uniformPts[j].y);
      if (d < 16.5) {
        // Check if we already logged a nearby crossing
        let already = crossings.some(c => abs(c.i - i) < 30 && abs(c.j - j) < 30);
        if (!already) {
          // Alternate over/under weave like a real kolam / dropped rope
          let overIdx = (crossings.length % 2 === 0) ? j : i;
          let underIdx = (overIdx === j) ? i : j;
          crossings.push({ i, j, overIdx, underIdx });
        }
      }
    }
  }

  // Apply smooth Gaussian elevation bumps at over-crossings
  for (let c of crossings) {
    let centerIdx = c.overIdx;
    for (let k = max(0, centerIdx - 28); k <= min(N - 1, centerIdx + 28); k++) {
      let ds = (k - centerIdx) / 14.0;
      let bump = 9.5 * exp(-ds * ds);
      uniformPts[k].z = max(uniformPts[k].z, bump);
    }
  }

  // Also slightly elevate the two rope ends where they enter the raised wooden handle collars
  for (let k = 0; k < 22; k++) {
    let t = 1 - k / 22;
    uniformPts[k].z = max(uniformPts[k].z, 4.5 * t);
  }
  for (let k = N - 22; k < N; k++) {
    let t = (k - (N - 22)) / 22;
    uniformPts[k].z = max(uniformPts[k].z, 4.5 * t);
  }

  // Construct the two wooden handles aligned with the rope ends
  let startP = uniformPts[0];
  let endP = uniformPts[N - 1];

  // Handle 1 points backward from startP
  let h1DirX = -startP.tx;
  let h1DirY = -startP.ty;
  // Handle 2 points forward from endP
  let h2DirX = endP.tx;
  let h2DirY = endP.ty;

  const handles = [
    {
      collarX: startP.x - h1DirX * 4,
      collarY: startP.y - h1DirY * 4,
      dx: h1DirX,
      dy: h1DirY,
      length: 118,
      maxRadius: 16.5,
      seed: 101
    },
    {
      collarX: endP.x - h2DirX * 4,
      collarY: endP.y - h2DirY * 4,
      dx: h2DirX,
      dy: h2DirY,
      length: 118,
      maxRadius: 16.5,
      seed: 202
    }
  ];

  return { points: uniformPts, crossings, handles };
}

function catmullRomPoint(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x = 0.5 * (
    (2 * p1.x) +
    (-p0.x + p2.x) * t +
    (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 +
    (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3
  );
  let y = 0.5 * (
    (2 * p1.y) +
    (-p0.y + p2.y) * t +
    (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 +
    (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3
  );
  return { x, y };
}

// ============================================================================
// 5. ROPE GROUND SHADOW, 3-PLY TWISTED COTTON STRANDS & OVER-CROSSINGS
// ============================================================================
function renderRopeGroundShadow(pts) {
  const N = pts.length;
  // Multi-pass umber shadow offset along (LX, LY), modulated by elevation z
  for (let i = 0; i < N - 2; i += 2) {
    let p = pts[i];
    let p2 = pts[i + 2];
    let shDist = 11.5 + p.z * 1.85;
    let sx1 = p.x + LX * shDist;
    let sy1 = p.y + LY * shDist;
    let sx2 = p2.x + LX * shDist;
    let sy2 = p2.y + LY * shDist;

    // Outer soft shadow penumbra
    for (let off = -7.5; off <= 7.5; off += 2.5) {
      let col = abs(off) < 3.5 ? "#210d06" : "#421b0d";
      let w = abs(off) < 3.5 ? 0.95 : 0.65;
      brush.set("charcoal", col, w);
      brush.line(
        sx1 + p.nx * off, sy1 + p.ny * off,
        sx2 + p2.nx * off, sy2 + p2.ny * off
      );
    }

    // Contact shadow right under the shadow side of the rope (where z is low)
    if (p.z < 3.5) {
      let cOff = 6.2;
      let signN = (p.nx * LX + p.ny * LY) >= 0 ? 1 : -1;
      brush.set("2B", "#170803", 0.75);
      brush.line(
        p.x + p.nx * signN * cOff + LX * 2,
        p.y + p.ny * signN * cOff + LY * 2,
        p2.x + p2.nx * signN * cOff + LX * 2,
        p2.y + p2.ny * signN * cOff + LY * 2
      );
    }
  }
}

function renderRopeCrossingOcclusion(pts, crossings) {
  // Cast a crisp dark contact shadow from the upper strand across the lower strand
  for (let c of crossings) {
    let pOver = pts[c.overIdx];
    let pUnder = pts[c.underIdx];

    // Shadow cast onto the lower rope strand shifted slightly along light vector
    let cx = pOver.x + LX * 5.5;
    let cy = pOver.y + LY * 5.5;

    for (let s = -11; s <= 11; s += 2.2) {
      let sx = cx + pOver.tx * s;
      let sy = cy + pOver.ty * s;
      // Clip to width of lower strand
      let dUnder = (sx - pUnder.x) * pUnder.nx + (sy - pUnder.y) * pUnder.ny;
      if (abs(dUnder) < 9.5) {
        brush.set("charcoal", "#362016", 0.72);
        brush.line(
          sx - pOver.nx * 7.5, sy - pOver.ny * 7.5,
          sx + pOver.nx * 7.5, sy + pOver.ny * 7.5
        );
      }
    }
  }
}

function renderRopePass(pts, minZ, maxZ) {
  const N = pts.length;
  const ropeR = 8.2; // Rope half-width (total diameter ~16.4px)

  // Step 1: Solid opaque underpainting along the rope centerline so no broom lines peek through
  for (let i = 0; i < N - 2; i += 2) {
    let p = pts[i];
    if (p.z < minZ || p.z >= maxZ) continue;
    let p2 = pts[i + 2];

    for (let frac = -0.82; frac <= 0.82; frac += 0.27) {
      // Determine how much this longitudinal strip faces the upper-left light
      let worldNx = p.nx * frac;
      let worldNy = p.ny * frac;
      let lightDot = -(worldNx * LX + worldNy * LY); // + on lit side, - on shadow side

      let col;
      if (lightDot > 0.22) col = "#ede4da";
      else if (lightDot > -0.15) col = "#cfc0b2";
      else if (lightDot > -0.48) col = "#9e8372";
      else col = "#7d5b49";

      brush.set("cpencil", col, 0.95);
      brush.line(
        p.x + p.nx * ropeR * frac, p.y + p.ny * ropeR * frac,
        p2.x + p2.nx * ropeR * frac, p2.y + p2.ny * ropeR * frac
      );
    }
  }

  // Step 2: Meticulous 3-ply twisted cotton strand nodules every ~3 steps (7.5px)
  const twistStep = 3;
  for (let i = 2; i < N - 4; i += twistStep) {
    let p = pts[i];
    if (p.z < minZ || p.z >= maxZ) continue;

    // A 3-ply twisted rope has diagonal S-curved lobes crossing from -N to +N
    // while advancing forward along +T by ~9.5px.
    let adv = 9.5;
    let xStart = p.x - p.nx * ropeR * 0.95 - p.tx * (adv * 0.48);
    let yStart = p.y - p.ny * ropeR * 0.95 - p.ty * (adv * 0.48);
    let xMid   = p.x + p.tx * 0.8;
    let yMid   = p.y + p.ty * 0.8;
    let xEnd   = p.x + p.nx * ropeR * 0.95 + p.tx * (adv * 0.48);
    let yEnd   = p.y + p.ny * ropeR * 0.95 + p.ty * (adv * 0.48);

    // Check which side of the rope faces the morning light
    let nDotL = -(p.nx * LX + p.ny * LY); // > 0 if +N side is lit, < 0 if -N side is lit

    // 2a. Deep crevice line between adjacent 3-ply twists
    let crevShift = -3.6;
    brush.set("2B", "#4f3224", 0.52);
    brush.spline([
      [xStart + p.tx * crevShift, yStart + p.ty * crevShift, 0.5],
      [xMid   + p.tx * crevShift, yMid   + p.ty * crevShift, 0.85],
      [xEnd   + p.tx * crevShift, yEnd   + p.ty * crevShift, 0.5]
    ], 0.35);

    // Darker crevice accent on the shadowed side of the twist
    let shEndX = nDotL >= 0 ? xStart : xEnd;
    let shEndY = nDotL >= 0 ? yStart : yEnd;
    brush.set("2B", "#2e180f", 0.58);
    brush.line(
      xMid + p.tx * crevShift, yMid + p.ty * crevShift,
      shEndX + p.tx * crevShift, shEndY + p.ty * crevShift
    );

    // 2b. Twisted cotton fiber threads across the plump strand bundle
    for (let f = -2.2; f <= 2.2; f += 1.1) {
      let fx1 = xStart + p.tx * f;
      let fy1 = yStart + p.ty * f;
      let fxm = xMid   + p.tx * f;
      let fym = yMid   + p.ty * f;
      let fx2 = xEnd   + p.tx * f;
      let fy2 = yEnd   + p.ty * f;

      // Shadowed half of the twist bundle (with warm terracotta bounce light)
      let shCol = abs(f) > 1.5 ? "#8c6551" : "#b89f8e";
      brush.set("cpencil", shCol, 0.48);
      if (nDotL >= 0) {
        brush.spline([[fx1, fy1, 0.5], [fxm, fym, 0.85]], 0.3);
      } else {
        brush.spline([[fxm, fym, 0.85], [fx2, fy2, 0.5]], 0.3);
      }

      // Sunlit half of the twist bundle in warm chalk white
      let litCol = abs(f) < 1.2 ? "#faf6f0" : "#e6dcd1";
      brush.set("cpencil", litCol, 0.55);
      if (nDotL >= 0) {
        brush.spline([[fxm, fym, 0.85], [fx2, fy2, 0.55]], 0.3);
      } else {
        brush.spline([[fx1, fy1, 0.55], [fxm, fym, 0.85]], 0.3);
      }
    }

    // 2c. Pure white chalk pastel highlight on the sunlit crest of each twist nodule
    let crestSign = nDotL >= 0 ? 0.46 : -0.46;
    let cx = p.x + p.nx * ropeR * crestSign - LX * 1.1;
    let cy = p.y + p.ny * ropeR * crestSign - LY * 1.1;
    brush.set("cpencil", "#ffffff", 0.62);
    brush.line(
      cx - p.tx * 2.2 - p.nx * 1.2,
      cy - p.ty * 2.2 - p.ny * 1.2,
      cx + p.tx * 2.2 + p.nx * 1.2,
      cy + p.ty * 2.2 + p.ny * 1.2
    );

    // 2d. Scalloped outer contour bumps of the twisted strands
    let rimSign = 1;
    for (let side of [-1, 1]) {
      let rx1 = p.x + p.nx * side * ropeR - p.tx * 3.5;
      let ry1 = p.y + p.ny * side * ropeR - p.ty * 3.5;
      let rxm = p.x + p.nx * side * (ropeR + 1.1);
      let rym = p.y + p.ny * side * (ropeR + 1.1);
      let rx2 = p.x + p.nx * side * ropeR + p.tx * 3.5;
      let ry2 = p.y + p.ny * side * ropeR + p.ty * 3.5;

      let sideLit = -( (p.nx * side) * LX + (p.ny * side) * LY ) > 0;
      brush.set("2H", sideLit ? "#f5efe8" : "#5e3e2f", sideLit ? 0.45 : 0.52);
      brush.spline([[rx1, ry1, 0.4], [rxm, rym, 0.85], [rx2, ry2, 0.4]], 0.35);
    }

    // 2e. Worn fuzzy stray cotton fibers fraying out from the rope edges
    if (random() < 0.72) {
      let side = random() < 0.5 ? 1 : -1;
      let sideLit = -( (p.nx * side) * LX + (p.ny * side) * LY ) > 0;
      let bx = p.x + p.nx * side * (ropeR - 0.5);
      let by = p.y + p.ny * side * (ropeR - 0.5);
      let fLen = random(4.0, 10.5);
      let flare = random(0.3, 0.85);
      let dirSign = random() < 0.5 ? 1 : -1;
      let ex = bx + (p.tx * dirSign * (1 - flare) + p.nx * side * flare) * fLen;
      let ey = by + (p.ty * dirSign * (1 - flare) + p.ny * side * flare) * fLen;

      brush.set("2H", sideLit ? "#fcf9f5" : "#c7b19f", random(0.24, 0.4));
      brush.line(bx, by, ex, ey);
    }
  }
}

// ============================================================================
// 6. TURNED WOODEN HANDLES, STOPPER KNOTS & FRAYED COTTON TIPS
// ============================================================================
function getHandleRadius(t, maxR) {
  // Lathe-turned wooden handle profile for t in [0..1] (0 = collar, 1 = outer pommel)
  if (t < 0.08) {
    // Tapered collar ferrule
    return maxR * lerp(0.58, 0.76, t / 0.08);
  } else if (t < 0.16) {
    // Decorative turned bead ring
    let u = (t - 0.08) / 0.08;
    return maxR * (0.76 + 0.12 * sin(u * 180));
  } else if (t < 0.82) {
    // Ergonomic grip waist swelling gently toward the palm
    let u = (t - 0.16) / 0.66;
    return maxR * (0.72 + 0.28 * sin(u * 165));
  } else {
    // Rounded pommel end cap
    let u = (t - 0.82) / 0.18;
    return maxR * cos(u * 68) * 0.92;
  }
}

function renderHandleShadows(handles) {
  for (let h of handles) {
    const nx = -h.dy;
    const ny = h.dx;
    const steps = 22;

    // Build shadow polygon cast onto the swept red earth
    let shOutline = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let r = getHandleRadius(t, h.maxRadius);
      let shShift = 18 + r * 0.95;
      let ax = h.collarX + h.dx * (t * h.length) + LX * shShift;
      let ay = h.collarY + h.dy * (t * h.length) + LY * shShift;
      shOutline.push([ax + nx * r * 1.05, ay + ny * r * 1.05]);
    }
    for (let i = steps; i >= 0; i--) {
      let t = i / steps;
      let r = getHandleRadius(t, h.maxRadius);
      let shShift = 18 + r * 0.95;
      let ax = h.collarX + h.dx * (t * h.length) + LX * shShift;
      let ay = h.collarY + h.dy * (t * h.length) + LY * shShift;
      shOutline.push([ax - nx * r * 1.05, ay - ny * r * 1.05]);
    }

    brush.noStroke();
    brush.fill("#240e06", 105);
    brush.fillBleed(0.25, "out");
    brush.fillTexture(0.6, 0.3);
    brush.beginShape(0.3);
    for (let pt of shOutline) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
    brush.noFill();

    // Dry charcoal hatching inside the handle shadow
    for (let i = 0; i <= 32; i++) {
      let t = i / 32;
      let r = getHandleRadius(t, h.maxRadius);
      let ax = h.collarX + h.dx * (t * h.length);
      let ay = h.collarY + h.dy * (t * h.length);
      for (let s = 4; s <= 28; s += 3.5) {
        let sx = ax + LX * s;
        let sy = ay + LY * s;
        let col = s < 14 ? "#170803" : "#3b180b";
        brush.set("charcoal", col, 0.72);
        brush.line(sx - nx * r, sy - ny * r, sx + nx * r, sy + ny * r);
      }
    }
  }
}

function renderWoodenHandle(h) {
  const nx = -h.dy;
  const ny = h.dx;
  const steps = 28;

  // 1. Solid opaque wash silhouette of the wooden handle
  let bodyPts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let r = getHandleRadius(t, h.maxRadius);
    let ax = h.collarX + h.dx * (t * h.length);
    let ay = h.collarY + h.dy * (t * h.length);
    bodyPts.push([ax + nx * r, ay + ny * r]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let r = getHandleRadius(t, h.maxRadius);
    let ax = h.collarX + h.dx * (t * h.length);
    let ay = h.collarY + h.dy * (t * h.length);
    bodyPts.push([ax - nx * r, ay - ny * r]);
  }

  brush.noStroke();
  brush.wash("#7d4427", 250);
  brush.beginShape(0.25);
  for (let pt of bodyPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);
  brush.noWash();

  // Determine which normal side (+nx, +ny) vs (-nx, -ny) faces the upper-left morning sun
  let nDotL = -(nx * LX + ny * LY);
  let litSign = nDotL >= 0 ? 1 : -1;

  // 2. Longitudinal wood-grain fibers & cylindrical shading across the turned handle
  for (let v = -0.95; v <= 0.95; v += 0.08) {
    // v * litSign > 0 is on the sunlit half of the cylinder; < 0 is on the shadow half
    let cylLight = v * litSign;
    let col;
    if (cylLight > 0.55) col = "#f2ceb0";
    else if (cylLight > 0.25) col = "#d99d73";
    else if (cylLight > -0.1) col = "#ad6840";
    else if (cylLight > -0.55) col = "#6e361c";
    else if (cylLight > -0.82) col = "#3d1a0b";
    else col = "#874124"; // Warm reflected terracotta ground light on bottom rim

    for (let i = 0; i < steps; i++) {
      let t1 = i / steps;
      let t2 = (i + 1) / steps;
      let r1 = getHandleRadius(t1, h.maxRadius);
      let r2 = getHandleRadius(t2, h.maxRadius);

      // Decorative faded crimson-terracotta painted band near the collar bead (t in 0.14..0.28)
      let inBand = (t1 >= 0.14 && t1 <= 0.26) || (t1 >= 0.30 && t1 <= 0.34);
      let strokeCol = col;
      if (inBand && random() < 0.78) {
        if (cylLight > 0.3) strokeCol = "#d95b43";
        else if (cylLight > -0.2) strokeCol = "#9e2b19";
        else strokeCol = "#4f1208";
      }

      let x1 = h.collarX + h.dx * (t1 * h.length) + nx * r1 * v;
      let y1 = h.collarY + h.dy * (t1 * h.length) + ny * r1 * v;
      let x2 = h.collarX + h.dx * (t2 * h.length) + nx * r2 * v;
      let y2 = h.collarY + h.dy * (t2 * h.length) + ny * r2 * v;

      brush.set("cpencil", strokeCol, 0.58);
      brush.line(x1, y1, x2, y2);
    }
  }

  // 3. Fine dark wood-grain pores & lathe turn rings
  const ringPositions = [0.08, 0.15, 0.26, 0.30, 0.34, 0.82];
  for (let rt of ringPositions) {
    let r = getHandleRadius(rt, h.maxRadius);
    let ax = h.collarX + h.dx * (rt * h.length);
    let ay = h.collarY + h.dy * (rt * h.length);
    brush.set("2B", "#2b1106", 0.48);
    brush.line(ax - nx * r * 0.92, ay - ny * r * 0.92, ax + nx * r * 0.92, ay + ny * r * 0.92);
    // Sunlit ridge next to groove
    brush.set("2H", "#f5d7be", 0.38);
    brush.line(
      ax - h.dx * 1.5 - nx * r * 0.7,
      ay - h.dy * 1.5 - ny * r * 0.7,
      ax - h.dx * 1.5 + nx * r * 0.7,
      ay - h.dy * 1.5 + ny * r * 0.7
    );
  }

  // 4. Specular chalk-white sheen along the sunlit cylinder ridge
  for (let i = 2; i < steps - 2; i++) {
    let t1 = i / steps;
    let t2 = (i + 1) / steps;
    let r1 = getHandleRadius(t1, h.maxRadius) * 0.52 * litSign;
    let r2 = getHandleRadius(t2, h.maxRadius) * 0.52 * litSign;
    let x1 = h.collarX + h.dx * (t1 * h.length) + nx * r1;
    let y1 = h.collarY + h.dy * (t1 * h.length) + ny * r1;
    let x2 = h.collarX + h.dx * (t2 * h.length) + nx * r2;
    let y2 = h.collarY + h.dy * (t2 * h.length) + ny * r2;
    brush.set("cpencil", "#fff8f0", 0.52);
    brush.line(x1, y1, x2, y2);
  }

  // 5. Dark bore-hole shadow at both ends of the wooden handle where the rope passes through
  let boreCollarX = h.collarX;
  let boreCollarY = h.collarY;
  brush.set("2B", "#1a0903", 0.75);
  brush.line(
    boreCollarX - nx * 6.5, boreCollarY - ny * 6.5,
    boreCollarX + nx * 6.5, boreCollarY + ny * 6.5
  );
}

function renderFrayedTip(h) {
  const nx = -h.dy;
  const ny = h.dx;

  // Outer pommel bore where the stopper knot and frayed cotton tassel emerge
  const tipBaseX = h.collarX + h.dx * (h.length + 2);
  const tipBaseY = h.collarY + h.dy * (h.length + 2);

  // 1. Cast shadow of the knot and frayed tassel on the swept earth
  for (let i = 0; i < 24; i++) {
    let ang = atan2(h.dy, h.dx) + random(-42, 42);
    let len = random(18, 46);
    let sx1 = tipBaseX + LX * 11;
    let sy1 = tipBaseY + LY * 11;
    let sx2 = sx1 + cos(ang) * len;
    let sy2 = sy1 + sin(ang) * len;
    brush.set("charcoal", "#291107", random(0.4, 0.75));
    brush.line(sx1, sy1, sx2, sy2);
  }

  // 2. Bulky figure-eight cotton stopper knot right outside the pommel hole
  const knotLobes = [
    { offD: 5, offN: -3.5, r: 6.5 },
    { offD: 9, offN: 3.5,  r: 6.8 },
    { offD: 13, offN: -1.5, r: 6.0 }
  ];
  for (let lb of knotLobes) {
    let kx = tipBaseX + h.dx * lb.offD + nx * lb.offN;
    let ky = tipBaseY + h.dy * lb.offD + ny * lb.offN;

    // Knot lobe shadow crevice
    brush.set("2B", "#3d2317", 0.65);
    brush.circle(kx + LX * 1.5, ky + LY * 1.5, lb.r, 0.25);

    // Knot lobe cotton fibers
    for (let f = -lb.r * 0.8; f <= lb.r * 0.8; f += 1.6) {
      let isLit = (f * (nx * LX + ny * LY)) < 0;
      brush.set("cpencil", isLit ? "#faf5ee" : "#b89f8d", 0.55);
      brush.line(
        kx - h.dx * lb.r * 0.65 + nx * f,
        ky - h.dy * lb.r * 0.65 + ny * f,
        kx + h.dx * lb.r * 0.65 + nx * f,
        ky + h.dy * lb.r * 0.65 + ny * f
      );
    }
    // Bright chalk highlight on knot lobe
    brush.set("cpencil", "#ffffff", 0.58);
    brush.line(kx - LX * 2.5 - 2, ky - LY * 2.5 - 1, kx - LX * 2.5 + 2, ky - LY * 2.5 + 1);
  }

  // 3. Frayed cotton strands & wispy individual threads splaying out from the knot
  const frayOriginX = tipBaseX + h.dx * 15;
  const frayOriginY = tipBaseY + h.dy * 15;
  const baseAngle = atan2(h.dy, h.dx);

  // First draw shadowed under-threads
  for (let i = 0; i < 42; i++) {
    let spread = map(i, 0, 41, -48, 48) + random(-5, 5);
    let a1 = baseAngle + spread * 0.55;
    let a2 = baseAngle + spread * 1.05 + random(-14, 14);
    let len = random(18, 42) * (1 - 0.35 * abs(spread) / 50);

    let x1 = frayOriginX + nx * map(i, 0, 41, -4.5, 4.5);
    let y1 = frayOriginY + ny * map(i, 0, 41, -4.5, 4.5);
    let xm = x1 + cos(a1) * (len * 0.52);
    let ym = y1 + sin(a1) * (len * 0.52);
    let x2 = xm + cos(a2) * (len * 0.52);
    let y2 = ym + sin(a2) * (len * 0.52);

    let col = i % 3 === 0 ? "#8f6f5d" : (i % 3 === 1 ? "#c7b2a1" : "#dfd3c7");
    brush.set("2H", col, random(0.32, 0.55));
    brush.spline([[x1, y1, 0.8], [xm, ym, 0.6], [x2, y2, 0.25]], 0.45);
  }

  // Next draw crisp sunlit chalk-white frayed cotton threads on top
  for (let i = 0; i < 38; i++) {
    let spread = random(-44, 44);
    let a1 = baseAngle + spread * 0.5;
    let a2 = baseAngle + spread + random(-18, 18);
    let len = random(16, 44);

    let x1 = frayOriginX + nx * random(-4, 4) - LX * 1.2;
    let y1 = frayOriginY + ny * random(-4, 4) - LY * 1.2;
    let xm = x1 + cos(a1) * (len * 0.5);
    let ym = y1 + sin(a1) * (len * 0.5);
    let x2 = xm + cos(a2) * (len * 0.5);
    let y2 = ym + sin(a2) * (len * 0.5);

    let col = random() < 0.6 ? "#ffffff" : "#f5eee6";
    brush.set(random() < 0.45 ? "cpencil" : "2H", col, random(0.28, 0.5));
    brush.spline([[x1, y1, 0.85], [xm, ym, 0.65], [x2, y2, 0.2]], 0.45);
  }
}

// ============================================================================
// 7. FINAL RAKING SUNLIGHT DUST, CHALK MOTES & DUSTY EDGES
// ============================================================================
function renderFinalDustAndVignette() {
  // Subtle chalk dust shed onto the red earth near the rope curves
  for (let i = 0; i < 180; i++) {
    let x = random(180, 1020);
    let y = random(180, 1020);
    brush.set("spray", random() < 0.65 ? "#f5e6d8" : "#e3a682", random(0.45, 0.95));
    brush.line(x, y, x + random(-18, 18), y + random(-18, 18));
  }

  // Dusty vignetted edges in burnt umber, sienna, and soft dry charcoal
  const borderStrokes = 220;
  for (let i = 0; i < borderStrokes; i++) {
    let edge = i % 4;
    let x1, y1, x2, y2;
    let margin = random(8, 95);
    if (edge === 0) {
      x1 = random(0, 1200); y1 = margin;
      x2 = x1 + random(-110, 110); y2 = y1 + random(-25, 25);
    } else if (edge === 1) {
      x1 = random(0, 1200); y1 = 1200 - margin;
      x2 = x1 + random(-110, 110); y2 = y1 + random(-25, 25);
    } else if (edge === 2) {
      x1 = margin; y1 = random(0, 1200);
      x2 = x1 + random(-25, 25); y2 = y1 + random(-110, 110);
    } else {
      x1 = 1200 - margin; y1 = random(0, 1200);
      x2 = x1 + random(-25, 25); y2 = y1 + random(-110, 110);
    }

    let col = random() < 0.5 ? "#4a1c0d" : (random() < 0.6 ? "#6e2c16" : "#c77d58");
    brush.set(random() < 0.6 ? "charcoal" : "spray", col, random(0.6, 1.35));
    brush.line(x1, y1, x2, y2);
  }
}

