function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

// Safe closed polygon wash (fast opaque/translucent pass)
function polyWash(pts, col, opacity) {
  if (!pts || pts.length < 3) return;
  resetBrush();
  brush.wash(col, opacity);
  brush.beginShape(0.45);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrush();
}

// Safe closed polygon watercolor fill (with bleed & texture)
function polyWatercolor(pts, col, opacity, bleed = 0.08, tex = 0.45, border = 0.35, curv = 0.45) {
  if (!pts || pts.length < 3) return;
  resetBrush();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrush();
}

// Generate organic noisy ellipse points
function makeBlobPoints(cx, cy, rx, ry, rotDeg, numPts, irr, seedOffset) {
  let pts = [];
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  for (let i = 0; i < numPts; i++) {
    let ang = (i / numPts) * 360;
    let n = noise(
      cos(ang) * 1.3 + seedOffset * 0.17,
      sin(ang) * 1.3 + seedOffset * 0.31
    );
    let rScale = 1 + (n - 0.5) * 2 * irr;
    let lx = cos(ang) * rx * rScale;
    let ly = sin(ang) * ry * rScale;
    let wx = cx + lx * c - ly * s;
    let wy = cy + lx * s + ly * c;
    pts.push([wx, wy]);
  }
  return pts;
}

// Catmull-Rom spline evaluation
function evalSplinePoint(ctrl, t) {
  let n = ctrl.length - 1;
  let segFloat = constrain(t, 0, 0.999999) * n;
  let idx = floor(segFloat);
  let u = segFloat - idx;

  let p0 = ctrl[max(0, idx - 1)];
  let p1 = ctrl[idx];
  let p2 = ctrl[min(n, idx + 1)];
  let p3 = ctrl[min(n, idx + 2)];

  let u2 = u * u;
  let u3 = u2 * u;

  let x =
    0.5 *
    (2 * p1[0] +
      (-p0[0] + p2[0]) * u +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3);
  let y =
    0.5 *
    (2 * p1[1] +
      (-p0[1] + p2[1]) * u +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3);

  return [x, y];
}

// Build dense arc-length table for a spline
function buildArcTable(ctrl, samples = 400) {
  let table = [];
  let totalLen = 0;
  let prev = evalSplinePoint(ctrl, 0);
  table.push({ t: 0, s: 0, x: prev[0], y: prev[1], ang: 0 });

  for (let i = 1; i <= samples; i++) {
    let t = i / samples;
    let pt = evalSplinePoint(ctrl, t);
    let dx = pt[0] - prev[0];
    let dy = pt[1] - prev[1];
    let d = sqrt(dx * dx + dy * dy);
    totalLen += d;
    let ang = atan2(dy, dx);
    table.push({ t, s: totalLen, x: pt[0], y: pt[1], ang });
    prev = pt;
  }
  if (table.length > 1) {
    table[0].ang = table[1].ang;
  }
  return { table, totalLen };
}

function sampleByArcLength(arcObj, sTarget) {
  let tbl = arcObj.table;
  let s = constrain(sTarget, 0, arcObj.totalLen);
  let lo = 0;
  let hi = tbl.length - 1;
  while (lo < hi - 1) {
    let mid = (lo + hi) >> 1;
    if (tbl[mid].s < s) lo = mid;
    else hi = mid;
  }
  let a = tbl[lo];
  let b = tbl[hi];
  let span = max(0.0001, b.s - a.s);
  let f = (s - a.s) / span;
  return {
    x: lerp(a.x, b.x, f),
    y: lerp(a.y, b.y, f),
    ang: a.ang,
    t: lerp(a.t, b.t, f)
  };
}

// =========================================================================
// 1. KOA-WOOD TABLE BACKGROUND (Transparent Watercolour + Soft Pencil Grain)
// =========================================================================
function drawKoaWoodTable() {
  background(PAL.paper);

  // Base warm golden-ochre and sienna watercolour washes across the table
  // Leaving breathing room and luminous paper glow along the diagonal window beam
  let fullRect = [
    [-20, -20],
    [1220, -20],
    [1220, 1220],
    [-20, 1220]
  ];
  polyWash(fullRect, PAL.paperWarm, 110);

  // Large diagonal watercolour bands following the koa grain angle (-21 deg)
  let grainAngle = -21;
  let cosG = cos(grainAngle);
  let sinG = sin(grainAngle);

  for (let b = -4; b < 14; b++) {
    let baseY = b * 105;
    let bandPts = [];
    let steps = 10;
    for (let i = 0; i <= steps; i++) {
      let x = -80 + (i / steps) * 1360;
      let wave = sin(i * 32 + b * 47) * 18 + (noise(i * 0.4, b * 0.7) - 0.5) * 35;
      let y = baseY + (x - 600) * tan(grainAngle) + wave;
      bandPts.push([x, y]);
    }
    for (let i = steps; i >= 0; i--) {
      let x = -80 + (i / steps) * 1360;
      let wave = sin(i * 30 + (b + 1) * 43) * 18 + (noise(i * 0.4, (b + 1) * 0.7) - 0.5) * 35;
      let y = baseY + 135 + (x - 600) * tan(grainAngle) + wave;
      bandPts.push([x, y]);
    }

    // Distance from sunlit diagonal window beam
    let distFromSun = abs(b - 4.2);
    let col = PAL.koaSun;
    let op = 48;
    if (distFromSun > 4.5) {
      col = PAL.koaDeep;
      op = 65;
    } else if (distFromSun > 2.8) {
      col = PAL.koaMid;
      op = 58;
    } else if (distFromSun > 1.4) {
      col = PAL.koaAmber;
      op = 52;
    } else {
      col = PAL.koaGold;
      op = 44;
    }
    polyWatercolor(bandPts, col, op, 0.12, 0.52, 0.25, 0.4);
  }

  // Side-window light warm glow in upper-left to center diagonal
  let sunBeam = [
    [-40, -40],
    [760, -40],
    [1240, 680],
    [1240, 1140],
    [460, 1240],
    [-40, 560]
  ];
  polyWash(sunBeam, PAL.koaSun, 32);

  // Deeper umber corners (upper-right & lower-left falloff away from window beam)
  let shadowCornerTR = [
    [620, -40],
    [1240, -40],
    [1240, 540],
    [920, 260]
  ];
  polyWatercolor(shadowCornerTR, PAL.koaUmber, 55, 0.18, 0.5, 0.3);

  let shadowCornerBL = [
    [-40, 640],
    [480, 1020],
    [720, 1240],
    [-40, 1240]
  ];
  polyWatercolor(shadowCornerBL, PAL.koaUmber, 62, 0.18, 0.5, 0.3);

  // Signature curly koa chatoyancy (rippling cross-bands perpendicular to grain)
  for (let c = 0; c < 28; c++) {
    let rx = random(60, 1140);
    let ry = random(60, 1140);
    let len = random(110, 260);
    let wid = random(18, 42);
    let perpAng = grainAngle + 90 + random(-12, 12);
    let pts = makeBlobPoints(rx, ry, len * 0.5, wid * 0.5, perpAng, 10, 0.22, c * 19);
    let isDarkRipple = c % 2 === 0;
    polyWash(
      pts,
      isDarkRipple ? PAL.koaDeep : PAL.koaSun,
      isDarkRipple ? random(18, 34) : random(16, 28)
    );
  }

  // Subtle koa wood plank join line running across the lower-right table
  resetBrush();
  let joinPts = [];
  for (let i = 0; i <= 16; i++) {
    let x = -40 + (i / 16) * 1280;
    let y = 980 + (x - 200) * tan(grainAngle) + sin(i * 15) * 1.8;
    joinPts.push([x, y, 0.55]);
  }
  brush.set("2B", PAL.koaDark, 0.75);
  brush.spline(joinPts, 0.3);
  let joinHighlight = joinPts.map((p) => [p[0], p[1] + 2.5, 0.4]);
  brush.set("2H", PAL.koaSun, 0.5);
  brush.spline(joinHighlight, 0.3);

  // Fine flowing wood grain lines in coloured pencil & soft 2B graphite
  let numGrainLines = 155;
  let knot1 = { x: 840, y: 860, r: 95 };
  let knot2 = { x: 140, y: 690, r: 75 };

  for (let g = 0; g < numGrainLines; g++) {
    let y0 = map(g, 0, numGrainLines - 1, -260, 1460);
    let pts = [];
    let segs = 18;
    for (let s = 0; s <= segs; s++) {
      let x = -40 + (s / segs) * 1280;
      let y = y0 + (x - 600) * tan(grainAngle);

      // Gentle organic wood grain undulation + deflection around knots
      let n = noise(x * 0.0025, g * 0.08) - 0.5;
      y += n * 38;

      let d1 = dist(x, y, knot1.x, knot1.y);
      if (d1 < knot1.r * 2.2) {
        let push = (1 - d1 / (knot1.r * 2.2)) * 28;
        y += y < knot1.y ? -push : push;
      }
      let d2 = dist(x, y, knot2.x, knot2.y);
      if (d2 < knot2.r * 2.2) {
        let push = (1 - d2 / (knot2.r * 2.2)) * 22;
        y += y < knot2.y ? -push : push;
      }

      let press = 0.25 + 0.45 * sin((s / segs) * 180) * noise(s * 0.3, g * 0.2);
      pts.push([x, y, press]);
    }

    let colChoice = g % 5 === 0 ? PAL.koaDark : g % 3 === 0 ? PAL.koaUmber : PAL.koaDeep;
    let brName = g % 4 === 0 ? "2B" : "cpencil";
    let wt = random(0.22, 0.52);
    brush.set(brName, colChoice, wt);
    brush.spline(pts, 0.4);
  }
  resetBrush();
}

// =========================================================================
// 2. SHALLOW BOWL IN UPPER-LEFT
// =========================================================================
function drawShallowBowlBase(cx, cy, rx, ry) {
  // Cast shadow of the shallow bowl onto the koa table (shifted toward lower-right)
  let sh1 = makeBlobPoints(cx + 32, cy + 28, rx * 1.03, ry * 1.02, -15, 28, 0.03, 11);
  polyWatercolor(sh1, PAL.koaDark, 105, 0.16, 0.45, 0.3);
  let sh2 = makeBlobPoints(cx + 18, cy + 16, rx * 0.99, ry * 0.98, -15, 28, 0.02, 17);
  polyWash(sh2, "#240f04", 85);

  // Outer bowl body paper-reserve + warm stoneware wash
  let outerPts = makeBlobPoints(cx, cy, rx, ry, -12, 36, 0.022, 23);
  polyWash(outerPts, PAL.bowlLight, 235);
  polyWatercolor(outerPts, PAL.bowlMid, 115, 0.06, 0.45, 0.35);

  // Exterior lower-right shaded crescent on the outer rim
  let extShade = [];
  for (let a = -25; a <= 145; a += 10) {
    extShade.push([cx + cos(a) * rx * 0.99, cy + sin(a) * ry * 0.99]);
  }
  for (let a = 145; a >= -25; a -= 10) {
    extShade.push([cx + cos(a) * rx * 0.87, cy + sin(a) * ry * 0.87]);
  }
  polyWash(extShade, PAL.bowlDeep, 120);

  // Inner bowl concavity
  let inRx = rx * 0.88;
  let inRy = ry * 0.88;
  let innerPts = makeBlobPoints(cx, cy, inRx, inRy, -12, 34, 0.02, 31);
  polyWash(innerPts, PAL.bowlLight, 210);

  // Interior shadow is on the UPPER-LEFT wall (concave vessel lit from upper-left!)
  let intShadePts = [];
  for (let a = 125; a <= 315; a += 10) {
    intShadePts.push([cx + cos(a) * inRx * 0.98, cy + sin(a) * inRy * 0.98]);
  }
  for (let a = 315; a >= 125; a -= 10) {
    let shiftX = cx + 38 + cos(a) * inRx * 0.62;
    let shiftY = cy + 34 + sin(a) * inRy * 0.62;
    intShadePts.push([shiftX, shiftY]);
  }
  polyWatercolor(intShadePts, PAL.bowlShade, 145, 0.1, 0.5, 0.3);

  let intDeepPts = [];
  for (let a = 145; a <= 295; a += 12) {
    intDeepPts.push([cx + cos(a) * inRx * 0.97, cy + sin(a) * inRy * 0.97]);
  }
  for (let a = 295; a >= 145; a -= 12) {
    intDeepPts.push([cx + 22 + cos(a) * inRx * 0.76, cy + 20 + sin(a) * inRy * 0.76]);
  }
  polyWash(intDeepPts, PAL.bowlDeep, 95);

  // Sunlit interior floor (lower-right hollow catches the window light)
  let intLitPts = makeBlobPoints(cx + 28, cy + 24, inRx * 0.64, inRy * 0.62, -15, 24, 0.04, 41);
  polyWash(intLitPts, PAL.paperLight, 130);

  // Subtle concentric turning rings & soft pencil contour on the bowl
  resetBrush();
  for (let r = 0.35; r <= 0.85; r += 0.12) {
    let startA = random(0, 90);
    let endA = startA + random(140, 240);
    let ringPts = [];
    for (let a = startA; a <= endA; a += 12) {
      ringPts.push([
        cx + cos(a) * inRx * r + random(-1.2, 1.2),
        cy + sin(a) * inRy * r + random(-1.2, 1.2),
        0.35
      ]);
    }
    brush.set("2H", PAL.bowlDeep, 0.32);
    brush.spline(ringPts, 0.4);
  }

  // Rim highlight on upper-left lip and lower-right inner lip
  let rimHi = [];
  for (let a = -20; a <= 115; a += 10) {
    rimHi.push([cx + cos(a) * (inRx + 5), cy + sin(a) * (inRy + 5), 0.7]);
  }
  brush.set("cpencil", PAL.paperLight, 0.9);
  brush.spline(rimHi, 0.4);

  // Sensitive graphite outlines around outer and inner bowl rims
  let outOutline = outerPts.map((p, idx) => [
    p[0],
    p[1],
    0.35 + 0.45 * sin((idx / outerPts.length) * 180)
  ]);
  outOutline.push(outOutline[0]);
  brush.set("2B", PAL.bowlDark, 0.58);
  brush.spline(outOutline, 0.4);

  let inOutline = innerPts.map((p, idx) => [
    p[0],
    p[1],
    0.3 + 0.4 * cos((idx / innerPts.length) * 180)
  ]);
  inOutline.push(inOutline[0]);
  brush.set("HB", PAL.bowlDark, 0.48);
  brush.spline(inOutline, 0.4);

  // Delicate pencil cross-hatching in the upper-left interior shadow
  for (let i = 0; i < 28; i++) {
    let a = map(i, 0, 27, 155, 285) + random(-3, 3);
    let x1 = cx + cos(a) * (inRx * 0.96);
    let y1 = cy + sin(a) * (inRy * 0.96);
    let len = random(28, 58);
    let x2 = x1 + LIGHT_X * len;
    let y2 = y1 + LIGHT_Y * len;
    brush.set("2H", PAL.bowlDark, 0.28);
    brush.line(x1, y1, x2, y2);
  }
  resetBrush();
}

// =========================================================================
// 3. RAGGED HULL SHARDS & CRUMBS
// =========================================================================
function drawHullShard(x, y, sz, rotDeg, seedVal, castShadow = true) {
  let c = cos(rotDeg);
  let s = sin(rotDeg);
  function toWorld(lx, ly) {
    return [x + lx * c - ly * s, y + lx * s + ly * c];
  }

  // Jagged, curled pericarp shard silhouette
  let localPts = [
    [-sz * 0.95, -sz * 0.15],
    [-sz * 0.45, -sz * 0.55],
    [sz * 0.25, -sz * 0.48],
    [sz * 0.98, -sz * 0.08],
    [sz * 0.55, sz * 0.38],
    [-sz * 0.05, sz * 0.18],
    [-sz * 0.62, sz * 0.42]
  ];
  let pts = localPts.map((p, idx) => {
    let n = (noise(seedVal * 0.3 + idx, idx * 0.7) - 0.5) * sz * 0.25;
    return toWorld(p[0] + n, p[1] + n);
  });

  if (castShadow) {
    let shPts = pts.map((p) => [p[0] + 3.5, p[1] + 3.2]);
    polyWash(shPts, PAL.koaDark, 90);
  }

  // Translucent amber rim + dark burnt-umber core
  polyWash(pts, PAL.hullAmber, 210);
  let corePts = pts.map((p) => [lerp(x, p[0], 0.72), lerp(y, p[1], 0.72)]);
  polyWash(corePts, PAL.hullBrown, 220);

  let tipPts = [pts[0], pts[1], [x, y], pts[6]];
  polyWash(tipPts, PAL.hullDark, 230);

  // Fine longitudinal pericarp striations & sharp ragged outline in pencil
  resetBrush();
  let outline = pts.map((p) => [p[0], p[1], 0.55]);
  outline.push(outline[0]);
  brush.set("2B", PAL.hullBlack, 0.36);
  brush.spline(outline, 0.25);

  for (let k = -1; k <= 1; k++) {
    let pA = toWorld(-sz * 0.7, k * sz * 0.14);
    let pB = toWorld(sz * 0.7, k * sz * 0.09);
    brush.set("2H", PAL.hullBlack, 0.24);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Tiny specular ridge glint on the curled hull edge
  let hiA = toWorld(-sz * 0.35, -sz * 0.32);
  let hiB = toWorld(sz * 0.35, -sz * 0.28);
  brush.set("cpencil", PAL.puffButter, 0.38);
  brush.line(hiA[0], hiA[1], hiB[0], hiB[1]);
  resetBrush();
}

function drawStarchCrumb(x, y, r, seedVal) {
  let pts = makeBlobPoints(x, y, r, r * 0.82, seedVal * 37, 8, 0.28, seedVal);
  let shPts = pts.map((p) => [p[0] + 2.5, p[1] + 2.2]);
  polyWash(shPts, PAL.koaDark, 75);
  polyWash(pts, PAL.puffBase, 225);
  resetBrush();
  brush.set("HB", PAL.puffPencil, 0.28);
  brush.circle(x, y, r * 0.9, 0.25);
  resetBrush();
}

// =========================================================================
// 4. HYPERREALISTIC POPCORN PUFF (Buttery Cream + Ragged Hull Shards)
// =========================================================================
function drawPopcornShadow(cx, cy, radius, seedVal, offX = 11, offY = 10, alpha = 105) {
  let shPts = makeBlobPoints(
    cx + offX,
    cy + offY,
    radius * 1.04,
    radius * 0.98,
    seedVal * 29,
    18,
    0.18,
    seedVal + 3
  );
  polyWatercolor(shPts, PAL.koaDark, alpha, 0.14, 0.45, 0.28);
}

function drawPopcornPuff(cx, cy, radius, seedVal, opts = {}) {
  let rotBase = (seedVal * 53) % 360;
  let numLobes = 4 + (seedVal % 2); // 4 or 5 distinct billowy starch lobes
  let lobes = [];

  for (let i = 0; i < numLobes; i++) {
    let ang = rotBase + (i / numLobes) * 360 + (noise(seedVal, i * 2.1) - 0.5) * 38;
    let distFactor = radius * (0.36 + 0.16 * noise(seedVal + 7, i * 1.7));
    let lx = cx + cos(ang) * distFactor;
    let ly = cy + sin(ang) * distFactor;
    let lrx = radius * (0.52 + 0.18 * noise(seedVal + 13, i * 3.1));
    let lry = radius * (0.46 + 0.16 * noise(seedVal + 19, i * 2.3));
    let lRot = ang + (noise(seedVal + 23, i) - 0.5) * 40;
    let pts = makeBlobPoints(lx, ly, lrx, lry, lRot, 14, 0.16, seedVal * 11 + i * 7);

    // Dot product with window light (-LIGHT_X, -LIGHT_Y is toward light source)
    let nx = cos(ang);
    let ny = sin(ang);
    let lightFacing = -(nx * LIGHT_X + ny * LIGHT_Y); // +1 = sunlit upper-left, -1 = shaded lower-right
    lobes.push({ lx, ly, lrx, lry, lRot, ang, pts, lightFacing });
  }

  // 1. Paper-reserve base wash so the creamy puff sits brightly over the dark wood
  let centerPts = makeBlobPoints(cx, cy, radius * 0.68, radius * 0.65, rotBase, 14, 0.14, seedVal);
  polyWash(centerPts, PAL.puffBase, 240);
  for (let lb of lobes) {
    polyWash(lb.pts, PAL.puffBase, 242);
  }

  // 2. Transparent watercolour glazes: warm buttery cream & golden interior crevices
  for (let lb of lobes) {
    if (lb.lightFacing > -0.15) {
      // Sunlit buttery cream wash
      polyWatercolor(lb.pts, PAL.puffCream, 95, 0.06, 0.4, 0.25);
      // Bright crown dome on upper-left of lobe
      let hiPts = makeBlobPoints(
        lb.lx - LIGHT_X * lb.lrx * 0.24,
        lb.ly - LIGHT_Y * lb.lry * 0.24,
        lb.lrx * 0.58,
        lb.lry * 0.54,
        lb.lRot,
        10,
        0.12,
        seedVal + 55
      );
      polyWash(hiPts, PAL.puffHighlight, 210);
    } else {
      // Shaded lower-right lobe form shadow
      polyWatercolor(lb.pts, PAL.puffShadow, 135, 0.07, 0.45, 0.3);
      let shSub = makeBlobPoints(
        lb.lx + LIGHT_X * lb.lrx * 0.2,
        lb.ly + LIGHT_Y * lb.lry * 0.2,
        lb.lrx * 0.62,
        lb.lry * 0.58,
        lb.lRot,
        10,
        0.14,
        seedVal + 71
      );
      polyWash(shSub, PAL.puffShadowDeep, 95);
    }
  }

  // 3. Deep golden-butter and toasted sienna burst crevices in the center between lobes
  let cleftPts = makeBlobPoints(
    cx + random(-3, 3),
    cy + random(-3, 3),
    radius * 0.46,
    radius * 0.42,
    rotBase + 25,
    12,
    0.32,
    seedVal + 99
  );
  polyWatercolor(cleftPts, PAL.puffButter, 165, 0.08, 0.5, 0.4);

  let deepCleftPts = makeBlobPoints(
    cx,
    cy,
    radius * 0.28,
    radius * 0.24,
    rotBase - 15,
    10,
    0.35,
    seedVal + 113
  );
  polyWash(deepCleftPts, PAL.puffCrevice, 185);

  // Radiating crevice arms between adjacent lobes
  for (let i = 0; i < lobes.length; i++) {
    let lb1 = lobes[i];
    let lb2 = lobes[(i + 1) % lobes.length];
    let midAng = atan2(
      (lb1.ly + lb2.ly) * 0.5 - cy,
      (lb1.lx + lb2.lx) * 0.5 - cx
    );
    let armLen = radius * 0.56;
    let armPts = [
      [cx, cy],
      [
        cx + cos(midAng - 14) * armLen * 0.55,
        cy + sin(midAng - 14) * armLen * 0.55
      ],
      [cx + cos(midAng) * armLen, cy + sin(midAng) * armLen],
      [
        cx + cos(midAng + 14) * armLen * 0.55,
        cy + sin(midAng + 14) * armLen * 0.55
      ]
    ];
    polyWash(armPts, PAL.puffButter, 145);
    resetBrush();
    brush.set("HB", PAL.puffDeepCleft, 0.42);
    brush.line(
      cx,
      cy,
      cx + cos(midAng) * armLen * 0.88,
      cy + sin(midAng) * armLen * 0.88
    );
  }

  // 4. Ragged Hull Shards clinging to the ruptured center and clefts
  let numShards = 2 + (seedVal % 3);
  for (let s = 0; s < numShards; s++) {
    let sAng = rotBase + s * 115 + (noise(seedVal, s * 4.3) - 0.5) * 45;
    let sDist = s === 0 ? radius * 0.12 : radius * random(0.24, 0.48);
    let sx = cx + cos(sAng) * sDist;
    let sy = cy + sin(sAng) * sDist;
    let sSize = radius * random(0.22, 0.34);
    drawHullShard(sx, sy, sSize, sAng + 70, seedVal * 17 + s * 13, false);
  }

  // 5. Soft Pencil Drawing: organic lobe contours, spongy cellular stipple, and shading hatch
  resetBrush();
  for (let i = 0; i < lobes.length; i++) {
    let lb = lobes[i];
    let contour = [];
    let nPts = lb.pts.length;
    for (let j = 0; j <= nPts; j++) {
      let p = lb.pts[j % nPts];
      // Heavier pencil pressure on the shadow side and inner folds
      let dx = p[0] - cx;
      let dy = p[1] - cy;
      let distFromCenter = sqrt(dx * dx + dy * dy);
      if (distFromCenter > radius * 0.34) {
        let shadeFactor = constrain((dx * LIGHT_X + dy * LIGHT_Y) / radius + 0.5, 0.15, 0.95);
        contour.push([p[0], p[1], shadeFactor * 0.72]);
      }
    }
    if (contour.length >= 3) {
      let col = lb.lightFacing < 0 ? PAL.puffPencilDark : PAL.puffPencil;
      brush.set("2B", col, 0.44);
      brush.spline(contour, 0.45);
    }

    // Subtle graphite hatching on shaded side of each lobe
    if (lb.lightFacing < 0.1) {
      for (let h = 0; h < 6; h++) {
        let ha = lb.ang + random(-35, 35);
        let hx1 = lb.lx + cos(ha) * lb.lrx * 0.35;
        let hy1 = lb.ly + sin(ha) * lb.lry * 0.35;
        let hx2 = lb.lx + cos(ha) * lb.lrx * 0.82;
        let hy2 = lb.ly + sin(ha) * lb.lry * 0.82;
        brush.set("2H", PAL.puffPencil, 0.25);
        brush.line(hx1, hy1, hx2, hy2);
      }
    }

    // Tiny spongy starch pores in fine 2H pencil
    for (let d = 0; d < 4; d++) {
      let da = random(360);
      let dr = random(0.15, 0.65);
      let dx = lb.lx + cos(da) * lb.lrx * dr;
      let dy = lb.ly + sin(da) * lb.lry * dr;
      brush.set("2H", PAL.puffShadowDeep, 0.22);
      brush.circle(dx, dy, random(1.2, 2.4), 0.2);
    }
  }
  resetBrush();
}

// =========================================================================
// 5. HYPERREALISTIC GLOSSY CRANBERRY (Deep Alizarin + Pinpoint Shine)
// =========================================================================
function drawCranberryShadow(cx, cy, rx, ry, rotDeg, offX = 10, offY = 9, alpha = 115) {
  let shPts = makeBlobPoints(cx + offX, cy + offY, rx * 1.02, ry * 1.02, rotDeg, 16, 0.05, 7);
  polyWatercolor(shPts, "#2b0c08", alpha, 0.12, 0.4, 0.3);
}

function drawCranberry(cx, cy, rx, ry, rotDeg, seedVal, opts = {}) {
  let bodyPts = makeBlobPoints(cx, cy, rx, ry, rotDeg, 22, 0.035, seedVal);

  // 1. Opaque crimson base reserve so berry is rich & jewel-like on the wood
  polyWash(bodyPts, PAL.berryBase, 242);

  // 2. Deep Alizarin watercolour glaze over whole berry
  polyWatercolor(bodyPts, PAL.berryAlizarin, 165, 0.05, 0.45, 0.35);

  // 3. Sunlit upper-left zone in luminous carmine-alizarin
  let litX = cx - LIGHT_X * rx * 0.26;
  let litY = cy - LIGHT_Y * ry * 0.26;
  let litPts = makeBlobPoints(litX, litY, rx * 0.64, ry * 0.62, rotDeg - 15, 16, 0.04, seedVal + 11);
  polyWash(litPts, PAL.berryLit, 175);

  // 4. Deep burgundy-umber core shadow curving through the center-right
  let coreX = cx + LIGHT_X * rx * 0.16;
  let coreY = cy + LIGHT_Y * ry * 0.16;
  let corePts = makeBlobPoints(coreX, coreY, rx * 0.78, ry * 0.75, rotDeg + 20, 18, 0.05, seedVal + 23);
  polyWatercolor(corePts, PAL.berryCore, 185, 0.05, 0.45, 0.3);

  let darkX = cx + LIGHT_X * rx * 0.28;
  let darkY = cy + LIGHT_Y * ry * 0.28;
  let darkPts = makeBlobPoints(darkX, darkY, rx * 0.56, ry * 0.52, rotDeg + 35, 14, 0.05, seedVal + 37);
  polyWash(darkPts, PAL.berryDark, 195);

  // 5. Warm koa-wood reflected light along the lower-right rim!
  let bouncePts = [];
  for (let a = -15; a <= 115; a += 12) {
    let radA = a;
    bouncePts.push([
      cx + cos(radA) * rx * 0.94,
      cy + sin(radA) * ry * 0.94
    ]);
  }
  for (let a = 115; a >= -15; a -= 12) {
    bouncePts.push([
      cx + cos(a) * rx * 0.72,
      cy + sin(a) * ry * 0.72
    ]);
  }
  polyWash(bouncePts, PAL.berryBounce, 130);

  // 6. Optional calyx crown or piercing dimple
  resetBrush();
  if (opts.showCalyx) {
    let calAng = rotDeg + (seedVal % 2 === 0 ? 0 : 180);
    let calX = cx + cos(calAng) * rx * 0.78;
    let calY = cy + sin(calAng) * ry * 0.78;
    brush.set("2B", PAL.berryDark, 0.45);
    brush.circle(calX, calY, 3.2, 0.2);
    for (let k = 0; k < 4; k++) {
      let ka = calAng + (k - 1.5) * 28;
      brush.set("HB", "#8c5c42", 0.32);
      brush.line(calX, calY, calX + cos(ka) * 4.5, calY + sin(ka) * 4.5);
    }
  }

  // 7. Soft Pencil Contour & Form Hatching
  let outline = bodyPts.map((p, idx) => {
    let dx = p[0] - cx;
    let dy = p[1] - cy;
    let shade = constrain((dx * LIGHT_X + dy * LIGHT_Y) / rx + 0.55, 0.2, 0.95);
    return [p[0], p[1], shade * 0.68];
  });
  outline.push(outline[0]);
  brush.set("2B", PAL.berryDark, 0.46);
  brush.spline(outline, 0.45);

  // Subtle curved graphite form lines in the core shadow
  for (let h = 0; h < 7; h++) {
    let ha = map(h, 0, 6, -35, 110);
    let rIn = 0.45 + (h % 2) * 0.12;
    let rOut = 0.82;
    let x1 = cx + cos(ha) * rx * rIn;
    let y1 = cy + sin(ha) * ry * rIn;
    let x2 = cx + cos(ha + 18) * rx * rOut;
    let y2 = cy + sin(ha + 18) * ry * rOut;
    brush.set("2H", PAL.berryDark, 0.25);
    brush.line(x1, y1, x2, y2);
  }

  // 8. PINPOINT SHINE (Crisp side-window specular reflection on upper-left dome)
  let shX = cx - LIGHT_X * rx * 0.42 + (noise(seedVal * 1.9) - 0.5) * 2.5;
  let shY = cy - LIGHT_Y * ry * 0.42 + (noise(seedVal * 2.7) - 0.5) * 2.5;

  // Soft rose-alizarin glow around the pinpoint shine
  let haloPts = makeBlobPoints(shX, shY, rx * 0.26, ry * 0.22, -40, 10, 0.08, seedVal + 51);
  polyWash(haloPts, PAL.berryHalo, 115);

  // Primary razor-sharp pinpoint window highlight
  let pinPts = makeBlobPoints(shX, shY, 3.4, 2.5, -38, 10, 0.05, seedVal + 61);
  polyWash(pinPts, PAL.berryShine, 255);

  // Tiny secondary catchlight dot right beside it (window mullion reflection)
  let pin2Pts = makeBlobPoints(shX + 4.8, shY - 2.2, 1.7, 1.3, -38, 8, 0.05, seedVal + 67);
  polyWash(pin2Pts, PAL.berryShine, 245);

  // Delicate curved specular whisker along upper-left contour
  resetBrush();
  brush.set("cpencil", PAL.berryShine, 0.55);
  brush.arc(cx, cy, rx * 0.72, 200, 232);
  resetBrush();
}

// =========================================================================
// 6. FUZZY COTTON THREAD RENDERING
// =========================================================================
function drawFuzzyThreadSegment(pts, shadowOffset = 6, drawShadow = true) {
  if (!pts || pts.length < 2) return;

  resetBrush();
  // 1. Soft cast shadow on the table
  if (drawShadow) {
    let shPts = pts.map((p) => [p[0] + shadowOffset, p[1] + shadowOffset * 0.9, 0.5]);
    brush.set("2B", PAL.koaDark, 0.72);
    brush.spline(shPts, 0.4);
  }

  // 2. Shaded underside of cotton twine
  let underPts = pts.map((p) => [p[0] + 1.3, p[1] + 1.3, 0.65]);
  brush.set("HB", PAL.threadDark, 0.78);
  brush.spline(underPts, 0.4);

  // 3. Bright creamy-cotton core
  let corePts = pts.map((p) => [p[0], p[1], 0.8]);
  brush.set("cpencil", PAL.threadLight, 1.15);
  brush.spline(corePts, 0.4);

  let hiPts = pts.map((p) => [p[0] - 0.6, p[1] - 0.6, 0.6]);
  brush.set("cpencil", PAL.paperLight, 0.72);
  brush.spline(hiPts, 0.4);

  // 4. Diagonal ply twist marks & slightly fuzzy stray cotton fibers along the segment
  for (let i = 0; i < pts.length - 1; i++) {
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let segLen = dist(p1[0], p1[1], p2[0], p2[1]);
    let ang = atan2(p2[1] - p1[1], p2[0] - p1[0]);
    let steps = max(1, floor(segLen / 4.5));

    for (let s = 0; s < steps; s++) {
      let f = (s + 0.5) / steps;
      let tx = lerp(p1[0], p2[0], f);
      let ty = lerp(p1[1], p2[1], f);

      // Tiny diagonal ply twist mark across the thread
      let plyAng = ang + 52;
      brush.set("2H", PAL.threadShade, 0.28);
      brush.line(
        tx - cos(plyAng) * 1.8,
        ty - sin(plyAng) * 1.8,
        tx + cos(plyAng) * 1.8,
        ty + sin(plyAng) * 1.8
      );

      // Fuzzy cotton halo: delicate fine hairs radiating out at shallow angles
      let numHairs = 2 + (s % 2);
      for (let h = 0; h < numHairs; h++) {
        let side = h % 2 === 0 ? 1 : -1;
        let hairAng = ang + side * random(18, 78) + ( random() < 0.5 ? 0 : 180 );
        let hairLen = random(3.5, 9.5);
        let hx1 = tx + cos(ang + side * 90) * random(0.4, 1.6);
        let hy1 = ty + sin(ang + side * 90) * random(0.4, 1.6);
        let hx2 = hx1 + cos(hairAng) * hairLen;
        let hy2 = hy1 + sin(hairAng) * hairLen;
        let hairCol = h === 0 ? PAL.threadLight : PAL.threadMid;
        brush.set("2H", hairCol, random(0.16, 0.25));
        brush.line(hx1, hy1, hx2, hy2);
      }
    }
  }
  resetBrush();
}

// Short overlapping stitch bridge where the thread emerges from a berry or popcorn puff
function drawThreadBridge(x1, y1, x2, y2, entryDimple = true) {
  resetBrush();
  if (entryDimple) {
    brush.set("2B", PAL.koaDark, 0.42);
    brush.circle(x1, y1, 2.2, 0.2);
  }
  let midX = (x1 + x2) * 0.5 + random(-0.8, 0.8);
  let midY = (y1 + y2) * 0.5 + random(-0.8, 0.8);
  drawFuzzyThreadSegment(
    [
      [x1, y1],
      [midX, midY],
      [x2, y2]
    ],
    4,
    false
  );
}

// =========================================================================
// 7. LONG STEEL LEI NEEDLE (Segmented for True 3D Mid-Threading)
// =========================================================================
function drawNeedleShadow(ex, ey, tx, ty) {
  let offX = 20;
  let offY = 18;
  let ang = atan2(ty - ey, tx - ex);
  let nx = -sin(ang);
  let ny = cos(ang);
  let w = 4.2;
  let pts = [
    [ex + offX + nx * w, ey + offY + ny * w],
    [tx + offX + nx * 1.2, ty + offY + ny * 1.2],
    [tx + offX - nx * 1.2, ty + offY - ny * 1.2],
    [ex + offX - nx * w, ey + offY - ny * w]
  ];
  polyWatercolor(pts, PAL.koaDark, 95, 0.14, 0.4, 0.25);
}

function drawNeedleSegment(ex, ey, tx, ty, t0, t1, includeEye = false, includeTip = false) {
  let ang = atan2(ty - ey, tx - ex);
  let nx = -sin(ang); // points toward upper-left (window light!)
  let ny = cos(ang);

  let pStart = [lerp(ex, tx, t0), lerp(ey, ty, t0)];
  let pEnd = [lerp(ex, tx, t1), lerp(ey, ty, t1)];

  // Half-width tapers toward tip
  function getHalfWidth(t) {
    if (t < 0.08) {
      // Slightly wider flattened eye housing at rear
      return map(t, 0, 0.08, 2.6, 3.8);
    }
    if (t > 0.82) {
      // Sharp tapered point at tip
      return map(t, 0.82, 1.0, 2.7, 0.35);
    }
    return map(t, 0.08, 0.82, 3.3, 2.7);
  }

  let steps = 14;
  let upperEdge = [];
  let lowerEdge = [];
  let midLine = [];
  let specLine = [];

  for (let i = 0; i <= steps; i++) {
    let t = lerp(t0, t1, i / steps);
    let cx = lerp(ex, tx, t);
    let cy = lerp(ey, ty, t);
    let hw = getHalfWidth(t);

    upperEdge.push([cx + nx * hw, cy + ny * hw]);
    lowerEdge.push([cx - nx * hw, cy - ny * hw]);
    midLine.push([cx - nx * hw * 0.25, cy - ny * hw * 0.25, 0.65]);
    specLine.push([cx + nx * hw * 0.52, cy + ny * hw * 0.52, 0.85]);
  }

  let bodyPoly = [...upperEdge, ...lowerEdge.slice().reverse()];
  polyWash(bodyPoly, PAL.steelLight, 248);

  // Dark metallic core reflection along the lower-mid cylinder
  let darkPoly = [];
  for (let i = 0; i <= steps; i++) {
    let t = lerp(t0, t1, i / steps);
    let cx = lerp(ex, tx, t);
    let cy = lerp(ey, ty, t);
    let hw = getHalfWidth(t);
    darkPoly.push([cx - nx * hw * 0.05, cy - ny * hw * 0.05]);
  }
  for (let i = steps; i >= 0; i--) {
    let t = lerp(t0, t1, i / steps);
    let cx = lerp(ex, tx, t);
    let cy = lerp(ey, ty, t);
    let hw = getHalfWidth(t);
    darkPoly.push([cx - nx * hw * 0.82, cy - ny * hw * 0.82]);
  }
  polyWash(darkPoly, PAL.steelDark, 230);

  resetBrush();
  // Warm koa-wood reflected light along bottom-right edge of steel cylinder
  let warmEdge = lowerEdge.map((p) => [p[0], p[1], 0.55]);
  brush.set("cpencil", PAL.steelWarm, 0.52);
  brush.spline(warmEdge, 0.25);

  // Crisp dark steel core line
  brush.set("2B", PAL.steelDeep, 0.48);
  brush.spline(midLine, 0.25);

  // Razor-sharp pure white window specular gleam along upper ridge
  brush.set("cpencil", PAL.steelBright, 0.85);
  brush.spline(specLine, 0.25);

  // Crisp upper and lower graphite contours
  let upStroke = upperEdge.map((p) => [p[0], p[1], 0.55]);
  brush.set("HB", PAL.steelDeep, 0.36);
  brush.spline(upStroke, 0.25);
  brush.spline(warmEdge, 0.25);

  // Elongated needle eye at the rear end (t = 0.015 .. 0.075)
  if (includeEye) {
    let eyeT0 = 0.018;
    let eyeT1 = 0.072;
    let eA = [lerp(ex, tx, eyeT0), lerp(ey, ty, eyeT0)];
    let eB = [lerp(ex, tx, eyeT1), lerp(ey, ty, eyeT1)];

    // Dark slot of the eye
    brush.set("pen", PAL.steelDeep, 0.72);
    brush.line(eA[0], eA[1], eB[0], eB[1]);

    // Bright bevel catchlight on the upper rim of the eye slot
    brush.set("cpencil", PAL.steelBright, 0.68);
    brush.line(
      eA[0] + nx * 1.6,
      eA[1] + ny * 1.6,
      eB[0] + nx * 1.6,
      eB[1] + ny * 1.6
    );
  }

  // Extra pinpoint gleam at the very tip of the needle
  if (includeTip) {
    brush.set("cpencil", PAL.steelBright, 0.95);
    brush.line(
      lerp(ex, tx, 0.92),
      lerp(ey, ty, 0.92),
      tx,
      ty
    );
  }
  resetBrush();
}

