  // Build the counted, patient alternating sequence along the garland spline
  // Working backward from s_top so the topmost seated item is a Popcorn puff,
  // which means the next item on the needle is Cranberry, then Popcorn!
  let garlandItems = [];
  let sCursor = garlandArc.totalLen - 28;
  let nextType = "popcorn"; // topmost item on thread
  let itemIdx = 0;

  while (sCursor > 24) {
    let rAlong = nextType === "popcorn" ? 31.5 : 21.5;
    let sample = sampleByArcLength(garlandArc, sCursor);
    garlandItems.push({
      type: nextType,
      s: sCursor,
      x: sample.x,
      y: sample.y,
      ang: sample.ang,
      rAlong: rAlong,
      seed: 1000 + itemIdx * 23
    });

    let followingType = nextType === "popcorn" ? "cranberry" : "popcorn";
    let nextRAlong = followingType === "popcorn" ? 31.5 : 21.5;
    // Snug, patient spacing along the cotton thread
    sCursor -= rAlong + nextRAlong - 2.5;
    nextType = followingType;
    itemIdx++;
  }
  garlandItems.reverse();

  // 1. Cast shadows for the entire garland + needle
  for (let i = 0; i < garlandItems.length; i++) {
    let it = garlandItems[i];
    // Slight progressive shadow lift near the top of the garland approaching the needle
    let lift = i >= garlandItems.length - 2 ? (i - (garlandItems.length - 3)) * 2.5 : 0;
    if (it.type === "popcorn") {
      drawPopcornShadow(it.x, it.y, 33, it.seed, 11 + lift, 10 + lift, 108);
    } else {
      drawCranberryShadow(it.x, it.y, 23, 19.5, it.ang, 10 + lift, 9 + lift, 118);
    }
  }

  // Cast shadows for the needle and the two mid-threading items impaled on it
  drawNeedleShadow(needleEx, needleEy, needleTx, needleTy);

  const needleBerryT = 0.56;
  const needleBerryX = lerp(needleEx, needleTx, needleBerryT);
  const needleBerryY = lerp(needleEy, needleTy, needleBerryT);

  const needlePuffT = 0.775;
  const needlePuffX = lerp(needleEx, needleTx, needlePuffT);
  const needlePuffY = lerp(needleEy, needleTy, needlePuffT);

  drawCranberryShadow(needleBerryX, needleBerryY, 23.5, 20, needleAng, 19, 17, 100);
  drawPopcornShadow(needlePuffX, needlePuffY, 34, 2025, 20, 18, 95);

  // 2. Draw exposed fuzzy cotton thread segments:
  //    a) Bottom-left tail entering the frame
  let firstItem = garlandItems[0];
  drawFuzzyThreadSegment(
    [
      [18, 1192],
      [44, 1168],
      [firstItem.x, firstItem.y]
    ],
    6,
    true
  );

  //    b) Spine thread under the garland
  let spineThreadPts = [];
  for (let s = 0; s <= garlandArc.totalLen; s += 28) {
    let smp = sampleByArcLength(garlandArc, s);
    spineThreadPts.push([smp.x, smp.y]);
  }
  drawFuzzyThreadSegment(spineThreadPts, 6, true);

  //    c) Exposed fuzzy cotton thread rising from the last seated popcorn puff into the needle eye!
  let lastItem = garlandItems[garlandItems.length - 1];
  let eyeSlotX = lerp(needleEx, needleTx, 0.042);
  let eyeSlotY = lerp(needleEy, needleTy, 0.042);

  let threadToEyePts = [
    [lastItem.x, lastItem.y],
    [734, 476],
    [756, 452],
    [eyeSlotX, eyeSlotY]
  ];
  drawFuzzyThreadSegment(threadToEyePts, 12, true);

  //    d) Loose doubled tail of the cotton thread looping out of the needle eye across the koa wood
  let threadTailPts = [
    [eyeSlotX, eyeSlotY],
    [806, 468],
    [834, 535],
    [848, 615],
    [888, 678],
    [958, 712],
    [1018, 704]
  ];
  drawFuzzyThreadSegment(threadTailPts, 9, true);

  // 3. Draw all the seated alternating Cranberries and Popcorn Puffs along the garland
  for (let i = 0; i < garlandItems.length; i++) {
    let it = garlandItems[i];
    if (it.type === "popcorn") {
      drawPopcornPuff(it.x, it.y, 33, it.seed);
    } else {
      drawCranberry(it.x, it.y, 23, 19.5, it.ang, it.seed, { showCalyx: false });
    }

    // Draw tiny fuzzy thread stitch bridge connecting the previous item into this item's center
    if (i > 0) {
      let prev = garlandItems[i - 1];
      let bridgeStart = sampleByArcLength(garlandArc, prev.s + prev.rAlong * 0.68);
      let bridgeEnd = sampleByArcLength(garlandArc, it.s - it.rAlong * 0.68);
      drawThreadBridge(bridgeStart.x, bridgeStart.y, bridgeEnd.x, bridgeEnd.y, true);
    }
  }

  // Draw the fuzzy thread emerging out of the center crevice of the last popcorn puff toward the needle eye
  let exitLast = [
    lastItem.x + cos(lastItem.ang) * 14,
    lastItem.y + sin(lastItem.ang) * 14
  ];
  drawFuzzyThreadSegment([exitLast, [734, 476], [756, 452], [eyeSlotX, eyeSlotY]], 10, false);

  // -----------------------------------------------------------------------
  // STEP 4: Long Steel Lei Needle Mid-Threading + Implied Hands
  // -----------------------------------------------------------------------
  // Segment A of Needle: Rear eye & shaft (t = 0.0 to t = 0.50, entering the cranberry)
  drawNeedleSegment(needleEx, needleEy, needleTx, needleTy, 0.0, 0.50, true, false);

  // Loop the fuzzy cotton thread visibly over the top rim of the needle eye so it passes through the slot!
  drawFuzzyThreadSegment(
    [
      [762, 444],
      [eyeSlotX, eyeSlotY],
      [792, 450]
    ],
    4,
    false
  );

  // Implied hands at the right / upper-right frame edge guiding the needle & steadying the puff
  drawImpliedHands(needleEx, needleEy, needleTx, needleTy);

  // Cranberry mid-threading on the needle shaft at t = 0.56
  // Entry dimple at t = 0.49
  drawCranberry(needleBerryX, needleBerryY, 23.5, 20, needleAng, 2024, { showCalyx: false });

  // Tiny exit dimple on the far side of the cranberry where the steel shaft emerges (t = 0.63)
  let berryExitX = lerp(needleEx, needleTx, 0.625);
  let berryExitY = lerp(needleEy, needleTy, 0.625);
  resetBrush();
  brush.set("2B", PAL.berryDark, 0.52);
  brush.circle(berryExitX, berryExitY, 2.8, 0.2);
  resetBrush();

  // Segment B of Needle: Gleaming steel shaft bridge between the cranberry and the popcorn puff (t = 0.62 to 0.71)
  drawNeedleSegment(needleEx, needleEy, needleTx, needleTy, 0.62, 0.71, false, false);

  // Popcorn puff mid-threading on the needle shaft at t = 0.775
  drawPopcornPuff(needlePuffX, needlePuffY, 34, 2025);

  // Segment C of Needle: Sharp steel point emerging cleanly through the popcorn puff! (t = 0.845 to 1.0)
  let tipExitX = lerp(needleEx, needleTx, 0.845);
  let tipExitY = lerp(needleEy, needleTy, 0.845);
  resetBrush();
  brush.set("2B", PAL.puffPencilDark, 0.48);
  brush.circle(tipExitX, tipExitY, 2.6, 0.25);
  resetBrush();

  drawNeedleSegment(needleEx, needleEy, needleTx, needleTy, 0.845, 1.0, false, true);

  noLoop();
}

