// ---------------------------------------------------------------------------
// Color & Math Utilities
// ---------------------------------------------------------------------------
function hexToRgb(hex) {
  let c = hex.replace("#", "");
  if (c.length === 3) c = c[0] + c[0] + c[1] + c[1] + c[2] + c[2];
  let num = parseInt(c, 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function rgbToHex(r, g, b) {
  const cl = (v) => Math.max(0, Math.min(255, Math.round(v)));
  return (
    "#" +
    ((1 << 24) + (cl(r) << 16) + (cl(g) << 8) + cl(b))
      .toString(16)
      .slice(1)
  );
}

function mixCol(h1, h2, t) {
  t = Math.max(0, Math.min(1, t));
  let a = hexToRgb(h1);
  let b = hexToRgb(h2);
  return rgbToHex(
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  );
}

function shadeCylinderCol(baseHex, litHex, darkHex, deepHex, u, normShift = 0) {
  let un = Math.max(-1, Math.min(1, u + normShift));
  // Key light around u = -0.34, secondary around u = +0.42, core shadow around u = +0.72 and -0.82
  if (un < -0.75) {
    // Far left edge: core shadow + subtle turquoise backboard bounce at extreme rim
    let t = (un + 1.0) / 0.25; // 0 at edge, 1 at -0.75
    let edgeCol = mixCol(darkHex, "#2A6B68", 0.28);
    return mixCol(edgeCol, darkHex, t);
  } else if (un < -0.34) {
    // Rising into key light
    let t = (un + 0.75) / 0.41;
    return mixCol(darkHex, litHex, Math.pow(t, 0.85));
  } else if (un < 0.15) {
    // Key light to rich center midtone
    let t = (un + 0.34) / 0.49;
    return mixCol(litHex, baseHex, t);
  } else if (un < 0.72) {
    // Center midtone into right core shadow
    let t = (un - 0.15) / 0.57;
    return mixCol(baseHex, deepHex, Math.pow(t, 1.1));
  } else {
    // Far right core shadow with warm ochre/pink rim bounce at +1.0
    let t = (un - 0.72) / 0.28;
    let bounce = mixCol(darkHex, "#8C5230", 0.32);
    return mixCol(deepHex, bounce, t * 0.75);
  }
}

// ---------------------------------------------------------------------------
// Safe p5.brush Wrapper Helpers (Prevents state leaks or unset brush errors)
// ---------------------------------------------------------------------------
function washPoly(pts, col, opacity = 255, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function fillPoly(pts, col, opacity = 110, bleed = 0.12, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(0.45, 0.3);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function strokeLine(x1, y1, x2, y2, bName, col, weight = 1) {
  if (dist(x1, y1, x2, y2) < 0.5) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(pts, bName, col, weight = 1, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curvature);
  }
}

function strokePoly(pts, bName, col, weight = 1, closed = true, curvature = 0) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function hatchPoly(pts, bName, col, weight, distPx, angleDeg, opts = { rand: 0.05 }, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(bName, col, weight);
  brush.hatch(distPx, angleDeg, opts);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

function makeEllipsePts(cx, cy, rx, ry, n = 40, startDeg = 0, endDeg = 360) {
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let a = lerp(startDeg, endDeg, i / n);
    pts.push([cx + rx * cos(a), cy + ry * sin(a)]);
  }
  return pts;
}

// ---------------------------------------------------------------------------
// 3D Cylindrical Projection for Tiffin Tiers
// ---------------------------------------------------------------------------
function mapTierPt(tier, u, v) {
  let uc = Math.max(-1, Math.min(1, u));
  let rx = lerp(tier.rxTop, tier.rxBot, v);
  let ry = lerp(tier.ryTop, tier.ryBot, v);
  let yBase = lerp(tier.yTop, tier.yBot, v);
  let sag = Math.sqrt(Math.max(0, 1 - uc * uc));

  let x = tier.cx + uc * rx;
  let y = yBase + ry * sag;
  let normShift = 0;

  if (tier.dents) {
    for (let d of tier.dents) {
      let du = (uc - d.u) / d.ru;
      let dv = (v - d.v) / d.rv;
      let r2 = du * du + dv * dv;
      if (r2 < 1.0) {
        let w = Math.pow(1.0 - r2, 2);
        x += d.dx * w;
        y += d.dy * w;
        // Derivative of dent creates sharp normal perturbation across the crease
        normShift += d.normShift * (1.0 - r2) * (dv > 0 ? -1.1 : 1.2);
      }
    }
  }
  return { x, y, u: uc, v, normShift };
}

function makeTierQuad(tier, u1, u2, v1, v2, stepsU = 10, stepsV = 4) {
  let pts = [];
  for (let i = 0; i <= stepsU; i++) {
    let p = mapTierPt(tier, lerp(u1, u2, i / stepsU), v1);
    pts.push([p.x, p.y]);
  }
  for (let j = 1; j <= stepsV; j++) {
    let p = mapTierPt(tier, u2, lerp(v1, v2, j / stepsV));
    pts.push([p.x, p.y]);
  }
  for (let i = stepsU - 1; i >= 0; i--) {
    let p = mapTierPt(tier, lerp(u1, u2, i / stepsU), v2);
    pts.push([p.x, p.y]);
  }
  for (let j = stepsV - 1; j >= 1; j--) {
    let p = mapTierPt(tier, u1, lerp(v1, v2, j / stepsV));
    pts.push([p.x, p.y]);
  }
  return pts;
}

