// 1. Backboard: Earthy Alcove, Striped Frame, Tin-Cut Flowers & Mirror Dots
// ---------------------------------------------------------------------------
function drawBackboardAlcove() {
  // Base warm earth wall
  washPoly([[0, 0], [1200, 0], [1200, 960], [0, 960]], PAL.alcoveDark, 255);

  // Radial warm earth glow behind tiffin carrier
  let glowRings = [
    { r: 520, col: PAL.alcoveMid, a: 180 },
    { r: 410, col: PAL.alcoveWarm, a: 160 },
    { r: 310, col: PAL.alcoveGlow, a: 135 },
    { r: 220, col: "#7D6048", a: 95 }
  ];
  for (let g of glowRings) {
    let pts = makeEllipsePts(600, 540, g.r, g.r * 1.08, 36);
    washPoly(pts, g.col, g.a);
  }

  // Subtle cross-hatched earth plaster texture in the alcove
  hatchPoly(
    [[140, 140], [1060, 140], [1060, 955], [140, 955]],
    "charcoal",
    "#18120E",
    0.55,
    18,
    25,
    { rand: 0.15 }
  );
  hatchPoly(
    [[140, 140], [1060, 140], [1060, 955], [140, 955]],
    "cpencil",
    "#574333",
    0.45,
    22,
    -65,
    { rand: 0.12 }
  );

  // Painted theatrical sunburst halo arch directly behind upper tiffin
  let haloCx = 600, haloCy = 340;
  let numRays = 24;
  for (let i = 0; i < numRays; i++) {
    let a1 = 180 + (i / numRays) * 180;
    let a2 = 180 + ((i + 1) / numRays) * 180;
    let col = i % 2 === 0 ? "#4D3B2C" : "#382A1F";
    if (i % 4 === 0) col = "#4E412D";
    let rayPts = [
      [haloCx, haloCy],
      [haloCx + 340 * cos(a1), haloCy + 280 * sin(a1)],
      [haloCx + 340 * cos(a2), haloCy + 280 * sin(a2)]
    ];
    washPoly(rayPts, col, 130);
  }
  // Thin gold-ochre scalloped ring around the halo
  for (let i = 0; i < 36; i++) {
    let a = 180 + (i / 36) * 180;
    let x = haloCx + 295 * cos(a);
    let y = haloCy + 245 * sin(a);
    let dotPts = makeEllipsePts(x, y, 4.5, 4.5, 10);
    washPoly(dotPts, PAL.earthOchre, 180);
  }
}

function drawStripedOuterFrame() {
  // Outer border thickness = 64px on left, top, right
  const bw = 64;
  // Base earth-wood backing for frame
  washPoly([[0, 0], [1200, 0], [1200, bw], [0, bw]], PAL.earthUmber, 255);
  washPoly([[0, 0], [bw, 0], [bw, 960], [0, 960]], PAL.earthUmber, 255);
  washPoly([[1200 - bw, 0], [1200, 0], [1200, 960], [1200 - bw, 960]], PAL.earthUmber, 255);

  const stripeCols = [
    PAL.turqBase,
    PAL.pinkBase,
    PAL.earthCream,
    PAL.saffronBase,
    PAL.turqDark,
    PAL.pinkLit,
    PAL.earthOchre,
    "#4B6E32"
  ];

  // Diagonal stripes along Left & Right pillars
  let step = 34;
  for (let i = -4; i < 32; i++) {
    let y0 = i * step;
    let y1 = y0 + step;
    let col = stripeCols[(i + 100) % stripeCols.length];
    // Left pillar chevron
    let lPts = [
      [0, constrain(y0, 0, 960)],
      [bw, constrain(y0 + 24, 0, 960)],
      [bw, constrain(y1 + 24, 0, 960)],
      [0, constrain(y1, 0, 960)]
    ];
    washPoly(lPts, col, 235);
    strokeLine(0, constrain(y0, 0, 960), bw, constrain(y0 + 24, 0, 960), "rotring", PAL.earthUmber, 0.9);

    // Right pillar chevron
    let rPts = [
      [1200, constrain(y0, 0, 960)],
      [1200 - bw, constrain(y0 + 24, 0, 960)],
      [1200 - bw, constrain(y1 + 24, 0, 960)],
      [1200, constrain(y1, 0, 960)]
    ];
    washPoly(rPts, col, 235);
    strokeLine(1200, constrain(y0, 0, 960), 1200 - bw, constrain(y0 + 24, 0, 960), "rotring", PAL.earthUmber, 0.9);
  }

  // Diagonal stripes along Top lintel
  for (let i = -2; i < 38; i++) {
    let x0 = i * step;
    let x1 = x0 + step;
    let col = stripeCols[(i + 100) % stripeCols.length];
    let skew = x0 < 600 ? 22 : -22;
    let tPts = [
      [constrain(x0, 0, 1200), 0],
      [constrain(x1, 0, 1200), 0],
      [constrain(x1 + skew, 0, 1200), bw],
      [constrain(x0 + skew, 0, 1200), bw]
    ];
    washPoly(tPts, col, 240);
    strokeLine(
      constrain(x0, 0, 1200),
      0,
      constrain(x0 + skew, 0, 1200),
      bw,
      "rotring",
      PAL.earthUmber,
      0.9
    );
  }

  // Aged patina & metallic inner molding strips along the striped frame
  // Outer edge shadow
  strokePoly([[4, 4], [1196, 4], [1196, 956], [4, 956]], "charcoal", "#120D0A", 1.8, false);

  // Double striped turquoise & hot pink inner fillet (x = 60..86, y = 60..86)
  washPoly([[58, 58], [1142, 58], [1142, 72], [58, 72]], PAL.turqDark, 255);
  washPoly([[58, 72], [1142, 72], [1142, 84], [58, 84]], PAL.pinkBase, 255);

  washPoly([[58, 58], [72, 58], [72, 956], [58, 956]], PAL.turqDark, 255);
  washPoly([[72, 72], [84, 72], [84, 956], [72, 956]], PAL.pinkBase, 255);

  washPoly([[1128, 58], [1142, 58], [1142, 956], [1128, 956]], PAL.turqDark, 255);
  washPoly([[1116, 72], [1128, 72], [1128, 956], [1116, 956]], PAL.pinkBase, 255);

  // Crisp highlight lines along the inner molding
  strokeLine(60, 60, 1140, 60, "enamel", PAL.turqBright, 0.65);
  strokeLine(74, 74, 1126, 74, "enamel", PAL.pinkBright, 0.55);
  strokeLine(60, 60, 60, 955, "enamel", PAL.turqBright, 0.65);
  strokeLine(1140, 60, 1140, 955, "enamel", PAL.turqBright, 0.65);
  strokeLine(84, 84, 1116, 84, "rotring", PAL.earthCream, 0.8);
  strokeLine(84, 84, 84, 955, "rotring", PAL.earthCream, 0.8);
  strokeLine(1116, 84, 1116, 955, "rotring", PAL.earthCream, 0.8);
}

function drawScallopedTinBorder() {
  // Build the theatrical scalloped arch & side curtains inside the frame
  // Side scallops run along x = 118 (left) and x = 1082 (right)
  // Top arch scallops curve across from (118, 250) up to (600, 118) and down to (1082, 250)

  let scallopCenters = [];

  // Left vertical column of scallops (bottom to top)
  for (let i = 0; i < 6; i++) {
    let y = 900 - i * 118;
    scallopCenters.push({ x: 112, y, r: 58, side: "left", idx: i });
  }
  // Right vertical column of scallops (bottom to top)
  for (let i = 0; i < 6; i++) {
    let y = 900 - i * 118;
    scallopCenters.push({ x: 1088, y, r: 58, side: "right", idx: i });
  }
  // Top theatrical arch scallops (left to right)
  let archCount = 9;
  for (let i = 0; i < archCount; i++) {
    let t = i / (archCount - 1); // 0 to 1
    let ang = lerp(195, 345, t);
    let x = 600 + 495 * cos(ang);
    let y = 275 + 155 * sin(ang);
    let r = i === 4 ? 68 : 60;
    scallopCenters.push({ x, y, r, side: "top", idx: i });
  }

  // First draw dark drop shadows behind all tin scallops onto the alcove wall
  for (let s of scallopCenters) {
    let shPts = makeEllipsePts(s.x + 6, s.y + 8, s.r + 4, s.r + 4, 24);
    washPoly(shPts, "#100B08", 190);
  }

  // Draw each tin-cut scalloped rosette, alternating Turquoise and Hot Pink
  for (let k = 0; k < scallopCenters.length; k++) {
    let s = scallopCenters[k];
    let isTurq = (s.idx % 2 === 0);
    drawTinScallopMedallion(s.x, s.y, s.r, isTurq);
  }

  // Corner gusset plates with extra mirror dots where arch meets vertical columns
  drawMirrorDot(165, 220, 13);
  drawMirrorDot(1035, 220, 13);
  drawMirrorDot(235, 165, 12);
  drawMirrorDot(965, 165, 12);

  // Hanging tin-cut teardrop pendants along the top arch cusps
  for (let i = 0; i < archCount - 1; i++) {
    let t = (i + 0.5) / (archCount - 1);
    let ang = lerp(195, 345, t);
    let px = 600 + 442 * cos(ang);
    let py = 278 + 145 * sin(ang);
    drawTinPendant(px, py, i % 2 === 0);
  }
}

function drawTinScallopMedallion(cx, cy, r, isTurq) {
  let mainCol = isTurq ? PAL.turqBase : PAL.pinkBase;
  let litCol = isTurq ? PAL.turqLit : PAL.pinkLit;
  let darkCol = isTurq ? PAL.turqDark : PAL.pinkDark;
  let accentCol = isTurq ? PAL.pinkBase : PAL.turqBase;
  let accentLit = isTurq ? PAL.pinkBright : PAL.turqBright;

  // 12-lobed crimped tin outer contour
  let lobes = 14;
  let outerPts = [];
  let steps = lobes * 4;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let wave = 1 + 0.08 * cos(a * lobes);
    let rad = r * wave;
    outerPts.push([cx + rad * cos(a), cy + rad * sin(a)]);
  }
  washPoly(outerPts, darkCol, 255);

  // Inner lit body shifted slightly toward top-left key light
  let innerBody = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let wave = 1 + 0.07 * cos(a * lobes);
    let rad = (r - 3.5) * wave;
    innerBody.push([cx - 1.5 + rad * cos(a), cy - 1.5 + rad * sin(a)]);
  }
  washPoly(innerBody, mainCol, 250);

  // Embossed radial flutes & bare tin rim highlights
  for (let i = 0; i < lobes; i++) {
    let a = (i / lobes) * 360;
    let x1 = cx + r * 0.58 * cos(a);
    let y1 = cy + r * 0.58 * sin(a);
    let x2 = cx + r * 0.96 * cos(a);
    let y2 = cy + r * 0.96 * sin(a);
    let fluteCol = (a > 190 && a < 350) ? litCol : darkCol;
    strokeLine(x1, y1, x2, y2, "enamel", fluteCol, 0.55);
    // Bare tin nick on outer crimp
    if (i % 2 === 0) {
      let tx1 = cx + (r + 1) * cos(a - 6);
      let ty1 = cy + (r + 1) * sin(a - 6);
      let tx2 = cx + (r + 1) * cos(a + 6);
      let ty2 = cy + (r + 1) * sin(a + 6);
      strokeLine(tx1, ty1, tx2, ty2, "rotring", PAL.steelBright, 0.85);
    }
  }

  // Concentric striped ring in saffron & cream
  washPoly(makeEllipsePts(cx, cy, r * 0.66, r * 0.66, 24), PAL.saffronBase, 250);
  washPoly(makeEllipsePts(cx, cy, r * 0.58, r * 0.58, 24), PAL.earthCream, 245);
  strokePoly(makeEllipsePts(cx, cy, r * 0.66, r * 0.66, 24), "rotring", PAL.earthUmber, 0.75, true);

  // Tin-cut 8-petal flower inside the medallion
  let petals = 8;
  for (let i = 0; i < petals; i++) {
    let a = (i / petals) * 360 + 22.5;
    let px = cx + r * 0.34 * cos(a);
    let py = cy + r * 0.34 * sin(a);
    let pPts = [];
    for (let j = -3; j <= 3; j++) {
      let pa = a + j * 14;
      let pr = r * (0.52 - Math.abs(j) * 0.055);
      pPts.push([cx + pr * cos(pa), cy + pr * sin(pa)]);
    }
    pPts.push([cx, cy]);
    washPoly(pPts, accentCol, 250);
    strokePoly(pPts, "rotring", "#1A120E", 0.65, true);
    // Specular tin crease on petal
    strokeLine(cx + r * 0.14 * cos(a), cy + r * 0.14 * sin(a), px, py, "rigger", accentLit, 0.7);
  }

  // Tiny mirror dots on the outer ring of the scallop
  for (let i = 0; i < 6; i++) {
    let a = i * 60;
    drawMirrorDot(cx + r * 0.78 * cos(a), cy + r * 0.78 * sin(a), 5.5);
  }

  // Central Shisha Mirror Dot
  drawMirrorDot(cx, cy, r * 0.21);
}

function drawMirrorDot(cx, cy, r) {
  // Oxidized tin bezel
  washPoly(makeEllipsePts(cx + 1, cy + 1.5, r + 2.5, r + 2.5, 16), "#120D0A", 220);
  washPoly(makeEllipsePts(cx, cy, r + 2, r + 2, 16), PAL.steelMid, 255);
  strokePoly(makeEllipsePts(cx, cy, r + 2, r + 2, 16), "rotring", PAL.earthUmber, 0.65, true);

  // Dark silvered glass core
  washPoly(makeEllipsePts(cx, cy, r, r, 16), "#172B30", 255);
  // Turquoise-sky lower crescent reflection
  washPoly(makeEllipsePts(cx + r * 0.15, cy + r * 0.18, r * 0.65, r * 0.55, 12), PAL.turqLit, 190);
  // Crisp diagonal white specular slash across glass
  strokeLine(cx - r * 0.55, cy - r * 0.35, cx + r * 0.35, cy - r * 0.55, "specular", "#FFFFFF", 0.65);
  strokeLine(cx - r * 0.45, cy + r * 0.15, cx + r * 0.45, cy - r * 0.15, "rotring", PAL.steelSpec, 0.85);
  // Tiny saffron & white enamel dots flanking bezel
  for (let a = 45; a < 360; a += 90) {
    let dx = cx + (r + 4.2) * cos(a);
    let dy = cy + (r + 4.2) * sin(a);
    washPoly(makeEllipsePts(dx, dy, 1.8, 1.8, 8), PAL.earthCream, 230);
  }
}

function drawTinPendant(x, y, isTurq) {
  let c1 = isTurq ? PAL.pinkBase : PAL.turqBase;
  let c2 = isTurq ? PAL.pinkBright : PAL.turqBright;
  let pts = [
    [x, y - 14],
    [x + 13, y + 6],
    [x, y + 24],
    [x - 13, y + 6]
  ];
  washPoly(pts, c1, 250);
  strokePoly(pts, "rotring", PAL.steelBright, 0.75, true);
  strokeLine(x, y - 10, x - 5, y + 6, "rigger", c2, 0.65);
  drawMirrorDot(x, y + 6, 5.5);
}

