// ---------------------------------------------------------------------------
// 4. Shared Cylinder Shading, Rolled Steel Rims, Dents & Enamel Speculars
// ---------------------------------------------------------------------------
function drawCylinderBaseAndShading(tier, baseHex, litHex, hotHex, darkHex, deepHex) {
  // Step 1: Solid base silhouette wash
  let silPts = makeTierQuad(tier, -1, 1, 0, 1, 28, 10);
  washPoly(silPts, darkHex, 255);

  // Step 2: Vertical cylindrical color bands (36 strips across u in [-1, 1])
  let strips = 38;
  for (let i = 0; i < strips; i++) {
    let u1 = lerp(-1, 1, i / strips);
    let u2 = lerp(-1, 1, (i + 1.05) / strips);
    let uMid = (u1 + u2) * 0.5;

    // Subdivide vertically into 3 sections so dent normal shifts affect shading locally
    for (let j = 0; j < 3; j++) {
      let v1 = j / 3;
      let v2 = (j + 1.02) / 3;
      let pMid = mapTierPt(tier, uMid, (v1 + v2) * 0.5);
      let col = shadeCylinderCol(baseHex, litHex, darkHex, deepHex, uMid, pMid.normShift);
      if (uMid + pMid.normShift > -0.44 && uMid + pMid.normShift < -0.22) {
        col = mixCol(col, hotHex, 0.45);
      }
      let qPts = makeTierQuad(tier, u1, u2, v1, v2, 3, 2);
      washPoly(qPts, col, 240);
    }
  }

  // Step 3: Fine vertical lacquer brush texture strokes following cylinder & dents
  for (let i = 0; i < 56; i++) {
    let u = lerp(-0.98, 0.98, i / 55);
    let pts = [];
    for (let k = 0; k <= 6; k++) {
      let p = mapTierPt(tier, u, k / 6);
      pts.push([p.x, p.y]);
    }
    let pMid = mapTierPt(tier, u, 0.5);
    let col = shadeCylinderCol(baseHex, litHex, darkHex, deepHex, u, pMid.normShift);
    col = (i % 2 === 0) ? mixCol(col, hotHex, 0.16) : mixCol(col, deepHex, 0.18);
    strokeSpline(pts, "enamel", col, 0.75, 0.3);
  }
}

function drawBottomFootRim(tier) {
  // Rolled stainless steel bottom rim at yBot = 952
  let rimPts = [];
  let n = 36;
  for (let i = 0; i <= n; i++) {
    let u = lerp(-1, 1, i / n);
    let sag = Math.sqrt(Math.max(0, 1 - u * u));
    rimPts.push([tier.cx + u * 224, tier.yBot - 4 + 44 * sag]);
  }
  for (let i = n; i >= 0; i--) {
    let u = lerp(-1, 1, i / n);
    let sag = Math.sqrt(Math.max(0, 1 - u * u));
    rimPts.push([tier.cx + u * 221, tier.yBot + 11 + 45 * sag]);
  }
  washPoly(rimPts, PAL.steelDark, 255);

  // Metallic reflection bands along foot rim
  for (let i = 0; i < 28; i++) {
    let u1 = lerp(-1, 1, i / 28);
    let u2 = lerp(-1, 1, (i + 1) / 28);
    let um = (u1 + u2) * 0.5;
    let col = PAL.steelMid;
    if (um > -0.45 && um < -0.18) col = PAL.steelSpec;
    else if (um > -0.65 && um < 0.15) col = PAL.steelBright;
    else if (um > 0.35 && um < 0.52) col = PAL.steelLit;
    else if (um > 0.58 || um < -0.78) col = "#252A2E";

    let s1 = Math.sqrt(Math.max(0, 1 - u1 * u1));
    let s2 = Math.sqrt(Math.max(0, 1 - u2 * u2));
    washPoly([
      [tier.cx + u1 * 223, tier.yBot - 2 + 44 * s1],
      [tier.cx + u2 * 223, tier.yBot - 2 + 44 * s2],
      [tier.cx + u2 * 221, tier.yBot + 9 + 45 * s2],
      [tier.cx + u1 * 221, tier.yBot + 9 + 45 * s1]
    ], col, 250);
  }
  // Crisp bottom steel contour
  let botLine = [];
  for (let i = 0; i <= 32; i++) {
    let u = lerp(-1, 1, i / 32);
    botLine.push([tier.cx + u * 221, tier.yBot + 10 + 45 * Math.sqrt(Math.max(0, 1 - u * u))]);
  }
  strokeSpline(botLine, "rotring", "#140E0A", 1.1, 0.4);
}

function drawRolledSteelRim(cx, yCenter, rx, ry, thickness, lowerPaintCol, upperPaintCol, scuffSeed) {
  let n = 36;
  // Dark under-lip shadow cast onto the tier below
  let shPts = [];
  for (let i = 0; i <= n; i++) {
    let u = lerp(-1, 1, i / n);
    let s = Math.sqrt(Math.max(0, 1 - u * u));
    shPts.push([cx + u * (rx - 2), yCenter + 2 + ry * s]);
  }
  for (let i = n; i >= 0; i--) {
    let u = lerp(-1, 1, i / n);
    let s = Math.sqrt(Math.max(0, 1 - u * u));
    shPts.push([cx + u * (rx - 4), yCenter + thickness + 7 + (ry + 2) * s]);
  }
  washPoly(shPts, "#140908", 215);

  // Rolled steel torus body
  for (let i = 0; i < 34; i++) {
    let u1 = lerp(-1, 1, i / 34);
    let u2 = lerp(-1, 1, (i + 1.04) / 34);
    let um = (u1 + u2) * 0.5;
    let s1 = Math.sqrt(Math.max(0, 1 - u1 * u1));
    let s2 = Math.sqrt(Math.max(0, 1 - u2 * u2));

    let col = PAL.steelMid;
    if (um > -0.42 && um < -0.22) col = PAL.steelSpec;
    else if (um > -0.60 && um < 0.08) col = PAL.steelBright;
    else if (um > 0.36 && um < 0.50) col = PAL.steelLit;
    else if (um > 0.56 && um < 0.88) col = PAL.steelDark;
    else if (um >= 0.88) col = mixCol(PAL.steelMid, PAL.earthOchre, 0.35);

    washPoly([
      [cx + u1 * rx, yCenter - thickness * 0.45 + ry * s1],
      [cx + u2 * rx, yCenter - thickness * 0.45 + ry * s2],
      [cx + u2 * rx, yCenter + thickness * 0.55 + ry * s2],
      [cx + u1 * rx, yCenter + thickness * 0.55 + ry * s1]
    ], col, 255);

    // Dark horizontal reflection band in the middle of the rolled steel bead
    let coreCol = (um > -0.38 && um < -0.26) ? PAL.steelBright : "#262C30";
    washPoly([
      [cx + u1 * (rx + 1), yCenter - thickness * 0.05 + ry * s1],
      [cx + u2 * (rx + 1), yCenter - thickness * 0.05 + ry * s2],
      [cx + u2 * (rx + 1), yCenter + thickness * 0.25 + ry * s2],
      [cx + u1 * (rx + 1), yCenter + thickness * 0.25 + ry * s1]
    ], coreCol, 235);
  }

  // Remnants of chipped enamel paint clinging to the rolled steel rim
  for (let k = 0; k < 9; k++) {
    let u = -0.82 + ((k * 0.21 + scuffSeed) % 1.64);
    if (Math.abs(u - (-0.33)) < 0.1) continue; // Keep primary specular clean
    let w = 0.04 + (k % 3) * 0.025;
    let s1 = Math.sqrt(Math.max(0, 1 - u * u));
    let s2 = Math.sqrt(Math.max(0, 1 - (u + w) * (u + w)));
    let pCol = k % 2 === 0 ? upperPaintCol : lowerPaintCol;
    if (u > 0.4) pCol = mixCol(pCol, "#1A120E", 0.5);
    washPoly([
      [cx + u * rx, yCenter - thickness * 0.4 + ry * s1],
      [cx + (u + w) * rx, yCenter - thickness * 0.4 + ry * s2],
      [cx + (u + w) * rx, yCenter + thickness * 0.35 + ry * s2],
      [cx + u * rx, yCenter + thickness * 0.35 + ry * s1]
    ], pCol, 225);
  }

  // Crisp top and bottom seam lines & blazing specular bead on the rim
  let topSeam = [], botSeam = [], specArc = [];
  for (let i = 0; i <= 32; i++) {
    let u = lerp(-1, 1, i / 32);
    let s = Math.sqrt(Math.max(0, 1 - u * u));
    topSeam.push([cx + u * rx, yCenter - thickness * 0.45 + ry * s]);
    botSeam.push([cx + u * rx, yCenter + thickness * 0.55 + ry * s]);
    if (u >= -0.52 && u <= -0.12) {
      specArc.push([cx + u * (rx + 0.5), yCenter - thickness * 0.22 + ry * s]);
    }
  }
  strokeSpline(topSeam, "rotring", "#1B120E", 0.95, 0.4);
  strokeSpline(botSeam, "rotring", "#140C09", 1.1, 0.4);
  strokeSpline(specArc, "specular", "#FFFFFF", 1.25, 0.4);
}

// Helper to draw a painted horizontal band on a tier
function drawTierBand(tier, v1, v2, baseHex, litHex, darkHex, deepHex, stepsU = 32) {
  for (let i = 0; i < stepsU; i++) {
    let u1 = lerp(-1, 1, i / stepsU);
    let u2 = lerp(-1, 1, (i + 1.03) / stepsU);
    let um = (u1 + u2) * 0.5;
    let pm = mapTierPt(tier, um, (v1 + v2) * 0.5);
    let col = shadeCylinderCol(baseHex, litHex, darkHex, deepHex, um, pm.normShift);
    let pts = makeTierQuad(tier, u1, u2, v1, v2, 2, 1);
    washPoly(pts, col, 248);
  }
}

function drawTierBeadRow(tier, v, count, colHex, rPx = 3.2) {
  for (let i = 1; i < count; i++) {
    let u = lerp(-0.95, 0.95, i / count);
    let p = mapTierPt(tier, u, v);
    let horizScale = Math.sqrt(Math.max(0.15, 1 - u * u));
    let c = shadeCylinderCol(colHex, "#FFFFFF", "#8A7356", "#3D2E1E", u, p.normShift);
    washPoly(makeEllipsePts(p.x, p.y, rPx * horizScale, rPx, 8), c, 245);
  }
}

// Helper to render a realistic dent with red-oxide primer and bare brushed steel
function drawDentAndScuff(tier, dent, lacquerDarkHex) {
  let u0 = dent.u;
  let v0 = dent.v;
  let ru = dent.ru;
  let rv = dent.rv;

  // 1. Concave shadow bowl in upper half of dent
  let upperBowl = [];
  for (let a = 180; a <= 360; a += 20) {
    let p = mapTierPt(tier, u0 + ru * 0.85 * cos(a), v0 + rv * 0.75 * sin(a));
    upperBowl.push([p.x, p.y]);
  }
  for (let a = 0; a <= 180; a += 20) {
    let p = mapTierPt(tier, u0 + ru * 0.65 * cos(a), v0 + rv * 0.12 * sin(a));
    upperBowl.push([p.x, p.y]);
  }
  washPoly(upperBowl, lacquerDarkHex, 210);

  // 2. Bright reflected catchlight on lower lip of the dent
  let lowerLip = [];
  for (let a = 15; a <= 165; a += 18) {
    let p = mapTierPt(tier, u0 + ru * 0.78 * cos(a), v0 + rv * 0.65 * sin(a));
    lowerLip.push([p.x, p.y]);
  }
  strokeSpline(lowerLip, "enamel", "#FFD6B8", 0.9, 0.4);

  // 3. Irregular chipped red-oxide primer patch around the impact crease
  let primerPts = [];
  let chipAngles = [0, 35, 72, 115, 155, 195, 235, 280, 325];
  let chipRads = [0.68, 0.48, 0.55, 0.62, 0.74, 0.58, 0.45, 0.52, 0.64];
  for (let i = 0; i < chipAngles.length; i++) {
    let a = chipAngles[i];
    let r = chipRads[i];
    let p = mapTierPt(tier, u0 + ru * r * cos(a), v0 + rv * r * 0.75 * sin(a));
    primerPts.push([p.x, p.y]);
  }
  washPoly(primerPts, PAL.primerOxide, 250);
  strokePoly(primerPts, "rotring", "#2B0C08", 0.75, true);

  // 4. Bare brushed stainless steel exposed inside the primer chip
  let steelPts = [];
  for (let i = 0; i < chipAngles.length; i++) {
    let a = chipAngles[i];
    let r = chipRads[i] * 0.74;
    let p = mapTierPt(tier, u0 + ru * r * cos(a), v0 + rv * r * 0.72 * sin(a));
    steelPts.push([p.x, p.y]);
  }
  washPoly(steelPts, PAL.steelMid, 255);

  // Metallic sheen & impact scratches across bare metal
  let pLeft = mapTierPt(tier, u0 - ru * 0.45, v0 - rv * 0.05);
  let pRight = mapTierPt(tier, u0 + ru * 0.45, v0 + rv * 0.08);
  let pTop = mapTierPt(tier, u0 - ru * 0.15, v0 - rv * 0.25);
  let pBot = mapTierPt(tier, u0 + ru * 0.20, v0 + rv * 0.25);

  washPoly([
    [pLeft.x, pLeft.y - 4],
    [pRight.x, pRight.y - 4],
    [pRight.x, pRight.y + 5],
    [pLeft.x, pLeft.y + 5]
  ], PAL.steelBright, 235);

  strokeLine(pLeft.x - 4, pLeft.y, pRight.x + 4, pRight.y, "rotring", "#1E2429", 1.15);
  strokeLine(pLeft.x - 2, pLeft.y + 2.5, pRight.x + 2, pRight.y + 2.5, "specular", PAL.steelSpec, 0.95);
  strokeLine(pTop.x, pTop.y, pBot.x, pBot.y, "rigger", PAL.steelDark, 0.8);
  strokeLine(pTop.x + 3, pTop.y, pBot.x + 3, pBot.y, "rigger", PAL.steelSpec, 0.65);

  // Pale chipped-enamel thickness edge along top of chip
  strokeSpline(primerPts.slice(4, 9), "rigger", "#F5D7C4", 0.65, 0.3);
}

// Helper to apply glossy enamel specular streaks across a tier
function drawTierSpecularStreaks(tier, primaryU = -0.34, secondaryU = 0.42) {
  // 1. Soft glossy bloom around primary key light streak
  for (let du of [-0.045, -0.02, 0.0, 0.02, 0.045]) {
    let pts = [];
    for (let k = 0; k <= 16; k++) {
      let v = k / 16;
      let p = mapTierPt(tier, primaryU + du, v);
      // Shift streak horizontally when dent perturbs surface normal!
      pts.push([p.x - p.normShift * 28, p.y]);
    }
    let w = (1.1 - Math.abs(du) * 14);
    let col = Math.abs(du) < 0.015 ? "#FFFFFF" : "#FFF2E2";
    strokeSpline(pts, "enamel", col, Math.max(0.35, w * 0.65), 0.35);
  }

  // 2. Hard razor-sharp specular core streak (broken slightly by hand-painted ridges)
  let segs = [
    [0.04, 0.32],
    [0.36, 0.68],
    [0.72, 0.95]
  ];
  for (let s of segs) {
    let pts = [];
    let pts2 = [];
    for (let k = 0; k <= 8; k++) {
      let v = lerp(s[0], s[1], k / 8);
      let p = mapTierPt(tier, primaryU, v);
      let p2 = mapTierPt(tier, primaryU - 0.022, v);
      pts.push([p.x - p.normShift * 32, p.y]);
      pts2.push([p2.x - p2.normShift * 32, p2.y]);
    }
    strokeSpline(pts, "specular", "#FFFFFF", 1.15, 0.35);
    strokeSpline(pts2, "rigger", "#E6F7FF", 0.85, 0.35);
  }

  // 3. Secondary right-side specular reflection streak (broken where dal stain or dent sits)
  let secSegs = [
    [0.08, 0.44],
    [0.64, 0.92]
  ];
  for (let s of secSegs) {
    let pts = [];
    for (let k = 0; k <= 6; k++) {
      let v = lerp(s[0], s[1], k / 6);
      let p = mapTierPt(tier, secondaryU, v);
      pts.push([p.x - p.normShift * 24, p.y]);
    }
    strokeSpline(pts, "enamel", "#FFF5DF", 0.55, 0.35);
    strokeSpline(pts, "rigger", "#D4F5F2", 0.6, 0.35);
  }

  // 4. Extreme left edge turquoise backboard rim reflection
  let rimPts = [];
  for (let k = 0; k <= 10; k++) {
    let p = mapTierPt(tier, -0.95, k / 10);
    rimPts.push([p.x, p.y]);
  }
  strokeSpline(rimPts, "enamel", PAL.turqLit, 0.55, 0.3);
}

// Helper to draw a rickshaw rose mapped onto any tier at (u0, v0)
function drawRickshawRoseOnTier(tier, u0, v0, ru, rv, mainHex, litHex, darkHex, tipHex) {
  // First draw serrated green rose leaves behind the blossom
  let leafAngles = [-155, -115, -45, 25, 145, -18];
  for (let i = 0; i < leafAngles.length; i++) {
    let a = leafAngles[i];
    let distScale = (i % 2 === 0) ? 1.38 : 1.18;
    let lu = u0 + ru * distScale * cos(a);
    let lv = v0 + rv * distScale * sin(a);
    if (lu < -0.95 || lu > 0.95 || lv < 0.08 || lv > 0.92) continue;

    let pBase = mapTierPt(tier, u0 + ru * 0.45 * cos(a), v0 + rv * 0.45 * sin(a));
    let pTip = mapTierPt(tier, lu, lv);
    let pSide1 = mapTierPt(tier, u0 + ru * 0.92 * cos(a - 22), v0 + rv * 0.92 * sin(a - 22));
    let pSide2 = mapTierPt(tier, u0 + ru * 0.92 * cos(a + 22), v0 + rv * 0.92 * sin(a + 22));

    let lCol = shadeCylinderCol("#2D8028", "#7BE04A", "#174516", "#0B240B", lu, pTip.normShift);
    let lLit = shadeCylinderCol("#8CE854", "#C8FF82", "#3B7A28", "#1F4514", lu, pTip.normShift);

    let leafPts = [[pBase.x, pBase.y], [pSide1.x, pSide1.y], [pTip.x, pTip.y], [pSide2.x, pSide2.y]];
    washPoly(leafPts, lCol, 250);
    strokePoly(leafPts, "rotring", "#122410", 0.7, true);
    strokeLine(pBase.x, pBase.y, pTip.x, pTip.y, "rigger", lLit, 0.75);
  }

  // Outer dark crimson rose shadow base
  let basePts = [];
  for (let i = 0; i < 18; i++) {
    let a = (i / 18) * 360;
    let rMod = 1 + 0.1 * sin(a * 6);
    let p = mapTierPt(tier, u0 + ru * rMod * cos(a), v0 + rv * rMod * sin(a));
    basePts.push([p.x, p.y]);
  }
  let pCenter = mapTierPt(tier, u0, v0);
  let cDark = shadeCylinderCol(darkHex, mainHex, "#380510", "#210208", u0, pCenter.normShift);
  washPoly(basePts, cDark, 255);
  strokePoly(basePts, "rotring", "#1F050A", 0.85, true);

  // 3 concentric rings of scalloped rickshaw-style petals with cream/pink brushed edges
  let rings = [
    { count: 7, rScale: 0.95, rot: 10 },
    { count: 6, rScale: 0.68, rot: 38 },
    { count: 5, rScale: 0.42, rot: 15 }
  ];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    let rg = rings[rIdx];
    for (let i = 0; i < rg.count; i++) {
      let a1 = rg.rot + (i / rg.count) * 360;
      let a2 = rg.rot + ((i + 0.88) / rg.count) * 360;
      let am = (a1 + a2) * 0.5;

      let petalPts = [];
      let pIn = mapTierPt(tier, u0 + ru * rg.rScale * 0.32 * cos(am), v0 + rv * rg.rScale * 0.32 * sin(am));
      petalPts.push([pIn.x, pIn.y]);

      let rimCurve = [];
      for (let s = 0; s <= 4; s++) {
        let ang = lerp(a1, a2, s / 4);
        let bulge = rg.rScale * (1.0 + 0.12 * sin((s / 4) * 180));
        let pu = u0 + ru * bulge * cos(ang);
        let pv = v0 + rv * bulge * sin(ang);
        let pt = mapTierPt(tier, pu, pv);
        petalPts.push([pt.x, pt.y]);
        rimCurve.push([pt.x, pt.y]);
      }

      let puMid = u0 + ru * rg.rScale * cos(am);
      let pCol = shadeCylinderCol(
        rIdx === 0 ? mainHex : litHex,
        litHex,
        darkHex,
        "#2B040C",
        puMid,
        pCenter.normShift
      );
      washPoly(petalPts, pCol, 250);

      // Hand-painted white/pink highlight arc along outer edge of each rose petal
      let tCol = shadeCylinderCol(tipHex, "#FFFFFF", litHex, mainHex, puMid, pCenter.normShift);
      strokeSpline(rimCurve, "rigger", tCol, 0.85, 0.45);
    }
  }

  // Golden saffron stamen heart
  let heartPts = [];
  for (let i = 0; i < 10; i++) {
    let a = i * 36;
    let p = mapTierPt(tier, u0 + ru * 0.18 * cos(a), v0 + rv * 0.18 * sin(a));
    heartPts.push([p.x, p.y]);
  }
  let sCol = shadeCylinderCol(PAL.saffronBright, "#FFFFFF", PAL.saffronBase, PAL.saffronDark, u0, pCenter.normShift);
  washPoly(heartPts, sCol, 255);
  strokePoly(heartPts, "rotring", "#3B0A10", 0.65, true);
}

// ---------------------------------------------------------------------------
// 5. TIER 3 (Bottom): Candy-Apple Red + Royal Peacock + Dent #1
// ---------------------------------------------------------------------------
function drawTier3RedPeacock(tier) {
  // 1. Glossy Candy-Apple Red cylindrical base
  drawCylinderBaseAndShading(tier, PAL.redBase, PAL.redLit, PAL.redHot, PAL.redDark, PAL.redDeep);

  // 2. Top and Bottom decorative rickshaw border bands
  drawTierBand(tier, 0.04, 0.095, PAL.saffronBase, PAL.saffronBright, PAL.saffronDark, PAL.saffronDeep);
  drawTierBand(tier, 0.095, 0.135, PAL.greenBase, PAL.greenBright, PAL.greenDark, PAL.greenDeep);
  drawTierBand(tier, 0.88, 0.92, PAL.greenBase, PAL.greenBright, PAL.greenDark, PAL.greenDeep);
  drawTierBand(tier, 0.92, 0.965, PAL.saffronBase, PAL.saffronBright, PAL.saffronDark, PAL.saffronDeep);

  drawTierBeadRow(tier, 0.155, 28, PAL.earthCream, 2.8);
  drawTierBeadRow(tier, 0.86, 28, PAL.earthCream, 2.8);

  // Cream & turquoise corner spandrel arches inside the red panel
  for (let side of [-1, 1]) {
    let uStart = side * 0.96;
    let uEnd = side * 0.56;
    let spPts = [
      mapTierPt(tier, uStart, 0.17),
      mapTierPt(tier, uEnd, 0.17),
      mapTierPt(tier, side * 0.72, 0.25),
      mapTierPt(tier, uStart, 0.42)
    ].map((p) => [p.x, p.y]);
    let spCol = shadeCylinderCol(PAL.turqBase, PAL.turqBright, PAL.turqDark, PAL.turqDeep, side * 0.78);
    washPoly(spPts, spCol, 240);
    strokePoly(spPts, "rigger", PAL.earthCream, 0.75, true);
  }

  // 3. Left Floral Spray (Rickshaw Rose + buds at u = -0.64, v = 0.58)
  drawRickshawRoseOnTier(
    tier,
    -0.64,
    0.58,
    0.16,
    0.18,
    PAL.pinkBase,
    PAL.pinkLit,
    PAL.pinkDark,
    PAL.earthCream
  );

  // Golden vine scrolls connecting rose to peacock
  let vinePts = [];
  for (let t = 0; t <= 1; t += 0.12) {
    let p = mapTierPt(tier, lerp(-0.52, -0.15, t), 0.74 + 0.06 * sin(t * 360));
    vinePts.push([p.x, p.y]);
  }
  strokeSpline(vinePts, "rigger", PAL.saffronBright, 1.0, 0.5);

  // 4. THE ROYAL RICKSHAW PEACOCK (MOR)
  // Sweeping tail train from u = -0.05 to u = +0.86, v = 0.24 to 0.82
  let plumeDefs = [
    { uTip: 0.78, vTip: 0.30, uMid: 0.38, vMid: 0.34 },
    { uTip: 0.85, vTip: 0.44, uMid: 0.44, vMid: 0.44 },
    { uTip: 0.86, vTip: 0.60, uMid: 0.45, vMid: 0.56 },
    { uTip: 0.78, vTip: 0.75, uMid: 0.40, vMid: 0.68 },
    { uTip: 0.56, vTip: 0.25, uMid: 0.24, vMid: 0.32 },
    { uTip: 0.62, vTip: 0.40, uMid: 0.28, vMid: 0.43 },
    { uTip: 0.64, vTip: 0.55, uMid: 0.30, vMid: 0.53 },
    { uTip: 0.58, vTip: 0.71, uMid: 0.26, vMid: 0.65 },
    { uTip: 0.36, vTip: 0.77, uMid: 0.14, vMid: 0.68 }
  ];

  // Underlying emerald-turquoise tail fan body
  let fanOutline = [
    mapTierPt(tier, -0.05, 0.52),
    mapTierPt(tier, 0.25, 0.24),
    mapTierPt(tier, 0.78, 0.28),
    mapTierPt(tier, 0.88, 0.52),
    mapTierPt(tier, 0.78, 0.76),
    mapTierPt(tier, 0.32, 0.80),
    mapTierPt(tier, -0.05, 0.62)
  ].map((p) => [p.x, p.y]);
  washPoly(fanOutline, PAL.greenDark, 235);

  // Paint each feather rachis, emerald barbules, and concentric peacock eye-spot
  for (let pf of plumeDefs) {
    let p0 = mapTierPt(tier, -0.02, 0.55);
    let p1 = mapTierPt(tier, pf.uMid, pf.vMid);
    let p2 = mapTierPt(tier, pf.uTip, pf.vTip);

    // Barbules along feather stem
    for (let s = 0.2; s <= 0.9; s += 0.12) {
      let us = lerp(-0.02, pf.uTip, s);
      let vs = lerp(0.55, pf.vTip, s) - 0.04 * sin(s * 180);
      let ps = mapTierPt(tier, us, vs);
      let pb1 = mapTierPt(tier, us + 0.04, vs - 0.045);
      let pb2 = mapTierPt(tier, us + 0.04, vs + 0.045);
      let bCol = shadeCylinderCol(PAL.greenLit, PAL.greenBright, PAL.greenBase, PAL.greenDark, us, ps.normShift);
      strokeLine(ps.x, ps.y, pb1.x, pb1.y, "rigger", bCol, 0.65);
      strokeLine(ps.x, ps.y, pb2.x, pb2.y, "rigger", bCol, 0.65);
    }

    // Golden stem (rachis)
    let stemCol = shadeCylinderCol(PAL.saffronBright, "#FFFFFF", PAL.saffronBase, PAL.saffronDark, pf.uMid, p1.normShift);
    strokeSpline([[p0.x, p0.y], [p1.x, p1.y], [p2.x, p2.y]], "rigger", stemCol, 0.8, 0.45);

    // Peacock Eye-Spot (Chand) at (uTip, vTip)
    let hScale = Math.sqrt(Math.max(0.2, 1 - pf.uTip * pf.uTip));
    let rxEye = 18 * hScale;
    let ryEye = 14;
    let cGold = shadeCylinderCol(PAL.saffronBright, "#FFFFFF", PAL.saffronBase, PAL.saffronDark, pf.uTip, p2.normShift);
    let cTurq = shadeCylinderCol(PAL.turqLit, PAL.turqBright, PAL.turqBase, PAL.turqDark, pf.uTip, p2.normShift);
    let cBlue = shadeCylinderCol(PAL.cobaltBase, PAL.cobaltLit, PAL.cobaltDark, "#051226", pf.uTip, p2.normShift);

    washPoly(makeEllipsePts(p2.x, p2.y, rxEye, ryEye, 14), PAL.greenBright, 240);
    washPoly(makeEllipsePts(p2.x, p2.y, rxEye * 0.78, ryEye * 0.78, 14), cGold, 250);
    washPoly(makeEllipsePts(p2.x, p2.y, rxEye * 0.54, ryEye * 0.54, 12), cTurq, 250);
    washPoly(makeEllipsePts(p2.x + 1.5, p2.y, rxEye * 0.32, ryEye * 0.32, 10), cBlue, 255);
    strokePoly(makeEllipsePts(p2.x, p2.y, rxEye * 0.78, ryEye * 0.78, 14), "rotring", "#172912", 0.6, true);
  }

  // Peacock Body, Wing & Graceful S-Curved Cobalt Neck (u = -0.38 .. +0.08)
  let bodyCoords = [
    [-0.28, 0.30], // head crown
    [-0.35, 0.33], // forehead
    [-0.32, 0.40], // throat
    [-0.36, 0.54], // chest
    [-0.28, 0.66], // lower belly
    [-0.08, 0.68], // under-tail
    [0.08, 0.58],  // rump
    [-0.04, 0.48], // back
    [-0.20, 0.46], // base of back-neck
    [-0.24, 0.35]  // nape
  ];
  let bodyPts = bodyCoords.map((c) => {
    let p = mapTierPt(tier, c[0], c[1]);
    return [p.x, p.y];
  });
  washPoly(bodyPts, PAL.cobaltBase, 255);
  // Lit turquoise-cobalt sheen on neck and chest (right in key light zone!)
  let litNeckPts = [
    mapTierPt(tier, -0.31, 0.32),
    mapTierPt(tier, -0.35, 0.52),
    mapTierPt(tier, -0.26, 0.62),
    mapTierPt(tier, -0.22, 0.46)
  ].map((p) => [p.x, p.y]);
  washPoly(litNeckPts, PAL.cobaltLit, 235);
  strokePoly(bodyPts, "rotring", "#07172E", 0.9, true);

  // Scalloped Saffron & Rose-Pink Wing on Peacock's side
  let wingCoords = [
    [-0.22, 0.50],
    [-0.02, 0.49],
    [0.06, 0.57],
    [-0.04, 0.64],
    [-0.22, 0.62]
  ];
  let wingPts = wingCoords.map((c) => {
    let p = mapTierPt(tier, c[0], c[1]);
    return [p.x, p.y];
  });
  washPoly(wingPts, PAL.saffronLit, 250);
  strokePoly(wingPts, "rotring", "#241008", 0.8, true);

  // Scalloped wing feather scales in crimson & white
  for (let uW = -0.18; uW <= 0.0; uW += 0.06) {
    let pw1 = mapTierPt(tier, uW, 0.52);
    let pw2 = mapTierPt(tier, uW, 0.61);
    strokeLine(pw1.x, pw1.y, pw2.x, pw2.y, "rigger", PAL.redBase, 0.8);
    washPoly(makeEllipsePts(pw1.x, (pw1.y + pw2.y) * 0.5, 4, 4, 8), PAL.earthCream, 240);
  }

  // Peacock Beak, Eye & Golden Crest (Kalgi)
  let pHead = mapTierPt(tier, -0.31, 0.34);
  let pBeakBase = mapTierPt(tier, -0.35, 0.34);
  let pBeakTip = mapTierPt(tier, -0.43, 0.36);
  washPoly([[pBeakBase.x, pBeakBase.y - 4], [pBeakTip.x, pBeakTip.y], [pBeakBase.x, pBeakBase.y + 4]], PAL.saffronBright, 255);
  strokePoly([[pBeakBase.x, pBeakBase.y - 4], [pBeakTip.x, pBeakTip.y], [pBeakBase.x, pBeakBase.y + 4]], "rotring", "#1E120A", 0.65, true);

  // Crisp white eye patch & dark pupil
  washPoly(makeEllipsePts(pHead.x, pHead.y, 6.5, 4.5, 10), "#FFFFFF", 255);
  washPoly(makeEllipsePts(pHead.x - 1, pHead.y, 3.0, 3.0, 8), "#0B0D12", 255);

  // 3-plume golden crest
  for (let k = -1; k <= 1; k++) {
    let pCrown = mapTierPt(tier, -0.28, 0.30);
    let pCrest = mapTierPt(tier, -0.24 + k * 0.035, 0.21 + Math.abs(k) * 0.015);
    strokeLine(pCrown.x, pCrown.y, pCrest.x, pCrest.y, "rigger", PAL.saffronBright, 0.8);
    washPoly(makeEllipsePts(pCrest.x, pCrest.y, 4, 3.5, 8), PAL.turqBright, 250);
  }

  // Peacock legs perched on golden branch
  let pLeg1 = mapTierPt(tier, -0.22, 0.67);
  let pFoot1 = mapTierPt(tier, -0.24, 0.77);
  let pLeg2 = mapTierPt(tier, -0.15, 0.68);
  let pFoot2 = mapTierPt(tier, -0.16, 0.78);
  strokeLine(pLeg1.x, pLeg1.y, pFoot1.x, pFoot1.y, "rigger", PAL.saffronBright, 0.9);
  strokeLine(pLeg2.x, pLeg2.y, pFoot2.x, pFoot2.y, "rigger", PAL.saffronBright, 0.9);

  // 5. Render Dent #1 & Bare Metal Scuffs on Tier 3
  drawDentAndScuff(tier, DENTS.tier3[0], PAL.redDeep);

  // Extra bottom-edge bare metal wear at u = -0.18, v = 0.94
  let pScuff1 = mapTierPt(tier, -0.24, 0.93);
  let pScuff2 = mapTierPt(tier, -0.11, 0.95);
  washPoly([
    [pScuff1.x, pScuff1.y - 4],
    [pScuff2.x, pScuff2.y - 3],
    [pScuff2.x, pScuff2.y + 5],
    [pScuff1.x, pScuff1.y + 4]
  ], PAL.primerOxide, 240);
  strokeLine(pScuff1.x + 3, pScuff1.y, pScuff2.x - 3, pScuff2.y, "specular", PAL.steelBright, 0.9);

  // 6. Glossy Enamel Specular Streaks across Tier 3
  drawTierSpecularStreaks(tier, -0.34, 0.42);
}

// ---------------------------------------------------------------------------
// 6. TIER 2 (Middle): Parrot Green + Lush Rickshaw Roses + Dent #2
// ---------------------------------------------------------------------------
function drawTier2GreenRoses(tier) {
  // 1. Glossy Parrot Green cylindrical base
  drawCylinderBaseAndShading(tier, PAL.greenBase, PAL.greenLit, PAL.greenBright, PAL.greenDark, PAL.greenDeep);

  // 2. Decorative Top & Bottom Borders in Saffron & Candy-Apple Red
  drawTierBand(tier, 0.045, 0.095, PAL.redBase, PAL.redLit, PAL.redDark, PAL.redDeep);
  drawTierBand(tier, 0.095, 0.14, PAL.saffronBase, PAL.saffronBright, PAL.saffronDark, PAL.saffronDeep);
  drawTierBand(tier, 0.86, 0.905, PAL.saffronBase, PAL.saffronBright, PAL.saffronDark, PAL.saffronDeep);
  drawTierBand(tier, 0.905, 0.955, PAL.redBase, PAL.redLit, PAL.redDark, PAL.redDeep);

  // Alternating triangle/chevron teeth along the inner border
  let teeth = 22;
  for (let i = 0; i < teeth; i++) {
    let u1 = lerp(-0.94, 0.94, i / teeth);
    let u2 = lerp(-0.94, 0.94, (i + 1) / teeth);
    let um = (u1 + u2) * 0.5;
    let p1 = mapTierPt(tier, u1, 0.14);
    let p2 = mapTierPt(tier, u2, 0.14);
    let pTip = mapTierPt(tier, um, 0.19);
    let c = shadeCylinderCol(
      i % 2 === 0 ? PAL.earthCream : PAL.turqLit,
      "#FFFFFF",
      PAL.earthOchre,
      PAL.earthUmber,
      um,
      pTip.normShift
    );
    washPoly([[p1.x, p1.y], [p2.x, p2.y], [pTip.x, pTip.y]], c, 240);
  }

  // 3. Central Scalloped Rickshaw Cartouche Panel
  let cartPts = [];
  let nC = 28;
  for (let i = 0; i <= nC; i++) {
    let a = (i / nC) * 360;
    let wave = 1 + 0.04 * cos(a * 14);
    let u = 0.82 * wave * cos(a);
    let v = 0.51 + 0.27 * wave * sin(a);
    let p = mapTierPt(tier, u, v);
    cartPts.push([p.x, p.y]);
  }
  strokePoly(cartPts, "enamel", PAL.saffronBright, 1.1, true);
  strokePoly(cartPts, "rotring", PAL.redDark, 0.75, true);

  // Swirling white/yellow floral tendrils behind the roses
  for (let side of [-1, 1]) {
    let tendril = [];
    for (let t = 0; t <= 1; t += 0.1) {
      let u = side * lerp(0.12, 0.78, t);
      let v = 0.52 + 0.14 * sin(t * 360 * side);
      let p = mapTierPt(tier, u, v);
      tendril.push([p.x, p.y]);
    }
    let tCol = side < 0 ? PAL.earthCream : PAL.earthOchre;
    strokeSpline(tendril, "rigger", tCol, 0.85, 0.5);
  }

  // 4. Three Lush Multi-Layered Rickshaw Roses (Gulab)
  // Left Rose (Saffron-Coral & Vermilion Rose)
  drawRickshawRoseOnTier(
    tier,
    -0.50,
    0.53,
    0.16,
    0.18,
    PAL.redLit,
    PAL.saffronBright,
    PAL.redDark,
    "#FFF4D4"
  );

  // Right Rose (Deep Magenta-Crimson Rose in cylinder shadow)
  drawRickshawRoseOnTier(
    tier,
    0.46,
    0.53,
    0.16,
    0.18,
    PAL.pinkBase,
    PAL.pinkLit,
    PAL.pinkDeep,
    PAL.pinkBright
  );

  // Center Hero Rose (Grand 5-layer Rickshaw Gulab in Candy-Apple & Hot Pink)
  drawRickshawRoseOnTier(
    tier,
    -0.03,
    0.51,
    0.22,
    0.25,
    PAL.redBase,
    PAL.pinkLit,
    PAL.redDeep,
    "#FFF7EB"
  );

  // Dainty jasmine buds & white dots around the center rose
  let budPos = [
    [-0.28, 0.33], [0.22, 0.33], [-0.27, 0.70], [0.22, 0.70],
    [-0.74, 0.44], [-0.74, 0.62], [0.72, 0.44], [0.72, 0.62]
  ];
  for (let bp of budPos) {
    let p = mapTierPt(tier, bp[0], bp[1]);
    let bCol = shadeCylinderCol(PAL.earthCream, "#FFFFFF", PAL.earthSand, PAL.earthOchre, bp[0], p.normShift);
    washPoly(makeEllipsePts(p.x, p.y, 6, 4.5, 10), bCol, 245);
    strokePoly(makeEllipsePts(p.x, p.y, 6, 4.5, 10), "rotring", "#1A2E14", 0.6, true);
    washPoly(makeEllipsePts(p.x, p.y, 2.5, 2.5, 8), PAL.pinkBase, 245);
  }

  // 5. Render Dent #2 (Upper-left impact dent & bare steel scuff)
  drawDentAndScuff(tier, DENTS.tier2[0], PAL.greenDeep);

  // 6. Glossy Enamel Specular Streaks across Tier 2
  drawTierSpecularStreaks(tier, -0.34, 0.42);
}

// ---------------------------------------------------------------------------
// 7. TIER 1 (Top): Saffron + Mughal Arcade, Lotuses & Chamfers
// ---------------------------------------------------------------------------
function drawTier1SaffronArcade(tier) {
  // 1. Glossy Saffron / Marigold cylindrical base
  drawCylinderBaseAndShading(
    tier,
    PAL.saffronBase,
    PAL.saffronLit,
    PAL.saffronBright,
    PAL.saffronDark,
    PAL.saffronDeep
  );

  // 2. Top & Bottom Borders in Parrot Green, Turquoise & Crimson
  drawTierBand(tier, 0.05, 0.10, PAL.turqBase, PAL.turqBright, PAL.turqDark, PAL.turqDeep);
  drawTierBand(tier, 0.10, 0.145, PAL.redBase, PAL.redLit, PAL.redDark, PAL.redDeep);
  drawTierBand(tier, 0.855, 0.90, PAL.redBase, PAL.redLit, PAL.redDark, PAL.redDeep);
  drawTierBand(tier, 0.90, 0.95, PAL.greenBase, PAL.greenBright, PAL.greenDark, PAL.greenDeep);

  drawTierBeadRow(tier, 0.165, 26, PAL.earthCream, 2.6);
  drawTierBeadRow(tier, 0.835, 26, PAL.earthCream, 2.6);

  // 3. Five Pointed Mughal Arches across the Saffron Tier
  let numArches = 5;
  for (let i = 0; i < numArches; i++) {
    let uL = lerp(-0.90, 0.90, i / numArches) + 0.02;
    let uR = lerp(-0.90, 0.90, (i + 1) / numArches) - 0.02;
    let uM = (uL + uR) * 0.5;

    let archCoords = [
      [uL, 0.79],
      [uL, 0.44],
      [lerp(uL, uM, 0.45), 0.30],
      [uM, 0.21],
      [lerp(uR, uM, 0.45), 0.30],
      [uR, 0.44],
      [uR, 0.79]
    ];
    let archPts = archCoords.map((c) => {
      let p = mapTierPt(tier, c[0], c[1]);
      return [p.x, p.y];
    });

    let pMid = mapTierPt(tier, uM, 0.5);
    let isTurq = (i % 2 === 0);
    let aCol = shadeCylinderCol(
      isTurq ? PAL.turqBase : PAL.redBase,
      isTurq ? PAL.turqLit : PAL.redLit,
      isTurq ? PAL.turqDark : PAL.redDark,
      isTurq ? PAL.turqDeep : PAL.redDeep,
      uM,
      pMid.normShift
    );
    washPoly(archPts, aCol, 248);

    // Cream & Parrot Green arch outline
    let outCol = shadeCylinderCol(PAL.earthCream, "#FFFFFF", PAL.earthSand, PAL.earthOchre, uM, pMid.normShift);
    strokePoly(archPts, "rigger", outCol, 0.85, true);

    // Hand-painted Lotus Blossom inside each arch
    let pLotus = mapTierPt(tier, uM, 0.54);
    let hScale = Math.sqrt(Math.max(0.2, 1 - uM * uM));
    let petalCol = shadeCylinderCol(
      isTurq ? PAL.pinkLit : PAL.saffronBright,
      "#FFFFFF",
      isTurq ? PAL.pinkBase : PAL.saffronBase,
      isTurq ? PAL.pinkDark : PAL.saffronDark,
      uM,
      pMid.normShift
    );

    // 5 lotus petals
    for (let k = -2; k <= 2; k++) {
      let ang = -90 + k * 28;
      let px = pLotus.x + 18 * hScale * cos(ang);
      let py = pLotus.y + 18 * sin(ang);
      let sx1 = pLotus.x + 10 * hScale * cos(ang - 18);
      let sy1 = pLotus.y + 10 * sin(ang - 18);
      let sx2 = pLotus.x + 10 * hScale * cos(ang + 18);
      let sy2 = pLotus.y + 10 * sin(ang + 18);
      washPoly([[pLotus.x, pLotus.y + 6], [sx1, sy1], [px, py], [sx2, sy2]], petalCol, 250);
      strokePoly([[pLotus.x, pLotus.y + 6], [sx1, sy1], [px, py], [sx2, sy2]], "rotring", "#1C0E0A", 0.6, true);
    }
    // Lotus stem & emerald base leaves
    let pStemBot = mapTierPt(tier, uM, 0.76);
    let leafCol = shadeCylinderCol(PAL.greenLit, PAL.greenBright, PAL.greenBase, PAL.greenDark, uM, pMid.normShift);
    strokeLine(pLotus.x, pLotus.y + 6, pStemBot.x, pStemBot.y, "rigger", leafCol, 0.8);
    washPoly(makeEllipsePts(pLotus.x - 9 * hScale, pLotus.y + 12, 7 * hScale, 3.5, 8), leafCol, 245);
    washPoly(makeEllipsePts(pLotus.x + 9 * hScale, pLotus.y + 12, 7 * hScale, 3.5, 8), leafCol, 245);
  }

  // 4. Dent & Utensil/Latch Scuffs on Tier 1
  drawDentAndScuff(tier, DENTS.tier1[0], PAL.saffronDeep);

  // Extra bare steel scuffs near top-left rim (u = -0.62, v = 0.08)
  let pS1 = mapTierPt(tier, -0.68, 0.07);
  let pS2 = mapTierPt(tier, -0.54, 0.09);
  washPoly([
    [pS1.x, pS1.y - 3],
    [pS2.x, pS2.y - 3],
    [pS2.x, pS2.y + 5],
    [pS1.x, pS1.y + 5]
  ], PAL.steelMid, 250);
  strokeLine(pS1.x, pS1.y, pS2.x, pS2.y, "specular", PAL.steelSpec, 0.85);

  // 5. Glossy Enamel Specular Streaks across Tier 1
  drawTierSpecularStreaks(tier, -0.34, 0.42);
}

// ---------------------------------------------------------------------------
// 8. Domed Lid & Top Handle
// ---------------------------------------------------------------------------
function drawDomedLidAndHandle() {
  const cx = 600;
  // 1. Overhanging Lower Lid Skirt Rim at y = 290 (rx = 218, ry = 25)
  drawRolledSteelRim(cx, 290, 218, 25, 14, PAL.saffronBase, PAL.redBase, 0.18);

  // 2. Cylindrical Lid Collar (y = 258 to 286, rx = 212, ry = 23)
  let collarTier = {
    cx: 600,
    yTop: 256,
    yBot: 286,
    rxTop: 206,
    rxBot: 212,
    ryTop: 20,
    ryBot: 24,
    dents: []
  };
  drawCylinderBaseAndShading(collarTier, PAL.redBase, PAL.redLit, PAL.redHot, PAL.redDark, PAL.redDeep);
  drawTierBeadRow(collarTier, 0.52, 28, PAL.saffronBright, 3.0);
  drawTierSpecularStreaks(collarTier, -0.34, 0.42);

  // Stepped steel shoulder bead at y = 256
  drawRolledSteelRim(cx, 256, 208, 21, 9, PAL.redBase, PAL.turqBase, 0.77);

  // 3. Domed Crown (y = 210 to 254, rx tapers from 204 to 136)
  // Painted in radiating rickshaw petal gadroons (Candy-Apple Red, Parrot Green, Saffron, Turquoise)
  let gadroons = 18;
  let gadCols = [
    [PAL.redBase, PAL.redLit, PAL.redDark, PAL.redDeep],
    [PAL.saffronBase, PAL.saffronBright, PAL.saffronDark, PAL.saffronDeep],
    [PAL.greenBase, PAL.greenBright, PAL.greenDark, PAL.greenDeep],
    [PAL.turqBase, PAL.turqBright, PAL.turqDark, PAL.turqDeep]
  ];

  for (let i = 0; i < gadroons; i++) {
    let u1 = lerp(-1, 1, i / gadroons);
    let u2 = lerp(-1, 1, (i + 1.02) / gadroons);
    let um = (u1 + u2) * 0.5;
    let s1 = Math.sqrt(Math.max(0, 1 - u1 * u1));
    let s2 = Math.sqrt(Math.max(0, 1 - u2 * u2));
    let sm = Math.sqrt(Math.max(0, 1 - um * um));

    let cSet = gadCols[i % gadCols.length];
    let col = shadeCylinderCol(cSet[0], cSet[1], cSet[2], cSet[3], um);

    let pts = [
      [cx + u1 * 136, 212 + 13 * s1],
      [cx + u2 * 136, 212 + 13 * s2],
      [cx + u2 * 178, 230 + 17 * s2],
      [cx + u2 * 204, 254 + 20 * s2],
      [cx + u1 * 204, 254 + 20 * s1],
      [cx + u1 * 178, 230 + 17 * s1]
    ];
    washPoly(pts, col, 250);
    strokeLine(
      cx + u1 * 136,
      212 + 13 * s1,
      cx + u1 * 204,
      254 + 20 * s1,
      "rotring",
      "#1E130E",
      0.75
    );
    // Cream dot inside each gadroon
    let dotCol = shadeCylinderCol(PAL.earthCream, "#FFFFFF", PAL.earthSand, PAL.earthUmber, um);
    washPoly(makeEllipsePts(cx + um * 176, 236 + 17 * sm, 3.2 * sm, 3.2, 8), dotCol, 240);
  }

  // Dome specular highlight flare at u = -0.34
  let domeSpec = [
    [cx - 0.34 * 136, 212 + 13 * 0.94],
    [cx - 0.34 * 178, 230 + 17 * 0.94],
    [cx - 0.34 * 204, 254 + 20 * 0.94]
  ];
  strokeSpline(domeSpec, "specular", "#FFFFFF", 1.35, 0.3);

  // 4. Top Stainless Steel Crown Plateau (cx = 600, cy = 212, rx = 136, ry = 14)
  washPoly(makeEllipsePts(cx, 212, 138, 15, 36), PAL.steelDark, 255);
  washPoly(makeEllipsePts(cx, 211, 134, 13.5, 36), PAL.steelMid, 255);

  // Concentric brushed steel reflection wedges on top plateau
  washPoly([
    [cx, 211],
    [cx - 128, 208],
    [cx - 85, 198],
    [cx - 25, 197]
  ], PAL.steelBright, 240);
  washPoly([
    [cx, 211],
    [cx - 75, 222],
    [cx - 15, 224],
    [cx + 35, 223]
  ], PAL.steelSpec, 245);
  washPoly([
    [cx, 211],
    [cx + 45, 199],
    [cx + 125, 206],
    [cx + 95, 220]
  ], PAL.steelDark, 230);

  // Inner stamped steel ring on top lid
  strokePoly(makeEllipsePts(cx, 211, 135, 14, 36), "rotring", "#1A1E22", 0.95, true);
  strokePoly(makeEllipsePts(cx, 211, 92, 9.5, 32), "rotring", PAL.steelDark, 0.85, true);
  strokePoly(makeEllipsePts(cx, 210, 90, 9.0, 32), "specular", PAL.steelSpec, 0.7, true);

  // 5. Top Handle Brackets, Wire Bail & Painted Grip
  // Shadow of handle on steel plateau
  washPoly([[490, 212], [710, 212], [695, 218], [505, 218]], "#1F2429", 180);

  // Left & Right riveted omega brackets (x = 492 and x = 708)
  for (let bx of [494, 706]) {
    washPoly([[bx - 18, 204], [bx + 18, 204], [bx + 22, 215], [bx - 22, 215]], PAL.steelDark, 255);
    washPoly([[bx - 12, 192], [bx + 12, 192], [bx + 14, 213], [bx - 14, 213]], PAL.steelLit, 255);
    strokeLine(bx - 10, 194, bx + 8, 194, "specular", PAL.steelSpec, 0.8);
    strokePoly([[bx - 18, 204], [bx + 18, 204], [bx + 22, 215], [bx - 22, 215]], "rotring", "#14181C", 0.7, true);
  }

  // Heavy bent steel wire handle bail
  let bailOuter = [
    [494, 204],
    [494, 160],
    [512, 146],
    [688, 146],
    [706, 160],
    [706, 204]
  ];
  strokePoly(bailOuter, "enamel", PAL.steelDark, 2.2, false, 0.15);
  strokePoly(bailOuter, "enamel", PAL.steelLit, 1.3, false, 0.15);
  strokeLine(492, 198, 492, 162, "specular", PAL.steelSpec, 0.85);
  strokeLine(510, 144, 680, 144, "specular", PAL.steelSpec, 0.85);

  // Central Grip Tube (x = 532 to 668, y = 134 to 158) - Chipped Saffron & Candy-Apple Red
  washPoly([[532, 135], [668, 135], [668, 157], [532, 157]], PAL.redDark, 255);
  washPoly([[532, 135], [668, 135], [668, 148], [532, 148]], PAL.redBase, 255);
  // Decorative saffron bands on grip
  for (let gx of [546, 592, 638]) {
    washPoly([[gx, 135], [gx + 16, 135], [gx + 16, 157], [gx, 157]], PAL.saffronLit, 250);
  }
  // Scuffed bare steel wear in center of grip where fingers hold it
  washPoly([[572, 136], [590, 136], [588, 150], [570, 150]], PAL.steelMid, 245);
  strokeLine(534, 139, 666, 139, "specular", "#FFFFFF", 0.95);
  strokePoly([[532, 135], [668, 135], [668, 157], [532, 157]], "rotring", "#1A0D0A", 0.85, true);
}

// ---------------------------------------------------------------------------
// 9. Right Locking Strap & Front-Right Hinged Latch Assembly
// ---------------------------------------------------------------------------
function drawRightStrapAndFrontLatch(tier1, tier2, tier3) {
  // Part A: Right-side vertical steel locking frame (x = 816..848, y = 255..940)
  washPoly([[810, 260], [852, 260], [848, 942], [806, 942]], "#120B08", 220);
  washPoly([[816, 258], [842, 258], [838, 938], [812, 938]], PAL.steelDark, 255);
  washPoly([[818, 258], [830, 258], [826, 938], [814, 938]], PAL.steelMid, 250);
  strokeLine(818, 260, 814, 936, "enamel", PAL.steelLit, 0.8);
  strokeLine(838, 260, 834, 936, "rotring", PAL.earthOchre, 0.65);

  let loopYs = [288, 492, 714, 922];
  for (let ly of loopYs) {
    washPoly([[808, ly - 10], [852, ly - 12], [852, ly + 8], [808, ly + 10]], PAL.steelDark, 255);
    washPoly([[810, ly - 6], [850, ly - 8], [850, ly + 4], [810, ly + 6]], PAL.steelMid, 250);
    strokeLine(812, ly - 4, 848, ly - 6, "specular", PAL.steelBright, 0.65);
  }

  // Part B: Prominent Front-Right Eccentric Clamping Latch Assembly (x ≈ 705..772, y ≈ 428..565)
  // This latch bridges the seam between Tier 1 (Saffron), the Steel Rim (y=494), and Tier 2 (Parrot Green)
  const lx = 738;
  const ly = 498;

  // Cast shadow of the heavy latch assembly onto the cylinders
  washPoly([
    [lx - 26, 434],
    [lx + 34, 438],
    [lx + 36, 568],
    [lx - 24, 562]
  ], "#0F0906", 220);

  // Upper mounting plate riveted to Tier 1 (y = 430..484)
  washPoly([
    [lx - 22, 430],
    [lx + 24, 433],
    [lx + 24, 484],
    [lx - 22, 481]
  ], PAL.steelDark, 255);
  washPoly([
    [lx - 19, 433],
    [lx + 18, 436],
    [lx + 18, 481],
    [lx - 19, 478]
  ], PAL.steelMid, 255);
  // Specular glint on left bevel of upper plate
  strokeLine(lx - 18, 434, lx - 18, 478, "specular", PAL.steelBright, 0.9);
  strokePoly([
    [lx - 22, 430],
    [lx + 24, 433],
    [lx + 24, 484],
    [lx - 22, 481]
  ], "rotring", "#14181C", 0.85, true);

  // Two rivets on upper plate
  for (let rx of [lx - 10, lx + 10]) {
    washPoly(makeEllipsePts(rx, 448, 4.5, 4.5, 10), PAL.steelDark, 255);
    washPoly(makeEllipsePts(rx - 0.8, 447, 3.2, 3.2, 8), PAL.steelBright, 250);
