// ============================================================================
// SAFE GEOMETRY & BRUSH HELPERS
// ============================================================================

function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) < 0.6) return;
  brush.line(x1, y1, x2, y2);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let cleaned = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = cleaned[cleaned.length - 1];
    if (dist(pts[i][0], pts[i][1], prev[0], prev[1]) > 1.2) {
      cleaned.push(pts[i]);
    }
  }
  if (cleaned.length === 2) {
    safeLine(cleaned[0][0], cleaned[0][1], cleaned[1][0], cleaned[1][1]);
  } else if (cleaned.length >= 3) {
    brush.spline(cleaned, curvature);
  }
}

function lerpPt(a, b, t) {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t)];
}

function evalCatmullRom(pts, t) {
  let n = pts.length - 1;
  let f = constrain(t, 0, 0.999999) * n;
  let i = Math.floor(f);
  let u = f - i;
  let p0 = pts[Math.max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[Math.min(n, i + 1)];
  let p3 = pts[Math.min(n, i + 2)];

  let u2 = u * u;
  let u3 = u2 * u;

  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * u +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * u +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3
  );
  return [x, y];
}

// ============================================================================
// 1. THE DARK CARVER'S WORKBENCH
// ============================================================================

function drawWorkbench() {
  brush.noField();

  // Base charcoal marker & wash passes across the three horizontal plank zones
  // Top plank: 0..215, Main plank: 222..978, Bottom plank: 985..1200
  const plankZones = [
    { y0: 0, y1: 215, seed: 10 },
    { y0: 222, y1: 978, seed: 20 },
    { y0: 985, y1: 1200, seed: 30 }
  ];

  // Subtle dark tonal variations
  for (let z of plankZones) {
    for (let y = z.y0 + 8; y < z.y1 - 6; y += 14) {
      let n = noise(y * 0.015, z.seed);
      let col = n > 0.58 ? PAL.benchMid : (n < 0.35 ? PAL.benchDeep : PAL.benchDark);
      brush.set("marker", col, random(2.2, 4.0));
      let yWave = y + (noise(y * 0.02, z.seed + 5) - 0.5) * 10;
      safeLine(-10, yWave, 1210, yWave + random(-4, 4));
    }
  }

  // Subtle warm kōkōwai (red ochre) rubbed stain along the central horizontal carving band
  // Echoing the red-ochre ground of painted rafter patterns (kōwhaiwhai)
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.3);

  const ochreBays = [
    [130, 560, 290, 220],
    [410, 410, 270, 210],
    [660, 580, 290, 220],
    [890, 400, 240, 200],
    [260, 360, 220, 140],
    [550, 740, 240, 140]
  ];
  for (let b of ochreBays) {
    brush.fill(PAL.ochreDark, 48);
    brush.rect(b[0], b[1], b[2], b[3], "center");
  }
  for (let b of ochreBays) {
    brush.fill(PAL.ochreDeep, 28);
    brush.circle(b[0] + random(-20, 20), b[1] + random(-15, 15), b[2] * 0.42, 0.35);
  }
  brush.noFill();

  // Horizontal wood grain lines and cathedral heartwood arches on the dark bench
  for (let z of plankZones) {
    let numLines = Math.floor((z.y1 - z.y0) * 0.45);
    for (let i = 0; i < numLines; i++) {
      let yBase = map(i, 0, numLines, z.y0 + 3, z.y1 - 3);
      let isDark = i % 2 === 0;
      let col = isDark ? PAL.crevice : (i % 5 === 0 ? PAL.benchWarm : PAL.benchMid);
      let w = isDark ? random(0.4, 0.85) : random(0.3, 0.65);
      brush.set("2H", col, w);

      let pts = [];
      for (let x = 0; x <= 1200; x += 60) {
        // Cathedral arch distortion around two knots/centers per plank
        let k1 = exp(-pow((x - 380) / 220, 2)) * sin((yBase - z.y0) * 0.8) * 14;
        let k2 = exp(-pow((x - 860) / 260, 2)) * cos((yBase - z.y0) * 0.7) * 16;
        let ny = yBase + k1 + k2 + (noise(x * 0.006, yBase * 0.015) - 0.5) * 14;
        ny = constrain(ny, z.y0 + 2, z.y1 - 2);
        pts.push([x, ny, random(0.5, 1.1)]);
      }
      safeSpline(pts, 0.4);
    }
  }

  // Deep horizontal plank seams at y = 218 and y = 981
  const seamYs = [218, 981];
  for (let sy of seamYs) {
    brush.set("marker", PAL.crevice, 2.2);
    safeLine(0, sy, 1200, sy);
    brush.set("rotring", PAL.crevice, 1.4);
    safeLine(0, sy - 2, 1200, sy - 2);
    safeLine(0, sy + 2, 1200, sy + 2);

    // Worn chamfer highlight along plank edge
    brush.set("2H", PAL.boneDeep, 0.55);
    for (let x = 20; x < 1180; x += random(45, 90)) {
      let len = random(25, 65);
      safeLine(x, sy + 5, x + len, sy + 5 + random(-0.5, 0.5));
    }

    // Fine ochre & bone sawdust caught inside the plank seam crack
    for (let x = 60; x < 1140; x += random(8, 22)) {
      let inBand = exp(-pow((x - 600) / 480, 2));
      if (random() < inBand * 0.75) {
        let dustCol = random() < 0.45 ? PAL.ochrePink : PAL.boneMid;
        brush.set("rotring", dustCol, random(0.45, 0.9));
        safeLine(x, sy + random(-1.5, 1.5), x + random(3, 10), sy + random(-1.5, 1.5));
      }
    }
  }

  // Old carver's test gouge marks and faint chalk rafter-rhythm arcs on the bench
  for (let i = 0; i < 42; i++) {
    let gx = random(60, 1140);
    let gy = random() < 0.78 ? random(250, 950) : random(40, 1160);
    let ang = random(-35, 35);
    let len = random(14, 34);
    let dx = cos(ang) * len;
    let dy = sin(ang) * len;
    brush.set("rotring", PAL.crevice, random(0.6, 1.1));
    safeLine(gx, gy, gx + dx, gy + dy);
    brush.set("2H", PAL.benchWarm, 0.5);
    safeLine(gx, gy + 1.8, gx + dx, gy + dy + 1.8);
  }
}

