// Generate a sweeping undulating ribbon wave and slice into 3D segments
function addWaveRibbon(cfg) {
  let path = [];
  for (let i = 0; i <= cfg.steps; i++) {
    let t = i / cfg.steps;
    let p = evalCatmullRom(cfg.pts, t);
    // Subtle organic wood-fiber wobble
    let wobX = (noise(t * 6, cfg.id * 13) - 0.5) * 8;
    let wobY = (noise(t * 6, cfg.id * 13 + 7) - 0.5) * 8;
    let z = cfg.zProfile(t);
    let tilt = cfg.tiltProfile(t) + sin(t * 360 * cfg.twistRate + cfg.twistPhase) * 26;
    let w = cfg.baseWidth * (0.86 + 0.24 * sin(t * 180));
    path.push({
      x: p[0] + wobX,
      y: p[1] + wobY,
      z: z,
      w: w,
      tilt: tilt,
      t: t
    });
  }
  discretizeRibbonPath(path, cfg);
}

// Generate a Koru spiral shaving (smooth stem transitioning into a multi-turn spiral with inner koru bulb)
function addKoruShaving(cfg) {
  let rawPts = [];
  let spiralSteps = Math.floor(Math.abs(cfg.turns) * 42);
  let totalDeg = cfg.turns * 360;
  let dir = cfg.turns >= 0 ? 1 : -1;

  // Compute spiral points
  let spiralPts = [];
  for (let i = 0; i <= spiralSteps; i++) {
    let s = i / spiralSteps;
    // Non-linear angle progression (tighter rotation near inner bulb)
    let ang = cfg.startAngle + totalDeg * pow(s, 0.94);

    // Radius tapers smoothly, then forms the characteristic rounded koru bulb at s > 0.86
    let rBase = lerp(cfg.rStart, cfg.rEnd, pow(s, 0.82));
    let bulbSwell = 0;
    if (s > 0.84) {
      let bs = (s - 0.84) / 0.16;
      bulbSwell = sin(bs * 180) * (cfg.rEnd * 0.34);
    }
    // Slight elliptical aspect echoing painted rafter koru proportions
    let r = rBase + bulbSwell;
    let wob = (noise(s * 8, cfg.id * 19) - 0.5) * (r * 0.08);
    let rx = (r + wob) * 1.04;
    let ry = (r + wob) * 0.96;

    // Spiral center drifts slightly upward/inward with 3D cone height
    let z = lerp(cfg.zBase, cfg.zPeak, pow(s, 0.75));
    let cxShift = cfg.cx + (z - cfg.zBase) * (cfg.coneTiltX || -0.22);
    let cyShift = cfg.cy + (z - cfg.zBase) * (cfg.coneTiltY || -0.34);

    let px = cxShift + cos(ang) * rx;
    let py = cyShift + sin(ang) * ry;
    spiralPts.push([px, py, z, s]);
  }

  // Combine stem points (if any) with the spiral start for a C2-continuous ribbon
  let controlPts = [];
  if (cfg.stemPts && cfg.stemPts.length > 0) {
    for (let sp of cfg.stemPts) controlPts.push([sp[0], sp[1]]);
  }
  // Sample key points from spiralPts for smooth Catmull-Rom transition near stem
  let joinCount = cfg.stemPts ? cfg.stemPts.length : 0;
  if (joinCount > 0) {
    let bridgePts = [...cfg.stemPts, [spiralPts[0][0], spiralPts[0][1]], [spiralPts[4][0], spiralPts[4][1]], [spiralPts[8][0], spiralPts[8][1]]];
    let stemSteps = joinCount * 16;
    for (let i = 0; i < stemSteps; i++) {
      let u = (i / stemSteps) * ((bridgePts.length - 2.2) / (bridgePts.length - 1));
      let p = evalCatmullRom(bridgePts, u);
      let sNorm = (i / stemSteps) * 0.15;
      let z = lerp(cfg.zBase * 0.5, cfg.zBase, i / stemSteps);
      rawPts.push({
        x: p[0],
        y: p[1],
        z: z,
        s: sNorm
      });
    }
    // Append rest of spiral from index 5 onward
    for (let i = 5; i < spiralPts.length; i++) {
      let sp = spiralPts[i];
      let sNorm = 0.15 + sp[3] * 0.85;
      rawPts.push({ x: sp[0], y: sp[1], z: sp[2], s: sNorm });
    }
  } else {
    for (let sp of spiralPts) {
      rawPts.push({ x: sp[0], y: sp[1], z: sp[2], s: sp[3] });
    }
  }

  // Smooth the combined path with 2 passes of local averaging so stem-to-spiral join is seamless
  for (let pass = 0; pass < 3; pass++) {
    for (let i = 1; i < rawPts.length - 1; i++) {
      rawPts[i].x = 0.25 * rawPts[i - 1].x + 0.5 * rawPts[i].x + 0.25 * rawPts[i + 1].x;
      rawPts[i].y = 0.25 * rawPts[i - 1].y + 0.5 * rawPts[i].y + 0.25 * rawPts[i + 1].y;
      rawPts[i].z = 0.25 * rawPts[i - 1].z + 0.5 * rawPts[i].z + 0.25 * rawPts[i + 1].z;
    }
  }

  // Assign width and 3D conical tilt along the path
  let path = [];
  for (let i = 0; i < rawPts.length; i++) {
    let pt = rawPts[i];
    let t = i / (rawPts.length - 1);
    // Ribbon stands up steeper as it coils into the koru center
    // and flares slightly at the inner koru bulb
    let bulbFlare = t > 0.86 ? sin(((t - 0.86) / 0.14) * 180) * 0.28 : 0;
    let w = cfg.baseWidth * (lerp(1.02, 0.62, pow(t, 0.7)) + bulbFlare);
    let tilt = dir * lerp(38, 72, pow(t, 0.65));
    path.push({
      x: pt.x,
      y: pt.y,
      z: pt.z,
      w: w,
      tilt: tilt,
      t: t
    });
  }

  discretizeRibbonPath(path, {
    ...cfg,
    featherL: true,
    featherR: true
  });
}

// Convert a 3D ribbon path into 3D-projected quad segments for back-to-front Painter's rendering
function discretizeRibbonPath(path, cfg) {
  let rings = [];

  for (let i = 0; i < path.length; i++) {
    let pPrev = path[Math.max(0, i - 1)];
    let pNext = path[Math.min(path.length - 1, i + 1)];
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let len = Math.hypot(dx, dy) || 1;
    let tx = dx / len;
    let ty = dy / len;
    // 2D normal perpendicular to tangent
    let nx = -ty;
    let ny = tx;

    let pt = path[i];
    let t = pt.t;

    // 3D cross-section vector of the ribbon:
    // Horizontal spread across normal = w * cos(tilt)
    // Vertical 3D rise = w * sin(|tilt|)
    let halfW = pt.w * 0.5;
    let cosT = cos(pt.tilt);
    let sinT = sin(Math.abs(pt.tilt));

    // Oblique top-down camera relief vector for vertical height Z
    let liftX = -0.34 * halfW * sinT;
    let liftY = -0.50 * halfW * sinT;

    let spreadX = nx * halfW * cosT + liftX;
    let spreadY = ny * halfW * cosT + liftY;

    // Feathered organic edge modulation where the shaving thins out
    let nL = (noise(t * 18, cfg.id * 31) - 0.35) * (pt.w * 0.11);
    let nR = (noise(t * 18, cfg.id * 31 + 17) - 0.35) * (pt.w * 0.11);

    // Chiseled bevel ends at t near 0 or 1
    let endTrimL = 0;
    let endTrimR = 0;
    if (t < 0.03) {
      endTrimL = (0.03 - t) * 140;
    } else if (t > 0.96) {
      endTrimR = (t - 0.96) * 90;
    }

    let xL = pt.x - spreadX * (1 + nL / pt.w) + tx * endTrimL;
    let yL = pt.y - spreadY * (1 + nL / pt.w) + ty * endTrimL;
    let zL = pt.z - halfW * sinT * 0.45;

    let xR = pt.x + spreadX * (1 + nR / pt.w) - tx * endTrimR;
    let yR = pt.y + spreadY * (1 + nR / pt.w) - ty * endTrimR;
    let zR = pt.z + halfW * sinT * 0.55;

    // 3D surface normal lighting calculation (light from upper-left-front)
    // Normal in 2D screen plane is (nx * sign(cosT), ny * sign(cosT)) blended with Z-up
    let surfNx = nx * cosT - 0.25 * sinT;
    let surfNy = ny * cosT - 0.35 * sinT;
    let surfNz = Math.abs(cosT) * 0.75 + 0.25;
    let sLen = Math.hypot(surfNx, surfNy, surfNz) || 1;
    surfNx /= sLen;
    surfNy /= sLen;
    surfNz /= sLen;

    // Light vector from top-left (-0.48, -0.58, 0.66)
    let dotL = surfNx * (-0.48) + surfNy * (-0.58) + surfNz * 0.66;
    let lightVal = constrain(map(dotL, -0.55, 0.88, 0.06, 1.0), 0.05, 1.0);

    rings.push({
      cx: pt.x,
      cy: pt.y,
      cz: pt.z,
      xL, yL, zL,
      xR, yR, zR,
      tx, ty, nx, ny,
      w: pt.w,
      t: t,
      light: lightVal,
      cosT: cosT
    });
  }

  shavingCurves.push({ rings, cfg });

  for (let i = 0; i < rings.length - 1; i++) {
    let r0 = rings[i];
    let r1 = rings[i + 1];
    let zAvg = 0.5 * (r0.cz + r1.cz) + 0.12 * Math.abs(r0.cosT) * 10;

    allSegments.push({
      r0,
      r1,
      zSort: zAvg,
      cfg,
      segIdx: i,
      totalSegs: rings.length - 1,
      occlusion: 0
    });
  }
}

// ============================================================================
// 3. BENCH CAST SHADOWS & TRANSLUCENT OCHRE-PINK FEATHER WASHES
// ============================================================================

function drawBenchCastShadowsAndFeathers() {
  brush.noField();

  // Pass 1: Deep charcoal cast shadows under all shavings onto the workbench
  for (let sc of shavingCurves) {
    let rings = sc.rings;
    for (let i = 0; i < rings.length - 1; i += 2) {
      let r0 = rings[i];
      let r1 = rings[Math.min(rings.length - 1, i + 2)];
      let shOffX = 8 + r0.cz * 0.34;
      let shOffY = 12 + r0.cz * 0.48;

      let sx0 = r0.cx + shOffX;
      let sy0 = r0.cy + shOffY;
      let sx1 = r1.cx + shOffX;
      let sy1 = r1.cy + shOffY;

      let wShadow = map(r0.w, 14, 68, 1.4, 4.8);
      brush.set("marker", PAL.crevice, wShadow);
      safeLine(sx0, sy0, sx1, sy1);

      // Soft outer penumbra
      brush.set("charcoal", PAL.benchDeep, wShadow * 0.9);
      safeLine(sx0 + 4, sy0 + 5, sx1 + 4, sy1 + 5);
    }
  }

  // Pass 2: Translucent Tōtara Ochre-Pink feather washes where shavings thin out at edges
  // Grouped by color for fast p5.brush fill caching
  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.35);

  for (let sc of shavingCurves) {
    let rings = sc.rings;
    let step = 6;
    for (let i = 0; i < rings.length - step; i += step) {
      let rA = rings[i];
      let rB = rings[i + Math.floor(step / 2)];
      let rC = rings[i + step];

      // Thin outer translucent skirt along Left & Right margins
      let flare = 1.18;
      let pL0 = [lerp(rA.cx, rA.xL, flare), lerp(rA.cy, rA.yL, flare)];
      let pL1 = [lerp(rB.cx, rB.xL, flare + 0.08), lerp(rB.cy, rB.yL, flare + 0.08)];
      let pL2 = [lerp(rC.cx, rC.xL, flare), lerp(rC.cy, rC.yL, flare)];
      let pIn2 = [lerp(rC.cx, rC.xL, 0.55), lerp(rC.cy, rC.yL, 0.55)];
      let pIn0 = [lerp(rA.cx, rA.xL, 0.55), lerp(rA.cy, rA.yL, 0.55)];

      if (dist(pL0[0], pL0[1], pL2[0], pL2[1]) > 8) {
        brush.fill(PAL.ochreRed, 58);
        brush.beginShape(0.2);
        brush.vertex(pL0[0], pL0[1]);
        brush.vertex(pL1[0], pL1[1]);
        brush.vertex(pL2[0], pL2[1]);
        brush.vertex(pIn2[0], pIn2[1]);
        brush.vertex(pIn0[0], pIn0[1]);
        brush.endShape(true);
      }

      let pR0 = [lerp(rA.cx, rA.xR, flare), lerp(rA.cy, rA.yR, flare)];
      let pR1 = [lerp(rB.cx, rB.xR, flare + 0.08), lerp(rB.cy, rB.yR, flare + 0.08)];
      let pR2 = [lerp(rC.cx, rC.xR, flare), lerp(rC.cy, rC.yR, flare)];
      let pInR2 = [lerp(rC.cx, rC.xR, 0.55), lerp(rC.cy, rC.yR, 0.55)];
      let pInR0 = [lerp(rA.cx, rA.xR, 0.55), lerp(rA.cy, rA.yR, 0.55)];

      if (dist(pR0[0], pR0[1], pR2[0], pR2[1]) > 8) {
        brush.fill(PAL.ochrePink, 52);
        brush.beginShape(0.2);
        brush.vertex(pR0[0], pR0[1]);
        brush.vertex(pR1[0], pR1[1]);
        brush.vertex(pR2[0], pR2[1]);
        brush.vertex(pInR2[0], pInR2[1]);
        brush.vertex(pInR0[0], pInR0[1]);
        brush.endShape(true);
      }
    }
  }
  brush.noFill();
}

// ============================================================================
// 4. THE WHITE-HANDLED CARVER'S CHISEL
// ============================================================================

function drawCarversChisel() {
  // Chisel axis from cutting edge (885, 678) down-right at 31 degrees to (1175, 852)
  const bx = 885;
  const by = 678;
  const ang = 31;
  const ux = cos(ang);
  const uy = sin(ang);
  const nx = -uy;
  const ny = ux;

  function chiselPt(s, w) {
    return [bx + ux * s + nx * w, by + uy * s + ny * w];
  }

  // 1. Heavy Cast Shadow under Chisel Blade & Handle onto Workbench
  for (let s = 5; s < 335; s += 6) {
    let halfW = s < 95 ? map(s, 0, 95, 26, 18) : (s < 145 ? 23 : map(sin(map(s, 145, 335, 10, 170)), 0, 1, 22, 31));
    let pL = chiselPt(s, -halfW + 10);
    let pR = chiselPt(s, halfW + 18);
    brush.set("marker", PAL.crevice, 3.2);
    safeLine(pL[0] + 8, pL[1] + 14, pR[0] + 8, pR[1] + 14);
  }

  // 2. Forged Steel Blade (s = 0 to 118)
  // Solid base wash for blade
  let b0L = chiselPt(0, -26);
  let b0R = chiselPt(0, 26);
  let b1R = chiselPt(92, 19);
  let b1L = chiselPt(92, -19);

  brush.noStroke();
  brush.wash(PAL.steelDark, 245);
  brush.beginShape(0);
  brush.vertex(b0L[0], b0L[1]);
  brush.vertex(b0R[0], b0R[1]);
  brush.vertex(b1R[0], b1R[1]);
  brush.vertex(b1L[0], b1L[1]);
  brush.endShape(true);
  brush.noWash();

  // Steel blade flat shading & side bevel chamfers
  for (let v = -1; v <= 1; v += 0.1) {
    let pStart = chiselPt(17, v * 25);
    let pEnd = chiselPt(92, v * 18.5);
    let col = PAL.steelDark;
    if (v < -0.72) col = PAL.boneLight; // Top bevel chamfer catches light
    else if (v > 0.72) col = PAL.crevice; // Bottom bevel chamfer in shadow
    else if (v > 0.15 && v < 0.55) col = PAL.ochreDeep; // Warm ochre reflection from shavings
    else if (v > -0.35 && v < 0.05) col = PAL.steelMid;

    brush.set("flat_chisel", col, 1.1);
    safeLine(pStart[0], pStart[1], pEnd[0], pEnd[1]);
  }

  // Razor-sharp ground bevel at tip (s = 0 to 17)
  let bv0L = chiselPt(0, -26);
  let bv0R = chiselPt(0, 26);
  let bv1R = chiselPt(17, 25);
  let bv1L = chiselPt(17, -25);

  brush.noStroke();
  brush.wash(PAL.boneBright, 240);
  brush.beginShape(0);
  brush.vertex(bv0L[0], bv0L[1]);
  brush.vertex(bv0R[0], bv0R[1]);
  brush.vertex(bv1R[0], bv1R[1]);
  brush.vertex(bv1L[0], bv1L[1]);
  brush.endShape(true);
  brush.noWash();

  // Honing striations on the bevel & steel face
  for (let i = 0; i < 24; i++) {
    let w = map(i, 0, 23, -24, 24);
    let p0 = chiselPt(1, w);
    let p1 = chiselPt(16, w * 0.96);
    brush.set("rotring", i % 3 === 0 ? PAL.boneShadow : PAL.boneMid, 0.45);
    safeLine(p0[0], p0[1], p1[0], p1[1]);
  }
  // Diagonal grinding marks on steel flat
  for (let s = 22; s < 88; s += 4.5) {
    let p0 = chiselPt(s, -16);
    let p1 = chiselPt(s + 8, 16);
    brush.set("2H", PAL.steelLight, 0.4);
    safeLine(p0[0], p0[1], p1[0], p1[1]);
  }

  // Steel neck & bolster (s = 92 to 122)
  for (let s = 92; s <= 122; s += 2.5) {
    let hw = s < 108 ? map(s, 92, 108, 18, 11) : map(s, 108, 122, 11, 21);
    let pL = chiselPt(s, -hw);
    let pR = chiselPt(s, hw);
    let pMid = chiselPt(s, -hw * 0.35);
    brush.set("marker", PAL.crevice, 1.3);
    safeLine(pL[0], pL[1], pR[0], pR[1]);
    brush.set("marker", PAL.boneLight, 0.9);
    safeLine(pL[0], pL[1], pMid[0], pMid[1]);
  }

  // 3. Brass / Dark Iron Ferrule Collar (s = 122 to 148)
  for (let v = -1; v <= 1; v += 0.08) {
    let p0 = chiselPt(122, v * 23);
    let p1 = chiselPt(148, v * 24.5);
    let col = PAL.inkBlack;
    if (v < -0.45 && v > -0.82) col = PAL.boneBright; // Bright metallic highlight
    else if (v >= -0.45 && v < -0.1) col = PAL.boneMid;
    else if (v > 0.35 && v < 0.75) col = PAL.ochreRed; // Warm ochre bounce light
    brush.set("flat_chisel", col, 1.0);
    safeLine(p0[0], p0[1], p1[0], p1[1]);
  }

  // 4. Turned Bone-White Handle (s = 148 to 332)
  function handleHalfWidth(s) {
    let u = (s - 148) / (332 - 148);
    if (u > 0.92) {
      let du = (u - 0.92) / 0.08;
      return 27 * sqrt(Math.max(0, 1 - du * du));
    }
    return 24.5 + sin(u * 165) * 6.5;
  }

  // Base opaque wash for the bone-white handle
  brush.noStroke();
  brush.wash(PAL.boneLight, 250);
  brush.beginShape(0.2);
  for (let s = 148; s <= 332; s += 8) {
    let p = chiselPt(s, -handleHalfWidth(s));
    brush.vertex(p[0], p[1]);
  }
  for (let s = 332; s >= 148; s -= 8) {
    let p = chiselPt(s, handleHalfWidth(s));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Cylindrical shading bands along the bone-white handle
  for (let v = -0.96; v <= 0.96; v += 0.07) {
    let col = PAL.boneLight;
    if (v < -0.35 && v > -0.78) col = PAL.boneBright; // Specular crown highlight
    else if (v <= -0.78) col = PAL.boneMid; // Upper turning edge
    else if (v >= -0.35 && v < 0.15) col = PAL.boneLight;
    else if (v >= 0.15 && v < 0.52) col = PAL.boneMid;
    else if (v >= 0.52 && v < 0.82) col = PAL.boneDeep; // Core shadow
    else col = PAL.ochrePink; // Warm reflected light on bottom rim

    let pts = [];
    for (let s = 150; s <= 328; s += 10) {
      let hw = handleHalfWidth(s);
      pts.push(chiselPt(s, v * hw));
    }
    brush.set("flat_chisel", col, 1.15);
    safeSpline(pts, 0.4);
  }

  // Decorative incised red-ochre & charcoal rings turned into the bone handle
  const ringPositions = [164, 282, 290];
  for (let rs of ringPositions) {
    let hw = handleHalfWidth(rs);
    let rPts = [];
    for (let v = -0.95; v <= 0.95; v += 0.15) {
      let curveS = rs + (1 - v * v) * 5.5;
      rPts.push(chiselPt(curveS, v * hw));
    }
    brush.set("rotring", PAL.ochreDeep, 1.3);
    safeSpline(rPts, 0.5);
    brush.set("rotring", PAL.inkBlack, 0.7);
    safeSpline(rPts, 0.5);
  }

  // Fine wood/bone longitudinal grain & cross-contour cylindrical ink hatching on handle
  for (let i = 0; i < 28; i++) {
    let v = random(-0.92, 0.92);
    let s0 = random(152, 260);
    let s1 = Math.min(324, s0 + random(35, 85));
    let p0 = chiselPt(s0, v * handleHalfWidth(s0));
    let p1 = chiselPt(s1, v * handleHalfWidth(s1));
    let col = v > 0.3 ? PAL.inkCharcoal : PAL.boneShadow;
    brush.set("2H", col, 0.45);
    safeLine(p0[0], p0[1], p1[0], p1[1]);
  }

  // Cross-contour ink hatching on the shadowed lower half of the handle
  for (let s = 152; s < 324; s += 4.2) {
    let hw = handleHalfWidth(s);
    let vStart = random(0.05, 0.28);
    let hPts = [];
    for (let v = vStart; v <= 0.96; v += 0.2) {
      let curveS = s + (1 - v * v) * 5.0;
      hPts.push(chiselPt(curveS, v * hw));
    }
    brush.set("rotring", PAL.inkCharcoal, 0.48);
    safeSpline(hPts, 0.4);
  }

  // Crisp ink contour lines around the entire chisel
  brush.set("rotring", PAL.inkBlack, 1.15);
  safeLine(b0L[0], b0L[1], b0R[0], b0R[1]); // Razor tip
  safeLine(bv1L[0], bv1L[1], bv1R[0], bv1R[1]); // Bevel shoulder
  safeLine(b0L[0], b0L[1], b1L[0], b1L[1]);
  safeLine(b0R[0], b0R[1], b1R[0], b1R[1]);

  let topOutline = [];
  let botOutline = [];
  for (let s = 148; s <= 330; s += 8) {
    topOutline.push(chiselPt(s, -handleHalfWidth(s)));
    botOutline.push(chiselPt(s, handleHalfWidth(s)));
  }
  brush.set("rotring", PAL.inkBlack, 1.0);
  safeSpline(topOutline, 0.4);
  brush.set("rotring", PAL.inkBlack, 1.35);
  safeSpline(botOutline, 0.4);
}

// ============================================================================
// 5. BACK-TO-FRONT 3D RENDERING OF WOOD SHAVINGS & KORU SPIRALS
// ============================================================================

function renderSortedRibbonSegments() {
  // Compute ambient/cast occlusion between segments in 3D space
  for (let i = 0; i < allSegments.length; i++) {
    let segA = allSegments[i];
    let ax = 0.5 * (segA.r0.cx + segA.r1.cx);
    let ay = 0.5 * (segA.r0.cy + segA.r1.cy);
    let az = segA.zSort;
    let occ = 0;

    for (let j = 0; j < allSegments.length; j += 2) {
      if (i === j) continue;
      let segB = allSegments[j];
      // If segment B is higher in 3D space and casts a shadow onto segment A
      if (segB.zSort > az + 4) {
        let bx = 0.5 * (segB.r0.cx + segB.r1.cx) + (segB.zSort - az) * 0.25;
        let by = 0.5 * (segB.r0.cy + segB.r1.cy) + (segB.zSort - az) * 0.35;
        let d = Math.hypot(ax - bx, ay - by);
        let thresh = (segA.r0.w + segB.r0.w) * 0.45;
        if (d < thresh) {
          occ = Math.max(occ, map(d, 0, thresh, 0.78, 0));
        }
      } else if (segA.cfg.id === segB.cfg.id && Math.abs(segA.segIdx - segB.segIdx) > 10) {
        // Spiral crevice ambient occlusion between adjacent coils of the same koru
        let bx = 0.5 * (segB.r0.cx + segB.r1.cx);
        let by = 0.5 * (segB.r0.cy + segB.r1.cy);
        let d = Math.hypot(ax - bx, ay - by);
        let thresh = (segA.r0.w + segB.r0.w) * 0.52;
        if (d < thresh) {
          occ = Math.max(occ, map(d, 0, thresh, 0.52, 0));
        }
      }
    }
    segA.occlusion = occ;
  }

  // Sort segments from lowest Z (closest to bench) to highest Z (closest to viewer)
  allSegments.sort((a, b) => a.zSort - b.zSort);

  // Render each segment in true 3D depth order
  for (let i = 0; i < allSegments.length; i++) {
    drawSingleRibbonSegment(allSegments[i]);
  }
}

function drawSingleRibbonSegment(seg) {
  let r0 = seg.r0;
  let r1 = seg.r1;
  let cfg = seg.cfg;

  // Effective lighting after inter-coil shadow occlusion
  let effLight = constrain(r0.light * (1 - seg.occlusion * 0.72), 0.04, 1.0);

  // Projected screen width of this ribbon slice
  let projW0 = dist(r0.xL, r0.yL, r0.xR, r0.yR);
  let projW1 = dist(r1.xL, r1.yL, r1.xR, r1.yR);
  let avgProjW = 0.5 * (projW0 + projW1);

  // 1. Opaque Core Wash (occludes underlying segments cleanly where curls cross)
  if (avgProjW > 4.5) {
    let baseCol = PAL.boneLight;
    if (effLight > 0.76) baseCol = PAL.boneBright;
    else if (effLight > 0.52) baseCol = PAL.boneLight;
    else if (effLight > 0.30) baseCol = PAL.boneMid;
    else if (effLight > 0.16) baseCol = PAL.boneShadow;
    else baseCol = PAL.boneDeep;

    // Slight overlap along tangent so adjacent segments fuse seamlessly
    let padX = r0.tx * 1.8;
    let padY = r0.ty * 1.8;

    let c0L = [lerp(r0.xL, r0.xR, 0.12) - padX, lerp(r0.yL, r0.yR, 0.12) - padY];
    let c0R = [lerp(r0.xL, r0.xR, 0.88) - padX, lerp(r0.yL, r0.yR, 0.88) - padY];
    let c1R = [lerp(r1.xL, r1.xR, 0.88) + padX, lerp(r1.yL, r1.yR, 0.88) + padY];
    let c1L = [lerp(r1.xL, r1.xR, 0.12) + padX, lerp(r1.yL, r1.yR, 0.12) + padY];

    brush.noStroke();
    brush.wash(baseCol, 248);
    brush.beginShape(0);
    brush.vertex(c0L[0], c0L[1]);
    brush.vertex(c0R[0], c0R[1]);
    brush.vertex(c1R[0], c1R[1]);
    brush.vertex(c1L[0], c1L[1]);
    brush.endShape(true);
    brush.noWash();
  }

  // 2. Flat Marker Bands across width (Bone-White core + Tōtara Ochre-Pink edges)
  let numBands = constrain(Math.floor(avgProjW / 4.2), 3, 9);
  let padX = r0.tx * 2.2;
  let padY = r0.ty * 2.2;

  for (let b = 0; b <= numBands; b++) {
    let v = b / numBands;
    let x0 = lerp(r0.xL, r0.xR, v) - padX;
    let y0 = lerp(r0.yL, r0.yR, v) - padY;
    let x1 = lerp(r1.xL, r1.xR, v) + padX;
    let y1 = lerp(r1.yL, r1.yR, v) + padY;

    // Cylindrical curvature across width v in [0, 1]
    let cylShade = sin(v * 180); // 1 in center, 0 at edges
    let localL = effLight * (0.68 + 0.32 * cylShade);

    let edgeL = cfg.ochreEdgeL || 0.25;
    let edgeR = cfg.ochreEdgeR || 0.25;

    let col;
    if (v < edgeL) {
      // Left ochre-pink heartwood edge
      let u = v / edgeL;
      if (u < 0.45) col = localL > 0.45 ? PAL.ochreRed : PAL.ochreDeep;
      else col = localL > 0.55 ? PAL.ochrePinkLight : PAL.ochrePink;
    } else if (v > 1 - edgeR) {
      // Right ochre-pink heartwood edge
      let u = (1 - v) / edgeR;
      if (u < 0.45) col = localL > 0.45 ? PAL.ochreRed : PAL.ochreDeep;
      else col = localL > 0.55 ? PAL.ochrePinkLight : PAL.ochrePink;
    } else {
      // Bone-white sapwood core
      if (localL > 0.78) col = PAL.boneBright;
      else if (localL > 0.56) col = PAL.boneLight;
      else if (localL > 0.36) col = PAL.boneMid;
      else if (localL > 0.20) col = PAL.boneShadow;
      else col = PAL.boneDeep;
    }

    let wMarker = constrain((avgProjW / numBands) * 0.42, 0.55, 2.4);
    brush.set("flat_chisel", col, wMarker);
    safeLine(x0, y0, x1, y1);
  }

  // 3. Longitudinal Wood Grain Lines (Cathedral & spiral fiber striations)
  let grainCount = avgProjW > 22 ? 4 : (avgProjW > 10 ? 2 : 1);
  for (let g = 0; g < grainCount; g++) {
    // Follow consistent wood-fiber tracks along the shaving
    let vTrack = 0.14 + 0.72 * ((g + 0.5) / grainCount) + 0.05 * sin(r0.t * 720 + g * 90);
    vTrack = constrain(vTrack, 0.06, 0.94);

    let gx0 = lerp(r0.xL, r0.xR, vTrack);
    let gy0 = lerp(r0.yL, r0.yR, vTrack);
    let gx1 = lerp(r1.xL, r1.xR, vTrack);
    let gy1 = lerp(r1.yL, r1.yR, vTrack);

    let isEdgeGrain = vTrack < 0.28 || vTrack > 0.72;
    let gCol = isEdgeGrain
      ? (effLight > 0.45 ? PAL.ochreRed : PAL.ochreDark)
      : (effLight > 0.65 ? PAL.boneShadow : PAL.boneDeep);

    brush.set("2H", gCol, random(0.38, 0.68));
    safeLine(gx0, gy0, gx1, gy1);
  }

  // 4. Cross-Contour Ink Hatching (Builds 3D curl volume & chisel chatter texture)
  // Denser in shadow crevices and on turning edges; open on bright highlights
  if (avgProjW > 6 && (effLight < 0.72 || seg.segIdx % 2 === 0)) {
    let hatchStartV = effLight > 0.62 ? 0.0 : 0.05;
    let hatchEndV = effLight > 0.62 ? 0.34 : (effLight < 0.35 ? 0.95 : 0.62);

    let hx0 = lerp(r0.xL, r0.xR, hatchStartV);
    let hy0 = lerp(r0.yL, r0.yR, hatchStartV);
    let hx1 = lerp(r0.xL, r0.xR, hatchEndV);
    let hy1 = lerp(r0.yL, r0.yR, hatchEndV);

    let hCol = effLight < 0.28 ? PAL.inkBlack : (effLight < 0.52 ? PAL.inkCharcoal : PAL.ochreDeep);
    let hWeight = effLight < 0.32 ? 0.62 : 0.42;
    brush.set("rotring", hCol, hWeight);
    safeLine(hx0, hy0, hx1, hy1);

    // Extra cross-hatch in deep interior spiral hollows
    if (effLight < 0.32 && avgProjW > 12) {
      let mx0 = lerp(r1.xL, r1.xR, 0.15);
      let my0 = lerp(r1.yL, r1.yR, 0.15);
      let mx1 = lerp(r0.xL, r0.xR, 0.85);
      let my1 = lerp(r0.yL, r0.yR, 0.85);
      brush.set("rotring", PAL.inkBlack, 0.5);
      safeLine(mx0, my0, mx1, my1);
    }
  }

  // 5. Crisp Ink Edges & Feathered Wood Splinters
  // Left edge contour
  let edgeColL = effLight < 0.4 ? PAL.inkBlack : PAL.ochreDeep;
  let edgeWL = Math.abs(r0.cosT) < 0.35 ? 1.15 : 0.75; // Thicker ink at 3D fold turnovers
  brush.set("rotring", edgeColL, edgeWL);
  safeLine(r0.xL, r0.yL, r1.xL, r1.yL);

  // Right edge contour (upper rim catches bright bone-white edge highlight next to dark ink)
  let edgeColR = effLight > 0.6 ? PAL.inkCharcoal : PAL.inkBlack;
  let edgeWR = Math.abs(r0.cosT) < 0.35 ? 1.2 : 0.85;
  brush.set("rotring", edgeColR, edgeWR);
  safeLine(r0.xR, r0.yR, r1.xR, r1.yR);

  if (effLight > 0.55 && avgProjW > 8) {
    let hl0x = lerp(r0.xL, r0.xR, 0.92);
    let hl0y = lerp(r0.yL, r0.yR, 0.92);
    let hl1x = lerp(r1.xL, r1.xR, 0.92);
    let hl1y = lerp(r1.yL, r1.yR, 0.92);
    brush.set("rotring", PAL.boneBright, 0.65);
    safeLine(hl0x, hl0y, hl1x, hl1y);
  }

  // Occasional fine wood-fiber splinters peeling off the translucent ochre-pink edge
  if (seg.segIdx % 7 === 2 && random() < 0.65) {
    let isLeft = random() < 0.5;
    let sx = isLeft ? r0.xL : r0.xR;
    let sy = isLeft ? r0.yL : r0.yR;
    let outSign = isLeft ? -1 : 1;
    let spLen = random(8, 22);
    let ex = sx + r0.tx * spLen + r0.nx * outSign * random(2, 6);
    let ey = sy + r0.ty * spLen + r0.ny * outSign * random(2, 6);
    brush.set("rotring", random() < 0.6 ? PAL.ochrePink : PAL.boneLight, 0.45);
    safeLine(sx, sy, ex, ey);
  }

  // Chiseled bevel end-cuts at the start (segIdx === 0) and inner koru tip (segIdx === totalSegs - 1)
  if (seg.segIdx === 0 || seg.segIdx === seg.totalSegs - 1) {
    let rEnd = seg.segIdx === 0 ? r0 : r1;
    brush.set("rotring", PAL.inkBlack, 0.95);
    safeLine(rEnd.xL, rEnd.yL, rEnd.xR, rEnd.yR);
    // Tiny end-grain fibers protruding from the chiseled cut
    let dirSign = seg.segIdx === 0 ? -1 : 1;
    for (let f = 0.15; f <= 0.85; f += 0.22) {
      let fx = lerp(rEnd.xL, rEnd.xR, f);
      let fy = lerp(rEnd.yL, rEnd.yR, f);
      brush.set("rotring", f < 0.3 || f > 0.7 ? PAL.ochrePink : PAL.boneBright, 0.5);
      safeLine(fx, fy, fx + rEnd.tx * dirSign * random(3, 8), fy + rEnd.ty * dirSign * random(3, 8));
    }
  }
}

// ============================================================================
// 6. CRESCENT GOUGE CHIPS, UNAUNAHI MOTIFS & FINE SAWDUST
// ============================================================================

function drawGougeChipsAndDust() {
  // Small crescent gouge parings arranged in rhythmic trios inside the negative spaces,
  // echoing traditional unaunahi (fish-scale / crescent) rafter & carving motifs
  const chipClusters = [
    // Near the chisel cutting zone
    { x: 845, y: 675, count: 6, spread: 45 },
    { x: 945, y: 745, count: 5, spread: 48 },
    { x: 1020, y: 810, count: 4, spread: 40 },
    // Rhythmic trios in the kōwhaiwhai bays
    { x: 262, y: 615, count: 3, spread: 18 },
    { x: 480, y: 488, count: 3, spread: 18 },
    { x: 718, y: 618, count: 3, spread: 18 },
    { x: 955, y: 448, count: 3, spread: 18 },
    // Along upper & lower bench margins of the band
    { x: 185, y: 285, count: 4, spread: 38 },
    { x: 465, y: 278, count: 4, spread: 42 },
    { x: 695, y: 282, count: 4, spread: 38 },
    { x: 275, y: 885, count: 4, spread: 42 },
    { x: 505, y: 890, count: 4, spread: 45 },
    { x: 745, y: 888, count: 4, spread: 40 },
    { x: 1045, y: 495, count: 4, spread: 36 }
  ];

  for (let cl of chipClusters) {
    for (let i = 0; i < cl.count; i++) {
      let cx = cl.x + random(-cl.spread, cl.spread);
      let cy = cl.y + random(-cl.spread * 0.7, cl.spread * 0.7);
      let ang = random(0, 360);
      let len = random(10, 24);
      let wid = random(4, 9);

      let ux = cos(ang);
      let uy = sin(ang);
      let nx = -uy;
      let ny = ux;

      // Cast shadow of wood chip
      brush.set("marker", PAL.crevice, 1.3);
      safeLine(cx - ux * len * 0.4 + 3, cy - uy * len * 0.4 + 4, cx + ux * len * 0.4 + 3, cy + uy * len * 0.4 + 4);

      // Crescent chip body (ochre-pink edge + bone-white core)
      let p0 = [cx - ux * len * 0.5, cy - uy * len * 0.5];
      let pMid = [cx + nx * wid, cy + ny * wid];
      let p1 = [cx + ux * len * 0.5, cy + uy * len * 0.5];

      brush.set("flat_chisel", PAL.ochrePink, 0.95);
      safeSpline([p0, [cx + nx * wid * 1.25, cy + ny * wid * 1.25], p1], 0.5);

      brush.set("flat_chisel", random() < 0.7 ? PAL.boneBright : PAL.boneLight, 0.85);
      safeSpline([p0, pMid, p1], 0.5);

      brush.set("rotring", PAL.inkBlack, 0.55);
      safeSpline([p0, pMid, p1], 0.5);
    }
  }

  // Fine sawdust & kōkōwai ochre specks scattered across the horizontal carving band
  for (let i = 0; i < 420; i++) {
    let x = random(25, 1175);
    // Concentrated along the horizontal band y = 260..940 and around the chisel
    let y = 600 + (random() - 0.5 + random() - 0.5) * 380;
    let r = random();
    let col = r < 0.48 ? PAL.boneLight : (r < 0.82 ? PAL.ochrePink : PAL.ochreRed);

    brush.set("rotring", col, random(0.35, 0.85));
    let a = random(360);
    let d = random(1.2, 4.2);
    safeLine(x, y, x + cos(a) * d, y + sin(a) * d);
  }

  // Subtle spray dust around the chisel tip and deep spiral bays
  const dustZones = [
    [885, 680, 110],
    [260, 615, 90],
    [480, 488, 90],
    [718, 618, 90],
    [955, 448, 85]
  ];
  for (let dz of dustZones) {
    brush.set("spray", PAL.boneMid, 0.55);
    brush.circle(dz[0], dz[1], dz[2], 0.4);
    brush.set("spray", PAL.ochrePink, 0.45);
    brush.circle(dz[0] + 10, dz[1] - 8, dz[2] * 0.75, 0.4);
  }
}

// Hyperrealist Sawmill Interior: Morning Light Shaft, Circular Saw Blade & Airborne Sawdust
// Rendered with p5.brush in soft compressed charcoal, burnt umber, raw sienna, and lifted bone-white

const LX = -486;
const LY = -126;
const RAY_MIN = 21.55;
const RAY_MAX = 36.95;

const BLADE_CX = 595;
const BLADE_CY = 585;
const BLADE_RX = 252;
const BLADE_RY = 332;
const BLADE_TILT = -7.5; // degrees
const NUM_TEETH = 44;

// Helper: convert blade polar (angle in deg, radius factor 0..1) to canvas (x, y)
function bladePt(angDeg, rFac, zOffset = 0) {
  let rad = angDeg * Math.PI / 180;
  let tilt = BLADE_TILT * Math.PI / 180;
  let lx = Math.cos(rad) * BLADE_RX * rFac;
  let ly = Math.sin(rad) * BLADE_RY * rFac;
  let rx = lx * Math.cos(tilt) - ly * Math.sin(tilt);
  let ry = lx * Math.sin(tilt) + ly * Math.cos(tilt);
  return [BLADE_CX + rx + zOffset * 0.92, BLADE_CY + ry + zOffset * 0.28];
}

// Helper: saw table throat slot Y coordinate at a given X
function slotY(x) {
  return 722 + (x - BLADE_CX) * 0.115;
}

// Helper: compute morning light shaft intensity (0.0 in deep shadow .. 1.0 in core beam)
function getLight(x, y, includeGodRays = true) {
  if (x < 105) return 0;
  let dx = x - LX;
  let dy = y - LY;
  let ang = Math.atan2(dy, dx) * 180 / Math.PI;

  // Penumbra widens slightly across the room
  let dist = Math.hypot(dx, dy);
  let blur = map(dist, 550, 1900, 0.32, 0.95, true);

  let topEdge = constrain((ang - (RAY_MIN - blur)) / (blur * 2), 0, 1);
  let botEdge = constrain(((RAY_MAX + blur) - ang) / (blur * 2), 0, 1);
  // Smoothstep
  topEdge = topEdge * topEdge * (3 - 2 * topEdge);
  botEdge = botEdge * botEdge * (3 - 2 * botEdge);
  let val = topEdge * botEdge;

  // Wall slit entrance cut-off on left
  if (x < 138) {
    let wallCut = constrain((x - 108) / 26, 0, 1);
    val *= wallCut * wallCut;
  }

  if (val <= 0.001) return 0;

  if (includeGodRays) {
    // Subtle crepuscular ray striations from plank gap splinters
    let rayWave = 0.88 + 0.12 * Math.sin(ang * 14.5) * Math.cos(ang * 5.2);
    val *= rayWave;

    // Shadow occlusion cast by the saw blade into the dusty air to its right
    if (x > BLADE_CX + 40 && ang > 24.2 && ang < 34.8) {
      let bladeShadow = 0.78 + 0.22 * Math.sin(ang * 38.0);
      val *= bladeShadow;
    }
  }
  return constrain(val, 0, 1);
}

// Helper: ray angle in degrees at (x, y) from light source
function getRayAngle(x, y) {
  return Math.atan2(y - LY, x - LX) * 180 / Math.PI;
}

