function draw() {
  translate(-width / 2, -height / 2);

  // 1. UNDERPAINTING: Velvety Burnt-Umber & Charcoal Darkness Outside the Beam
  drawUnderpainting();

  // 2. BACKGROUND: Rough Sawmill Plank Wall & Morning Light Gap
  drawPlankWallAndSlit();

  // 3. MIDGROUND LEFT: Sawn Pine Timber Cant & Back Saw-Table Bed
  drawBackTableAndTimberCant();

  // 4. FOCAL POINT: The Toothed Circular Saw Blade (Steel, Bevels, Rust Blooms, Fingerprint Smudge)
  drawCircularSawBlade();

  // 5. FOREGROUND: Saw-Table Surface, Kerf Slot, Raw Sienna Wood Fibres & Pine Curls
  drawForegroundSawTable();
  drawWoodFibresAndSawdustDrifts();
  drawPineCurls();

  // 6. ATMOSPHERE: Lifted Bone-White Light Wedge, Crepuscular Rays & Airborne Sawdust Motes
  drawLiftedLightBeamAndMotes();

  // 7. FINAL CHARCOAL DENSITY: Deepening Outer Shadows for Maximum Chiaroscuro
  drawFinalShadowVignette();

  noLoop();
}

