// ============================================================================
// 2. SAWMILL PLANK WALL & MORNING LIGHT SLIT
// ============================================================================
function drawPlankWallAndSlit() {
  // Vertical rough-sawn barn planks across y = 0..710
  let plankEdges = [0, 116, 134, 285, 445, 615, 790, 965, 1130, 1200];

  // Compressed charcoal & burnt umber vertical shading across wall
  for (let p = 0; p < plankEdges.length - 1; p++) {
    let x0 = plankEdges[p];
    let x1 = plankEdges[p + 1];
    // Skip the light slit gap at p === 1 (116..134)
    if (p === 1) continue;

    let step = 7;
    for (let x = x0 + 3; x < x1 - 2; x += step) {
      let yMax = slotY(x) - 10;
      for (let y = 10; y < yMax; y += 55) {
        let y2 = min(y + 62, yMax);
        let ym = (y + y2) * 0.5;
        let lVal = getLight(x, ym, false);

        if (lVal < 0.08) {
          // Deep velvety burnt-umber charcoal outside the beam
          let col = random() < 0.6 ? "#140b06" : "#21130b";
          brush.set("velvet_umber", col, random(1.1, 1.9));
          brush.line(x + random(-2, 2), y, x + random(-2, 2), y2);
        } else if (lVal < 0.65) {
          // Penumbra raking across rough plank grain
          let col = lVal > 0.35 ? "#6e4423" : "#3b2313";
          brush.set("charcoal", col, random(0.8, 1.4));
          brush.line(x + random(-1, 1), y, x + random(-1, 1), y2);
        } else {
          // Illuminated plank wall behind the dust beam: warm raw sienna & bone tone
          if (random() < 0.45) {
            let col = random() < 0.5 ? "#c99b64" : "#dec092";
            brush.set("cpencil", col, random(0.5, 0.9));
            brush.line(x, y, x + random(-1, 1), y2);
          }
        }
      }
    }

    // Plank seam crevices
    if (p > 0 && p !== 2) {
      for (let y = 0; y < 700; y += 35) {
        let lVal = getLight(x0, y + 17, false);
        let seamCol = lVal > 0.5 ? "#4a2912" : "#0b0603";
        brush.set("charcoal", seamCol, lVal > 0.5 ? 0.9 : 1.5);
        brush.line(x0 + random(-1, 1), y, x0 + random(-1, 1), y + 38);
      }
    }
  }

  // Subtle weathered wood knots & horizontal band-saw marks on the illuminated wall planks
  for (let i = 0; i < 160; i++) {
    let wx = random(145, 950);
    let wy = random(90, 650);
    // Skip if behind the blade
    let bdx = (wx - BLADE_CX) / BLADE_RX;
    let bdy = (wy - BLADE_CY) / BLADE_RY;
    if (bdx * bdx + bdy * bdy < 0.95) continue;

    let lVal = getLight(wx, wy, false);
    if (lVal > 0.25) {
      let col = lVal > 0.65 ? "#b88248" : "#5c361a";
      brush.set("2B", col, random(0.4, 0.8));
      let len = random(18, 55);
      brush.line(wx, wy, wx + random(-3, 3), wy + len);
    }
  }

  // THE PLANK GAP / LIGHT SLIT (x = 115..135, y = 112..332)
  // Blazing bone-white core inside the gap
  brush.noStroke();
  brush.wash("#fffdf7", 245);
  brush.beginShape(0);
  brush.vertex(115, 112);
  brush.vertex(135, 116);
  brush.vertex(131, 334);
  brush.vertex(112, 326);
  brush.endShape(true);
  brush.noWash();

  // Golden-sienna halation and splintered plank edges framing the light gap
  for (let y = 108; y < 336; y += 3) {
    // Left inner plank thickness catching blazing rim light
    brush.set("cpencil", "#f5dca8", random(0.8, 1.4));
    brush.line(113 + random(-1, 1), y, 116, y + 4);
    brush.set("rotring", "#a85619", random(0.5, 0.9));
    brush.line(109 + random(-1.5, 1), y, 112, y + 4);

    // Right chamfered edge of gap
    brush.set("cpencil", "#f7e6c4", random(0.9, 1.5));
    brush.line(133, y, 138 + random(0, 4), y + 4);

    // Tiny backlit wood splinters jutting into the bright slit
    if (random() < 0.38) {
      let sx = random() < 0.5 ? 115 : 133;
      let dir = sx < 124 ? 1 : -1;
      brush.set("rotring", "#3d1c08", random(0.35, 0.65));
      brush.line(sx, y, sx + dir * random(4, 11), y + random(-3, 5));
    }
  }

  // Deep shadow above and below the slit between the planks
  brush.set("charcoal", "#0d0704", 2.2);
  brush.line(122, 0, 124, 110);
  brush.line(121, 336, 118, 680);
}

