// ============================================================================
// 4. THE TOOTHED CIRCULAR SAW BLADE (FORENSIC HYPERREALISM)
// ============================================================================
function drawCircularSawBlade() {
  // 4A. 3D Steel Plate Rim Thickness (Back/Right Offset Layer) & Blade Base Fill
  let bodyPts = [];
  let rimBackPts = [];
  for (let a = 0; a < 360; a += 3) {
    let pt = bladePt(a, 0.898, 0);
    let sy = slotY(pt[0]);
    if (pt[1] < sy + 8) {
      bodyPts.push([pt[0], min(pt[1], sy)]);
      let bpt = bladePt(a, 0.898, 5.5);
      rimBackPts.push([bpt[0], min(bpt[1], sy)]);
    }
  }

  // Dark steel edge thickness
  brush.noStroke();
  brush.wash("#2b1c12", 240);
  brush.beginShape(0);
  for (let pt of rimBackPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // Base warm steel wash for the main blade plate
  brush.wash("#8c7f6e", 235);
  brush.beginShape(0);
  for (let pt of bodyPts) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);
  brush.noWash();

  // 4B. Radial & Concentric Steel Shading Modulated by the Morning Light Shaft
  // We render hundreds of fine elliptical grinding grooves around the blade disc.
  // Each segment samples getLight(x, y) plus anisotropic metallic reflection!
  for (let rFac = 0.21; rFac <= 0.895; rFac += 0.0065) {
    let stepAng = rFac < 0.45 ? 5 : 3;
    for (let a = -168; a < 32; a += stepAng) {
      let p1 = bladePt(a, rFac, 0);
      let p2 = bladePt(a + stepAng + 0.4, rFac, 0);
      let mx = (p1[0] + p2[0]) * 0.5;
      let my = (p1[1] + p2[1]) * 0.5;

      // Clip at the saw-table throat slot
      if (my > slotY(mx) - 1) continue;

      let lVal = getLight(mx, my, false);

      // Anisotropic brushed-steel specular lobes (perpendicular to light ray at ~ -60 deg and +120 deg)
      let normAng = ((a % 360) + 360) % 360;
      let spec1 = Math.exp(-Math.pow((normAng - 318) / 28, 2));
      let spec2 = Math.exp(-Math.pow((normAng - 142) / 32, 2));
      let spec3 = Math.exp(-Math.pow((normAng - 225) / 36, 2)) * 0.5;
      let sheen = constrain(spec1 + spec2 + spec3, 0, 1);

      // Check if inside the fingerprint smudge zone (centered around a = -28, rFac = 0.56)
      let fpDist = Math.hypot((a - (-28)) * 0.016, (rFac - 0.56) * 2.4);
      let inFingerprint = fpDist < 0.22;

      let col;
      let w = random(0.45, 0.95);
      let brName = "steel_micro";

      if (lVal < 0.08) {
        // Outside the beam: deep oiled charcoal & burnt umber steel shadow
        col = sheen > 0.45 ? "#38271b" : (random() < 0.5 ? "#1c110a" : "#26180f");
        brName = "2B";
        w = random(0.7, 1.3);
      } else if (lVal < 0.48) {
        // Penumbra edge cutting sharply across the steel disc
        col = sheen > 0.4 ? "#857461" : "#4f3b2b";
        brName = "HB";
      } else {
        // Inside the hard morning light beam!
        if (inFingerprint && fpDist < 0.17) {
          // Oily skin-lipid smudge dulls the bright specular steel into warm greasy umber-grey
          col = random() < 0.5 ? "#6e5c49" : "#594836";
        } else if (sheen > 0.62 && random() < 0.75) {
          col = "#fbf5e6"; // Blazing bone-white metallic specular glint
          w = random(0.6, 1.1);
        } else if (sheen > 0.32) {
          col = random() < 0.5 ? "#dfd5c1" : "#c7bba6";
        } else {
          col = random() < 0.5 ? "#a69884" : "#8c7e6b";
        }
      }

      brush.set(brName, col, w);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Deepen the shadowy portions of the blade (very top tip and lower-left belly) with charcoal
  for (let i = 0; i < 240; i++) {
    let rFac = random(0.24, 0.89);
    let a = random(-172, 35);
    let pt = bladePt(a, rFac, 0);
    if (pt[1] > slotY(pt[0]) - 2) continue;
    let lVal = getLight(pt[0], pt[1], false);
    if (lVal < 0.22) {
      brush.set("charcoal", lVal < 0.06 ? "#120a05" : "#29180e", random(0.8, 1.6));
      let p2 = bladePt(a + random(4, 9), rFac, 0);
      brush.line(pt[0], pt[1], p2[0], p2[1]);
    }
  }

  // 4C. Radial Laser/Machined Expansion Slots with Stress-Relief Keyhole Circles
  let slotAngles = [-122, -48, 22, 162];
  for (let sa of slotAngles) {
    let rStart = 0.62;
    let rEnd = 0.885;
    let pIn = bladePt(sa, rStart, 0);
    let pOut = bladePt(sa, rEnd, 0);
    if (pIn[1] > slotY(pIn[0])) continue;

    // Stress-relief circular hole at the inner base of the expansion slot
    let lHole = getLight(pIn[0], pIn[1], false);
    // 3D steel thickness inside the hole
    brush.set("rotring", lHole > 0.4 ? "#f7efe0" : "#5e4936", 1.1);
    brush.circle(pIn[0] + 2.2, pIn[1] + 0.8, 7.5, 0.1);
    // Dark void of the hole
    brush.noStroke();
    brush.wash("#120a05", 245);
    brush.circle(pIn[0], pIn[1], 7.0, 0.05);
    brush.noWash();

    // Radial expansion slot cut
    if (pOut[1] < slotY(pOut[0])) {
      // Bright bevel edge of the slot catching morning light
      brush.set("rotring", lHole > 0.4 ? "#fbf6e8" : "#6e5844", 0.95);
      brush.line(pIn[0] + 2.5, pIn[1] + 1.0, pOut[0] + 2.5, pOut[1] + 1.0);
      // Dark kerf gap of the expansion slot
      brush.set("pen", "#120a05", 1.9);
      brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
    }
  }

  // 4D. Rust Blooms on the Steel Blade Face (Sharp Oxidation Colonies)
  let rustColonies = [
    { ang: -74, r: 0.66, rad: 38 }, // Large upper-left illuminated rust bloom
    { ang: -12, r: 0.74, rad: 32 }, // Right rim rust bloom near teeth
    { ang: -102, r: 0.46, rad: 26 }, // Mid-upper rust bloom above arbor
    { ang: -42, r: 0.36, rad: 22 },  // Inner rust patch near fingerprint
    { ang: -138, r: 0.72, rad: 34 }, // Left edge rust bloom crossing beam border
    { ang: 8, r: 0.58, rad: 25 }     // Lower-right illuminated rust bloom
  ];

  for (let rc of rustColonies) {
    let center = bladePt(rc.ang, rc.r, 0);
    if (center[1] > slotY(center[0]) - 8) continue;

    // Rusty halo stretched slightly along the concentric grinding grooves
    let numSpecks = floor(rc.rad * 7.5);
    for (let i = 0; i < numSpecks; i++) {
      let da = randomGaussian(0, rc.rad * 0.28);
      let dr = randomGaussian(0, rc.rad * 0.0018);
      let pt = bladePt(rc.ang + da, constrain(rc.r + dr, 0.23, 0.89), 0);
      if (pt[1] > slotY(pt[0]) - 2) continue;

      let lVal = getLight(pt[0], pt[1], false);
      let distNorm = Math.hypot(da / (rc.rad * 0.35), dr / (rc.rad * 0.0022));

      let rCol;
      if (lVal < 0.15) {
        rCol = distNorm < 0.5 ? "#240c04" : "#381709";
      } else {
        if (distNorm < 0.38) {
          rCol = random() < 0.5 ? "#5c1b07" : "#7a270c"; // Deep pitted iron oxide core
        } else if (distNorm < 0.78) {
          rCol = random() < 0.55 ? "#b54614" : "#cc5c1f"; // Vibrant rust bloom orange-sienna
        } else {
          rCol = random() < 0.5 ? "#d67f33" : "#b86b28"; // Feathery raw sienna oxidation halo
        }
      }

      brush.set(distNorm < 0.5 ? "rotring" : "cpencil", rCol, random(0.35, 0.85));
      let pNext = bladePt(rc.ang + da + random(0.6, 2.2), constrain(rc.r + dr, 0.23, 0.89), 0);
      brush.line(pt[0], pt[1], pNext[0], pNext[1]);
    }
  }

  // 4E. FORENSIC FINGERPRINT SMUDGE ON THE ILLUMINATED STEEL
  // Placed at angle = -28 deg, r = 0.56 (approx x = 712, y = 472, right in the bright beam)
  drawFingerprintSmudgeOnSteel();

  // 4F. THE 44 HOOKED RIP-SAW TEETH (Each Tooth's Bevel & Rust Bloom Sharp)
  drawSawTeeth();

  // 4G. CENTRAL ARBOR CLAMPING FLANGE, COLLAR & MACHINED HEX NUT
  drawBladeArborAndCollar();
}

function drawFingerprintSmudgeOnSteel() {
  let fpCenter = bladePt(-28, 0.56, 0);
  let fcx = fpCenter[0];
  let fcy = fpCenter[1];
  let tiltRad = 28 * Math.PI / 180; // Thumb angled diagonally across the steel

  // 1. Soft greasy skin-oil stain & directional smear trail
  for (let i = 0; i < 95; i++) {
    let u = randomGaussian(0, 14);
    let v = randomGaussian(0, 21);
    let rx = u * Math.cos(tiltRad) - v * Math.sin(tiltRad);
    let ry = u * Math.sin(tiltRad) + v * Math.cos(tiltRad);
    let col = random() < 0.5 ? "#786550" : "#614e3a";
    brush.set("2H", col, random(0.4, 0.75));
    brush.line(fcx + rx, fcy + ry, fcx + rx + random(-5, 3), fcy + ry + random(-6, 2));
  }

  // 2. Forensic Whorl & Loop Friction Ridges (broken stippled micro-arcs catching raking light)
  for (let ring = 2.5; ring <= 29; ring += 1.65) {
    let rW = ring * 0.92;
    let rH = ring * 1.35;
    for (let a = -165; a < 175; a += 14) {
      // Natural breaks for sweat pores and smudge pressure variations
      if (noise(ring * 0.4, a * 0.08) < 0.28) continue;

      let a1 = a * Math.PI / 180;
      let a2 = (a + 10.5) * Math.PI / 180;

      // Whorl distortion toward bottom of print
      let pinch1 = 1.0 + 0.18 * Math.sin(a1);
      let pinch2 = 1.0 + 0.18 * Math.sin(a2);

      let u1 = Math.cos(a1) * rW * pinch1;
      let v1 = Math.sin(a1) * rH;
      let u2 = Math.cos(a2) * rW * pinch2;
      let v2 = Math.sin(a2) * rH;

      let x1 = fcx + u1 * Math.cos(tiltRad) - v1 * Math.sin(tiltRad);
      let y1 = fcy + u1 * Math.sin(tiltRad) + v1 * Math.cos(tiltRad);
      let x2 = fcx + u2 * Math.cos(tiltRad) - v2 * Math.sin(tiltRad);
      let y2 = fcy + u2 * Math.sin(tiltRad) + v2 * Math.cos(tiltRad);

      // Dark oily ridge line
      brush.set("rotring", "#3d2d1e", 0.34);
      brush.line(x1, y1, x2, y2);

      // Tiny bright raking-light ridge edge (forensic clarity!)
      if (Math.sin(a1 - 0.5) < 0 && random() < 0.55) {
        brush.set("steel_micro", "#efe4ce", 0.35);
        brush.line(x1 + 0.6, y1 - 0.5, x2 + 0.6, y2 - 0.5);
      }
    }
  }

  // 3. Faint secondary index-finger smudge & fine sawdust clinging to the oil
  let f2 = bladePt(-16, 0.64, 0);
  for (let ring = 3; ring <= 16; ring += 1.9) {
    for (let a = -120; a < 120; a += 18) {
      if (random() < 0.35) continue;
      let a1 = a * Math.PI / 180;
      let a2 = (a + 12) * Math.PI / 180;
      let x1 = f2[0] + Math.cos(a1) * ring * 0.85;
      let y1 = f2[1] + Math.sin(a1) * ring * 1.15;
      let x2 = f2[0] + Math.cos(a2) * ring * 0.85;
      let y2 = f2[1] + Math.sin(a2) * ring * 1.15;
      brush.set("rotring", "#4a3828", 0.3);
      brush.line(x1, y1, x2, y2);
    }
  }
  // Tiny raw-sienna sawdust grains stuck to the sticky fingerprint oil
  for (let i = 0; i < 28; i++) {
    let sx = fcx + randomGaussian(0, 11);
    let sy = fcy + randomGaussian(0, 16);
    brush.set("rotring", random() < 0.6 ? "#e8b668" : "#b86b23", random(0.4, 0.75));
    brush.line(sx, sy, sx + 1.2, sy + 0.8);
  }
}

function drawSawTeeth() {
  let dAng = 360 / NUM_TEETH;

  for (let i = 0; i < NUM_TEETH; i++) {
    let baseAng = i * dAng;

    // Key points of each hooked rip-saw tooth
    let gRoot = bladePt(baseAng, 0.892, 0);
    let gCurve = bladePt(baseAng + dAng * 0.26, 0.922, 0);
    let tip = bladePt(baseAng + dAng * 0.16, 1.000, 0); // Aggressive forward hook
    let bevelBack = bladePt(baseAng + dAng * 0.62, 0.958, 0);
    let nextRoot = bladePt(baseAng + dAng, 0.892, 0);

    // Skip teeth buried below the saw-table throat slot
    if (tip[1] > slotY(tip[0]) + 4 && gRoot[1] > slotY(gRoot[0]) + 4) continue;

    // 3D thickness offset points (steel plate depth & swage set)
    let swage = (i % 2 === 0) ? 6.5 : 4.8; // Alternate top bevel (ATB) set
    let tipBack = bladePt(baseAng + dAng * 0.16, 1.000, swage);
    let bevelBack3D = bladePt(baseAng + dAng * 0.62, 0.958, swage);
    let gCurve3D = bladePt(baseAng + dAng * 0.26, 0.922, swage);
    let nextRoot3D = bladePt(baseAng + dAng, 0.892, swage);

    let lVal = getLight(tip[0], tip[1], false);

    // 1. 3D Steel Thickness & Chiseled Bevel Facets
    // Top clearance bevel plane (between tip, tipBack, bevelBack3D, bevelBack)
    let topFacingSun = Math.sin((baseAng - 35) * Math.PI / 180) < 0.25;
    let hookFacingSun = Math.cos((baseAng - 25) * Math.PI / 180) > -0.2;

    let bodyCol = lVal < 0.12 ? "#1e120a" : (lVal < 0.45 ? "#594736" : "#9c8e7b");
    let topBevelCol, hookBevelCol;

    if (lVal < 0.12) {
      topBevelCol = topFacingSun ? "#3d291a" : "#140b06";
      hookBevelCol = hookFacingSun ? "#47301f" : "#170d07";
    } else {
      topBevelCol = topFacingSun ? (i % 2 === 0 ? "#fbf5e6" : "#dfd2bc") : "#594838";
      hookBevelCol = hookFacingSun ? "#fffdf9" : "#6e5a46";
    }

    brush.noStroke();
    // Tooth flat steel plate triangle
    brush.wash(bodyCol, 245);
    brush.beginShape(0);
    brush.vertex(gRoot[0], gRoot[1]);
    brush.vertex(gCurve[0], gCurve[1]);
    brush.vertex(tip[0], tip[1]);
    brush.vertex(bevelBack[0], bevelBack[1]);
    brush.vertex(nextRoot[0], nextRoot[1]);
    brush.endShape(true);

    // Top clearance bevel facet
    brush.wash(topBevelCol, 245);
    brush.beginShape(0);
    brush.vertex(tip[0], tip[1]);
    brush.vertex(tipBack[0], tipBack[1]);
    brush.vertex(bevelBack3D[0], bevelBack3D[1]);
    brush.vertex(bevelBack[0], bevelBack[1]);
    brush.endShape(true);

    // Hook rake bevel facet (inside the gullet throat)
    brush.wash(hookBevelCol, 245);
    brush.beginShape(0);
    brush.vertex(gCurve[0], gCurve[1]);
    brush.vertex(gCurve3D[0], gCurve3D[1]);
    brush.vertex(tipBack[0], tipBack[1]);
    brush.vertex(tip[0], tip[1]);
    brush.endShape(true);
    brush.noWash();

    // 2. Micro-grinding hatch lines on the bevel faces & sharp contour edges
    let edgeCol = lVal > 0.35 ? "#2b190d" : "#0d0704";
    brush.set("rotring", edgeCol, 0.55);
    brush.line(gRoot[0], gRoot[1], gCurve[0], gCurve[1]);
    brush.line(gCurve[0], gCurve[1], tip[0], tip[1]);
    brush.line(tip[0], tip[1], bevelBack[0], bevelBack[1]);
    brush.line(bevelBack[0], bevelBack[1], nextRoot[0], nextRoot[1]);
    brush.line(tip[0], tip[1], tipBack[0], tipBack[1]);
    brush.line(bevelBack[0], bevelBack[1], bevelBack3D[0], bevelBack3D[1]);
    brush.line(tipBack[0], tipBack[1], bevelBack3D[0], bevelBack3D[1]);

    // 3. Razor-sharp bone-white specular glint on each illuminated tooth's bevel & tip
    if (lVal > 0.25) {
      brush.set("rotring", "#fffef9", lVal > 0.6 ? 0.95 : 0.6);
      brush.line(tip[0], tip[1], tipBack[0], tipBack[1]);
      if (topFacingSun) {
        brush.line(tip[0], tip[1], bevelBack[0], bevelBack[1]);
      }
      if (hookFacingSun) {
        brush.line(gCurve[0], gCurve[1], tip[0], tip[1]);
      }

      // Rust bloom & packed raw-sienna resin/sawdust in the tooth gullet!
      let rustCol = random() < 0.55 ? "#b84814" : "#8f320b";
      for (let k = 0; k < 7; k++) {
        let rx = lerp(gRoot[0], gCurve[0], random(0.1, 0.9)) + random(-2.5, 2.5);
        let ry = lerp(gRoot[1], gCurve[1], random(0.1, 0.9)) + random(-2.5, 2.5);
        brush.set("rotring", k < 4 ? rustCol : "#e3a656", random(0.45, 0.85));
        brush.line(rx, ry, rx + random(-2, 2), ry + random(-2, 2));
      }
    }
  }
}

function drawBladeArborAndCollar() {
  // Heavy machined clamping collar / flange at center of blade (rFac = 0.215)
  // Casts a crisp diagonal shadow down-right at angle ~30 deg
  let shadowOffX = 11;
  let shadowOffY = 7;

  // Cast shadow of the collar onto the blade face
  brush.noStroke();
  brush.wash("#24150c", 215);
  brush.beginShape(0);
  for (let a = 0; a < 360; a += 10) {
    let pt = bladePt(a, 0.215, 0);
    brush.vertex(pt[0] + shadowOffX, pt[1] + shadowOffY);
  }
  brush.endShape(true);

  // 3D beveled side wall of the collar
  brush.wash("#594938", 245);
  brush.beginShape(0);
  for (let a = 0; a < 360; a += 10) {
    let pt = bladePt(a, 0.215, 7);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);

  // Front machined face of the collar
  brush.wash("#b5a793", 245);
  brush.beginShape(0);
  for (let a = 0; a < 360; a += 10) {
    let pt = bladePt(a, 0.195, 7);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Concentric lathe turning rings on the clamping collar
  for (let r = 0.08; r <= 0.212; r += 0.011) {
    for (let a = 0; a < 360; a += 12) {
      let p1 = bladePt(a, r, 7);
      let p2 = bladePt(a + 12, r, 7);
      let isBright = (a > 185 && a < 315) || (a > 10 && a < 85);
      let col = isBright ? "#fbf5e6" : ((a > 90 && a < 175) ? "#4a3a2a" : "#8c7e6a");
      brush.set("rotring", col, isBright ? 0.65 : 0.5);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Two pin-spanner holes on the collar face with rust stains bleeding downward
  for (let pa of [-45, 135]) {
    let hp = bladePt(pa, 0.14, 7);
    brush.noStroke();
    brush.wash("#170d06", 245);
    brush.circle(hp[0], hp[1], 5.5, 0.08);
    brush.noWash();
    brush.set("rotring", "#fbf5e6", 0.7);
    brush.arc(hp[0], hp[1], 5.8, -40, 140);
    // Rust streak below pin hole
    for (let k = 0; k < 8; k++) {
      brush.set("cpencil", "#a84112", 0.5);
      brush.line(hp[0] + random(-2, 2), hp[1] + 5, hp[0] + random(-3, 3), hp[1] + random(10, 22));
    }
  }

  // Central Hexagonal Arbor Nut & Threaded Spindle Tip
  let hexR = 0.072;
  // Shadow of hex nut
  brush.noStroke();
  brush.wash("#1c1008", 230);
  brush.beginShape(0);
  for (let i = 0; i < 6; i++) {
    let pt = bladePt(i * 60 + 15, hexR, 7);
    brush.vertex(pt[0] + 8, pt[1] + 5);
  }
  brush.endShape(true);

  // Hex nut 3D body
  brush.wash("#756450", 250);
  brush.beginShape(0);
  for (let i = 0; i < 6; i++) {
    let pt = bladePt(i * 60 + 15, hexR, 14);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // Sharp hex nut facets & bevel edges
  for (let i = 0; i < 6; i++) {
    let a1 = i * 60 + 15;
    let a2 = (i + 1) * 60 + 15;
    let p1 = bladePt(a1, hexR, 14);
    let p2 = bladePt(a2, hexR, 14);
    let p1Base = bladePt(a1, hexR, 7);
    let p2Base = bladePt(a2, hexR, 7);

    let facetCol = (i === 3 || i === 4) ? "#fbf5e6" : (i === 0 || i === 1 ? "#332215" : "#968571");
    brush.noStroke();
    brush.wash(facetCol, 240);
    brush.beginShape(0);
    brush.vertex(p1[0], p1[1]);
    brush.vertex(p2[0], p2[1]);
    brush.vertex(p2Base[0], p2Base[1]);
    brush.vertex(p1Base[0], p1Base[1]);
    brush.endShape(true);
    brush.noWash();

    brush.set("rotring", i >= 3 ? "#fffdf9" : "#24150b", 0.65);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.line(p1[0], p1[1], p1Base[0], p1Base[1]);
  }

  // Central threaded spindle end inside the nut
  let spCenter = bladePt(0, 0, 15);
  brush.noStroke();
  brush.wash("#38281b", 245);
  brush.circle(spCenter[0], spCenter[1], 8.5, 0.05);
  brush.noWash();
  brush.set("rotring", "#fbf5e6", 0.7);
  brush.arc(spCenter[0], spCenter[1], 8.5, 190, 340);
  brush.arc(spCenter[0], spCenter[1], 5.5, 190, 340);
}

// ============================================================================
// 5. FOREGROUND SAW-TABLE, RAW SIENNA WOOD FIBRES & PINE CURLS
// ============================================================================
function drawForegroundSawTable() {
  // Dark kerf throat slot where the circular blade plunges into the timber bench
  let sLeft = [342, slotY(342)];
  let sRight = [855, slotY(855)];

  // Deep shadow inside the saw-table throat slot
  brush.noStroke();
  brush.wash("#0a0503", 250);
  brush.beginShape(0);
  brush.vertex(sLeft[0], sLeft[1] - 4);
  brush.vertex(sRight[0], sRight[1] - 4);
  brush.vertex(sRight[0] + 15, sRight[1] + 9);
  brush.vertex(sLeft[0] - 10, sLeft[1] + 7);
  brush.endShape(true);
  brush.noWash();

  // Illuminated front lip of the wooden throat slot catching morning light
  for (let x = sLeft[0]; x <= sRight[0]; x += 6) {
    let sy = slotY(x) + 7;
    let lVal = getLight(x, sy, false);
    let col = lVal > 0.45 ? "#e6c48c" : (lVal > 0.15 ? "#784921" : "#1f1108");
    brush.set("cpencil", col, lVal > 0.45 ? 1.1 : 0.8);
    brush.line(x, sy, x + 7, slotY(x + 7) + 7);
  }

  // Cast shadow of the upper saw blade onto the right side of the saw-table
  // Because light comes from (LX = -486, LY = -126), the lower-right rim of the blade casts a shadow across x = 620..1200, y = 730..980
  brush.noStroke();
  brush.wash("#2b180c", 150);
  brush.beginShape(0);
  brush.vertex(610, slotY(610) + 5);
  brush.vertex(835, slotY(835) + 5);
  brush.vertex(1200, 995);
  brush.vertex(1200, 1140);
  brush.vertex(740, 825);
  brush.endShape(true);
  brush.noWash();

  // Horizontal heavy plank grain on the foreground saw-bench (y = 720..1200)
  for (let yBase = 725; yBase < 1200; yBase += 5.5) {
    for (let x = 0; x < 1190; x += 48) {
      let x2 = min(1200, x + 52);
      let y1 = yBase + (x - 600) * 0.115;
      let y2 = yBase + (x2 - 600) * 0.115;
      if (y1 < slotY(x) + 6) continue;
      if (y1 > 1200) continue;

      let xm = (x + x2) * 0.5;
      let ym = (y1 + y2) * 0.5;
      let lVal = getLight(xm, ym, true);

      if (lVal < 0.08) {
        // Velvety burnt-umber shadow outside the beam
        let col = random() < 0.6 ? "#120a05" : "#1f1209";
        brush.set("velvet_umber", col, random(1.0, 1.8));
        brush.line(x, y1, x2, y2);
      } else if (lVal < 0.45) {
        let col = lVal > 0.25 ? "#693b18" : "#361e0d";
        brush.set("charcoal", col, random(0.8, 1.3));
        brush.line(x, y1, x2, y2);
      } else {
        // Illuminated saw-table bench: warm raw sienna & golden-bone wood grain
        let col = lVal > 0.72 ? (random() < 0.45 ? "#f2e2c2" : "#d9a968") : "#b57432";
        brush.set("cpencil", col, random(0.6, 1.1));
        brush.line(x, y1, x2, y2);

        // Fine dark wood pore lines for forensic wood grain clarity
        if (random() < 0.35) {
          brush.set("2H", "#7d4518", random(0.35, 0.6));
          brush.line(x + 4, y1 + 1.2, x2 - 4, y2 + 1.2);
        }
      }
    }
  }
}

function drawWoodFibresAndSawdustDrifts() {
  // 1. Mounded Sawdust Drifts piled around the blade kerf slot and across the bench
  let mounds = [
    { cx: 525, cy: 735, rx: 95, ry: 26 },
    { cx: 695, cy: 748, rx: 115, ry: 32 },
    { cx: 835, cy: 775, rx: 90, ry: 28 },
    { cx: 640, cy: 815, rx: 130, ry: 38 },
    { cx: 920, cy: 855, rx: 140, ry: 42 },
    { cx: 780, cy: 910, rx: 125, ry: 36 },
    { cx: 1040, cy: 945, rx: 130, ry: 40 }
  ];

  for (let m of mounds) {
    // Granular sawdust texture across each mound
    let count = floor(m.rx * 4.2);
    for (let i = 0; i < count; i++) {
      let ang = random(0, 360);
      let rad = Math.sqrt(random()) * 1.0;
      let gx = m.cx + Math.cos(ang * Math.PI / 180) * m.rx * rad;
      let gy = m.cy + Math.sin(ang * Math.PI / 180) * m.ry * rad;
      if (gy < slotY(gx) - 3) continue;

      let lVal = getLight(gx, gy, true);
      // Mound self-shading (upper-left slope facing the morning light is brighter, lower-right slope is raw sienna/umber)
      let slopeLight = Math.sin((ang + 135) * Math.PI / 180);

      let col;
      if (lVal < 0.15) {
        col = slopeLight > 0 ? "#381f0e" : "#1a0e06";
      } else {
        if (slopeLight > 0.25 && lVal > 0.55) {
          col = random() < 0.55 ? "#fbf4e3" : "#edd19d"; // Sun-bleached golden sawdust crest
        } else if (slopeLight > -0.2) {
          col = random() < 0.5 ? "#d18b3f" : "#b86c23"; // Raw sienna core
        } else {
          col = random() < 0.5 ? "#8a4614" : "#5c2b0a"; // Warm burnt-sienna shadow slope
        }
      }

      brush.set("cpencil", col, random(0.45, 0.95));
      brush.line(gx, gy, gx + random(1.5, 4.5), gy + random(-1, 2));
    }
  }

  // 2. Forensic Raw Sienna Wood Fibres & Torn Splinters Inside the Light Beam
  // Hundreds of needle-sharp fibrous strands with individual cast shadows
  for (let i = 0; i < 420; i++) {
    let fx = random(420, 1185);
    let fy = random(715, 1160);
    if (fy < slotY(fx) + 2) continue;

    let lVal = getLight(fx, fy, true);
    if (lVal < 0.12 && random() < 0.75) continue;

    let len = random(10, 46);
    let ang = random(-28, 42);
    let midAng = ang + random(-14, 14);

    let x1 = fx;
    let y1 = fy;
    let x2 = fx + Math.cos(ang * Math.PI / 180) * (len * 0.5);
    let y2 = fy + Math.sin(ang * Math.PI / 180) * (len * 0.5);
    let x3 = x2 + Math.cos(midAng * Math.PI / 180) * (len * 0.5);
    let y3 = y2 + Math.sin(midAng * Math.PI / 180) * (len * 0.5);

    if (lVal > 0.25) {
      // Hair-thin cast shadow directly beneath the wood fibre
      let shOffX = random(1.5, 3.5);
      let shOffY = random(1.2, 2.8);
      brush.set("rotring", lVal > 0.5 ? "#381c09" : "#1c0e05", random(0.35, 0.65));
      brush.spline([[x1 + shOffX, y1 + shOffY], [x2 + shOffX, y2 + shOffY], [x3 + shOffX, y3 + shOffY]], 0.4);

      // Raw sienna & bone-white illuminated wood fibre
      let fCol;
      let r = random();
      if (r < 0.35) fCol = "#c88338";      // Pure raw sienna
      else if (r < 0.65) fCol = "#ab5d1b"; // Deep raw sienna / ochre
      else if (r < 0.85) fCol = "#edc98c"; // Pale pine fibre
      else fCol = "#fbf5e6";               // Specular bone-white splinter edge

      brush.set("rotring", fCol, random(0.35, 0.75));
      brush.spline([[x1, y1], [x2, y2], [x3, y3]], 0.4);
    } else {
      // Dim splinter in shadow
      brush.set("2B", "#331b0b", random(0.4, 0.7));
      brush.line(x1, y1, x3, y3);
    }
  }
}

