function drawSinglePineCurl(cx, cy, sc, rotDeg) {
  let lVal = getLight(cx, cy, true);
  let rot = rotDeg * Math.PI / 180;

  // Helper to transform local curl coordinates
  function cPt(lx, ly) {
    let rx = (lx * Math.cos(rot) - ly * Math.sin(rot)) * sc;
    let ry = (lx * Math.sin(rot) + ly * Math.cos(rot)) * sc;
    return [cx + rx, cy + ry];
  }

  // 1. Crisp diagonal cast shadow of the pine curl on the saw-bench (angle ~30 deg)
  let shX = 9 * sc;
  let shY = 5.5 * sc;
  brush.noStroke();
  brush.wash(lVal > 0.3 ? "#2b1508" : "#120904", 215);
  brush.beginShape(0.3);
  for (let a = 0; a < 360; a += 30) {
    let rad = a * Math.PI / 180;
    let pt = cPt(Math.cos(rad) * 22 + 6, Math.sin(rad) * 12);
    brush.vertex(pt[0] + shX, pt[1] + shY);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Render 2.5 overlapping helical ribbon coils of shaved pine
  let coils = 2;
  for (let k = 0; k < coils; k++) {
    let xOff = (k - 0.5) * 14;
    let rOuterX = 16 - k * 2.5;
    let rOuterY = 11 - k * 1.5;
    let ribbonW = 8.5 - k * 1.2;

    // Back/Inner concave wall of the wood curl (warm raw sienna / burnt sienna)
    let innerCol = lVal > 0.35 ? "#9c5119" : "#3d1e0a";
    brush.noStroke();
    brush.wash(innerCol, 235);
    brush.beginShape(0);
    for (let a = 150; a <= 390; a += 18) {
      let rad = a * Math.PI / 180;
      let pt = cPt(xOff + Math.cos(rad) * rOuterX, Math.sin(rad) * rOuterY);
      brush.vertex(pt[0], pt[1]);
    }
    for (let a = 390; a >= 150; a -= 18) {
      let rad = a * Math.PI / 180;
      let pt = cPt(xOff + ribbonW + Math.cos(rad) * (rOuterX * 0.78), Math.sin(rad) * (rOuterY * 0.78) + 2);
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);

    // Front convex sunlit ribbon of the wood curl (translucent golden-amber & bone-white)
    let outerCol = lVal > 0.45 ? "#f2d8a7" : (lVal > 0.2 ? "#b87835" : "#4f2910");
    brush.wash(outerCol, 242);
    brush.beginShape(0);
    for (let a = -30; a <= 210; a += 18) {
      let rad = a * Math.PI / 180;
      let pt = cPt(xOff + Math.cos(rad) * rOuterX, Math.sin(rad) * rOuterY);
      brush.vertex(pt[0], pt[1]);
    }
    for (let a = 210; a >= -30; a -= 18) {
      let rad = a * Math.PI / 180;
      let pt = cPt(xOff + ribbonW + Math.cos(rad) * (rOuterX * 0.82), Math.sin(rad) * (rOuterY * 0.82) + 1.5);
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
    brush.noWash();

    // Fine longitudinal pine wood-grain lines & feathered translucent curl edges
    for (let g = 0; g <= 1.0; g += 0.25) {
      let pts = [];
      for (let a = -25; a <= 205; a += 25) {
        let rad = a * Math.PI / 180;
        let gx = xOff + g * ribbonW + Math.cos(rad) * lerp(rOuterX, rOuterX * 0.82, g);
        let gy = Math.sin(rad) * lerp(rOuterY, rOuterY * 0.82, g) + g * 1.5;
        pts.push(cPt(gx, gy));
      }
      let gCol;
      if (g === 0 || g === 1.0) {
        gCol = lVal > 0.4 ? "#fffdf7" : "#78441b"; // Crisp backlit bone-white edge of shaved pine
      } else {
        gCol = lVal > 0.4 ? "#c87d32" : "#4a250c"; // Raw sienna wood grain striation
      }
      brush.set("rotring", gCol, (g === 0 || g === 1.0) ? 0.55 : 0.35);
      brush.spline(pts, 0.45);
    }
  }
}

// ============================================================================
// 6. THE LIFTED BONE-WHITE LIGHT WEDGE & SUSPENDED AIRBORNE SAWDUST MOTES
// ============================================================================
function drawLiftedLightBeamAndMotes() {
  // 6A. Volumetric "Lifted-Out" Bone-White Ray Strokes along the Light Wedge
  // Simulates a kneaded eraser / white chalk lifting compressed charcoal along a straightedge
  for (let i = 0; i < 310; i++) {
    let ang = random(RAY_MIN + 0.15, RAY_MAX - 0.15);
    let rad = ang * Math.PI / 180;
    let rStart = random(615, 1550);
    let rLen = random(95, 340);
    let rEnd = min(1820, rStart + rLen);

    let x1 = LX + Math.cos(rad) * rStart;
    let y1 = LY + Math.sin(rad) * rStart;
    let x2 = LX + Math.cos(rad) * rEnd;
    let y2 = LY + Math.sin(rad) * rEnd;

    if (x1 < 120 || x1 > 1190 || y1 < 0 || y1 > 1190) continue;

    // Modulate intensity so rays near the top & bottom edges of the wedge define a razor-sharp boundary
    let edgeProximity = min(ang - RAY_MIN, RAY_MAX - ang);
    let isEdgeRay = edgeProximity < 1.1;

    // Check if ray passes in front of the dark background or over the blade
    let bdx = (x1 - BLADE_CX) / BLADE_RX;
    let bdy = (y1 - BLADE_CY) / BLADE_RY;
    let overBlade = (bdx * bdx + bdy * bdy) < 1.05 && y1 < slotY(x1);

    if (overBlade && random() < 0.65) continue; // Keep forensic steel crisp!

    let col = isEdgeRay ? "#fbf6e8" : (random() < 0.6 ? "#f7eed8" : "#ecd7ac");
    let w = isEdgeRay ? random(0.6, 1.3) : random(0.8, 1.8);
    brush.set(isEdgeRay ? "2H" : "charcoal_block", col, w);
    brush.line(x1, y1, x2, y2);
  }

  // Razor-sharp lifted straightedge lines along RAY_MIN and RAY_MAX
  for (let boundaryAng of [RAY_MIN, RAY_MAX]) {
    let rad = boundaryAng * Math.PI / 180;
    for (let r = 610; r < 1780; r += 65) {
      let x1 = LX + Math.cos(rad) * r;
      let y1 = LY + Math.sin(rad) * r;
      let x2 = LX + Math.cos(rad) * (r + 72);
      let y2 = LY + Math.sin(rad) * (r + 72);
      brush.set("cpencil", "#fbf6e8", random(0.75, 1.25));
      brush.line(x1, y1, x2, y2);
    }
  }

  // 6B. Fine Spray of Suspended Motes across the Light Shaft
  for (let i = 0; i < 65; i++) {
    let ang = random(RAY_MIN + 0.4, RAY_MAX - 0.4);
    let rad = ang * Math.PI / 180;
    let r1 = random(620, 1650);
    let r2 = r1 + random(40, 120);
    let x1 = LX + Math.cos(rad) * r1;
    let y1 = LY + Math.sin(rad) * r1;
    let x2 = LX + Math.cos(rad) * r2;
    let y2 = LY + Math.sin(rad) * r2;

    let col = random() < 0.65 ? "#fbf6e8" : "#edd29f";
    brush.set("mote_spray", col, random(0.8, 1.5));
    brush.line(x1, y1, x2, y2);
  }

  // 6C. Individual Forensic Airborne Sawdust Particles (Pinpoint Glints, Spinning Wood Flecks & Bokeh Motes)
  for (let i = 0; i < 950; i++) {
    // Concentrate slightly denser near the wall slit and around the saw blade turbulence
    let ang = random(RAY_MIN - 0.2, RAY_MAX + 0.2);
    let rad = ang * Math.PI / 180;
    let dist = random(612, 1820);
    let mx = LX + Math.cos(rad) * dist;
    let my = LY + Math.sin(rad) * dist;

    if (mx < 118 || mx > 1195 || my < 10 || my > 1190) continue;

    let lVal = getLight(mx, my, true);
    if (lVal < 0.18) continue;

    let moteType = random();

    if (moteType < 0.08) {
      // Soft out-of-focus foreground dust bokeh circle catching the morning sun
      let bRad = random(2.2, 5.2);
      brush.noStroke();
      brush.wash(random() < 0.6 ? "#fbf6e8" : "#f2dca8", random(65, 135));
      brush.circle(mx, my, bRad, 0.15);
      brush.noWash();
      // Bright pinpoint center
      brush.set("rotring", "#fffef9", 0.55);
      brush.line(mx, my, mx + 0.8, my + 0.5);
    } else if (moteType < 0.32) {
      // Tumbling airborne raw-sienna & golden wood-fibre fleck
      let fLen = random(2.5, 7.5);
      let fAng = random(0, 360) * Math.PI / 180;
      let col = random() < 0.55 ? "#f7e5be" : (random() < 0.5 ? "#df9f52" : "#c88338");
      brush.set("rotring", col, random(0.45, 0.85));
      brush.line(mx, my, mx + Math.cos(fAng) * fLen, my + Math.sin(fAng) * fLen);
    } else {
      // Razor-sharp sunlit sawdust mote speck
      let col = random() < 0.72 ? "#fffdf9" : "#f5e1b5";
      brush.set("rotring", col, random(0.4, 0.9));
      brush.line(mx, my, mx + random(0.8, 2.2), my + random(-0.8, 1.6));
    }
  }
}

