// ============================================================================
// GEOMETRY & MADHUBANI DOUBLE-OUTLINE HELPERS
// ============================================================================

function sampleSpline(ctrlPts, closed = false, stepPx = 4) {
  let pts = [];
  let n = ctrlPts.length;
  if (n < 2) return ctrlPts;

  let totalSegs = closed ? n : n - 1;
  let dense = [];

  for (let i = 0; i < totalSegs; i++) {
    let p0 = ctrlPts[(i - 1 + n) % n];
    let p1 = ctrlPts[i % n];
    let p2 = ctrlPts[(i + 1) % n];
    let p3 = ctrlPts[(i + 2) % n];
    if (!closed) {
      if (i === 0) p0 = p1;
      if (i === n - 2) p3 = p2;
    }
    let segLen = dist(p1[0], p1[1], p2[0], p2[1]);
    let steps = max(4, floor(segLen / 2));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let t2 = t * t;
      let t3 = t2 * t;
      let x =
        0.5 *
        (2 * p1[0] +
          (-p0[0] + p2[0]) * t +
          (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
          (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y =
        0.5 *
        (2 * p1[1] +
          (-p0[1] + p2[1]) * t +
          (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
          (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      dense.push([x, y]);
    }
  }
  if (!closed) dense.push(ctrlPts[n - 1]);

  // Resample at uniform arc length
  pts.push(dense[0]);
  let acc = 0;
  for (let i = 1; i < dense.length; i++) {
    let d = dist(dense[i - 1][0], dense[i - 1][1], dense[i][0], dense[i][1]);
    acc += d;
    if (acc >= stepPx) {
      pts.push(dense[i]);
      acc = 0;
    }
  }
  if (!closed && dist(pts[pts.length - 1][0], pts[pts.length - 1][1], dense[dense.length - 1][0], dense[dense.length - 1][1]) > 1) {
    pts.push(dense[dense.length - 1]);
  }
  return pts;
}

function computeCurveNormals(pts, closed = false) {
  let normals = [];
  let n = pts.length;
  for (let i = 0; i < n; i++) {
    let prev = closed ? pts[(i - 1 + n) % n] : pts[max(0, i - 1)];
    let next = closed ? pts[(i + 1) % n] : pts[min(n - 1, i + 1)];
    let dx = next[0] - prev[0];
    let dy = next[1] - prev[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    normals.push([-dy / len, dx / len]);
  }
  return normals;
}

/**
 * Draws the quintessential Madhubani double outline with tiny perpendicular dashes
 * filling the channel between the two parallel contour lines.
 */
function drawMadhubaniDoubleOutline(ctrlPts, options = {}) {
  let {
    closed = true,
    gap = 9,
    dashSpacing = 4.5,
    outerColor = PAL.lampBlack,
    innerColor = PAL.lampBlack,
    dashColor = PAL.lampBlack,
    altDashColor = null,
    channelColor = PAL.channelLight,
    channelAlpha = 210,
    weightOuter = 0.65,
    weightInner = 0.52,
    weightDash = 0.38
  } = options;

  let pts = sampleSpline(ctrlPts, closed, dashSpacing);
  let normals = computeCurveNormals(pts, closed);
  let n = pts.length;
  if (n < 3) return;

  let outerPts = [];
  let innerPts = [];
  for (let i = 0; i < n; i++) {
    let nx = normals[i][0];
    let ny = normals[i][1];
    outerPts.push([pts[i][0] + nx * (gap * 0.5), pts[i][1] + ny * (gap * 0.5)]);
    innerPts.push([pts[i][0] - nx * (gap * 0.5), pts[i][1] - ny * (gap * 0.5)]);
  }

  // 1. Optional parchment channel ribbon between the double lines
  if (channelColor) {
    brush.noStroke();
    brush.noFill();
    brush.noHatch();
    brush.set("glazeMarker", channelColor, gap * 0.28);
    for (let i = 0; i < n - 1; i += 2) {
      let i2 = min(n - 1, i + 2);
      brush.line(pts[i][0], pts[i][1], pts[i2][0], pts[i2][1]);
    }
    if (closed) {
      brush.line(pts[n - 1][0], pts[n - 1][1], pts[0][0], pts[0][1]);
    }
  }

  // 2. Tiny perpendicular dashes inside the double-line gap
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  for (let i = 0; i < n; i++) {
    let c = altDashColor && i % 2 === 1 ? altDashColor : dashColor;
    brush.set("rotring", c, weightDash);
    let x1 = innerPts[i][0];
    let y1 = innerPts[i][1];
    let x2 = outerPts[i][0];
    let y2 = outerPts[i][1];
    brush.line(x1, y1, x2, y2);
  }

  // 3. Draw inner and outer continuous boundaries
  brush.set("rotring", outerColor, weightOuter);
  for (let i = 0; i < n - 1; i++) {
    brush.line(outerPts[i][0], outerPts[i][1], outerPts[i + 1][0], outerPts[i + 1][1]);
  }
  if (closed) {
    brush.line(outerPts[n - 1][0], outerPts[n - 1][1], outerPts[0][0], outerPts[0][1]);
  }

  brush.set("rotring", innerColor, weightInner);
  for (let i = 0; i < n - 1; i++) {
    brush.line(innerPts[i][0], innerPts[i][1], innerPts[i + 1][0], innerPts[i + 1][1]);
  }
  if (closed) {
    brush.line(innerPts[n - 1][0], innerPts[n - 1][1], innerPts[0][0], innerPts[0][1]);
  }
}

function drawWashPolygon(pts, col, opacity = 180, useWatercolor = false) {
  brush.noStroke();
  brush.noHatch();
  if (useWatercolor) {
    brush.noWash();
    brush.fill(col, opacity);
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.45, 0.3);
  } else {
    brush.noFill();
    brush.wash(col, opacity);
  }
  brush.beginShape(0);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noFill();
  brush.noWash();
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 0.00001) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

// ============================================================================
// 1. DUSKY TWILIGHT GROUND
// ============================================================================

function renderTwilightGround() {
  background(PAL.groundWarm);

  // Deep twilight vignette & atmospheric washes
  let fullRect = [[0, 0], [1200, 0], [1200, 1200], [0, 1200]];
  drawWashPolygon(fullRect, "#826c66", 150, false);

  // Twilight plum-indigo atmospheric wash around corners
  let corners = [
    [[0, 0], [650, 0], [420, 420], [0, 650]],
    [[1200, 0], [1200, 650], [780, 420], [550, 0]],
    [[0, 1200], [0, 580], [420, 780], [650, 1200]],
    [[1200, 1200], [580, 1200], [780, 780], [1200, 580]]
  ];
  for (let c of corners) {
    drawWashPolygon(c, "#433442", 95, true);
  }

  // Warm twilight amber glow behind parrot & guava
  let glowPoly = [];
  for (let a = 0; a < 360; a += 15) {
    glowPoly.push([630 + cos(a) * 390, 560 + sin(a) * 390]);
  }
  drawWashPolygon(glowPoly, "#bfa388", 90, true);
}

// ============================================================================
// 2. DENSE LATTICE OF LEAVES IN LAMP-BLACK & VERMILION (NO EMPTY SPACE)
// ============================================================================

function isFullyOccludedBySubject(cx, cy) {
  // Approximate core interior of parrot body and split guava to save unnecessary hidden strokes
  let dHead = dist(cx, cy, 565, 255);
  if (dHead < 75) return true;
  let dBody = dist(cx, cy, 505, 540);
  if (dBody < 105) return true;
  let dGuava = dist(cx, cy, 785, 765);
  if (dGuava < 82) return true;
  return false;
}

function renderBackgroundLattice() {
  // We tile the entire 56..1144 square with an interlocking ogival leaf lattice.
  // Every cell contains a primary double-outlined leaf, two flanking corner crescents
  // filled with katchni hatching, and internal photographic leaf-vein relief.
  let xMin = 56, xMax = 1144;
  let yMin = 56, yMax = 1144;
  let cols = 7;
  let rows = 8;
  let cellW = (xMax - xMin) / cols;
  let cellH = (yMax - yMin) / rows;

  // First, fill the entire background field with dense base katchni twilight cross-striations
  // so that even a 1-pixel micro-gap between leaf cells is 100% filled with line work.
  brush.noFill();
  brush.noWash();
  for (let y = yMin; y <= yMax; y += 6.5) {
    let col = floor(y / 6.5) % 2 === 0 ? PAL.lampBlack : PAL.vermilionDeep;
    brush.set("rotring", col, 0.32);
    brush.line(xMin, y, xMax, y);
  }

  // Now render every ogival lattice cell and its interstitial diamond leaf
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let cx = xMin + (c + 0.5) * cellW;
      let cy = yMin + (r + 0.5) * cellH;

      if (!isFullyOccludedBySubject(cx, cy)) {
        let parity = (r + c) % 2;
        drawLatticeLeafCell(cx, cy, cellW, cellH, parity);
      }

      // Interstitial diamond leaf at grid intersections (guarantees zero empty space between ogives)
      if (r < rows - 1 && c < cols - 1) {
        let ix = xMin + (c + 1) * cellW;
        let iy = yMin + (r + 1) * cellH;
        if (!isFullyOccludedBySubject(ix, iy)) {
          drawInterstitialLeaf(ix, iy, cellW * 0.46, cellH * 0.46, (r + c) % 2 === 0);
        }
      }
    }
  }

  // Edge half-diamonds along top, bottom, left, right borders to seal against frame
  for (let c = 0; c < cols - 1; c++) {
    let ix = xMin + (c + 1) * cellW;
    drawInterstitialLeaf(ix, yMin + 18, cellW * 0.36, 34, true);
    drawInterstitialLeaf(ix, yMax - 18, cellW * 0.36, 34, false);
  }
  for (let r = 0; r < rows - 1; r++) {
    let iy = yMin + (r + 1) * cellH;
    drawInterstitialLeaf(xMin + 18, iy, 34, cellH * 0.36, true);
    drawInterstitialLeaf(xMax - 18, iy, 34, cellH * 0.36, false);
  }
}

function drawLatticeLeafCell(cx, cy, w, h, parity) {
  let tilt = parity === 0 ? -14 : 14;
  let hw = w * 0.48;
  let hh = h * 0.48;

  // Ogival pointed leaf contour
  let rawPts = [
    [0, -hh],
    [hw * 0.68, -hh * 0.42],
    [hw * 0.85, 0],
    [hw * 0.62, hh * 0.48],
    [0, hh],
    [-hw * 0.62, hh * 0.48],
    [-hw * 0.85, 0],
    [-hw * 0.68, -hh * 0.42]
  ];

  let poly = rawPts.map(p => {
    let rx = p[0] * cos(tilt) - p[1] * sin(tilt);
    let ry = p[0] * sin(tilt) + p[1] * cos(tilt);
    return [cx + rx, cy + ry];
  });

  // Dusky twilight wash inside cell so each cell has sculptural depth
  let washCol = parity === 0 ? "#4a3b47" : "#5e4647";
  drawWashPolygon(poly, washCol, 195, false);

  // Corner filler arcs around the ogive (katchni radiating fans in vermilion & lamp-black)
  let corners = [
    [cx - w * 0.48, cy - h * 0.48],
    [cx + w * 0.48, cy - h * 0.48],
    [cx + w * 0.48, cy + h * 0.48],
    [cx - w * 0.48, cy + h * 0.48]
  ];
  for (let k = 0; k < 4; k++) {
    let kx = corners[k][0];
    let ky = corners[k][1];
    let baseAng = k * 90 + 15;
    for (let s = 0; s <= 6; s++) {
      let ang = baseAng + s * 10;
      let r1 = 6;
      let r2 = 28;
      brush.set("rotring", s % 2 === 0 ? PAL.vermilion : PAL.lampBlack, 0.35);
      brush.line(kx + cos(ang) * r1, ky + sin(ang) * r1, kx + cos(ang) * r2, ky + sin(ang) * r2);
    }
  }

  // Hyperreal 3D curved leaf venation & chiaroscuro hatching inside the leaf cell
  let topPt = poly[0];
  let botPt = poly[4];
  let steps = 18;
  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    let mx = lerp(topPt[0], botPt[0], t);
    let my = lerp(topPt[1], botPt[1], t);
    let widthFactor = sin(t * 180);
    let span = hw * 0.72 * widthFactor;

    // Left side veins (shadowed lamp-black with vermilion undertint)
    let lAng = tilt - 135 + t * 25;
    let lx = mx + cos(lAng) * span;
    let ly = my + sin(lAng) * span;
    brush.set("rotring", i % 3 === 0 ? PAL.vermilion : PAL.lampBlack, 0.42);
    brush.line(mx, my, lx, ly);

    // Sub-vein micro-hatching for photographic relief
    let mx2 = lerp(mx, lx, 0.5);
    let my2 = lerp(my, ly, 0.5);
    brush.set("microPen", PAL.lampBlack, 0.32);
    brush.line(mx2, my2, mx2 + cos(lAng - 35) * (span * 0.35), my2 + sin(lAng - 35) * (span * 0.35));

    // Right side veins (lit vermilion & warm twilight gold-ochre)
    let rAng = tilt - 45 - t * 25;
    let rx = mx + cos(rAng) * span;
    let ry = my + sin(rAng) * span;
    brush.set("rotring", i % 2 === 0 ? PAL.vermilionBright : PAL.lampBlack, 0.42);
    brush.line(mx, my, rx, ry);

    let rx2 = lerp(mx, rx, 0.45);
    let ry2 = lerp(my, ry, 0.45);
    brush.set("microPen", PAL.channelLight, 0.28);
    brush.line(mx, my, rx2, ry2);
  }

  // Central midrib double line
  brush.set("rotring", PAL.vermilionBright, 0.65);
  brush.line(topPt[0], topPt[1], botPt[0], botPt[1]);
  brush.set("rotring", PAL.lampBlack, 0.45);
  brush.line(topPt[0] + 2, topPt[1], botPt[0] + 2, botPt[1]);

  // Strict Madhubani double outline around the leaf cell in Lamp-Black & Vermilion
  drawMadhubaniDoubleOutline(poly, {
    closed: true,
    gap: 6.5,
    dashSpacing: 4.5,
    outerColor: parity === 0 ? PAL.lampBlack : PAL.vermilion,
    innerColor: parity === 0 ? PAL.vermilion : PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilionBright,
    channelColor: "#a88f7d",
    weightOuter: 0.55,
    weightInner: 0.48,
    weightDash: 0.35
  });
}

function drawInterstitialLeaf(cx, cy, rx, ry, isWarm) {
  let poly = [
    [cx, cy - ry],
    [cx + rx * 0.65, cy - ry * 0.25],
    [cx + rx, cy],
    [cx + rx * 0.65, cy + ry * 0.25],
    [cx, cy + ry],
    [cx - rx * 0.65, cy + ry * 0.25],
    [cx - rx, cy],
    [cx - rx * 0.65, cy - ry * 0.25]
  ];

  drawWashPolygon(poly, isWarm ? "#54383b" : "#382e3d", 210, false);

  // Dense concentric parallel hatching inside interstitial diamond leaf
  let rings = 6;
  for (let k = 1; k <= rings; k++) {
    let s = k / (rings + 1);
    let c = k % 2 === 0 ? PAL.vermilionBright : PAL.lampBlack;
    brush.set("rotring", c, 0.36);
    brush.line(cx, cy - ry * s, cx + rx * s, cy);
    brush.line(cx + rx * s, cy, cx, cy + ry * s);
    brush.line(cx, cy + ry * s, cx - rx * s, cy);
    brush.line(cx - rx * s, cy, cx, cy - ry * s);
  }

  // Center jewel dot
  brush.set("rotring", PAL.vermilionBright, 0.7);
  brush.circle(cx, cy, 4, 0.1);

  drawMadhubaniDoubleOutline(poly, {
    closed: true,
    gap: 5,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.vermilion,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilionBright,
    channelColor: "#b89f8b",
    weightOuter: 0.5,
    weightInner: 0.42,
    weightDash: 0.32
  });
}

// ============================================================================
// 3. GNARLED GUAVA BRANCH & BOTANICAL LEAVES
// ============================================================================

function renderGuavaBranch() {
  // Main horizontal gnarled branch supporting parrot and guava
  let branchCtrl = [
    [58, 765],
    [220, 750],
    [390, 758],
    [545, 762],
    [710, 795],
    [920, 845],
    [1142, 875],
    [1142, 922],
    [910, 892],
    [695, 842],
    [535, 810],
    [385, 804],
    [215, 802],
    [58, 818]
  ];

  let branchPoly = sampleSpline(branchCtrl, true, 8);
  drawWashPolygon(branchPoly, PAL.barkDark, 235, false);

  // Hyperreal cylindrical bark fissures and lichen knots inside branch
  let topSpine = [
    [58, 765], [220, 750], [390, 758], [545, 762], [710, 795], [920, 845], [1142, 875]
  ];
  let botSpine = [
    [58, 818], [215, 802], [385, 804], [535, 810], [695, 842], [910, 892], [1142, 922]
  ];
  let tPts = sampleSpline(topSpine, false, 6);
  let bPts = sampleSpline(botSpine, false, 6);
  let count = min(tPts.length, bPts.length);

  // Longitudinal bark ridges
  for (let f = 0; f <= 12; f++) {
    let v = f / 12;
    let col = v < 0.3 ? PAL.barkLight : v < 0.65 ? PAL.barkMid : PAL.lampBlack;
    let w = v < 0.25 ? 0.42 : 0.35;
    for (let i = 0; i < count - 1; i++) {
      let n1 = noise(i * 0.15, f * 0.4) * 8 - 4;
      let n2 = noise((i + 1) * 0.15, f * 0.4) * 8 - 4;
      let x1 = lerp(tPts[i][0], bPts[i][0], v);
      let y1 = lerp(tPts[i][1], bPts[i][1], v) + n1;
      let x2 = lerp(tPts[i + 1][0], bPts[i + 1][0], v);
      let y2 = lerp(tPts[i + 1][1], bPts[i + 1][1], v) + n2;
      brush.set("microPen", col, w);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Cross-contour cylindrical shading lines on bark
  for (let i = 0; i < count; i += 2) {
    let xT = tPts[i][0], yT = tPts[i][1];
    let xB = bPts[i][0], yB = bPts[i][1];
    let mx = (xT + xB) * 0.5 + 4;
    let my = (yT + yB) * 0.5;
    brush.set("microPen", PAL.lampBlack, 0.35);
    brush.line(mx, my, xB, yB);
    if (i % 4 === 0) {
      brush.set("microPen", PAL.channelLight, 0.3);
      brush.line(xT, yT, mx, my);
    }
  }

  // Madhubani double outline around the main branch
  drawMadhubaniDoubleOutline(branchCtrl, {
    closed: true,
    gap: 8.5,
    dashSpacing: 4.5,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelWarm,
    weightOuter: 0.65,
    weightInner: 0.52,
    weightDash: 0.38
  });

  // Two hyperreal guava leaves sprouting near the fruit
  drawHyperrealGuavaLeaf(965, 705, 135, 58, -32);
  drawHyperrealGuavaLeaf(995, 955, 125, 54, 28);
  drawHyperrealGuavaLeaf(210, 665, 130, 56, -152);
}

function drawHyperrealGuavaLeaf(cx, cy, len, wid, angleDeg) {
  let raw = [
    [-len * 0.5, 0],
    [-len * 0.25, -wid * 0.48],
    [len * 0.1, -wid * 0.52],
    [len * 0.38, -wid * 0.28],
    [len * 0.5, 0],
    [len * 0.38, wid * 0.28],
    [len * 0.1, wid * 0.52],
    [-len * 0.25, wid * 0.48]
  ];
  let poly = raw.map(p => {
    let rx = p[0] * cos(angleDeg) - p[1] * sin(angleDeg);
    let ry = p[0] * sin(angleDeg) + p[1] * cos(angleDeg);
    return [cx + rx, cy + ry];
  });

  let dense = sampleSpline(poly, true, 5);
  drawWashPolygon(dense, PAL.viridianDark, 235, false);

  // Hyperreal ribbed guava leaf veins & barb-like serration shading
  let steps = 28;
  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    let lx = (t - 0.5) * len;
    let env = sin(t * 180) * wid * 0.48;
    let mx = cx + lx * cos(angleDeg);
    let my = cy + lx * sin(angleDeg);

    // Upper blade (sunlit emerald & turmeric)
    for (let s = 0; s < 3; s++) {
      let frac = (s + 1) / 3;
      let vx = lx + frac * env * 0.55;
      let vy = -frac * env;
      let wx = cx + vx * cos(angleDeg) - vy * sin(angleDeg);
      let wy = cy + vx * sin(angleDeg) + vy * cos(angleDeg);
      let col = s === 0 ? PAL.parrotGreen : s === 1 ? PAL.chartreuse : PAL.turmeric;
      brush.set("microPen", col, 0.34);
      brush.line(mx, my, wx, wy);
    }

    // Lower blade (twilight teal & deep emerald shadow)
    for (let s = 0; s < 3; s++) {
      let frac = (s + 1) / 3;
      let vx = lx + frac * env * 0.55;
      let vy = frac * env;
      let wx = cx + vx * cos(angleDeg) - vy * sin(angleDeg);
      let wy = cy + vx * sin(angleDeg) + vy * cos(angleDeg);
      let col = s === 0 ? PAL.deepTeal : s === 1 ? PAL.parrotGreen : PAL.emeraldMid;
      brush.set("microPen", col, 0.34);
      brush.line(mx, my, wx, wy);
    }
  }

  // Prominent central midrib
  let pStart = [cx - len * 0.48 * cos(angleDeg), cy - len * 0.48 * sin(angleDeg)];
  let pEnd = [cx + len * 0.48 * cos(angleDeg), cy + len * 0.48 * sin(angleDeg)];
  brush.set("rotring", PAL.turmericBright, 0.55);
  brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);

  drawMadhubaniDoubleOutline(poly, {
    closed: true,
    gap: 7,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight,
    weightOuter: 0.58,
    weightInner: 0.48,
    weightDash: 0.35
  });
}

// ============================================================================
// 4. PARROT TAIL FEATHERS (HYPERREAL BARBS IN TEAL, PARROT GREEN & TURMERIC)
// ============================================================================

function renderParrotTail() {
  // Long graduated tail feathers sweeping diagonally to lower-left
  let tailFeathers = [
    // Lateral left feather
    {
      pts: [[415, 690], [310, 815], [205, 945], [140, 1020], [175, 1032], [285, 905], [445, 725]],
      rachis: [[430, 708], [295, 860], [155, 1026]],
      isCentral: false
    },
    // Lateral right feather
    {
      pts: [[465, 725], [375, 855], [275, 995], [220, 1072], [258, 1078], [365, 935], [505, 745]],
      rachis: [[485, 735], [370, 895], [238, 1075]],
      isCentral: false
    },
    // Long Central Rectrix (signature of Psittacula krameri)
    {
      pts: [[440, 710], [320, 875], [190, 1045], [95, 1140], [135, 1142], [265, 995], [480, 735]],
      rachis: [[460, 722], [290, 935], [115, 1141]],
      isCentral: true
    }
  ];

  for (let tf of tailFeathers) {
    let dense = sampleSpline(tf.pts, true, 6);
    drawWashPolygon(dense, tf.isCentral ? PAL.deepTeal : PAL.viridianDark, 240, false);

    // Render individual hyperreal barbs radiating from the central rachis
    let rSpline = sampleSpline(tf.rachis, false, 3.5);
    for (let i = 1; i < rSpline.length - 1; i++) {
      let rx = rSpline[i][0];
      let ry = rSpline[i][1];
      let dx = rSpline[i + 1][0] - rSpline[i - 1][0];
      let dy = rSpline[i + 1][1] - rSpline[i - 1][1];
      let tang = atan2(dy, dx);
      let t = i / rSpline.length;
      let vaneW = (1 - t * 0.65) * (tf.isCentral ? 26 : 22);

      // Left vane barbs (sunlit parrot green -> turmeric tip)
      let angL = tang + 38;
      let mxL = rx + cos(angL) * (vaneW * 0.55);
      let myL = ry + sin(angL) * (vaneW * 0.55);
      let exL = rx + cos(angL) * vaneW;
      let eyL = ry + sin(angL) * vaneW;
      brush.set("microPen", tf.isCentral ? PAL.napeBlue : PAL.parrotGreen, 0.34);
      brush.line(rx, ry, mxL, myL);
      brush.set("microPen", tf.isCentral ? PAL.chartreuse : PAL.turmeric, 0.3);
      brush.line(mxL, myL, exL, eyL);

      // Right vane barbs (shadowed viridian/teal -> emerald tip)
      let angR = tang - 38;
      let mxR = rx + cos(angR) * (vaneW * 0.55);
      let myR = ry + sin(angR) * (vaneW * 0.55);
      let exR = rx + cos(angR) * vaneW;
      let eyR = ry + sin(angR) * vaneW;
      brush.set("microPen", PAL.shadowIndigo, 0.36);
      brush.line(rx, ry, mxR, myR);
      brush.set("microPen", tf.isCentral ? PAL.deepTeal : PAL.parrotGreen, 0.32);
      brush.line(mxR, myR, exR, eyR);
    }

    // Central shaft (rachis)
    brush.set("rotring", PAL.lampBlack, 0.55);
    for (let i = 0; i < rSpline.length - 1; i++) {
      brush.line(rSpline[i][0], rSpline[i][1], rSpline[i + 1][0], rSpline[i + 1][1]);
    }
    brush.set("microPen", PAL.turmericBright, 0.28);
    for (let i = 0; i < rSpline.length - 1; i += 2) {
      brush.line(rSpline[i][0] - 1, rSpline[i][1], rSpline[i + 1][0] - 1, rSpline[i + 1][1]);
    }

    // Madhubani double outline around each tail feather
    drawMadhubaniDoubleOutline(tf.pts, {
      closed: true,
      gap: 7.5,
      dashSpacing: 4.5,
      outerColor: PAL.lampBlack,
      innerColor: PAL.lampBlack,
      dashColor: PAL.lampBlack,
      altDashColor: PAL.vermilion,
      channelColor: PAL.channelLight,
      weightOuter: 0.58,
      weightInner: 0.48,
      weightDash: 0.35
    });
  }
}

// ============================================================================
// 5. THE SPLIT GUAVA (GLISTENING CORAL-PINK FLESH & INDIVIDUAL SEEDS)
// ============================================================================

function renderSplitGuava() {
  // --------------------------------------------------------------------------
  // PART A: THE UPPER-LEFT SPLIT CLEAVAGE HALF (GRIPPED BY PARROT'S RIGHT FOOT)
  // Shows the bumpy parrot-green & turmeric-blushed outer skin and split wedge
  // --------------------------------------------------------------------------
  let backSkinCtrl = [
    [595, 675],
    [580, 610],
    [615, 555],
    [680, 540],
    [745, 565],
    [775, 620],
    [740, 695],
    [655, 720]
  ];
  let backSkinPoly = sampleSpline(backSkinCtrl, true, 5);
  drawWashPolygon(backSkinPoly, PAL.viridianDark, 240, false);

  // Spherical contour cross-hatching on bumpy outer guava skin
  let skinCx = 668, skinCy = 622;
  for (let r = 10; r < 98; r += 3.2) {
    for (let a = 150; a < 355; a += 8) {
      let bump = sin(a * 5) * 4 + cos(r * 4) * 3;
      let x1 = skinCx + cos(a) * (r + bump);
      let y1 = skinCy + sin(a) * (r * 0.85 + bump);
      let x2 = skinCx + cos(a + 7) * (r + bump);
      let y2 = skinCy + sin(a + 7) * (r * 0.85 + bump);
      if (pointInPoly(x1, y1, backSkinPoly)) {
        // Chiaroscuro from shadow viridian to turmeric-blushed sunlit dome
        let light = map(cos(a - 255) + (1 - r / 100), -0.5, 1.8, 0, 1);
        let col =
          light > 0.78
            ? PAL.turmericBright
            : light > 0.58
            ? PAL.turmeric
            : light > 0.38
            ? PAL.chartreuse
            : light > 0.2
            ? PAL.parrotGreen
            : PAL.deepTeal;
        brush.set("microPen", col, 0.38);
        brush.line(x1, y1, x2, y2);
      }
    }
  }

  // Natural guava skin lenticels (tiny russet & pale speckles)
  for (let i = 0; i < 65; i++) {
    let sx = skinCx + random(-80, 80);
    let sy = skinCy + random(-70, 70);
    if (pointInPoly(sx, sy, backSkinPoly)) {
      brush.set("microPen", i % 2 === 0 ? PAL.barkDark : PAL.barbsHighlight, 0.42);
      brush.circle(sx, sy, random(1.2, 2.5), 0.2);
    }
  }

  drawMadhubaniDoubleOutline(backSkinCtrl, {
    closed: true,
    gap: 8,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight
  });

  // --------------------------------------------------------------------------
  // PART B: THE MAIN SPLIT GUAVA HALF (OPEN CROSS-SECTION FACING VIEWER)
  // --------------------------------------------------------------------------
  let cx = 775, cy = 745;

  // 1. Lower-right crescent of outer green-gold skin supporting the cut face
  let lowerSkinCtrl = [
    [645, 795],
    [695, 868],
    [785, 892],
    [878, 865],
    [925, 795],
    [920, 710],
    [885, 765],
    [785, 835],
    [685, 815]
  ];
  let lowerSkinPoly = sampleSpline(lowerSkinCtrl, true, 5);
  drawWashPolygon(lowerSkinPoly, PAL.viridianDark, 240, false);

  for (let i = 0; i < 380; i++) {
    let px = random(645, 928);
    let py = random(705, 895);
    if (pointInPoly(px, py, lowerSkinPoly)) {
      let ang = atan2(py - cy, px - cx) + 90;
      let col = px > 800 ? PAL.turmeric : px > 720 ? PAL.parrotGreen : PAL.deepTeal;
      brush.set("microPen", col, 0.38);
      brush.line(px, py, px + cos(ang) * 9, py + sin(ang) * 9);
    }
  }
  drawMadhubaniDoubleOutline(lowerSkinCtrl, {
    closed: true,
    gap: 7.5,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight
  });

  // 2. Cream-Chartreuse Granular Mesocarp Rind Wall
  let outerFaceCtrl = [];
  let innerPulpCtrl = [];
  for (let a = 0; a < 360; a += 30) {
    let radX = 132 + sin(a * 3) * 5;
    let radY = 114 + cos(a * 2) * 5;
    let tilt = -16;
    let ox = radX * cos(a);
    let oy = radY * sin(a);
    let rx = ox * cos(tilt) - oy * sin(tilt);
    let ry = ox * sin(tilt) + oy * cos(tilt);
    outerFaceCtrl.push([cx + rx, cy + ry]);

    let iradX = 102 + sin(a * 4) * 5;
    let iradY = 86 + cos(a * 3) * 5;
    let iox = iradX * cos(a);
    let ioy = iradY * sin(a);
    let irx = iox * cos(tilt) - ioy * sin(tilt);
    let iry = iox * sin(tilt) + ioy * cos(tilt);
    innerPulpCtrl.push([cx + irx, cy + iry]);
  }

  let outerFacePoly = sampleSpline(outerFaceCtrl, true, 5);
  let innerPulpPoly = sampleSpline(innerPulpCtrl, true, 5);

  drawWashPolygon(outerFacePoly, PAL.rindCream, 245, false);

  // Radial granular stone-cell texture across the pale cream-green rind ring
  for (let a = 0; a < 360; a += 2) {
    let tilt = -16;
    for (let s = 0; s < 5; s++) {
      let t = map(s, 0, 5, 0.76, 0.97);
      let radX = 132 * t;
      let radY = 114 * t;
      let ox = radX * cos(a), oy = radY * sin(a);
      let px = cx + ox * cos(tilt) - oy * sin(tilt);
      let py = cy + ox * sin(tilt) + oy * cos(tilt);
      let col = s >= 3 ? PAL.rindChartreuse : s === 2 ? PAL.rindCream : PAL.pulpPink;
      if (a > 120 && a < 260 && s >= 2) col = "#9c9e6b"; // shadow side
      brush.set("microPen", col, 0.36);
      let rAng = a + tilt;
      brush.line(px, py, px + cos(rAng) * 5.5, py + sin(rAng) * 5.5);
    }
  }

  // 3. GLISTENING CORAL-PINK FLESH CAVITY (ENDOCARP)
  drawWashPolygon(innerPulpPoly, PAL.pulpDeep, 245, false);

  // Multi-layered watercolor coral-pink glows for juicy translucency
  let coralMidPoly = innerPulpPoly.map(p => [lerp(cx, p[0], 0.85), lerp(cy, p[1], 0.85)]);
  drawWashPolygon(coralMidPoly, PAL.pulpCoral, 200, true);

  // Radial cellular pulp fibers rendered with fine pen hatching in coral, salmon, rose & crimson
  for (let a = 0; a < 360; a += 1.5) {
    let rMax = 96;
    for (let r = 6; r < rMax; r += 9) {
      let wav = sin(r * 6 + a * 3) * 3;
      let ang = a + wav;
      let x1 = cx + cos(ang) * r * 1.04;
      let y1 = cy + sin(ang) * r * 0.88;
      let x2 = cx + cos(ang) * (r + 8.5) * 1.04;
      let y2 = cy + sin(ang) * (r + 8.5) * 0.88;

      if (pointInPoly(x2, y2, innerPulpPoly)) {
        // Create 4 distinct carpel locule chambers with darker juicy recesses
        let chamberFactor = abs(sin((a + 18) * 2));
        let col;
        if (chamberFactor > 0.55 && r > 22 && r < 74) {
          col = (r + a) % 3 === 0 ? PAL.pulpShadow : PAL.pulpDeep;
        } else if (r < 22) {
          col = PAL.pulpSalmon;
        } else {
          col = (a + r) % 2 === 0 ? PAL.pulpCoral : PAL.pulpPink;
        }
        brush.set("microPen", col, 0.36);
        brush.line(x1, y1, x2, y2);
      }
    }
  }

  // Pale coral-pink septum walls dividing the 4 carpel chambers
  for (let k = 0; k < 4; k++) {
    let sepAng = k * 90 - 18;
    for (let r = 4; r < 85; r += 3) {
      let sx = cx + cos(sepAng + sin(r * 3) * 6) * r * 1.02;
      let sy = cy + sin(sepAng + sin(r * 3) * 6) * r * 0.86;
      brush.set("microPen", PAL.pulpPink, 0.45);
      brush.circle(sx, sy, 3.2, 0.15);
      if (r % 6 === 0) {
        brush.set("microPen", PAL.pulpWet, 0.32);
        brush.line(sx - 2, sy - 1, sx + 2, sy + 1);
      }
    }
  }

  // 4. INDIVIDUALLY RENDERED HYPERREAL GUAVA SEEDS & WET SPECULAR HIGHLIGHTS
  let seedPositions = [];
  for (let k = 0; k < 4; k++) {
    let baseA = k * 90 + 27;
    // Two concentric curved arcs of seeds in each carpel locule
    for (let ring = 0; ring < 2; ring++) {
      let rad = ring === 0 ? 36 : 60;
      let count = ring === 0 ? 7 : 11;
      for (let s = 0; s < count; s++) {
        let aOff = map(s, 0, count - 1, -26, 26);
        let a = baseA + aOff + random(-2.5, 2.5);
        let r = rad + random(-4, 4);
        let sx = cx + cos(a) * r * 1.02;
        let sy = cy + sin(a) * r * 0.86;
        seedPositions.push({ x: sx, y: sy, ang: a + 90 + random(-25, 25) });
      }
    }
  }

  // Render each individual seed with shadow pit, gelatinous pulp aril, amber-ivory coat, and wet glint
  for (let sp of seedPositions) {
    drawHyperrealGuavaSeed(sp.x, sp.y, sp.ang);
  }

  // Glistening wet specular highlights across the moist coral-pink flesh surface
  for (let i = 0; i < 55; i++) {
    let a = random(360);
    let r = random(8, 86);
    let wx = cx + cos(a) * r * 1.0;
    let wy = cy + sin(a) * r * 0.84;
    if (pointInPoly(wx, wy, innerPulpPoly)) {
      brush.set("microPen", PAL.pulpWet, 0.35);
      brush.line(wx, wy, wx + cos(a + 90) * 4.5, wy + sin(a + 90) * 4.5);
      if (i % 3 === 0) {
        brush.set("microPen", PAL.pureWhite, 0.42);
        brush.line(wx, wy, wx + 2.2, wy - 1.2);
      }
    }
  }

  // Strict Madhubani double outlines enclosing both the inner coral pulp and outer guava rim!
  drawMadhubaniDoubleOutline(innerPulpCtrl, {
    closed: true,
    gap: 6,
    dashSpacing: 4,
    outerColor: PAL.vermilionDeep,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilionBright,
    channelColor: PAL.pulpPink,
    weightOuter: 0.48,
    weightInner: 0.42,
    weightDash: 0.32
  });

  drawMadhubaniDoubleOutline(outerFaceCtrl, {
    closed: true,
    gap: 8.5,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight,
    weightOuter: 0.65,
    weightInner: 0.52,
    weightDash: 0.38
  });
}

function drawHyperrealGuavaSeed(x, y, ang) {
  let c = cos(ang), s = sin(ang);
  // 1. Deep crimson-plum socket shadow in wet pulp
  brush.set("rotring", PAL.seedShadow, 0.65);
  brush.line(x - c * 3.5 + 1.2, y - s * 3.5 + 1.5, x + c * 3.5 + 1.2, y + s * 3.5 + 1.5);

  // 2. Translucent glistening coral aril halo
  brush.set("rotring", PAL.pulpSalmon, 0.55);
  brush.line(x - c * 3.8, y - s * 3.8, x + c * 3.8, y + s * 3.8);

  // 3. Hard kidney-shaped seed body in warm amber-ochre & pale ivory
  brush.set("rotring", PAL.seedAmber, 0.62);
  brush.line(x - c * 2.8, y - s * 2.8, x + c * 2.8, y + s * 2.8);

  brush.set("microPen", PAL.seedIvory, 0.48);
  brush.line(x - c * 2.1 - s * 0.6, y - s * 2.1 + c * 0.6, x + c * 2.1 - s * 0.6, y + s * 2.1 + c * 0.6);

  // 4. Micro-contour dark rim
  brush.set("microPen", PAL.pulpShadow, 0.3);
  brush.line(x - c * 2.6 + s * 1.4, y - s * 2.6 - c * 1.4, x + c * 2.6 + s * 1.4, y + s * 2.6 - c * 1.4);

  // 5. Razor-sharp wet specular catchlight
  brush.set("microPen", PAL.pureWhite, 0.45);
  brush.line(x - c * 1.2 - s * 1.0, y - s * 1.2 + c * 1.0, x + c * 0.8 - s * 1.0, y + s * 0.8 + c * 1.0);
}

// ============================================================================
// 6. ROSE-RINGED PARROT: HYPERREAL FEATHER BARBS IN PARROT GREEN & TURMERIC
// ============================================================================

/**
 * Renders a single hyperreal feather with central rachis and individual barbs
 * visible in parrot green, viridian shadow, and glowing turmeric-gold.
 */
function drawHyperrealFeather(cx, cy, len, wid, angleDeg, lightFactor = 0.5, hueShift = 0) {
  let c = cos(angleDeg);
  let s = sin(angleDeg);

  let x0 = cx - c * (len * 0.45);
  let y0 = cy - s * (len * 0.45);
  let x1 = cx + c * (len * 0.55);
  let y1 = cy + s * (len * 0.55);

  // Choose base shadow, mid-vane parrot green, and sunlit tip turmeric colors
  let baseCol = lightFactor < 0.35 ? PAL.shadowIndigo : PAL.deepTeal;
  let midCol =
    hueShift === 1
      ? PAL.napeBlue
      : lightFactor > 0.65
      ? PAL.emeraldMid
      : lightFactor > 0.35
      ? PAL.parrotGreen
      : PAL.viridianDark;
  let tipCol =
    hueShift === 1
      ? PAL.napeLilac
      : lightFactor > 0.72
      ? PAL.turmericBright
      : lightFactor > 0.45
      ? PAL.turmeric
      : PAL.chartreuse;

  let barbSteps = max(7, floor(len / 2.6));
  for (let i = 1; i <= barbSteps; i++) {
    let t = i / barbSteps;
    let rx = lerp(x0, x1, t);
    let ry = lerp(y0, y1, t);
    let env = sin(pow(t, 0.75) * 180);
    let bLen = wid * 0.55 * env;

    // Both left (-1) and right (+1) vanes of the feather
    for (let side of [-1, 1]) {
      let barbAng = angleDeg + side * (38 - t * 14);
      let bc = cos(barbAng);
      let bs = sin(barbAng);

      let mx = rx + bc * (bLen * 0.52);
      let my = ry + bs * (bLen * 0.52);
      let ex = rx + bc * bLen;
      let ey = ry + bs * bLen;

      // Inner half of barb (shadowed base under overlapping feather -> parrot green)
      brush.set("microPen", t < 0.32 ? baseCol : midCol, 0.31);
      brush.line(rx, ry, mx, my);

      // Outer half of barb (parrot green -> glowing turmeric tip)
      let outerC = t > 0.58 || (side === -1 && lightFactor > 0.5) ? tipCol : midCol;
      brush.set("microPen", outerC, 0.28);
      brush.line(mx, my, ex, ey);

      // Extra luminous barb highlight on strongly lit turmeric feathers
      if (lightFactor > 0.78 && t > 0.68 && side === -1 && i % 2 === 0) {
        brush.set("microPen", PAL.barbsHighlight, 0.24);
        brush.line(mx, my, ex, ey);
      }
    }
  }

  // Central feather shaft (rachis)
  brush.set("microPen", lightFactor > 0.6 ? PAL.turmeric : PAL.deepTeal, 0.35);
  brush.line(x0, y0, x1, y1);
}

function renderParrotBodyAndWing() {
  // --------------------------------------------------------------------------
  // A. BREAST, BELLY & VENT PLUMAGE CELL
  // --------------------------------------------------------------------------
  let breastCtrl = [
    [622, 345],
    [658, 435],
    [662, 535],
    [635, 625],
    [575, 705],
    [495, 742],
    [425, 718],
    [410, 610],
    [425, 480],
    [455, 365],
    [540, 345]
  ];
  let breastPoly = sampleSpline(breastCtrl, true, 6);
  drawWashPolygon(breastPoly, PAL.viridianDark, 245, false);

  // Layered rows of overlapping contour feathers across breast & belly
  for (let row = 0; row < 16; row++) {
    let ty = row / 15;
    let yBase = lerp(358, 725, ty);
    let colsInRow = 11;
    for (let col = 0; col < colsInRow; col++) {
      let tx = (col + (row % 2) * 0.5) / colsInRow;
      let fx = lerp(420, 658, tx);
      let fy = yBase + sin(tx * 180) * 14;
      if (pointInPoly(fx, fy, breastPoly)) {
        // 3D cylindrical illumination: right edge (facing guava/light) glows turmeric-gold,
        // middle is lush parrot green, left flank curves into deep twilight teal
        let light = constrain(map(tx, 0.15, 0.92, 0.15, 0.95) - ty * 0.15, 0.1, 0.98);
        let fAng = 95 - (tx - 0.5) * 38;
        drawHyperrealFeather(fx, fy, 36, 24, fAng, light, 0);
      }
    }
  }

  // Strict Madhubani double outline around the breast & belly cell
  drawMadhubaniDoubleOutline(breastCtrl, {
    closed: true,
    gap: 8.5,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight
  });

  // --------------------------------------------------------------------------
  // B. FOLDED WING: PRIMARY FLIGHT FEATHERS (LOWER WING)
  // --------------------------------------------------------------------------
  let primariesCtrl = [
    [435, 555],
    [535, 585],
    [475, 705],
    [390, 815],
    [325, 865],
    [305, 845],
    [345, 715],
    [390, 585]
  ];
  let primariesPoly = sampleSpline(primariesCtrl, true, 5);
  drawWashPolygon(primariesPoly, PAL.shadowIndigo, 245, false);

  // 6 long overlapping primary flight feathers with individual barbs
  for (let p = 0; p < 6; p++) {
    let t = p / 5;
    let sx = lerp(415, 515, t);
    let sy = lerp(575, 595, t);
    let ex = lerp(318, 435, t);
    let ey = lerp(850, 755, t);
    let fLen = dist(sx, sy, ex, ey);
    let fAng = atan2(ey - sy, ex - sx);
    let mx = (sx + ex) * 0.5;
    let my = (sy + ey) * 0.5;
    drawHyperrealFeather(mx, my, fLen, 26, fAng, 0.35 + t * 0.45, p < 2 ? 1 : 0);

    // Crisp dark feather edge & luminous turmeric outer-web rim
    brush.set("rotring", PAL.lampBlack, 0.5);
    brush.line(sx, sy, ex, ey);
    brush.set("microPen", PAL.turmericBright, 0.34);
    brush.line(sx + 3, sy, ex + 3, ey);
  }

  drawMadhubaniDoubleOutline(primariesCtrl, {
    closed: true,
    gap: 7.5,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight
  });

  // --------------------------------------------------------------------------
  // C. FOLDED WING: SCAPULARS, LESSER, MEDIAN & GREATER COVERTS (UPPER WING)
  // --------------------------------------------------------------------------
  let wingCtrl = [
    [445, 295],
    [535, 345],
    [575, 445],
    [555, 565],
    [485, 625],
    [395, 610],
    [365, 505],
    [385, 385]
  ];
  let wingPoly = sampleSpline(wingCtrl, true, 5);
  drawWashPolygon(wingPoly, PAL.deepTeal, 245, false);

  // Overlapping scalloped rows of wing covert feathers, each barb visible
  for (let row = 0; row < 11; row++) {
    let ty = row / 10;
    let yRow = lerp(315, 600, ty);
    let cols = 8;
    for (let col = 0; col < cols; col++) {
      let tx = (col + (row % 2) * 0.5) / cols;
      let fx = lerp(372, 565, tx);
      let fy = yRow + sin(tx * 180) * 12;
      if (pointInPoly(fx, fy, wingPoly)) {
        let light = constrain(0.25 + tx * 0.65 + (1 - abs(ty - 0.35)) * 0.2, 0.15, 0.95);
        let fAng = 112 - tx * 24;
        drawHyperrealFeather(fx, fy, 42, 28, fAng, light, 0);
      }
    }
  }

  drawMadhubaniDoubleOutline(wingCtrl, {
    closed: true,
    gap: 8.5,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight
  });
}

function renderParrotHeadAndBeak() {
  // --------------------------------------------------------------------------
  // A. HEAD, CROWN, CHEEK & NAPE CELL
  // --------------------------------------------------------------------------
  let headCtrl = [
    [450, 275],
    [468, 200],
    [525, 155],
    [605, 162],
    [665, 208],
    [645, 288],
    [615, 335],
    [525, 325]
  ];
  let headPoly = sampleSpline(headCtrl, true, 5);
  drawWashPolygon(headPoly, PAL.viridianDark, 245, false);

  // Radial cranial flow of micro-feathers around eye (600, 242) and over crown
  let eyeX = 598, eyeY = 238;
  for (let ring = 1; ring <= 9; ring++) {
    let rad = ring * 16;
    let count = floor(ring * 7.5);
    for (let k = 0; k < count; k++) {
      let a = (k / count) * 360;
      let fx = eyeX + cos(a) * rad * 1.08;
      let fy = eyeY + sin(a) * rad * 0.88;
      if (pointInPoly(fx, fy, headPoly) && dist(fx, fy, eyeX, eyeY) > 22) {
        // Feathers sweep backward from forehead/lore over crown and cheek
        let flowAng = atan2(fy - (eyeY - 10), fx - (eyeX + 55));
        // Brow & upper crown catch bright turmeric light; nape shifts toward powder blue-lilac
        let isNape = fx < 515 && fy > 215;
        let light = map(fx - fy * 0.6, 300, 520, 0.25, 0.95);
        drawHyperrealFeather(fx, fy, 24, 15, flowAng, constrain(light, 0.2, 0.96), isNape ? 1 : 0);
      }
    }
  }

  // Characteristic thin black lore line from eye to cere
  brush.set("rotring", PAL.lampBlack, 0.65);
  brush.line(618, 232, 662, 215);
  brush.line(618, 235, 662, 218);

  drawMadhubaniDoubleOutline(headCtrl, {
    closed: true,
    gap: 8,
    dashSpacing: 4.2,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight
  });

  // --------------------------------------------------------------------------
  // B. THE ICONIC ROSE & BLACK COLLAR RING (PSITTACULA KRAMERI)
  // --------------------------------------------------------------------------
  let collarCtrl = [
    [442, 268],
    [525, 305],
    [605, 318],
    [632, 305],
    [630, 348],
    [585, 358],
    [505, 342],
    [435, 302]
  ];
  let collarPoly = sampleSpline(collarCtrl, true, 4);
  drawWashPolygon(collarPoly, PAL.lampBlack, 245, false);

  // Upper/anterior half of collar: Velvet Lamp-Black feathers;
  // Lower/posterior half of collar: Vivid Rose-Pink feathers!
  let spineTop = sampleSpline([[442, 268], [525, 305], [605, 318], [632, 305]], false, 3);
  let spineBot = sampleSpline([[435, 302], [505, 342], [585, 358], [630, 348]], false, 3);
  let cCount = min(spineTop.length, spineBot.length);

  for (let i = 0; i < cCount; i++) {
    let t = i / cCount;
    let tx = spineTop[i][0], ty = spineTop[i][1];
    let bx = spineBot[i][0], by = spineBot[i][1];
    let mx = lerp(tx, bx, 0.48);
    let my = lerp(ty, by, 0.48);

    // Velvet black throat/cheek band with indigo sheen barbs
    brush.set("microPen", PAL.lampBlack, 0.45);
    brush.line(tx, ty, mx, my);
    if (i % 2 === 0) {
      brush.set("microPen", PAL.napeBlue, 0.28);
      brush.line(tx, ty, lerp(tx, mx, 0.6), lerp(ty, my, 0.6));
    }

    // Glowing Rose-Pink nape/collar band (broadest on the left/nape side)
    let roseCol = i % 3 === 0 ? PAL.collarPinkLight : i % 2 === 0 ? PAL.collarRose : PAL.collarPinkDeep;
    brush.set("microPen", roseCol, 0.42);
    brush.line(mx, my, bx, by);
    if (t < 0.75) {
      brush.set("microPen", PAL.collarPinkLight, 0.32);
      brush.line(lerp(mx, bx, 0.3), lerp(my, by, 0.3), bx - 2, by + 1);
    }
  }

  drawMadhubaniDoubleOutline(collarCtrl, {
    closed: true,
    gap: 6.5,
    dashSpacing: 3.8,
    outerColor: PAL.lampBlack,
    innerColor: PAL.vermilion,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilionBright,
    channelColor: PAL.channelLight,
    weightOuter: 0.55,
    weightInner: 0.45,
