  });

  // --------------------------------------------------------------------------
  // C. THE HOOKED BEAK (LOWER MANDIBLE & GLOSSY CORAL-RUBY UPPER MANDIBLE)
  // --------------------------------------------------------------------------
  // 1. Lower Mandible (Dark Horn / Mahogany)
  let lowerBeakCtrl = [
    [622, 305],
    [668, 298],
    [695, 322],
    [662, 345],
    [625, 338]
  ];
  let lowerBeakPoly = sampleSpline(lowerBeakCtrl, true, 4);
  drawWashPolygon(lowerBeakPoly, PAL.lampBlack, 245, false);

  for (let i = 0; i < 24; i++) {
    let t = i / 24;
    let x1 = lerp(625, 668, t);
    let y1 = lerp(335, 302, t);
    let x2 = lerp(662, 692, t);
    let y2 = lerp(343, 322, t);
    brush.set("microPen", i % 3 === 0 ? PAL.barkLight : PAL.beakShadow, 0.36);
    brush.line(x1, y1, x2, y2);
  }
  drawMadhubaniDoubleOutline(lowerBeakCtrl, {
    closed: true,
    gap: 5.5,
    dashSpacing: 3.8,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    channelColor: PAL.channelLight,
    weightOuter: 0.5,
    weightInner: 0.42,
    weightDash: 0.3
  });

  // 2. Upper Mandible (Deep Carmine, Vermilion-Scarlet & Glossy Specular Ridge)
  let upperBeakCtrl = [
    [662, 206],
    [712, 224],
    [746, 265],
    [748, 318],
    [722, 362],
    [705, 322],
    [678, 302],
    [638, 292],
    [645, 245]
  ];
  let upperBeakPoly = sampleSpline(upperBeakCtrl, true, 4);
  drawWashPolygon(upperBeakPoly, PAL.beakCrimson, 245, false);

  // Curved keratin growth lines & glossy 3D shading from culmen ridge to cutting tomium
  let culmenArc = sampleSpline([[662, 206], [712, 224], [746, 265], [748, 318], [722, 362]], false, 3);
  let tomiumArc = sampleSpline([[642, 260], [638, 292], [678, 302], [705, 322], [722, 362]], false, 3);
  let bSteps = min(culmenArc.length, tomiumArc.length);

  for (let i = 0; i < bSteps; i++) {
    let cx1 = culmenArc[i][0], cy1 = culmenArc[i][1];
    let tx1 = tomiumArc[i][0], ty1 = tomiumArc[i][1];
    for (let s = 0; s <= 8; s++) {
      let u = s / 8;
      let px = lerp(cx1, tx1, u);
      let py = lerp(cy1, ty1, u);
      let col =
        u < 0.18
          ? PAL.beakOrange
          : u < 0.35
          ? PAL.beakGloss
          : u < 0.65
          ? PAL.beakScarlet
          : u < 0.85
          ? PAL.beakCrimson
          : PAL.beakShadow;
      brush.set("microPen", col, 0.42);
      if (i < bSteps - 1) {
        let nx = lerp(culmenArc[i + 1][0], tomiumArc[i + 1][0], u);
        let ny = lerp(culmenArc[i + 1][1], tomiumArc[i + 1][1], u);
        brush.line(px, py, nx, ny);
      }
    }
  }

  // Razor-sharp white specular highlight along the polished upper beak ridge
  for (let i = 2; i < bSteps - 3; i++) {
    let hx1 = lerp(culmenArc[i][0], tomiumArc[i][0], 0.24);
    let hy1 = lerp(culmenArc[i][1], tomiumArc[i][1], 0.24);
    let hx2 = lerp(culmenArc[i + 1][0], tomiumArc[i + 1][0], 0.24);
