  brush.circle(658, 224, 7, 0.15);
  brush.set("rotring", PAL.lampBlack, 0.7);
  brush.circle(659, 224, 3.2, 0.1);

  drawMadhubaniDoubleOutline(upperBeakCtrl, {
    closed: true,
    gap: 6.5,
    dashSpacing: 4,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight,
    weightOuter: 0.58,
    weightInner: 0.48,
    weightDash: 0.34
  });

  // --------------------------------------------------------------------------
  // D. PHOTOGRAPHIC EYE WITH PERIORBITAL MADHUBANI RING
  // --------------------------------------------------------------------------
  let eyeRingCtrl = [];
  for (let a = 0; a < 360; a += 30) {
    eyeRingCtrl.push([eyeX + cos(a) * 21, eyeY + sin(a) * 19.5]);
  }
  drawMadhubaniDoubleOutline(eyeRingCtrl, {
    closed: true,
    gap: 5.5,
    dashSpacing: 3.5,
    outerColor: PAL.lampBlack,
    innerColor: PAL.vermilion,
    dashColor: PAL.lampBlack,
    channelColor: PAL.eyeRing,
    weightOuter: 0.52,
    weightInner: 0.45,
    weightDash: 0.32
  });

  // Iris base
  let irisPoly = [];
  for (let a = 0; a < 360; a += 20) {
    irisPoly.push([eyeX + cos(a) * 14.5, eyeY + sin(a) * 14.5]);
  }
  drawWashPolygon(irisPoly, PAL.irisGold, 250, false);

  // Radial iris fibers in amber, orange-gold & cream
  for (let a = 0; a < 360; a += 6) {
    let c = a % 12 === 0 ? PAL.beakOrange : PAL.turmericBright;
    brush.set("microPen", c, 0.32);
    brush.line(eyeX + cos(a) * 6.5, eyeY + sin(a) * 6.5, eyeX + cos(a) * 14, eyeY + sin(a) * 14);
  }

  // Deep obsidian pupil
  let pupilPoly = [];
  for (let a = 0; a < 360; a += 24) {
    pupilPoly.push([eyeX + cos(a) * 7.2, eyeY + sin(a) * 7.2]);
  }
  drawWashPolygon(pupilPoly, PAL.lampBlack, 255, false);
  brush.set("rotring", PAL.lampBlack, 0.85);
  brush.circle(eyeX, eyeY, 6.8, 0.05);
  brush.circle(eyeX, eyeY, 14.5, 0.05);

  // Double corneal specular catchlight
  brush.set("rotring", PAL.pureWhite, 0.95);
  brush.circle(eyeX + 4.2, eyeY - 4.2, 2.8, 0.05);
  brush.line(eyeX + 3, eyeY - 5, eyeX + 5.5, eyeY - 3);
  brush.set("microPen", PAL.pureWhite, 0.55);
  brush.circle(eyeX - 4.5, eyeY + 4.2, 1.4, 0.05);
}

