function renderParrotTalons() {
  // Left Foot gripping the wooden branch around (505, 758)
  drawScalyToe([[488, 728], [472, 752], [462, 782]], [-8, 22], 14);
  drawScalyToe([[505, 730], [502, 758], [498, 792]], [2, 24], 15);
  drawScalyToe([[522, 728], [532, 755], [538, 785]], [12, 22], 13);

  // Right Foot reaching forward to grip the split guava rind around (605, 645)
  drawScalyToe([[568, 668], [595, 642], [625, 628]], [18, -14], 14);
  drawScalyToe([[572, 682], [608, 668], [642, 662]], [22, -4], 15);
  drawScalyToe([[565, 696], [598, 695], [628, 702]], [20, 10], 13);
}

function drawScalyToe(spinePts, clawVec, widthPx) {
  let spine = sampleSpline(spinePts, false, 4);
  let normals = computeCurveNormals(spine, false);
  let leftEdge = [];
  let rightEdge = [];

  for (let i = 0; i < spine.length; i++) {
    let t = i / (spine.length - 1);
    let w = widthPx * (1 - t * 0.32) * 0.5;
    leftEdge.push([spine[i][0] + normals[i][0] * w, spine[i][1] + normals[i][1] * w]);
    rightEdge.push([spine[i][0] - normals[i][0] * w, spine[i][1] - normals[i][1] * w]);
  }
  let toePoly = leftEdge.concat(rightEdge.reverse());
  drawWashPolygon(toePoly, PAL.scaleDark, 245, false);

  // Individual overlapping keratin scutes (scales) along the toe
  for (let i = 1; i < spine.length - 1; i += 2) {
    let pL = leftEdge[i];
    let pR = rightEdge[ rightEdge.length - 1 - i ];
    let mx = spine[i][0], my = spine[i][1];

    brush.set("rotring", PAL.lampBlack, 0.55);
    brush.line(pL[0], pL[1], pR[0], pR[1]);

    brush.set("microPen", PAL.scaleMid, 0.45);
    brush.line(pL[0], pL[1] - 1.5, mx, my - 2);

    brush.set("microPen", PAL.scaleLight, 0.42);
    brush.line(mx - 2, my - 2.2, pR[0] - 1, pR[1] - 1.5);
  }

  // Curved black-horn talon claw at tip of toe
  let tip = spine[spine.length - 1];
  let clawEnd = [tip[0] + clawVec[0], tip[1] + clawVec[1]];
  let clawMid = [
    (tip[0] + clawEnd[0]) * 0.5 - clawVec[1] * 0.25,
    (tip[1] + clawEnd[1]) * 0.5 + clawVec[0] * 0.25
  ];
  brush.set("rotring", PAL.lampBlack, 0.95);
  brush.line(tip[0], tip[1], clawMid[0], clawMid[1]);
  brush.line(clawMid[0], clawMid[1], clawEnd[0], clawEnd[1]);
  brush.set("microPen", PAL.scaleLight, 0.42);
  brush.line(tip[0], tip[1] - 1.5, clawMid[0], clawMid[1] - 1.5);

  // Madhubani double outline around the toe
  drawMadhubaniDoubleOutline(toePoly, {
    closed: true,
    gap: 5,
    dashSpacing: 3.8,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilion,
    channelColor: PAL.channelLight,
    weightOuter: 0.48,
    weightInner: 0.4,
    weightDash: 0.3
  });
}

// ============================================================================
// 8. STRICT MADHUBANI DOUBLE-LINED GEOMETRIC OUTER FRAME
// ============================================================================

function renderMadhubaniOuterFrame() {
  // Frame margin masks to ensure razor-sharp edges around the 56..1144 field
  let m = 56;
  let o = 14;
  let bands = [
    [[0, 0], [1200, 0], [1200, m], [0, m]],
    [[0, 1200 - m], [1200, 1200 - m], [1200, 1200], [0, 1200]],
    [[0, m], [m, m], [m, 1200 - m], [0, 1200 - m]],
    [[1200 - m, m], [1200, m], [1200, 1200 - m], [1200 - m, 1200 - m]]
  ];
  for (let b of bands) {
    drawWashPolygon(b, PAL.groundDark, 248, false);
  }

  // Alternating geometric chevron & leaf-petal frieze inside the 4 border channels
  let step = 36;
  for (let pos = m; pos < 1200 - m; pos += step) {
    let next = min(1200 - m, pos + step);
    let mid = (pos + next) * 0.5;

    // Top border chevron & katchni hatching
    drawFrameChevron(pos, m - 6, mid, o + 6, next, m - 6);
    // Bottom border chevron
    drawFrameChevron(pos, 1200 - m + 6, mid, 1200 - o - 6, next, 1200 - m + 6);
    // Left border chevron
    drawFrameChevronVert(m - 6, pos, o + 6, mid, m - 6, next);
    // Right border chevron
    drawFrameChevronVert(1200 - m + 6, pos, 1200 - o - 6, mid, 1200 - m + 6, next);
  }

  // Corner lotus mandala Rosettes
  let corners = [
    [35, 35],
    [1165, 35],
    [1165, 1165],
    [35, 1165]
  ];
  for (let c of corners) {
    for (let a = 0; a < 360; a += 30) {
      brush.set("rotring", a % 60 === 0 ? PAL.vermilionBright : PAL.channelLight, 0.45);
      brush.line(c[0], c[1], c[0] + cos(a) * 18, c[1] + sin(a) * 18);
    }
    brush.set("rotring", PAL.lampBlack, 0.65);
    brush.circle(c[0], c[1], 18, 0.05);
    brush.set("rotring", PAL.vermilionBright, 0.65);
    brush.circle(c[0], c[1], 8, 0.05);
  }

  // Inner and Outer Madhubani double outlines framing the entire artwork
  let innerFrame = [[m, m], [1200 - m, m], [1200 - m, 1200 - m], [m, 1200 - m]];
  let outerFrame = [[o, o], [1200 - o, o], [1200 - o, 1200 - o], [o, 1200 - o]];

  drawMadhubaniDoubleOutline(innerFrame, {
    closed: true,
    gap: 8,
    dashSpacing: 4.5,
    outerColor: PAL.lampBlack,
    innerColor: PAL.vermilion,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilionBright,
    channelColor: PAL.channelLight,
    weightOuter: 0.65,
    weightInner: 0.55,
    weightDash: 0.38
  });

  drawMadhubaniDoubleOutline(outerFrame, {
    closed: true,
    gap: 8,
    dashSpacing: 4.5,
    outerColor: PAL.lampBlack,
    innerColor: PAL.lampBlack,
    dashColor: PAL.lampBlack,
    altDashColor: PAL.vermilionBright,
    channelColor: PAL.channelLight,
    weightOuter: 0.65,
    weightInner: 0.55,
    weightDash: 0.38
  });
}

function drawFrameChevron(x1, y1, xm, ym, x2, y2) {
  for (let s = 1; s <= 5; s++) {
    let t = s / 5;
    let col = s % 2 === 0 ? PAL.vermilionBright : PAL.channelLight;
    brush.set("rotring", col, 0.4);
    brush.line(lerp(xm, x1, t), lerp(ym, y1, t), xm, lerp(y1, ym, t));
    brush.line(xm, lerp(y1, ym, t), lerp(xm, x2, t), lerp(ym, y2, t));
  }
}

function drawFrameChevronVert(x1, y1, xm, ym, x2, y2) {
  for (let s = 1; s <= 5; s++) {
    let t = s / 5;
    let col = s % 2 === 0 ? PAL.vermilionBright : PAL.channelLight;
    brush.set("rotring", col, 0.4);
    brush.line(lerp(xm, x1, t), lerp(ym, y1, t), lerp(x1, xm, t), ym);
    brush.line(lerp(x1, xm, t), ym, lerp(xm, x2, t), lerp(ym, y2, t));
  }
}

