// =============================================================================
// GEOMETRY & STATE HELPERS
// =============================================================================

function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
  brush.noClip();
}

function safeShape(pts, curvature = 0.2, close = true) {
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (
      clean.length === 0 ||
      dist(p[0], p[1], clean[clean.length - 1][0], clean[clean.length - 1][1]) > 1.5
    ) {
      clean.push(p);
    }
  }
  if (
    close &&
    clean.length > 2 &&
    dist(clean[0][0], clean[0][1], clean[clean.length - 1][0], clean[clean.length - 1][1]) <= 1.5
  ) {
    clean.pop();
  }
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(close);
}

function safeSpline(pts, curvature = 0.5) {
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (
      clean.length === 0 ||
      dist(p[0], p[1], clean[clean.length - 1][0], clean[clean.length - 1][1]) > 1.5
    ) {
      clean.push(p);
    }
  }
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
    return;
  }
  brush.spline(clean, curvature);
}

function ellipsePoints(cx, cy, rx, ry, startDeg, endDeg, steps) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(startDeg, endDeg, i / steps);
    pts.push([cx + rx * cos(a), cy + ry * sin(a)]);
  }
  return pts;
}

// Draws a cut-edge theatrical flat profile strip (bright gold on downward edges, plum on upward edges)
function drawCutEdgeBevel(pts, thickness = 6, isUnderlit = true) {
  if (pts.length < 2) return;
  for (let i = 0; i < pts.length - 1; i++) {
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let dx = p2[0] - p1[0];
    let dy = p2[1] - p1[1];
    let len = sqrt(dx * dx + dy * dy);
    if (len < 1) continue;
    // Normal vector
    let nx = -dy / len;
    let ny = dx / len;
    // Determine if this edge segment faces downward (toward the footlights at y = 1200)
    let facesDown = isUnderlit ? ny > -0.15 : ny < 0.15;
    let bevelCol = facesDown ? PAL.paleGold : PAL.deepViolet;
    let rimCol = facesDown ? PAL.specWhite : PAL.midnightWine;

    brush.set("marker", bevelCol, map(thickness, 3, 10, 0.35, 0.75));
    brush.line(p1[0] + nx * 2, p1[1] + abs(ny) * 2, p2[0] + nx * 2, p2[1] + abs(ny) * 2);

    brush.set("rotring", rimCol, 0.32);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// =============================================================================
// 1. DEEP OPERA BACKCLOTH (SCENIC WATERCOLOUR & SCUMBLED DRY-BRUSH)
// =============================================================================

function drawScenicBackcloth() {
  resetBrush();

  // Broad watercolour atmospheric bands (rose-violet top grading to pale gold footlight horizon)
  let bands = [
    { y1: 0, y2: 240, col: PAL.midnightWine, op: 155, bleed: 0.45 },
    { y1: 160, y2: 400, col: PAL.deepViolet, op: 145, bleed: 0.48 },
    { y1: 310, y2: 550, col: PAL.operaPlum, op: 135, bleed: 0.45 },
    { y1: 460, y2: 690, col: PAL.damaskRose, op: 125, bleed: 0.42 },
    { y1: 600, y2: 820, col: PAL.terracotta, op: 115, bleed: 0.4 },
    { y1: 710, y2: 950, col: PAL.coralRose, op: 110, bleed: 0.38 },
    { y1: 790, y2: 1080, col: PAL.amberGold, op: 120, bleed: 0.42 },
    { y1: 860, y2: 1180, col: PAL.brightGold, op: 130, bleed: 0.4 }
  ];

  for (let b of bands) {
    resetBrush();
    brush.fill(b.col, b.op);
    brush.fillBleed(b.bleed, "out");
    brush.fillTexture(0.65, 0.28);
    let pts = [
      [30, b.y1],
      [320, b.y1 + random(-18, 18)],
      [600, b.y1 + random(-22, 12)],
      [880, b.y1 + random(-18, 18)],
      [1170, b.y1],
      [1170, b.y2],
      [880, b.y2 + random(-15, 20)],
      [600, b.y2 + random(-15, 22)],
      [320, b.y2 + random(-15, 20)],
      [30, b.y2]
    ];
    safeShape(pts, 0.25, true);
  }

  // Central footlight halo blooming on the backcloth behind the cake
  resetBrush();
  brush.fill(PAL.paleGold, 130);
  brush.fillBleed(0.5, "out");
  brush.fillTexture(0.5, 0.2);
  brush.circle(600, 760, 290, 0.25);

  // Distant painted arcade & patisserie salon mirrors on the backcloth
  let archCenters = [340, 600, 860];
  for (let i = 0; i < archCenters.length; i++) {
    let ax = archCenters[i];
    let aw = i === 1 ? 190 : 155;
    let ayTop = i === 1 ? 235 : 265;
    let ayBot = 740;

    // Arch shadow top (rose-violet)
    resetBrush();
    brush.wash(PAL.deepViolet, 75);
    let archPts = [];
    for (let a = 180; a <= 360; a += 15) {
      archPts.push([ax + (aw / 2) * cos(a), ayTop + (aw / 2) * sin(a)]);
    }
    archPts.push([ax + aw / 2, ayBot - 160]);
    archPts.push([ax - aw / 2, ayBot - 160]);
    safeShape(archPts, 0.15, true);

    // Arch lower limelight glow
    resetBrush();
    brush.wash(PAL.brightGold, 65);
    brush.rect(ax - aw / 2 + 10, ayBot - 220, aw - 20, 210, "corner");

    // Scumbled dry-brush mullions & classical molding on the painted cloth
    resetBrush();
    brush.set("scumble", PAL.paleGold, 0.7);
    brush.arc(ax, ayTop, aw / 2 + 8, 185, 355);
    brush.set("charcoal", PAL.operaPlum, 0.55);
    brush.arc(ax, ayTop - 6, aw / 2 + 14, 185, 355);

    // Painted radial fanlight ribs
    for (let a = 205; a <= 335; a += 26) {
      brush.set("cpencil", PAL.peachBlush, 0.45);
      brush.line(
        ax + 18 * cos(a),
        ayTop + 18 * sin(a),
        ax + (aw / 2) * cos(a),
        ayTop + (aw / 2) * sin(a)
      );
    }

    // Painted chandelier silhouette in each arch catching golden under-light
    let cy = ayTop + 65;
    brush.set("cpencil", PAL.operaPlum, 0.45);
    brush.line(ax, ayTop - aw / 2, ax, cy);
    for (let k = -2; k <= 2; k++) {
      let cx = ax + k * 22;
      let armY = cy + abs(k) * 5;
      brush.set("scumble", PAL.paleGold, 0.45);
      brush.line(ax, cy, cx, armY);
      brush.set("rotring", PAL.specWhite, 0.35);
      brush.circle(cx, armY - 6, 4, 0.2);
    }
  }

  // Theatrical dry-brush scumbling across the backcloth to give chalky scenic softness
  resetBrush();
  for (let i = 0; i < 65; i++) {
    let sx = random(80, 1120);
    let sy = random(90, 820);
    let len = random(60, 180);
    let isLower = sy > 520;
    let col = isLower
      ? random([PAL.paleGold, PAL.amberGold, PAL.peachBlush])
      : random([PAL.operaPlum, PAL.damaskRose, PAL.terracotta]);
    brush.set("scumble", col, random(0.45, 0.95));
    let ang = random(-8, 8);
    brush.line(sx, sy, sx + len * cos(ang), sy + len * sin(ang));
  }
}

// =============================================================================
// 2 & 4. HANGING GAUZE SCRIM VEILS (TRANSLUCENT WASHES & FINE NET WEAVE)
// =============================================================================

function drawGauzeScrim(layerIndex, x1, y1, x2, y2, density) {
  resetBrush();
  let w = x2 - x1;
  let h = y2 - y1;

  // Upper rose-violet gauze veil wash
  brush.wash(PAL.operaPlum, layerIndex === 1 ? 22 : 16);
  brush.rect(x1, y1, w, h * 0.52, "corner");

  // Lower pale-gold limelight gauze veil wash (catches upward footlight)
  brush.wash(PAL.paleGold, layerIndex === 1 ? 30 : 24);
  brush.rect(x1, y1 + h * 0.42, w, h * 0.58, "corner");

  // Fine vertical theatrical gauze threads (tulle/bobbinet)
  let step = layerIndex === 1 ? 18 : 22;
  for (let x = x1 + 15; x < x2 - 15; x += step) {
    // Distance from center limelight determines how bright the gauze thread glows
    let centerFactor = 1 - abs(x - 600) / 600;
    let yMid = lerp(580, 460, centerFactor);

    // Upper thread in dusty rose-mauve
    brush.set("2H", PAL.peachBlush, 0.16 * density);
    brush.line(x, y1 + 20, x + random(-2, 2), yMid);

    // Lower thread catching golden limelight
    brush.set("2H", PAL.paleGold, (0.18 + centerFactor * 0.12) * density);
    brush.line(x + random(-2, 2), yMid - 20, x, y2 - 20);
  }

  // Draped catenary fold lines across the hanging scrim
  let foldCount = layerIndex === 1 ? 7 : 9;
  for (let f = 0; f < foldCount; f++) {
    let fy = map(f, 0, foldCount - 1, 160, 880);
    let sag = map(fy, 160, 880, 35, 75);
    let col = fy > 500 ? PAL.paleGold : PAL.peachBlush;
    let wt = fy > 500 ? 0.24 : 0.18;

    brush.set("2H", col, wt * density);
    let pts = [];
    for (let s = 0; s <= 12; s++) {
      let t = s / 12;
      let px = lerp(x1 + 30, x2 - 30, t);
      let py = fy + sin(t * 180) * sag + sin(t * 540 + f * 30) * 6;
      pts.push([px, py]);
    }
    safeSpline(pts, 0.45);
  }
}

// =============================================================================
// 3. SCENIC FLAT LAYER 1: CUT-EDGE SHELVES & PAINTED APOTHECARY JARS
// =============================================================================

function drawShelfFlatsAndJars() {
  resetBrush();

  // Upward-cast shadow behind the shelf flats
  brush.wash(PAL.midnightWine, 45);
  brush.rect(40, 290, 420, 460, "corner");
  brush.rect(740, 290, 420, 460, "corner");

  // Two receding horizontal shelf levels across the mid-back stage
  // Plus baroque scrolled side-wing frames holding the shelves
  let shelfLevels = [
    { y: 445, thick: 22, xL1: 55, xL2: 475, xR1: 725, xR2: 1145, bridge: true },
    { y: 655, thick: 26, xL1: 45, xL2: 440, xR1: 760, xR2: 1155, bridge: false }
  ];

  // Draw the painted jars FIRST so the shelf lip / brackets can overlap or anchor them cleanly,
  // or draw shelf underside in pale gold and jars sitting on top of the shelf plane.
  for (let sIdx = 0; sIdx < shelfLevels.length; sIdx++) {
    let sh = shelfLevels[sIdx];

    // Left Wing Jars on this shelf
    let leftJarSpecs =
      sIdx === 0
        ? [
            { x: 145, w: 66, h: 125, type: "cylinder", contents: "dragees", col: PAL.coralRose },
            { x: 245, w: 78, h: 145, type: "apothecary", contents: "macarons", col: PAL.amberGold },
            { x: 350, w: 64, h: 115, type: "globe", contents: "violets", col: PAL.damaskRose },
            { x: 435, w: 54, h: 98, type: "cylinder", contents: "sticks", col: PAL.brightGold }
          ]
        : [
            { x: 135, w: 82, h: 148, type: "cloche", contents: "petitsfours", col: PAL.peachBlush },
            { x: 255, w: 72, h: 135, type: "apothecary", contents: "dragees", col: PAL.amberGold },
            { x: 365, w: 68, h: 122, type: "globe", contents: "macarons", col: PAL.coralRose }
          ];

    // Right Wing Jars on this shelf
    let rightJarSpecs =
      sIdx === 0
        ? [
            { x: 765, w: 54, h: 98, type: "cylinder", contents: "sticks", col: PAL.brightGold },
            { x: 850, w: 64, h: 115, type: "globe", contents: "violets", col: PAL.damaskRose },
            { x: 955, w: 78, h: 145, type: "apothecary", contents: "macarons", col: PAL.amberGold },
            { x: 1055, w: 66, h: 125, type: "cylinder", contents: "dragees", col: PAL.coralRose }
          ]
        : [
            { x: 835, w: 68, h: 122, type: "globe", contents: "macarons", col: PAL.coralRose },
            { x: 945, w: 72, h: 135, type: "apothecary", contents: "dragees", col: PAL.amberGold },
            { x: 1065, w: 82, h: 148, type: "cloche", contents: "petitsfours", col: PAL.peachBlush }
          ];

    // Optional center-bridge jars high behind the cake top
    let bridgeJars =
      sIdx === 0
        ? [
            { x: 525, w: 48, h: 88, type: "apothecary", contents: "dragees", col: PAL.peachBlush },
            { x: 675, w: 48, h: 88, type: "apothecary", contents: "dragees", col: PAL.peachBlush }
          ]
        : [];

    let allJars = leftJarSpecs.concat(rightJarSpecs).concat(bridgeJars);
    for (let j of allJars) {
      drawScenicJarFlat(j.x, sh.y, j.w, j.h, j.type, j.contents, j.col);
    }

    // Now draw the cut-edge shelf plane itself:
    // Top edge in rose-violet shadow, underside & scrolled brackets glowing in pale gold!
    let segments = sh.bridge
      ? [[sh.xL1, sh.xR2]]
      : [
          [sh.xL1, sh.xL2],
          [sh.xR1, sh.xR2]
        ];

    for (let seg of segments) {
      let sx1 = seg[0];
      let sx2 = seg[1];
      let sw = sx2 - sx1;

      // 1. Top surface of shelf board (falls into rose-violet shadow)
      resetBrush();
      brush.fill(PAL.deepViolet, 165);
      brush.fillBleed(0.18, "out");
      brush.fillTexture(0.55, 0.35);
      brush.rect(sx1, sh.y - 7, sw, 9, "corner");

      // 2. Underside of shelf board (glows luminous pale gold from limelight below!)
      resetBrush();
      brush.fill(PAL.paleGold, 195);
      brush.fillBleed(0.22, "out");
      brush.fillTexture(0.45, 0.3);
      brush.rect(sx1, sh.y + 2, sw, sh.thick, "corner");

      // Warm amber transition strip across middle of shelf edge
      resetBrush();
      brush.wash(PAL.amberGold, 120);
      brush.rect(sx1, sh.y, sw, 8, "corner");

      // Scalloped cut-edge paper/wood trim along the bottom of the shelf
      let scallopStep = 28;
      let scallopPts = [];
      for (let x = sx1; x <= sx2; x += scallopStep) {
        scallopPts.push([x, sh.y + sh.thick]);
        if (x + scallopStep / 2 <= sx2) {
          scallopPts.push([x + scallopStep / 2, sh.y + sh.thick + 9]);
        }
      }
      drawCutEdgeBevel(scallopPts, 5, true);

      // Ornate cut-edge corbel brackets under the shelf catching golden limelight
      let bracketXs =
        sw > 600
          ? [sx1 + 65, sx1 + 230, sx1 + 380, sx2 - 380, sx2 - 230, sx2 - 65]
          : [sx1 + 55, sx1 + 195, sx2 - 65];
      for (let bx of bracketXs) {
        drawShelfBracketFlat(bx, sh.y + sh.thick, 26, 52);
      }

      // Crisp stage-flat outlines
      brush.set("rotring", PAL.midnightWine, 0.38);
      brush.line(sx1, sh.y - 7, sx2, sh.y - 7);
      brush.set("rotring", PAL.specWhite, 0.45);
      brush.line(sx1, sh.y + sh.thick, sx2, sh.y + sh.thick);
    }
  }
}

function drawScenicJarFlat(cx, shelfY, w, h, type, contents, baseCol) {
  let topY = shelfY - h;
  let hw = w / 2;

  // 1. Upward-cast scenic shadow behind the jar flat on the backdrop
  resetBrush();
  brush.wash(PAL.midnightWine, 55);
  brush.rect(cx - hw - 5, topY - 26, w + 10, h + 16, "corner");

  // 2. Jar lower body wash (glowing pale gold & warm amber from footlights below)
  resetBrush();
  brush.fill(PAL.paleGold, 150);
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.55, 0.3);
  if (type === "globe") {
    brush.circle(cx, shelfY - h * 0.45, hw * 1.05, 0.15);
  } else {
    brush.rect(cx - hw, shelfY - h * 0.62, w, h * 0.6, "corner");
  }

  // 3. Jar upper shoulder & lid wash (falling into rose-violet shadow at top)
  resetBrush();
  brush.fill(PAL.operaPlum, 145);
  brush.fillBleed(0.3, "in");
  brush.fillTexture(0.6, 0.35);
  brush.rect(cx - hw * 0.88, topY, w * 1.76 * 0.5, h * 0.48, "corner");

  // 4. Painted confectionery contents inside the jar (scumbled dry-brush & watercolour dots)
  resetBrush();
  if (contents === "dragees" || contents === "violets") {
    let rows = 5;
    for (let r = 0; r < rows; r++) {
      let py = map(r, 0, rows - 1, shelfY - 14, shelfY - h * 0.68);
      let isLit = r < 2;
      let dotCol = isLit
        ? random([PAL.paleGold, PAL.brightGold, PAL.peachBlush])
        : random([baseCol, PAL.damaskRose, PAL.operaPlum]);
      for (let c = -2; c <= 2; c++) {
        let px = cx + c * (w * 0.16) + (r % 2) * 4;
        brush.wash(dotCol, 155);
        brush.circle(px, py, w * 0.09, 0.2);
      }
    }
  } else if (contents === "macarons") {
    for (let stack = -1; stack <= 1; stack++) {
      let sx = cx + stack * (w * 0.26);
      for (let m = 0; m < 4; m++) {
        let my = shelfY - 14 - m * 18;
        let mCol = m < 2 ? PAL.brightGold : m === 2 ? baseCol : PAL.operaPlum;
        brush.set("marker", mCol, 0.55);
        brush.line(sx - 9, my, sx + 9, my);
        brush.set("rotring", PAL.paleGold, 0.28);
        brush.line(sx - 9, my + 3, sx + 9, my + 3);
      }
    }
  } else if (contents === "sticks") {
    for (let s = -3; s <= 3; s++) {
      let sx1 = cx + s * (w * 0.11);
      let sx2 = cx + s * (w * 0.08) + 6;
      brush.set("cpencil", s % 2 === 0 ? PAL.paleGold : PAL.coralRose, 0.5);
      brush.line(sx1, shelfY - 8, sx2, topY + 22);
    }
  } else if (contents === "petitsfours") {
    // Tiered stand inside bell cloche
    brush.set("rotring", PAL.paleGold, 0.4);
    brush.line(cx - hw * 0.7, shelfY - h * 0.38, cx + hw * 0.7, shelfY - h * 0.38);
    brush.line(cx, shelfY - 6, cx, shelfY - h * 0.65);
    for (let p = -1; p <= 1; p++) {
      brush.wash(PAL.brightGold, 165);
      brush.rect(cx + p * 18 - 6, shelfY - h * 0.38 - 14, 12, 12, "corner");
      brush.wash(PAL.damaskRose, 155);
      brush.rect(cx + p * 14 - 5, shelfY - h * 0.65 - 12, 10, 10, "corner");
    }
  }

  // 5. Cut-edge contour & stopper finial (underlit in pale gold, dark plum top)
  // Footed base underside glow
  brush.set("marker", PAL.paleGold, 0.65);
  brush.line(cx - hw * 0.85, shelfY - 3, cx + hw * 0.85, shelfY - 3);
  // Lid overhang underside glow
  brush.set("marker", PAL.paleGold, 0.5);
  brush.line(cx - hw * 0.75, topY + 14, cx + hw * 0.75, topY + 14);
  // Lid finial knob (rose-violet top, golden neck underside)
  resetBrush();
  brush.wash(PAL.deepViolet, 180);
  brush.circle(cx, topY - 8, 9, 0.15);
  brush.set("rotring", PAL.paleGold, 0.38);
  brush.arc(cx, topY - 8, 9, 20, 160);

  // Scumbled glass reflection streaks on the painted flat
  brush.set("scumble", PAL.paleGold, 0.4);
  brush.line(cx - hw + 8, shelfY - 12, cx - hw + 8, topY + 28);
  brush.set("rotring", PAL.deepViolet, 0.35);
  brush.line(cx - hw, shelfY - 6, cx - hw, topY + 16);
  brush.line(cx + hw, shelfY - 6, cx + hw, topY + 16);
}

function drawShelfBracketFlat(bx, topY, w, h) {
  resetBrush();
  let pts = [
    [bx - w / 2, topY],
    [bx + w / 2, topY],
    [bx + w * 0.35, topY + h * 0.45],
    [bx + w * 0.12, topY + h * 0.7],
    [bx, topY + h],
    [bx - w * 0.12, topY + h * 0.7],
    [bx - w * 0.35, topY + h * 0.45]
  ];
  brush.wash(PAL.amberGold, 150);
  safeShape(pts, 0.25, true);
  drawCutEdgeBevel(pts, 4, true);
}

// =============================================================================
// 5. SCENIC FLAT LAYER 2: CUT-EDGE LETTERED AWNINGS & PROSCENIUM WING FLATS
// =============================================================================

function drawAwningAndProsceniumFlats() {
  resetBrush();

  // --- A. RECEDING STRIPED PATISSERIE AWNING FLAT (y = 140..315) ---
  let awnX1 = 110;
  let awnX2 = 1090;
  let awnYTop = 145;
  let awnYBot = 285;
  let numStripes = 19;
  let stripeW = (awnX2 - awnX1) / numStripes;

  // Cast shadow above/behind the awning onto the second scrim
  resetBrush();
  brush.wash(PAL.midnightWine, 65);
  brush.rect(awnX1 - 15, awnYTop - 22, awnX2 - awnX1 + 30, 35, "corner");

  for (let i = 0; i < numStripes; i++) {
    let sx1 = awnX1 + i * stripeW;
    let sx2 = sx1 + stripeW;
    let sxMid = (sx1 + sx2) / 2;

    // Slight perspective fan outward toward bottom of awning slope
    let bx1 = lerp(600, sx1, 1.04);
    let bx2 = lerp(600, sx2, 1.04);
    let bxMid = (bx1 + bx2) / 2;

    // Slight arch across the full window span
    let archOffset = sin((i / (numStripes - 1)) * 180) * -18;
    let yT = awnYTop + archOffset;
    let yB = awnYBot + archOffset;

    let isCreamStripe = i % 2 === 0;

    // 1. Upper portion of each awning stripe (falls into rose-violet shadow)
    resetBrush();
    let topCol = isCreamStripe ? PAL.damaskRose : PAL.deepViolet;
    brush.fill(topCol, 165);
    brush.fillBleed(0.2, "in");
    brush.fillTexture(0.55, 0.3);
    safeShape(
      [
        [sx1, yT],
        [sx2, yT],
        [lerp(sx2, bx2, 0.58), lerp(yT, yB, 0.58)],
        [lerp(sx1, bx1, 0.58), lerp(yT, yB, 0.58)]
      ],
      0.08,
      true
    );

    // 2. Lower portion & scalloped valance (glows pale gold & warm coral from limelight below!)
    resetBrush();
    let botCol = isCreamStripe ? PAL.paleGold : PAL.coralRose;
    brush.fill(botCol, 185);
    brush.fillBleed(0.22, "in");
    brush.fillTexture(0.5, 0.3);
    safeShape(
      [
        [lerp(sx1, bx1, 0.45), lerp(yT, yB, 0.45)],
        [lerp(sx2, bx2, 0.45), lerp(yT, yB, 0.45)],
        [bx2, yB],
        [bxMid, yB + 26],
        [bx1, yB]
      ],
      0.2,
      true
    );

    // 3. Dry-brush theatrical scumbling along the stripe seam
    brush.set("cpencil", PAL.midnightWine, 0.32);
    brush.line(sx1, yT, bx1, yB);

    // 4. Cut-edge golden limelight bevel on the bottom scallop of each stripe!
    brush.set("marker", PAL.paleGold, 0.75);
    brush.line(bx1, yB + 2, bxMid, yB + 27);
    brush.line(bxMid, yB + 27, bx2, yB + 2);
    brush.set("rotring", PAL.specWhite, 0.42);
    brush.line(bx1 + 2, yB + 4, bxMid, yB + 28);
    brush.line(bxMid, yB + 28, bx2 - 2, yB + 4);

    // Little golden tassel hanging between scallops
    brush.set("rotring", PAL.brightGold, 0.38);
    brush.line(bx1, yB, bx1, yB + 14);
    brush.circle(bx1, yB + 16, 2.5, 0.1);
  }

  // --- B. CUT-EDGE LETTERED SIGNBOARD / FASCIA FLAT (y = 55..175) ---
  drawLetteredFasciaFlat();

  // --- C. FOREGROUND BAROQUE CUT-EDGE SIDE WING FLATS (Left & Right Framing Planes) ---
  drawBaroqueSideWingFlats();
}

function drawLetteredFasciaFlat() {
  resetBrush();
  let cx = 600;
  let cy = 112;
  let bw = 740;
  let bh = 86;

  // Build ornate baroque scrolled signboard polygon
  let signPts = [];
  // Top edge (curves gently upward at center, with scrolled ears)
  for (let i = 0; i <= 20; i++) {
    let t = i / 20;
    let x = lerp(cx - bw / 2, cx + bw / 2, t);
    let arch = -sin(t * 180) * 20 + sin(t * 540) * 5;
    signPts.push([x, cy - bh / 2 + arch]);
  }
  // Right scrolled profile edge
  signPts.push([cx + bw / 2 + 24, cy - 12]);
  signPts.push([cx + bw / 2 + 12, cy + 18]);
  // Bottom edge (underlit by limelight!)
  for (let i = 20; i >= 0; i--) {
    let t = i / 20;
    let x = lerp(cx - bw / 2, cx + bw / 2, t);
    let arch = -sin(t * 180) * 16 - sin(t * 540) * 5;
    signPts.push([x, cy + bh / 2 + arch]);
  }
  // Left scrolled profile edge
  signPts.push([cx - bw / 2 - 12, cy + 18]);
  signPts.push([cx - bw / 2 - 24, cy - 12]);

  // 1. Deep rose-violet shadow wash across the upper signboard
  resetBrush();
  brush.fill(PAL.deepViolet, 195);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.35);
  safeShape(signPts, 0.2, true);

  // 2. Warm damask-rose & amber gradient wash on the lower signboard half
  resetBrush();
  brush.wash(PAL.damaskRose, 130);
  brush.rect(cx - bw / 2 + 15, cy - 5, bw - 30, bh * 0.48, "corner");
  brush.wash(PAL.amberGold, 110);
  brush.rect(cx - bw / 2 + 25, cy + 16, bw - 50, bh * 0.25, "corner");

  // 3. Cut-edge bevel around the entire signboard (gold below, dark violet above)
  drawCutEdgeBevel(signPts, 7, true);

  // Inner gilded molding frame
  let innerTop = [];
  let innerBot = [];
  for (let i = 0; i <= 16; i++) {
    let t = i / 16;
    let x = lerp(cx - bw / 2 + 28, cx + bw / 2 - 28, t);
    let archT = -sin(t * 180) * 17;
    let archB = -sin(t * 180) * 14;
    innerTop.push([x, cy - bh / 2 + 11 + archT]);
    innerBot.push([x, cy + bh / 2 - 11 + archB]);
  }
  brush.set("rotring", PAL.operaPlum, 0.45);
  safeSpline(innerTop, 0.3);
  brush.set("marker", PAL.paleGold, 0.55);
  safeSpline(innerBot, 0.3);
  brush.set("rotring", PAL.specWhite, 0.38);
  safeSpline(innerBot, 0.3);

  // 4. STAGE-PAINTED FRENCH LETTERING: "PÂTISSERIE DE L'OPÉRA"
  drawStageText("PÂTISSERIE DE L'OPÉRA", cx, cy + 2, 1.08, 15);

  // 5. Smaller receding side-wing cartouche plaques ("CONFISERIE" & "GLACES")
  drawSidePlaque(195, 345, 210, 48, "CONFISERIE");
  drawSidePlaque(1005, 345, 210, 48, "GLACES");
}

function drawSidePlaque(cx, cy, w, h, label) {
  resetBrush();
  let pts = [
    [cx - w / 2, cy - h / 2],
    [cx + w / 2, cy - h / 2],
    [cx + w / 2 + 12, cy],
    [cx + w / 2, cy + h / 2],
    [cx - w / 2, cy + h / 2],
    [cx - w / 2 - 12, cy]
  ];
  brush.fill(PAL.operaPlum, 175);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.5, 0.3);
  safeShape(pts, 0.15, true);

  brush.wash(PAL.amberGold, 115);
  brush.rect(cx - w / 2 + 8, cy + 4, w - 16, h / 2 - 6, "corner");

  drawCutEdgeBevel(pts, 5, true);
  drawStageText(label, cx, cy + 2, 0.72, 0);
}

// Vector Roman Serif Stage Lettering with upward rose-violet drop shadow and golden bottom serifs
function drawStageText(str, cx, cy, scale, archAmt) {
  let charSpacing = 28 * scale;
  let totalW = (str.length - 1) * charSpacing;
  let startX = cx - totalW / 2;

  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    if (ch === " ") continue;
    let t = str.length > 1 ? i / (str.length - 1) : 0.5;
    let x = startX + i * charSpacing;
    let y = cy - sin(t * 180) * archAmt;

    // Pass 1: Upward-cast rose-violet theatrical drop shadow
    drawGlyph(ch, x - 2, y - 4.5 * scale, scale, PAL.midnightWine, 0.65 * scale, false);
    // Pass 2: Warm honey-gold body
    drawGlyph(ch, x, y, scale, PAL.amberGold, 0.62 * scale, false);
    // Pass 3: Pale gold limelight core & bright bottom serifs
    drawGlyph(ch, x, y + 0.8 * scale, scale, PAL.paleGold, 0.38 * scale, true);
  }
}

function drawGlyph(ch, x, y, s, col, wt, highlightBottom) {
  let w = 9 * s;
  let h = 15 * s;
  brush.set("rotring", col, wt);

  let L = x - w;
  let R = x + w;
  let T = y - h;
  let B = y + h;
  let M = y;

  let base = ch;
  if (ch === "Â") base = "A";
  if (ch === "É") base = "E";

  switch (base) {
    case "P":
      brush.line(L, B, L, T);
      brush.line(L, T, x + w * 0.6, T);
      brush.line(x + w * 0.6, T, R, y - h * 0.5);
      brush.line(R, y - h * 0.5, x + w * 0.6, M);
      brush.line(x + w * 0.6, M, L, M);
      break;
    case "A":
      brush.line(L, B, x, T);
      brush.line(x, T, R, B);
      brush.line(x - w * 0.55, y + h * 0.25, x + w * 0.55, y + h * 0.25);
      break;
    case "T":
      brush.line(L, T, R, T);
      brush.line(x, T, x, B);
      break;
    case "I":
      brush.line(x, T, x, B);
      brush.line(x - w * 0.45, T, x + w * 0.45, T);
      brush.line(x - w * 0.45, B, x + w * 0.45, B);
      break;
    case "S":
      brush.line(R, T + h * 0.25, x, T);
      brush.line(x, T, L, T + h * 0.35);
      brush.line(L, T + h * 0.35, R, B - h * 0.35);
      brush.line(R, B - h * 0.35, x, B);
      brush.line(x, B, L, B - h * 0.25);
      break;
    case "E":
      brush.line(L, T, L, B);
      brush.line(L, T, R, T);
      brush.line(L, M, x + w * 0.55, M);
      brush.line(L, B, R, B);
      break;
    case "R":
      brush.line(L, B, L, T);
      brush.line(L, T, x + w * 0.55, T);
      brush.line(x + w * 0.55, T, R, y - h * 0.5);
      brush.line(R, y - h * 0.5, x + w * 0.55, M);
      brush.line(x + w * 0.55, M, L, M);
      brush.line(x, M, R, B);
      break;
    case "D":
      brush.line(L, T, L, B);
      brush.line(L, T, x + w * 0.4, T);
      brush.line(x + w * 0.4, T, R, M);
      brush.line(R, M, x + w * 0.4, B);
      brush.line(x + w * 0.4, B, L, B);
      break;
    case "L":
      brush.line(L, T, L, B);
      brush.line(L, B, R, B);
      break;
    case "O":
      brush.line(x, T, R, M);
      brush.line(R, M, x, B);
      brush.line(x, B, L, M);
      brush.line(L, M, x, T);
      break;
    case "C":
      brush.line(R, T + h * 0.3, x, T);
      brush.line(x, T, L, M);
      brush.line(L, M, x, B);
      brush.line(x, B, R, B - h * 0.3);
      break;
    case "N":
      brush.line(L, B, L, T);
      brush.line(L, T, R, B);
      brush.line(R, B, R, T);
      break;
    case "F":
      brush.line(L, T, L, B);
      brush.line(L, T, R, T);
      brush.line(L, M, x + w * 0.5, M);
      break;
    case "G":
      brush.line(R, T + h * 0.3, x, T);
      brush.line(x, T, L, M);
      brush.line(L, M, x, B);
      brush.line(x, B, R, B - h * 0.3);
      brush.line(R, B - h * 0.3, R, M);
      brush.line(x, M, R, M);
      break;
    case "'":
      brush.line(x, T - h * 0.1, x - w * 0.3, T + h * 0.35);
      break;
  }

  // Diacritics
  if (ch === "Â") {
    brush.line(x - w * 0.4, T - h * 0.15, x, T - h * 0.42);
    brush.line(x, T - h * 0.42, x + w * 0.4, T - h * 0.15);
  } else if (ch === "É") {
    brush.line(x - w * 0.2, T - h * 0.15, x + w * 0.35, T - h * 0.4);
  }

  // Specular limelight glint along bottom serifs
  if (highlightBottom && base !== "'") {
    brush.set("micro", PAL.specWhite, 0.9);
    brush.line(L - 2 * s, B, R + 2 * s, B);
  }
}

function drawBaroqueSideWingFlats() {
  // Left and Right foreground cut-edge drapery & pilaster flats framing the opera window
  for (let side = -1; side <= 1; side += 2) {
    let xEdge = side === -1 ? 0 : 1200;
    let dir = -side; // +1 for left wing (growing rightward), -1 for right wing

    // Build ornate baroque scrolled wing contour from top (y=0) to stage floor (y=980)
    let wingPts = [[xEdge, 0]];
    let profilePts = [
      [xEdge + dir * 240, 0],
      [xEdge + dir * 215, 110],
      [xEdge + dir * 165, 220],
      [xEdge + dir * 195, 320],
      [xEdge + dir * 135, 430],
      [xEdge + dir * 165, 530],
      [xEdge + dir * 110, 650],
      [xEdge + dir * 145, 760],
      [xEdge + dir * 95, 880],
      [xEdge + dir * 130, 990]
    ];
    for (let p of profilePts) wingPts.push(p);
    wingPts.push([xEdge, 990]);

    // 1. Upper wing wash (deep rose-violet & plum shadow)
    resetBrush();
    brush.fill(PAL.deepViolet, 185);
    brush.fillBleed(0.25, "in");
    brush.fillTexture(0.6, 0.35);
    safeShape(wingPts, 0.25, true);

    // 2. Lower wing wash (glowing amber & pale gold from footlights below)
    resetBrush();
    brush.fill(PAL.amberGold, 155);
    brush.fillBleed(0.32, "in");
    brush.fillTexture(0.55, 0.3);
    let lowerWing = [
      [xEdge, 540],
      [xEdge + dir * 155, 540],
      [xEdge + dir * 110, 650],
      [xEdge + dir * 145, 760],
      [xEdge + dir * 95, 880],
      [xEdge + dir * 130, 990],
      [xEdge, 990]
    ];
    safeShape(lowerWing, 0.22, true);

    // 3. Scumbled dry-brush velvet curtain folds & boiserie panels on the wing flat
    resetBrush();
    for (let f = 0; f < 6; f++) {
      let fx = xEdge + dir * (25 + f * 22);
      brush.set("scumble", PAL.operaPlum, 0.65);
      brush.line(fx, 40, fx + dir * 8, 560);
      brush.set("scumble", PAL.paleGold, 0.55);
      brush.line(fx + dir * 8, 520, fx, 960);
    }

    // 4. Cut-edge bevel along the scrolled inner profile (pale gold on downward scrolls!)
    drawCutEdgeBevel(profilePts, 8, true);

    // 5. Painted golden tassel fringe along the lower cut-outs of the wing flat
    for (let k = 1; k < profilePts.length - 1; k++) {
      let p = profilePts[k];
      if (p[1] > 300) {
        brush.set("marker", PAL.paleGold, 0.55);
        brush.circle(p[0], p[1] + 6, 5, 0.2);
        brush.set("rotring", PAL.specWhite, 0.35);
        brush.line(p[0], p[1], p[0], p[1] + 18);
      }
    }
  }
}

