// =============================================================================
// 8A. HYPERREAL FOREGROUND: ORNATE GILDED PORCELAIN CAKE PEDESTAL
// =============================================================================

function drawHyperrealPedestal() {
  resetBrush();
  let cx = 600;
  let platterY = 858;
  let platterRx = 278;
  let platterRy = 42;
  let footY = 1068;
  let footRx = 185;
  let footRy = 32;

  // 1. Cast shadow on the stage floor behind/above the foot (since footlights are in front-below)
  resetBrush();
  brush.wash(PAL.operaPlum, 85);
  safeShape(ellipsePoints(cx, footY - 12, footRx * 1.08, footRy * 0.95, 0, 360, 28), 0.2, true);

  // 2. Stepped Pedestal Base & Turned Baluster Stem
  // Base dome (glowing pale gold on underside & lower rim, rose-violet on upper curve)
  let basePts = [];
  for (let a = 0; a <= 180; a += 10) {
    basePts.push([cx + footRx * cos(a), footY + footRy * sin(a)]);
  }
  basePts.push([cx - 62, 985]);
  basePts.push([cx + 62, 985]);
  resetBrush();
  brush.fill(PAL.amberGold, 195);
  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.35, 0.25);
  safeShape(basePts, 0.18, true);

  // Upper shadow on the pedestal foot
  resetBrush();
  brush.wash(PAL.operaPlum, 130);
  safeShape(
    [
      [cx - footRx * 0.85, footY - 2],
      [cx - 58, 985],
      [cx + 58, 985],
      [cx + footRx * 0.85, footY - 2]
    ],
    0.2,
    true
  );

  // Turned baluster knop at y = 955
  resetBrush();
  brush.wash(PAL.paleGold, 210);
  brush.circle(cx, 955, 58, 0.08);
  brush.wash(PAL.deepViolet, 140);
  safeShape(ellipsePoints(cx, 942, 56, 20, 180, 360, 16), 0.15, true);

  // Fluted vertical gadrooning on the pedestal foot (razor-sharp lines)
  for (let i = -9; i <= 9; i++) {
    let t = i / 9;
    let bx = cx + footRx * 0.92 * sin(t * 90);
    let by = footY + footRy * 0.92 * cos(t * 90);
    let tx = cx + 48 * sin(t * 90);
    let ty = 985 + 8 * cos(t * 90);
    let isCenter = abs(i) <= 4;
    brush.set("rotring", isCenter ? PAL.specWhite : PAL.honeyOchre, isCenter ? 0.35 : 0.28);
    brush.line(tx, ty, bx, by);
    brush.set("2H", PAL.operaPlum, 0.25);
    brush.line(tx + 3, ty, bx + 4, by);
  }

  // Crisp specular rings on the foot and baluster
  brush.set("marker", PAL.paleGold, 0.65);
  safeSpline(ellipsePoints(cx, footY + 4, footRx, footRy, 15, 165, 20), 0.4);
  brush.set("micro", PAL.specWhite, 1.1);
  safeSpline(ellipsePoints(cx, footY + 5, footRx, footRy, 35, 145, 18), 0.4);
  safeSpline(ellipsePoints(cx, 962, 58, 16, 20, 160, 16), 0.4);

  // 3. Underside of the Grand Platter (catches intense golden limelight from below!)
  let underPlatterPts = [];
  for (let a = 0; a <= 180; a += 8) {
    underPlatterPts.push([cx + platterRx * cos(a), platterY + 18 + platterRy * sin(a)]);
  }
  for (let a = 180; a >= 0; a -= 12) {
    underPlatterPts.push([cx + 68 * cos(a), 925 + 14 * sin(a)]);
  }
  resetBrush();
  brush.fill(PAL.paleGold, 225);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.25, 0.2);
  safeShape(underPlatterPts, 0.15, true);

  // Radial gilded flutes on the underside of the platter
  for (let a = 12; a <= 168; a += 6) {
    let x1 = cx + 55 * cos(a);
    let y1 = 918 + 12 * sin(a);
    let x2 = cx + platterRx * 0.96 * cos(a);
    let y2 = platterY + 16 + platterRy * 0.96 * sin(a);
    let isFront = a > 55 && a < 125;
    brush.set("rotring", isFront ? PAL.specWhite : PAL.amberGold, isFront ? 0.35 : 0.25);
    brush.line(x1, y1, x2, y2);
  }

  // 4. Top Surface of the Platter (porcelain & rose-violet cast shadow from Tier 1)
  resetBrush();
  brush.fill(PAL.operaPlum, 170);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.25, 0.2);
  safeShape(ellipsePoints(cx, platterY, platterRx, platterRy, 0, 360, 36), 0.2, true);

  // Front porcelain rim of the platter catching limelight & gilded openwork lace gallery
  let frontRim = ellipsePoints(cx, platterY, platterRx, platterRy, 5, 175, 32);
  brush.set("marker", PAL.paleGold, 0.85);
  safeSpline(frontRim, 0.4);
  brush.set("micro", PAL.specWhite, 1.2);
  safeSpline(ellipsePoints(cx, platterY + 2, platterRx, platterRy, 25, 155, 26), 0.4);

  // Pierced golden gallery scallops along the front platter lip
  for (let a = 10; a <= 170; a += 5) {
    let px = cx + platterRx * cos(a);
    let py = platterY + platterRy * sin(a);
    brush.set("rotring", PAL.deepViolet, 0.32);
    brush.circle(px, py + 7, 3.5, 0.05);
    brush.set("micro", PAL.specWhite, 0.9);
    brush.arc(px, py + 7, 4, 20, 160);
  }
}

// =============================================================================
// 8B. HYPERREAL FOREGROUND: THREE-TIERED CAKE WITH PIPED ROSETTES & GANACHE
// =============================================================================

function drawHyperrealCake() {
  let cx = 600;

  // Define the 3 cylindrical cake tiers (drawn bottom to top so upper tiers & rosettes sit cleanly)
  let tiers = [
    {
      id: 1,
      yBot: 848,
      yTop: 658,
      rx: 226,
      ryBot: 33,
      ryTop: 28,
      style: "quilted",
      dripCount: 19,
      rosetteCount: 25,
      rosetteR: 15.5
    },
    {
      id: 2,
      yBot: 658,
      yTop: 486,
      rx: 162,
      ryBot: 24,
      ryTop: 20,
      style: "swags",
      dripCount: 15,
      rosetteCount: 19,
      rosetteR: 15
    },
    {
      id: 3,
      yBot: 486,
      yTop: 342,
      rx: 106,
      ryBot: 16,
      ryTop: 14,
      style: "fluted",
      dripCount: 11,
      rosetteCount: 14,
      rosetteR: 14
    }
  ];

  for (let t of tiers) {
    // 1. Cylinder Body with 3D Cylindrical + Limelight-from-Below Shading
    drawCakeTierCylinder(cx, t);

    // 2. Intricate Surface Relief (Quilted Lattice + Sugar Pearls, Royal Icing Swags, or Micro-Fluting)
    if (t.style === "quilted") {
      drawTierQuiltedLattice(cx, t);
    } else if (t.style === "swags") {
      drawTierBaroqueSwags(cx, t);
    } else if (t.style === "fluted") {
      drawTierMicroFluting(cx, t);
    }

    // 3. Glossy Mirror-Glaze Chocolate Ganache Pour & Viscous Drips (5-Pass Hyperreal Speculars)
    drawTierGlossyGanache(cx, t);

    // 4. Ring of Hyperreal Piped Star-Tip Buttercream Rosettes around the Tier Base
    drawTierRosetteRing(cx, t);
  }

  // 5. Crown Topper: Chantilly Rosettes, Glazed Ruby Berries, Chocolate Scrolls & Spun Sugar Dome
  drawCakeCrownTopper(cx, tiers[2]);
}

function drawCakeTierCylinder(cx, t) {
  resetBrush();

  // Construct cylinder boundary polygon
  let cylPts = [];
  for (let a = 0; a <= 180; a += 8) {
    cylPts.push([cx + t.rx * cos(a), t.yBot + t.ryBot * sin(a)]);
  }
  for (let a = 180; a >= 0; a -= 8) {
    cylPts.push([cx + t.rx * cos(a), t.yTop + t.ryTop * sin(a)]);
  }

  // Base warm Chantilly buttercream fill
  brush.fill(PAL.chantilly, 235);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.18, 0.12);
  safeShape(cylPts, 0.1, true);

  // Vertical strips across the cylinder for hyperreal 3D form + bottom limelight gradient
  let numCols = 36;
  for (let i = 0; i < numCols; i++) {
    let a1 = map(i, 0, numCols, 180, 0);
    let a2 = map(i + 1, 0, numCols, 180, 0);
    let aMid = (a1 + a2) / 2;

    let x1 = cx + t.rx * cos(a1);
    let x2 = cx + t.rx * cos(a2);
    let yB1 = t.yBot + t.ryBot * sin(a1);
    let yB2 = t.yBot + t.ryBot * sin(a2);
    let yT1 = t.yTop + t.ryTop * sin(a1);
    let yT2 = t.yTop + t.ryTop * sin(a2);

    // Horizontal cylinder lighting factor: front-center (90 deg) is brightest, sides fall into rose shadow,
    // extreme edges (0..18 and 162..180 deg) catch warm golden rim bounce light!
    let frontFactor = sin(aMid); // 1 at front, 0 at edges
    let rimFactor = pow(1 - frontFactor, 3);

    // Upper half of cylinder strip (falls toward rose-violet shadow under the ganache overhang)
    resetBrush();
    let topCol =
      frontFactor > 0.72
        ? PAL.peachBlush
        : frontFactor > 0.35
        ? PAL.coralRose
        : rimFactor > 0.55
        ? PAL.amberGold
        : PAL.operaPlum;
    let topAlpha = map(frontFactor, 0, 1, 145, 70);
    brush.wash(topCol, topAlpha);
    safeShape(
      [
        [x1, yT1],
        [x2, yT2],
        [x2, lerp(yT2, yB2, 0.58)],
        [x1, lerp(yT1, yB1, 0.58)]
      ],
      0.02,
      true
    );

    // Lower half of cylinder strip (glows luminous pale gold from limelight below!)
    resetBrush();
    let botCol =
      frontFactor > 0.55
        ? PAL.paleGold
        : frontFactor > 0.25
        ? PAL.brightGold
        : PAL.amberGold;
    let botAlpha = map(frontFactor, 0, 1, 95, 165);
    brush.wash(botCol, botAlpha);
    safeShape(
      [
        [x1, lerp(yT1, yB1, 0.45)],
        [x2, lerp(yT2, yB2, 0.45)],
        [x2, yB2],
        [x1, yB1]
      ],
      0.02,
      true
    );
  }

  // Fine cross-contour buttercream combing lines for hyperreal surface tactility
  for (let hFrac = 0.15; hFrac <= 0.88; hFrac += 0.12) {
    let pts = [];
    for (let a = 8; a <= 172; a += 8) {
      let px = cx + t.rx * cos(a);
      let py = lerp(t.yTop + t.ryTop * sin(a), t.yBot + t.ryBot * sin(a), hFrac);
      pts.push([px, py]);
    }
    let col = hFrac > 0.55 ? PAL.specWhite : PAL.coralRose;
    brush.set("2H", col, 0.18);
    safeSpline(pts, 0.35);
  }

  // Crisp vertical cylinder silhouette edges catching warm golden rim-light
  brush.set("rotring", PAL.paleGold, 0.38);
  brush.line(cx - t.rx, t.yTop, cx - t.rx, t.yBot);
  brush.line(cx + t.rx, t.yTop, cx + t.rx, t.yBot);
}

function drawTierQuiltedLattice(cx, t) {
  // Embossed diamond quilting on Tier 1 with 3D spherical golden sugar pearls at intersections
  let angleSteps = 16;
  let rows = 4;

  // Draw diagonal lattice score lines projected onto the 3D cylinder
  for (let dir = -1; dir <= 1; dir += 2) {
    for (let startIdx = -rows; startIdx < angleSteps + rows; startIdx++) {
      let pts = [];
      let ptsHighlight = [];
      for (let r = 0; r <= rows; r++) {
        let aIdx = startIdx + dir * r;
        let a = map(aIdx, 0, angleSteps, 172, 8);
        if (a < 6 || a > 174) continue;
        let vFrac = map(r, 0, rows, 0.22, 0.92);
        let px = cx + t.rx * cos(a);
        let py = lerp(t.yTop + t.ryTop * sin(a), t.yBot + t.ryBot * sin(a), vFrac);
        pts.push([px, py]);
        ptsHighlight.push([px, py + 2.2]);
      }
      if (pts.length >= 2) {
        // Upper shadow of score groove (rose-violet)
        brush.set("rotring", PAL.damaskRose, 0.28);
        safeSpline(pts, 0.3);
        // Lower lip of score groove catching golden limelight
        brush.set("micro", PAL.specWhite, 0.75);
        safeSpline(ptsHighlight, 0.3);
      }
    }
  }

  // 3D Golden Sugar Pearls (Dragées) at every diamond intersection
  for (let r = 1; r < rows; r++) {
    let vFrac = map(r, 0, rows, 0.22, 0.92);
    for (let i = 1; i < angleSteps; i++) {
      if ((i + r) % 2 !== 0) continue;
      let a = map(i, 0, angleSteps, 172, 8);
      let px = cx + t.rx * cos(a);
      let py = lerp(t.yTop + t.ryTop * sin(a), t.yBot + t.ryBot * sin(a), vFrac);
      drawSugarPearl(px, py, 4.2);
    }
  }
}

function drawSugarPearl(x, y, r) {
  // Upward cast shadow on the buttercream
  brush.set("rotring", PAL.operaPlum, 0.45);
  brush.arc(x, y - 1.5, r, 195, 345);

  // Golden body
  resetBrush();
  brush.wash(PAL.amberGold, 220);
  brush.circle(x, y, r, 0.05);

  // Dark rose-plum top hemisphere reflection
  brush.set("rotring", PAL.deepViolet, 0.32);
  brush.arc(x, y, r * 0.85, 200, 340);

  // Luminous pale-gold lower crescent (from limelight below)
  brush.set("rotring", PAL.paleGold, 0.42);
  brush.arc(x, y, r * 0.85, 20, 160);

  // Pinpoint white-gold specular glint
  brush.set("micro", PAL.specWhite, 1.15);
  brush.line(x - 1, y + r * 0.45, x + 1.2, y + r * 0.45);
}

function drawTierBaroqueSwags(cx, t) {
  // Piped royal-icing catenary swags (lambrequins) around Tier 2
  let numSwags = 6;
  let aStart = 172;
  let aEnd = 8;
  let dA = (aStart - aEnd) / numSwags;

  for (let s = 0; s < numSwags; s++) {
    let a1 = aStart - s * dA;
    let a2 = a1 - dA;

    let swagShadowPts = [];
    let swagBodyPts = [];
    let swagGoldPts = [];
    let swagSpecPts = [];

    let steps = 12;
    for (let i = 0; i <= steps; i++) {
      let u = i / steps;
      let a = lerp(a1, a2, u);
      let px = cx + (t.rx + 2) * cos(a);
      let basePy = lerp(t.yTop + t.ryTop * sin(a), t.yBot + t.ryBot * sin(a), 0.42);
      let sag = sin(u * 180) * 38;
      let py = basePy + sag;

      swagShadowPts.push([px, py - 5]);
      swagBodyPts.push([px, py]);
      swagGoldPts.push([px, py + 3]);
      swagSpecPts.push([px, py + 4.5]);
    }

    // 1. Upward-cast shadow of the piped swag onto the cylinder wall
    brush.set("cpencil", PAL.operaPlum, 0.65);
    safeSpline(swagShadowPts, 0.4);

    // 2. Upper shadow side of the piped cord
    brush.set("marker", PAL.coralRose, 0.55);
    safeSpline(swagBodyPts, 0.4);

    // 3. Lower golden limelight side of the piped cord
    brush.set("marker", PAL.paleGold, 0.55);
    safeSpline(swagGoldPts, 0.4);

    // 4. Razor-sharp serrated piping ridges along the swag
    brush.set("micro", PAL.specWhite, 0.95);
    safeSpline(swagSpecPts, 0.4);

    // Piped knot & hanging sugar pearl tassel at each swag junction
    if (s < numSwags) {
      let kx = cx + (t.rx + 2) * cos(a1);
      let ky = lerp(t.yTop + t.ryTop * sin(a1), t.yBot + t.ryBot * sin(a1), 0.42);
      drawSugarPearl(kx, ky, 4.8);
      drawSugarPearl(kx, ky + 11, 3.6);
      drawSugarPearl(kx, ky + 20, 2.8);
    }
  }
}

function drawTierMicroFluting(cx, t) {
  // Fine vertical French pastry-comb grooves on Tier 3 catching golden limelight on each ridge
  for (let a = 10; a <= 170; a += 4.5) {
    let x = cx + t.rx * cos(a);
    let yT = t.yTop + t.ryTop * sin(a) + 22;
    let yB = t.yBot + t.ryBot * sin(a) - 10;
    let front = sin(a);

    // Shadow groove
    brush.set("rotring", PAL.damaskRose, 0.24);
    brush.line(x, yT, x, yB);

    // Illuminated ridge next to groove
    if (front > 0.35) {
      brush.set("micro", PAL.paleGold, 0.75 * front);
      brush.line(x + 1.6, yT + 10, x + 1.6, yB);
    }
  }
}

function drawTierGlossyGanache(cx, t) {
  resetBrush();

  // Generate deterministic, organic drip profiles around the front 180 degrees of the tier
  let drips = [];
  let numDrips = t.dripCount;
  for (let i = 0; i < numDrips; i++) {
    let frac = (i + 0.5) / numDrips;
    let a = lerp(175, 5, frac);
    // Vary drip lengths rhythmically like real poured couverture ganache
    let baseLen =
      (t.id === 1 ? 52 : t.id === 2 ? 44 : 36) +
      sin(i * 137.5) * 24 +
      cos(i * 73.1) * 14;
    // Perspective foreshortening of drip width near cylinder edges
    let proj = max(0.28, sin(a));
    let w = (t.id === 1 ? 11.5 : t.id === 2 ? 9.8 : 8.5) * proj;

    let x = cx + (t.rx + 1.5) * cos(a);
    let yShoulder = t.yTop + t.ryTop * sin(a);
    let yBridge = yShoulder + (t.id === 1 ? 16 : 13);
    let yTip = yBridge + baseLen;

    drips.push({ a, x, yShoulder, yBridge, yTip, w, proj, len: baseLen });
  }

  // Build the continuous polygon for the poured ganache curtain + bulbous drips
  let ganachePts = [];
  // Back half of top ellipse
  for (let a = 0; a <= 180; a += 10) {
    ganachePts.push([cx + (t.rx + 1.5) * cos(a), t.yTop - t.ryTop * sin(a)]);
  }
  // Front wave of drips from left (180 deg) to right (0 deg)
  for (let i = 0; i < drips.length; i++) {
    let d = drips[i];
    // Left neck of drip
    ganachePts.push([d.x - d.w * 0.75, d.yBridge]);
    ganachePts.push([d.x - d.w * 0.62, lerp(d.yBridge, d.yTip, 0.55)]);
    // Bulbous teardrop swelling at bottom
    ganachePts.push([d.x - d.w * 0.88, d.yTip - d.w * 0.6]);
    ganachePts.push([d.x, d.yTip]);
    ganachePts.push([d.x + d.w * 0.88, d.yTip - d.w * 0.6]);
    // Right neck ascending
    ganachePts.push([d.x + d.w * 0.62, lerp(d.yBridge, d.yTip, 0.55)]);
    ganachePts.push([d.x + d.w * 0.75, d.yBridge]);

    // Concave meniscus arch between this drip and the next
    if (i < drips.length - 1) {
      let dNext = drips[i + 1];
      let midX = (d.x + dNext.x) / 2;
      let midY = (d.yBridge + dNext.yBridge) / 2 - 4;
      ganachePts.push([midX, midY]);
    }
  }

  // PASS 1: Upward & lateral cast shadow of the thick ganache drips onto the buttercream
  for (let d of drips) {
    resetBrush();
    brush.wash(PAL.operaPlum, 135);
    brush.rect(d.x - d.w * 0.7, d.yBridge, d.w * 1.65, d.len - 2, "corner");
    brush.circle(d.x + 2, d.yTip - 2, d.w * 0.95, 0.08);
  }

  // PASS 2: Deep mirror-chocolate ganache base fill
  resetBrush();
  brush.fill(PAL.ganacheDark, 248);
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.12, 0.1);
  safeShape(ganachePts, 0.18, true);

  // PASS 3: Warm ruby-mahogany subsurface glow along thin arches and drip necks
  for (let i = 0; i < drips.length; i++) {
    let d = drips[i];
    brush.set("rotring", PAL.ganacheRuby, 0.48);
    brush.line(d.x - d.w * 0.55, d.yBridge, d.x - d.w * 0.55, d.yTip - d.w);
    brush.line(d.x + d.w * 0.55, d.yBridge, d.x + d.w * 0.55, d.yTip - d.w);

    if (i < drips.length - 1) {
      let dNext = drips[i + 1];
      let midX = (d.x + dNext.x) / 2;
      let midY = (d.yBridge + dNext.yBridge) / 2 - 4;
      // Golden limelight reflected on the downward-facing arch meniscus between drips!
      brush.set("rotring", PAL.amberGold, 0.45);
      safeSpline(
        [
          [d.x + d.w * 0.7, d.yBridge + 1],
          [midX, midY + 1],
          [dNext.x - dNext.w * 0.7, dNext.yBridge + 1]
        ],
        0.4
      );
      brush.set("micro", PAL.paleGold, 0.9);
      safeSpline(
        [
          [d.x + d.w * 0.65, d.yBridge + 2],
          [midX, midY + 2],
          [dNext.x - dNext.w * 0.65, dNext.yBridge + 2]
        ],
        0.4
      );
    }
  }

  // PASS 4: GOLDEN LIMELIGHT UNDER-CRESCENTS ON EVERY DRIP BULB
  // Because limelight shines from below, the curved bottom belly of every glossy ganache drop
  // reflects a blazing crescent of pale gold!
  for (let d of drips) {
    let rBulb = max(2.5, d.w * 0.78);
    // Warm amber outer glow crescent
    brush.set("rotring", PAL.amberGold, 0.55);
    brush.arc(d.x, d.yTip - rBulb * 0.75, rBulb, 15, 165);
    // Brilliant pale gold core crescent
    brush.set("rotring", PAL.paleGold, 0.42);
    brush.arc(d.x, d.yTip - rBulb * 0.72, rBulb * 0.92, 28, 152);
    // Razor-sharp white-gold hot spot at bottom of droplet
    if (d.proj > 0.45) {
      brush.set("micro", PAL.specWhite, 1.15);
      brush.arc(d.x, d.yTip - rBulb * 0.7, rBulb * 0.88, 45, 135);
    }
  }

  // PASS 5: RAZOR-SHARP WINDOW SPECULAR HIGHLIGHTS ALONG DRIP STEMS & TOP SHOULDER
  for (let d of drips) {
    if (d.proj < 0.35) continue;
    let hx = d.x - d.w * 0.26;
    // Soft rose-cream window reflection Halo
    brush.set("rotring", PAL.peachBlush, 0.45 * d.proj);
    brush.line(hx, d.yShoulder + 4, hx, d.yTip - d.w * 1.4);

    // Razor-sharp white specular streak broken near the bulb neck
    brush.set("micro", PAL.specWhite, 1.15 * d.proj);
    brush.line(hx, d.yShoulder + 6, hx, d.yTip - d.w * 1.8);
    // Specular bead on the upper-left curve of the bulb
    brush.line(hx - 0.5, d.yTip - d.w * 1.2, hx + 0.5, d.yTip - d.w * 0.85);
  }

  // Glossy specular rim along the rounded top shoulder of the ganache pour
  let shoulderSpec1 = ellipsePoints(cx, t.yTop + 2, t.rx * 0.96, t.ryTop * 0.96, 18, 82, 18);
  let shoulderSpec2 = ellipsePoints(cx, t.yTop + 2, t.rx * 0.96, t.ryTop * 0.96, 98, 162, 18);
  brush.set("rotring", PAL.peachBlush, 0.55);
  safeSpline(shoulderSpec1, 0.4);
  safeSpline(shoulderSpec2, 0.4);
  brush.set("micro", PAL.specWhite, 1.25);
  safeSpline(shoulderSpec1, 0.4);
  safeSpline(shoulderSpec2, 0.4);
}

// =============================================================================
// HYPERREAL PIPED BUTTERCREAM ROSETTES
// =============================================================================

function drawTierRosetteRing(cx, t) {
  let count = t.rosetteCount;
  // Draw from edges (0 and 180 deg) inward toward front center (90 deg) so front rosettes overlap side ones naturally
  let indices = [];
  for (let i = 0; i < count; i++) indices.push(i);
  indices.sort((a, b) => {
    let angA = map(a, 0, count - 1, 178, 2);
    let angB = map(b, 0, count - 1, 178, 2);
    return sin(angA) - sin(angB);
  });

  for (let idx of indices) {
    let a = map(idx, 0, count - 1, 178, 2);
    let rx = cx + (t.rx + 4) * cos(a);
    let ry = t.yBot + (t.ryBot + 2) * sin(a) - 3;
    let proj = map(sin(a), 0, 1, 0.72, 1.05);
    drawHyperrealRosette(rx, ry, t.rosetteR * proj, t.rosetteR * 0.92, idx * 25);
  }
}

function drawHyperrealRosette(cx, cy, rx, ry, rotOffset) {
  resetBrush();

  // 1. Tight upward-cast shadow onto the cake cylinder above the rosette (limelight from below)
  brush.wash(PAL.deepViolet, 145);
  brush.circle(cx, cy - ry * 0.38, max(rx, ry) * 0.95, 0.12);

  // 2. Base tonal mass of the rosette:
  // Upper half in warm damask-rose shadow, lower half blazing with pale golden limelight
  resetBrush();
  brush.wash(PAL.coralRose, 210);
  brush.circle(cx, cy - ry * 0.12, max(rx, ry) * 0.92, 0.1);

  resetBrush();
  brush.wash(PAL.paleGold, 235);
  brush.circle(cx, cy + ry * 0.18, max(rx, ry) * 0.88, 0.1);

  // 3. Piped Star-Tip Spiral Petals (7 interlocking fluted lobes wrapping from outer rim to center)
  let numPetals = 7;
  for (let p = 0; p < numPetals; p++) {
    let baseAng = (p * (360 / numPetals) + rotOffset) % 360;
    let aStart = baseAng;
    let aMid = baseAng + 48;
    let aEnd = baseAng + 95;

    // Determine whether this petal sits on the lower (limelight-lit) half or upper (rose-shadow) half
    let midSin = sin((aStart + aEnd) / 2); // +1 is bottom, -1 is top
    let isBottomLit = midSin > -0.1;

    let p1 = [cx + rx * 0.98 * cos(aStart), cy + ry * 0.98 * sin(aStart)];
    let p2 = [cx + rx * 0.72 * cos(aMid), cy + ry * 0.72 * sin(aMid)];
    let p3 = [cx + rx * 0.25 * cos(aEnd), cy + ry * 0.25 * sin(aEnd)];

    // Deep crevice line between overlapping star-tip folds
    let creviceCol = isBottomLit ? PAL.honeyOchre : PAL.deepViolet;
    brush.set("rotring", creviceCol, 0.36);
    safeSpline([p1, p2, p3], 0.45);

    // Fluted star-nozzle ridges parallel to the petal curve
    let ridgeCol = isBottomLit ? PAL.paleGold : PAL.peachBlush;
    brush.set("cpencil", ridgeCol, 0.48);
    safeSpline(
      [
        [p1[0] * 0.9 + cx * 0.1, p1[1] * 0.9 + cy * 0.1 + 1.5],
        [p2[0] * 0.9 + cx * 0.1, p2[1] * 0.9 + cy * 0.1 + 1.5],
        [p3[0], p3[1] + 1]
      ],
      0.45
    );

    // Razor-sharp serrated icing ridge highlight
    if (isBottomLit) {
      brush.set("micro", PAL.specWhite, 1.05);
      safeSpline(
        [
          [p1[0], p1[1] + 1.2],
          [p2[0], p2[1] + 1.2],
          [p3[0], p3[1] + 0.8]
        ],
        0.45
      );
    } else {
      brush.set("rotring", PAL.damaskRose, 0.28);
      safeSpline(
        [
          [p1[0], p1[1] - 1.2],
          [p2[0], p2[1] - 1.2],
          [p3[0], p3[1]]
        ],
        0.45
      );
    }
  }

  // 4. Central Piped Swirl Peak & Golden Sugar Pearl Heart
  brush.set("rotring", PAL.operaPlum, 0.35);
  brush.arc(cx, cy - 1, rx * 0.32, 190, 350);
  brush.set("micro", PAL.specWhite, 1.15);
  brush.arc(cx, cy + 1, rx * 0.32, 15, 165);
  drawSugarPearl(cx, cy, max(2.2, rx * 0.2));
}

// =============================================================================
// 8C. CROWN TOPPER: CHANTILLY SWIRLS, GLAZED BERRIES & SPUN SUGAR FILIGREE
// =============================================================================

function drawCakeCrownTopper(cx, topTier) {
  let cy = topTier.yTop - 4;
  let rx = topTier.rx * 0.78;
  let ry = topTier.ryTop * 0.75;

  // 1. Back half of crown Chantilly rosettes & glazed ruby cherries
  for (let i = 0; i < 5; i++) {
    let a = map(i, 0, 4, 195, 345);
    let px = cx + rx * cos(a);
    let py = cy + ry * sin(a) - 6;
    drawHyperrealRosette(px, py, 14, 13, i * 40);
  }

  // 2. Dark Couverture Chocolate Opera Scrolls / Shards rising from the crown
  let scrollSpecs = [
    { x: cx - 42, y: cy - 12, w: 22, h: 68, tilt: -14 },
    { x: cx, y: cy - 18, w: 26, h: 86, tilt: 4 },
    { x: cx + 44, y: cy - 12, w: 22, h: 64, tilt: 16 }
  ];
  for (let sc of scrollSpecs) {
    resetBrush();
    let xTop = sc.x + sc.tilt;
    let yTop = sc.y - sc.h;
    let pts = [
      [sc.x - sc.w / 2, sc.y],
      [xTop - sc.w * 0.35, yTop + 12],
      [xTop, yTop],
      [xTop + sc.w * 0.45, yTop + 16],
      [sc.x + sc.w / 2, sc.y]
    ];
    brush.fill(PAL.ganacheDark, 240);
    brush.fillBleed(0.03, "in");
    safeShape(pts, 0.25, true);

    // Golden limelight catching the curled edge & edible gold leaf flakes
    brush.set("rotring", PAL.amberGold, 0.45);
    safeSpline(
      [
        [sc.x - sc.w / 2, sc.y],
        [xTop - sc.w * 0.35, yTop + 12],
        [xTop, yTop]
      ],
      0.35
    );
    brush.set("micro", PAL.specWhite, 1.1);
    safeSpline(
      [
        [sc.x - sc.w / 2 + 1.5, sc.y - 4],
        [xTop - sc.w * 0.3, yTop + 14],
        [xTop, yTop + 2]
      ],
      0.35
    );

    // Edible gold leaf flecks on the dark chocolate shard
    for (let g = 0; g < 4; g++) {
      let gx = lerp(sc.x, xTop, (g + 1) / 5) + random(-4, 4);
      let gy = lerp(sc.y, yTop, (g + 1) / 5);
      brush.set("marker", PAL.brightGold, 0.38);
      brush.line(gx - 2, gy, gx + 2, gy - 2);
      brush.set("micro", PAL.specWhite, 0.9);
      brush.line(gx - 1, gy + 1, gx + 1, gy);
    }
  }

  // 3. Front crown Chantilly rosettes & Glossy Glazed Ruby Cherries
  let frontAngles = [165, 130, 90, 50, 15];
  for (let i = 0; i < frontAngles.length; i++) {
    let a = frontAngles[i];
    let px = cx + rx * 0.95 * cos(a);
    let py = cy + ry * 0.95 * sin(a) - 2;
    drawHyperrealRosette(px, py, 15.5, 14.5, i * 55);

    // Nestle a glossy candied ruby berry between each pair of rosettes
    if (i < frontAngles.length - 1) {
      let aMid = (a + frontAngles[i + 1]) / 2;
      let bx = cx + rx * 0.78 * cos(aMid);
      let by = cy + ry * 0.78 * sin(aMid) - 10;
      drawGlazedRubyBerry(bx, by, 11.5);
    }
  }
  // Central apex glazed berry
  drawGlazedRubyBerry(cx, cy - 22, 13);

  // 4. SPUN-SUGAR CARAMEL FILIGREE DOME (Hair-thin parabolic golden arcs catching limelight)
  for (let i = 0; i < 18; i++) {
    let a1 = random(15, 165);
    let a2 = a1 + random(75, 160);
    let x1 = cx + rx * 0.85 * cos(a1);
    let y1 = cy + ry * 0.5 * sin(a1) - 8;
    let x2 = cx + rx * 0.85 * cos(a2);
    let y2 = cy + ry * 0.5 * sin(a2) - 8;
    let peakX = (x1 + x2) / 2 + random(-18, 18);
    let peakY = cy - random(65, 135);

    let sugarPts = [
      [x1, y1],
      [lerp(x1, peakX, 0.55), lerp(y1, peakY, 0.75)],
      [peakX, peakY],
      [lerp(x2, peakX, 0.55), lerp(y2, peakY, 0.75)],
      [x2, y2]
    ];

    // Golden caramel thread
    brush.set("rotring", i % 2 === 0 ? PAL.amberGold : PAL.paleGold, 0.24);
    safeSpline(sugarPts, 0.55);

    // Incandescent white-gold specular glint along the underside of the sugar arch
    if (i % 3 === 0) {
      brush.set("micro", PAL.specWhite, 0.85);
      safeSpline(
        [
          [lerp(x1, peakX, 0.55), lerp(y1, peakY, 0.75) + 1],
          [peakX, peakY + 1],
          [lerp(x2, peakX, 0.55), lerp(y2, peakY, 0.75) + 1]
        ],
        0.55
      );
    }
  }
}

function drawGlazedRubyBerry(cx, cy, r) {
  resetBrush();
  // Deep crimson base
  brush.fill(PAL.berryDark, 240);
  brush.fillBleed(0.03, "in");
  brush.circle(cx, cy, r, 0.06);

  // Warm ruby midtone
  resetBrush();
  brush.wash(PAL.berryMid, 210);
  brush.circle(cx - r * 0.1, cy + r * 0.1, r * 0.82, 0.06);

  // Subsurface bright crimson-amber glow on lower hemisphere (limelight from below!)
  brush.set("marker", PAL.berryBright, 0.55);
  brush.arc(cx, cy, r * 0.72, 20, 160);
  brush.set("rotring", PAL.paleGold, 0.42);
  brush.arc(cx, cy, r * 0.86, 30, 150);

  // Crisp curved window reflection on upper-left of the glossy glaze
  brush.set("micro", PAL.specWhite, 1.25);
  brush.arc(cx, cy, r * 0.65, 205, 255);
  brush.circle(cx - r * 0.25, cy - r * 0.5, 1.5, 0.05);
}

// =============================================================================
// 9. FINAL LIMELIGHT ATMOSPHERIC GLOW & STAGE DUST MOTES
// =============================================================================

function drawFinalLimelightBloom() {
  resetBrush();

  // Subtle upward-floating golden dust motes & spun-sugar sparkles in the limelight beam
  for (let i = 0; i < 42; i++) {
    let mx = random(240, 960);
    let my = random(260, 1080);
    // Concentrate near the central limelight cone
    let distFromCenter = abs(mx - 600);
    if (distFromCenter > map(my, 260, 1080, 220, 420)) continue;

    let isBright = random() > 0.35;
    brush.set("micro", isBright ? PAL.specWhite : PAL.paleGold, random(0.6, 1.1));
    brush.circle(mx, my, random(1.0, 2.4), 0.1);
  }

  // Final framing proscenium shadow vignette at the very top edge
  resetBrush();
  brush.wash(PAL.midnightWine, 55);
  brush.rect(0, 0, 1200, 38, "corner");
}

// Hyperreal Photogravure: Steam Iron on Crumpled Linen
// Rendered with p5.js v2 + p5.brush in WEBGL

const PAL = {
  paper: "#eae7de",
  paperLight: "#f4f2eb",
  paperWarm: "#dfdcd2",
  steamBright: "#f5f4ee",
  steamLight: "#e2e3de",
  steamMid: "#bfc3c4",
  plateLight: "#b4b8ba",
  plateMid: "#8c9298",
  plateDark: "#5f666e",
  slateDeep: "#394048",
  inkDark: "#21262d",
  inkBlack: "#121519",
  velvetBlack: "#0b0d10",
  sepiaCharcoal: "#1b1a1c",
  chromeSpec: "#f7f8f4",
  chromeBright: "#dce0e2",
  chromeMid: "#9ca3aa",
  chromeSlate: "#525962",
  chromeDark: "#232931"
};

// 3D-to-2D Projection Parameters for the Steam Iron
const IRON_ANCHOR = { x: 515, y: 885 };
const IRON_LEN = 555;
const U_VEC = { x: -0.155, y: -0.968, z: 0.195 };
const V_VEC = { x: 0.365, y: 0.088, z: 0.926 };
const W_VEC = { x: 0.895, y: 0.042, z: -0.444 };

function soleHalfWidth(u) {
  u = constrain(u, 0, 1);
  if (u < 0.055) {
    let t = u / 0.055;
    return 136 * (0.74 + 0.20 * Math.sin(t * Math.PI * 0.5));
  } else if (u < 0.24) {
    let t = (u - 0.055) / 0.185;
    return 136 * (0.94 + 0.06 * Math.sin(t * Math.PI * 0.5));
  } else {
    let t = (u - 0.24) / 0.76;
    return 136 * Math.pow(Math.max(0, 1 - Math.pow(t, 1.30)), 0.78);
  }
}

function hoodTopW(u) {
  u = constrain(u, 0, 1);
  if (u < 0.06) {
    return 118 + 22 * (u / 0.06);
  } else if (u < 0.55) {
    let t = (u - 0.06) / 0.49;
    return 140 - 12 * t * t;
  } else {
    let t = (u - 0.55) / 0.45;
    return 128 * Math.pow(Math.max(0, 1 - 0.74 * Math.pow(t, 1.15)), 0.9);
  }
}

function projectIron(u, vPx, wPx) {
  let uPx = u * IRON_LEN;
  let x = IRON_ANCHOR.x + uPx * U_VEC.x + vPx * V_VEC.x + wPx * W_VEC.x;
  let y = IRON_ANCHOR.y + uPx * U_VEC.y + vPx * V_VEC.y + wPx * W_VEC.y;
  let z = uPx * U_VEC.z + vPx * V_VEC.z + wPx * W_VEC.z;
  return [x, y, z];
}

function hoodPoint(u, s) {
  // s in [0, 1]: 0 = near right skirt edge (w=18), 1 = top dorsal spine (v=0, w=hoodTopW)
  let hw = soleHalfWidth(u) * 0.96;
  let wt = hoodTopW(u);
  let ang = s * Math.PI * 0.5;
  let vPx = hw * Math.pow(Math.cos(ang), 0.40);
  let wPx = 18 + (wt - 18) * Math.pow(Math.sin(ang), 0.76);
  // Subtle streamline decorative step at s = 0.56
  if (s > 0.54 && s < 0.62) {
    wPx += 2.2 * Math.sin(((s - 0.54) / 0.08) * Math.PI);
  } else if (s >= 0.62) {
    wPx -= 1.8;
  }
  return projectIron(u, vPx, wPx);
}

// Hyperreal Chrome Reflection Shader (returns tone 0..1 where 0 = inkBlack, 1 = specular white)
function chromeReflectionVal(u, s) {
  // Discontinuity across the embossed streamline rib at s = 0.57
  let sShift = s > 0.57 ? s + 0.055 : s;
  let uShift = s > 0.57 ? u - 0.025 : u;

  // Anamorphic surface normal warp
  let nx = uShift * 1.15 + 0.18 * Math.sin(sShift * Math.PI * 2.1);
  let ny = sShift * 1.35 + 0.14 * Math.cos(uShift * Math.PI * 2.6);

  // 1. Lower skirt reflection of crumpled linen folds (u < 0.34 or s < 0.22)
  let linenWeight = constrain(map(u, 0.34, 0.04, 0, 1), 0, 1) * 0.75 +
                    constrain(map(s, 0.22, 0.0, 0, 1), 0, 1) * 0.65;
  let linenWave = 0.5 + 0.5 * Math.sin(u * 26.0 - s * 14.0 + Math.sin(u * 9.0) * 1.8);

  // 2. Studio window reflection (warped mullioned panes across the convex belly)
  let winU = nx - 0.12 * Math.pow(sShift - 0.42, 2);
  let winV = ny + 0.16 * Math.sin((uShift - 0.45) * 4.2);

  let inWindow = (winU > 0.24 && winU < 0.88 && winV > 0.20 && winV < 0.92);
  let windowTone = 0.16;
  if (inWindow) {
    windowTone = 0.86 - 0.12 * winV;
    // Dark wooden window mullions (curved by the dome)
    let mullionU1 = Math.abs(winU - 0.48);
    let mullionU2 = Math.abs(winU - 0.70);
    let mullionV1 = Math.abs(winV - 0.48);
    let mullionV2 = Math.abs(winV - 0.74);
    if (mullionU1 < 0.024 || mullionU2 < 0.022 || mullionV1 < 0.028 || mullionV2 < 0.025) {
      windowTone = 0.18;
    } else if (mullionU1 < 0.038 || mullionU2 < 0.035 || mullionV1 < 0.042 || mullionV2 < 0.038) {
      windowTone = 0.48;
    }
  } else {
    // Dark studio interior reflection with secondary soft light band
    let secBand = Math.exp(-Math.pow((winV - 1.08) / 0.14, 2)) * 0.62;
    let darkCore = Math.exp(-Math.pow((winV - 0.09) / 0.08, 2)) * 0.08;
    windowTone = 0.12 + secBand + darkCore;
  }

  // 3. Dark reflection of the Bakelite handle arch near the top spine (s > 0.76)
  if (s > 0.74 && u > 0.14 && u < 0.82) {
    let handleShadow = constrain(map(s, 0.74, 0.92, 0, 1), 0, 1);
    windowTone = lerp(windowTone, 0.08, handleShadow * 0.85);
  }

  // Combine window and linen reflections
  let val = lerp(windowTone, 0.30 + 0.56 * linenWave, constrain(linenWeight, 0, 0.85));

  // 4. Sharp streamline rib highlight at s = 0.56..0.585
  if (s > 0.555 && s < 0.588 && u > 0.08 && u < 0.94) {
    val = 0.97;
  } else if (s > 0.530 && s <= 0.555 && u > 0.08 && u < 0.94) {
    val = 0.10;
  }

  // 5. Grazing specular rim along nose ridge (u > 0.58, s near 0.26..0.34)
  let noseSpec = Math.exp(-Math.pow((s - 0.30) / 0.045, 2)) * constrain(map(u, 0.45, 0.95, 0.2, 1.0), 0, 1);
  val = Math.min(1.0, val + noseSpec * 0.45);

  return constrain(val, 0, 1);
}

function drawPolyFill(pts) {
  brush.beginShape(0.15);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(84193);

  // Required brush scaling
  brush.scaleBrushes(3);

  // Custom brushes for early photogravure aquatint & hyperreal chrome engraving
  brush.add("aquatint", {
    type: "spray",
    weight: 6.5,
    scatter: 3.8,
    opacity: 20,
    spacing: 0.85,
    pressure: [0.5, 1.2, 0.5]
  });

  brush.add("steam_stipple", {
    type: "spray",
    weight: 5.0,
    scatter: 4.6,
    opacity: 26,
    spacing: 0.75,
    pressure: [0.4, 1.15, 0.35]
  });

  brush.add("fine_needle", {
    type: "default",
    weight: 0.28,
    scatter: 0.04,
    sharpness: 0.94,
    grain: 3,
    opacity: 195,
    spacing: 0.12,
    pressure: [0.65, 1.0, 0.65],
    noise: 0.2
  });

  brush.add("velvet_charcoal", {
    type: "default",
    weight: 1.4,
    scatter: 0.65,
    sharpness: 0.22,
    grain: 16,
    opacity: 90,
    spacing: 0.18,
    pressure: [0.45, 1.25, 0.45],
    noise: 0.75
  });

  brush.addField("gravure_steam", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.08;
        let ny = row * 0.08;
        let curl = (noise(nx, ny, t * 0.1) - 0.5) * 110;
        field[col][row] = -82 + curl;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.paper);

  // 1. Photogravure Plate-Tone Ground & Atmospheric Vignette
  renderPlateGround();

  // 2. Softly Modelled Pictorialist Crumpled Linen Sheet
  renderCrumpledLinen();

  // 3. Braided Vintage Electrical Cord on Linen
  renderBraidedCord();

  // 4. Sculpted Bakelite Handle, Heel Rest & Thermostat Dial
  renderHandleAndDial();

  // 5. Hyperreal Polished Chrome Shell (Sharp Focal Plane)
  renderHyperrealChrome();

  // 6. Deep Velvety Charcoal Soleplate, Beveled Rim & Steam Vents
  renderSoleplate();

  // 7. Delicate Spray-Stippled Steam Unfurling Upward
  renderUnfurlingSteam();

  // 8. Final Aquatint Grain, Corner Plate-Tone Inking & Etched Plate Mark
  renderAquatintAndPlateBorder();

  noLoop();
}

// =============================================================================
// 1. PHOTOGRAVURE PLATE-TONE GROUND
// =============================================================================
function renderPlateGround() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base cream-platinum plate wash inside plate mark [30, 30, 1170, 1170]
  brush.wash(PAL.paperWarm, 85);
  brush.rect(32, 32, 1136, 1136, "corner");
  brush.noWash();

  // Batch 1: Mid-light cool gravure plate tone across upper backdrop & edges
  brush.fill(PAL.plateLight, 68);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.65, 0.22);
  drawPolyFill([[32, 32], [1168, 32], [1168, 760], [32, 740]]);
  drawPolyFill([[32, 700], [420, 720], [520, 1168], [32, 1168]]);
  drawPolyFill([[880, 740], [1168, 700], [1168, 1168], [760, 1168]]);

  // Batch 2: Deeper slate-sepia backdrop around the iron & steam plumes
  // Note how we carve a luminous channel around x: 350..560, y: 80..540 for the rising steam
  brush.fill(PAL.plateMid, 78);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.70, 0.25);
  // Left of steam plume
  drawPolyFill([[32, 32], [410, 32], [350, 240], [380, 480], [440, 680], [32, 710]]);
  // Right of steam plume & behind iron handle
  drawPolyFill([[520, 32], [1168, 32], [1168, 730], [720, 710], [560, 420], [535, 190]]);

  // Batch 3: Rich dark pictorialist shadows in upper corners & behind iron nose
  brush.fill(PAL.plateDark, 82);
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.72, 0.28);
  drawPolyFill([[32, 32], [330, 32], [270, 280], [320, 560], [32, 650]]);
  drawPolyFill([[600, 32], [1168, 32], [1168, 660], [830, 640], [640, 340]]);
  // Subtle dark pocket right behind the rising steam & iron tip to make both glow
  drawPolyFill([[390, 240], [575, 220], [620, 490], [435, 560]]);

  // Batch 4: Heavier corner inking (classic gravure plate edge tone)
  brush.fill(PAL.slateDeep, 74);
  brush.fillBleed(0.5, "out");
  drawPolyFill([[32, 32], [260, 32], [160, 190], [32, 320]]);
  drawPolyFill([[890, 32], [1168, 32], [1168, 360], [990, 210]]);
  drawPolyFill([[32, 910], [165, 1020], [290, 1168], [32, 1168]]);
  drawPolyFill([[1010, 990], [1168, 860], [1168, 1168], [860, 1168]]);

  brush.noFill();

  // Soft aquatint grain across the upper background
  brush.set("aquatint", PAL.slateDeep, 1.3);
  for (let i = 0; i < 160; i++) {
    let y = random(38, 700);
    let x = random(38, 1162);
    // Leave lighter core inside the main steam corridor
    let inSteamCore = (x > 365 && x < 545 && y > 90 && y < 520);
    if (inSteamCore && random() < 0.72) continue;
    let len = random(35, 95);
    let ang = random(-15, 15);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

// =============================================================================
// 2. SOFTLY MODELLED CRUMPLED LINEN SHEET (SHALLOW PICTORIALIST FOCUS)
// =============================================================================
function renderCrumpledLinen() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Define sculptural, out-of-focus linen folds radiating from iron heel (610, 890)
  const midFolds = [
    // Horizon transition folds (distant out-of-focus linen)
    [[32, 680], [450, 685], [460, 760], [32, 780]],
    [[740, 675], [1168, 690], [1168, 785], [760, 765]],
    // Left sweeping trough from under heel
    [[45, 835], [310, 795], [535, 855], [510, 920], [260, 895], [45, 935]],
    // Front-left diagonal crease
    [[60, 1025], [340, 950], [595, 915], [645, 960], [385, 1035], [110, 1120]],
    // Central foreground trough below the heel
    [[310, 1110], [610, 975], [790, 925], [845, 975], [625, 1065], [370, 1165]],
    // Right mid-ground fold behind cord
    [[765, 815], [985, 775], [1165, 815], [1165, 885], [965, 855], [775, 865]],
    // Right foreground broad crease
    [[660, 1115], [935, 995], [1165, 945], [1165, 1055], [945, 1095], [740, 1165]]
  ];

  const deepTroughs = [
    // Cast shadow trough directly left & front-left of the iron heel
    [[195, 865], [515, 850], [605, 905], [545, 955], [320, 945], [165, 915]],
    // Immediate indentation right under the iron heel & heel rest
    [[485, 875], [775, 870], [805, 918], [585, 938], [465, 910]],
    // Deep crease pocket in lower left foreground
    [[40, 1055], [275, 995], [440, 975], [360, 1030], [125, 1115], [40, 1135]],
    // Deep crease pocket in lower right under the cord loop
    [[775, 1045], [995, 985], [1160, 975], [1160, 1035], [960, 1060], [810, 1090]],
    // Distant horizon shadow blur
    [[32, 665], [455, 680], [445, 725], [32, 725]],
    [[755, 670], [1168, 675], [1168, 730], [770, 720]]
  ];

  // Batch 1: Soft mid-tone linen fold modeling
  brush.fill(PAL.plateLight, 74);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.16);
  for (let poly of midFolds) drawPolyFill(poly);

  // Batch 2: Deeper fold troughs & cast shadow base
  brush.fill(PAL.plateMid, 82);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.62, 0.20);
  for (let poly of deepTroughs) drawPolyFill(poly);

  // Batch 3: Deepest shadow core under the iron heel & cast shadow
  brush.fill(PAL.plateDark, 90);
  brush.fillBleed(0.38, "out");
  drawPolyFill([[275, 875], [535, 862], [775, 878], [785, 912], [545, 935], [255, 910]]);
  drawPolyFill([[465, 880], [765, 878], [775, 906], [495, 916]]);

  brush.noFill();

  // Pictorialist soft shading along the linen creases using wide, delicate graphite & aquatint
  const creaseCurves = [
    [[55, 775], [230, 755], [445, 785]],
    [[45, 885], [265, 845], [515, 875]],
    [[170, 905], [385, 885], [575, 905]],
    [[55, 1075], [295, 995], [565, 940], [740, 910]],
    [[210, 1150], [485, 1045], [735, 955], [945, 915]],
    [[455, 1160], [695, 1055], [935, 955], [1155, 905]],
    [[780, 840], [970, 810], [1155, 845]],
    [[680, 1155], [915, 1045], [1155, 995]],
    [[790, 745], [980, 735], [1155, 760]]
  ];

  // Soft tonal roll across each linen crease (shallow focus: multiple offset soft passes)
  for (let c = 0; c < creaseCurves.length; c++) {
    let pts = creaseCurves[c];
    for (let pass = -5; pass <= 5; pass++) {
      let offY = pass * 6.5;
      let distFactor = 1 - Math.abs(pass) / 6;
      let col = Math.abs(pass) <= 1 ? PAL.plateDark : (Math.abs(pass) <= 3 ? PAL.plateMid : PAL.plateLight);
      brush.set("velvet_charcoal", col, 0.55 + 0.55 * distFactor);
      let shifted = pts.map(p => [p[0] + random(-4, 4), p[1] + offY + random(-3, 3), 0.4 + 0.5 * distFactor]);
      brush.spline(shifted, 0.55);
    }

    // Luminous soft linen crest just above/beside each trough
    for (let h = 0; h < 4; h++) {
      let crestY = -36 - h * 5.5;
      brush.set("steam_stipple", PAL.paperLight, 1.15);
      let crestPts = pts.map(p => [p[0] + random(-5, 5), p[1] + crestY + random(-3, 3)]);
      brush.spline(crestPts, 0.5);
    }
  }

  // Deep velvety charcoal & aquatint shadow directly beneath the iron heel & cast to the left
  for (let i = 0; i < 65; i++) {
    let t = i / 65;
    let x1 = lerp(210, 490, t * 0.5) + random(-25, 25);
    let x2 = lerp(580, 795, 1 - t * 0.3) + random(-15, 15);
    let y = lerp(868, 932, t) + random(-6, 6);
    brush.set("velvet_charcoal", i < 35 ? PAL.inkDark : PAL.plateDark, random(0.6, 1.2));
    brush.line(x1, y, x2, y + random(-8, 8));
  }

  // Soft linen weave / aquatint stipple across foreground to unify the out-of-focus cloth
  brush.set("aquatint", PAL.plateMid, 1.1);
  for (let i = 0; i < 110; i++) {
    let x = random(40, 1160);
    let y = random(700, 1160);
    let len = random(30, 80);
    let ang = random(-18, 12);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

// =============================================================================
// 3. BRAIDED VINTAGE ELECTRICAL CORD (CHARCOAL MASSING)
// =============================================================================
function renderBraidedCord() {
  // Centerline of the vintage cloth-braided cord emerging from the heel grommet
  const cordSpine = [
    [712, 852],
    [775, 868],
    [875, 902],
    [965, 948],
    [982, 992],
    [925, 1032],
    [815, 1068],
    [775, 1098],
    [825, 1128],
    [965, 1148],
    [1145, 1162]
  ];

  // Sample dense points along the spline for smooth ribbon construction
  let sampled = [];
  let steps = 90;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let seg = t * (cordSpine.length - 1);
    let idx = Math.min(Math.floor(seg), cordSpine.length - 2);
    let f = seg - idx;
    let p0 = cordSpine[Math.max(0, idx - 1)];
    let p1 = cordSpine[idx];
    let p2 = cordSpine[idx + 1];
    let p3 = cordSpine[Math.min(cordSpine.length - 1, idx + 2)];
    // Catmull-Rom interpolation
    let f2 = f * f, f3 = f2 * f;
    let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * f + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f3);
    let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * f + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f3);
    // Cord radius (slightly thicker rubber strain-relief grommet near heel t < 0.14)
    let r = t < 0.13 ? map(t, 0, 0.13, 14.5, 9.5) : 9.2 + 1.8 * t;
    sampled.push({ x, y, r, t });
  }

  // Compute normals and build polygon for cord & cast shadow
  let leftEdge = [];
  let rightEdge = [];
  let shadowPoly = [];
  for (let i = 0; i < sampled.length; i++) {
    let pPrev = sampled[Math.max(0, i - 1)];
    let pNext = sampled[Math.min(sampled.length - 1, i + 1)];
    let dx = pNext.x - pPrev.x;
    let dy = pNext.y - pPrev.y;
    let d = Math.hypot(dx, dy) || 1;
    let nx = -dy / d;
    let ny = dx / d;
    let p = sampled[i];
    leftEdge.push([p.x + nx * p.r, p.y + ny * p.r]);
    rightEdge.unshift([p.x - nx * p.r, p.y - ny * p.r]);
    shadowPoly.push([p.x + nx * p.r - 4, p.y + ny * p.r + 12]);
  }
  for (let i = sampled.length - 1; i >= 0; i--) {
    let p = sampled[i];
    shadowPoly.push([p.x - 4, p.y + 4]);
  }

  // 1. Soft cast shadow of the cord on the linen sheet
  brush.noStroke();
  brush.fill(PAL.plateDark, 85);
  brush.fillBleed(0.35, "out");
  drawPolyFill(shadowPoly);
  brush.noFill();

  for (let i = 0; i < sampled.length - 1; i += 2) {
    let p = sampled[i];
    brush.set("velvet_charcoal", PAL.slateDeep, 0.9);
    brush.line(p.x - 3, p.y + 8, sampled[i + 1].x - 3, sampled[i + 1].y + 11);
  }

  // 2. Charcoal massing for the deep velvety black of the cord
  let cordPoly = leftEdge.concat(rightEdge);
  brush.noStroke();
  brush.wash(PAL.inkDark, 210);
  drawPolyFill(cordPoly);
  brush.noWash();

  brush.mass("charcoal", PAL.inkBlack, {
    precision: 0.72,
    strength: 0.95,
    gradient: 0.15,
    outline: true
  });
  drawPolyFill(cordPoly);
  brush.noMass();

  // 3. Molded rubber strain-relief grommet ribs near the heel (t < 0.13) & braided cloth weave
  for (let i = 1; i < sampled.length - 1; i++) {
    let p = sampled[i];
    let pNext = sampled[i + 1];
    let dx = pNext.x - p.x;
    let dy = pNext.y - p.y;
    let d = Math.hypot(dx, dy) || 1;
    let nx = -dy / d;
    let ny = dx / d;

    // Deep velvety underside core
    brush.set("charcoal", PAL.velvetBlack, 0.85);
    brush.line(p.x - nx * p.r * 0.45, p.y - ny * p.r * 0.45, pNext.x - nx * pNext.r * 0.45, pNext.y - ny * pNext.r * 0.45);

    // Braided diagonal cloth texture & top grazing highlight
    if (i % 2 === 0) {
      let highlightCol = p.t < 0.13 ? PAL.chromeSlate : (p.t < 0.65 ? PAL.plateMid : PAL.plateDark);
      brush.set("2B", highlightCol, 0.75);
      // Diagonal weave mark across the lit upper flank
      let wx1 = p.x + nx * p.r * 0.72;
      let wy1 = p.y + ny * p.r * 0.72;
      let wx2 = pNext.x + nx * pNext.r * 0.15;
      let wy2 = pNext.y + ny * pNext.r * 0.15;
      brush.line(wx1, wy1, wx2, wy2);
    }
  }
}

// =============================================================================
// 4. SCULPTED BAKELITE HANDLE, HEEL REST & THERMOSTAT DIAL
// =============================================================================
function renderHandleAndDial() {
  // Build outer silhouette of the sculpted Bakelite handle + heel rest in (u, w)
  // Handle attaches to the dorsal spine of the chrome hood (v = 0, w = hoodTopW(u))
  const outerProfileUW = [
    [0.00, 120],
    [-0.015, 165], // Heel rest rear foot sitting on linen
    [-0.012, 238], // Heel rest outer corner on linen
    [0.03, 250],   // Rear flare of handle heel
    [0.10, 238],
    [0.22, 226],   // Lower grip arch
    [0.38, 224],   // Center grip arch
    [0.54, 228],
    [0.67, 236],   // Upper grip arch approaching thumb rest
    [0.74, 254],   // Sculpted thumb-rest horn at front top of handle
    [0.79, 248],
    [0.81, 215],   // Front slope down toward steam button
    [0.83, 175],   // Front riser meeting chrome hood
    [0.85, 110]
  ];

  // Inner grip window cutout in (u, w)
  const windowProfileUW = [
    [0.17, 136],
    [0.21, 178],
    [0.34, 184],
    [0.50, 186],
    [0.61, 182],
    [0.64, 145],
    [0.58, 128],
    [0.40, 132],
    [0.22, 134]
  ];

  // Project outer handle contour (with 3D thickness v = -18..+24)
  // Since the handle has 3D cylindrical/sculpted thickness in v, its visible silhouette
  // encompasses the far edge (v = -16) along the top/outer spine and near edge (v = +22) along the bottom
  let handleOuterPts = [];
  for (let i = 0; i < outerProfileUW.length; i++) {
    let [u, w] = outerProfileUW[i];
    let p = projectIron(u, 14, w);
    handleOuterPts.push([p[0], p[1]]);
  }
  // Close along the chrome hood spine from u = 0.85 down to u = 0.00
  for (let u = 0.85; u >= 0.0; u -= 0.05) {
    let p = projectIron(u, 0, hoodTopW(u) - 6);
    handleOuterPts.push([p[0], p[1]]);
  }

  let windowPts = windowProfileUW.map(([u, w]) => {
    let p = projectIron(u, 12, w);
    return [p[0], p[1]];
  });

  // Construct separate top/bottom/post polygons around the open grip window so the window stays open!
  // 1. Rear heel post & base (u = -0.015 .. 0.22)
  let rearPostPts = [
    projectIron(0.00, 0, 118),
    projectIron(-0.015, 18, 165),
    projectIron(-0.012, 18, 238),
    projectIron(0.04, 16, 250),
    projectIron(0.14, 14, 234),
    projectIron(0.22, 14, 226),
    projectIron(0.21, 12, 178),
    projectIron(0.17, 12, 136),
    projectIron(0.18, 0, 134)
  ].map(p => [p[0], p[1]]);

  // 2. Main grip bar (u = 0.18 .. 0.76, w = 178 .. 254)
  let gripBarPts = [
    projectIron(0.18, 14, 230),
    projectIron(0.30, 14, 225),
    projectIron(0.46, 14, 225),
    projectIron(0.62, 14, 232),
    projectIron(0.74, 16, 254),
    projectIron(0.79, 15, 248),
    projectIron(0.81, 14, 212),
    projectIron(0.64, 12, 145),
    projectIron(0.61, 12, 182),
    projectIron(0.50, 12, 186),
    projectIron(0.34, 12, 184),
    projectIron(0.21, 12, 178)
  ].map(p => [p[0], p[1]]);

  // 3. Front riser post (u = 0.58 .. 0.85, w = 108 .. 215)
  let frontPostPts = [
    projectIron(0.58, 0, 122),
    projectIron(0.64, 12, 145),
    projectIron(0.81, 14, 215),
    projectIron(0.83, 12, 175),
    projectIron(0.86, 4, 108),
    projectIron(0.72, 0, 118)
  ].map(p => [p[0], p[1]]);

  // Base dark wash for Bakelite handle components
  brush.noStroke();
  brush.wash(PAL.inkDark, 230);
  drawPolyFill(rearPostPts);
  drawPolyFill(gripBarPts);
  drawPolyFill(frontPostPts);
  brush.noWash();

  // Deep velvety charcoal massing on the Bakelite handle
  brush.mass("charcoal", PAL.inkBlack, {
    precision: 0.78,
    strength: 0.95,
    gradient: 0.2,
    outline: true
  });
  drawPolyFill(rearPostPts);
  drawPolyFill(gripBarPts);
  drawPolyFill(frontPostPts);
  brush.noMass();

  // 3D thickness bevel on the far side of the inner grip window (gives real depth to the cutout!)
  brush.set("velvet_charcoal", PAL.slateDeep, 1.1);
  for (let i = 0; i < windowProfileUW.length; i++) {
    let [u1, w1] = windowProfileUW[i];
    let [u2, w2] = windowProfileUW[(i + 1) % windowProfileUW.length];
    let p1 = projectIron(u1, -8, w1 - 3);
    let p2 = projectIron(u2, -8, w2 - 3);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Crisp inner window contour
  brush.set("2B", PAL.inkBlack, 1.1);
  brush.spline(windowPts.concat([windowPts[0]]), 0.35);

  // Satin-gloss specular highlight strip along the sculpted Bakelite grip spine & thumb rest
  const handleHighlightUW = [
    [0.02, 238],
    [0.14, 226],
    [0.30, 216],
    [0.48, 216],
    [0.64, 224],
    [0.74, 244],
    [0.78, 238]
  ];
  for (let pass = 0; pass < 5; pass++) {
    let wOff = (pass - 2) * 2.2;
    let col = pass === 2 ? PAL.chromeMid : (pass === 1 || pass === 3 ? PAL.chromeSlate : PAL.slateDeep);
    let weight = pass === 2 ? 0.95 : 0.75;
    brush.set("2B", col, weight);
    let pts = handleHighlightUW.map(([u, w]) => {
      let p = projectIron(u, 15, w + wOff);
      return [p[0], p[1], 0.8];
    });
    brush.spline(pts, 0.45);
  }

  // Secondary highlight along the front riser post
  brush.set("2B", PAL.chromeSlate, 0.85);
  let frontGleam = [
    projectIron(0.63, 14, 150),
    projectIron(0.72, 14, 178),
    projectIron(0.80, 14, 206)
  ].map(p => [p[0], p[1]]);
  brush.spline(frontGleam, 0.4);

  // Steam / Spray Valve Button at top front nose of handle (u = 0.80, w = 228..244)
  let btnBase1 = projectIron(0.80, 8, 220);
  let btnBase2 = projectIron(0.83, 8, 192);
  let btnTop1 = projectIron(0.81, 8, 236);
  let btnTop2 = projectIron(0.84, 8, 208);
  brush.noStroke();
  brush.wash(PAL.chromeMid, 210);
  drawPolyFill([[btnBase1[0], btnBase1[1]], [btnTop1[0], btnTop1[1]], [btnTop2[0], btnTop2[1]], [btnBase2[0], btnBase2[1]]]);
  brush.noWash();
  brush.set("fine_needle", PAL.inkBlack, 1.0);
  brush.line(btnBase1[0], btnBase1[1], btnTop1[0], btnTop1[1]);
  brush.line(btnTop1[0], btnTop1[1], btnTop2[0], btnTop2[1]);
  brush.line(btnTop2[0], btnTop2[1], btnBase2[0], btnBase2[1]);
  brush.set("fine_needle", PAL.chromeSpec, 1.1);
  brush.line(btnTop1[0] - 1, btnTop1[1] + 2, btnTop2[0] - 1, btnTop2[1] + 2);

  // =========================================================================
  // HYPERREAL THERMOSTAT FABRIC SELECTOR DIAL (Nestled under handle window)
  // =========================================================================
  // Positioned on the dorsal spine of the chrome hood at u = 0.41, w = 135
  let dialCenter = projectIron(0.41, 10, 136);
  let dialRings = [28, 24, 18, 10];

  // Elliptical foreshortened dial helper
  function dialPt(r, angDeg, wLift = 0) {
    let rad = angDeg * Math.PI / 180;
    let du = Math.cos(rad) * (r / IRON_LEN) * 1.15;
    let dv = Math.sin(rad) * r * 0.85;
    return projectIron(0.41 + du, 10 + dv, 134 + wLift);
  }

  // Dial base disc
  let dialOuterPoly = [];
  for (let a = 0; a < 360; a += 15) {
    let p = dialPt(28, a, 2);
    dialOuterPoly.push([p[0], p[1]]);
  }
  brush.noStroke();
  brush.wash(PAL.chromeDark, 230);
  drawPolyFill(dialOuterPoly);
  brush.noWash();

  // Metallic dial face plate (silver half + dark half reflection)
  let dialLightHalf = [];
  for (let a = -70; a <= 110; a += 15) {
    let p = dialPt(24, a, 5);
    dialLightHalf.push([p[0], p[1]]);
  }
  brush.wash(PAL.chromeBright, 210);
  drawPolyFill(dialLightHalf);
  brush.noWash();

  // Crisp concentric turned-metal rings on the dial
  for (let r of dialRings) {
    let ringPts = [];
    for (let a = 0; a <= 360; a += 15) {
      let p = dialPt(r, a, 5);
      ringPts.push([p[0], p[1]]);
    }
    brush.set("fine_needle", r === 24 ? PAL.chromeSpec : PAL.inkBlack, 0.95);
    brush.spline(ringPts, 0.4);
  }

  // Microscopic radial knurling & fabric-setting graduation ticks around the dial rim
  for (let a = 0; a < 360; a += 12) {
    let p1 = dialPt(24, a, 5);
    let p2 = dialPt(28, a, 2);
    brush.set("fine_needle", a % 24 === 0 ? PAL.chromeSpec : PAL.inkBlack, 0.75);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    // Tiny engraved scale ticks inside the face plate
    if (a % 36 === 0) {
      let t1 = dialPt(15, a, 5.5);
      let t2 = dialPt(21, a, 5.5);
      brush.set("fine_needle", PAL.inkBlack, 0.8);
      brush.line(t1[0], t1[1], t2[0], t2[1]);
    }
  }

  // Sculpted Bakelite pointer flange in the center of the dial
  let ptr1 = dialPt(20, -35, 9);
  let ptr2 = dialPt(8, 75, 9);
  let ptr3 = dialPt(14, 145, 9);
  let ptr4 = dialPt(8, 235, 9);
  brush.noStroke();
  brush.wash(PAL.inkBlack, 245);
  drawPolyFill([[ptr1[0], ptr1[1]], [ptr2[0], ptr2[1]], [ptr3[0], ptr3[1]], [ptr4[0], ptr4[1]]]);
  brush.noWash();
  brush.set("fine_needle", PAL.chromeSpec, 0.9);
  brush.line(ptr1[0], ptr1[1], ptr3[0], ptr3[1]);
}

// =============================================================================
// 5. HYPERREAL POLISHED CHROME SHELL (THE FOCAL HEART)
// =============================================================================
function renderHyperrealChrome() {
  // Build outer boundary of the Chrome Hood for base wash
  let hoodBoundary = [];
  for (let u = 0.0; u <= 0.99; u += 0.03) {
    let p = hoodPoint(u, 0.0);
    hoodBoundary.push([p[0], p[1]]);
  }
  for (let u = 0.99; u >= 0.0; u -= 0.03) {
    let p = hoodPoint(u, 1.0);
    hoodBoundary.push([p[0], p[1]]);
  }

  // Clean metallic base wash
  brush.noStroke();
  brush.wash(PAL.chromeMid, 225);
  drawPolyFill(hoodBoundary);
  brush.noWash();

  // Grid-based tonal patches for the anamorphic studio window & linen reflections
  const NU = 56;
  const NS = 26;
  let darkQuads = [];
  let slateQuads = [];
  let lightQuads = [];
  let specQuads = [];

  for (let iu = 0; iu < NU; iu++) {
    let u0 = iu / NU * 0.985;
    let u1 = (iu + 1) / NU * 0.985;
    for (let is = 0; is < NS; is++) {
      let s0 = is / NS;
      let s1 = (is + 1) / NS;
      let val = chromeReflectionVal((u0 + u1) * 0.5, (s0 + s1) * 0.5);
      let p00 = hoodPoint(u0, s0);
      let p10 = hoodPoint(u1, s0);
      let p11 = hoodPoint(u1, s1);
      let p01 = hoodPoint(u0, s1);
      let q = [[p00[0], p00[1]], [p10[0], p10[1]], [p11[0], p11[1]], [p01[0], p01[1]]];

      if (val < 0.24) {
        darkQuads.push(q);
      } else if (val < 0.48) {
        slateQuads.push(q);
      } else if (val > 0.86) {
        specQuads.push(q);
      } else if (val > 0.68) {
        lightQuads.push(q);
      }
    }
  }

  // Batch render the base reflection zones using fast wash passes
  brush.noStroke();
  brush.wash(PAL.chromeDark, 215);
  for (let q of darkQuads) drawPolyFill(q);
  brush.wash(PAL.chromeSlate, 185);
  for (let q of slateQuads) drawPolyFill(q);
  brush.wash(PAL.chromeBright, 210);
  for (let q of lightQuads) drawPolyFill(q);
  brush.wash(PAL.chromeSpec, 240);
  for (let q of specQuads) drawPolyFill(q);
  brush.noWash();

  // =========================================================================
  // PRECISION ENGRAVED METAL REFLECTION LINES (Hyperreal Focus)
  // =========================================================================
  // 1. Longitudinal flow lines following the compound curvature of the chrome shell
  const S_LINES = 68;
  const U_STEPS = 72;
  for (let is = 0; is <= S_LINES; is++) {
    let s = is / S_LINES;
    for (let iu = 0; iu < U_STEPS; iu++) {
      let u0 = (iu / U_STEPS) * 0.985;
      let u1 = ((iu + 1) / U_STEPS) * 0.985;
      let um = (u0 + u1) * 0.5;
      let val = chromeReflectionVal(um, s);

      let p0 = hoodPoint(u0, s);
      let p1 = hoodPoint(u1, s);

      if (val < 0.16) {
        brush.set("rotring", PAL.inkBlack, 0.95);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      } else if (val < 0.30) {
        brush.set("fine_needle", PAL.chromeDark, 0.9);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      } else if (val < 0.52) {
        if ((is + iu) % 2 === 0) {
          brush.set("2H", PAL.chromeSlate, 0.75);
          brush.line(p0[0], p0[1], p1[0], p1[1]);
        }
      } else if (val > 0.85) {
        brush.set("fine_needle", PAL.chromeSpec, 1.15);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      } else if (val > 0.70 && is % 2 === 0) {
        brush.set("fine_needle", PAL.chromeBright, 0.85);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      }
    }
  }

  // 2. Cross-contour brushed metal & distorted linen-crease reflections along the lower hood & heel
  for (let iu = 1; iu < 64; iu++) {
    let u = iu / 64 * 0.96;
    // Denser cross-contour reflection lines in the lower belly and near the mullion edges
    let stepS = 28;
    for (let is = 0; is < stepS; is++) {
      let s0 = is / stepS;
      let s1 = (is + 1) / stepS;
      let sm = (s0 + s1) * 0.5;
      let val = chromeReflectionVal(u, sm);
      let p0 = hoodPoint(u, s0);
      let p1 = hoodPoint(u, s1);

      if (val < 0.22 && iu % 2 === 0) {
        brush.set("fine_needle", PAL.inkBlack, 0.85);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      } else if (u < 0.32 && val > 0.62) {
        // Sharp warped reflection of the linen ridges in the lower chrome!
        brush.set("fine_needle", PAL.chromeSpec, 0.9);
        brush.line(p0[0], p0[1], p1[0], p1[1]);
      }
    }
  }

  // 3. Razor-sharp embossed Streamline Moderne rib (s = 0.565) & dark step shadow (s = 0.545)
  let ribSpecPts = [];
  let ribShadowPts = [];
  let noseCrestPts = [];
  for (let u = 0.04; u <= 0.96; u += 0.025) {
    let pSpec = hoodPoint(u, 0.568);
    let pShad = hoodPoint(u, 0.542);
    ribSpecPts.push([pSpec[0], pSpec[1], 1.1]);
    ribShadowPts.push([pShad[0], pShad[1], 1.0]);
    if (u >= 0.42) {
      let pNose = hoodPoint(u, 0.29);
      noseCrestPts.push([pNose[0], pNose[1], 1.2]);
    }
  }
  brush.set("rotring", PAL.inkBlack, 1.05);
  brush.spline(ribShadowPts, 0.45);
  brush.set("fine_needle", PAL.chromeSpec, 1.35);
  brush.spline(ribSpecPts, 0.45);
  brush.set("fine_needle", PAL.chromeSpec, 1.25);
  brush.spline(noseCrestPts, 0.45);

  // 4. Crisp assembly details on the chrome shell:
  //    a) Two recessed slotted machine screws (one near heel u=0.09, s=0.38; one near front collar u=0.72, s=0.72)
  const screws = [
    { u: 0.09, s: 0.36, r: 4.5 },
    { u: 0.72, s: 0.70, r: 4.2 }
  ];
  for (let sc of screws) {
    let cp = hoodPoint(sc.u, sc.s);
    brush.set("rotring", PAL.inkBlack, 0.9);
    brush.circle(cp[0], cp[1], sc.r, 0.08);
    // Specular lower-right rim of countersunk screw
    brush.set("fine_needle", PAL.chromeSpec, 1.1);
    brush.arc(cp[0], cp[1], sc.r + 0.8, -35, 115);
    // Screw slot line
    brush.set("rotring", PAL.inkBlack, 0.95);
    brush.line(cp[0] - sc.r * 0.7, cp[1] - sc.r * 0.4, cp[0] + sc.r * 0.7, cp[1] + sc.r * 0.4);
  }

  //    b) Crisp metallic collar seam where the front Bakelite handle post meets the chrome dome
  let collarPts = [];
  for (let u = 0.58; u <= 0.84; u += 0.04) {
    let p = hoodPoint(u, 0.92);
    collarPts.push([p[0], p[1]]);
  }
  brush.set("rotring", PAL.inkBlack, 1.0);
  brush.spline(collarPts, 0.4);
  let collarSpec = collarPts.map(p => [p[0] - 1.8, p[1] + 1.2]);
  brush.set("fine_needle", PAL.chromeSpec, 1.1);
  brush.spline(collarSpec, 0.4);
}

// =============================================================================
// 6. SOLEPLATE & BEVELED METALLIC RIM (DEEP VELVETY CHARCOAL MASSING)
// =============================================================================
function renderSoleplate() {
  // 1. The 18px Beveled Aluminum/Steel Rim (w = 0..18) along the near edge (v = +soleHalfWidth)
  //    and around the heel (u = 0) and pointed tip (u = 1.0)
  let bevelNearPts = [];
  for (let u = 0.0; u <= 1.0; u += 0.02) {
    let p = projectIron(u, soleHalfWidth(u), 0);
    bevelNearPts.push([p[0], p[1]]);
  }
  for (let u = 1.0; u >= 0.0; u -= 0.02) {
    let p = projectIron(u, soleHalfWidth(u) * 0.96, 18);
    bevelNearPts.push([p[0], p[1]]);
  }

  // Base metallic fill of the soleplate bevel
  brush.noStroke();
  brush.wash(PAL.chromeMid, 225);
  drawPolyFill(bevelNearPts);
  brush.noWash();

  // Render the button-nook groove (at w = 9) and sharp metallic highlights along the bevel
  let grooveShadowPts = [];
  let bevelFrontSpec = [];
  let bevelBackSpec = [];
  let skirtSeamPts = [];
  for (let u = 0.0; u <= 1.0; u += 0.02) {
    let hw = soleHalfWidth(u);
    let p0 = projectIron(u, hw, 2.5);
    let pGroove = projectIron(u, hw * 0.97, 9.0);
    let pBack = projectIron(u, hw * 0.975, 13.5);
    let pSeam = projectIron(u, hw * 0.96, 18.0);
    bevelFrontSpec.push([p0[0], p0[1], 1.1]);
    grooveShadowPts.push([pGroove[0], pGroove[1], 1.0]);
    bevelBackSpec.push([pBack[0], pBack[1], 1.0]);
    skirtSeamPts.push([pSeam[0], pSeam[1], 1.0]);
  }

  // Fine cross-contour metallic reflections along the bevel edge
  for (let u = 0.02; u < 0.98; u += 0.012) {
    let hw = soleHalfWidth(u);
    let pA = projectIron(u, hw, 0);
    let pB = projectIron(u, hw * 0.96, 18);
    let tone = Math.sin(u * 28) > 0.15 ? PAL.chromeSpec : PAL.chromeSlate;
    brush.set("fine_needle", tone, 0.85);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  brush.set("rotring", PAL.inkBlack, 1.05);
  brush.spline(grooveShadowPts, 0.45);
  brush.set("rotring", PAL.inkBlack, 1.15);
  brush.spline(skirtSeamPts, 0.45);
  brush.set("fine_needle", PAL.chromeSpec, 1.35);
  brush.spline(bevelFrontSpec, 0.45);
  brush.set("fine_needle", PAL.chromeBright, 1.1);
  brush.spline(bevelBackSpec, 0.45);

  // Heel bottom bevel rim (u = 0, v in [-hw, +hw], w = 0..18)
  let heelRimPts = [];
  let hw0 = soleHalfWidth(0);
  for (let v = -hw0; v <= hw0; v += 15) {
    let p = projectIron(0, v, 0);
    heelRimPts.push([p[0], p[1]]);
  }
  for (let v = hw0; v >= -hw0; v -= 15) {
    let p = projectIron(0, v * 0.96, 18);
    heelRimPts.push([p[0], p[1]]);
  }
  brush.noStroke();
  brush.wash(PAL.slateDeep, 230);
  drawPolyFill(heelRimPts);
  brush.noWash();

  // =========================================================================
  // 2. THE FLAT SOLEPLATE FACE (w = 0): DEEP VELVETY CHARCOAL MASSING
  // =========================================================================
  let solePoly = [];
  for (let u = 0.0; u <= 1.0; u += 0.02) {
    let p = projectIron(u, -soleHalfWidth(u), 0);
    solePoly.push([p[0], p[1]]);
  }
  for (let u = 0.98; u >= 0.0; u -= 0.02) {
    let p = projectIron(u, soleHalfWidth(u), 0);
    solePoly.push([p[0], p[1]]);
  }

  // Deep ink under-wash so zero light paper peeks through the soleplate
  brush.noStroke();
  brush.wash(PAL.inkDark, 245);
  drawPolyFill(solePoly);
  brush.noWash();

  // Primary charcoal massing pass across the entire soleplate
  brush.mass("charcoal", PAL.inkBlack, {
    precision: 0.68,
    strength: 0.96,
    gradient: 0.22,
    outline: true
  });
  drawPolyFill(solePoly);
  brush.noMass();

  // Secondary deepest carbon-black massing in the lower and central soleplate belly (u = 0.0..0.72)
  let bellySolePoly = [];
  for (let u = 0.0; u <= 0.72; u += 0.03) {
    let p = projectIron(u, -soleHalfWidth(u) * 0.85, 0);
    bellySolePoly.push([p[0], p[1]]);
  }
  for (let u = 0.72; u >= 0.0; u -= 0.03) {
    let p = projectIron(u, soleHalfWidth(u) * 0.96, 0);
    bellySolePoly.push([p[0], p[1]]);
  }
  brush.mass("charcoal", PAL.velvetBlack, {
    precision: 0.62,
    strength: 0.92,
    gradient: 0.15,
    outline: false
  });
  drawPolyFill(bellySolePoly);
  brush.noMass();

  // Subtle oblique grazing metallic sheen near the pointed tip (u > 0.68) and far-left edge
  for (let u = 0.04; u <= 0.97; u += 0.014) {
    let hw = soleHalfWidth(u);
    let pLeft = projectIron(u, -hw, 0);
    let pMid = projectIron(u, -hw * 0.25, 0);
    let pRight = projectIron(u, hw * 0.95, 0);

    // Velvety directional charcoal texture across the soleplate width
    brush.set("velvet_charcoal", u < 0.62 ? PAL.velvetBlack : PAL.inkBlack, 0.85);
    brush.line(pLeft[0], pLeft[1], pRight[0], pRight[1]);

    // Cool slate grazing light near the far-left rim & upper nose
    if (u > 0.35) {
      let sheenCol = u > 0.72 ? PAL.plateDark : PAL.slateDeep;
      brush.set("2B", sheenCol, 0.75);
      brush.line(pLeft[0], pLeft[1], pMid[0], pMid[1]);
    }
  }

  // Crisp far-left contour & inner bevel line of the soleplate
  let farContour = [];
  let innerGrooveLeft = [];
  let innerGrooveRight = [];
  for (let u = 0.04; u <= 0.96; u += 0.025) {
    let hw = soleHalfWidth(u);
    let pEdge = projectIron(u, -hw, 0);
    farContour.push([pEdge[0], pEdge[1]]);
    if (u >= 0.26 && u <= 0.93) {
      let pGL = projectIron(u, -hw * 0.70, 0);
      let pGR = projectIron(u, hw * 0.70, 0);
      innerGrooveLeft.push([pGL[0], pGL[1]]);
      innerGrooveRight.push([pGR[0], pGR[1]]);
    }
  }
  brush.set("charcoal", PAL.inkBlack, 1.0);
  brush.spline(farContour, 0.45);

  // =========================================================================
  // 3. RECESSED STEAM DISTRIBUTION CHANNELS & 15 STEAM VENTS
  // =========================================================================
  // Pressed steam channel connecting the upper vents (u = 0.28..0.92)
  brush.set("velvet_charcoal", PAL.velvetBlack, 1.1);
  brush.spline(innerGrooveLeft, 0.45);
  brush.spline(innerGrooveRight, 0.45);

  // Subtle catchlight lip on the near side of the recessed steam channel
  let grooveLipLeft = innerGrooveLeft.map(p => [p[0] + 2.2, p[1] + 0.8]);
  let grooveLipRight = innerGrooveRight.map(p => [p[0] + 2.4, p[1] + 0.8]);
  brush.set("2H", PAL.chromeSlate, 0.85);
  brush.spline(grooveLipLeft, 0.45);
  brush.spline(grooveLipRight, 0.45);

  // Central elongated teardrop recess on the soleplate belly (u = 0.36..0.64, v = -24..+24)
  let centerRecess = [];
  for (let a = 0; a <= 360; a += 20) {
    let rad = a * Math.PI / 180;
    let ru = 0.50 + 0.14 * Math.cos(rad);
    let rv = 22 * Math.sin(rad) * (1 - 0.35 * Math.cos(rad));
    let p = projectIron(ru, rv, 0);
    centerRecess.push([p[0], p[1]]);
  }
  brush.set("charcoal", PAL.velvetBlack, 0.95);
  brush.spline(centerRecess, 0.4);
  // Catchlight on the right rim of the central recess
  for (let a = -60; a <= 60; a += 15) {
    let rad1 = a * Math.PI / 180;
    let rad2 = (a + 15) * Math.PI / 180;
    let p1 = projectIron(0.50 + 0.14 * Math.cos(rad1), 22 * Math.sin(rad1), 0);
    let p2 = projectIron(0.50 + 0.14 * Math.cos(rad2), 22 * Math.sin(rad2), 0);
    brush.set("fine_needle", PAL.chromeSlate, 0.85);
    brush.line(p1[0] + 1.5, p1[1], p2[0] + 1.5, p2[1]);
  }

  // 15 Recessed Circular Steam Vents arranged in a chevron arch along the soleplate
  const ventPositions = [
    { u: 0.91, vFrac: 0.0, r: 6.5 }, // Apex nose vent
    { u: 0.84, vFrac: -0.68, r: 6.2 }, { u: 0.84, vFrac: 0.68, r: 6.8 },
    { u: 0.76, vFrac: -0.70, r: 6.4 }, { u: 0.76, vFrac: 0.70, r: 7.0 },
    { u: 0.68, vFrac: -0.70, r: 6.5 }, { u: 0.68, vFrac: 0.70, r: 7.2 },
    { u: 0.59, vFrac: -0.70, r: 6.5 }, { u: 0.59, vFrac: 0.70, r: 7.2 },
    { u: 0.50, vFrac: -0.70, r: 6.4 }, { u: 0.50, vFrac: 0.70, r: 7.1 },
    { u: 0.41, vFrac: -0.69, r: 6.2 }, { u: 0.41, vFrac: 0.69, r: 6.9 },
    { u: 0.32, vFrac: -0.66, r: 6.0 }, { u: 0.32, vFrac: 0.66, r: 6.6 }
  ];

  for (let vp of ventPositions) {
    let hw = soleHalfWidth(vp.u);
    let vCenter = vp.vFrac * hw;
    // Project foreshortened ellipse for each countersunk steam hole
    let holeOuter = [];
    let holeInner = [];
    for (let a = 0; a < 360; a += 24) {
      let rad = a * Math.PI / 180;
      let du = Math.cos(rad) * (vp.r * 1.45 / IRON_LEN);
      let dv = Math.sin(rad) * (vp.r * 1.35);
      let pOut = projectIron(vp.u + du, vCenter + dv, 0);
      let pIn = projectIron(vp.u + du * 0.62, vCenter + dv * 0.62, 2.5);
      holeOuter.push([pOut[0], pOut[1]]);
      holeInner.push([pIn[0], pIn[1]]);
    }

    // Countersunk bevel shadow
    brush.noStroke();
    brush.wash(PAL.velvetBlack, 250);
    drawPolyFill(holeOuter);
    brush.noWash();

    // Crisp metallic crescent glint on the right/lower countersunk lip of each steam vent
    for (let a = -55; a <= 75; a += 20) {
      let rad1 = a * Math.PI / 180;
      let rad2 = (a + 20) * Math.PI / 180;
      let p1 = projectIron(vp.u + Math.cos(rad1) * (vp.r * 1.45 / IRON_LEN), vCenter + Math.sin(rad1) * (vp.r * 1.35), 0);
      let p2 = projectIron(vp.u + Math.cos(rad2) * (vp.r * 1.45 / IRON_LEN), vCenter + Math.sin(rad2) * (vp.r * 1.35), 0);
      brush.set("fine_needle", vp.u > 0.55 ? PAL.chromeMid : PAL.chromeSlate, 0.95);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Subtle mineral/steam halo ring around the upper active vents
    if (vp.u >= 0.50) {
      let cp = projectIron(vp.u, vCenter, 0);
      brush.set("steam_stipple", PAL.plateLight, 0.75);
      brush.circle(cp[0], cp[1], vp.r * 1.3, 0.25);
    }
  }
}

