// =============================================================================
function renderUnfurlingSteam() {
  // 1. Immediate steam jets emerging from the upper 9 soleplate vents (u = 0.50..0.91)
  //    They project slightly forward-left (-w direction) before curling buoyantly upward!
  const activeVents = [
    { u: 0.91, vFrac: 0.0, strength: 1.0 },
    { u: 0.84, vFrac: -0.68, strength: 0.92 },
    { u: 0.84, vFrac: 0.68, strength: 0.95 },
    { u: 0.76, vFrac: -0.70, strength: 0.88 },
    { u: 0.76, vFrac: 0.70, strength: 0.90 },
    { u: 0.68, vFrac: -0.70, strength: 0.80 },
    { u: 0.68, vFrac: 0.70, strength: 0.82 },
    { u: 0.59, vFrac: -0.70, strength: 0.68 },
    { u: 0.59, vFrac: 0.70, strength: 0.72 },
    { u: 0.50, vFrac: -0.70, strength: 0.52 },
    { u: 0.50, vFrac: 0.70, strength: 0.55 }
  ];

  for (let av of activeVents) {
    let hw = soleHalfWidth(av.u);
    let p0 = projectIron(av.u, av.vFrac * hw, 0);
    // Outward + upward curl trajectory from each vent
    let p1 = [p0[0] - 28 * av.strength, p0[1] - 18 * av.strength];
    let p2 = [p0[0] - 52 * av.strength + sin(av.u * 400) * 14, p0[1] - 68 * av.strength];
    let p3 = [p0[0] - 42 * av.strength + cos(av.u * 500) * 24, p0[1] - 145 * av.strength];

    for (let k = 0; k < 14; k++) {
      let jitX = random(-12, 12) * (k / 14 + 0.2);
      let jitY = random(-10, 10) * (k / 14 + 0.2);
      let col = k < 5 ? PAL.steamBright : (k < 10 ? PAL.steamLight : PAL.steamMid);
      brush.set("steam_stipple", col, random(0.75, 1.35) * av.strength);
      brush.spline([
        [p0[0] + random(-3, 3), p0[1] + random(-3, 3)],
        [p1[0] + jitX * 0.4, p1[1] + jitY * 0.4],
        [p2[0] + jitX * 0.8, p2[1] + jitY * 0.8],
        [p3[0] + jitX * 1.4, p3[1] + jitY * 1.4]
      ], 0.55);
    }
  }

  // 2. Grand unfurling steam plumes rising from the soleplate nose into the upper plate (y: 560 -> 45)
  //    Constructed from multi-layered stipple bands so the vapor curls in 3D and dissolves into the paper grain
  const mainPlumes = [
    // Primary central-left billowing plume rising from the nose tip
    {
      spine: [[445, 420], [405, 345], [385, 260], [425, 175], [395, 95], [355, 42]],
      spread: [18, 34, 48, 64, 85, 115],
      density: 62
    },
    // Secondary inner curl rising from the right-side vents across the iron tip & handle arch
    {
      spine: [[505, 510], [475, 425], [468, 330], [505, 240], [485, 145], [535, 65]],
      spread: [16, 28, 42, 56, 76, 105],
      density: 54
    },
    // Lower left languid wisp drifting out from the mid-soleplate vents and dissolving left
    {
      spine: [[435, 565], [375, 510], [320, 440], [295, 355], [335, 265], [305, 175]],
      spread: [14, 26, 40, 58, 78, 98],
      density: 44
    },
    // Delicate trailing eddy curling back toward the upper right above the handle
    {
      spine: [[470, 310], [525, 255], [585, 200], [575, 125], [635, 65]],
      spread: [15, 28, 44, 65, 92],
      density: 36
    }
  ];

  // Pass A: Soft mid-tone aquatint shadow hollows inside & around the curling eddies
  for (let plume of mainPlumes) {
    let n = plume.spine.length;
    for (let i = 0; i < plume.density * 0.65; i++) {
      let side = random() < 0.5 ? -1 : 1;
      let offsetFrac = random(0.45, 1.25) * side;
      let pts = [];
      for (let j = 0; j < n; j++) {
        let sp = plume.spread[j];
        let curlWave = Math.sin(j * 1.4 + i * 0.2) * sp * 0.35;
        let x = plume.spine[j][0] + offsetFrac * sp + curlWave + random(-10, 10);
        let y = plume.spine[j][1] + random(-12, 12);
        pts.push([x, y]);
      }
      let col = Math.abs(offsetFrac) > 0.85 ? PAL.plateMid : PAL.plateLight;
      brush.set("aquatint", col, random(0.85, 1.35));
      brush.spline(pts, 0.55);
    }
  }

  // Pass B: Luminous cream & pearl spray stipple building the volumetric core and dissolving edges
  for (let plume of mainPlumes) {
    let n = plume.spine.length;
    for (let i = 0; i < plume.density; i++) {
      // Concentrate brighter stipple near the curved ridge of each plume, softer toward the top & edges
      let radial = (random() + random() - 1.0); // bell-shaped distribution in [-1, 1]
      let pts = [];
      for (let j = 0; j < n; j++) {
        let sp = plume.spread[j];
        let billow = Math.sin(j * 1.6 + i * 0.15) * sp * 0.28;
        let x = plume.spine[j][0] + radial * sp * 0.85 + billow + random(-8, 8);
        let y = plume.spine[j][1] + random(-9, 9);
        pts.push([x, y]);
      }

      let distFromCore = Math.abs(radial);
      let col = distFromCore < 0.28 ? PAL.steamBright : (distFromCore < 0.62 ? PAL.steamLight : PAL.steamMid);
      let weight = map(distFromCore, 0, 1, 1.35, 0.75) * random(0.85, 1.15);
      brush.set("steam_stipple", col, weight);
      brush.spline(pts, 0.6);
    }
  }

  // Pass C: Vector-field flowLine stipple wisps so the upper steam dissolves imperceptibly into the paper
  brush.field("gravure_steam");
  for (let i = 0; i < 190; i++) {
    let t = random();
    // Sample along the rising steam corridor (x: 250..640, y: 55..560)
    let y = lerp(550, 52, Math.pow(t, 0.85));
    let centerX = lerp(460, 415, t) + Math.sin(y * 0.018) * 55;
    let spreadX = lerp(65, 185, t);
    let x = centerX + (random() + random() - 1.0) * spreadX;

    let distNorm = Math.abs(x - centerX) / spreadX;
    let col;
    if (distNorm < 0.35 && t < 0.78) {
      col = PAL.steamBright;
    } else if (distNorm < 0.68) {
      col = PAL.steamLight;
    } else {
      col = random() < 0.5 ? PAL.steamMid : PAL.plateLight;
    }

    brush.set("steam_stipple", col, random(0.65, 1.3));
    brush.flowLine(x, y, random(35, 95), -85 + random(-22, 22));
  }
  brush.noField();
}

