function renderAquatintAndPlateBorder() {
  // 1. Heavier photogravure plate-tone haze at the four corners & outer edges
  const corners = [
    { cx: 40, cy: 40, rx: 380, ry: 360, angStart: 0, angEnd: 90 },
    { cx: 1160, cy: 40, rx: 380, ry: 360, angStart: 90, angEnd: 180 },
    { cx: 40, cy: 1160, rx: 360, ry: 340, angStart: 270, angEnd: 360 },
    { cx: 1160, cy: 1160, rx: 380, ry: 340, angStart: 180, angEnd: 270 }
  ];

  for (let c of corners) {
    for (let i = 0; i < 65; i++) {
      let rFrac = Math.pow(random(), 1.35);
      let ang = random(c.angStart, c.angEnd);
      let x = c.cx + cos(ang) * c.rx * rFrac;
      let y = c.cy + sin(ang) * c.ry * rFrac;
      x = constrain(x, 36, 1164);
      y = constrain(y, 36, 1164);

      let col = rFrac < 0.38 ? PAL.inkDark : (rFrac < 0.70 ? PAL.slateDeep : PAL.plateDark);
      brush.set("aquatint", col, random(0.85, 1.45));
      let tangent = ang + 90 + random(-25, 25);
      let len = random(28, 72);
      brush.line(x, y, x + cos(tangent) * len, y + sin(tangent) * len);
    }
  }

  // Edge plate-tone haze along top, bottom, left, right borders
  for (let i = 0; i < 140; i++) {
    let edge = i % 4;
    let x, y, ang;
    if (edge === 0) { x = random(40, 1160); y = random(34, 115); ang = random(-12, 12); }
    else if (edge === 1) { x = random(40, 1160); y = random(1085, 1166); ang = random(-12, 12); }
    else if (edge === 2) { x = random(34, 115); y = random(40, 1160); ang = 90 + random(-12, 12); }
    else { x = random(1085, 1166); y = random(40, 1160); ang = 90 + random(-12, 12); }

    brush.set("aquatint", random() < 0.45 ? PAL.plateDark : PAL.plateMid, random(0.75, 1.25));
    let len = random(30, 75);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // 2. Fine overall aquatint grain across the print (sparing the hyperreal chrome hood so it stays crisp)
  for (let i = 0; i < 180; i++) {
    let x = random(38, 1162);
    let y = random(38, 1162);
    // Keep the polished chrome hood free of coarse over-grain so its reflection remains hyper-sharp
    if (x > 520 && x < 715 && y > 355 && y < 865) continue;
    let col = random() < 0.5 ? PAL.paperLight : PAL.plateMid;
    brush.set("aquatint", col, random(0.55, 0.95));
    let ang = random(360);
    brush.line(x, y, x + cos(ang) * random(15, 38), y + sin(ang) * random(15, 38));
  }

  // 3. Debossed Copper Plate Impression Border at [32, 32, 1168, 1168]
  //    Outer bevel shadow line + inner paper highlight + slight ink buildup at plate corners
  brush.set("2H", PAL.plateMid, 0.85);
  brush.line(31, 31, 1169, 31);
  brush.line(31, 31, 31, 1169);
  brush.set("2H", PAL.plateDark, 0.9);
  brush.line(1169, 31, 1169, 1169);
  brush.line(31, 1169, 1169, 1169);

  // Subtle inner plate bevel highlight
  brush.set("fine_needle", PAL.paperLight, 1.1);
  brush.line(33, 33, 1167, 33);
  brush.line(33, 33, 33, 1167);

  // Slight gravure ink wipe buildup along the copper plate corners
  const plateCorners = [
    [[32, 85], [32, 32], [85, 32]],
    [[1115, 32], [1168, 32], [1168, 85]],
    [[32, 1115], [32, 1168], [85, 1168]],
    [[1115, 1168], [1168, 1168], [1168, 1115]]
  ];
  for (let pc of plateCorners) {
    brush.set("charcoal", PAL.slateDeep, 0.75);
    brush.spline(pc, 0.15);
  }
}

