// ============================================================================
// GEOMETRY & PARAMETRIC SPINE HELPERS
// ============================================================================

function catmullRom(p0, p1, p2, p3, u) {
  let u2 = u * u;
  let u3 = u2 * u;
  return 0.5 * (
    (2 * p1) +
    (-p0 + p2) * u +
    (2 * p0 - 5 * p1 + 4 * p2 - p3) * u2 +
    (-p0 + 3 * p1 - 3 * p2 + p3) * u3
  );
}

function evalSpine(t) {
  t = constrain(t, 0, 1);
  let n = SPINE_PTS.length - 1;
  let scaled = t * n;
  let idx = min(floor(scaled), n - 1);
  let u = scaled - idx;

  let i0 = max(0, idx - 1);
  let i1 = idx;
  let i2 = min(n, idx + 1);
  let i3 = min(n, idx + 2);

  let x = catmullRom(SPINE_PTS[i0][0], SPINE_PTS[i1][0], SPINE_PTS[i2][0], SPINE_PTS[i3][0], u);
  let y = catmullRom(SPINE_PTS[i0][1], SPINE_PTS[i1][1], SPINE_PTS[i2][1], SPINE_PTS[i3][1], u);
  let r = catmullRom(constRADII[i0], constRADII[i1], constRADII[i2], constRADII[i3], u);

  // Numerical derivative for smooth tangent and normal
  let dt = 0.002;
  let tA = max(0, t - dt);
  let tB = min(1, t + dt);
  let sA = tA * n, idxA = min(floor(sA), n - 1), uA = sA - idxA;
  let sB = tB * n, idxB = min(floor(sB), n - 1), uB = sB - idxB;

  let xA = catmullRom(SPINE_PTS[max(0, idxA - 1)][0], SPINE_PTS[idxA][0], SPINE_PTS[min(n, idxA + 1)][0], SPINE_PTS[min(n, idxA + 2)][0], uA);
  let yA = catmullRom(SPINE_PTS[max(0, idxA - 1)][1], SPINE_PTS[idxA][1], SPINE_PTS[min(n, idxA + 1)][1], SPINE_PTS[min(n, idxA + 2)][1], uA);
  let xB = catmullRom(SPINE_PTS[max(0, idxB - 1)][0], SPINE_PTS[idxB][0], SPINE_PTS[min(n, idxB + 1)][0], SPINE_PTS[min(n, idxB + 2)][0], uB);
  let yB = catmullRom(SPINE_PTS[max(0, idxB - 1)][1], SPINE_PTS[idxB][1], SPINE_PTS[min(n, idxB + 1)][1], SPINE_PTS[min(n, idxB + 2)][1], uB);

  let dx = xB - xA;
  let dy = yB - yA;
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len;
  let ty = dy / len;

  // Clockwise loop in screen coords: outer dorsal normal is (ty, -tx)
  let nx = ty;
  let ny = -tx;

  return { x, y, r, tx, ty, nx, ny };
}

// s in [-1, 1]: -1 is inner ventral edge, +1 is outer dorsal ridge
function shellPoint(t, s, rScale = 1.0) {
  let sp = evalSpine(t);
  let rad = sp.r * rScale;
  return [
    sp.x + sp.nx * s * rad,
    sp.y + sp.ny * s * rad
  ];
}

