function drawIndigoCloth() {
  background("#04081c");
  brush.noField();

  // Deep diagonal cloth drapery washes
  const folds = [
    { pts: [[0, 0], [520, 0], [0, 560]], col: "#091540", op: 95 },
    { pts: [[480, 0], [1200, 0], [1200, 380], [0, 1180], [0, 520]], col: "#0c1d56", op: 85 },
    { pts: [[1200, 260], [1200, 780], [320, 1200], [0, 1200], [0, 960]], col: "#061030", op: 110 },
    { pts: [[760, 0], [1160, 0], [360, 820], [120, 680]], col: "#142e7a", op: 55 },
    { pts: [[1200, 520], [1200, 1200], [540, 1200]], col: "#0a1948", op: 90 },
    { pts: [[640, 220], [1200, 40], [1200, 340], [580, 520]], col: "#1a3b96", op: 45 }
  ];

  brush.noStroke();
  for (let f of folds) {
    brush.fill(f.col, f.op);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.55, 0.25);
    brush.beginShape(0.3);
    for (let p of f.pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  }
  brush.noFill();

  // Damp darkened indigo halo under the ice mound (meltwater soaked into cloth)
  brush.noStroke();
  brush.fill("#02040f", 165);
  brush.fillBleed(0.45, "out");
  brush.beginShape(0.45);
  const haloPts = [
    [530, 505], [700, 585], [765, 745], [710, 945],
    [550, 1085], [310, 1125], [125, 1020], [75, 835],
    [105, 625], [235, 495], [390, 475]
  ];
  for (let p of haloPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // Subtle woven linen/velvet grain across the indigo cloth
  // Warp threads (diagonal ~ -32 deg) and Weft threads (~ 58 deg)
  for (let i = 0; i < 420; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let len = random(45, 160);
    let ang = -32 + sin(x * 0.25 + y * 0.2) * 4;
    let dx = cos(ang) * len;
    let dy = sin(ang) * len;

    // Brighter indigo weave highlights in the upper-right negative space
    let distIce = dist(x, y, 380, 780);
    let col = distIce > 380
      ? (random() < 0.45 ? "#1b3ea3" : (random() < 0.6 ? "#102566" : "#050b24"))
      : (random() < 0.5 ? "#0b1a4a" : "#030616");

    brush.set("cpencil", col, random(0.28, 0.55));
    brush.line(x, y, x + dx, y + dy);
  }

  for (let i = 0; i < 260; i++) {
    let x = random(30, 1170);
    let y = random(30, 1170);
    let len = random(25, 85);
    let ang = 58 + cos(x * 0.2 + y * 0.25) * 3;
    let col = random() < 0.35 ? "#2148b8" : "#071238";
    brush.set("fine_cp", col, random(0.22, 0.42));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Soft fold ridges along the cloth in coloured pencil
  const ridgeCurves = [
    [[80, 380], [340, 280], [680, 150], [1060, 40]],
    [[440, 470], [720, 350], [980, 210], [1180, 110]],
    [[640, 740], [880, 610], [1150, 440]],
    [[540, 990], [840, 850], [1160, 690]]
  ];
  for (let rc of ridgeCurves) {
    for (let s = -4; s <= 4; s += 2) {
      let shifted = rc.map(p => [p[0] + s * 2.2, p[1] + s * 3.5]);
      brush.set("cpencil", s < 0 ? "#1f45b0" : "#04091f", 0.45);
      brush.spline(shifted, 0.45);
    }
  }
}

