let iceShards = [];

function generateIceShards() {
  iceShards = [];
  // Main bed under and around the prawn boteh
  for (let i = 0; i < 145; i++) {
    let angle = random(360);
    let rad = pow(random(), 0.72) * 310;
    // Skew bed slightly along the boteh contour
    let cx = 385 + cos(angle) * rad * 0.95 + (sin(angle) > 0 ? 35 : -15);
    let cy = 775 + sin(angle) * rad * 1.05;

    let distFromCore = dist(cx, cy, 385, 775);
    let size = map(distFromCore, 0, 330, random(26, 52), random(9, 24));
    size = constrain(size, 8, 54);

    // Distance to prawn spine for coral-pink subsurface reflection
    let minPrawnDist = 999;
    for (let sp of SPINE_PTS) {
      let d = dist(cx, cy, sp[0], sp[1]);
      if (d < minPrawnDist) minPrawnDist = d;
    }

    let sides = floor(random(5, 8));
    let pts = [];
    let baseRot = random(360);
    for (let k = 0; k < sides; k++) {
      let a = baseRot + k * (360 / sides) + random(-18, 18);
      let r = size * random(0.62, 1.15);
      pts.push([cx + cos(a) * r, cy + sin(a) * r]);
    }

    iceShards.push({
      cx, cy, size, pts, minPrawnDist, distFromCore,
      isForeground: (minPrawnDist > 52 && minPrawnDist < 95 && random() < 0.24)
    });
  }

  // Scattered stray ice granules & meltwater drops further out on the cloth
  const straySpots = [
    [685, 620], [725, 665], [750, 725], [690, 825], [645, 915],
    [575, 995], [475, 1055], [340, 1075], [205, 1020], [130, 910],
    [105, 765], [135, 620], [215, 520], [335, 485], [465, 510],
    [630, 565], [785, 680], [665, 965], [260, 1065]
  ];
  for (let sp of straySpots) {
    let cx = sp[0] + random(-14, 14);
    let cy = sp[1] + random(-14, 14);
    let size = random(7, 17);
    let sides = floor(random(4, 7));
    let pts = [];
    for (let k = 0; k < sides; k++) {
      let a = k * (360 / sides) + random(-15, 15);
      let r = size * random(0.65, 1.15);
      pts.push([cx + cos(a) * r, cy + sin(a) * r]);
    }
    iceShards.push({
      cx, cy, size, pts, minPrawnDist: 160, distFromCore: 320, isForeground: false
    });
  }
}

function drawSingleIceShard(shard, brightBoost = false) {
  let { cx, cy, size, pts, minPrawnDist } = shard;

  // Determine translucent facet color
  let fillCol = "#183e82";
  let fillOp = 115;
  if (minPrawnDist < 95 && random() < 0.45) {
    // Subsurface coral/salmon reflection from the prawn shell
    fillCol = random() < 0.5 ? "#8c3b68" : "#c9526b";
    fillOp = 95;
  } else {
    let r = random();
    if (r < 0.28) { fillCol = "#0e265c"; fillOp = 135; }
    else if (r < 0.58) { fillCol = "#2155a3"; fillOp = 110; }
    else if (r < 0.84) { fillCol = "#488fd6"; fillOp = 95; }
    else { fillCol = "#89ccf5"; fillOp = 85; }
  }

  brush.noStroke();
  brush.wash(fillCol, fillOp);
  brush.beginShape(0.08);
  for (let p of pts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Internal cleavage planes (divide crystal into 2-3 facets)
  let pA = pts[0];
  let pB = pts[floor(pts.length / 2)];
  let pC = pts[floor(pts.length * 0.75)];
  let midX = cx + random(-size * 0.2, size * 0.2);
  let midY = cy + random(-size * 0.2, size * 0.2);

  // Upper-left bright facet wash
  brush.noStroke();
  brush.wash(brightBoost ? "#d8f3ff" : "#78bef0", brightBoost ? 130 : 75);
  brush.beginShape(0.05);
  brush.vertex(pA[0], pA[1]);
  brush.vertex(pts[1][0], pts[1][1]);
  brush.vertex(midX, midY);
  brush.endShape(true);
  brush.noWash();

  // Coloured pencil facet hatching
  let hatchAng = atan2(pB[1] - pA[1], pB[0] - pA[0]);
  let hCol = minPrawnDist < 85 && random() < 0.35 ? "#ff7a8a" : "#62b2f0";
  brush.set("fine_cp", hCol, 0.32);
  for (let f = 0.2; f <= 0.8; f += 0.25) {
    let lx1 = lerp(pA[0], midX, f);
    let ly1 = lerp(pA[1], midY, f);
    let lx2 = lerp(pts[1][0], pB[0], f);
    let ly2 = lerp(pts[1][1], pB[1], f);
    brush.line(lx1, ly1, lx2, ly2);
  }

  // Crisp crystal edges
  for (let k = 0; k < pts.length; k++) {
    let q1 = pts[k];
    let q2 = pts[(k + 1) % pts.length];
    // Top/left edges get bright icy cyan or burnished white; bottom/right get deep cobalt
    let isLit = (q2[1] < cy || q1[0] < cx);
    if (isLit) {
      brush.set("fine_cp", "#bce8ff", 0.42);
      brush.line(q1[0], q1[1], q2[0], q2[1]);
      if (random() < 0.55 || brightBoost) {
        brush.set("burnish_white", "#ffffff", random(0.35, 0.65));
        brush.line(
          lerp(q1[0], q2[0], 0.15),
          lerp(q1[1], q2[1], 0.15),
          lerp(q1[0], q2[0], 0.85),
          lerp(q1[1], q2[1], 0.85)
        );
      }
    } else {
      brush.set("fine_cp", "#091b47", 0.45);
      brush.line(q1[0], q1[1], q2[0], q2[1]);
    }
  }

  // Internal fracture ridge in burnished white
  brush.set("burnish_white", "#e8f8ff", 0.38);
  brush.line(pA[0], pA[1], midX, midY);
  brush.set("fine_cp", "#3c8cd4", 0.32);
  brush.line(midX, midY, pB[0], pB[1]);
  brush.line(midX, midY, pC[0], pC[1]);
}

function drawCrushedIceBed() {
  generateIceShards();

  // Base icy indigo-turquoise under-glow of the ice pile
  brush.noStroke();
  brush.fill("#112e6e", 110);
  brush.fillBleed(0.3, "out");
  brush.beginShape(0.4);
  const bedOutline = [
    [515, 535], [665, 610], [715, 745], [665, 910],
    [515, 1035], [310, 1065], [155, 975], [110, 815],
    [135, 645], [255, 525], [385, 505]
  ];
  for (let p of bedOutline) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // Draw all background ice shards
  for (let shard of iceShards) {
    if (!shard.isForeground) {
      drawSingleIceShard(shard, false);
    }
  }
}

function drawForegroundIceAndSheen() {
  // Foreground ice shards resting against the lower shell & legs
  for (let shard of iceShards) {
    if (shard.isForeground) {
      drawSingleIceShard(shard, true);
    }
  }

  // Extra burnished white specular glints & meltwater meniscus arcs across the ice bed
  for (let i = 0; i < 95; i++) {
    let shard = random(iceShards);
    let gx = shard.cx + random(-shard.size * 0.45, shard.size * 0.45);
    let gy = shard.cy + random(-shard.size * 0.45, shard.size * 0.45);

    // Tiny burnished white diamond/facet glint
    brush.set("burnish_white", "#ffffff", random(0.45, 0.85));
    let gl = random(3, 9);
    let ga = random(-35, 25);
    brush.line(gx, gy, gx + cos(ga) * gl, gy + sin(ga) * gl);
    brush.line(gx + 1, gy - 1, gx + cos(ga + 75) * (gl * 0.6), gy + sin(ga + 75) * (gl * 0.6));
  }

  // Meltwater sheen puddles and wet meniscus rims around the perimeter
  for (let i = 0; i < 42; i++) {
    let shard = random(iceShards);
    if (shard.distFromCore < 140) continue;
    let mx = shard.cx + random(-18, 18);
    let my = shard.cy + shard.size * 0.75;
    let mw = random(10, 28);
    let mh = mw * random(0.28, 0.45);

    // Dark glassy water refraction
    brush.set("fine_cp", "#061130", 0.55);
    brush.arc(mx, my, mw * 0.5, 10, 170);

    // Bright white wet meniscus highlight
    brush.set("burnish_white", "#ffffff", 0.42);
    brush.arc(mx, my + 1.5, mw * 0.48, 25, 155);
  }
}

// ============================================================================
// 3. PRAWN CONTACT SHADOW ON ICE & CLOTH
// ============================================================================

function drawPrawnShadow() {
  brush.noStroke();
  brush.fill("#03071c", 160);
  brush.fillBleed(0.25, "out");
  brush.beginShape(0.35);

  for (let t = 0; t <= 1.0; t += 0.04) {
    let p = shellPoint(t, 1.06);
    brush.vertex(p[0] + 10, p[1] + 14);
  }
  for (let t = 1.0; t >= 0; t -= 0.04) {
    let p = shellPoint(t, -1.05);
    brush.vertex(p[0] + 8, p[1] + 12);
  }
  brush.endShape(true);
  brush.noFill();

  // Warm ambient coral-violet bounce shadow in the ice crevices next to the shell
  for (let t = 0.05; t <= 0.95; t += 0.03) {
    let pOut = shellPoint(t, 1.12);
    brush.set("cpencil", "#1b0b2e", 0.65);
    brush.line(pOut[0], pOut[1], pOut[0] + 12, pOut[1] + 15);
  }
}

// ============================================================================
// 4. FEATHERED SWIMMERETS (PLEOPODS) & WALKING LEGS (PEREIOPODS)
// ============================================================================

function drawSwimmerets() {
  // 5 pairs of biramous feathered swimmerets along the inner curve (Segments 1 to 5)
  const pleopodT = [0.35, 0.46, 0.57, 0.68, 0.78];

  for (let idx = 0; idx < pleopodT.length; idx++) {
    let t = pleopodT[idx];
    let base = shellPoint(t, -0.88);
    let sp = evalSpine(t);
    // Pointing inward toward the boteh cavity and slightly backward along the curl
    let inX = -sp.nx;
    let inY = -sp.ny;
    let dirX = inX * 0.78 + sp.tx * 0.45;
    let dirY = inY * 0.78 + sp.ty * 0.45;
    let baseAng = atan2(dirY, dirX);
    let scaleLen = map(idx, 0, 4, 62, 36);

    // Muscular basal protopodite (coral-pink joint stalk)
    let stalkEnd = [
      base[0] + cos(baseAng) * (scaleLen * 0.32),
      base[1] + sin(baseAng) * (scaleLen * 0.32)
    ];
    brush.set("cpencil", "#ff3b4e", 0.85);
    brush.line(base[0], base[1], stalkEnd[0], stalkEnd[1]);
    brush.set("fine_cp", "#ff9e8a", 0.5);
    brush.line(base[0] - 1.5, base[1] - 1.5, stalkEnd[0] - 1.5, stalkEnd[1] - 1.5);

    // Two biramous feathered blades (exopodite and endopodite)
    for (let branch = -1; branch <= 1; branch += 2) {
      let bAng = baseAng + branch * 14;
      let bLen = scaleLen * (branch === 1 ? 0.95 : 0.78);
      let mid = [
        stalkEnd[0] + cos(bAng + branch * 8) * (bLen * 0.52),
        stalkEnd[1] + sin(bAng + branch * 8) * (bLen * 0.52)
      ];
      let tip = [
        stalkEnd[0] + cos(bAng + branch * 22) * bLen,
        stalkEnd[1] + sin(bAng + branch * 22) * bLen
      ];

      // Feathered setae hairs fanning off both sides of the blade
      let steps = 16;
      for (let s = 1; s <= steps; s++) {
        let u = s / steps;
        let px = bezierPoint(stalkEnd[0], mid[0], mid[0], tip[0], u);
        let py = bezierPoint(stalkEnd[1], mid[1], mid[1], tip[1], u);
        let hLen = sin(u * 180) * 14 + 4;

        for (let side = -1; side <= 1; side += 2) {
          let hAng = bAng + branch * 18 + side * 38;
          let hx = px + cos(hAng) * hLen;
          let hy = py + sin(hAng) * hLen;
          let hCol = u > 0.6 ? "#a8e0ff" : (side > 0 ? "#ff6859" : "#ffb59e");
          brush.set("micro_cp", hCol, 0.28);
          brush.line(px, py, hx, hy);
        }
      }

      // Central rachis of the swimmeret blade
      brush.set("fine_cp", "#ff3348", 0.48);
      brush.spline([stalkEnd, mid, tip], 0.45);
      brush.set("micro_cp", "#ffe3d8", 0.26);
      brush.spline([
        [stalkEnd[0] + 1, stalkEnd[1] - 1],
        [mid[0] + 1, mid[1] - 1],
        [tip[0], tip[1]]
      ], 0.45);
    }
  }
}

function drawWalkingLegs() {
  // 5 segmented pereiopods + 2 long feathered maxillipeds emerging from under the head/thorax
  const legConfigs = [
    // Reaching inward into the paisley hollow with graceful jointed bends
    { t: 0.24, j1: [395, 795], j2: [350, 745], j3: [315, 715], tip: [298, 690], thick: 4.5, chela: false },
    { t: 0.20, j1: [412, 775], j2: [368, 720], j3: [338, 678], tip: [322, 650], thick: 4.8, chela: false },
    { t: 0.16, j1: [432, 755], j2: [392, 695], j3: [368, 648], tip: [362, 618], thick: 5.2, chela: true },
    { t: 0.12, j1: [454, 738], j2: [425, 678], j3: [415, 632], tip: [422, 602], thick: 5.5, chela: true },
    // Extending forward and outward over the head/ice
    { t: 0.08, j1: [482, 724], j2: [472, 665], j3: [485, 615], tip: [505, 582], thick: 5.6, chela: true },
    { t: 0.04, j1: [518, 712], j2: [535, 655], j3: [575, 612], tip: [612, 588], thick: 5.0, chela: false },
    { t: 0.02, j1: [548, 728], j2: [598, 698], j3: [648, 682], tip: [684, 678], thick: 4.2, chela: false }
  ];

  for (let leg of legConfigs) {
    let base = shellPoint(leg.t, -0.82);
    let joints = [base, leg.j1, leg.j2, leg.j3, leg.tip];

    // Draw each tubular segment of the leg
    for (let s = 0; s < joints.length - 1; s++) {
      let p1 = joints[s];
      let p2 = joints[s + 1];
      let w1 = leg.thick * map(s, 0, 3, 1.0, 0.42);
      let w2 = leg.thick * map(s + 1, 0, 4, 1.0, 0.25);

      let dx = p2[0] - p1[0];
      let dy = p2[1] - p1[1];
      let len = sqrt(dx * dx + dy * dy) || 1;
      let nx = -dy / len;
      let ny = dx / len;

      // Base translucent coral/blue-violet wash
      brush.noStroke();
      brush.wash(s % 2 === 0 ? "#d93248" : "#6c8ec2", 145);
      brush.beginShape(0.15);
      brush.vertex(p1[0] + nx * w1, p1[1] + ny * w1);
      brush.vertex(p2[0] + nx * w2, p2[1] + ny * w2);
      brush.vertex(p2[0] - nx * w2, p2[1] - ny * w2);
      brush.vertex(p1[0] - nx * w1, p1[1] - ny * w1);
      brush.endShape(true);
      brush.noWash();

      // Longitudinal coloured pencil shading across the tubular leg segment
      for (let f = -0.9; f <= 0.9; f += 0.35) {
        let col = f < -0.2 ? "#ff9e88" : (f < 0.35 ? "#ff3848" : "#1c1f4a");
        brush.set("fine_cp", col, 0.38);
        brush.line(
          p1[0] + nx * w1 * f, p1[1] + ny * w1 * f,
          p2[0] + nx * w2 * f, p2[1] + ny * w2 * f
        );
      }

      // Specular highlight along the lit edge
      brush.set("burnish_white", "#ffeae3", 0.32);
      brush.line(
        p1[0] - nx * w1 * 0.55, p1[1] - ny * w1 * 0.55,
        p2[0] - nx * w2 * 0.55, p2[1] - ny * w2 * 0.55
      );

      // Fine sensory setae bristles along the leg margin
      let bristles = 9;
      for (let b = 1; b < bristles; b++) {
        let u = b / bristles;
        let bx = lerp(p1[0], p2[0], u) + nx * lerp(w1, w2, u);
        let by = lerp(p1[1], p2[1], u) + ny * lerp(w1, w2, u);
        let bAng = atan2(dy, dx) + 55;
        let bLen = random(5, 12);
        brush.set("micro_cp", "#ff8b78", 0.25);
        brush.line(bx, by, bx + cos(bAng) * bLen, by + sin(bAng) * bLen);
      }

      // Vivid coral-orange joint ring (articulation)
      brush.set("fine_cp", "#ff2238", 0.58);
      brush.line(p2[0] - nx * w2 * 1.15, p2[1] - ny * w2 * 1.15, p2[0] + nx * w2 * 1.15, p2[1] + ny * w2 * 1.15);
      brush.set("burnish_white", "#ffd4c4", 0.35);
      brush.line(p2[0] - nx * w2 * 0.8, p2[1] - ny * w2 * 0.8, p2[0] + nx * w2 * 0.3, p2[1] + ny * w2 * 0.3);
    }

    // Tiny pincer (chela) on chelate pereiopods
    if (leg.chela) {
      let p3 = leg.j3;
      let tp = leg.tip;
      let ang = atan2(tp[1] - p3[1], tp[0] - p3[0]);
      brush.set("fine_cp", "#ff2a3c", 0.42);
      brush.line(tp[0], tp[1], tp[0] + cos(ang - 22) * 9, tp[1] + sin(ang - 22) * 9);
      brush.line(tp[0], tp[1], tp[0] + cos(ang + 18) * 9, tp[1] + sin(ang + 18) * 9);
    }
  }
}

// ============================================================================
// 5. TAIL FAN (TELSON & UROPODS - HOOKED TIP OF PAISLEY BOTEH)
// ============================================================================

function drawTailFan() {
  // 4 Uropod blades + 1 sharp central Telson curving into the paisley hook at (442, 650)
  const blades = [
    // Inner/ventral uropods
    { sStart: -0.75, sEnd: -0.15, tipOff: [-18, 12], lenT: 0.99, colBase: "#4d7da6", colTip: "#ff3845" },
    { sStart: -0.45, sEnd: 0.25,  tipOff: [-8, 16],  lenT: 1.00, colBase: "#5e94bf", colTip: "#ff4f38" },
    // Outer/dorsal uropods
    { sStart: -0.10, sEnd: 0.65,  tipOff: [6, 12],   lenT: 1.00, colBase: "#6da5cf", colTip: "#ff2e44" },
    { sStart: 0.25,  sEnd: 0.95,  tipOff: [14, 2],   lenT: 0.99, colBase: "#82b8e0", colTip: "#ff6238" },
    // Central sharp Telson forming the exact hooked apex
    { sStart: 0.05,  sEnd: 0.72,  tipOff: [2, 6],    lenT: 1.00, colBase: "#3d6b94", colTip: "#ff1e38", isTelson: true }
  ];

  for (let b of blades) {
    let poly = [];
    for (let t = 0.88; t <= b.lenT; t += 0.02) {
      let u = map(t, 0.88, b.lenT, 0, 1);
      let p = shellPoint(t, lerp(b.sEnd, 0.0, pow(u, 1.4)));
      poly.push([p[0] + b.tipOff[0] * u, p[1] + b.tipOff[1] * u]);
    }
    for (let t = b.lenT; t >= 0.88; t -= 0.02) {
      let u = map(t, 0.88, b.lenT, 0, 1);
      let p = shellPoint(t, lerp(b.sStart, 0.0, pow(u, 1.4)));
      poly.push([p[0] + b.tipOff[0] * u, p[1] + b.tipOff[1] * u]);
    }

    // Translucent base wash
    brush.noStroke();
    brush.wash(b.colBase, 155);
    brush.beginShape(0.25);
    for (let pt of poly) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
    brush.noWash();

    // Longitudinal rays & colour transition from blue-grey to fiery coral-red and dark indigo band
    let rays = 14;
    for (let r = 0; r <= rays; r++) {
      let frac = r / rays;
      let sVal = lerp(b.sStart, b.sEnd, frac);
      let rayPts = [];
      for (let t = 0.88; t <= b.lenT; t += 0.02) {
        let u = map(t, 0.88, b.lenT, 0, 1);
        let p = shellPoint(t, lerp(sVal, 0, pow(u, 1.35)));
        rayPts.push([p[0] + b.tipOff[0] * u, p[1] + b.tipOff[1] * u]);
      }

      // Basal blue-grey pencil
      brush.set("fine_cp", frac > 0.65 ? "#b8e4ff" : "#4b7da8", 0.36);
      brush.spline(rayPts.slice(0, 4), 0.3);

      // Sub-terminal dark navy-crimson band
      brush.set("fine_cp", "#160a26", 0.45);
      brush.spline(rayPts.slice(2, 6), 0.3);

      // Fiery coral-pink tip
      brush.set("fine_cp", b.colTip, 0.42);
      brush.spline(rayPts.slice(4), 0.3);
    }

    // Iridescent coral & electric-cyan marginal setae fringe along the fan rim
    for (let k = 0; k < poly.length; k += 1) {
      let pt = poly[k];
      brush.set("micro_cp", k % 2 === 0 ? "#ff5242" : "#7ce0ff", 0.28);
      brush.line(pt[0], pt[1], pt[0] + 5, pt[1] + 7);
    }

    // Burnished white ridge along the central telson and outer uropod edge
    if (b.isTelson) {
      let ridge = [];
      for (let t = 0.88; t <= 1.0; t += 0.02) {
        let u = map(t, 0.88, 1.0, 0, 1);
        let p = shellPoint(t, lerp(0.45, 0, u));
        ridge.push([p[0] + b.tipOff[0] * u, p[1] + b.tipOff[1] * u]);
      }
      brush.set("burnish_white", "#ffffff", 0.52);
      brush.spline(ridge, 0.35);
    }
  }
}

// ============================================================================
// 6. ABDOMINAL SEGMENTS (TRANSLUCENT SHELL, CORAL JOINTS, CHEVRONS & DOTS)
// ============================================================================

function drawOrnamentalBand(tCenter, tHalfWidth, sMin, sMax, numChevrons) {
  // Renders both the dark natural tiger-stripe shadow and the ornamental chevrons & pigment dots
  // 1. Soft dark tiger band foundation lines
  for (let s = sMin; s <= sMax; s += 0.04) {
    let wFactor = sin(map(s, sMin, sMax, 0, 180));
    let hw = tHalfWidth * (0.45 + 0.65 * wFactor);
    let p1 = shellPoint(tCenter - hw, s);
    let p2 = shellPoint(tCenter + hw, s);
    let col = s > 0.4 ? "#131c42" : (s < -0.35 ? "#6e1632" : "#090e26");
    brush.set("fine_cp", col, 0.48);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Minute repeated chevrons (< >) aligned along the segment contour
  for (let i = 0; i < numChevrons; i++) {
    let frac = (i + 0.5) / numChevrons;
    let sMid = lerp(sMin + 0.06, sMax - 0.06, frac);
    let ds = (sMax - sMin) / (numChevrons * 1.15);
    let wFactor = sin(frac * 180);
    let dt = tHalfWidth * (0.55 + 0.55 * wFactor);

    // Outer dark navy/crimson chevron
    let pTop = shellPoint(tCenter - dt * 0.7, sMid + ds);
    let pApex = shellPoint(tCenter + dt * 0.85, sMid);
    let pBot = shellPoint(tCenter - dt * 0.7, sMid - ds);

    brush.set("micro_cp", "#070b1e", 0.38);
    brush.line(pTop[0], pTop[1], pApex[0], pApex[1]);
    brush.line(pApex[0], pApex[1], pBot[0], pBot[1]);

    // Inner nested coral-vermilion & golden-ochre chevron
    let pTop2 = shellPoint(tCenter - dt * 0.95, sMid + ds * 0.75);
    let pApex2 = shellPoint(tCenter + dt * 0.35, sMid);
    let pBot2 = shellPoint(tCenter - dt * 0.95, sMid - ds * 0.75);

    brush.set("micro_cp", i % 2 === 0 ? "#ff3348" : "#ff8840", 0.34);
    brush.line(pTop2[0], pTop2[1], pApex2[0], pApex2[1]);
    brush.line(pApex2[0], pApex2[1], pBot2[0], pBot2[1]);

    // Flanking luminous ice-cyan / burnished white micro-chevrons on the band borders
    let pTop3 = shellPoint(tCenter + dt * 0.45, sMid + ds * 0.65);
    let pApex3 = shellPoint(tCenter + dt * 1.35, sMid);
    let pBot3 = shellPoint(tCenter + dt * 0.45, sMid - ds * 0.65);

    brush.set("micro_cp", sMid > 0.1 ? "#bef0ff" : "#ffb09c", 0.28);
    brush.line(pTop3[0], pTop3[1], pApex3[0], pApex3[1]);
    brush.line(pApex3[0], pApex3[1], pBot3[0], pBot3[1]);
  }

  // 3. Jewel-like chromatophore pigment dots flanking and filling the band
  let dotRows = numChevrons * 2;
  for (let r = 0; r <= dotRows; r++) {
    let s = lerp(sMin + 0.04, sMax - 0.04, r / dotRows);
    let wFactor = sin(map(s, sMin, sMax, 0, 180));
    let dt = tHalfWidth * (0.6 + 0.6 * wFactor);

    const offsets = [-dt * 1.45, -dt * 1.1, 0, dt * 1.1, dt * 1.45];
    const cols = ["#ff4a4a", "#f5faff", "#ff9d42", "#aee8ff", "#ff3b56"];

    for (let k = 0; k < offsets.length; k++) {
      let pt = shellPoint(tCenter + offsets[k], s);
      brush.set("micro_cp", cols[k], k === 1 || k === 3 ? 0.34 : 0.30);
      brush.circle(pt[0], pt[1], random(1.1, 2.1), 0.15);
    }
  }
}

function drawAbdominalSegments() {
  // Draw from Segment 6 (posterior) forward to Segment 1 (anterior) for proper overlapping
  const segments = [
    { id: 6, t0: 0.80, t1: 0.90, sMin: -0.92, sMax: 1.00, chev: 7 },
    { id: 5, t0: 0.70, t1: 0.81, sMin: -0.96, sMax: 1.02, chev: 9 },
    { id: 4, t0: 0.60, t1: 0.71, sMin: -1.00, sMax: 1.03, chev: 11 },
    { id: 3, t0: 0.49, t1: 0.61, sMin: -1.04, sMax: 1.08, chev: 13 }, // Dorsal hump segment
    { id: 2, t0: 0.38, t1: 0.51, sMin: -1.16, sMax: 1.03, chev: 15 }, // Broad overlapping pleuron
    { id: 1, t0: 0.28, t1: 0.40, sMin: -1.05, sMax: 1.02, chev: 14 }
  ];

  for (let seg of segments) {
    let { t0, t1, sMin, sMax, chev } = seg;
    let tMid = (t0 + t1) * 0.5;

    // Build segment polygon with rounded lateral pleuron scallop at sMin
    let segPoly = [];
    // Dorsal arch (s = sMax)
    for (let u = 0; u <= 1.0; u += 0.1) {
      let t = lerp(t0, t1, u);
      let hump = seg.id === 3 ? sin(u * 180) * 0.06 : 0;
      segPoly.push(shellPoint(t, sMax + hump));
    }
    // Posterior edge curving down to rounded pleuron lobe
    for (let v = 1.0; v >= 0.0; v -= 0.12) {
      let s = lerp(sMin, sMax, v);
      let curveT = t1 + sin(v * 180) * 0.012;
      segPoly.push(shellPoint(curveT, s));
    }
    // Ventral rounded pleuron scallop (paisley petal rim at sMin)
    for (let u = 1.0; u >= 0.0; u -= 0.1) {
      let t = lerp(t0, t1, u);
      let lobe = sin(u * 180) * 0.12;
      segPoly.push(shellPoint(t, sMin - lobe));
    }
    // Anterior edge rising back to dorsal
    for (let v = 0.0; v <= 1.0; v += 0.12) {
      let s = lerp(sMin, sMax, v);
      segPoly.push(shellPoint(t0, s));
    }

    // 1. Base translucent blue-grey shell wash
    brush.noStroke();
    brush.wash("#5384ab", 165);
    brush.beginShape(0.25);
    for (let p of segPoly) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    brush.noWash();

    // 2. Obsessive coloured-pencil cross-contour shading for 3D cylindrical volume
    for (let s = sMin; s <= sMax; s += 0.032) {
      let normS = map(s, sMin, sMax, -1, 1);
      let col;
      if (normS > 0.62) {
        // Upper dorsal wet sheen & sky-blue highlight zone
        col = normS > 0.82 ? "#7ab8e0" : "#c8eeff";
      } else if (normS > 0.05) {
        // Translucent grey-blue & electric cyan midtone
        col = random() < 0.5 ? "#5a90ba" : "#76b2db";
      } else if (normS > -0.55) {
        // Core slate-indigo shadow & subtle violet-pink translucency
        col = random() < 0.5 ? "#2c4c78" : "#4a5688";
      } else if (normS > -0.82) {
        // Subsurface coral-salmon glow near the pleuron base
        col = "#e85d68";
      } else {
        // Vivid coral-pink marginal pleuron rim
        col = "#ff3344";
      }

      let pStart = shellPoint(t0 + 0.004, s);
      let pMid = shellPoint(tMid, s - (normS < -0.5 ? 0.05 : 0));
      let pEnd = shellPoint(t1 - 0.004, s);
      brush.set("fine_cp", col, 0.42);
      brush.spline([pStart, pMid, pEnd], 0.35);
    }

    // 3. Vivid Coral-Pink Posterior Joint Membrane & Lateral Hinge Condyle
    for (let s = sMin * 0.85; s <= sMax * 0.96; s += 0.035) {
      let pA = shellPoint(t1 - 0.012, s);
      let pB = shellPoint(t1 + 0.008, s);
      let jCol = abs(s + 0.25) < 0.22 ? "#ff1e34" : "#ff5c45";
      brush.set("fine_cp", jCol, 0.52);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }

    // Lateral hinge spot (the bright coral-orange pivot dot on each segment side)
    let hingePt = shellPoint(t1 - 0.008, -0.28);
    brush.set("cpencil", "#ff2438", 0.75);
    brush.circle(hingePt[0], hingePt[1], 5.5, 0.2);
    brush.set("burnish_white", "#ffe3d6", 0.45);
    brush.circle(hingePt[0] - 1, hingePt[1] - 1, 2.4, 0.15);

    // 4. Tiger Stripe + Ornamental Chevrons & Dots inside the segment
    drawOrnamentalBand(tMid, (t1 - t0) * 0.22, sMin * 0.88, sMax * 0.96, chev);

    // Secondary delicate ornamental dot-arch near the anterior edge of the segment
    for (let s = sMin * 0.75; s <= sMax * 0.85; s += 0.09) {
      let dp = shellPoint(t0 + 0.018, s);
      brush.set("micro_cp", "#182b5c", 0.32);
      brush.circle(dp[0], dp[1], 1.8, 0.15);
      let dp2 = shellPoint(t0 + 0.024, s);
      brush.set("micro_cp", "#d9f4ff", 0.28);
      brush.circle(dp2[0], dp2[1], 1.2, 0.15);
    }

    // 5. Pleuron Scallop Rim (Coral-Pink & Burnished White Paisley Petal Edge)
    let pleuronEdge = [];
    let pleuronInner = [];
    for (let u = 0; u <= 1.0; u += 0.08) {
      let t = lerp(t0 + 0.005, t1 - 0.005, u);
      let lobe = sin(u * 180) * 0.12;
      pleuronEdge.push(shellPoint(t, sMin - lobe));
      pleuronInner.push(shellPoint(t, sMin - lobe + 0.09));
    }
    brush.set("fine_cp", "#ff2438", 0.58);
    brush.spline(pleuronEdge, 0.45);
    brush.set("burnish_white", "#ffffff", 0.42);
    brush.spline(pleuronInner, 0.45);

    // 6. Burnished White Dorsal Wet Specular Highlight (along s ~ 0.72)
    let specCurve1 = [];
    let specCurve2 = [];
    for (let u = 0.08; u <= 0.92; u += 0.12) {
      let t = lerp(t0, t1, u);
      specCurve1.push(shellPoint(t, 0.72));
      specCurve2.push(shellPoint(t, 0.66));
    }
    brush.set("burnish_white", "#ffffff", 0.65);
    brush.spline(specCurve1, 0.35);
    brush.set("burnish_white", "#d6f3ff", 0.45);
    brush.spline(specCurve2, 0.35);

    // Crisp outer dorsal contour line
    let dorsalEdge = [];
    for (let u = 0; u <= 1.0; u += 0.1) {
      let t = lerp(t0, t1, u);
      let hump = seg.id === 3 ? sin(u * 180) * 0.06 : 0;
      dorsalEdge.push(shellPoint(t, sMax + hump));
    }
    brush.set("fine_cp", "#a6dcff", 0.45);
    brush.spline(dorsalEdge, 0.35);
  }
}

// ============================================================================
// 7. CEPHALOTHORAX (CARAPACE, SERRATED ROSTRUM, ORNAMENTAL FILL & EYE)
// ============================================================================

function drawCarapaceAndHead() {
  let t0 = 0.00;
  let t1 = 0.30;

  // Build Carapace Polygon
  let caraPoly = [];
  for (let u = 0; u <= 1.0; u += 0.06) {
    let t = lerp(t0, t1, u);
    caraPoly.push(shellPoint(t, 1.02));
  }
  for (let v = 1.0; v >= -1.02; v -= 0.1) {
    let curveT = t1 + sin(map(v, -1.02, 1.0, 0, 180)) * 0.015;
    caraPoly.push(shellPoint(curveT, v));
  }
  for (let u = 1.0; u >= 0.0; u -= 0.06) {
    let t = lerp(t0, t1, u);
    let ventS = -1.02 - sin(u * 180) * 0.08;
    caraPoly.push(shellPoint(t, ventS));
  }
  for (let v = -1.02; v <= 1.02; v += 0.1) {
    caraPoly.push(shellPoint(t0, v));
  }

  // 1. Translucent grey-blue base wash
  brush.noStroke();
  brush.wash("#4a7ca6", 170);
  brush.beginShape(0.25);
  for (let p of caraPoly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // 2. Dense Coloured-Pencil Longitudinal & Cross Shading of Carapace
  for (let s = -1.04; s <= 1.02; s += 0.026) {
    let pts = [];
    for (let u = 0; u <= 1.0; u += 0.12) {
      let t = lerp(t0, t1, u);
      let sMod = s - (s < -0.5 ? sin(u * 180) * 0.06 : 0);
      pts.push(shellPoint(t, sMod));
    }

    let col;
    if (s > 0.65) {
      col = s > 0.85 ? "#6ca8d4" : "#c8eeff";
    } else if (s > 0.05) {
      col = random() < 0.5 ? "#5289b5" : "#74b0d9";
    } else if (s > -0.55) {
      col = random() < 0.5 ? "#26436e" : "#425685";
    } else if (s > -0.85) {
      col = "#e65060";
    } else {
      col = "#ff2b3e";
    }
    brush.set("fine_cp", col, 0.42);
    brush.spline(pts, 0.35);
  }

  // 3. Three Transverse Tiger Stripes + Ornamental Paisley Chevrons & Dots on Carapace
  drawOrnamentalBand(0.07, 0.024, -0.78, 0.96, 12);
  drawOrnamentalBand(0.16, 0.028, -0.88, 0.98, 15);
  drawOrnamentalBand(0.25, 0.026, -0.92, 0.98, 16);

  // Ornamental rosette / boteh medallion motif on the hepatic/branchial cheek of the carapace
  let cheekCenter = shellPoint(0.14, -0.22);
  for (let ring = 1; ring <= 3; ring++) {
    let rad = ring * 8.5;
    let dots = ring * 7;
    for (let d = 0; d < dots; d++) {
      let a = d * (360 / dots);
      let dx = cheekCenter[0] + cos(a) * rad * 1.15;
      let dy = cheekCenter[1] + sin(a) * rad * 0.85;
      let dCol = ring === 1 ? "#ff3848" : (ring === 2 ? "#d6f2ff" : "#0b1433");
      brush.set("micro_cp", dCol, 0.32);
      brush.circle(dx, dy, 1.6, 0.15);
    }
  }

  // Anatomical Cervical Groove & Hepatic Carina Ridge (highlighted in coral & burnished white)
  let groovePts = [
    shellPoint(0.19, 0.55),
    shellPoint(0.17, 0.12),
    shellPoint(0.12, -0.35),
    shellPoint(0.06, -0.68)
  ];
  brush.set("fine_cp", "#111c42", 0.52);
  brush.spline(groovePts, 0.4);
  let grooveLit = groovePts.map(p => [p[0] - 2.5, p[1] - 2]);
  brush.set("burnish_white", "#d8f3ff", 0.45);
  brush.spline(grooveLit, 0.4);

  // Posterior margin of carapace (coral-pink & white collar overlapping Segment 1)
  let postMargin = [];
  let postMarginLit = [];
  for (let s = -0.98; s <= 1.0; s += 0.08) {
    let curveT = t1 + sin(map(s, -0.98, 1.0, 0, 180)) * 0.015;
    postMargin.push(shellPoint(curveT, s));
    postMarginLit.push(shellPoint(curveT - 0.008, s));
  }
  brush.set("fine_cp", "#ff263a", 0.62);
  brush.spline(postMargin, 0.35);
  brush.set("burnish_white", "#ffffff", 0.42);
  brush.spline(postMarginLit, 0.35);

  // Burnished white specular highlight along upper carapace
  let caraSpec1 = [];
  let caraSpec2 = [];
  for (let u = 0.05; u <= 0.92; u += 0.1) {
    let t = lerp(t0, t1, u);
    caraSpec1.push(shellPoint(t, 0.72));
    caraSpec2.push(shellPoint(t, 0.65));
  }
  brush.set("burnish_white", "#ffffff", 0.72);
  brush.spline(caraSpec1, 0.35);
  brush.set("burnish_white", "#c8edff", 0.48);
  brush.spline(caraSpec2, 0.35);

  // 4. Serrated Rostrum (Curved Ornamental Crest jutting from anterior dorsal carapace)
  let rBaseDorsal = shellPoint(0.06, 0.98);
  let rFrontDorsal = shellPoint(0.0, 0.92);
  let rFrontVent = shellPoint(0.0, 0.42);
  let rMid = [608, 692];
  let rTip = [656, 628];

  let rostrumSpine = [rBaseDorsal, rFrontDorsal, rMid, rTip];

  // Rostrum blade shading
  for (let f = 0; f <= 1.0; f += 0.12) {
    let pStart = [
      lerp(rFrontVent[0], rFrontDorsal[0], f),
      lerp(rFrontVent[1], rFrontDorsal[1], f)
    ];
    let pMid = [
      lerp(600, 612, f),
      lerp(704, 686, f)
    ];
    let col = f > 0.6 ? "#ff2638" : (f > 0.25 ? "#ff7648" : "#89c4eb");
    brush.set("fine_cp", col, 0.42);
    brush.spline([pStart, pMid, rTip], 0.35);
  }

  // 7 Dorsal Serrated Rostral Teeth (vivid coral-red spines with burnished tips)
  for (let k = 0; k < 7; k++) {
    let u = k / 6.5;
    let bx = bezierPoint(rBaseDorsal[0], rFrontDorsal[0], rMid[0], rTip[0], u);
    let by = bezierPoint(rBaseDorsal[1], rFrontDorsal[1], rMid[1], rTip[1], u);
    let tx = bx + 11 * (1 - u * 0.45);
    let ty = by + 4 * (1 - u * 0.45);
    let nx = bx + 4;
    let ny = by - 8;

    brush.set("fine_cp", "#ff1e34", 0.52);
    brush.line(bx, by, tx, ty);
    brush.line(tx, ty, nx, ny);
    brush.set("burnish_white", "#ffe6dc", 0.35);
    brush.line(bx + 1, by, tx - 1, ty);
  }

  // Burnished white lateral carina on the rostrum
  brush.set("burnish_white", "#ffffff", 0.52);
  brush.spline([rFrontVent, [604, 698], rTip], 0.35);

  // 5. Stalked Compound Eye (Glossy Obsidian Sphere with Hexagonal Ommatidia & Wet Glint)
  let eyeStalkBase = shellPoint(0.01, 0.32);
  let eyeCenter = [558, 696];
  let eyeRad = 17.5;

  // Coral-pink eye stalk (ocular peduncle)
  brush.set("cpencil", "#ff4754", 0.85);
  brush.line(eyeStalkBase[0], eyeStalkBase[1], eyeCenter[0], eyeCenter[1]);
  brush.set("burnish_white", "#ffd4c8", 0.45);
  brush.line(eyeStalkBase[0] - 2, eyeStalkBase[1] - 2, eyeCenter[0] - 3, eyeCenter[1] - 2);

  // Dark obsidian-indigo sphere wash
  brush.noStroke();
  brush.wash("#050816", 235);
  brush.circle(eyeCenter[0], eyeCenter[1], eyeRad, 0.08);
  brush.noWash();

  // Warm bronze-amber & royal-blue peripheral iris glow (internal compound eye reflection)
  for (let a = 110; a <= 310; a += 14) {
    let r1 = eyeRad * 0.55;
    let r2 = eyeRad * 0.92;
    let col = a < 210 ? "#e06a2b" : "#2e6fd9";
    brush.set("fine_cp", col, 0.42);
    brush.line(
      eyeCenter[0] + cos(a) * r1, eyeCenter[1] + sin(a) * r1,
      eyeCenter[0] + cos(a) * r2, eyeCenter[1] + sin(a) * r2
    );
  }

  // Micro-ommatidia facet stippling
  for (let i = 0; i < 45; i++) {
    let a = random(360);
    let r = random(2, eyeRad * 0.85);
    let ox = eyeCenter[0] + cos(a) * r;
    let oy = eyeCenter[1] + sin(a) * r;
    brush.set("micro_cp", r > eyeRad * 0.55 ? "#ff944d" : "#182c66", 0.28);
    brush.circle(ox, oy, 1.1, 0.1);
  }

  // Crisp dark rim & bright curved wet specular highlight on the eye
  brush.set("fine_cp", "#02040d", 0.55);
  brush.circle(eyeCenter[0], eyeCenter[1], eyeRad, 0.08);

  brush.set("burnish_white", "#ffffff", 0.78);
  brush.arc(eyeCenter[0] - 1, eyeCenter[1] - 1, eyeRad * 0.68, 200, 315);
  brush.set("burnish_white", "#ffffff", 0.92);
  brush.circle(eyeCenter[0] - 5, eyeCenter[1] - 6, 3.2, 0.1);
  brush.set("burnish_white", "#a8e4ff", 0.45);
  brush.arc(eyeCenter[0], eyeCenter[1], eyeRad * 0.82, 25, 115);
}

// ============================================================================
// 8. SWEEPING HAIRLINE ANTENNAE (PAISLEY TENDRILS ACROSS EMPTY CLOTH)
// ============================================================================

function evalPolyline(pts, u) {
  u = constrain(u, 0, 1);
  let n = pts.length - 1;
  let s = u * n;
  let i = min(floor(s), n - 1);
  let f = s - i;

  let i0 = max(0, i - 1);
  let i1 = i;
  let i2 = min(n, i + 1);
  let i3 = min(n, i + 2);

  let x = catmullRom(pts[i0][0], pts[i1][0], pts[i2][0], pts[i3][0], f);
  let y = catmullRom(pts[i0][1], pts[i1][1], pts[i2][1], pts[i3][1], f);
  return [x, y];
}

function drawTendrilCurve(pts, baseWeight, isPrimary) {
  // Subtle dark shadow on cloth near the basal third
  let shadowPts = pts.slice(0, 5).map(p => [p[0] + 6, p[1] + 9]);
  brush.set("fine_cp", "#020410", baseWeight * 0.85);
  brush.spline(shadowPts, 0.45);

  // Build pressure-tapered spline points: [x, y, pressure]
  let n = pts.length;
  let mainSpline = [];
  let highlightSpline = [];

  for (let i = 0; i < n; i++) {
    let u = i / (n - 1);
    let press = lerp(1.15, 0.18, pow(u, 0.65));
    mainSpline.push([pts[i][0], pts[i][1], press]);
    highlightSpline.push([pts[i][0] - 1.2 * (1 - u * 0.7), pts[i][1] - 1.2 * (1 - u * 0.7), press * 0.75]);
  }

  // 1. Vivid coral-vermilion core stroke
  brush.set("fine_cp", "#ff2e40", baseWeight);
  brush.spline(mainSpline, 0.45);

  // 2. Warm tangerine-coral secondary pass for luminous saturation against the indigo cloth
  brush.set("micro_cp", "#ff7847", baseWeight * 0.72);
  brush.spline(mainSpline, 0.45);

  // 3. Fine burnished highlight along the upper edge of the antenna
  brush.set("micro_cp", "#ffd8c4", baseWeight * 0.52);
  brush.spline(highlightSpline, 0.45);

  // 4. Natural crustacean flagellar annulations / ornamental paisley beading along the curve
  let steps = isPrimary ? 95 : 48;
  for (let s = 1; s < steps; s++) {
    let u = s / steps;
    let p = evalPolyline(pts, u);
    // Tiny dark crimson/amber annulation ring mark
    if (s % 2 === 0) {
      brush.set("micro_cp", "#7a1128", 0.26);
      brush.line(p[0] - 1, p[1] - 1, p[0] + 1, p[1] + 1);
    } else if (u < 0.75 && s % 5 === 0) {
      // Minute specular bead glint
      brush.set("burnish_white", "#fff0e8", 0.28);
      brush.circle(p[0] - 0.8, p[1] - 0.8, 0.9, 0.1);
    }
  }
}

