// =============================================================================
// CLIPPING & GEOMETRY HELPERS
// =============================================================================

function setPaneClip(pane) {
  activePane = pane;
  brush.clip([pane.x1, pane.y1, pane.x2, pane.y2]);
}

function clearPaneClip() {
  activePane = null;
  brush.noClip();
}

function makeTransform(cx, cy, scaleFactor, angleDeg) {
  const rad = angleDeg * (Math.PI / 180);
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  return {
    pt(u, v) {
      const su = u * scaleFactor;
      const sv = v * scaleFactor;
      return [cx + su * c - sv * s, cy + su * s + sv * c];
    },
    pts(arr) {
      return arr.map(p => {
        const su = p[0] * scaleFactor;
        const sv = p[1] * scaleFactor;
        const out = [cx + su * c - sv * s, cy + su * s + sv * c];
        if (p.length > 2) out.push(p[2]);
        return out;
      });
    },
    angle(localDeg) {
      return angleDeg + localDeg;
    },
    s: scaleFactor
  };
}

// Sutherland-Hodgman polygon clipper to keep all polygon washes/hatches strictly inside activePane
function clipPolygonToRect(pts, rect) {
  if (!pts || pts.length < 3) return [];
  if (!rect) return pts;

  const xmin = rect.x1 - 1;
  const ymin = rect.y1 - 1;
  const xmax = rect.x2 + 1;
  const ymax = rect.y2 + 1;

  function clipEdge(poly, insideFn, intersectFn) {
    const out = [];
    if (poly.length === 0) return out;
    let S = poly[poly.length - 1];
    for (let i = 0; i < poly.length; i++) {
      const E = poly[i];
      const Ein = insideFn(E);
      const Sin = insideFn(S);
      if (Ein) {
        if (!Sin) out.push(intersectFn(S, E));
        out.push(E);
      } else if (Sin) {
        out.push(intersectFn(S, E));
      }
      S = E;
    }
    return out;
  }

  let res = pts.map(p => [p[0], p[1]]);
  res = clipEdge(res, p => p[0] >= xmin, (a, b) => [xmin, a[1] + (b[1] - a[1]) * (xmin - a[0]) / (b[0] - a[0] || 1e-6)]);
  res = clipEdge(res, p => p[0] <= xmax, (a, b) => [xmax, a[1] + (b[1] - a[1]) * (xmax - a[0]) / (b[0] - a[0] || 1e-6)]);
  res = clipEdge(res, p => p[1] >= ymin, (a, b) => [a[0] + (b[0] - a[0]) * (ymin - a[1]) / (b[1] - a[1] || 1e-6), ymin]);
  res = clipEdge(res, p => p[1] <= ymax, (a, b) => [a[0] + (b[0] - a[0]) * (ymax - a[1]) / (b[1] - a[1] || 1e-6), ymax]);

  // Filter near-duplicate consecutive vertices
  const clean = [];
  for (let i = 0; i < res.length; i++) {
    const prev = clean[clean.length - 1];
    if (!prev || Math.hypot(res[i][0] - prev[0], res[i][1] - prev[1]) > 0.5) {
      clean.push(res[i]);
    }
  }
  if (clean.length >= 3) {
    const first = clean[0];
    const last = clean[clean.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) < 0.5) clean.pop();
  }
  return clean.length >= 3 ? clean : [];
}

function drawPolyLayer(rawPts, opts = {}) {
  const pts = clipPolygonToRect(rawPts, activePane);
  if (pts.length < 3) return;

  // Verify non-zero area
  let area2 = 0;
  for (let i = 0; i < pts.length; i++) {
    const j = (i + 1) % pts.length;
    area2 += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1];
  }
  if (Math.abs(area2) < 4) return;

  const poly = new brush.Polygon(pts);
  if (opts.washCol) {
    poly.wash(opts.washCol, opts.washOp ?? 200);
  }
  if (opts.fillCol) {
    poly.fill(opts.fillCol, opts.fillOp ?? 120, opts.bleed ?? 0.02, opts.tex ?? 0.25);
  }
  if (opts.hatchBrush && opts.hatchCol) {
    brush.hatchStyle(opts.hatchBrush, opts.hatchCol, opts.hatchWeight ?? 0.8);
    poly.hatch(opts.hatchDist ?? 3, opts.hatchAngle ?? 45, opts.hatchOpts ?? { rand: 0.03 });
    brush.noHatch();
  }
  if (opts.strokeBrush && opts.strokeCol) {
    poly.draw(opts.strokeBrush, opts.strokeCol, opts.strokeWeight ?? 0.7);
  }
}

function strokeLine(bName, col, weight, p1, p2) {
  if (!p1 || !p2) return;
  if (Math.hypot(p2[0] - p1[0], p2[1] - p1[1]) < 0.5) return;
  brush.set(bName, col, weight);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
}

function strokeSpline(bName, col, weight, pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

