function drawBareSkyPane(pane, isEmptySky) {
  setPaneClip(pane);
  const w = pane.x2 - pane.x1;
  const h = pane.y2 - pane.y1;

  // Crisp luminous white paper sky base
  const rectPts = [
    [pane.x1, pane.y1],
    [pane.x2, pane.y1],
    [pane.x2, pane.y2],
    [pane.x1, pane.y2]
  ];
  drawPolyLayer(rectPts, {
    washCol: isEmptySky ? "#FDFCF9" : "#F8FAFD",
    washOp: 220
  });

  // Whisper-light atmospheric pencil grain near top of pane for tactile depth
  const topBandH = Math.min(h * 0.45, 130);
  const topBand = [
    [pane.x1, pane.y1],
    [pane.x2, pane.y1],
    [pane.x2, pane.y1 + topBandH],
    [pane.x1, pane.y1 + topBandH]
  ];
  drawPolyLayer(topBand, {
    hatchBrush: "2H",
    hatchCol: isEmptySky ? "#EBF0F6" : "#E3EAF3",
    hatchWeight: 0.45,
    hatchDist: 6.5,
    hatchAngle: 12,
    hatchOpts: { rand: 0.08, gradient: 0.75 }
  });

  // Subtle diagonal cross-grain on bare white sky panes to give hot-press paper tactility
  if (isEmptySky) {
    const step = 18;
    for (let y = pane.y1 + 10; y < pane.y2 - 6; y += step) {
      strokeLine("2H", "#F2F4F7", 0.35, [pane.x1 + 6, y], [pane.x2 - 6, y + 4]);
    }
  }
  clearPaneClip();
}

// =============================================================================
// WASHING LINE & PINCHED WHITE COTTON SHEET
// =============================================================================

function drawWashingLineSegment(cx, cy, scaleFactor, angleDeg, halfSpanUnits) {
  const T = makeTransform(cx, cy, scaleFactor, angleDeg);
  const u1 = -halfSpanUnits;
  const u2 = halfSpanUnits;
  const rCord = 3.8; // cord radius in peg units

  // Build slight catenary curve along the washing line
  const steps = 16;
  const topEdge = [];
  const midLine = [];
  const botEdge = [];
  const shadowBot = [];

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const u = u1 + (u2 - u1) * t;
    // Slight dip away from the peg clamp at u = 0
    const sag = 0.0006 * u * u;
    topEdge.push(T.pt(u, -rCord + sag));
    midLine.push(T.pt(u, sag));
    botEdge.push(T.pt(u, rCord + sag));
    shadowBot.push(T.pt(u, rCord + 3.4 + sag));
  }

  // Dark cast shadow under the cord onto the cotton
  const shadowPoly = [...botEdge, ...shadowBot.slice().reverse()];
  drawPolyLayer(shadowPoly, {
    washCol: COTTON.castShadow,
    washOp: 185,
    hatchBrush: "cpencil",
    hatchCol: COTTON.castAbyss,
    hatchWeight: 0.55,
    hatchDist: 2.2,
    hatchAngle: T.angle(5)
  });

  // Cord body polygon
  const cordPoly = [...topEdge, ...botEdge.slice().reverse()];
  drawPolyLayer(cordPoly, {
    washCol: "#D6DEE8",
    washOp: 230,
    hatchBrush: "cpencil",
    hatchCol: "#8E9CAD",
    hatchWeight: 0.5,
    hatchDist: 2.4,
    hatchAngle: T.angle(28)
  });

  // Helical braided core twist lines inside PVC clothesline
  for (let u = u1 + 4; u < u2 - 4; u += 5.5) {
    const sag = 0.0006 * u * u;
    strokeLine("2H", "#647285", 0.55, T.pt(u - 2.2, -rCord * 0.75 + sag), T.pt(u + 2.2, rCord * 0.8 + sag));
    strokeLine("cpencil", "#FFFFFF", 0.5, T.pt(u - 1.0, -rCord * 0.85 + sag), T.pt(u + 2.6, rCord * 0.2 + sag));
  }

  // Crisp top sunlit specular rim and dark bottom contour of cord
  strokeSpline("cpencil", "#FFFFFF", 0.95, topEdge, 0.4);
  strokeSpline("2B", "#3B4657", 0.65, botEdge, 0.4);
}

function drawPinchedCottonSheet(cfg) {
  const { cx, cy, scale: S, angle, palette, sheetWidth, sheetDepth } = cfg;
  const T = makeTransform(cx, cy, S, angle);
  const W = sheetWidth || 220;
  const D = sheetDepth || 220;

  // 1. Main sunlit white cotton sheet body hanging from the washing line (v = -3 to +D)
  const mainSheet = T.pts([
    [-W, -2.5], [W, -2.5], [W, D], [-W, D]
  ]);
  drawPolyLayer(mainSheet, {
    washCol: COTTON.warmLight,
    washOp: 245,
    hatchBrush: "2H",
    hatchCol: "#E8EDF5",
    hatchWeight: 0.45,
    hatchDist: 4.5,
    hatchAngle: T.angle(2)
  });

  // 2. Sculptural radial pinched pleats fanning downward from the peg jaws (u = -18..18, v = 0..D)
  const pleats = [
    // Far-left soft fold valley
    {
      pts: [[-W, 4], [-22, 2], [-58, D], [-W, D]],
      wash: "#EDF1F7", op: 190, hCol: COTTON.foldMid, hDist: 3.4, hAng: 78
    },
    // Left primary tension pleat shadow (pinched directly by left jaw)
    {
      pts: [[-22, 0], [-7, 0], [-19, D], [-58, D]],
      wash: COTTON.coolHalftone, op: 220, hCol: COTTON.foldDeep, hDist: 2.4, hAng: 102
    },
    // Left deep core crease
    {
      pts: [[-14, 2], [-7, 2], [-12, D * 0.85], [-26, D * 0.85]],
      wash: COTTON.foldMid, op: 210, hCol: COTTON.foldCore, hDist: 1.9, hAng: 98
    },
    // Central brightly lit pinched crest (rises up into the peg's line hole!)
    {
      pts: [[-7, -14], [7, -14], [16, D], [-18, D]],
      wash: COTTON.pureWhite, op: 250, hCol: "#FFFFFF", hDist: 2.5, hAng: 90
    },
    // Right side of central pleat (steep shadow drop)
    {
      pts: [[2, -8], [11, 0], [34, D], [8, D]],
      wash: COTTON.foldMid, op: 225, hCol: COTTON.foldCore, hDist: 2.0, hAng: 82
    },
    // Right secondary tension pleat (lit flank + valley)
    {
      pts: [[11, 0], [24, 2], [68, D], [34, D]],
      wash: COTTON.pureWhite, op: 235, hCol: COTTON.coolHalftone, hDist: 3.0, hAng: 75
    },
    // Far-right deep fold shadow
    {
      pts: [[24, 2], [52, 4], [115, D], [68, D]],
      wash: COTTON.coolHalftone, op: 215, hCol: COTTON.foldDeep, hDist: 2.6, hAng: 68
    }
  ];

  for (const p of pleats) {
    drawPolyLayer(T.pts(p.pts), {
      washCol: p.wash,
      washOp: p.op,
      hatchBrush: "cpencil",
      hatchCol: p.hCol,
      hatchWeight: 0.62,
      hatchDist: p.hDist,
      hatchAngle: T.angle(p.hAng),
      hatchOpts: { rand: 0.04 }
    });
  }

  // 3. Colored bounce-light reflection from the peg glowing in the upper pinched cotton hollows!
  const bounceLeft = T.pts([
    [-24, 2], [-4, 4], [-14, 52], [-38, 44]
  ]);
  const bounceRight = T.pts([
    [3, 4], [25, 2], [40, 46], [12, 54]
  ]);
  drawPolyLayer(bounceLeft, {
    washCol: palette.bounce,
    washOp: 135,
    hatchBrush: "cpencil",
    hatchCol: palette.bounceDeep,
    hatchWeight: 0.6,
    hatchDist: 2.4,
    hatchAngle: T.angle(110)
  });
  drawPolyLayer(bounceRight, {
    washCol: palette.bounce,
    washOp: 150,
    hatchBrush: "cpencil",
    hatchCol: palette.bounceDeep,
    hatchWeight: 0.6,
    hatchDist: 2.4,
    hatchAngle: T.angle(72)
  });

  // 4. Sharp angular cast shadow thrown by the peg jaws onto the pinched cotton
  const castShadowPoly = T.pts([
    [-23, 0], [25, 0], [34, 34], [12, 42], [2, 22], [-9, 36], [-28, 24]
  ]);
  drawPolyLayer(castShadowPoly, {
    washCol: COTTON.castShadow,
    washOp: 205,
    hatchBrush: "cpencil",
    hatchCol: COTTON.castAbyss,
    hatchWeight: 0.7,
    hatchDist: 1.8,
    hatchAngle: T.angle(35)
  });

  // 5. Fine coloured-pencil contour & cotton weave lines + stitched hem line
  // Stitched seam 14 units below the washing line, warping across the pinched pleats
  const hemY = 15;
  for (let u = -W + 6; u < W - 6; u += 4.2) {
    const pinchPull = -5.5 * Math.exp(-(u * u) / 380);
    const wave = 1.8 * Math.sin(u * 0.14);
    const v1 = hemY + pinchPull + wave;
    const v2 = hemY + pinchPull + 1.8 * Math.sin((u + 2.4) * 0.14);
    strokeLine("2H", "#7D8CA3", 0.55, T.pt(u, v1), T.pt(u + 2.3, v2));
    strokeLine("cpencil", "#FFFFFF", 0.45, T.pt(u, v1 - 0.8), T.pt(u + 2.3, v2 - 0.8));
  }

  // Radial tension crease lines in coloured pencil
  const creases = [
    { u0: -15, v0: 4, u1: -28, v1: 45, u2: -46, v2: D * 0.9, col: COTTON.foldCore, w: 0.75 },
    { u0: -8,  v0: 2, u1: -12, v1: 42, u2: -17, v2: D * 0.95, col: COTTON.castShadow, w: 0.85 },
    { u0: -2,  v0: -8, u1: -1, v1: 38, u2: -3,  v2: D * 0.95, col: "#FFFFFF", w: 1.1 },
    { u0: 3,   v0: -6, u1: 7,  v1: 36, u2: 12,  v2: D * 0.95, col: COTTON.castShadow, w: 0.9 },
    { u0: 11,  v0: 2, u1: 21,  v1: 44, u2: 34,  v2: D * 0.95, col: COTTON.foldCore, w: 0.8 },
    { u0: 16,  v0: 4, u1: 36,  v1: 46, u2: 58,  v2: D * 0.9, col: "#FFFFFF", w: 0.95 },
    { u0: 22,  v0: 5, u1: 45,  v1: 48, u2: 74,  v2: D * 0.85, col: COTTON.foldDeep, w: 0.7 }
  ];
  for (const cr of creases) {
    strokeSpline("cpencil", cr.col, cr.w, T.pts([
      [cr.u0, cr.v0], [cr.u1, cr.v1], [cr.u2, cr.v2]
    ]), 0.5);
  }
}

// =============================================================================
// HYPERREAL PLASTIC CLOTHES PEG (FRONT / 3/4 VIEW)
// =============================================================================

// Outer & inner profile curves of a single peg lever in peg local coordinates
// v runs from -108 (top handle tip) to +86 (bottom jaw tip), fulcrum is at v = 0
function pegOuterU(v) {
  if (v < -104) {
    // Rounded top tip
    const t = (v + 108) / 4;
    return 18 + 11.5 * Math.sqrt(Math.max(0, 1 - (1 - t) * (1 - t)));
  }
  if (v < -56) {
    // Upper finger-grip region with 5 moulded ergonomic grip ridges
    const base = 29.5 - ((v + 104) / 48) * 2.2;
    const ridge = 1.45 * Math.sin(((v + 102) / 44) * Math.PI * 5 * 2);
    return base + ridge;
  }
  if (v < -35) {
    return 27.2 - ((v + 56) / 21) * 1.0;
  }
  if (v < -25) {
    // Semicircular notch where the rusted steel spring arm hooks around the outside!
    const nv = (v + 30) / 5;
    return 26.2 - 2.8 * Math.max(0, 1 - nv * nv);
  }
  if (v < 15) {
    // Fulcrum waist
    return 26.0 - ((v + 25) / 40) * 1.2;
  }
  if (v < 82) {
    // Lower jaw taper
    return 24.8 - ((v - 15) / 67) * 6.4;
  }
  // Rounded bottom jaw tip
  const bt = (86 - v) / 4;
  return 11 + 7.4 * Math.sqrt(Math.max(0, bt));
}

function pegInnerU(v) {
  if (v < -14) {
    // Iconic V-shaped diverging inner handle gap above the fulcrum
    const t = (-14 - v) / 94;
    return 1.6 + 13.5 * Math.pow(t, 1.08);
  }
  if (v < 14) {
    // Fulcrum contact boss (with semi-circular spring seat cutout right at v = -6..+6)
    if (Math.abs(v) < 6.5) {
      return 1.2 + Math.sqrt(Math.max(0, 6.5 * 6.5 - v * v)) * 0.85;
    }
    return 1.2;
  }
  if (v < 44) {
    // Oval pipe-hole opening for the washing line
    const nv = (v - 29) / 15;
    return 1.4 + 10.6 * Math.sqrt(Math.max(0, 1 - nv * nv));
  }
  if (v < 78) {
    // 4 interlocking saw-tooth grip teeth clamping the cotton fold
    const phase = ((v - 44) / 34) * 4;
    const tooth = Math.abs((phase % 1) - 0.5) * 2; // 0 to 1 triangle wave
    return 1.3 + tooth * 3.4;
  }
  // Bottom jaw entry flare
  return 1.8 + ((v - 78) / 8) * 5.8;
}

function drawHyperrealPegFront(cfg) {
  const { cx, cy, scale: S, angle, palette, sideDir = -1 } = cfg;
  const T = makeTransform(cx, cy, S, angle);
  const dSide = 7.8 * sideDir; // 3D side-wall extrusion offset

  // Cast shadow of the entire peg onto the cotton below (v > 20)
  const pegCastPts = T.pts([
    [-26, 22], [28, 22], [35, 93], [-22, 95]
  ]);
  drawPolyLayer(pegCastPts, {
    washCol: COTTON.castAbyss,
    washOp: 165
  });

  // Draw the two symmetrical levers (draw the one further from the 3D side-view first)
  const leverOrder = sideDir < 0 ? [1, -1] : [-1, 1];

  for (const s of leverOrder) {
    // Sample v along the lever from -108 to +86
    const vSteps = [];
    for (let v = -108; v <= 86; v += 2) vSteps.push(v);

    const outerFront = vSteps.map(v => [s * pegOuterU(v), v]);
    const innerFront = vSteps.slice().reverse().map(v => [s * pegInnerU(v), v]);
    const frontPoly = [...outerFront, ...innerFront];

    // 1. 3D Side Wall (visible on the outer side when s == sideDir, and inner gap when s != sideDir)
    if (s === sideDir) {
      const outerBack = vSteps.slice().reverse().map(v => [s * pegOuterU(v) + dSide, v + 1.2]);
      const sideWallPoly = [...outerFront, ...outerBack];
      drawPolyLayer(T.pts(sideWallPoly), {
        washCol: palette.dark,
        washOp: 245,
        hatchBrush: "cpencil",
        hatchCol: palette.abyss,
        hatchWeight: 0.65,
        hatchDist: 2.0,
        hatchAngle: T.angle(18)
      });

      // Mould-parting flash seam running down the middle of the outer 3D side wall!
      const seamLineDark = vSteps.map(v => T.pt(s * pegOuterU(v) + dSide * 0.48, v + 0.6));
      const seamLineLight = vSteps.map(v => T.pt(s * pegOuterU(v) + dSide * 0.40, v + 0.5));
      strokeSpline("rotring", palette.abyss, 0.65, seamLineDark, 0.3);
      strokeSpline("cpencil", palette.seamLight, 0.55, seamLineLight, 0.3);
    } else {
      // Inner V-gap 3D wall & jaw hole wall visible on the opposite lever
      const innerVSteps = [];
      for (let v = -108; v <= 84; v += 2.5) innerVSteps.push(v);
      const inFront = innerVSteps.map(v => [s * pegInnerU(v), v]);
      const inBack = innerVSteps.slice().reverse().map(v => [s * pegInnerU(v) + dSide * 0.72, v + 1.0]);
      drawPolyLayer(T.pts([...inFront, ...inBack]), {
        washCol: palette.abyss,
        washOp: 240,
        hatchBrush: "cpencil",
        hatchCol: palette.dark,
        hatchWeight: 0.6,
        hatchDist: 2.0,
        hatchAngle: T.angle(15)
      });

      // Inner mould-parting seam line along the inside wall
      const inSeam = innerVSteps.map(v => T.pt(s * pegInnerU(v) + dSide * 0.36, v + 0.5));
      strokeSpline("cpencil", palette.seamLight, 0.48, inSeam, 0.3);
    }

    // 2. Main Front Face of the Lever (vibrant pure Mondrian plastic color + coloured-pencil grain)
    drawPolyLayer(T.pts(frontPoly), {
      washCol: palette.pure,
      washOp: 245,
      hatchBrush: "cpencil",
      hatchCol: palette.midDark,
      hatchWeight: 0.62,
      hatchDist: 2.3,
      hatchAngle: T.angle(s * 24),
      hatchOpts: { rand: 0.03 }
    });

    // Second cross-hatch pass in pure/glow coloured pencil for dense waxy pigment
    drawPolyLayer(T.pts(frontPoly), {
      hatchBrush: "cpencil",
      hatchCol: palette.glow,
      hatchWeight: 0.55,
      hatchDist: 3.1,
      hatchAngle: T.angle(90 + s * 6),
      hatchOpts: { rand: 0.02 }
    });

    // 3. Upper Recessed Moulded Trough (v = -98 to -16)
    const uTroughSteps = [];
    for (let v = -96; v <= -16; v += 3) uTroughSteps.push(v);
    const uTroughOut = uTroughSteps.map(v => [s * (pegOuterU(v) - 4.4), v]);
    const uTroughIn = uTroughSteps.slice().reverse().map(v => [s * (pegInnerU(v) + 4.2), v]);
    const uTroughPoly = [...uTroughOut, ...uTroughIn];

    // Subsurface scattering glow inside the thin plastic trough floor
    drawPolyLayer(T.pts(uTroughPoly), {
      washCol: palette.glow,
      washOp: 225,
      hatchBrush: "cpencil",
      hatchCol: palette.glowBright,
      hatchWeight: 0.6,
      hatchDist: 2.2,
      hatchAngle: T.angle(-25)
    });

    // Deep recessed rim shadow along one side of the upper trough
    const uShadowStrip = [
      ...uTroughSteps.map(v => [s * (pegInnerU(v) + 4.2), v]),
      ...uTroughSteps.slice().reverse().map(v => [s * (pegInnerU(v) + 7.2), v + 1.2])
    ];
    drawPolyLayer(T.pts(uShadowStrip), {
      washCol: palette.dark,
      washOp: 235,
      hatchBrush: "cpencil",
      hatchCol: palette.abyss,
      hatchWeight: 0.6,
      hatchDist: 1.8,
      hatchAngle: T.angle(85)
    });

    // Bright bevel catch-light along opposite wall of upper trough
    const uLightEdge = uTroughSteps.map(v => T.pt(s * (pegOuterU(v) - 4.4), v));
    strokeSpline("cpencil", palette.bevelLight, 0.85, uLightEdge, 0.35);

    // Moulded horizontal stiffening ribs inside upper trough (at v = -74 and v = -46)
    for (const rv of [-74, -46]) {
      const uA = s * (pegInnerU(rv) + 4.4);
      const uB = s * (pegOuterU(rv) - 4.5);
      const ribPoly = T.pts([
        [uA, rv - 2.2], [uB, rv - 2.2], [uB, rv + 2.2], [uA, rv + 2.2]
      ]);
      drawPolyLayer(ribPoly, {
        washCol: palette.pure,
        washOp: 240
      });
      strokeLine("cpencil", palette.bevelLight, 0.85, T.pt(uA, rv - 1.8), T.pt(uB, rv - 1.8));
      strokeLine("rotring", palette.abyss, 0.65, T.pt(uA, rv + 2.2), T.pt(uB, rv + 2.2));
    }

    // Circular injection-mould ejector pin ring at v = -60
    drawEjectorPinMark(T, s * 0.5 * (pegInnerU(-60) + pegOuterU(-60)), -60, 3.3, palette);

    // 4. Lower Recessed Moulded Trough (v = +18 to +76)
    const lTroughSteps = [];
    for (let v = 18; v <= 75; v += 3) lTroughSteps.push(v);
    const lTroughOut = lTroughSteps.map(v => [s * (pegOuterU(v) - 4.2), v]);
    const lTroughIn = lTroughSteps.slice().reverse().map(v => [s * (Math.max(pegInnerU(v) + 3.6, 7.2)), v]);
    const lTroughPoly = [...lTroughOut, ...lTroughIn];

    drawPolyLayer(T.pts(lTroughPoly), {
      washCol: palette.glow,
      washOp: 215,
      hatchBrush: "cpencil",
      hatchCol: palette.glowBright,
      hatchWeight: 0.58,
      hatchDist: 2.2,
      hatchAngle: T.angle(30)
    });

    // Rim shadow & highlight inside lower trough
    strokeSpline("rotring", palette.abyss, 0.7, T.pts(lTroughIn), 0.35);
    strokeSpline("cpencil", palette.bevelLight, 0.8, T.pts(lTroughOut), 0.35);

    // Stiffening rib at v = +52 and ejector pin ring at v = +64
    const rvLow = 52;
    const luA = s * 7.8;
    const luB = s * (pegOuterU(rvLow) - 4.3);
    strokeLine("cpencil", palette.bevelLight, 0.8, T.pt(luA, rvLow - 1.5), T.pt(luB, rvLow - 1.5));
    strokeLine("rotring", palette.abyss, 0.65, T.pt(luA, rvLow + 1.8), T.pt(luB, rvLow + 1.8));
    drawEjectorPinMark(T, s * 11.5, 64, 2.8, palette);

    // 5. Raised Circular Fulcrum Boss Collar around the Spring Seat (v = -13..+13)
    const bossArc = [];
    for (let a = -82; a <= 82; a += 14) {
      const rad = a * (Math.PI / 180);
      bossArc.push(T.pt(s * (2.5 + 12.5 * Math.cos(rad)), 12.5 * Math.sin(rad)));
    }
    strokeSpline("cpencil", palette.bevelLight, 0.9, bossArc, 0.5);
    const bossShadowArc = [];
    for (let a = -78; a <= 78; a += 14) {
      const rad = a * (Math.PI / 180);
      bossShadowArc.push(T.pt(s * (2.5 + 14.2 * Math.cos(rad)), 14.2 * Math.sin(rad)));
    }
    strokeSpline("rotring", palette.dark, 0.65, bossShadowArc, 0.5);

    // 6. Finger-Grip Serration Highlights (v = -100 to -58) & Saw-Tooth Jaw Facets (v = +45 to +78)
    for (let k = 0; k < 5; k++) {
      const gv = -98 + k * 8.8;
      const gu = s * pegOuterU(gv);
      strokeLine("cpencil", palette.spec, 0.9, T.pt(gu - s * 2.5, gv - 1.6), T.pt(gu, gv));
      strokeLine("rotring", palette.dark, 0.6, T.pt(gu - s * 2.8, gv + 2.0), T.pt(gu, gv + 2.4));
    }

    for (let k = 0; k < 4; k++) {
      const tv = 48 + k * 8.2;
      const tuTip = s * 1.4;
      const tuRoot = s * 4.8;
      strokeLine("cpencil", palette.bevelLight, 0.8, T.pt(tuRoot, tv - 3.5), T.pt(tuTip, tv));
      strokeLine("rotring", palette.abyss, 0.7, T.pt(tuTip, tv), T.pt(tuRoot, tv + 3.5));
    }

    // 7. Burnished Specular Highlights along the Front Bevel & Rim Contours
    const specOuter = [];
    for (let v = -102; v <= 80; v += 4) {
      specOuter.push(T.pt(s * (pegOuterU(v) - 1.5), v));
    }
    strokeSpline("cpencil", palette.bevelLight, 0.95, specOuter, 0.4);

    // Intense pure-white glint streaks along the upper handle and lower jaw bevel
    const glintUpper = [];
    for (let v = -96; v <= -38; v += 4) {
      glintUpper.push(T.pt(s * (pegOuterU(v) - 1.3), v));
    }
    strokeSpline("cpencil", palette.spec, 1.1, glintUpper, 0.4);

    const glintInner = [];
    for (let v = -100; v <= -18; v += 4) {
      glintInner.push(T.pt(s * (pegInnerU(v) + 1.4), v));
    }
    strokeSpline("cpencil", palette.bevelLight, 0.85, glintInner, 0.4);

    // Crisp outer boundary line of the lever
    strokeSpline("rotring", palette.abyss, 0.6, T.pts(outerFront), 0.35);
    strokeSpline("rotring", palette.abyss, 0.65, T.pts(innerFront), 0.35);
  }

  // 8. THE RUSTED STEEL TORSION SPRING (at fulcrum u = 0, v = 0)
  drawRustedTorsionSpring(T, palette, sideDir);
}

function drawEjectorPinMark(T, uCenter, vCenter, radius, palette) {
  const topArc = [];
  const botArc = [];
  for (let a = 180; a <= 360; a += 30) {
    const rad = a * (Math.PI / 180);
    topArc.push(T.pt(uCenter + radius * Math.cos(rad), vCenter + radius * Math.sin(rad)));
  }
  for (let a = 0; a <= 180; a += 30) {
    const rad = a * (Math.PI / 180);
    botArc.push(T.pt(uCenter + radius * Math.cos(rad), vCenter + radius * Math.sin(rad)));
  }
  strokeSpline("rotring", palette.dark, 0.5, topArc, 0.5);
  strokeSpline("cpencil", palette.bevelLight, 0.55, botArc, 0.5);
}

// =============================================================================
// RUSTED STEEL TORSION SPRING
// =============================================================================

function drawRustedTorsionSpring(T, palette, sideDir) {
  // 1. Orange-brown rust oxidation stains bleeding onto the plastic around the notches & boss
  const stainLeft = T.pts([[-29, -35], [-21, -33], [-21, -24], [-29, -25]]);
  const stainRight = T.pts([[21, -33], [29, -35], [29, -25], [21, -24]]);
  const stainCenter = T.pts([[-14, -10], [14, -10], [14, 10], [-14, 10]]);

  drawPolyLayer(stainLeft, { washCol: RUST.ochre, washOp: 130 });
  drawPolyLayer(stainRight, { washCol: RUST.ochre, washOp: 130 });
  drawPolyLayer(stainCenter, { washCol: RUST.rustRed, washOp: 120 });

  // 2. Crisp dark cast shadows of the two spring wire arms across the plastic levers
  const leftArmShadow = T.pts([
    [-12, -5], [-27.5, -26.5], [-27.5, -23.0], [-11, -1.5]
  ]);
  const rightArmShadow = T.pts([
    [12, 4], [27.5, -25.5], [27.5, -22.0], [12, 7.8]
  ]);
  drawPolyLayer(leftArmShadow, { washCol: palette.abyss, washOp: 220 });
  drawPolyLayer(rightArmShadow, { washCol: palette.abyss, washOp: 220 });

  // 3. Left Wire Arm + Hook around Left Plastic Notch (-26.5, -30)
  drawRustedWireSegment(T, [-11.5, -7.2], [-27.2, -28.8], 3.3);
  // Hook wrapping over the outer edge of the left lever
  drawRustedWireHook(T, -27.2, -29.2, -1);

  // 4. Right Wire Arm + Hook around Right Plastic Notch (+26.5, -30)
  drawRustedWireSegment(T, [11.5, 2.2], [27.2, -28.2], 3.3);
  drawRustedWireHook(T, 27.2, -28.8, 1);

  // 5. Central Helical Spring Coil (6 tightly wound turns across u = -13..+13, v = -8.5..+8.5)
  const coilShadow = T.pts([
    [-14.5, -6.5], [14.5, -6.5], [15.5, 11.8], [-13.5, 11.8]
  ]);
  drawPolyLayer(coilShadow, {
    washCol: RUST.abyss,
    washOp: 235
  });

  const numTurns = 6;
  const uStart = -12.5;
  const uEnd = 12.5;
  const turnW = (uEnd - uStart) / numTurns;

  for (let i = 0; i < numTurns; i++) {
    const u0 = uStart + i * turnW;
    const u1 = u0 + turnW * 0.88;
    const skew = 1.1; // helical slant of each coil turn

    // Coil cylinder body polygon
    const turnPoly = T.pts([
      [u0, -8.4],
      [u1, -8.4],
      [u1 + skew, 8.4],
      [u0 + skew, 8.4]
    ]);
    drawPolyLayer(turnPoly, {
      washCol: RUST.darkUmber,
      washOp: 245,
      hatchBrush: "cpencil",
      hatchCol: RUST.rustRed,
      hatchWeight: 0.65,
      hatchDist: 1.6,
      hatchAngle: T.angle(82)
    });

    // Mid-upper rust orange & ochre oxidation band across the curved wire turn
    const rustBand = T.pts([
      [u0 + 0.2, -6.2],
      [u1 - 0.2, -6.2],
      [u1 + skew * 0.6, 2.2],
      [u0 + skew * 0.6, 2.2]
    ]);
    drawPolyLayer(rustBand, {
      washCol: RUST.rustOrange,
      washOp: 215,
      hatchBrush: "cpencil",
      hatchCol: RUST.ochre,
      hatchWeight: 0.58,
      hatchDist: 1.5,
      hatchAngle: T.angle(15)
    });

    // Granular corroded rust stipple & metallic steel glint on each turn
    const uMid = 0.5 * (u0 + u1);
    strokeLine("charcoal", RUST.sienna, 0.7, T.pt(uMid, -5.5), T.pt(uMid + skew * 0.5, 3.8));
    strokeLine("cpencil", RUST.steelLight, 0.75, T.pt(uMid - 0.4, -6.8), T.pt(uMid + 0.2, -1.8));
    strokeLine("cpencil", RUST.spec, 0.9, T.pt(uMid - 0.2, -5.2), T.pt(uMid + 0.1, -2.5));

    // Deep dark crevice groove between adjacent coil turns
    strokeLine("rotring", RUST.abyss, 0.75, T.pt(u1, -8.6), T.pt(u1 + skew, 8.6));
  }
}

function drawRustedWireSegment(T, pA, pB, thickness) {
  const dx = pB[0] - pA[0];
  const dy = pB[1] - pA[1];
  const len = Math.hypot(dx, dy) || 1;
  const nx = (-dy / len) * (thickness * 0.5);
  const ny = (dx / len) * (thickness * 0.5);

  const wirePoly = T.pts([
    [pA[0] + nx, pA[1] + ny],
    [pB[0] + nx, pB[1] + ny],
    [pB[0] - nx, pB[1] - ny],
    [pA[0] - nx, pA[1] - ny]
  ]);
  drawPolyLayer(wirePoly, {
    washCol: RUST.sienna,
    washOp: 245,
    hatchBrush: "cpencil",
    hatchCol: RUST.rustOrange,
    hatchWeight: 0.6,
    hatchDist: 1.6,
    hatchAngle: T.angle(45)
  });

  // Wire cylindrical shading: dark underside, ochre rust mid, steel highlight crest
  strokeLine("rotring", RUST.abyss, 0.7, T.pt(pA[0] - nx * 0.85, pA[1] - ny * 0.85), T.pt(pB[0] - nx * 0.85, pB[1] - ny * 0.85));
  strokeLine("cpencil", RUST.ochre, 0.65, T.pt(pA[0], pA[1]), T.pt(pB[0], pB[1]));
  strokeLine("cpencil", RUST.steelLight, 0.7, T.pt(pA[0] + nx * 0.55, pA[1] + ny * 0.55), T.pt(pB[0] + nx * 0.55, pB[1] + ny * 0.55));
  strokeLine("cpencil", RUST.spec, 0.65,
    T.pt(pA[0] * 0.65 + pB[0] * 0.35 + nx * 0.5, pA[1] * 0.65 + pB[1] * 0.35 + ny * 0.5),
    T.pt(pA[0] * 0.35 + pB[0] * 0.65 + nx * 0.5, pA[1] * 0.35 + pB[1] * 0.65 + ny * 0.5)
  );
}

function drawRustedWireHook(T, uNotch, vNotch, dir) {
  const hookPts = T.pts([
    [uNotch - dir * 1.5, vNotch - 2.4],
    [uNotch + dir * 2.8, vNotch - 2.6],
    [uNotch + dir * 3.2, vNotch + 2.6],
    [uNotch - dir * 1.2, vNotch + 2.8]
  ]);
  drawPolyLayer(hookPts, {
    washCol: RUST.darkUmber,
    washOp: 245,
    hatchBrush: "cpencil",
    hatchCol: RUST.rustOrange,
    hatchWeight: 0.6,
    hatchDist: 1.5,
    hatchAngle: T.angle(90)
  });
