// =============================================================================
// HYPERREAL PLASTIC CLOTHES PEG (SIDE-PROFILE MACRO VIEW FOR PANE 7)
// =============================================================================

function drawHyperrealPegSide(cfg) {
  const { cx, cy, scale: S, angle, palette } = cfg;
  const T = makeTransform(cx, cy, S, angle);

  // In side profile, we see the broad side face of the peg (u = -21..+21, v = -108..+86)
  // with the prominent injection-mould parting seam running vertically down u = 0!
  const vSteps = [];
  for (let v = -108; v <= 86; v += 3) vSteps.push(v);

  function sideHalfWidth(v) {
    if (v < -104) return 11 + 8.5 * ((v + 108) / 4);
    if (v < -20) return 19.5 - ((v + 104) / 84) * 1.2;
    if (v < 20) return 18.3;
    if (v < 82) return 18.3 - ((v - 20) / 62) * 4.5;
    return 13.8 * ((86 - v) / 4 + 0.3);
  }

  const leftEdge = vSteps.map(v => [-sideHalfWidth(v), v]);
  const rightEdge = vSteps.slice().reverse().map(v => [sideHalfWidth(v), v]);
  const sideBodyPoly = [...leftEdge, ...rightEdge];

  // 1. Base side wall plastic body (lit on left half, shaded on right half of the mould seam)
  const leftHalfPoly = [
    ...vSteps.map(v => [-sideHalfWidth(v), v]),
    ...vSteps.slice().reverse().map(v => [0, v])
  ];
  const rightHalfPoly = [
    ...vSteps.map(v => [0, v]),
    ...vSteps.slice().reverse().map(v => [sideHalfWidth(v), v])
  ];

  drawPolyLayer(T.pts(leftHalfPoly), {
    washCol: palette.pure,
    washOp: 245,
    hatchBrush: "cpencil",
    hatchCol: palette.glow,
    hatchWeight: 0.65,
    hatchDist: 2.3,
    hatchAngle: T.angle(22)
  });

  drawPolyLayer(T.pts(rightHalfPoly), {
    washCol: palette.midDark,
    washOp: 245,
    hatchBrush: "cpencil",
    hatchCol: palette.dark,
    hatchWeight: 0.65,
    hatchDist: 2.2,
    hatchAngle: T.angle(-22)
  });

  // 2. Moulded Grip Ribs across the upper side handle (v = -98 to -58)
  for (let k = 0; k < 5; k++) {
    const gv = -96 + k * 8.6;
    const hw = sideHalfWidth(gv) - 1.5;
    const ribPts = T.pts([[-hw, gv - 2.0], [hw, gv - 2.0], [hw, gv + 2.0], [-hw, gv + 2.0]]);
    drawPolyLayer(ribPts, {
      washCol: palette.glow,
      washOp: 180
    });
    strokeLine("cpencil", palette.spec, 0.9, T.pt(-hw, gv - 1.6), T.pt(hw * 0.4, gv - 1.6));
    strokeLine("rotring", palette.dark, 0.65, T.pt(-hw, gv + 2.0), T.pt(hw, gv + 2.0));
  }

  // 3. THE PROMINENT VERTICAL MOULD-PARTING SEAM (u = 0, v = -107..+85)
  // Drawn with a sharp dark flash groove, raised bright plastic ridge, and tiny mould burrs
  const seamDarkPts = vSteps.map(v => T.pt(0.7, v));
  const seamBrightPts = vSteps.map(v => T.pt(-0.5, v));
  strokeSpline("rotring", palette.seamDark, 0.8, seamDarkPts, 0.3);
  strokeSpline("cpencil", palette.spec, 0.95, seamBrightPts, 0.3);

  // Two circular mould gate/ejector marks flanking the parting seam
  drawEjectorPinMark(T, -7.5, -38, 3.6, palette);
  drawEjectorPinMark(T, 7.5, 42, 3.4, palette);

  // 4. Burnished bevel highlight along the left edge & dark contour on both edges
  const leftSpec = vSteps.map(v => T.pt(-sideHalfWidth(v) + 2.2, v));
  strokeSpline("cpencil", palette.spec, 1.1, leftSpec, 0.35);
  strokeSpline("rotring", palette.abyss, 0.65, T.pts(leftEdge), 0.35);
  strokeSpline("rotring", palette.abyss, 0.7, T.pts(rightEdge), 0.35);

  // 5. Rusted Steel Spring Saddle Loop wrapping across the Side Notch at v = -29
  const hwNotch = sideHalfWidth(-29);
  // Rust stain around the notch
  drawPolyLayer(T.pts([[-hwNotch, -36], [hwNotch, -36], [hwNotch, -21], [-hwNotch, -21]]), {
    washCol: RUST.ochre,
    washOp: 125
  });
  // Dark shadow under the horizontal wire strap
  drawPolyLayer(T.pts([[-hwNotch, -27], [hwNotch, -27], [hwNotch, -22.5], [-hwNotch, -22.5]]), {
    washCol: palette.abyss,
    washOp: 225
  });
  // The rusted steel wire strap crossing horizontally from (-hwNotch, -29) to (+hwNotch, -29)
  drawRustedWireSegment(T, [-hwNotch - 1.5, -29.5], [hwNotch + 1.5, -28.5], 4.2);

  // End-on circular view of the rusted coil protruding slightly at the side edge (u = +hwNotch, v = 0)
  const coilEndPts = [];
  for (let a = -90; a <= 90; a += 20) {
    const rad = a * (Math.PI / 180);
    coilEndPts.push([hwNotch - 2 + 8.5 * Math.cos(rad), 8.5 * Math.sin(rad)]);
  }
  drawPolyLayer(T.pts(coilEndPts), {
    washCol: RUST.darkUmber,
    washOp: 245,
    hatchBrush: "cpencil",
    hatchCol: RUST.rustOrange,
    hatchWeight: 0.65,
    hatchDist: 1.5,
    hatchAngle: T.angle(45)
  });
}

// =============================================================================
// PANE 6 (CENTER): MEDIUM-SCALE CLOTHESLINE WITH YELLOW, RED & BLUE PEGS
// =============================================================================

function drawCenterClotheslineScene(pane) {
  // Continuous billowing white cotton sheet across the lower half of Pane 6 (y = 590..746)
  const sheetTop = [];
  const steps = 24;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = pane.x1 + (pane.x2 - pane.x1) * t;
    // Slight catenary sag along the washing line from (442, 594) to (896, 608)
    const sag = 14 * Math.sin(t * Math.PI);
    sheetTop.push([x, 592 + t * 14 + sag]);
  }

  const sheetPoly = [
    ...sheetTop,
    [pane.x2, pane.y2],
    [pane.x1, pane.y2]
  ];
  drawPolyLayer(sheetPoly, {
    washCol: COTTON.warmLight,
    washOp: 245,
    hatchBrush: "2H",
    hatchCol: "#E5ECF5",
    hatchWeight: 0.45,
    hatchDist: 4.0,
    hatchAngle: 4
  });

  // Pinched fabric drape folds under each of the three pegs (Yellow at x=526, Red at x=676, Blue at x=826)
  const pegConfigs = [
    { cx: 526, cy: 576, lineY: 604, scale: 0.88, angle: -5, palette: PALETTES.YELLOW, sideDir: -1 },
    { cx: 676, cy: 584, lineY: 612, scale: 0.88, angle: 4,  palette: PALETTES.RED,    sideDir: -1 },
    { cx: 826, cy: 586, lineY: 612, scale: 0.88, angle: -8, palette: PALETTES.BLUE,   sideDir: 1 }
  ];

  for (const pc of pegConfigs) {
    drawPinchedCottonSheet({
      cx: pc.cx, cy: pc.lineY, scale: pc.scale, angle: pc.angle,
      palette: pc.palette, pane,
      sheetWidth: 95, sheetDepth: 190
    });
  }

  // Continuous taut braided washing line spanning across the whole pane
  const cordTop = sheetTop.map(p => [p[0], p[1] - 3.4]);
  const cordBot = sheetTop.map(p => [p[0], p[1] + 3.4]);
  const cordShadow = sheetTop.map(p => [p[0], p[1] + 6.8]);

  drawPolyLayer([...cordBot, ...cordShadow.slice().reverse()], {
    washCol: COTTON.castShadow,
    washOp: 185
  });
  drawPolyLayer([...cordTop, ...cordBot.slice().reverse()], {
    washCol: "#D6DEE8",
    washOp: 235
  });
  strokeSpline("cpencil", "#FFFFFF", 0.9, cordTop, 0.4);
  strokeSpline("2B", "#3B4657", 0.6, cordBot, 0.4);

  // Render the three hyperreal pegs in pure Yellow, Red, and Blue
  for (const pc of pegConfigs) {
    drawHyperrealPegFront(pc);
    drawJawPinchOverlay(pc.cx, pc.cy, pc.scale, pc.angle, pc.palette);
  }
}

