// FLAT GOUACHE-LIKE WATERCOLOUR BLACK WINDOW MUNTINS
// =============================================================================

function drawWindowMuntins(panes) {
  clearPaneClip();

  // 1. Subtle interior depth shadow cast by the thick window muntins onto the top & left of each pane
  for (const key of Object.keys(panes)) {
    const p = panes[key];
    // Top interior glass rim shadow
    drawPolyLayer([
      [p.x1, p.y1], [p.x2, p.y1], [p.x2, p.y1 + 4.5], [p.x1, p.y1 + 4.5]
    ], { washCol: "#C8D0DC", washOp: 115 });
    // Left interior glass rim shadow
    drawPolyLayer([
      [p.x1, p.y1], [p.x1 + 4.5, p.y1], [p.x1 + 4.5, p.y2], [p.x1, p.y2]
    ], { washCol: "#C8D0DC", washOp: 115 });
  }

  // 2. Define all vertical and horizontal black muntin bars
  const bars = [
    // Outer window frame bars (24px thick)
    { x1: 0,    y1: 0,    x2: 1200, y2: 24,   dir: "H" },
    { x1: 0,    y1: 1176, x2: 1200, y2: 1200, dir: "H" },
    { x1: 0,    y1: 0,    x2: 24,   y2: 1200, dir: "V" },
    { x1: 1176, y1: 0,    x2: 1200, y2: 1200, dir: "V" },

    // Primary Vertical Muntins (28px thick)
    { x1: 414,  y1: 0,    x2: 442,  y2: 1200, dir: "V" },
    { x1: 896,  y1: 0,    x2: 924,  y2: 1200, dir: "V" },

    // Secondary Vertical Muntin in bottom-left (24px thick)
    { x1: 156,  y1: 760,  x2: 180,  y2: 1200, dir: "V" },

    // Primary Horizontal Muntin 1 across full width (28px thick)
    { x1: 0,    y1: 466,  x2: 1200, y2: 494,  dir: "H" },

    // Primary Horizontal Muntin 2 across left & center columns (28px thick)
    { x1: 0,    y1: 746,  x2: 910,  y2: 774,  dir: "H" },

    // Secondary Horizontal Muntins in right column (24px thick)
    { x1: 910,  y1: 198,  x2: 1200, y2: 222,  dir: "H" },
    { x1: 910,  y1: 938,  x2: 1200, y2: 962,  dir: "H" }
  ];

  // 3. Paint each muntin bar in dense, flat gouache-like watercolour with crisp edges
  for (const b of bars) {
    const pts = [
      [b.x1, b.y1],
      [b.x2, b.y1],
      [b.x2, b.y2],
      [b.x1, b.y2]
    ];
    const poly = new brush.Polygon(pts);

    // Dense opaque lamp-black gouache base wash
    poly.wash("#0D0F13", 252);

    // Flat gouache watercolour pass with minimal bleed and fine matte pigment tooth
    poly.fill("#111318", 220, 0.008, 0.32);

    // Longitudinal gouache brush-hair grain inside the bar
    brush.hatchStyle("cpencil", "#1A1E26", 0.55);
    poly.hatch(3.2, b.dir === "H" ? 0 : 90, { rand: 0.015 });
    brush.noHatch();

    brush.hatchStyle("2B", "#07080A", 0.65);
    poly.hatch(4.5, b.dir === "H" ? 0 : 90, { rand: 0.02 });
    brush.noHatch();
  }

  // 4. Crisp architectural gouache edges & subtle putty bevel along every pane opening
  for (const key of Object.keys(panes)) {
    const p = panes[key];
    // Razor-sharp dark pigment bead along the muntin boundary
    strokeLine("rotring", "#040507", 1.15, [p.x1, p.y1], [p.x2, p.y1]);
    strokeLine("rotring", "#040507", 1.15, [p.x2, p.y1], [p.x2, p.y2]);
    strokeLine("rotring", "#040507", 1.15, [p.x2, p.y2], [p.x1, p.y2]);
    strokeLine("rotring", "#040507", 1.15, [p.x1, p.y2], [p.x1, p.y1]);

    // Delicate matte gouache highlight along the bottom and right interior putty bevel
    strokeLine("2H", "#2B303C", 0.6, [p.x1 + 1.5, p.y2 + 1.8], [p.x2 - 1.5, p.y2 + 1.8]);
    strokeLine("2H", "#2B303C", 0.6, [p.x2 + 1.8, p.y1 + 1.5], [p.x2 + 1.8, p.y2 - 1.5]);
  }
}

