// Precompute 240x240 spatial grid for O(1) inside test, edge distance, elevation & ridge angle
function buildSpatialGrid() {
  grid = new Array(GRID_RES);
  for (let gx = 0; gx < GRID_RES; gx++) {
    grid[gx] = new Array(GRID_RES);
    let x = (gx + 0.5) * CELL_SIZE;
    for (let gy = 0; gy < GRID_RES; gy++) {
      let y = (gy + 0.5) * CELL_SIZE;
      let inside = pointInPoly(x, y, handPoly);
      let edgeInfo = nearestPolyEdge(x, y, handPoly);
      let signedDist = inside ? edgeInfo.dist : -edgeInfo.dist;
      let elev = inside ? computeElevation(x, y, signedDist) : 0;
      let rAngle = inside ? computeRidgeAngle(x, y) : 0;

      grid[gx][gy] = {
        inside: inside,
        edgeDist: signedDist,
        edgeAngle: edgeInfo.angle,
        nx: edgeInfo.nx,
        ny: edgeInfo.ny,
        elev: elev,
        ridgeAngle: rAngle
      };
    }
  }
}

function queryGrid(x, y) {
  let gx = Math.floor(x / CELL_SIZE);
  let gy = Math.floor(y / CELL_SIZE);
  if (gx < 0 || gx >= GRID_RES || gy < 0 || gy >= GRID_RES) {
    return { inside: false, edgeDist: -100, edgeAngle: 0, nx: 0, ny: 0, elev: 0, ridgeAngle: 0 };
  }
  return grid[gx][gy];
}

function computeElevation(x, y, edgeDist) {
  // Base cylindrical falloff from hand boundary
  let base = Math.min(1, Math.pow(Math.max(0, edgeDist) / 55, 0.55)) * 0.45;

  // Thenar eminence (huge muscular ball of thumb)
  let th = gaussianElliptical(x, y, 458, 812, 115, 165, -28) * 0.48;

  // Hypothenar eminence (ulnar muscular pad)
  let hy = gaussianElliptical(x, y, 748, 785, 82, 165, 14) * 0.38;

  // Central Palmar Hollow (Plain of Mars - concave depression)
  let hollow = -gaussianElliptical(x, y, 595, 725, 105, 95, 5) * 0.28;

  // Callus islands elevation boost
  let cal = 0;
  for (let c of callusIslands) {
    cal += gaussianElliptical(x, y, c.x, c.y, c.rx, c.ry, c.angle) * 0.34;
  }

  // Crease valley indentation
  let creaseDip = 0;
  for (let mc of majorCreases) {
    let d = distToPolyline(x, y, mc.pts);
    if (d < mc.bankWidth) {
      creaseDip += Math.pow(1 - d / mc.bankWidth, 2) * 0.28 * mc.depth;
    }
  }

  return constrain(base + th + hy + hollow + cal - creaseDip, 0, 1);
}

function computeRidgeAngle(x, y) {
  // Check proximity to fingertip whorls first
  for (let d of digits) {
    let w = d.whorl;
    let dx = x - w.x;
    let dy = y - w.y;
    let ca = cos(-w.angle);
    let sa = sin(-w.angle);
    let lx = dx * ca - dy * sa;
    let ly = dx * sa + dy * ca;
    let normD = Math.sqrt((lx / w.rx) ** 2 + (ly / w.ry) ** 2);
    if (normD < 2.2) {
      // Elliptical whorl tangent angle + gentle arch blend
      let tangentLocal = atan2(lx * (w.ry / w.rx), -ly * (w.rx / w.ry));
      let whorlAngle = w.angle + tangentLocal;
      let archAngle = w.angle + 90 + (ly / w.ry) * 28;
      let blend = constrain((normD - 1.1) / 1.1, 0, 1);
      return lerpAngleDeg(whorlAngle, archAngle, blend);
    }
  }

  // Inside finger shafts: gentle transverse arches bowed distally
  for (let d of digits) {
    let dAxis = distToPolylineInfo(x, y, d.axis);
    if (dAxis.dist < 52 && y < 650) {
      let perpAngle = dAxis.angle + 90;
      let signedSide = (x - dAxis.px) * cos(perpAngle) + (y - dAxis.py) * sin(perpAngle);
      let archCurvature = (signedSide / 40) * 24;
      return perpAngle - archCurvature;
    }
  }

  // Hypothenar whorl/loop on lower right palm
  let hdx = x - 758;
  let hdy = y - 815;
  let hDist = Math.sqrt(hdx * hdx + hdy * hdy);
  if (hDist < 95) {
    let loopAng = atan2(hdy, hdx) + 90;
    let blend = constrain(hDist / 95, 0, 1);
    let basePalmAng = 22 + 18 * sin((x - 450) * 0.5) - 15 * cos((y - 600) * 0.4);
    return lerpAngleDeg(loopAng, basePalmAng, blend * blend);
  }

  // Thenar sweep (parallel to Life Line around thumb base)
  if (x < 565 && y > 610 && y < 960) {
    let thAngle = atan2(y - 690, x - 340) + 82;
    return thAngle;
  }

  // General palmar dermatoglyphic sweep with triradius deflections
  let baseAng = 18 + (x - 580) * 0.12 + (y - 700) * 0.08;
  for (let tr of triradii) {
    let tdx = x - tr.x;
    let tdy = y - tr.y;
    let td = Math.sqrt(tdx * tdx + tdy * tdy);
    if (td < 68 && td > 2) {
      // Three-way triradius star deflection (-0.5 index singularity)
      let theta = atan2(tdy, tdx);
      let triAng = -0.5 * theta + 45;
      let w = Math.pow(1 - td / 68, 1.6);
      baseAng = lerpAngleDeg(baseAng, triAng, w);
    }
  }
  return baseAng;
}

