// ============================================================================
// LAYER 2: CARTOGRAPHIC COASTLINE RIPPLES & RHUMB LINES
// ============================================================================

function drawCartographicUnderlay() {
  // Faint rhumb lines (loxodromes) radiating from the thumb compass rose (286, 646)
  const cx = 286, cy = 646;
  brush.set("2H", "#b89b78", 0.26);
  for (let i = 0; i < 16; i++) {
    let ang = i * 22.5 - 10;
    let rStart = 54;
    let rEnd = 920;
    // Draw segmented faint chart lines across background and palm
    let steps = 18;
    for (let s = 0; s < steps; s++) {
      if (random() < 0.22) continue;
      let t0 = map(s, 0, steps, rStart, rEnd);
      let t1 = map(s + 0.75, 0, steps, rStart, rEnd);
      let x0 = cx + cos(ang) * t0;
      let y0 = cy + sin(ang) * t0;
      let x1 = cx + cos(ang) * t1;
      let y1 = cy + sin(ang) * t1;
      if (x0 > 45 && x0 < 1155 && y0 > 45 && y0 < 1155 &&
          x1 > 45 && x1 < 1155 && y1 > 45 && y1 < 1155) {
        brush.line(x0, y0, x1, y1);
      }
    }
  }

  // Faint antique coastline water-ripples echoing the hand silhouette outside
  const offsets = [7, 15, 25];
  const weights = [0.32, 0.24, 0.18];
  const cols = ["#9e7b56", "#b2916d", "#c4a784"];

  for (let k = 0; k < offsets.length; k++) {
    let dOff = offsets[k];
    brush.set("rotring", cols[k], weights[k]);
    let n = handPoly.length;
    let segPts = [];
    for (let i = 0; i < n; i++) {
      let pPrev = handPoly[(i - 1 + n) % n];
      let pCurr = handPoly[i];
      let pNext = handPoly[(i + 1) % n];
      if (pCurr[1] > 1165) {
        if (segPts.length > 3) brush.spline(segPts, 0.35);
        segPts = [];
        continue;
      }
      let tx = pNext[0] - pPrev[0];
      let ty = pNext[1] - pPrev[1];
      let len = Math.sqrt(tx * tx + ty * ty) || 1;
      // Outward normal for clockwise polygon in screen coords (y down) is (ty/len, -tx/len)
      let nx = ty / len;
      let ny = -tx / len;
      let ox = pCurr[0] + nx * dOff;
      let oy = pCurr[1] + ny * dOff;

      // Skip inside tight web clefts where offset self-intersects
      let q = queryGrid(ox, oy);
      if (q.inside || q.edgeDist > -dOff * 0.55 || random() < 0.08) {
        if (segPts.length > 3) brush.spline(segPts, 0.35);
        segPts = [];
      } else {
        segPts.push([ox, oy]);
        if (segPts.length > 14) {
          brush.spline(segPts, 0.35);
          segPts = [segPts[segPts.length - 1]];
        }
      }
    }
    if (segPts.length > 3) brush.spline(segPts, 0.35);
  }
}

