    if (tipPts.length > 3) drawFilledPoly(tipPts, "#b8764c", 56, 0.22, 0.58, 0.5);

    // Proximal & middle phalanx tea shading along finger sides
    for (let i = 0; i < d.axis.length - 1; i++) {
      let p0 = d.axis[i];
      let p1 = d.axis[i + 1];
      let mx = (p0[0] + p1[0]) * 0.5;
      let my = (p0[1] + p1[1]) * 0.5;
      let segLen = dist(p0[0], p0[1], p1[0], p1[1]) * 0.42;
      let segAng = atan2(p1[1] - p0[1], p1[0] - p0[0]);
      let r = d.radii[i] * 0.82;
      let padPts = makeRotatedOval(mx, my, segLen, r, segAng, 16, 0.06);
      padPts = clipPolyToHand(padPts);
      if (padPts.length > 3) drawFilledPoly(padPts, "#c99668", 38, 0.2, 0.55, 0.4);
