  // 5. Tea-stain river valley ribbons along major palmar creases
  for (let mc of majorCreases) {
    let ribbonPts = buildRibbonPoly(mc.pts, mc.bankWidth * 0.78);
    ribbonPts = clipPolyToHand(ribbonPts);
    if (ribbonPts.length > 3) {
      drawFilledPoly(ribbonPts, "#8c5832", 48 * mc.depth, 0.28, 0.75, 0.7);
    }
  }
}

