function drawCallusIslands() {
  // 1. Pale yellowish-parchment keratin washes for each raised callus island
  brush.noStroke();
  for (let c of callusIslands) {
    let outerPts = makeRotatedOval(c.x, c.y, c.rx * 1.08, c.ry * 1.08, c.angle, 18, 0.1);
    outerPts = clipPolyToHand(outerPts);
    if (outerPts.length > 3) {
      drawFilledPoly(outerPts, "#e6d2b2", 82, 0.16, 0.5, 0.65);
    }
    let corePts = makeRotatedOval(c.x, c.y, c.rx * 0.65, c.ry * 0.65, c.angle, 16, 0.09);
    corePts = clipPolyToHand(corePts);
    if (corePts.length > 3) {
      drawFilledPoly(corePts, "#f0e2c8", 88, 0.12, 0.45, 0.6);
    }
  }

  // 2. Concentric engraved skin-stratum / island coastline contours & slope hachures
  for (let c of callusIslands) {
    let numRings = c.rings;
    for (let rIdx = 0; rIdx < numRings; rIdx++) {
      let frac = map(rIdx, 0, numRings - 1, 0.28, 1.06);
      let rx = c.rx * frac;
      let ry = c.ry * frac;
      let ringPts = makeRotatedOval(c.x, c.y, rx, ry, c.angle, 28, 0.08);

      // Draw broken organic contour segments (peeling keratin / island shoal lines)
      let isOuter = (rIdx >= numRings - 2);
      let col = isOuter ? "#59381f" : "#785132";
      let w = isOuter ? 0.44 : 0.32;
      brush.set("rotring", col, w);

      let seg = [];
      for (let i = 0; i <= ringPts.length; i++) {
        let pt = ringPts[i % ringPts.length];
        let q = queryGrid(pt[0], pt[1]);
        if (!q.inside || q.edgeDist < 4 || random() < 0.16) {
          if (seg.length > 2) brush.spline(seg, 0.4);
          seg = [];
        } else {
          seg.push(pt);
        }
      }
      if (seg.length > 2) brush.spline(seg, 0.4);

      // Add tiny outward topographical slope hachures on the outer callus rim
      if (rIdx === numRings - 1 || rIdx === numRings - 2) {
        brush.set("rotring", "#664125", 0.28);
        let hCount = Math.floor((rx + ry) * 0.65);
        for (let h = 0; h < hCount; h++) {
          if (random() < 0.25) continue;
          let theta = map(h, 0, hCount, 0, 360) + random(-4, 4);
          let lx = cos(theta) * rx;
          let ly = sin(theta) * ry;
          let ca = cos(c.angle), sa = sin(c.angle);
          let px = c.x + lx * ca - ly * sa;
          let py = c.y + lx * sa + ly * ca;

          // Outward normal on rotated ellipse
          let nxLocal = cos(theta) / rx;
          let nyLocal = sin(theta) / ry;
          let nLen = Math.sqrt(nxLocal * nxLocal + nyLocal * nyLocal) || 1;
          nxLocal /= nLen;
          nyLocal /= nLen;
          let nx = nxLocal * ca - nyLocal * sa;
          let ny = nxLocal * sa + nyLocal * ca;

          let hLen = random(4, 8.5) * (rIdx === numRings - 1 ? 1.15 : 0.75);
          let q = queryGrid(px, py);
          if (q.inside && q.edgeDist > 6) {
            brush.line(px, py, px + nx * hLen, py + ny * hLen);
          }
        }
      }
    }
  }
}

// ============================================================================
// LAYER 5: DERMATOGLYPHICS (SEPIA FRICTION SKIN RIDGES & WHORLS)
// ============================================================================

function drawDermatoglyphicRidges() {
  // Streamlines following the exact palmar & digital friction-ridge vector field
  const spacing = 9.5;
  const stepLen = 6.5;

  for (let y = 95; y < 1165; y += spacing) {
    for (let x = 150; x < 915; x += spacing) {
      let sx = x + random(-3.2, 3.2);
      let sy = y + random(-3.2, 3.2);
      let q0 = queryGrid(sx, sy);
      if (!q0.inside || q0.edgeDist < 4) continue;

      // Slightly thin out ridges on smooth callus summits so calluses look keratinized
      let onCallusCore = false;
      for (let c of callusIslands) {
        if (gaussianElliptical(sx, sy, c.x, c.y, c.rx * 0.55, c.ry * 0.55, c.angle) > 0.6) {
          onCallusCore = true;
          break;
        }
      }
      if (onCallusCore && random() < 0.65) continue;

      // Trace a short curved skin ridge streamline of 4 to 7 vertices
      let pts = [[sx, sy]];
      let cx = sx, cy = sy;
      let numSteps = Math.floor(random(3, 6));
      let dirSign = random() < 0.5 ? 1 : -1;

      for (let s = 0; s < numSteps; s++) {
        let q = queryGrid(cx, cy);
        if (!q.inside || q.edgeDist < 3) break;
        let ang = q.ridgeAngle + (dirSign < 0 ? 180 : 0);
        cx += cos(ang) * stepLen;
        cy += sin(ang) * stepLen;
        let qNext = queryGrid(cx, cy);
        if (!qNext.inside || qNext.edgeDist < 3) break;
        pts.push([cx, cy]);
      }

      if (pts.length >= 3) {
        // Choose sepia shade and weight according to local elevation & shadow
        let darkFactor = 1 - q0.elev;
        let col = darkFactor > 0.58 ? "#5c3b21" : (darkFactor > 0.42 ? "#754e2f" : "#8c6340");
        let w = map(darkFactor, 0, 1, 0.20, 0.34);
        brush.set("rotring", col, w);
        brush.spline(pts, 0.45);
      }
    }
  }

  // Extra dense, crisp concentric whorl/loop ridges on the 5 fingertips & triradii
  for (let d of digits) {
    let w = d.whorl;
    for (let r = 4; r <= 34; r += 3.6) {
      let rx = r * (w.rx / 28);
      let ry = r * (w.ry / 28);
      let numArcs = 3;
      for (let a = 0; a < numArcs; a++) {
        let startA = a * 120 + random(-12, 12);
        let endA = startA + random(68, 102);
        let arcPts = [];
        for (let th = startA; th <= endA; th += 12) {
          let lx = cos(th) * rx;
          let ly = sin(th) * ry;
          let ca = cos(w.angle + 90), sa = sin(w.angle + 90);
          let px = w.x + lx * ca - ly * sa;
          let py = w.y + lx * sa + ly * ca;
          let q = queryGrid(px, py);
          if (q.inside && q.edgeDist > 3.5) arcPts.push([px, py]);
        }
        if (arcPts.length >= 3) {
          brush.set("rotring", "#59381f", 0.26);
          brush.spline(arcPts, 0.5);
        }
      }
    }
  }
}

// ============================================================================
// LAYER 6: SCULPTURAL FORM HATCHING & ANATOMICAL SHADING
// ============================================================================

function drawAnatomicalFormHatching() {
  // 1. Cylindrical cross-contour hatching along the shadowed edges of all 5 digits
  for (let d of digits) {
    let steps = 42;
    for (let s = 0; s < steps; s++) {
      let t = s / (steps - 1);
      let pos = samplePolyline(d.axis, t);
      let r = lerpArray(d.radii, t);
      let perpAngle = pos.angle + 90;
      let nx = cos(perpAngle);
      let ny = sin(perpAngle);

      // Left (radial) and Right (ulnar) cylindrical shadow wrap hatches
      for (let side of [-1, 1]) {
        // Right side receives deeper shadow (light coming from upper-left)
        let numPasses = (side === 1) ? 2 : 1;
        for (let p = 0; p < numPasses; p++) {
          let startFrac = (side === 1) ? random(0.32, 0.58) : random(0.48, 0.68);
          let endFrac = 0.96;
          let hatchPts = [];
          for (let f = startFrac; f <= endFrac; f += 0.14) {
            let distFromAxis = f * r * side;
            // Curve slightly along the cylinder contour
            let bow = Math.sin(f * Math.PI) * 5.5;
            let hx = pos.x + nx * distFromAxis - cos(pos.angle) * bow;
            let hy = pos.y + ny * distFromAxis - sin(pos.angle) * bow;
            let q = queryGrid(hx, hy);
            if (q.inside && q.edgeDist > 2) hatchPts.push([hx, hy]);
          }
          if (hatchPts.length >= 3) {
            let col = (side === 1) ? "#4f311a" : "#6e482b";
            let w = (side === 1) ? 0.30 : 0.24;
            brush.set("rotring", col, w);
            brush.spline(hatchPts, 0.45);
          }
        }
      }
    }
  }

  // 2. Sculptural cross-hatching in the Central Palmar Basin & Mount Slopes
  const shadowRegions = [
    // Deep palmar hollow (Plain of Mars)
    { x: 595, y: 720, rx: 95, ry: 85, ang1: -32, ang2: 38, density: 135, col: "#54341c", w: 0.28 },
    // Base of Thenar along Life Line valley
    { x: 535, y: 775, rx: 55, ry: 115, ang1: -55, ang2: 25, density: 110, col: "#4a2d17", w: 0.30 },
    // Ulnar border shadow along Hypothenar
    { x: 802, y: 770, rx: 42, ry: 135, ang1: -15, ang2: 45, density: 115, col: "#4a2d17", w: 0.30 },
    // Radial border shadow along lower Thenar & wrist
    { x: 405, y: 880, rx: 45, ry: 95, ang1: 28, ang2: -35, density: 85, col: "#59381f", w: 0.27 },
    // Web space valleys between finger bases
    { x: 518, y: 552, rx: 28, ry: 26, ang1: -45, ang2: 45, density: 42, col: "#472a15", w: 0.30 },
    { x: 631, y: 548, rx: 28, ry: 26, ang1: -45, ang2: 45, density: 42, col: "#472a15", w: 0.30 },
    { x: 738, y: 582, rx: 28, ry: 26, ang1: -45, ang2: 45, density: 42, col: "#472a15", w: 0.30 },
    // First web space (purlicue) deep fold
    { x: 412, y: 638, rx: 38, ry: 36, ang1: -25, ang2: 52, density: 58, col: "#472a15", w: 0.32 },
    // Wrist shadow below Rasceta
    { x: 600, y: 1065, rx: 155, ry: 85, ang1: -18, ang2: 22, density: 140, col: "#57361d", w: 0.28 }
  ];

  for (let sr of shadowRegions) {
    for (let i = 0; i < sr.density; i++) {
      let r = Math.sqrt(random()) * 0.98;
      let th = random(360);
      let px = sr.x + cos(th) * sr.rx * r;
      let py = sr.y + sin(th) * sr.ry * r;
      let q = queryGrid(px, py);
      if (!q.inside || q.edgeDist < 4) continue;

      let ang = (i % 2 === 0 ? sr.ang1 : sr.ang2) + random(-8, 8);
      let hLen = random(10, 22) * (1 - r * 0.45);
      let x0 = px - cos(ang) * hLen * 0.5;
      let y0 = py - sin(ang) * hLen * 0.5;
      let x1 = px + cos(ang) * hLen * 0.5;
      let y1 = py + sin(ang) * hLen * 0.5;
      if (queryGrid(x0, y0).inside && queryGrid(x1, y1).inside) {
        brush.set(i % 3 === 0 ? "2H" : "rotring", sr.col, sr.w);
        brush.line(x0, y0, x1, y1);
      }
    }
  }
}

// ============================================================================
// LAYER 7: DEEP PALMAR CREASES, RIVER VALLEYS & FINGER JOINT FOLDS
// ============================================================================

function drawCreaseRiversAndValleys() {
  // 1. Major Palmar Creases (Life, Head, Heart, Fate, Apollo, Rasceta)
  for (let mc of majorCreases) {
    let densePts = resamplePolyline(mc.pts, 8);

    // A. Bank Hachures & Tension Wrinkles (topographical river banks + skin fold tension lines)
    brush.set("rotring", "#5c3920", 0.27);
    for (let i = 1; i < densePts.length - 1; i++) {
      let pPrev = densePts[i - 1];
      let pCurr = densePts[i];
      let pNext = densePts[i + 1];
      let tang = atan2(pNext[1] - pPrev[1], pNext[0] - pPrev[0]);

      for (let side of [-1, 1]) {
        if (random() < 0.22) continue;
        // Oblique bank hachure angle (classic cartographic + anatomical crease feathering)
        let hAng = tang + side * random(58, 84);
        let bankLen = random(5, mc.bankWidth * 0.68) * mc.depth;
        let sx = pCurr[0] + cos(hAng) * random(1.2, 3.0);
        let sy = pCurr[1] + sin(hAng) * random(1.2, 3.0);
        let ex = sx + cos(hAng) * bankLen;
        let ey = sy + sin(hAng) * bankLen;
        if (queryGrid(sx, sy).inside && queryGrid(ex, ey).inside) {
          brush.line(sx, sy, ex, ey);
        }
      }
    }

    // B. Multi-pass Core River Fissure (braided sepia & dark iron-gall ink channels)
    // Pass 1: Warm sepia outer channel
    let pass1 = densePts.map(p => [p[0] + random(-1.2, 1.2), p[1] + random(-1.2, 1.2)]);
    brush.set("pen", "#54321a", mc.weight * 0.72);
    brush.spline(pass1, 0.45);

    // Pass 2: Deep umber-sepia core fissure
    let pass2 = densePts.map((p, idx) => {
      let t = idx / (densePts.length - 1);
      let pressure = Math.sin(t * Math.PI) * 0.85 + 0.35;
      return [p[0] + random(-0.6, 0.6), p[1] + random(-0.6, 0.6), pressure];
    });
    brush.set("rotring", "#2b170a", mc.weight * 0.58);
    brush.spline(pass2, 0.45);

    // Pass 3: Braided sister micro-channel along the deepest central section
    if (mc.depth > 0.75) {
      let subPts = densePts.slice(2, densePts.length - 2).map(p => [
        p[0] + random(-2.8, 2.8),
        p[1] + random(-2.8, 2.8)
      ]);
      if (subPts.length > 3) {
        brush.set("rotring", "#3d2210", mc.weight * 0.36);
        brush.spline(subPts, 0.4);
      }
    }
  }

  // 2. Secondary Tributary Creases & Estuaries
  for (let minPts of minorCreases) {
    let dense = resamplePolyline(minPts, 9);
    // Fine tributary hachures
    brush.set("rotring", "#6e472b", 0.23);
    for (let i = 1; i < dense.length - 1; i++) {
      if (random() < 0.45) continue;
      let tang = atan2(dense[i + 1][1] - dense[i - 1][1], dense[i + 1][0] - dense[i - 1][0]);
      let side = random() < 0.5 ? 1 : -1;
      let hAng = tang + side * random(55, 80);
      let len = random(4, 9);
      let sx = dense[i][0];
      let sy = dense[i][1];
      let ex = sx + cos(hAng) * len;
      let ey = sy + sin(hAng) * len;
      if (queryGrid(ex, ey).inside) brush.line(sx, sy, ex, ey);
    }

    // Core tributary line
    let jPts = dense.map((p, idx) => {
      let t = idx / (dense.length - 1);
      return [p[0] + random(-0.7, 0.7), p[1] + random(-0.7, 0.7), (1 - Math.abs(t - 0.5) * 1.4)];
    });
    brush.set("rotring", "#3f2412", 0.44);
    brush.spline(jPts, 0.45);
  }

  // 3. Interphalangeal Finger & Thumb Joint Flexion Folds (Double & Triple Elliptical Creases)
  for (let jc of jointCreases) {
    let ca = cos(jc.angle), sa = sin(jc.angle);
    let na = jc.angle + 90;
    let nca = cos(na), nsa = sin(na);

    for (let l = 0; l < jc.lines; l++) {
      let offsetAlongFinger = (l - (jc.lines - 1) * 0.5) * 6.5;
      let bowDir = (l === 0) ? -1 : 1;
      let bowAmp = (jc.lines === 3 && l === 1) ? 1.0 : 4.2 * bowDir;

      let foldPts = [];
      let steps = 10;
      for (let s = 0; s <= steps; s++) {
        let u = map(s, 0, steps, -0.46, 0.46);
        let across = u * jc.w;
        let arch = (1 - 4 * u * u) * bowAmp;
        let px = jc.x + across * ca + (offsetAlongFinger + arch) * nca;
        let py = jc.y + across * sa + (offsetAlongFinger + arch) * nsa;
        let q = queryGrid(px, py);
        if (q.inside && q.edgeDist > 2) {
          let pressure = (1 - 3.2 * u * u);
          foldPts.push([px, py, Math.max(0.25, pressure)]);
        }
      }

      if (foldPts.length >= 3) {
        // Soft shadow wash under joint crease
        brush.set("pen", "#633d22", 0.52);
        brush.spline(foldPts, 0.45);
        // Crisp dark crease core
        brush.set("rotring", "#2b170a", 0.42);
        brush.spline(foldPts, 0.45);

        // Short longitudinal skin-fold ticks crossing the joint crease
        brush.set("rotring", "#54331b", 0.24);
        for (let fPt of foldPts) {
          if (random() < 0.35) continue;
          let tickLen = random(4, 8.5);
          let tx0 = fPt[0] - nca * tickLen * 0.5;
          let ty0 = fPt[1] - nsa * tickLen * 0.5;
          let tx1 = fPt[0] + nca * tickLen * 0.5;
          let ty1 = fPt[1] + nsa * tickLen * 0.5;
          brush.line(tx0, ty0, tx1, ty1);
        }
      }
    }
  }
}

// ============================================================================
// LAYER 8: SKIN PORES, WEATHERED STIPPLING & LANGER'S POLYGON FISSURES
// ============================================================================

function drawPoresAndWeatheredTexture() {
  // 1. Fine Polygonal Skin Fissures (rhomboid skin crinkles in the central palm & wrist)
  brush.set("rotring", "#664227", 0.22);
  for (let i = 0; i < 360; i++) {
    let px = random(350, 835);
    let py = random(540, 1040);
    let q = queryGrid(px, py);
    if (!q.inside || q.edgeDist < 12) continue;

    // Cross-diagonal micro-fissures oblique to local ridge angle
    let ang = q.ridgeAngle + (random() < 0.5 ? 42 : -42) + random(-10, 10);
    let len = random(5, 13);
    let x1 = px + cos(ang) * len;
    let y1 = py + sin(ang) * len;
    if (queryGrid(x1, y1).inside) {
      brush.line(px, py, x1, y1);
    }
  }

  // 2. Thousands of Sepia Sweat Pores & Sun-Weathered Stipples along Ridges & Calluses
  const poreCols = ["#4a2c16", "#5e3b20", "#734b2c", "#3b2210"];
  for (let cIdx = 0; cIdx < poreCols.length; cIdx++) {
    brush.set("rotring", poreCols[cIdx], 0.32 + (cIdx % 2) * 0.1);
    let count = 420;
    for (let i = 0; i < count; i++) {
      let px = random(150, 915);
      let py = random(90, 1170);
      let q = queryGrid(px, py);
      if (!q.inside || q.edgeDist < 3) continue;

      // Tiny pore mark oriented along the skin ridge
      let pLen = random(1.0, 2.4);
      let ang = q.ridgeAngle;
      brush.line(px, py, px + cos(ang) * pLen, py + sin(ang) * pLen);
    }
  }

  // 3. Subtle dry-media charcoal/spray sun-weathered grain on mounts
  brush.set("spray", "#6e4728", 0.45);
  for (let i = 0; i < 65; i++) {
    let px = random(220, 840);
    let py = random(160, 1020);
    let q = queryGrid(px, py);
    if (q.inside && q.edgeDist > 20) {
      let ang = q.ridgeAngle;
      brush.line(px, py, px + cos(ang) * random(10, 24), py + sin(ang) * random(10, 24));
    }
  }
}

// ============================================================================
// LAYER 9: HAND OUTER CONTOUR, HYPONYCHIUM NAIL RIMS & COASTAL EDGE SHADOW
// ============================================================================

function drawHandContourAndNails() {
  // 1. Multi-pass organic sepia pen outline around the hand (thicker on shadowed ulnar/lower edges)
  let n = handPoly.length;
  let chunkSize = 10;

  for (let i = 0; i < n; i += chunkSize - 1) {
    let seg = [];
    let avgNx = 0, avgNy = 0;
    for (let k = 0; k <= chunkSize && (i + k) < n; k++) {
      let idx = (i + k) % n;
      let pPrev = handPoly[(idx - 1 + n) % n];
      let pCurr = handPoly[idx];
      let pNext = handPoly[(idx + 1) % n];
      if (pCurr[1] > 1182) continue;
      seg.push(pCurr);
      let tx = pNext[0] - pPrev[0];
      let ty = pNext[1] - pPrev[1];
      let l = Math.sqrt(tx * tx + ty * ty) || 1;
      avgNx += ty / l;
      avgNy += -tx / l;
    }

    if (seg.length >= 3) {
      // Light from top-left (-0.7, -0.7): edges facing bottom-right have heavier coastal shadow
      let shade = constrain((avgNx * 0.7 + avgNy * 0.7) / seg.length, -1, 1);
      let w = map(shade, -1, 1, 0.42, 0.95);
      let col = shade > 0.15 ? "#2b170a" : "#4f3019";
      brush.set("pen", col, w);
      brush.spline(seg, 0.4);

      // Add fine coastal edge hachures curving inward from the hand outline
      if (shade > -0.2) {
        brush.set("rotring", "#4f3019", 0.25);
        for (let pt of seg) {
          if (random() < 0.35 || pt[1] > 1160) continue;
          let q = queryGrid(pt[0], pt[1]);
          let inLen = random(4, 11) * map(shade, -0.2, 1, 0.6, 1.3);
          let ix = pt[0] - q.nx * inLen;
          let iy = pt[1] - q.ny * inLen;
          if (queryGrid(ix, iy).inside) {
            brush.line(pt[0], pt[1], ix, iy);
          }
        }
      }
    }
  }

  // 2. Hyponychium / Distal Nail Plate Crescent Rims peeking at the very apex of each fingertip
  for (let d of digits) {
    let nt = d.nailTip;
    let ca = cos(nt.angle), sa = sin(nt.angle);
    let pa = nt.angle + 90;
    let pca = cos(pa), psa = sin(pa);

    let innerArc = [];
    let outerArc = [];
    for (let s = -5; s <= 5; s++) {
      let u = s / 5;
      let across = u * nt.w * 0.5;
      let curveIn = (1 - u * u) * 7.5;
      let curveOut = (1 - u * u) * 11.5;
      innerArc.push([
        nt.x + across * pca - (curveIn - 4) * ca,
        nt.y + across * psa - (curveIn - 4) * sa
      ]);
      outerArc.push([
        nt.x + across * pca - (curveOut - 5.5) * ca,
        nt.y + across * psa - (curveOut - 5.5) * sa
      ]);
    }
    brush.set("rotring", "#3b2210", 0.36);
    brush.spline(innerArc, 0.5);
    brush.set("rotring", "#261408", 0.42);
    brush.spline(outerArc, 0.5);
  }
}

// ============================================================================
// LAYER 10: TINY MARINER'S COMPASS ROSE INKED ON THE THUMB
// ============================================================================

function drawThumbCompassRose(cx, cy) {
  // Oriented slightly with the thumb's surface while pointing North (-10 deg)
  const northAng = -10;
  const rOuter = 36;
  const rInnerRing = 31;
  const rCore = 7.5;

  // Helper to project compass coords onto the 3D cylindrical curvature of the thumb
  const thumbAxisAng = -56;
  function projThumb(dx, dy) {
    // Slight cylindrical foreshortening perpendicular to the thumb shaft
    let ca = cos(-thumbAxisAng), sa = sin(-thumbAxisAng);
    let tx = dx * ca - dy * sa;
    let ty = dx * sa + dy * ca;
    ty *= 0.87; // foreshorten across thumb cylinder
    let wx = tx * cos(thumbAxisAng) - ty * sin(thumbAxisAng);
    let wy = tx * sin(thumbAxisAng) + ty * cos(thumbAxisAng);
    return [cx + wx, cy + wy];
  }

  // Subtle antique ochre/tea wash behind the compass rose
  brush.noStroke();
  let roseWashPts = [];
  for (let a = 0; a < 360; a += 20) {
    roseWashPts.push(projThumb(cos(a) * rInnerRing * 0.9, sin(a) * rInnerRing * 0.9));
  }
  drawFilledPoly(roseWashPts, "#c99b68", 42, 0.15, 0.5, 0.5);

  // Outer & Inner Degree Rings
  for (let r of [rOuter, rInnerRing, rCore]) {
    let ringPts = [];
    for (let a = 0; a <= 360; a += 10) {
      ringPts.push(projThumb(cos(a) * r, sin(a) * r));
    }
    brush.set("rotring", "#2b1a0e", r === rOuter ? 0.38 : 0.28);
    brush.spline(ringPts, 0.45);
  }

  // Degree tick marks between inner and outer rings
  brush.set("rotring", "#3b2414", 0.22);
  for (let a = 0; a < 360; a += 7.5) {
    let p0 = projThumb(cos(a + northAng) * rInnerRing, sin(a + northAng) * rInnerRing);
    let p1 = projThumb(cos(a + northAng) * rOuter, sin(a + northAng) * rOuter);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // 16-Point Compass Star (8 secondary points + 8 principal points)
  // Draw 8 secondary half-points first
  for (let i = 0; i < 8; i++) {
    let ang = northAng + i * 45 + 22.5;
    let tipR = rInnerRing * 0.68;
    let baseR = rCore * 1.15;
    let halfSpan = 10;

    let pTip = projThumb(cos(ang) * tipR, sin(ang) * tipR);
    let pCenter = projThumb(cos(ang) * rCore * 0.4, sin(ang) * rCore * 0.4);
    let pLeft = projThumb(cos(ang - halfSpan) * baseR, sin(ang - halfSpan) * baseR);
    let pRight = projThumb(cos(ang + halfSpan) * baseR, sin(ang + halfSpan) * baseR);

    brush.set("rotring", "#3d2514", 0.24);
    brush.line(pLeft[0], pLeft[1], pTip[0], pTip[1]);
    brush.line(pRight[0], pRight[1], pTip[0], pTip[1]);
    brush.line(pCenter[0], pCenter[1], pTip[0], pTip[1]);
  }

  // Draw 8 principal points (Cardinals N, E, S, W and Ordinals NE, SE, SW, NW)
  for (let i = 0; i < 8; i++) {
    let isCardinal = (i % 2 === 0);
    let ang = northAng + i * 45;
    let tipR = isCardinal ? rInnerRing * 0.98 : rInnerRing * 0.82;
    let baseR = rCore * 1.35;
    let halfSpan = isCardinal ? 14 : 11;

    let pTip = projThumb(cos(ang) * tipR, sin(ang) * tipR);
    let pCenter = projThumb(0, 0);
    let pLeft = projThumb(cos(ang - halfSpan) * baseR, sin(ang - halfSpan) * baseR);
    let pRight = projThumb(cos(ang + halfSpan) * baseR, sin(ang + halfSpan) * baseR);

    // Shade the right half of each star point with dense ink lines
    brush.set("rotring", "#24160c", 0.25);
    for (let f = 0.15; f <= 0.95; f += 0.2) {
      let hx = lerp(pCenter[0], pRight[0], f);
      let hy = lerp(pCenter[1], pRight[1], f);
      brush.line(hx, hy, pTip[0], pTip[1]);
    }

    // Crisp outer edges of the star point
    brush.set("rotring", "#1f1209", isCardinal ? 0.34 : 0.28);
    brush.line(pLeft[0], pLeft[1], pTip[0], pTip[1]);
    brush.line(pRight[0], pRight[1], pTip[0], pTip[1]);
    brush.line(pCenter[0], pCenter[1], pTip[0], pTip[1]);
  }

  // Ornate miniature Fleur-de-Lis pointer at North (top of outer ring)
  let fnTip = projThumb(cos(northAng) * (rOuter + 13), sin(northAng) * (rOuter + 13));
  let fnBase = projThumb(cos(northAng) * rOuter, sin(northAng) * rOuter);
  let fnLeft = projThumb(cos(northAng - 10) * (rOuter + 6), sin(northAng - 10) * (rOuter + 6));
  let fnRight = projThumb(cos(northAng + 10) * (rOuter + 6), sin(northAng + 10) * (rOuter + 6));
  let fnCurlL = projThumb(cos(northAng - 16) * (rOuter + 2.5), sin(northAng - 16) * (rOuter + 2.5));
  let fnCurlR = projThumb(cos(northAng + 16) * (rOuter + 2.5), sin(northAng + 16) * (rOuter + 2.5));

  brush.set("rotring", "#1f1209", 0.36);
  brush.line(fnBase[0], fnBase[1], fnTip[0], fnTip[1]);
  brush.spline([fnBase, fnLeft, fnTip], 0.45);
  brush.spline([fnBase, fnRight, fnTip], 0.45);
  brush.spline([fnBase, fnLeft, fnCurlL], 0.5);
  brush.spline([fnBase, fnRight, fnCurlR], 0.5);
}

// ============================================================================
// LAYER 11: WINDING DOTTED BIRO TRAIL & INKED 'X' NEAR FINGER BASES
// ============================================================================

function drawBiroTrailAndX() {
  // Winding path from the wrist creases up through the palmar valleys to the 'X'
  const trailWaypoints = [
    [612, 1062],
    [605, 1012],
    [594, 962],  //Ford across Rasceta wrist rivers
    [568, 915],
    [548, 862],  // Skirting the eastern bank of the Life Line
    [556, 808],
    [592, 782],  // Entering the Central Hollow (Plain of Mars)
    [645, 780],
    [684, 754],  // Looping around the lower Apollo valley
    [676, 712],
    [640, 682],  // Crossing the Head Line Canyon
    [652, 650],
    [694, 642],  // Meandering below Mount of Apollo
    [682, 608],  // Crossing the Heart Line River
    [648, 582],
    [624, 556]   // Destination 'X' between Saturn & Apollo callus islands
  ];

  // Smoothly interpolate the trail
  let smoothTrail = [];
  for (let iteration = 0; iteration < 3; iteration++) {
    let src = (iteration === 0) ? trailWaypoints : smoothTrail;
    let next = [src[0]];
    for (let i = 0; i < src.length - 1; i++) {
      let p0 = src[i];
      let p1 = src[i + 1];
      next.push([0.75 * p0[0] + 0.25 * p1[0], 0.75 * p0[1] + 0.25 * p1[1]]);
      next.push([0.25 * p0[0] + 0.75 * p1[0], 0.25 * p0[1] + 0.75 * p1[1]]);
    }
    next.push(src[src.length - 1]);
    smoothTrail = next;
  }

  // Resample at even arc-length intervals to draw authentic ballpoint dashes/dots
  let totalLen = 0;
  for (let i = 0; i < smoothTrail.length - 1; i++) {
    totalLen += dist(smoothTrail[i][0], smoothTrail[i][1], smoothTrail[i + 1][0], smoothTrail[i + 1][1]);
  }

  let dashStep = 14.5;
  let dashLen = 6.8;
  let numDashes = Math.floor((totalLen - 22) / dashStep);

  for (let d = 0; d < numDashes; d++) {
    let s0 = (d * dashStep) / totalLen;
    let s1 = (d * dashStep + dashLen) / totalLen;
    let p0 = samplePolyline(smoothTrail, s0);
    let p1 = samplePolyline(smoothTrail, s1);

    // Subtle biro ink bleed into underlying skin ridge
    let mx = (p0.x + p1.x) * 0.5;
    let my = (p0.y + p1.y) * 0.5;
    let q = queryGrid(mx, my);
    let rAng = q.ridgeAngle;
    brush.set("rotring", "#2b3846", 0.24);
    brush.line(
      mx - cos(rAng) * 2.2, my - sin(rAng) * 2.2,
      mx + cos(rAng) * 2.2, my + sin(rAng) * 2.2
    );

    // Multi-pass ballpoint pen dash (weathered dark slate-indigo / blue-black biro)
    brush.set("pen", "#253342", 0.62);
    brush.line(p0.x, p0.y, p1.x, p1.y);

    brush.set("rotring", "#18222d", 0.48);
    brush.line(
      p0.x + random(-0.5, 0.5), p0.y + random(-0.5, 0.5),
      p1.x + random(-0.5, 0.5), p1.y + random(-0.5, 0.5)
    );

    // Ballpoint ink buildup dot at the start or end of dash
    brush.set("rotring", "#141c26", 0.58);
    brush.line(p0.x, p0.y, p0.x + 0.8, p0.y + 0.8);
  }

  // Draw the small hand-inked 'X' near the base of the middle & ring fingers (624, 556)
  const xx = 624, xy = 556;

  // Subtle ink stain halo around the X
  brush.noStroke();
  let xHalo = makeOrganicBlob(xx, xy, 18, 16, 14, 0.12);
  drawFilledPoly(xHalo, "#384654", 26, 0.25, 0.6, 0.5);

  // Faint dotted biro ring encircling the X
  brush.set("rotring", "#253342", 0.34);
  for (let a = 0; a < 360; a += 28) {
    let a1 = a + 14;
    let r = 21 + random(-1, 1);
    brush.line(
      xx + cos(a) * r, xy + sin(a) * r,
      xx + cos(a1) * r, xy + sin(a1) * r
    );
  }

  // Vigorous multi-stroke ballpoint 'X' (two crossed arms with ink buildup & ridge bleed)
  const arm1 = [[xx - 13, xy - 12], [xx - 4, xy - 3], [xx + 5, xy + 5], [xx + 14, xy + 13]];
  const arm2 = [[xx + 13, xy - 13], [xx + 4, xy - 4], [xx - 5, xy + 4], [xx - 13, xy + 13]];

  for (let arm of [arm1, arm2]) {
    // Micro-bleed along local skin furrows under the X
    for (let t = 0; t <= 1; t += 0.12) {
      let pt = samplePolyline(arm, t);
      let q = queryGrid(pt.x, pt.y);
      brush.set("rotring", "#283645", 0.28);
      brush.line(
        pt.x - cos(q.ridgeAngle) * 3.2, pt.y - sin(q.ridgeAngle) * 3.2,
        pt.x + cos(q.ridgeAngle) * 3.2, pt.y + sin(q.ridgeAngle) * 3.2
      );
    }

    // 4 overlapping ballpoint passes for realistic hand-drawn biro texture
    for (let pass = 0; pass < 4; pass++) {
      let jArm = arm.map((p, idx) => [
        p[0] + random(-1.4, 1.4),
        p[1] + random(-1.4, 1.4),
        (idx === 0 || idx === arm.length - 1) ? 1.15 : 0.85
      ]);
      brush.set(pass < 2 ? "pen" : "rotring", pass % 2 === 0 ? "#18222e" : "#241b18", pass < 2 ? 0.78 : 0.52);
      brush.spline(jArm, 0.35);
    }

    // Small serif/pressure ink ticks at the ends of the X arms
    for (let endPt of [arm[0], arm[arm.length - 1]]) {
      brush.set("rotring", "#141d26", 0.52);
      brush.line(endPt[0] - 2.2, endPt[1] + 1.5, endPt[0] + 2.2, endPt[1] - 1.5);
    }
  }
}

