// GEOMETRIC & BRUSH HELPER UTILITIES
// ============================================================================

function drawFilledPoly(pts, col, opacity, bleed, tex, border) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(0.35);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function makeOrganicBlob(cx, cy, rx, ry, numPts, irregularity) {
  let pts = [];
  let nOff = random(1000);
  for (let i = 0; i < numPts; i++) {
    let a = map(i, 0, numPts, 0, 360);
    let n = noise(cx * 0.01 + cos(a) * 1.2 + nOff, cy * 0.01 + sin(a) * 1.2);
    let rMod = 1 + map(n, 0, 1, -irregularity, irregularity);
    pts.push([cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod]);
  }
  return pts;
}

function makeRotatedOval(cx, cy, rx, ry, angleDeg, numPts, irregularity) {
  let pts = [];
  let ca = cos(angleDeg), sa = sin(angleDeg);
  let nOff = (cx * 0.13 + cy * 0.07) % 100;
  for (let i = 0; i < numPts; i++) {
    let a = map(i, 0, numPts, 0, 360);
    let n = noise(nOff + cos(a) * 1.1, nOff + sin(a) * 1.1);
    let rMod = 1 + map(n, 0, 1, -irregularity, irregularity);
    let lx = cos(a) * rx * rMod;
    let ly = sin(a) * ry * rMod;
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

function clipPolyToHand(pts) {
  let out = [];
  for (let p of pts) {
    let q = queryGrid(p[0], p[1]);
    if (q.inside && q.edgeDist > 2) {
      out.push(p);
    } else {
      // Pull point slightly inward toward hand interior
      let near = nearestPolyEdge(p[0], p[1], handPoly);
      let ix = near.px - near.nx * 5;
      let iy = near.py - near.ny * 5;
      if (queryGrid(ix, iy).inside) out.push([ix, iy]);
    }
  }
  return out;
}

function buildRibbonPoly(pts, halfWidth) {
  let left = [];
  let right = [];
  for (let i = 0; i < pts.length; i++) {
    let pPrev = pts[Math.max(0, i - 1)];
    let pNext = pts[Math.min(pts.length - 1, i + 1)];
    let ang = atan2(pNext[1] - pPrev[1], pNext[0] - pPrev[0]) + 90;
    let taper = Math.sin((i / (pts.length - 1)) * Math.PI) * 0.8 + 0.2;
    let w = halfWidth * taper;
    left.push([pts[i][0] + cos(ang) * w, pts[i][1] + sin(ang) * w]);
    right.unshift([pts[i][0] - cos(ang) * w, pts[i][1] - sin(ang) * w]);
  }
  return left.concat(right);
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
                    (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-7) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function nearestPolyEdge(x, y, poly) {
  let minD2 = Infinity;
  let bestAng = 0;
  let bestNx = 0, bestNy = 0;
  let bestPx = x, bestPy = y;
  let n = poly.length;
  for (let i = 0; i < n; i++) {
    let a = poly[i];
    let b = poly[(i + 1) % n];
    let vx = b[0] - a[0];
    let vy = b[1] - a[1];
    let l2 = vx * vx + vy * vy;
    let t = l2 > 0 ? constrain(((x - a[0]) * vx + (y - a[1]) * vy) / l2, 0, 1) : 0;
    let px = a[0] + t * vx;
    let py = a[1] + t * vy;
    let d2 = (x - px) ** 2 + (y - py) ** 2;
    if (d2 < minD2) {
      minD2 = d2;
      bestAng = atan2(vy, vx);
      let l = Math.sqrt(l2) || 1;
      bestNx = vy / l;
      bestNy = -vx / l;
      bestPx = px;
      bestPy = py;
    }
  }
  return { dist: Math.sqrt(minD2), angle: bestAng, nx: bestNx, ny: bestNy, px: bestPx, py: bestPy };
}

function distToPolyline(x, y, pts) {
  return distToPolylineInfo(x, y, pts).dist;
}

function distToPolylineInfo(x, y, pts) {
  let minD2 = Infinity;
  let bestAng = 0;
  let bestPx = x, bestPy = y;
  for (let i = 0; i < pts.length - 1; i++) {
    let a = pts[i];
    let b = pts[i + 1];
    let vx = b[0] - a[0];
    let vy = b[1] - a[1];
    let l2 = vx * vx + vy * vy;
    let t = l2 > 0 ? constrain(((x - a[0]) * vx + (y - a[1]) * vy) / l2, 0, 1) : 0;
    let px = a[0] + t * vx;
    let py = a[1] + t * vy;
    let d2 = (x - px) ** 2 + (y - py) ** 2;
    if (d2 < minD2) {
      minD2 = d2;
      bestAng = atan2(vy, vx);
      bestPx = px;
      bestPy = py;
    }
  }
  return { dist: Math.sqrt(minD2), angle: bestAng, px: bestPx, py: bestPy };
}

function gaussianElliptical(x, y, cx, cy, rx, ry, angleDeg) {
  let dx = x - cx;
  let dy = y - cy;
  let ca = cos(-angleDeg), sa = sin(-angleDeg);
  let lx = dx * ca - dy * sa;
  let ly = dx * sa + dy * ca;
  let d2 = (lx / rx) ** 2 + (ly / ry) ** 2;
  return d2 > 6 ? 0 : Math.exp(-d2 * 1.35);
}

function lerpAngleDeg(a, b, t) {
  let diff = ((b - a + 540) % 360) - 180;
  return a + diff * t;
}

function samplePolyline(pts, t) {
  t = constrain(t, 0, 1);
  let total = 0;
  let lens = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let d = dist(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    lens.push(d);
    total += d;
  }
  let target = t * total;
  let acc = 0;
  for (let i = 0; i < lens.length; i++) {
    if (acc + lens[i] >= target || i === lens.length - 1) {
      let localT = lens[i] > 0 ? (target - acc) / lens[i] : 0;
      let x = lerp(pts[i][0], pts[i + 1][0], localT);
      let y = lerp(pts[i][1], pts[i + 1][1], localT);
      let ang = atan2(pts[i + 1][1] - pts[i][1], pts[i + 1][0] - pts[i][0]);
      return { x: x, y: y, angle: ang };
    }
    acc += lens[i];
  }
  return { x: pts[0][0], y: pts[0][1], angle: 0 };
}

function resamplePolyline(pts, stepDist) {
  let total = 0;
  for (let i = 0; i < pts.length - 1; i++) {
    total += dist(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
  let steps = Math.max(4, Math.floor(total / stepDist));
  let out = [];
  for (let s = 0; s <= steps; s++) {
    let pos = samplePolyline(pts, s / steps);
    out.push([pos.x, pos.y]);
  }
  return out;
}

function lerpArray(arr, t) {
  let idx = constrain(t * (arr.length - 1), 0, arr.length - 1.0001);
  let i = Math.floor(idx);
  let f = idx - i;
  return lerp(arr[i], arr[i + 1], f);
}

// Cobalt Monochrome Urban Willow-Pattern:
// Documentary hyperrealism in transfer-printed stipple, engraved line & flow-blue glaze bleed

const PAL = {
  cream: "#F5F1E6",
  paperWarm: "#ECE6D6",
  glazeMist: "#D2E0F5",
  glazePale: "#A6C2E8",
  glazeSoft: "#739BD4",
  cobaltLight: "#4B78BE",
  cobaltMid: "#26539E",
  cobaltRich: "#143A82",
  cobaltDeep: "#0B245B",
  cobaltInk: "#061539",
  cobaltBlack: "#030B22"
};

const CX = 600;
const CY = 600;
const R_SCENE = 446;

function inScene(x, y, margin = 0) {
  let dx = x - CX;
  let dy = y - CY;
  return Math.sqrt(dx * dx + dy * dy) <= (R_SCENE + margin);
}

function clampToScene(x, y, margin = 0) {
  let dx = x - CX;
  let dy = y - CY;
  let d = Math.sqrt(dx * dx + dy * dy);
  let maxR = R_SCENE + margin;
  if (d <= maxR) return [x, y];
  let ang = Math.atan2(dy, dx);
  return [CX + Math.cos(ang) * maxR, CY + Math.sin(ang) * maxR];
}

function setPen(brushName, col, weight = 1) {
  brush.noFill();
  brush.noHatch();
  brush.set(brushName, col, weight);
}

// Bridge deck curve helper: x from 280 to 890
function bridgeArchY(x) {
  let t = (x - 585) / 305; // -1 to 1
  return 508 + 38 * t * t - 12 * t;
}

function bridgeDeckY(x) {
  let t = (x - 585) / 305;
  return 492 + 24 * t * t - 12 * t;
}

function bridgeTopRailY(x) {
  return bridgeDeckY(x) - 56;
}

