function drawPorcelainAndGlazeBleeds() {
  brush.noStroke();
  brush.noHatch();

  // Batch 1: Very pale mist glaze washes (outer plate rim & sky clouds)
  brush.fill(PAL.glazeMist, 65);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.65, 0.35);

  // Upper sky glaze aura
  drawBlob(600, 270, 290, 140, 18, 0.18);
  // Water mist base
  drawBlob(580, 790, 340, 190, 20, 0.15);

  // Outer scalloped rim glaze bleed halos
  for (let i = 0; i < 16; i++) {
    let ang = (i / 16) * Math.PI * 2;
    let rx = CX + Math.cos(ang) * 505;
    let ry = CY + Math.sin(ang) * 505;
    drawBlob(rx, ry, 85, 85, 12, 0.25);
  }

  // Batch 2: Soft flow-blue glaze pooling at scene edges & foliage
  brush.fill(PAL.glazePale, 75);
  brush.fillBleed(0.5, "out");
