  drawBlob(250, 610, 110, 140, 16, 0.2);
  drawBlob(920, 540, 115, 135, 16, 0.2);
  // Deep water shadow glaze
  drawBlob(575, 655, 250, 95, 18, 0.2);
  drawBlob(340, 860, 160, 110, 16, 0.22);

  // Ring of glaze pooling along the scalloped border band
  for (let i = 0; i < 24; i++) {
    let ang = (i / 24) * Math.PI * 2 + 0.1;
    let r = 465 + (i % 2) * 35;
    drawBlob(CX + Math.cos(ang) * r, CY + Math.sin(ang) * r, 58, 58, 10, 0.22);
  }

  // Batch 3: Mid cobalt glaze blur in deep architectural shadows
  brush.fill(PAL.glazeSoft, 70);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.75, 0.5);

  // Under bridge arch shadow pool
  drawBlob(585, 595, 220, 62, 16, 0.18);
  // Left wall water reflection pool
  drawBlob(285, 725, 95, 90, 14, 0.2);
  // Right wall water reflection pool
  drawBlob(855, 675, 95, 85, 14, 0.2);
  // Foreground parapet corner pool
  drawBlob(260, 820, 85, 95, 14, 0.22);

  // Batch 4: Concentrated cobalt glaze bleed in darkest recesses
  brush.fill(PAL.cobaltMid, 55);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.8, 0.55);
  drawBlob(580, 575, 165, 42, 14, 0.15);
