function drawBlob(cx, cy, rx, ry, steps = 14, irreg = 0.2) {
  brush.beginShape(0.5);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let n = noise(cx * 0.01 + Math.cos(a) * 1.5, cy * 0.01 + Math.sin(a) * 1.5);
    let radX = rx * (1 + (n - 0.5) * irreg * 2);
    let radY = ry * (1 + (n - 0.5) * irreg * 2);
    brush.vertex(cx + Math.cos(a) * radX, cy + Math.sin(a) * radY);
  }
  brush.endShape(true);
}

