// ============================================================================
// 3. CANAL WATER, REFLECTIONS & HYPERREAL INTERSECTING RIPPLES
// ============================================================================
function drawCanalWaterAndRipples() {
  // Define ripple centers (concentric elliptical rings on the water plane)
  const ripples = [
    { x: 560, y: 745, maxR: 195, freq: 0.24, amp: 1.0 },
    { x: 685, y: 815, maxR: 165, freq: 0.28, amp: 0.9 },
    { x: 445, y: 865, maxR: 150, freq: 0.26, amp: 0.85 },
    { x: 590, y: 940, maxR: 170, freq: 0.22, amp: 0.95 },
    { x: 485, y: 660, maxR: 110, freq: 0.35, amp: 0.75 },
    { x: 720, y: 695, maxR: 120, freq: 0.32, amp: 0.75 }
  ];

  // Engraved horizontal water lines from Y = 555 down to bottom of medallion (Y = 1044)
  for (let y = 556; y <= 1044; y += 2.6) {
    // Perspective foreshortening: lines get slightly bolder and wider-spaced toward bottom
    let depthT = constrain((y - 556) / 488, 0, 1);

    // Determine horizontal canal bounds at this Y
    let dy = y - CY;
    if (Math.abs(dy) >= R_SCENE - 2) continue;
    let circleHalfW = Math.sqrt(R_SCENE * R_SCENE - dy * dy);
    let minX = CX - circleHalfW + 4;
    let maxX = CX + circleHalfW - 4;

    // Left towpath wall cuts across water on left side
    let leftBankX = 150;
    if (y < 690) {
      leftBankX = map(y, 555, 690, 355, 290);
    } else if (y < 860) {
      leftBankX = map(y, 690, 860, 290, 350);
    } else {
      leftBankX = map(y, 860, 1044, 350, 395);
    }

    // Right canal wall cuts across water on right side
    let rightBankX = 1050;
    if (y < 710) {
      rightBankX = map(y, 555, 710, 825, 925);
    } else {
      rightBankX = map(y, 710, 1044, 925, 990);
    }

    let xStart = Math.max(minX, leftBankX);
    let xEnd = Math.min(maxX, rightBankX);
    if (xEnd <= xStart + 10) continue;

    // Walk along scanline in small segments to modulate darkness & wave displacement
    let stepX = 14;
    for (let x = xStart; x < xEnd; x += stepX) {
      let x2 = Math.min(xEnd, x + stepX);
      let xm = (x + x2) * 0.5;

      // Compute reflection tone at (xm, y)
      let tone = 0.25;

      // 1. Dark shadow directly under the bridge arch (Y: 556 to 650)
      let archShadow = Math.exp(-Math.pow((y - 585) / 48, 2));
      tone += archShadow * 0.62;

      // 2. Reflection of left & right brick abutments and lock house
      if (xm < 430) {
        tone += map(xm, xStart, 430, 0.48, 0.05, true);
      }
      if (xm > 740) {
        tone += map(xm, 740, xEnd, 0.05, 0.52, true);
      }

      // 3. Reflection of vertical bridge truss posts & diagonal bars in the water
      let postPhase = Math.sin((xm - 340) * (Math.PI * 2 / 60));
      if (y > 580 && y < 820 && postPhase > 0.65) {
        tone += 0.22 * (1 - (y - 580) / 260);
      }

      // 4. Ripple wave modulation
      let waveVal = Math.sin(y * 0.35 + xm * 0.04 + noise(xm * 0.02, y * 0.05) * 5) * 0.18;
      let rippleDispY = 0;

      for (let r of ripples) {
        let rdx = xm - r.x;
        let rdy = (y - r.y) * 3.1; // Foreshortened ellipse aspect ratio
        let dist = Math.sqrt(rdx * rdx + rdy * rdy);
        if (dist < r.maxR && dist > 4) {
          let atten = (1 - dist / r.maxR);
          let s = Math.sin(dist * r.freq - 0.8);
          waveVal += s * 0.38 * atten * r.amp;
          rippleDispY += s * 1.8 * atten * r.amp;
        }
      }

      let finalTone = tone + waveVal;

      // Leave crisp cream specular water highlights where finalTone is low
      if (finalTone < 0.18) continue;

      let wy1 = y + rippleDispY + Math.sin(x * 0.08 + y * 0.2) * 0.8;
      let wy2 = y + rippleDispY + Math.sin(x2 * 0.08 + y * 0.2) * 0.8;

      if (finalTone > 0.78) {
        setPen("rotring", PAL.cobaltBlack, 0.82 + depthT * 0.28);
        brush.line(x, wy1, x2, wy2);
        // Double-engraved line for deepest trough
        setPen("needle", PAL.cobaltDeep, 0.65);
        brush.line(x, wy1 + 1.1, x2, wy2 + 1.1);
      } else if (finalTone > 0.56) {
        setPen("rotring", PAL.cobaltDeep, 0.68 + depthT * 0.2);
        brush.line(x, wy1, x2, wy2);
      } else if (finalTone > 0.36) {
        setPen("engraver", PAL.cobaltRich, 0.55 + depthT * 0.15);
        brush.line(x, wy1, x2, wy2);
      } else {
        setPen("needle", PAL.cobaltLight, 0.42 + depthT * 0.1);
        brush.line(x, wy1, x2, wy2);
      }
    }
  }

  // Draw crisp concentric elliptical ripple crests & troughs
  for (let r of ripples) {
    let numRings = 7;
    for (let k = 1; k <= numRings; k++) {
      let radX = (k / numRings) * r.maxR * 0.88;
      let radY = radX / 3.1;
      let segs = 36;
      for (let s = 0; s < segs; s++) {
        if ( (s + k) % 3 === 0 ) continue; // Broken organic water ring
        let a1 = (s / segs) * Math.PI * 2;
        let a2 = ((s + 0.85) / segs) * Math.PI * 2;
        let x1 = r.x + Math.cos(a1) * radX;
        let y1 = r.y + Math.sin(a1) * radY;
        let x2 = r.x + Math.cos(a2) * radX;
        let y2 = r.y + Math.sin(a2) * radY;

        if (inScene(x1, y1, -6) && inScene(x2, y2, -6) && x1 > 345 && x1 < 920) {
          let col = k % 2 === 0 ? PAL.cobaltDeep : PAL.cobaltMid;
          setPen("engraver", col, 0.55 + (1 - k / numRings) * 0.35);
          brush.line(x1, y1, x2, y2);
        }
      }
    }
  }

  // Stipple tonal transitions across water surface (transferware dot sheen)
  setPen("transferDot", PAL.cobaltRich, 0.75);
  for (let i = 0; i < 280; i++) {
    let x = random(310, 910);
    let y = random(565, 980);
    if (inScene(x, y, -10)) {
      // Concentrate stipple near dark reflections
      if (y < 650 || x < 430 || x > 760 || random() < 0.3) {
        brush.line(x, y, x + random(4, 14), y + random(-1, 1));
      }
    }
  }
}

