function drawBrickWall(x1, y1, x2, y2, courseH, brickW, col, shadeProb) {
  let row = 0;
  for (let y = y1; y < y2; y += courseH) {
    if (!inScene(x1 + 20, y, -4)) continue;
    setPen("needle", col, 0.5);
    let slopeY = (y2 - y1) * 0.04;
    brush.line(x1, y, x2, y + slopeY);

    let offset = (row % 2) * (brickW * 0.5);
    for (let x = x1 + offset; x < x2; x += brickW) {
      if (!inScene(x, y, -4)) continue;
      let t = (x - x1) / (x2 - x1);
      let by = y + slopeY * t;
      setPen("needle", col, 0.48);
      brush.line(x, by, x, by + courseH);

      // Individual brick texture: stipple or fine horizontal hatch
      if (random() < shadeProb) {
        setPen("needle", col, 0.42);
        let bw = Math.min(brickW - 2, x2 - x);
        for (let h = 1.8; h < courseH - 1; h += 2.0) {
          brush.line(x + 1.5, by + h, x + bw, by + h);
        }
      }
    }
    row++;
  }
}

