  // Deep shadow under the bridge deck (gives 3D mass to the span)
  brush.hatchStyle("rotring", PAL.cobaltBlack, 0.8);
  brush.hatch(2.4, 12, { rand: 0.03 });
  brush.noStroke();
  brush.beginShape(0);
  for (let x = xL; x <= xR; x += 25) {
    brush.vertex(x, bridgeDeckY(x) + 6);
  }
  for (let x = xR; x >= xL; x -= 25) {
    brush.vertex(x, bridgeArchY(x) + 18);
  }
  brush.endShape(true);
  brush.noHatch();

  // Cross-hatch underside for deep cobalt transferware ink tone
  brush.hatchStyle("engraver", PAL.cobaltDeep, 0.65);
  brush.hatch(3.0, -25, { rand: 0.03 });
  brush.beginShape(0);
  for (let x = xL; x <= xR; x += 25) {
    brush.vertex(x, bridgeDeckY(x) + 8);
  }
  for (let x = xR; x >= xL; x -= 25) {
    brush.vertex(x, bridgeArchY(x) + 18);
  }
  brush.endShape(true);
  brush.noHatch();

  // Transverse I-beam floor joists under the bridge deck
  setPen("rotring", PAL.cobaltBlack, 0.75);
  for (let i = 0; i <= numBays * 2; i++) {
    let x = lerp(xL, xR, i / (numBays * 2));
    let y1 = bridgeDeckY(x) + 5;
    let y2 = bridgeArchY(x) + 17;
    brush.line(x, y1, x - 8, y2);
    brush.line(x + 2, y1, x - 6, y2);
  }

  // --- B. FAR-SIDE (BACK) PARAPET RAILING (IN PERSPECTIVE OFFSET) ---
  let backOffsetX = -10;
  let backOffsetY = -14;
  setPen("engraver", PAL.cobaltMid, 0.6);
  let backTopPts = [];
  let backBotPts = [];
  for (let i = 0; i <= numBays; i++) {
    let x = lerp(xL, xR, i / numBays) + backOffsetX;
    let yt = bridgeTopRailY(x - backOffsetX) + backOffsetY;
    let yb = bridgeDeckY(x - backOffsetX) + backOffsetY;
    backTopPts.push([x, yt]);
    backBotPts.push([x, yb]);
    // Back vertical posts
    setPen("engraver", PAL.cobaltMid, 0.65);
    brush.line(x, yt, x, yb);

    // Back diagonal truss & wire mesh
    if (i < numBays) {
      let nx = lerp(xL, xR, (i + 1) / numBays) + backOffsetX;
      let nyt = bridgeTopRailY(nx - backOffsetX) + backOffsetY;
      let nyb = bridgeDeckY(nx - backOffsetX) + backOffsetY;
      setPen("needle", PAL.cobaltLight, 0.5);
      brush.line(x, yt, nx, nyb);
      brush.line(x, yb, nx, nyt);
    }
  }
  setPen("rotring", PAL.cobaltMid, 0.75);
  brush.spline(backTopPts, 0.2);
  brush.spline(backBotPts, 0.2);

  // Pedestrian silhouettes or streetlamp poles on the bridge?
  // Two classic industrial swan-neck canal bridge lamps at 1/3 and 2/3 span
  for (let lampT of [0.28, 0.72]) {
    let lx = lerp(xL, xR, lampT);
    let ly = bridgeTopRailY(lx);
    setPen("rotring", PAL.cobaltDeep, 0.85);
    brush.line(lx, ly + 56, lx, ly - 52);
    brush.line(lx + 1.8, ly + 56, lx + 1.8, ly - 52);
    // Swan neck curve & luminaire hood
    brush.spline([[lx, ly - 52], [lx + 6, ly - 64], [lx + 16, ly - 60]], 0.4);
    brush.line(lx + 11, ly - 59, lx + 21, ly - 59);
    // Ladder rest bars
    brush.line(lx - 5, ly - 36, lx + 7, ly - 36);
  }

  // --- C. NEAR-SIDE (FRONT) STEEL PRATT TRUSS & SAFETY MESH ---
  // 1. Fine diamond chain-link safety mesh inside each truss bay
  for (let i = 0; i < numBays; i++) {
    let x1 = lerp(xL, xR, i / numBays);
    let x2 = lerp(xL, xR, (i + 1) / numBays);
    let yt1 = bridgeTopRailY(x1) + 4;
    let yt2 = bridgeTopRailY(x2) + 4;
    let yb1 = bridgeDeckY(x1) - 4;
    let yb2 = bridgeDeckY(x2) - 4;

    // Cross-hatched wire mesh in pale-to-mid cobalt needle lines
    for (let angle of [48, -48]) {
      brush.hatchStyle("needle", PAL.cobaltLight, 0.38);
      brush.hatch(5.5, angle, { rand: 0.01 });
      brush.noStroke();
      brush.beginShape(0);
      brush.vertex(x1 + 3, yt1);
      brush.vertex(x2 - 3, yt2);
      brush.vertex(x2 - 3, yb2);
      brush.vertex(x1 + 3, yb1);
      brush.endShape(true);
      brush.noHatch();
    }
  }

  // 2. Diagonal structural angle-iron bracing in each bay
  for (let i = 0; i < numBays; i++) {
    let x1 = lerp(xL, xR, i / numBays);
    let x2 = lerp(xL, xR, (i + 1) / numBays);
    let yt1 = bridgeTopRailY(x1);
    let yt2 = bridgeTopRailY(x2);
    let yb1 = bridgeDeckY(x1);
    let yb2 = bridgeDeckY(x2);

    setPen("rotring", PAL.cobaltDeep, 0.85);
    // Primary tension/compression diagonals (double line for steel L-section thickness)
    brush.line(x1 + 2, yt1 + 2, x2 - 2, yb2 - 2);
    brush.line(x1 + 4, yt1 + 2, x2, yb2 - 2);

    setPen("rotring", PAL.cobaltRich, 0.72);
    brush.line(x1 + 2, yb1 - 2, x2 - 2, yt2 + 2);
    brush.line(x1 + 4, yb1 - 2, x2, yt2 + 2);

    // Center X-intersection gusset plate with 4 bolts!
    let mx = (x1 + x2) * 0.5;
    let my = (yt1 + yb2) * 0.5;
    drawGussetPlate(mx, my, 10, 8, 4);
  }

  // 3. Main Lower Plate-Girder Web (between deck Y and arch Y)
  let deckPts = [];
  let archPts = [];
  let railPts = [];
  for (let i = 0; i <= 30; i++) {
    let x = lerp(xL - 8, xR + 8, i / 30);
    deckPts.push([x, bridgeDeckY(x)]);
    archPts.push([x, bridgeArchY(x)]);
    railPts.push([x, bridgeTopRailY(x)]);
  }

  // Wash cream + cobalt stipple on steel girder web so rivets & bolts stand out sharply
  brush.noStroke();
  brush.wash(PAL.cream, 210);
  brush.beginShape(0);
  for (let p of deckPts) brush.vertex(p[0], p[1]);
  for (let i = archPts.length - 1; i >= 0; i--) brush.vertex(archPts[i][0], archPts[i][1]);
  brush.endShape(true);
  brush.noWash();

  // Horizontal steel engraving lines along the girder web
  for (let i = 0; i < 30; i++) {
    let x1 = deckPts[i][0], x2 = deckPts[i + 1][0];
    let dy1 = deckPts[i][1], dy2 = deckPts[i + 1][1];
    let ay1 = archPts[i][1], ay2 = archPts[i + 1][1];
    for (let f = 0.15; f <= 0.9; f += 0.18) {
      setPen("engraver", PAL.cobaltMid, 0.55);
      brush.line(x1, lerp(dy1, ay1, f), x2, lerp(dy2, ay2, f));
    }
  }

  // Heavy top handrail, middle chord, and lower arch chord flanges
  setPen("rotring", PAL.cobaltBlack, 1.15);
  brush.spline(railPts, 0.2);
  setPen("rotring", PAL.cobaltDeep, 0.85);
  brush.spline(railPts.map(p => [p[0], p[1] + 3.5]), 0.2);

  setPen("rotring", PAL.cobaltBlack, 1.2);
  brush.spline(deckPts, 0.2);
  brush.spline(deckPts.map(p => [p[0], p[1] - 3.5]), 0.2);

  setPen("rotring", PAL.cobaltBlack, 1.25);
  brush.spline(archPts, 0.2);
  brush.spline(archPts.map(p => [p[0], p[1] + 3.5]), 0.2);

  // 4. Vertical H-Beam Stanchions & Riveted Gusset Plates with Hex Bolts
  for (let i = 0; i <= numBays; i++) {
    let x = lerp(xL, xR, i / numBays);
    let yt = bridgeTopRailY(x);
    let yd = bridgeDeckY(x);
    let ya = bridgeArchY(x);

    // Cream highlight strip on left flange of vertical post
    brush.noStroke();
    brush.wash(PAL.cream, 220);
    brush.rect(x - 3.5, yt, 7, ya - yt, "corner");
    brush.noWash();

    // Vertical post flanges
    setPen("rotring", PAL.cobaltBlack, 0.95);
    brush.line(x - 3.5, yt, x - 3.5, ya + 3);
    brush.line(x + 3.5, yt, x + 3.5, ya + 3);
    // Shaded web of vertical post
    setPen("engraver", PAL.cobaltRich, 0.6);
    brush.line(x + 1, yt, x + 1, ya);

    // Top gusset plate & bolts
    drawGussetPlate(x, yt + 5, 15, 11, 6);
    // Deck-level heavy gusset plate & bolts
    drawGussetPlate(x, yd - 3, 18, 14, 8);
    // Lower arch flange splice plate & bolts
    drawGussetPlate(x, ya, 14, 9, 4);
  }

  // Row of rivets & drainage weep holes along the main girder web
  for (let x = xL + 8; x < xR - 8; x += 9) {
    let yd = bridgeDeckY(x);
    let ya = bridgeArchY(x);
    drawMicroBolt(x, yd + 4.5, 1.6);
    drawMicroBolt(x, ya - 3.5, 1.6);
  }
}

function drawGussetPlate(cx, cy, w, h, numBolts) {
  let x0 = cx - w / 2;
  let y0 = cy - h / 2;
  // Opaque cream backing
  brush.noStroke();
  brush.wash(PAL.cream, 235);
  brush.rect(x0, y0, w, h, "corner");
  brush.noWash();

  // Gusset bevel outline & bottom/right cast shadow
  setPen("rotring", PAL.cobaltDeep, 0.75);
  brush.rect(x0, y0, w, h, "corner");
  setPen("rotring", PAL.cobaltBlack, 1.0);
  brush.line(x0, y0 + h, x0 + w, y0 + h);
  brush.line(x0 + w, y0, x0 + w, y0 + h);

  // Hex bolts arranged in two rows inside gusset plate
  let cols = Math.max(2, Math.floor(numBolts / 2));
  for (let c = 0; c < cols; c++) {
    let bx = x0 + 3 + (c / Math.max(1, cols - 1)) * (w - 6);
    drawMicroBolt(bx, y0 + 3, 1.8);
    drawMicroBolt(bx, y0 + h - 3, 1.8);
  }
}

function drawMicroBolt(x, y, r) {
  // Cast shadow under hex bolt head
  setPen("rotring", PAL.cobaltBlack, 0.9);
  brush.line(x - r * 0.7, y + r * 0.8, x + r * 0.9, y + r * 0.8);
  brush.line(x + r * 0.8, y - r * 0.5, x + r * 0.8, y + r * 0.8);
  // Top-left rim of hex head
  setPen("needle", PAL.cobaltRich, 0.55);
  brush.line(x - r * 0.8, y - r * 0.7, x + r * 0.7, y - r * 0.7);
  brush.line(x - r * 0.8, y - r * 0.7, x - r * 0.8, y + r * 0.7);
}

// ============================================================================
// 7. FOREGROUND TOWPATH PARAPET & HYPERREAL CLOSE-UP STRUCTURAL BOLTS
// ============================================================================
function drawForegroundParapetAndBolts() {
  // In the lower-left foreground (X: 170 to 395, Y: 660 to 1015), the canal towpath
  // and bridge approach parapet sweep forward into documentary close-up!

  // 1. Towpath Masonry Coping Stones & Cracked Concrete Wall (X: 165 to 385, Y: 685 to 1015)
  brush.noStroke();
  brush.wash(PAL.cream, 215);
  brush.beginShape(0);
