  brush.vertex(310, 665);
  brush.vertex(390, 995);
  brush.vertex(250, 985);
  brush.endShape(true);
  brush.noWash();

  // Shaded vertical canal-facing wall of foreground towpath
  brush.hatchStyle("rotring", PAL.cobaltDeep, 0.72);
  brush.hatch(2.8, 18, { rand: 0.04 });
  brush.noStroke();
  brush.beginShape(0);
