  brush.noHatch();

  // Cross-hatch lower waterline of towpath wall
  brush.hatchStyle("rotring", PAL.cobaltBlack, 0.75);
  brush.hatch(2.4, -40, { rand: 0.04 });
  brush.beginShape(0);
  brush.vertex(325, 760);
  brush.vertex(345, 685);
  brush.vertex(405, 1005);
  brush.vertex(380, 1008);
  brush.endShape(true);
  brush.noHatch();

  // Coping stone joints & surface stipple
  setPen("rotring", PAL.cobaltDeep, 0.85);
  brush.line(295, 670, 355, 1010);
  brush.line(345, 685, 405, 1005);
  for (let t = 0.1; t < 0.95; t += 0.16) {
    let jx1 = lerp(175, 290, t);
    let jy1 = lerp(695, 990, t);
    let jx2 = lerp(295, 355, t);
    let jy2 = lerp(670, 1010, t);
    setPen("rotring", PAL.cobaltDeep, 0.75);
    brush.line(jx1, jy1, jx2, jy2);
    // Vertical joint on side face
    let jx3 = lerp(345, 405, t);
    let jy3 = lerp(685, 1005, t);
    brush.line(jx2, jy2, jx3, jy3);
  }

  // 2. Close-up Steel Parapet Stanchion, Splice Plate & Heavy Hex Bolts (X: 215 to 335, Y: 635 to 915)
  // Heavy angled handrail bar coming from the bridge abutment toward the foreground
  let rTop1 = [308, 452], rTop2 = [195, 675];
  let rBot1 = [308, 505], rBot2 = [202, 745];

  // Cream wash inside foreground steel rails
  brush.noStroke();
  brush.wash(PAL.cream, 235);
  brush.beginShape(0);
