  brush.vertex(rTop2[0], rTop2[1]);
  brush.vertex(rTop2[0], rTop2[1] + 18);
  brush.vertex(rTop1[0], rTop1[1] + 10);
  brush.endShape(true);
  brush.noWash();

  // Shaded steel channel underside
  for (let f = 0; f <= 1; f += 0.015) {
    let x = lerp(rTop2[0], rTop1[0], f);
    let y = lerp(rTop2[1], rTop1[1], f);
    let h = lerp(18, 10, f);
    setPen("engraver", PAL.cobaltRich, 0.6);
    brush.line(x, y + h * 0.45, x, y + h);
  }
  setPen("rotring", PAL.cobaltBlack, 1.15);
  brush.line(rTop2[0], rTop2[1], rTop1[0], rTop1[1]);
  brush.line(rTop2[0], rTop2[1] + 18, rTop1[0], rTop1[1] + 10);

  // Foreground Hero Vertical Steel Box-Stanchion (X: 238 to 282, Y: 585 to 865)
  let sx = 240, sy = 582, sw = 38, sh = 275;
  brush.noStroke();
  brush.wash(PAL.cream, 240);
  brush.rect(sx, sy, sw, sh, "corner");
  brush.noWash();

  // Engraved vertical steel grain & right-side flange shadow
  for (let x = sx + 2; x < sx + sw; x += 2.2) {
    let weight = x > sx + sw * 0.6 ? 0.75 : 0.42;
    let col = x > sx + sw * 0.6 ? PAL.cobaltDeep : PAL.cobaltLight;
    if (x > sx + sw * 0.25 && x < sx + sw * 0.42) continue; // Specular cream highlight band
    setPen("engraver", col, weight);
    brush.line(x, sy + 4, x, sy + sh - 4);
  }
  setPen("rotring", PAL.cobaltBlack, 1.2);
  brush.rect(sx, sy, sw, sh, "corner");

  // HERO SPLICE PLATE (X: 228 to 292, Y: 660 to 770) with 8 Hyperreal Structural Hex Bolts!
  let px = 228, py = 662, pw = 64, ph = 108;
  // Cast shadow of splice plate
  brush.hatchStyle("rotring", PAL.cobaltBlack, 0.85);
  brush.hatch(1.8, 45, { rand: 0.02 });
  brush.noStroke();
  brush.rect(px + 4, py + 5, pw, ph, "corner");
