  // Splice plate body
  brush.noStroke();
  brush.wash(PAL.cream, 245);
  brush.rect(px, py, pw, ph, "corner");
  brush.noWash();

  // Brushed steel horizontal cross-hatching & rust stipple around bolts
  for (let y = py + 3; y < py + ph - 2; y += 2.5) {
    setPen("needle", PAL.cobaltLight, 0.45);
    brush.line(px + 3, y, px + pw - 3, y);
  }
  setPen("rotring", PAL.cobaltBlack, 1.15);
  brush.rect(px, py, pw, ph, "corner");
