  // Draw 8 Large Hyperreal Hexagonal Bolts & Washers on the Hero Splice Plate
  const boltRows = [py + 16, py + 41, py + 67, py + 92];
  const boltCols = [px + 17, px + 47];
  for (let by of boltRows) {
    for (let bx of boltCols) {
      drawHeroHexBolt(bx, by, 8.5);
