  }

  // Heavy Bolted Baseplate Anchored to Concrete Coping Stone (X: 218 to 302, Y: 842 to 874)
  brush.noStroke();
  brush.wash(PAL.cream, 235);
  brush.beginShape(0);
  brush.vertex(226, 842);
  brush.vertex(294, 838);
  brush.vertex(306, 870);
  brush.vertex(216, 876);
  brush.endShape(true);
  brush.noWash();

  setPen("rotring", PAL.cobaltBlack, 1.1);
  brush.beginShape(0);
  brush.vertex(226, 842);
  brush.vertex(294, 838);
  brush.vertex(306, 870);
  brush.vertex(216, 876);
  brush.endShape(true);
  // Baseplate thickness
  brush.line(216, 876, 216, 883);
  brush.line(306, 870, 306, 877);
  brush.line(216, 883, 306, 877);

  // Anchor bolts with protruding threaded studs on baseplate
  drawHeroHexBolt(234, 858, 7.5, true);
  drawHeroHexBolt(286, 854, 7.5, true);

  // Cast-iron canal mooring bollard in lower foreground (X: 300 to 342, Y: 885 to 975)
  drawMooringBollard(320, 935);
}

// Hyperreal close-up hexagonal structural bolt with washer, facets, shadow & rust stipple
function drawHeroHexBolt(cx, cy, r, withThread = false) {
  // 1. Rust & weathering streak below bolt in fine cobalt stipple
  setPen("transferDot", PAL.cobaltMid, 0.65);
  brush.line(cx, cy + r, cx, cy + r * 2.4);

  // 2. Cast shadow of circular washer & hex nut (down-right)
  brush.hatchStyle("rotring", PAL.cobaltBlack, 0.85);
  brush.hatch(1.5, 40, { rand: 0.02 });
  brush.noStroke();
  brush.circle(cx + 2.5, cy + 3.0, r * 1.18, 0.05);
  brush.noHatch();

  // 3. Circular steel washer
  brush.noStroke();
  brush.wash(PAL.cream, 245);
  brush.circle(cx, cy, r * 1.15, 0.04);
  brush.noWash();
  setPen("rotring", PAL.cobaltDeep, 0.85);
  brush.circle(cx, cy, r * 1.15, 0.04);

  // 4. 3D Hexagonal Bolt Head / Nut (6 vertices + side facet depth)
  let hexPts = [];
  for (let i = 0; i < 6; i++) {
    let a = (i * 60 - 30) * (Math.PI / 180);
    hexPts.push([cx + Math.cos(a) * r * 0.82, cy + Math.sin(a) * r * 0.82]);
  }

  // Shade bottom & right facets of hexagon
  brush.hatchStyle("rotring", PAL.cobaltDeep, 0.75);
  brush.hatch(1.6, 15, { rand: 0.02 });
  brush.noStroke();
  brush.beginShape(0);
  brush.vertex(cx, cy);
  brush.vertex(hexPts[1][0], hexPts[1][1]);
  brush.vertex(hexPts[2][0], hexPts[2][1]);
  brush.vertex(hexPts[3][0], hexPts[3][1]);
  brush.endShape(true);
  brush.noHatch();

  // Mid-tone shade on lower-left facet
  brush.hatchStyle("needle", PAL.cobaltMid, 0.55);
  brush.hatch(2.0, -30, { rand: 0.02 });
  brush.beginShape(0);
  brush.vertex(cx, cy);
  brush.vertex(hexPts[3][0], hexPts[3][1]);
  brush.vertex(hexPts[4][0], hexPts[4][1]);
  brush.endShape(true);
  brush.noHatch();

  // Crisp hexagon edges & inner chamfer circle
  setPen("rotring", PAL.cobaltBlack, 0.95);
  for (let i = 0; i < 6; i++) {
    let p1 = hexPts[i];
    let p2 = hexPts[(i + 1) % 6];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  setPen("engraver", PAL.cobaltDeep, 0.65);
  brush.circle(cx, cy, r * 0.58, 0.03);

  // Protruding threaded bolt shaft center (with helical thread rings)
  if (withThread) {
    for (let ty = cy + 2; ty >= cy - 7; ty -= 2.0) {
      setPen("rotring", PAL.cobaltBlack, 0.8);
      brush.arc(cx, ty, r * 0.42, 0, 360);
    }
  } else {
    // Stamped bolt grade markings on flat bolt head
    setPen("needle", PAL.cobaltRich, 0.55);
    brush.line(cx - r * 0.25, cy - r * 0.15, cx + r * 0.25, cy - r * 0.15);
    brush.line(cx - r * 0.15, cy + r * 0.2, cx + r * 0.2, cy + r * 0.2);
  }
}

function drawMooringBollard(bx, by) {
  // Cast-iron cylindrical bollard with flared mushroom cap
  let bw = 28, bh = 58;
  // Cast shadow on towpath stones
  brush.hatchStyle("rotring", PAL.cobaltBlack, 0.85);
  brush.hatch(2.0, 25, { rand: 0.03 });
  brush.noStroke();
  brush.beginShape(0.2);
  brush.vertex(bx + 10, by + 20);
  brush.vertex(bx + 45, by + 28);
  brush.vertex(bx + 42, by + 42);
  brush.vertex(bx - 12, by + 30);
  brush.endShape(true);
  brush.noHatch();

  // Bollard body
  brush.noStroke();
  brush.wash(PAL.cream, 235);
  brush.rect(bx - bw / 2, by - bh / 2, bw, bh, "corner");
  brush.noWash();

  // Cylindrical vertical contour shading
  for (let dx = -bw / 2; dx <= bw / 2; dx += 2.0) {
    if (dx > -9 && dx < -3) continue; // Specular cream highlight
    let w = dx > 2 ? 0.85 : 0.55;
    let col = dx > 4 ? PAL.cobaltBlack : PAL.cobaltDeep;
    setPen("rotring", col, w);
    brush.line(bx + dx, by - bh / 2 + 6, bx + dx * 1.15, by + bh / 2);
  }
  // Mushroom cap & rope wear grooves
  setPen("rotring", PAL.cobaltBlack, 1.1);
  brush.arc(bx, by - bh / 2 + 6, bw * 0.62, 180, 360);
  brush.line(bx - bw * 0.62, by - bh / 2 + 6, bx + bw * 0.62, by - bh / 2 + 6);
  brush.line(bx - bw * 0.52, by, bx + bw * 0.52, by + 2);
  brush.line(bx - bw * 0.65, by + bh / 2, bx + bw * 0.65, by + bh / 2);
}

// ============================================================================
// 8. OVERHANGING URBAN WEEPING WILLOW BRANCHES
// ============================================================================
function drawOverhangingWillow() {
  // Right-side weeping willow canopy drooping over the lock-house & bridge (X: 770 to 1035, Y: 185 to 495)
  const rightBranches = [
    [[975, 290], [910, 250], [845, 240], [795, 255]],
    [[995, 330], [925, 285], [860, 280], [805, 305]],
    [[1015, 375], [955, 335], [895, 325], [840, 345]],
    [[940, 265], [880, 215], [820, 205], [770, 225]]
  ];

  for (let bPts of rightBranches) {
    // Draw gnarled main bough
    setPen("rotring", PAL.cobaltBlack, 1.15);
    brush.spline(bPts, 0.4);
    setPen("rotring", PAL.cobaltDeep, 0.8);
    brush.spline(bPts.map(p => [p[0], p[1] + 2.5]), 0.4);

    // Hang slender weeping fronds with lanceolate willow leaves along each bough
    for (let t = 0.15; t <= 0.98; t += 0.085) {
      let idx = Math.min(bPts.length - 2, Math.floor(t * (bPts.length - 1)));
      let lt = (t * (bPts.length - 1)) - idx;
      let sx = lerp(bPts[idx][0], bPts[idx + 1][0], lt);
      let sy = lerp(bPts[idx][1], bPts[idx + 1][1], lt);
      let frondLen = random(65, 135);
      drawWillowFrond(sx, sy, frondLen, -8);
    }
  }

  // Left-side overhanging willow & urban plane branches (X: 165 to 385, Y: 215 to 465)
  const leftBranches = [
    [[215, 295], [270, 255], [330, 250], [375, 270]],
    [[185, 355], [245, 310], [305, 305], [355, 325]],
    [[245, 245], [295, 215], [350, 215], [390, 235]]
  ];

  for (let bPts of leftBranches) {
    setPen("rotring", PAL.cobaltBlack, 1.1);
    brush.spline(bPts, 0.4);
    for (let t = 0.15; t <= 0.98; t += 0.095) {
      let idx = Math.min(bPts.length - 2, Math.floor(t * (bPts.length - 1)));
      let lt = (t * (bPts.length - 1)) - idx;
      let sx = lerp(bPts[idx][0], bPts[idx + 1][0], lt);
      let sy = lerp(bPts[idx][1], bPts[idx + 1][1], lt);
      let frondLen = random(55, 118);
      drawWillowFrond(sx, sy, frondLen, 6);
    }
  }
}

function drawWillowFrond(sx, sy, len, swayX) {
  if (!inScene(sx, sy, -8)) return;
  let midX = sx + swayX * 0.5 + random(-4, 4);
  let midY = sy + len * 0.5;
  let endX = sx + swayX + random(-6, 6);
  let endY = sy + len;

  setPen("needle", PAL.cobaltDeep, 0.5);
  brush.spline([[sx, sy], [midX, midY], [endX, endY]], 0.35);

  // Narrow lanceolate willow leaves alternating down the drooping stem
  let numLeaves = Math.floor(len / 8.5);
  for (let i = 1; i <= numLeaves; i++) {
    let f = i / numLeaves;
    let lx = lerp(sx, endX, f) + Math.sin(f * Math.PI) * (swayX * 0.25);
    let ly = lerp(sy, endY, f);
    if (!inScene(lx, ly, -10)) continue;

    let side = (i % 2 === 0) ? 1 : -1;
    let leafLen = (1 - Math.abs(f - 0.45)) * 13 + 5;
    let leafAng = (90 + side * 28 + random(-6, 6)) * (Math.PI / 180);
    let tipX = lx + Math.cos(leafAng) * leafLen;
    let tipY = ly + Math.sin(leafAng) * leafLen;

    let col = f < 0.5 ? PAL.cobaltBlack : PAL.cobaltRich;
    setPen("engraver", col, 0.6);
    brush.spline([
      [lx, ly],
      [(lx + tipX) * 0.5 + side * 1.8, (ly + tipY) * 0.5 - 1],
      [tipX, tipY]
    ], 0.4);
    brush.spline([
      [lx, ly],
      [(lx + tipX) * 0.5 - side * 1.2, (ly + tipY) * 0.5 + 1],
      [tipX, tipY]
    ], 0.4);
  }
}

// ============================================================================
// 9. TWO WHEELING PIGEONS IN HYPERREAL ORNITHOLOGICAL DETAIL (COLUMBA LIVIA)
// ============================================================================
function drawWheelingPigeons() {
  // Left Pigeon: Banking upward & right toward its partner (X: 465, Y: 292)
  drawHyperrealPigeon({
    cx: 468,
    cy: 292,
    scale: 1.08,
    dir: 1, // Facing right
    bankAngle: -16,
    upperWingPose: true
  });

  // Right Pigeon: Wheeling gracefully leftward & slightly higher (X: 705, Y: 262)
  drawHyperrealPigeon({
    cx: 706,
    cy: 262,
    scale: 1.02,
    dir: -1, // Facing left
    bankAngle: 14,
    upperWingPose: false
  });
}

function drawHyperrealPigeon(cfg) {
  const { cx, cy, scale: sc, dir, bankAngle } = cfg;
  const rad = bankAngle * (Math.PI / 180);

  // Coordinate transform helper for pigeon anatomy
  function pt(lx, ly) {
    let x = lx * dir * sc;
    let y = ly * sc;
    let rx = x * Math.cos(rad) - y * Math.sin(rad);
    let ry = x * Math.sin(rad) + y * Math.cos(rad);
    return [cx + rx, cy + ry];
  }

  // 1. Soft watercolor glaze aura around wings
  brush.noStroke();
  brush.fill(PAL.glazeMist, 95);
  brush.fillBleed(0.35, "out");
  let auraC = pt(0, -15);
  brush.circle(auraC[0], auraC[1], 72 * sc, 0.2);
  brush.noFill();

  // 2. FAR WING (Swept upward behind the body)
  drawPigeonWing(pt, dir, sc, true);

  // 3. FANNED TAIL FEATHERS (12 Rectrices with dark cobalt subterminal bar & pale tips)
  const numTail = 12;
  for (let i = 0; i < numTail; i++) {
    let t = (i / (numTail - 1)) - 0.5; // -0.5 to 0.5
    let baseP = pt(-28, 6 + t * 8);
    let len = 58 - Math.abs(t) * 14;
    let ang = (166 + t * 44) * (Math.PI / 180);
    let tipP = pt(-28 + Math.cos(ang) * len, 6 + Math.sin(ang) * len);
    let vaneW = 5.5;
    let perpX = -Math.sin(ang) * vaneW;
    let perpY = Math.cos(ang) * vaneW;
    let side1 = pt(-28 + Math.cos(ang) * len * 0.88 + perpX, 6 + Math.sin(ang) * len * 0.88 + perpY);
    let side2 = pt(-28 + Math.cos(ang) * len * 0.88 - perpX, 6 + Math.sin(ang) * len * 0.88 - perpY);

    // Cream wash for feather vane
    brush.noStroke();
    brush.wash(PAL.cream, 240);
    brush.beginShape(0.2);
    brush.vertex(baseP[0], baseP[1]);
    brush.vertex(side1[0], side1[1]);
    brush.vertex(tipP[0], tipP[1]);
    brush.vertex(side2[0], side2[1]);
    brush.endShape(true);
    brush.noWash();

    // Feather barbs & dark cobalt subterminal band (at 70% to 92% of tail length)
    for (let f = 0.15; f <= 0.96; f += 0.055) {
      let fx = -28 + Math.cos(ang) * (len * f);
      let fy = 6 + Math.sin(ang) * (len * f);
      let fw = vaneW * Math.sin(f * Math.PI * 0.85);
      let pA = pt(fx, fy);
      let pB1 = pt(fx - Math.cos(ang) * 3 + perpX * (fw / vaneW), fy - Math.sin(ang) * 3 + perpY * (fw / vaneW));
      let pB2 = pt(fx - Math.cos(ang) * 3 - perpX * (fw / vaneW), fy - Math.sin(ang) * 3 - perpY * (fw / vaneW));

      // Subterminal dark band characteristic of Columba livia
      let isBand = (f >= 0.68 && f <= 0.90);
      let col = isBand ? PAL.cobaltBlack : (f < 0.4 ? PAL.cobaltMid : PAL.cobaltLight);
      let w = isBand ? 0.78 : 0.42;
      setPen("needle", col, w);
      brush.line(pA[0], pA[1], pB1[0], pB1[1]);
      brush.line(pA[0], pA[1], pB2[0], pB2[1]);
    }

    // Crisp feather shaft (rachis) & outline
    setPen("engraver", PAL.cobaltDeep, 0.58);
    brush.line(baseP[0], baseP[1], tipP[0], tipP[1]);
    setPen("needle", PAL.cobaltRich, 0.48);
    brush.spline([baseP, side1, tipP, side2], 0.25);
  }

  // 4. TORSO, BREAST, HEAD & IRIDESCENT NECK PLUMAGE
  const bodyContour = [
    pt(-32, 4),   // Rump / tail base
    pt(-12, -8),  // Back
    pt(14, -12),  // Nape
    pt(28, -20),  // Crown
    pt(38, -16),  // Forehead
    pt(42, -11),  // Beak base
    pt(36, -6),   // Throat
    pt(26, 8),    // Crop / breast front
    pt(6, 18),    // Breast keel
    pt(-16, 15),  // Belly / vent
    pt(-32, 4)
  ];

  // Opaque cream wash for body
  brush.noStroke();
  brush.wash(PAL.cream, 245);
  brush.beginShape(0.35);
  for (let p of bodyContour) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Anatomical contour feather hatching on breast, belly, and head
  for (let row = 0; row < 16; row++) {
    let t = row / 15;
    let bx = lerp(-26, 26, t);
    let byTop = lerp(0, -10, t);
    let byBot = lerp(14, 8, Math.sin(t * Math.PI));
    for (let s = 0.1; s <= 0.95; s += 0.12) {
      let py = lerp(byTop, byBot, s);
      let p1 = pt(bx, py);
      let p2 = pt(bx - 5.5, py + 1.8);
      // Darker shading along lower breast keel and crown
      let isDark = (s > 0.65 || t > 0.72);
      setPen("needle", isDark ? PAL.cobaltDeep : PAL.cobaltLight, isDark ? 0.58 : 0.4);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Iridescent metallic neck gorget (dense shimmering scale-hatching in cobalt black & rich blue)
  for (let nx = 12; nx <= 28; nx += 2.2) {
    for (let ny = -10; ny <= 5; ny += 2.0) {
      let np1 = pt(nx, ny);
      let np2 = pt(nx - 3.2, ny + 1.2);
      let col = ((Math.floor(nx + ny) % 2 === 0)) ? PAL.cobaltBlack : PAL.cobaltRich;
      setPen("rotring", col, 0.68);
      brush.line(np1[0], np1[1], np2[0], np2[1]);
    }
  }

  // Crisp body outline
  setPen("rotring", PAL.cobaltBlack, 0.82);
  brush.spline(bodyContour, 0.35);

  // Beak, white cere & eye with catchlight
  let beakBase1 = pt(41, -13);
  let beakBase2 = pt(39, -8);
  let beakTip = pt(50, -10);
  setPen("rotring", PAL.cobaltBlack, 0.85);
  brush.line(beakBase1[0], beakBase1[1], beakTip[0], beakTip[1]);
  brush.line(beakBase2[0], beakBase2[1], beakTip[0], beakTip[1]);
  // White fleshy cere at beak base
  let cereP = pt(41, -12);
  brush.noStroke();
  brush.wash(PAL.cream, 255);
  brush.circle(cereP[0], cereP[1], 2.2 * sc, 0.05);
  brush.noWash();
  setPen("needle", PAL.cobaltDeep, 0.5);
  brush.circle(cereP[0], cereP[1], 2.2 * sc, 0.05);

  // Eye ring & dark pupil
  let eyeP = pt(34, -14);
  setPen("rotring", PAL.cobaltBlack, 0.95);
  brush.circle(eyeP[0], eyeP[1], 2.4 * sc, 0.02);
  setPen("rotring", PAL.cobaltBlack, 1.3);
  brush.line(eyeP[0], eyeP[1], eyeP[0] + 0.5, eyeP[1]);

  // Tucked feet under tail base
  let foot1 = pt(-18, 15);
  let foot2 = pt(-25, 17);
  setPen("rotring", PAL.cobaltBlack, 0.75);
  brush.line(foot1[0], foot1[1], foot2[0], foot2[1]);

  // 5. NEAR WING (Sweeping upward & back in hyperreal anatomical feather layering)
  drawPigeonWing(pt, dir, sc, false);
}

function drawPigeonWing(pt, dir, sc, isFarWing) {
  let ox = isFarWing ? 8 : 2;
  let oy = isFarWing ? -10 : -4;
  let wingScale = isFarWing ? 0.82 : 1.05;
  let angleOffset = isFarWing ? -22 : 0;

  // 10 Primary Flight Feathers (Remiges) + 8 Secondary Feathers
  const totalFeathers = 17;
  // Draw from innermost secondary (16) to outermost primary (0) so outer primaries overlap cleanly
  for (let i = totalFeathers - 1; i >= 0; i--) {
    let isPrimary = i < 10;
    let fNorm = i / (totalFeathers - 1); // 0 = leading primary tip, 1 = inner secondary

    // Leading edge wrist joint curve
    let rootX = ox + lerp(16, -20, fNorm) * wingScale;
    let rootY = oy + lerp(-22, -6, fNorm) * wingScale;

    // Feather length & sweep angle
    let featherLen = (isPrimary ? lerp(92, 68, i / 9) : lerp(65, 42, (i - 10) / 7)) * wingScale;
    let sweepDeg = lerp(-68, -142, Math.pow(fNorm, 0.88)) + angleOffset;
    let sweepRad = sweepDeg * (Math.PI / 180);

    let midX = rootX + Math.cos(sweepRad + 0.08) * featherLen * 0.52;
    let midY = rootY + Math.sin(sweepRad + 0.08) * featherLen * 0.52;
    let tipX = rootX + Math.cos(sweepRad) * featherLen;
    let tipY = rootY + Math.sin(sweepRad) * featherLen;

    let vaneW = (isPrimary ? 5.2 : 6.4) * wingScale;
    let perpX = -Math.sin(sweepRad) * vaneW;
    let perpY = Math.cos(sweepRad) * vaneW;

    let pRoot = pt(rootX, rootY);
    let pMid = pt(midX, midY);
    let pTip = pt(tipX, tipY);
    let pLead = pt(midX + perpX * 0.45, midY + perpY * 0.45);
    let pTrail = pt(midX - perpX * 1.15, midY - perpY * 1.15);
    let pTipTrail = pt(tipX - perpX * 0.65, tipY - perpY * 0.65);

    // Cream wash inside each individual feather vane
    brush.noStroke();
    brush.wash(PAL.cream, 242);
    brush.beginShape(0.25);
    brush.vertex(pRoot[0], pRoot[1]);
    brush.vertex(pLead[0], pLead[1]);
    brush.vertex(pTip[0], pTip[1]);
    brush.vertex(pTipTrail[0], pTipTrail[1]);
    brush.vertex(pTrail[0], pTrail[1]);
    brush.endShape(true);
    brush.noWash();

    // Fine anatomical feather barbs along the rachis shaft
    for (let b = 0.12; b <= 0.96; b += 0.06) {
      let bx = lerp(rootX, tipX, b);
      let by = lerp(rootY, tipY, b);
      let pShaft = pt(bx, by);
      let barbSpread = Math.sin(b * Math.PI * 0.9);
      let pBarbTrail = pt(
        bx - Math.cos(sweepRad) * 4 - perpX * 1.1 * barbSpread,
        by - Math.sin(sweepRad) * 4 - perpY * 1.1 * barbSpread
      );

      // Primary tips and secondary ends are darker cobalt (classic rock dove wing coloration)
      let isDarkTip = (isPrimary && b > 0.55) || (!isPrimary && b > 0.72) || isFarWing;
      let col = isDarkTip ? PAL.cobaltDeep : PAL.cobaltLight;
      let w = isDarkTip ? 0.58 : 0.38;
      setPen("needle", col, w);
      brush.line(pShaft[0], pShaft[1], pBarbTrail[0], pBarbTrail[1]);
    }

    // Crisp feather outline & central rachis shaft
    setPen("engraver", isFarWing ? PAL.cobaltDeep : PAL.cobaltBlack, 0.62);
    brush.spline([pRoot, pMid, pTip], 0.3);
    setPen("needle", PAL.cobaltRich, 0.5);
    brush.spline([pRoot, pLead, pTip, pTipTrail, pTrail], 0.3);
  }

  // Greater & Median Wing Coverts with the Iconic Two Black/Cobalt Wing Bars of Columba livia!
  if (!isFarWing) {
    for (let bar = 0; bar < 2; bar++) {
      let barDist = bar === 0 ? 0.36 : 0.22;
      for (let k = 4; k < 16; k++) {
        let fNorm = k / 16;
        let rx = ox + lerp(14, -18, fNorm) * wingScale;
        let ry = oy + lerp(-20, -6, fNorm) * wingScale;
        let sweepRad = lerp(-75, -140, fNorm) * (Math.PI / 180);
        let cxBar = rx + Math.cos(sweepRad) * (62 * barDist);
        let cyBar = ry + Math.sin(sweepRad) * (62 * barDist);
        let pBar1 = pt(cxBar, cyBar);
        let pBar2 = pt(cxBar + Math.cos(sweepRad) * 7, cyBar + Math.sin(sweepRad) * 7);
        setPen("rotring", PAL.cobaltBlack, 0.95);
        brush.line(pBar1[0], pBar1[1], pBar2[0], pBar2[1]);
      }
    }
  }
}

// ============================================================================
// 10. DECORATIVE SCALLOPED BORDER BAND (TRANSFERWARE FRAME)
// ============================================================================
function drawScallopedBorderBand() {
  const R_IN = 446;
  const R_MID_IN = 462;
  const R_MID_OUT = 524;
  const R_OUT = 554;

  // 1. Clean cream porcelain mask in the border band so interior scene lines terminate crisply
  // Draw 8 alternating transferware border panels between R_MID_IN and R_MID_OUT:
  // Even panels (0, 2, 4, 6): Classic Willow-pattern diamond diaper lattice
  // Odd panels (1, 3, 5, 7): Scroll cartouches with willow fronds & industrial hex-nut rosettes

  // Concentric framing rings
  setPen("rotring", PAL.cobaltDeep, 1.0);
  brush.circle(CX, CY, R_IN, 0.008);
  setPen("rotring", PAL.cobaltRich, 0.75);
  brush.circle(CX, CY, R_IN + 4.5, 0.008);

  setPen("rotring", PAL.cobaltBlack, 1.1);
  brush.circle(CX, CY, R_MID_IN, 0.008);
  brush.circle(CX, CY, R_MID_OUT, 0.008);

  // 2. INNER SCALLOPED LACE FRINGE (48 inward-facing scallops inside R_IN)
  const numInScallops = 48;
  for (let i = 0; i < numInScallops; i++) {
    let a1 = (i / numInScallops) * Math.PI * 2;
    let a2 = ((i + 1) / numInScallops) * Math.PI * 2;
    let am = (a1 + a2) * 0.5;

    let x1 = CX + Math.cos(a1) * R_IN;
    let y1 = CY + Math.sin(a1) * R_IN;
    let x2 = CX + Math.cos(a2) * R_IN;
    let y2 = CY + Math.sin(a2) * R_IN;
    let xm = CX + Math.cos(am) * (R_IN - 14);
    let ym = CY + Math.sin(am) * (R_IN - 14);

    setPen("rotring", PAL.cobaltDeep, 0.78);
    brush.spline([[x1, y1], [xm, ym], [x2, y2]], 0.45);

    // Inner parallel scallop line
    let xm2 = CX + Math.cos(am) * (R_IN - 10);
    let ym2 = CY + Math.sin(am) * (R_IN - 10);
    setPen("needle", PAL.cobaltMid, 0.5);
    brush.spline([[x1, y1], [xm2, ym2], [x2, y2]], 0.45);

    // Pendant transferware pearl dot at cusp of each scallop
    let px = CX + Math.cos(a1) * (R_IN - 18);
    let py = CY + Math.sin(a1) * (R_IN - 18);
    setPen("rotring", PAL.cobaltBlack, 1.05);
    brush.circle(px, py, 2.0, 0.05);
  }

  // Band between R_IN and R_MID_IN: Radial fret/bead ticks
  for (let i = 0; i < 180; i++) {
    let a = (i / 180) * Math.PI * 2;
    let r1 = R_IN + 4.5;
    let r2 = R_MID_IN;
    setPen("needle", PAL.cobaltRich, i % 2 === 0 ? 0.65 : 0.4);
    brush.line(CX + Math.cos(a) * r1, CY + Math.sin(a) * r1, CX + Math.cos(a) * r2, CY + Math.sin(a) * r2);
  }

  // 3. MAIN DIAPER LATTICE & URBAN-BOTANICAL CARTOUCHES (R_MID_IN to R_MID_OUT)
  const numSectors = 8;
  for (let s = 0; s < numSectors; s++) {
    let sa1 = (s / numSectors) * Math.PI * 2;
    let sa2 = ((s + 1) / numSectors) * Math.PI * 2;
    let pad = 0.015;

    // Radial divider scrolling cartouche border
    for (let bAng of [sa1 + pad, sa2 - pad]) {
      setPen("rotring", PAL.cobaltBlack, 0.95);
      brush.line(
        CX + Math.cos(bAng) * R_MID_IN,
        CY + Math.sin(bAng) * R_MID_IN,
        CX + Math.cos(bAng) * R_MID_OUT,
        CY + Math.sin(bAng) * R_MID_OUT
      );
    }

    if (s % 2 === 0) {
      // EVEN SECTOR: Classic Staffordshire Diamond Diaper Trellis
      let stepsA = 18;
      let stepsR = 4;
      for (let i = 0; i < stepsA; i++) {
        let aStart = lerp(sa1 + pad, sa2 - pad, i / stepsA);
        let aEnd = lerp(sa1 + pad, sa2 - pad, Math.min(1, (i + stepsR) / stepsA));
        let rEnd = R_MID_IN + ((aEnd - aStart) / ((sa2 - sa1 - 2 * pad) / stepsA)) * ((R_MID_OUT - R_MID_IN) / stepsR);
        rEnd = Math.min(R_MID_OUT, rEnd);

        // Spiral trellis lines in both directions
        let pts1 = [], pts2 = [];
        for (let k = 0; k <= 6; k++) {
          let f = k / 6;
          let ang1 = lerp(aStart, aEnd, f);
          let rad1 = lerp(R_MID_IN, rEnd, f);
          pts1.push([CX + Math.cos(ang1) * rad1, CY + Math.sin(ang1) * rad1]);

          let aStartRev = lerp(sa2 - pad, sa1 + pad, i / stepsA);
          let aEndRev = lerp(sa2 - pad, sa1 + pad, Math.min(1, (i + stepsR) / stepsA));
          let ang2 = lerp(aStartRev, aEndRev, f);
          pts2.push([CX + Math.cos(ang2) * rad1, CY + Math.sin(ang2) * rad1]);
        }
        setPen("engraver", PAL.cobaltDeep, 0.65);
        brush.spline(pts1, 0.1);
        brush.spline(pts2, 0.1);

        // Tiny cobalt floret dots inside diamond cells
        if (i < stepsA - 1) {
          let cellA = lerp(sa1 + pad, sa2 - pad, (i + 0.5) / stepsA);
          for (let rStep = 0.25; rStep <= 0.75; rStep += 0.25) {
            let cellR = lerp(R_MID_IN, R_MID_OUT, rStep);
            setPen("rotring", PAL.cobaltBlack, 0.9);
            brush.circle(CX + Math.cos(cellA) * cellR, CY + Math.sin(cellA) * cellR, 1.4, 0.05);
          }
        }
      }
    } else {
      // ODD SECTOR: Reserve Cartouche with Engraved Hex-Bolt Rosette & Willow Scrolls
      let midA = (sa1 + sa2) * 0.5;
      let midR = (R_MID_IN + R_MID_OUT) * 0.5;

      // Dark cross-hatched cobalt reserve background at ends of cartouche
      for (let a = sa1 + pad; a <= sa2 - pad; a += 0.008) {
        let distFromMid = Math.abs(a - midA) / ((sa2 - sa1) * 0.5);
        if (distFromMid > 0.62) {
          setPen("rotring", PAL.cobaltDeep, 0.75);
          brush.line(
            CX + Math.cos(a) * R_MID_IN,
            CY + Math.sin(a) * R_MID_IN,
            CX + Math.cos(a) * R_MID_OUT,
            CY + Math.sin(a) * R_MID_OUT
          );
        }
      }

      // Central Hex-Bolt & Willow Rosette at (midA, midR)
      let rx = CX + Math.cos(midA) * midR;
      let ry = CY + Math.sin(midA) * midR;
      drawHeroHexBolt(rx, ry, 11, false);

      // Flanking willow leaf scrolls inside cartouche
      for (let side of [-1, 1]) {
        let scrollPts = [];
        for (let k = 0; k <= 8; k++) {
          let f = k / 8;
          let a = midA + side * (0.04 + f * 0.16);
          let r = midR + Math.sin(f * Math.PI * 1.5) * 16 * side;
          scrollPts.push([CX + Math.cos(a) * r, CY + Math.sin(a) * r]);
        }
        setPen("rotring", PAL.cobaltDeep, 0.8);
        brush.spline(scrollPts, 0.4);

        // Willow leaves along scroll
        for (let k = 1; k < 8; k++) {
          let lp = scrollPts[k];
          let leafA = midA + side * (0.05 + k * 0.02) + (k % 2 === 0 ? 0.6 : -0.6);
          setPen("engraver", PAL.cobaltRich, 0.65);
          brush.line(lp[0], lp[1], lp[0] + Math.cos(leafA) * 11, lp[1] + Math.sin(leafA) * 11);
          brush.line(lp[0], lp[1], lp[0] + Math.cos(leafA + 0.18) * 9, lp[1] + Math.sin(leafA + 0.18) * 9);
        }
      }
    }
  }

  // 4. OUTER SCALLOPED & GADROONED PLATE RIM (R_MID_OUT to R_OUT = 554)
  const numOutScallops = 36;
  for (let i = 0; i < numOutScallops; i++) {
    let a1 = (i / numOutScallops) * Math.PI * 2;
    let a2 = ((i + 1) / numOutScallops) * Math.PI * 2;
    let am = (a1 + a2) * 0.5;

    let x1 = CX + Math.cos(a1) * (R_OUT - 14);
    let y1 = CY + Math.sin(a1) * (R_OUT - 14);
    let x2 = CX + Math.cos(a2) * (R_OUT - 14);
    let y2 = CY + Math.sin(a2) * (R_OUT - 14);
    let xm = CX + Math.cos(am) * R_OUT;
    let ym = CY + Math.sin(am) * R_OUT;

    // Radial fluted shading lines inside each outer scallop lobe
    for (let f = 0.08; f <= 0.92; f += 0.09) {
      let a = lerp(a1, a2, f);
      let lobeProfile = Math.sin(f * Math.PI);
      let rOuter = (R_OUT - 14) + lobeProfile * 14;
      setPen("engraver", f > 0.5 ? PAL.cobaltDeep : PAL.cobaltMid, 0.58);
      brush.line(
        CX + Math.cos(a) * R_MID_OUT,
        CY + Math.sin(a) * R_MID_OUT,
        CX + Math.cos(a) * (rOuter - 2),
        CY + Math.sin(a) * (rOuter - 2)
      );
    }

    // Outer scalloped rim contour (double cobalt line)
    setPen("rotring", PAL.cobaltBlack, 1.15);
    brush.spline([[x1, y1], [xm, ym], [x2, y2]], 0.45);

    let xmIn = CX + Math.cos(am) * (R_OUT - 4.5);
    let ymIn = CY + Math.sin(am) * (R_OUT - 4.5);
    let x1In = CX + Math.cos(a1) * (R_OUT - 18.5);
    let y1In = CY + Math.sin(a1) * (R_OUT - 18.5);
    let x2In = CX + Math.cos(a2) * (R_OUT - 18.5);
    let y2In = CY + Math.sin(a2) * (R_OUT - 18.5);
    setPen("rotring", PAL.cobaltDeep, 0.75);
    brush.spline([[x1In, y1In], [xmIn, ymIn], [x2In, y2In]], 0.45);
  }
}

// ============================================================================
// 11. FINAL TRANSFER-PRINT STIPPLE PASS & GLAZE EDGE UNIFICATION
// ============================================================================
function drawFinalTransferStipplePass() {
  // Authentic copperplate transferware dot-matrix stippling around the scalloped border
  // and in the sky/water transitions to unify the cobalt monochrome surface
  for (let i = 0; i < 420; i++) {
    let ang = random(Math.PI * 2);
    // Concentrate stipple dots near the inner & outer scalloped border edges
    let ringChoice = random();
    let rad;
    if (ringChoice < 0.45) {
      rad = random(420, 455);
    } else if (ringChoice < 0.85) {
      rad = random(535, 572);
    } else {
      rad = random(180, 420);
    }

    let x = CX + Math.cos(ang) * rad;
    let y = CY + Math.sin(ang) * rad;

    let col = rad > 545 ? PAL.glazeSoft : PAL.cobaltMid;
    setPen("rotring", col, random(0.45, 0.85));
    brush.line(x, y, x + 0.8, y + 0.8);
  }

  // Subtle corner spandrel stipple & plate rim framing marks
  setPen("transferDot", PAL.glazeSoft, 0.6);
  for (let i = 0; i < 90; i++) {
    let ang = random(Math.PI * 2);
    let rad = random(548, 578);
    let x = CX + Math.cos(ang) * rad;
    let y = CY + Math.sin(ang) * rad;
    brush.line(x, y, x + random(-6, 6), y + random(-6, 6));
  }
}
